// データストア（API接続版）
// ====================================
const Storage = {
  // 患者データはAPIから取得（キャッシュ用）
  _patientsCache: [],
  _recordsCache: [],

  getPatients: () => Storage._patientsCache,
  setPatients: (data) => { Storage._patientsCache = data; },

  getRecords: () => Storage._recordsCache,
  setRecords: (data) => { Storage._recordsCache = data; },

  getCurrentUser: () => AuthAPI ? AuthAPI.getCurrentUser() : null,
  setCurrentUser: (user) => sessionStorage.setItem('dm_currentUser', JSON.stringify(user)),
  clearCurrentUser: () => {
    if (AuthAPI) return AuthAPI.logout();
    sessionStorage.removeItem('dm_currentUser');
    return Promise.resolve();
  }
};

