function closePrescriptionAuditDisableDialog() {
  const dialog = document.getElementById('prescription-audit-disable-dialog');
  dialog?.classList.add('hidden');
  prescriptionAuditDisableState = null;
}

function openPrescriptionAuditDisableDialog(rowIndex) {
  const row = karteWarningDialogRows[rowIndex];
  if (!row || !row.canDisableAudit) {
    showToast('この警告は警告一覧から無効化できません', 'info');
    return;
  }

  prescriptionAuditDisableState = { row, rowIndex };
  const dialog = ensurePrescriptionAuditDisableDialog();
  const tableBody = dialog.querySelector('.prescription-audit-disable-table tbody');
  const defaultScope = dialog.querySelector('input[name="prescription-audit-disable-scope"][value="both"]');
  const chartScope = dialog.querySelector('input[name="prescription-audit-disable-scope"][value="chart"]');
  const receiptConfigurable = isFacilityWarningReceiptConfigurable(row);
  dialog.querySelectorAll('[data-prescription-audit-disable-scope-option]').forEach(option => {
    const scope = option.dataset.prescriptionAuditDisableScopeOption;
    option.classList.toggle('hidden', !receiptConfigurable && scope !== 'chart');
  });
  if (receiptConfigurable && defaultScope) defaultScope.checked = true;
  if (!receiptConfigurable && chartScope) chartScope.checked = true;

  if (tableBody) {
    tableBody.innerHTML = `
      <tr>
        <td>${escapeHtml(row.itemName)}</td>
        <td>
          <span class="karte-warning-list-kind ${escapeHtml(row.level)} ${escapeHtml(getKarteWarningLevelClass(row))}">
            ${getKarteWarningListIconMarkup(row)}
            ${escapeHtml(row.category)}
          </span>
        </td>
        <td>${escapeHtml(row.message)}</td>
      </tr>
    `;
  }

  dialog.classList.remove('hidden');
  dialog.focus();
  dialog.querySelector('.prescription-audit-disable-submit')?.focus();
}

function buildPrescriptionAuditDisablePayload(row, scope) {
  const receiptConfigurable = isFacilityWarningReceiptConfigurable(row);
  const normalizedScope = receiptConfigurable ? scope : 'chart';
  const chartEnabled = normalizedScope === 'receipt';
  const receiptEnabled = receiptConfigurable ? normalizedScope === 'chart' : true;
  const level = row.level || 'warning';
  return {
    rule_code: row.ruleCode || null,
    rule_type: row.ruleType || 'drug',
    item_code: row.itemCode || row.targetCode || null,
    item_name: row.itemName || row.targetName || '処方監査',
    warning_type: row.warningType || row.category || '処方監査',
    chart_enabled: chartEnabled,
    chart_level: level,
    chart_note: row.message || null,
    receipt_enabled: receiptEnabled,
    receipt_level: level,
    receipt_note: row.message || null
  };
}

