const NUMERIC_KEYPAD_SELECTOR = 'input[data-numeric-pad]';
const numericKeypadState = {
  input: null,
  element: null
};

function normalizeNumericKeypadText(value, allowDecimal) {
  let normalized = String(value || '')
    .replace(/[０-９]/g, ch => String.fromCharCode(ch.charCodeAt(0) - 0xFEE0))
    .replace(/[．。]/g, '.')
    .replace(/[^\d.]/g, '');
  if (!allowDecimal) return normalized.replace(/[^\d]/g, '');
  const parts = normalized.split('.');
  if (parts.length <= 1) return normalized;
  return `${parts.shift()}.${parts.join('')}`;
}

function sanitizeNumericKeypadInput(input) {
  if (!input) return;
  const allowDecimal = input.dataset.numericPad === 'decimal';
  const normalized = normalizeNumericKeypadText(input.value, allowDecimal);
  if (input.value !== normalized) input.value = normalized;
}

function commitNumericKeypadValue(input) {
  if (!input) return;
  const allowDecimal = input.dataset.numericPad === 'decimal';
  let value = normalizeNumericKeypadText(input.value, allowDecimal);
  if (value === '' || value === '.') {
    input.value = value;
    dispatchNumericKeypadInput(input, { commit: true });
    return;
  }
  let numeric = allowDecimal ? Number.parseFloat(value) : Number.parseInt(value, 10);
  if (!Number.isFinite(numeric)) return;
  const min = input.dataset.min !== undefined ? Number(input.dataset.min) : null;
  const max = input.dataset.max !== undefined ? Number(input.dataset.max) : null;
  if (Number.isFinite(min) && numeric < min) numeric = min;
  if (Number.isFinite(max) && numeric > max) numeric = max;
  value = allowDecimal ? String(numeric) : String(Math.floor(numeric));
  if (input.value !== value) {
    input.value = value;
    dispatchNumericKeypadInput(input);
  }
  dispatchNumericKeypadInput(input, { commit: true });
}

function dispatchNumericKeypadInput(input, options = {}) {
  input.dispatchEvent(new Event('input', { bubbles: true }));
  if (options.commit) {
    input.dispatchEvent(new Event('change', { bubbles: true }));
  }
}

function getNumericKeypadElement() {
  if (numericKeypadState.element) return numericKeypadState.element;
  const keypad = document.createElement('div');
  keypad.className = 'numeric-keypad hidden';
  keypad.setAttribute('role', 'group');
  keypad.setAttribute('aria-label', '数値入力');
  keypad.innerHTML = ['7', '8', '9', '4', '5', '6', '1', '2', '3', '0', '.', 'C']
    .map(key => `<button type="button" class="numeric-keypad-key${key === 'C' ? ' is-clear' : ''}" data-key="${key}">${key}</button>`)
    .join('');
  document.body.appendChild(keypad);
  keypad.addEventListener('pointerdown', event => event.preventDefault());
  keypad.addEventListener('click', event => {
    const button = event.target.closest('.numeric-keypad-key');
    if (!button || button.disabled) return;
    applyNumericKeypadKey(button.dataset.key);
  });
  numericKeypadState.element = keypad;
  return keypad;
}

function positionNumericKeypad(input) {
  if (!input) return;
  const keypad = getNumericKeypadElement();
  if (keypad.classList.contains('hidden')) return;
  const rect = input.getBoundingClientRect();
  const width = keypad.offsetWidth || 110;
  const height = keypad.offsetHeight || 126;
  const margin = 6;
  const left = Math.min(Math.max(rect.left, margin), window.innerWidth - width - margin);
  const below = rect.bottom + margin;
  const top = below + height > window.innerHeight - margin
    ? Math.max(margin, rect.top - height - margin)
    : below;
  keypad.style.left = `${left}px`;
  keypad.style.top = `${top}px`;
}

function openNumericKeypad(input) {
  if (!input || input.disabled || input.readOnly) return;
  sanitizeNumericKeypadInput(input);
  numericKeypadState.input = input;
  const keypad = getNumericKeypadElement();
  const allowDecimal = input.dataset.numericPad === 'decimal';
  keypad.querySelector('[data-key="."]')?.toggleAttribute('disabled', !allowDecimal);
  keypad.classList.remove('hidden');
  positionNumericKeypad(input);
}

function closeNumericKeypad(options = {}) {
  const input = numericKeypadState.input;
  numericKeypadState.input = null;
  numericKeypadState.element?.classList.add('hidden');
  if (options.commit !== false) commitNumericKeypadValue(input);
}

function applyNumericKeypadKey(key) {
  const input = numericKeypadState.input;
  if (!input) return;
  const allowDecimal = input.dataset.numericPad === 'decimal';
  let nextValue = input.value || '';
  if (key === 'C') {
    nextValue = '';
  } else if (key === '.') {
    if (!allowDecimal || nextValue.includes('.')) return;
    nextValue = nextValue ? `${nextValue}.` : '0.';
  } else {
    nextValue = `${nextValue}${key}`;
  }
  input.value = normalizeNumericKeypadText(nextValue, allowDecimal);
  input.dataset.numericPadDirty = 'true';
  dispatchNumericKeypadInput(input);
  input.focus({ preventScroll: true });
  positionNumericKeypad(input);
}

function initNumericKeypad() {
  if (document.body.dataset.numericKeypadInitialized === 'true') return;
  document.body.dataset.numericKeypadInitialized = 'true';
  document.addEventListener('focusin', event => {
    const input = event.target?.closest?.(NUMERIC_KEYPAD_SELECTOR);
    if (input) {
      if (numericKeypadState.input && numericKeypadState.input !== input) closeNumericKeypad();
      openNumericKeypad(input);
    } else if (numericKeypadState.element && !numericKeypadState.element.contains(event.target)) {
      closeNumericKeypad();
    }
  });
  document.addEventListener('input', event => {
    if (event.target?.matches?.(NUMERIC_KEYPAD_SELECTOR)) sanitizeNumericKeypadInput(event.target);
  }, true);
  document.addEventListener('pointerdown', event => {
    const keypad = numericKeypadState.element;
    if (!keypad || keypad.classList.contains('hidden')) return;
    if (event.target === numericKeypadState.input || keypad.contains(event.target)) return;
    if (event.target?.closest?.(NUMERIC_KEYPAD_SELECTOR)) return;
    closeNumericKeypad();
  }, true);
  document.addEventListener('keydown', event => {
    if (!numericKeypadState.input) return;
    if (event.key === 'Escape' || event.key === 'Enter') closeNumericKeypad();
  });
  window.addEventListener('resize', () => positionNumericKeypad(numericKeypadState.input));
  window.addEventListener('scroll', () => positionNumericKeypad(numericKeypadState.input), true);
}

// ====================================
// ログイン機能（API接続版）
// ====================================
let loginFacilityContext = null;

function enablePasswordOnlyLogin() {
  loginFacilityContext = {
    facility_code: 'DEMO001',
    facility_name: '西春内科・在宅クリニック',
    certificate_id: null,
    password_only_mode: true,
    development_mode: true
  };
  setLoginFacilityState('ready', loginFacilityContext);
}

function setLoginFacilityState(state, context = null, message = '') {
  const card = document.getElementById('login-facility-context');
  const status = document.getElementById('login-certificate-status');
  const name = document.getElementById('login-facility-name');
  const detail = document.getElementById('login-certificate-detail');
  const submit = document.querySelector('#login-form button[type="submit"]');
  if (!card || !status || !name || !detail || !submit) return;

  card.classList.toggle('is-loading', state === 'loading');
  card.classList.toggle('is-error', state === 'error');
  status.textContent = state === 'ready'
    ? (context?.password_only_mode ? 'ID・パスワードでログインできます' : (context?.development_mode ? '開発用の施設を選択中' : '施設証明書を確認しました'))
    : (state === 'loading' ? '施設情報を確認しています' : '施設情報を確認できません');
  name.textContent = context?.facility_name || '';
  detail.textContent = message || (context?.password_only_mode
    ? `施設コード: ${context.facility_code}（証明書は不要です）`
    : context?.development_mode
    ? `施設コード: ${context.facility_code}`
    : [context?.certificate_label, context?.certificate_serial ? `Serial ${context.certificate_serial}` : '']
        .filter(Boolean).join(' / '));
  submit.disabled = state !== 'ready';
}

async function loadLoginFacilityContext() {
  loginFacilityContext = null;
  setLoginFacilityState('loading');
  try {
    loginFacilityContext = await AuthAPI.getFacilityContext();
    setLoginFacilityState('ready', loginFacilityContext);
    return loginFacilityContext;
  } catch (error) {
    setLoginFacilityState('error', null, error?.message || '施設情報を取得できません。起動状態を確認してください');
    return null;
  }
}

async function initializeAuthentication() {
  const storedUser = Storage.getCurrentUser();
  if (storedUser && AuthAPI.isLoggedIn()) {
    try {
      const user = await AuthAPI.me();
      await loadPatients();
      await showReceptionScreen(user);
      return;
    } catch (error) {
      console.warn('保存済みセッションを利用できません:', error);
      AuthAPI.clearLocalSession();
    }
  }
  showLoginScreen({ loadContext: false });
  enablePasswordOnlyLogin();
}

function initLogin() {
  const loginForm = document.getElementById('login-form');
  const logoutBtn = document.getElementById('btn-logout');

  loginForm.addEventListener('submit', async (e) => {
    e.preventDefault();

    const rawLoginId = document.getElementById('login-id').value.trim();
    const rawPassword = document.getElementById('login-password').value;
    const loginId = rawLoginId;
    const password = rawPassword;
    const submitBtn = loginForm.querySelector('button[type="submit"]');

    if (!loginId || !password) {
      showToast('ログインIDとパスワードを入力してください', 'error');
      return;
    }
    try {
      submitBtn.disabled = true;
      submitBtn.textContent = 'ログイン中...';
      showLoading();

      const user = await AuthAPI.login(loginId, password);

      // 患者データを取得
      await loadPatients();

      hideLoading();
      showToast(`${user.name}さん、ようこそ`, 'success');
      showReceptionScreen(user);
    } catch (error) {
      hideLoading();
      showToast('ログインに失敗しました: ' + error.message, 'error');
    } finally {
      submitBtn.disabled = !loginFacilityContext;
      submitBtn.textContent = 'ログイン';
    }
  });

  logoutBtn.addEventListener('click', async () => {
    if (!(await confirmDiscardKarteChangesIfNeeded())) return;
    if (!(await confirmLogout())) return;
    await Storage.clearCurrentUser();
    showLoginScreen();
  });
}

// 患者データをAPIから取得
function mergePatientsIntoStorage(newPatients) {
  const currentPatients = Storage.getPatients();
  const patientMap = new Map(currentPatients.map(patient => [patient.id, patient]));
  newPatients.forEach(patient => patientMap.set(patient.id, patient));
  Storage.setPatients(Array.from(patientMap.values()));
}

async function loadPatients(query = '', limit = 100, offset = 0) {
  try {
    const result = await PatientAPI.list(query, limit, offset);
    const patients = result.data || [];
    if (query) {
      mergePatientsIntoStorage(patients);
    } else {
      Storage.setPatients(patients);
    }
    updatePatientSelector();
    return patients;
  } catch (error) {
    console.error('患者データ取得エラー:', error);
    if (!query) {
      Storage.setPatients([]);
      updatePatientSelector();
    }
    return [];
  }
}

function showLoginScreen(options = {}) {
  resetSetTreeExpansionState();
  document.getElementById('login-screen').classList.remove('hidden');
  document.getElementById('main-screen').classList.add('hidden');
  document.getElementById('reception-screen').classList.add('hidden');
  document.getElementById('facility-screen')?.classList.add('hidden');
  document.getElementById('login-id').value = '';
  document.getElementById('login-password').value = '';
  if (options.loadContext !== false) loadLoginFacilityContext();
  scheduleAppScreenHistoryUpdate();
}

function showMainScreen(user, options = {}) {
  appScreenHistory?.capture();
  // 履歴の読込は患者選択後に行い、ここでは左側の初期タブだけ戻す。
  showKarteHistoryTab({ reload: false });
  document.getElementById('main-screen').classList.toggle('patient-overview', options.patientOverview === true);
  document.getElementById('login-screen').classList.add('hidden');
  document.getElementById('reception-screen').classList.add('hidden');
  document.getElementById('facility-screen')?.classList.add('hidden');
  document.getElementById('main-screen').classList.remove('hidden');
  document.getElementById('login-user-name').textContent = user?.name || 'ユーザー';
  applyM3FeatureSettingsToUi();

  // 患者セレクター更新
  updatePatientSelector();

  const targetKarteDate = normalizeKarteDateValue(options.karteDate)
    || normalizeKarteDateValue(currentKarteDate)
    || getDisplayedReceptionDateValue()
    || getLocalDateString();
  setKarteDate(targetKarteDate);
  resetOrderZoneForKarte();
  ensureFacilityWarningsLoadedForKarte();
  updateKarteHeaderContext();
}

// ====================================
// 受付一覧画面
// ====================================
async function showReceptionScreen(user, options = {}) {
  if (!options.skipKarteDirtyGuard && !(await confirmDiscardKarteChangesIfNeeded())) return false;
  appScreenHistory?.capture();
  resetSetTreeExpansionState();
  document.getElementById('login-screen').classList.add('hidden');
  document.getElementById('main-screen').classList.add('hidden');
  document.getElementById('facility-screen')?.classList.add('hidden');
  document.getElementById('reception-screen').classList.remove('hidden');
  document.getElementById('reception-user-name').textContent = user?.name || 'ユーザー';
  updateFacilityDisplayLabels(getCurrentUserFacilitySnapshot());
  applyM3FeatureSettingsToUi();

  const receptionDateInput = document.getElementById('reception-date');
  if (receptionDateInput) {
    const receptionDate = normalizeKarteDateValue(options.date)
      || normalizeKarteDateValue(receptionDateInput.value)
      || getLocalDateString();
    receptionDateInput.value = receptionDate;
    updateDateDisplay(parseLocalDate(receptionDate));
  }

  scheduleAppScreenHistoryUpdate();
  // 受付一覧を更新（APIから取得）
  await loadReceptions();
  return true;
}

