const m3CommentAddTemplates = m3CommentAddListRawText
  .trim()
  .split(/\r?\n/)
  .map(normalizeCommentMasterTemplate)
  .filter(Boolean);
const m3CommentAddTemplateOrder = new Map(
  m3CommentAddTemplates.map((template, index) => [template, index])
);

function buildM3CommentAddRow(template, index) {
  const override = commentMasterOfficialOverrides[template] || {};
  return {
    code: override.code || `0998${String(index + 1).padStart(5, '0')}`,
    template,
    start: override.start || '0001-01-01',
    end: override.end || '9999-12-31',
    typeLabel: '',
    targetName: '',
    targetCategory: '',
    searchText: template,
    payload: {
      source: 'm3_comment_add_list',
      m3Order: index
    }
  };
}

function normalizeOfficialReceiptCommentRow(item, index) {
  const template = normalizeCommentMasterTemplate(item.template || item.receipt_text || item.name);
  if (!template) return null;

  const code = String(item.code || item.receipt_code || `ORC_${String(index + 1).padStart(5, '0')}`).trim();
  const sourceSheet = item.sourceSheet || item.source_sheet || item.sourceTable || item.source_table || '摘要記載';
  const targetName = item.targetName || item.target_name || '';
  const targetCategory = item.targetCategory || item.target_category || '';
  const tableKind = item.tableKind || item.table_kind || '';
  const typeLabel = [
    sourceSheet,
    item.paperOnly || item.paper_only ? '紙レセのみ' : ''
  ].filter(Boolean).join('・');

  return {
    code,
    template,
    start: '2026-06-01',
    end: '9999-12-31',
    typeLabel,
    targetName,
    targetCategory,
    searchText: [
      code,
      template,
      targetName,
      targetCategory,
      tableKind,
      sourceSheet
    ].filter(Boolean).join(' '),
    payload: {
      source: 'official_receipt_comment_requirements',
      sourceSheet,
      targetName,
      targetCategory,
      tableKind,
      paperOnly: item.paperOnly || item.paper_only || false,
      applies20260601: item.applies20260601 || item.applies_2026_06_01 || false
    }
  };
}

function getOfficialReceiptCommentRows() {
  return (window.OFFICIAL_RECEIPT_COMMENT_REQUIREMENTS?.items || [])
    .map(normalizeOfficialReceiptCommentRow)
    .filter(Boolean);
}

function mergeCommentMasterRows(rows) {
  const merged = [];
  const byCode = new Map();
  const byTemplate = new Map();

  rows.forEach(row => {
    const templateKey = normalizeCommentMasterTemplate(row.template);
    if (!templateKey) return;
    const codeKey = row.code ? String(row.code).trim() : '';
    const existing = (codeKey && byCode.get(codeKey)) || byTemplate.get(templateKey);

    if (existing) {
      if (/^0999/.test(existing.code || '') && codeKey && !/^0999/.test(codeKey)) {
        existing.code = codeKey;
        byCode.set(codeKey, existing);
      }
      existing.searchText = [existing.searchText, row.searchText].filter(Boolean).join(' ');
      if (!existing.typeLabel && row.typeLabel) existing.typeLabel = row.typeLabel;
      existing.payload = { ...(existing.payload || {}), ...(row.payload || {}) };
      return;
    }

    const normalized = {
      ...row,
      template: templateKey,
      searchText: row.searchText || [row.code, templateKey, row.typeLabel].filter(Boolean).join(' ')
    };
    merged.push(normalized);
    if (codeKey) byCode.set(codeKey, normalized);
    byTemplate.set(templateKey, normalized);
  });

  return merged;
}

