const facilityCommentMasterRows = (() => {
  let pendingTypeLabel = '';
  const rows = facilityCommentMasterRawText
    .trim()
    .split(/\r?\n/)
    .map(line => line.trim())
    .filter(Boolean)
    .reduce((acc, line) => {
      if (line === '選択式') {
        pendingTypeLabel = line;
        return acc;
      }
      const override = commentMasterOfficialOverrides[line] || {};
      acc.push({
        code: override.code || `0999${String(acc.length + 1).padStart(5, '0')}`,
        template: line,
        start: override.start || '0001-01-01',
        end: override.end || '9999-12-31',
        typeLabel: pendingTypeLabel
      });
      pendingTypeLabel = '';
      return acc;
    }, []);

  Object.entries(commentMasterOfficialOverrides).forEach(([template, override]) => {
    if (!rows.some(row => row.template === template)) {
      rows.push({ code: override.code, template, start: override.start, end: override.end, typeLabel: '' });
    }
  });

  rows.push(...m3CommentAddTemplates.map(buildM3CommentAddRow));
  rows.push(...getOfficialReceiptCommentRows());

  return mergeCommentMasterRows(rows);
})();

const LONG_TERM_LISTED_COMMENT_CODES = new Set([
  '820101320',
  '820101321',
  '820101322',
  '820101323',
  '820101324',
  '820101325'
]);

const LONG_TERM_LISTED_KEYWORDS = [
  '長期収載',
  '選定療養',
  '後発医薬品',
  '後発変更不可',
  '患者希望',
  '医療上必要',
  '効能・効果に差異',
  '治療効果に差異',
  '剤形上',
  '在庫状況',
  'ガイドライン',
  '適応症不一致'
];

function normalizePrescriptionFlagText(value) {
  return String(value || '').replace(/\s+/g, '').toLowerCase();
}

function readOptionalBooleanFlag(source, keys) {
  for (const key of keys) {
    if (!source || source[key] === undefined || source[key] === null || source[key] === '') continue;
    const value = source[key];
    if (typeof value === 'boolean') return value;
    if (typeof value === 'number') return value !== 0;
    const normalized = normalizePrescriptionFlagText(value);
    if (['1', 'true', 'yes', 'on', 'あり', '有', '対象', '可'].includes(normalized)) return true;
    if (['0', 'false', 'no', 'off', 'なし', '無', '非対象', '不可'].includes(normalized)) return false;
  }
  return null;
}

function getProcedureCommentSearchText(comment) {
  if (!comment) return '';
  return [
    comment.code,
    comment.name,
    comment.template,
    comment.freeText,
    comment.free_text,
    comment.prescriptionRemarkText,
    comment.prescription_remark_text,
    comment.typeLabel,
    comment.targetName,
    comment.targetCategory
  ].filter(Boolean).join(' ');
}

function isLongTermListedPrescriptionComment(comment) {
  const code = String(comment?.code || '').trim();
  if (LONG_TERM_LISTED_COMMENT_CODES.has(code)) return true;
  const text = getProcedureCommentSearchText(comment);
  return LONG_TERM_LISTED_KEYWORDS.some(keyword => text.includes(keyword));
}

function findLongTermListedCommentOptions({ patientChoice = false } = {}) {
  const rows = facilityCommentMasterRows
    .map((row, index) => ({ ...row, index }))
    .filter(row => {
      const code = String(row.code || '').trim();
      const text = [row.template, row.searchText, row.targetName, row.targetCategory].filter(Boolean).join(' ');
      const longTerm = LONG_TERM_LISTED_COMMENT_CODES.has(code)
        || LONG_TERM_LISTED_KEYWORDS.some(keyword => text.includes(keyword));
      if (!longTerm) return false;
      if (patientChoice) return text.includes('患者希望') || text.includes('選定療養');
      return !text.includes('患者希望');
    });

  if (patientChoice && !rows.length) {
    return [{
      index: -1,
      code: '820101320',
      template: '患者希望（長期収載品：選定療養）',
      typeLabel: '長期収載',
      start: '2026-06-01',
      end: '9999-12-31'
    }];
  }
  return rows;
}

function prescriptionHasLongTermListedComment(prescription) {
  return getPrescriptionComments(prescription).some(isLongTermListedPrescriptionComment);
}

function getPrescriptionRequirementState(prescription) {
  const comments = getPrescriptionComments(prescription);
  const combinedText = [
    prescription?.drug_name,
    prescription?.name,
    prescription?.generic_name,
    prescription?.genericChangeReason,
    prescription?.generic_change_reason,
    prescription?.instructions,
    prescription?.note,
    prescription?.comment,
    ...comments.map(getProcedureCommentSearchText)
  ].filter(Boolean).join(' ');

  const explicitLongTerm = readOptionalBooleanFlag(prescription, [
    'long_term_listed',
    'longTermListed',
    'long_term_listed_drug',
    'is_long_term_listed'
  ]);
  const explicitPatientChoice = readOptionalBooleanFlag(prescription, [
    'long_term_patient_choice',
    'longTermPatientChoice',
    'patient_choice_long_term',
    'patientChoiceLongTerm'
  ]);
  const explicitCommentRequired = readOptionalBooleanFlag(prescription, [
    'requires_comment',
    'requiresComment',
    'comment_required',
    'commentRequired',
    'selectable_comment_required',
    'selectableCommentRequired'
  ]);
  const explicitGenericChangeAllowed = readOptionalBooleanFlag(prescription, [
    'generic_change_allowed',
    'genericChangeAllowed'
  ]);

  const hasLongTermComment = comments.some(isLongTermListedPrescriptionComment);
  const patientChoice = explicitPatientChoice === true
    || combinedText.includes('患者希望')
    || combinedText.includes('選定療養');
  const longTermListed = explicitLongTerm === true
    || hasLongTermComment
    || explicitGenericChangeAllowed === false
    || LONG_TERM_LISTED_KEYWORDS.some(keyword => combinedText.includes(keyword));
  const requiresComment = explicitCommentRequired === true
    || (longTermListed && !hasLongTermComment);
  let genericChangeAllowed = explicitGenericChangeAllowed;
  if (genericChangeAllowed === null) {
    genericChangeAllowed = longTermListed && !patientChoice ? false : true;
  }

  return {
    longTermListed,
    longTermPatientChoice: patientChoice,
    hasLongTermListedComment: hasLongTermComment,
    requiresComment,
    genericChangeAllowed,
    genericChangeReason: prescription?.generic_change_reason || prescription?.genericChangeReason || ''
  };
}

function getPrescriptionRequirementNotices(prescription) {
  const state = getPrescriptionRequirementState(prescription);
  const notices = [];
  if (state.longTermListed) notices.push(['長期収載', state.hasLongTermListedComment
    ? '長期収載品です。理由コメントまたは患者希望コメントが登録されています。'
    : '長期収載品です。理由コメントまたは患者希望コメントを確認してください。']);
  if (state.longTermPatientChoice) notices.push(['患者希望', '患者希望（選定療養）の設定があります。']);
  if (state.requiresComment) notices.push(['コメント要', '処方コメントの確認が必要です。', 'warning']);
  if (prescription?.is_temporary || prescription?.isTemporary || prescription?.temporary) notices.push(['臨時', '臨時処方の設定があります。']);
  if (prescription?.refill_allowed || prescription?.refillAllowed || prescription?.is_refill || prescription?.isRefill) notices.push(['リフィル', 'リフィル処方の設定があります。']);
  return notices.map(([category, message, level = 'info']) => ({
    itemName: prescription?.drug_name || prescription?.name || '処方薬',
    item_code: prescription?.drug_code || prescription?.code || null,
    rule_type: 'prescription_requirement',
    category,
    message,
    level,
    icon: 'warning'
  }));
}

function markPrescriptionLongTermListed(prescription, { patientChoice = false, reason = '' } = {}) {
  if (!prescription) return;
  prescription.long_term_listed = true;
  prescription.longTermListed = true;
  prescription.requires_comment = true;
  prescription.requiresComment = true;
  prescription.comment_required = true;
  prescription.selectable_comment_required = true;
  if (patientChoice) {
    prescription.long_term_patient_choice = true;
    prescription.longTermPatientChoice = true;
  } else {
    prescription.generic_change_allowed = false;
    prescription.genericChangeAllowed = false;
  }
  if (reason) {
    prescription.generic_change_reason = reason;
    prescription.genericChangeReason = reason;
  }
}

