let facilityWarnings = [];
let facilityWarningsFacilityId = null;
let facilityWarningsLoaded = false;
let facilityWarningsLoadPromise = null;
let facilityWarningsLoadError = null;

const INITIAL_DIAGNOSIS_REMAINS_WARNING = {
  ruleCode: 'WARN_INITIAL_DIAGNOSIS_REMAINS',
  itemCode: '111000110',
  itemName: '初診料',
  warningType: '傷病名残存チェック',
  message: '傷病名が残っています。'
};

function createInitialDiagnosisRemainsWarningSetting() {
  return {
    rule_code: INITIAL_DIAGNOSIS_REMAINS_WARNING.ruleCode,
    rule_type: 'calculation',
    item_code: INITIAL_DIAGNOSIS_REMAINS_WARNING.itemCode,
    item_name: INITIAL_DIAGNOSIS_REMAINS_WARNING.itemName,
    warning_type: INITIAL_DIAGNOSIS_REMAINS_WARNING.warningType,
    chart_enabled: true,
    chart_level: 'warning',
    chart_note: INITIAL_DIAGNOSIS_REMAINS_WARNING.message,
    receipt_enabled: true,
    receipt_level: 'warning',
    receipt_note: INITIAL_DIAGNOSIS_REMAINS_WARNING.message,
    is_active: true
  };
}

function normalizeFacilityWarningRows(value) {
  if (Array.isArray(value)) return value;
  return value?.items || value?.data || value?.warnings || [];
}

function getCurrentFacilityIdForWarnings() {
  const user = Storage.getCurrentUser();
  return currentPatient?.facility_id || currentReception?.facility_id || user?.facility_id || null;
}

function isFacilityWarningsLoadedFor(facilityId = getCurrentFacilityIdForWarnings()) {
  return facilityWarningsLoaded && String(facilityWarningsFacilityId || '') === String(facilityId || '');
}

function findFacilityWarningSetting(ruleCode) {
  return (facilityWarnings || []).find(warning =>
    String(warning?.rule_code || '') === String(ruleCode || '')
    && warning?.is_active !== false
  ) || null;
}

function refreshProcedureWarningIndicators() {
  if (!isKarteScreenVisible() || !Array.isArray(selectedActions) || selectedActions.length === 0) return;
  renderSelectedActionsInProcedure();
}

function ensureFacilityWarningsLoadedForKarte(facilityId = getCurrentFacilityIdForWarnings()) {
  const normalizedFacilityId = String(facilityId || '');
  if (!normalizedFacilityId) {
    facilityWarnings = [];
    facilityWarningsFacilityId = '';
    facilityWarningsLoaded = true;
    facilityWarningsLoadError = '施設情報が取得できません';
    return Promise.resolve(facilityWarnings);
  }

  if (isFacilityWarningsLoadedFor(normalizedFacilityId)) {
    return Promise.resolve(facilityWarnings);
  }

  if (facilityWarningsLoadPromise && String(facilityWarningsFacilityId || '') === normalizedFacilityId) {
    return facilityWarningsLoadPromise;
  }

  facilityWarningsFacilityId = normalizedFacilityId;
  facilityWarningsLoaded = false;
  facilityWarningsLoadError = null;

  if (typeof FacilityWarningAPI === 'undefined' || !FacilityWarningAPI?.getWarnings) {
    facilityWarnings = [];
    facilityWarningsLoaded = true;
    facilityWarningsLoadError = '施設警告設定APIが利用できません';
    return Promise.resolve(facilityWarnings);
  }

  facilityWarningsLoadPromise = FacilityWarningAPI.getWarnings(normalizedFacilityId)
    .then(response => {
      if (String(facilityWarningsFacilityId || '') !== normalizedFacilityId) return facilityWarnings;
      facilityWarnings = normalizeFacilityWarningRows(response);
      facilityWarningsLoaded = true;
      facilityWarningsLoadError = null;
      refreshProcedureWarningIndicators();
      return facilityWarnings;
    })
    .catch(error => {
      console.error('施設警告設定取得エラー:', error);
      if (String(facilityWarningsFacilityId || '') === normalizedFacilityId) {
        facilityWarnings = [];
        facilityWarningsLoaded = true;
        facilityWarningsLoadError = error?.message || '施設警告設定の取得に失敗しました';
        refreshProcedureWarningIndicators();
      }
      return facilityWarnings;
    })
    .finally(() => {
      if (String(facilityWarningsFacilityId || '') === normalizedFacilityId) {
        facilityWarningsLoadPromise = null;
      }
    });

  return facilityWarningsLoadPromise;
}

function getFacilityWarningsLoadBlockMessage() {
  if (!facilityWarningsLoadError) return '';
  return `${facilityWarningsLoadError}。保存前チェックを実行できないため、保存・会計完了を中止しました。`;
}

function getChartWarningSetting(ruleCode) {
  if (!isFacilityWarningsLoadedFor()) {
    ensureFacilityWarningsLoadedForKarte();
    return null;
  }
  const setting = findFacilityWarningSetting(ruleCode);
  if (!setting || setting.chart_enabled === false) return null;
  return setting;
}

function isInitialVisitFeeAction(action = {}) {
  const code = String(action.code || action.billing_code || action.receipt_code || '').trim();
  const name = String(action.name || action.billing_name || '').trim();
  return code === INITIAL_DIAGNOSIS_REMAINS_WARNING.itemCode
    || code === 'A000'
    || name === '初診料'
    || /^初診料[（(]/.test(name);
}

function hasPreviousVisitBeforeCurrentDate() {
  const visitDate = getCurrentKarteDateValue();
  const previousDate = normalizeKarteDateValue(
    currentReception?.previous_visit_date
    || currentReception?.last_visit_date
    || currentReception?.last_reception_date
  );
  return Boolean(previousDate && previousDate < visitDate);
}

function isDiagnosisContinuingOnVisitDate(diagnosis, visitDate) {
  const normalized = normalizeDiagnosisItem(diagnosis);
  const outcome = String(normalized.outcome || '').trim().toLowerCase();
  const endedOutcomes = new Set([
    'cured',
    'discontinued',
    'improved',
    'died',
    'transferred',
    '治癒',
    '中止',
    '軽快',
    '死亡',
    '移行'
  ]);
  if (endedOutcomes.has(outcome)) return false;

  const endDate = normalizeKarteDateValue(normalized.end_date);
  return !(endDate && endDate <= visitDate);
}

function getCarriedOverDiagnosesForInitialFeeWarning() {
  if (!currentPatient) return [];

  const visitDate = getCurrentKarteDateValue();
  const source = String(currentPatientDiagnosesPatientId || '') === String(currentPatient.id || '')
    ? currentPatientDiagnoses
    : [];

  return (source || [])
    .map(normalizeDiagnosisItem)
    .filter(diagnosis => {
      if (!isDiagnosisContinuingOnVisitDate(diagnosis, visitDate)) return false;
      const startDate = normalizeKarteDateValue(diagnosis.start_date);
      if (startDate) return startDate < visitDate;
      return hasPreviousVisitBeforeCurrentDate();
    });
}

function buildInitialDiagnosisRemainsWarnings(action) {
  if (!isInitialVisitFeeAction(action)) return [];

  const setting = getChartWarningSetting(INITIAL_DIAGNOSIS_REMAINS_WARNING.ruleCode);
  if (!setting) return [];

  const diagnoses = getCarriedOverDiagnosesForInitialFeeWarning();
  if (diagnoses.length === 0) return [];

  return [{
    rule_code: INITIAL_DIAGNOSIS_REMAINS_WARNING.ruleCode,
    itemName: action?.name || INITIAL_DIAGNOSIS_REMAINS_WARNING.itemName,
    category: setting.warning_type || INITIAL_DIAGNOSIS_REMAINS_WARNING.warningType,
    message: setting.chart_note || INITIAL_DIAGNOSIS_REMAINS_WARNING.message,
    level: setting.chart_level || 'warning'
  }];
}

function isActiveRealtimeWarning(warning) {
  if (!warning || warning.passed === true || !warning.message) return false;
  const setting = findFacilityWarningSettingForWarning(warning);
  if (setting?.chart_enabled === false) return false;
  if (
    isPrescriptionAuditWarningForLevelFilter(warning)
    && !isIndicationAuditWarning(warning)
    && getKarteWarningSeverityLevel(warning) < getPrescriptionAuditMinimumLevel()
  ) {
    return false;
  }
  return true;
}

function normalizeWarningCompareText(value) {
  return String(value || '')
    .replace(/\u3000/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();
}

function getWarningTargetCodes(warning) {
  const source = warning?.sourceWarning || {};
  return [
    warning?.target_code,
    warning?.related_code,
    warning?.action_code,
    warning?.item_code,
    warning?.drug_code,
    warning?.code,
    warning?.details?.target_code,
    warning?.details?.related_code,
    warning?.details?.drug_code,
    source.target_code,
    source.related_code,
    source.action_code,
    source.item_code,
    source.drug_code,
    source.code,
    source.details?.target_code,
    source.details?.related_code,
    source.details?.drug_code
  ].map(value => String(value || '').trim()).filter(Boolean);
}

function getWarningTargetNames(warning) {
  const source = warning?.sourceWarning || {};
  return [
    warning?.itemName,
    warning?.item_name,
    warning?.target_name,
    warning?.related_name,
    warning?.action_name,
    warning?.drug_name,
    warning?.name,
    source.itemName,
    source.item_name,
    source.target_name,
    source.related_name,
    source.action_name,
    source.drug_name,
    source.name
  ].map(normalizeWarningCompareText).filter(Boolean);
}

function warningMatchesItem(warning, itemCode, itemName) {
  const code = String(itemCode || '').trim();
  if (code && getWarningTargetCodes(warning).includes(code)) return true;

  const name = normalizeWarningCompareText(itemName);
  if (!name) return false;
  return getWarningTargetNames(warning).some(targetName =>
    targetName === name || targetName.includes(name) || name.includes(targetName)
  );
}

function formatCalculationWarningForAction(warning, action) {
  const categoryLabels = {
    exclusive: '同時算定チェック',
    combine: '併算定チェック',
    limit: '回数制限チェック',
    age: '年齢制限チェック',
    diagnosis: '傷病名チェック',
    comment: '選択式コメント確認'
  };
  return {
    itemName: action?.name || warning?.target_name || warning?.action_name || warning?.rule_name || '処置行為',
    category: categoryLabels[warning?.category] || warning?.warning_type || warning?.prohibition_name || warning?.rule_name || '算定チェック',
    message: warning?.message || '',
    level: warning?.level === 'error' ? 'error' : 'warning'
  };
}

function buildCommentAppendWarningMessage(comment) {
  const label = getReceiptCommentAppendLabel(comment) || 'コメント';
  return `定型文以降のコメントが未入力です。定型文を変更せずにコメントを追記してください。修正しても改善されない場合はコメントを削除して入れなおしてください。（エラーコード：${DIGIKAR_COMMENT_APPEND_ERROR_CODE}）（${label}）`;
}

function buildCommentAppendWarningForEntry(entry, comment, entryKind = 'action') {
  const itemName = entryKind === 'prescription'
    ? (entry?.drug_name || entry?.name || '処方薬')
    : (entry?.name || entry?.action_name || '処置行為');
  const itemCode = entryKind === 'prescription'
    ? (entry?.drug_code || entry?.code || '')
    : (entry?.code || entry?.action_code || '');
  return {
    rule_code: DIGIKAR_COMMENT_APPEND_ERROR_CODE,
    ruleCode: DIGIKAR_COMMENT_APPEND_ERROR_CODE,
    rule_type: 'calculation',
    ruleType: 'calculation',
    rule_name: 'コメント入力形式チェック',
    warning_type: '算定チェック',
    category: '算定チェック',
    typeLabel: '算定チェック',
    itemName,
    item_name: itemName,
    target_name: itemName,
    target_code: itemCode,
    item_code: itemCode,
    message: buildCommentAppendWarningMessage(comment),
    level: 'warning',
    icon: 'comment-error-code',
    details: {
      error_code: DIGIKAR_COMMENT_APPEND_ERROR_CODE,
      comment_code: comment?.code || comment?.comment_code || '',
      comment_name: getReceiptCommentAppendLabel(comment),
      audit_icon: 'comment-error-code',
      warning_source: 'm3_digikar_comment_code'
    }
  };
}

function getCommentAppendWarningsForEntry(entry, entryKind = 'action') {
  const comments = entryKind === 'prescription'
    ? getPrescriptionComments(entry)
    : getActionComments(entry);
  return comments
    .filter(comment => isReceiptCommentAppendTemplate(comment))
    .filter(comment => looksLikeReceiptCommentPlaceholder(getReceiptCommentAppendedText(comment), comment))
    .map(comment => buildCommentAppendWarningForEntry(entry, comment, entryKind));
}

function getCalculationWarningsForAction(action) {
  return (calculationWarnings || [])
    .filter(isActiveRealtimeWarning)
    .filter(warning => warningMatchesItem(warning, action?.code, action?.name))
    .map(warning => formatCalculationWarningForAction(warning, action));
}

function getProcedureActionWarnings(action) {
  return [
    ...buildInitialDiagnosisRemainsWarnings(action),
    ...getCommentAppendWarningsForEntry(action, 'action'),
    ...getCalculationWarningsForAction(action)
  ];
}

function renderProcedureActionWarnings(action, originalIndex) {
  const warnings = getProcedureActionWarnings(action);
  if (warnings.length === 0) return '';
  const primaryWarning = warnings.find(isCommentAppendErrorWarning) || warnings[0];
  const levelClass = getKarteWarningLevelClass(primaryWarning);
  const commentClass = isCommentAppendErrorWarning(primaryWarning) ? ' comment-warning-code-btn' : '';
  return `
    <button type="button" class="procedure-warning-btn ${escapeHtml(levelClass)}${commentClass}" onclick="event.stopPropagation(); showProcedureActionWarnings(${originalIndex})" title="警告を確認" aria-label="警告を確認">
      ${getKarteWarningInlineIconMarkup(primaryWarning)}
    </button>
  `;
}

function showProcedureActionWarnings(index) {
  const action = selectedActions[index];
  const warnings = getProcedureActionWarnings(action);
  if (warnings.length === 0) return;
  showKarteWarningListDialog(warnings, {
    title: '算定チェック警告',
    confirmText: '閉じる'
  });
}

function formatDrugWarningForPrescription(warning, prescription) {
  const typeLabels = {
    dispensing_mix: '院内処方・院外処方の併用チェック',
    interaction: '薬剤相互作用',
    duration: '投与日数警告',
    adverse_drug: '副作用薬チェック',
    regular_drug: '常用薬チェック',
    allergy: 'アレルギーチェック',
    past_history: '既往歴チェック',
    comment: '処方コメント確認',
    long_term_listed: '長期収載品コメント確認',
    multi_drug: '多剤投与確認',
    indication: '適応症チェック',
    contraindication: '禁忌病名チェック',
    dosage: '最大投与量チェック',
    generic_prescription: '一般名処方加算チェック'
  };
  const setting = findFacilityWarningSettingForWarning(warning);
  const level = setting?.chart_level || warning?.level || 'warning';
  const prescriptionCode = prescription?.drug_code || prescription?.code || warning?.drug_code || warning?.target_code || warning?.details?.target_code || '';
  const prescriptionName = prescription?.drug_name || prescription?.name || warning?.target_name || warning?.itemName || '処方薬';
  const formatted = {
    ...warning,
    itemName: prescriptionName,
    category: typeLabels[warning?.type] || typeLabels[warning?.category] || warning?.warning_type || warning?.rule_name || warning?.category || '処方チェック',
    message: warning?.message || warning?.error_message || '',
    level,
    icon: warning?.icon || warning?.details?.audit_icon || (isIndicationAuditWarning(warning) ? 'indication' : 'warning')
  };
  return {
    sourceWarning: warning,
    itemName: formatted.itemName,
    category: formatted.category,
    message: formatted.message,
    level: formatted.level,
    severityLevel: getKarteWarningSeverityLevel(formatted),
    icon: formatted.icon,
    type: warning?.type || warning?.category || '',
    rule_code: getWarningRuleCode(warning),
    rule_type: warning?.rule_type || 'drug',
    item_code: prescriptionCode || getPrimaryWarningTargetCode(warning) || null,
    target_code: prescriptionCode || getPrimaryWarningTargetCode(warning) || null,
    drug_code: prescriptionCode || getPrimaryWarningTargetCode(warning) || null,
    target_name: prescriptionName,
    drug_name: prescriptionName,
    warning_type: warning?.warning_type || warning?.type || warning?.category || formatted.category,
    details: {
      ...(warning?.details || {}),
      target_code: prescriptionCode || warning?.details?.target_code || warning?.target_code || null,
      drug_code: prescriptionCode || warning?.details?.drug_code || warning?.drug_code || null,
      target_name: prescriptionName
    }
  };
}

function getDrugWarningsForPrescription(prescription) {
  return (drugWarnings || [])
    .filter(isActiveRealtimeWarning)
    .filter(warning => !isDispensingMixWarning(warning) || hasMixedPrescriptionDispensingTypes(pendingPrescriptions))
    .filter(warning => warningMatchesItem(
      warning,
      prescription?.drug_code || prescription?.code,
      prescription?.drug_name || prescription?.name
    ))
    .map(warning => formatDrugWarningForPrescription(warning, prescription));
}

function getPrescriptionWarningsForDisplay(prescription) {
  return [
    ...getDrugWarningsForPrescription(prescription),
    ...getCommentAppendWarningsForEntry(prescription, 'prescription'),
    ...getPrescriptionRequirementNotices(prescription)
  ];
}

function renderPrescriptionWarnings(prescription, originalIndex) {
  const warnings = getPrescriptionWarningsForDisplay(prescription);
  if (warnings.length === 0) return '';
  const indicationWarning = warnings.find(isIndicationAuditWarning);
  const alertWarning = warnings
    .filter(warning => !isIndicationAuditWarning(warning))
    .sort((a, b) => Number(isCommentAppendErrorWarning(b)) - Number(isCommentAppendErrorWarning(a)) || getKarteWarningSeverityLevel(b) - getKarteWarningSeverityLevel(a))[0];
  const buttons = [];
  if (alertWarning) {
    buttons.push(`
      <button type="button" class="procedure-warning-btn prescription-warning-btn ${escapeHtml(getKarteWarningLevelClass(alertWarning))}" onclick="event.stopPropagation(); showPrescriptionWarnings(${originalIndex})" title="処方チェック警告を確認" aria-label="処方チェック警告を確認">
        <i class="fas fa-exclamation-triangle"></i>
      </button>
    `);
  }
  if (indicationWarning) {
    buttons.push(`
      <button type="button" class="procedure-warning-btn prescription-warning-btn prescription-indication-btn" onclick="event.stopPropagation(); showPrescriptionWarnings(${originalIndex})" title="適応症チェックを確認" aria-label="適応症チェックを確認">適</button>
    `);
  }
  return `
    <span class="prescription-audit-icons">${buttons.join('')}</span>
  `;
}

function showPrescriptionWarnings(index) {
  const prescription = pendingPrescriptions[index];
  const warnings = getPrescriptionWarningsForDisplay(prescription);
  if (warnings.length === 0) return;
  showKarteWarningListDialog(warnings, {
    title: '処方チェック警告',
    confirmText: '閉じる'
  });
}

