function normalizeStandardBillingLookupText(value) {
  return String(value || '')
    .normalize('NFKC')
    .replace(/[〜～]/g, '~')
    .replace(/[ \t\r\n　]+/g, '')
    .toLowerCase();
}

const STANDARD_BILLING_BY_CODE = new Map();
const STANDARD_BILLING_BY_NAME = new Map();

STANDARD_BILLING_ACTIONS.forEach(action => {
  STANDARD_BILLING_BY_CODE.set(action.code, action);
  (action.codeAliases || []).forEach(alias => {
    STANDARD_BILLING_BY_CODE.set(String(alias), action);
  });
  [action.name, ...(action.aliases || [])].forEach(name => {
    STANDARD_BILLING_BY_NAME.set(normalizeStandardBillingLookupText(name), action);
  });
});

function findStandardBillingAction(action) {
  if (!action) return null;
  const name = action.billing_name || action.name || action.action_name || action.display_name || '';
  const nameMatch = STANDARD_BILLING_BY_NAME.get(normalizeStandardBillingLookupText(name));
  if (nameMatch) return nameMatch;

  const code = String(action.billing_code || action.code || action.action_code || action.receipt_code || '').trim();
  return STANDARD_BILLING_BY_CODE.get(code) || STANDARD_BILLING_BY_CODE.get(normalizeStandardBillingLookupText(code)) || null;
}

function enrichStandardBillingAction(action) {
  const isSelfPay = Boolean(action?.is_self_pay || action?.isSelfPay || action?.item_type === 'self_pay' || action?.category === '自費');
  const isDrug = action?.item_type === 'drug';
  if (!action || isSelfPay || isDrug) return action;

  const standard = findStandardBillingAction(action);
  if (!standard) return action;

  return {
    ...action,
    code: standard.code,
    action_code: standard.code,
    billing_code: standard.code,
    name: standard.name,
    action_name: standard.name,
    billing_name: standard.name,
    points: standard.points,
    score: standard.points,
    unit_score: standard.points,
    pointsMissing: false,
    category: standard.category || action.category || '診察'
  };
}

let facilityAutoCalcActions = [];
let facilityAutoCalcActionsFacilityId = null;
let facilityAutoCalcActionsLoading = false;
let facilityAutoCalcActionsLoadError = null;

async function showFacilityScreen(section = 'medical') {
  if (!(await confirmDiscardKarteChangesIfNeeded())) return false;
  appScreenHistory?.capture();
  resetSetTreeExpansionState();
  const user = Storage.getCurrentUser();
  document.getElementById('login-screen').classList.add('hidden');
  document.getElementById('main-screen').classList.add('hidden');
  document.getElementById('reception-screen').classList.add('hidden');
  document.getElementById('facility-screen')?.classList.remove('hidden');
  setTextById('facility-user-name', user?.name || 'ユーザー');
  applyM3FeatureSettingsToUi();
  await switchFacilitySection(section);
  return true;
}

async function switchFacilitySection(section) {
  const panel = document.querySelector(`[data-facility-panel="${section}"]`);
  if (!panel) {
    showToast('この設定ページは準備中です', 'info');
    return;
  }

  document.querySelectorAll('.facility-side-item').forEach(item => {
    item.classList.toggle('active', item.dataset.facilitySection === section);
  });
  document.querySelectorAll('[data-facility-panel]').forEach(item => {
    item.classList.toggle('hidden', item.dataset.facilityPanel !== section);
  });
  const facilityMain = document.querySelector('.facility-main');
  if (facilityMain) facilityMain.scrollTop = 0;
  window.scrollTo(0, 0);
  scheduleAppScreenHistoryUpdate();

  if (section === 'medical') await renderFacilityMedicalInfo();
  if (section === 'users') await renderFacilityUsers();
  if (section === 'certificates') await renderFacilityCertificates();
  if (section === 'monthly-count') await renderFacilityMonthlyReceptionCounts();
  if (section === 'masters') {
    await refreshAllFacilityMastersFromApi();
    renderFacilityMasterFacilities();
    await renderOfficialMasterImportStatus();
  }
  if (section === 'accident') await renderFacilityAccidentSettings();
  if (section === 'shared-password') await renderFacilitySharedPassword();
  if (section === 'login-log') await renderFacilityLoginLog();
  if (section === 'audit-log') await renderFacilityAuditLog();
  if (section === 'warnings') await renderFacilityWarnings();
  if (section === 'data-submit') await renderFacilityDataSubmissionSettings();
  if (section === 'rme') await renderFacilityRmeNotificationManagement();
  if (section === 'other') await renderFacilityOtherSettings();
  if (section === 'auto-calc') await renderFacilityAutoCalc();
  if (section === 'documents') await renderFacilityDocuments();
}

async function renderFacilityMonthlyReceptionCounts() {
  const tbody = document.getElementById('facility-monthly-count-body');
  if (!tbody) return;

  tbody.innerHTML = '<tr><td colspan="2" class="facility-empty-cell">受付回数を読み込み中...</td></tr>';
  try {
    const response = await ReceptionAPI.listMonthlyCounts();
    const rows = Array.isArray(response) ? response : (response?.data || []);
    if (!rows.length) {
      tbody.innerHTML = '<tr><td colspan="2" class="facility-empty-cell">受付データはありません</td></tr>';
      return;
    }

    tbody.innerHTML = rows.map(row => {
      const year = Number(row.year);
      const month = Number(row.month);
      const receptionCount = Number(row.reception_count);
      const receptionMonth = Number.isInteger(year) && Number.isInteger(month)
        ? `${year}/${month}`
        : '-';
      const countText = Number.isFinite(receptionCount)
        ? `${receptionCount.toLocaleString('ja-JP')} 回`
        : '-';
      return `
        <tr>
          <td>${escapeHtml(receptionMonth)}</td>
          <td>${escapeHtml(countText)}</td>
        </tr>
      `;
    }).join('');
  } catch (error) {
    console.error('月別受付回数取得エラー:', error);
    tbody.innerHTML = `<tr><td colspan="2" class="facility-empty-cell">${escapeHtml(error?.message || '受付回数を取得できませんでした')}</td></tr>`;
  }
}

function renderFacilityMedicalInfoRows(facility) {
  const rows = [
    ['医療機関情報', facility.name],
    ['医療機関コード', facility.code],
    ['郵便番号', facility.postalCode],
    ['住所', facility.address],
    ['電話番号', facility.phone],
    ['FAX番号', facility.fax],
    ['メールアドレス', facility.email],
    ['院内・院外', facility.outpatientType],
    ['適格事業者番号', facility.registrationNumber]
  ];
  return rows.map(([label, value]) => `
    <tr>
      <th>${escapeHtml(label)}</th>
      <td>${escapeHtml(value || '')}</td>
    </tr>
  `).join('');
}

async function renderFacilityMedicalInfo(preloadedFacility = null) {
  const tbody = document.getElementById('facility-medical-info-body');
  if (!tbody) return;

  if (!preloadedFacility) {
    tbody.innerHTML = '<tr><td colspan="2">医療機関情報を読み込み中...</td></tr>';
  }

  try {
    const facility = preloadedFacility || await loadCurrentFacilityInfo({ force: true });
    tbody.innerHTML = renderFacilityMedicalInfoRows(facility);
  } catch (error) {
    console.error('医療機関情報取得エラー:', error);
    tbody.innerHTML = `<tr><td colspan="2">医療機関情報を取得できませんでした: ${escapeHtml(error?.message || '不明なエラー')}</td></tr>`;
  }
}

function normalizeOfficialMasterImportRows(value) {
  if (Array.isArray(value)) return value;
  return value?.items || value?.data || value?.rows || [];
}

function formatOfficialMasterNumber(value) {
  const number = Number(value);
  return Number.isFinite(number) ? number.toLocaleString() : '-';
}

function formatOfficialMasterDateTime(value) {
  if (!value) return '-';
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return String(value);
  return date.toLocaleString('ja-JP', {
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false
  });
}

function getOfficialMasterStatusMeta(row = {}) {
  const status = String(row.status || '').toLowerCase();
  if (row.dry_run) return { label: '差分確認', className: 'running' };
  if (['success', 'completed', 'finished'].includes(status)) return { label: '完了', className: 'success' };
  if (['failed', 'error'].includes(status)) return { label: '失敗', className: 'failed' };
  if (['running', 'started', 'processing'].includes(status)) return { label: '取込中', className: 'running' };
  return { label: row.status || '-', className: '' };
}

function getOfficialMasterDiffText(row = {}) {
  const diff = row.diff_summary && typeof row.diff_summary === 'object' ? row.diff_summary : {};
  const newCount = row.new_count ?? diff.new_count ?? diff.created_count;
  const retainedCount = row.retained_count ?? diff.retained_count ?? diff.updated_count;
  const deactivatedCount = row.deactivated_count ?? diff.deactivated_count ?? diff.deleted_count;
  return [
    `新 ${formatOfficialMasterNumber(newCount)}`,
    `維持 ${formatOfficialMasterNumber(retainedCount)}`,
    `停止 ${formatOfficialMasterNumber(deactivatedCount)}`
  ].join(' / ');
}

function renderOfficialMasterLatestRows(rows) {
  if (!rows.length) {
    return '<tr><td colspan="6" class="facility-master-empty">公式マスターの取込履歴がありません</td></tr>';
  }

  return rows.map(row => {
    const status = getOfficialMasterStatusMeta(row);
    return `
      <tr>
        <td>${escapeHtml(row.master_label || row.master_key || '-')}</td>
        <td><span class="facility-official-master-status ${escapeHtml(status.className)}">${escapeHtml(status.label)}</span></td>
        <td>${escapeHtml(formatOfficialMasterNumber(row.imported_count ?? row.parsed_count))}</td>
        <td class="facility-official-master-diff">${escapeHtml(getOfficialMasterDiffText(row))}</td>
        <td>${escapeHtml(formatOfficialMasterDateTime(row.finished_at || row.started_at))}</td>
        <td>${escapeHtml(row.source_filename || row.source_version || '-')}</td>
      </tr>
    `;
  }).join('');
}

function renderOfficialMasterHistoryRows(rows) {
  if (!rows.length) {
    return '<tr><td colspan="6" class="facility-master-empty">取込履歴がありません</td></tr>';
  }

  return rows.map(row => {
    const status = getOfficialMasterStatusMeta(row);
    const importedText = `${formatOfficialMasterNumber(row.imported_count)} / ${formatOfficialMasterNumber(row.parsed_count)}`;
    return `
      <tr>
        <td>${escapeHtml(formatOfficialMasterDateTime(row.started_at))}</td>
        <td>${escapeHtml(row.master_label || row.master_key || '-')}</td>
        <td><span class="facility-official-master-status ${escapeHtml(status.className)}">${escapeHtml(status.label)}</span></td>
        <td>${escapeHtml(importedText)}</td>
        <td class="facility-official-master-diff">${escapeHtml(getOfficialMasterDiffText(row))}</td>
        <td>${escapeHtml(row.error_message || row.source_filename || '-')}</td>
      </tr>
    `;
  }).join('');
}

async function renderOfficialMasterImportStatus() {
  const summary = document.getElementById('official-master-import-summary');
  const latestBody = document.getElementById('official-master-import-body');
  const historyBody = document.getElementById('official-master-import-history-body');
  if (!summary || !latestBody || !historyBody) return;

  if (typeof FacilityMasterAPI === 'undefined' || !FacilityMasterAPI.listLatestOfficialImports) {
    summary.textContent = '公式マスター取込APIが未接続です';
    latestBody.innerHTML = '<tr><td colspan="6" class="facility-master-empty">公式マスター取込APIが未接続です</td></tr>';
    historyBody.innerHTML = '<tr><td colspan="6" class="facility-master-empty">公式マスター取込APIが未接続です</td></tr>';
    return;
  }

  summary.textContent = '公式マスター取込状況を読み込み中です';
  latestBody.innerHTML = '<tr><td colspan="6" class="facility-master-empty">読み込み中...</td></tr>';
  historyBody.innerHTML = '<tr><td colspan="6" class="facility-master-empty">読み込み中...</td></tr>';

  try {
    const [latestResult, historyResult] = await Promise.all([
      FacilityMasterAPI.listLatestOfficialImports(),
      FacilityMasterAPI.listOfficialImportHistory({ limit: 30 })
    ]);
    const latestRows = normalizeOfficialMasterImportRows(latestResult);
    const historyRows = normalizeOfficialMasterImportRows(historyResult);
    latestBody.innerHTML = renderOfficialMasterLatestRows(latestRows);
    historyBody.innerHTML = renderOfficialMasterHistoryRows(historyRows);
    const latestDate = latestRows
      .map(row => row.finished_at || row.started_at)
      .filter(Boolean)
      .sort()
      .pop();
    summary.textContent = latestRows.length
      ? `最新 ${latestRows.length} 種類 / 最終更新 ${formatOfficialMasterDateTime(latestDate)}`
      : 'まだ公式マスター取込履歴がありません';
  } catch (error) {
    console.error('公式マスター取込状況取得エラー:', error);
    const message = error?.message || '公式マスター取込状況を取得できませんでした';
    summary.textContent = message;
    latestBody.innerHTML = `<tr><td colspan="6" class="facility-master-empty">${escapeHtml(message)}</td></tr>`;
    historyBody.innerHTML = `<tr><td colspan="6" class="facility-master-empty">${escapeHtml(message)}</td></tr>`;
  }
}

function setFacilityInputValue(id, value) {
  const element = document.getElementById(id);
  if (element) element.value = value || '';
}

function populateFacilitySettingsForm(facility) {
  setFacilityInputValue('facility-name', facility.name);
  setFacilityInputValue('facility-founder-name', facility.founderName);
  setFacilityInputValue('facility-code', facility.code);
  setFacilityInputValue('facility-postal-code', facility.postalCode);
  setFacilityInputValue('facility-address', facility.address);
  setFacilityInputValue('facility-tel', facility.phone);
  setFacilityInputValue('facility-fax', facility.fax);
  setFacilityInputValue('facility-email', facility.email);
  setFacilityInputValue('facility-outpatient-type', facility.outpatientType);
  setFacilityInputValue('facility-registration-number', facility.registrationNumber);
}

function formatFacilityApiDateTime(value) {
  if (!value) return '';
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return String(value);
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  const hour = String(date.getHours()).padStart(2, '0');
  const minute = String(date.getMinutes()).padStart(2, '0');
  return `${year}/${month}/${day} ${hour}:${minute}`;
}

function formatFacilityHistoryDateTime(value) {
  if (!value) return '';
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return String(value);
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  const hour = String(date.getHours()).padStart(2, '0');
  const minute = String(date.getMinutes()).padStart(2, '0');
  const second = String(date.getSeconds()).padStart(2, '0');
  return `${year}/${month}/${day} ${hour}:${minute}:${second}`;
}

const facilityRoleLabels = {
  admin: '管理者',
  doctor: '医師',
  nurse: '医師以外の医療従事者',
  clerk: '受付'
};

async function renderFacilityUsers() {
  const tbody = document.getElementById('facility-users-body');
  if (!tbody) return;

  tbody.innerHTML = '<tr><td colspan="9" class="facility-empty-cell">利用者を読み込み中...</td></tr>';
  try {
    const response = await FacilityUserAPI.list();
    facilityUsers = response?.data || [];
  } catch (error) {
    tbody.innerHTML = `<tr><td colspan="9" class="facility-empty-cell">${escapeHtml(error?.message || '利用者を取得できませんでした')}</td></tr>`;
    return;
  }

  const hideInactive = document.getElementById('facility-hide-inactive-users')?.checked !== false;
  const visibleUsers = hideInactive
    ? facilityUsers.filter(facilityUser => facilityUser.is_active)
    : facilityUsers;

  if (!visibleUsers.length) {
    tbody.innerHTML = '<tr><td colspan="9" class="facility-empty-cell">利用者が登録されていません</td></tr>';
    return;
  }

  tbody.innerHTML = visibleUsers.map(user => `
    <tr>
      <td>${escapeHtml(user.login_id)}</td>
      <td>${escapeHtml(user.name)}</td>
      <td>${escapeHtml(facilityRoleLabels[user.role] || user.role)}</td>
      <td>${user.is_facility_admin ? 'あり' : 'なし'}</td>
      <td>${user.is_active ? '有効' : '無効'}</td>
      <td>${escapeHtml(formatFacilityApiDateTime(user.updated_at))}</td>
      <td>${escapeHtml(formatFacilityApiDateTime(user.last_login_at))}</td>
      <td><button type="button" class="facility-row-edit" data-facility-user-edit="${escapeHtmlAttribute(String(user.id || ''))}" title="利用者編集" aria-label="${escapeHtmlAttribute(`${user.name || user.login_id}を編集`)}"><i class="fas fa-pencil-alt"></i></button></td>
      <td><button type="button" class="facility-history-btn" data-facility-user-history="${escapeHtmlAttribute(String(user.id || ''))}">ログイン・パスワード更新履歴</button></td>
    </tr>
  `).join('');

  tbody.querySelectorAll('[data-facility-user-edit]').forEach(button => {
    button.addEventListener('click', () => {
      openFacilityUserEditModal(button.dataset.facilityUserEdit);
    });
  });
  tbody.querySelectorAll('[data-facility-user-history]').forEach(button => {
    button.addEventListener('click', () => {
      openFacilityUserHistoryModal(button.dataset.facilityUserHistory);
    });
  });
}

function findFacilityUser(userId) {
  return facilityUsers.find(user => String(user.id) === String(userId)) || null;
}

function checkFacilityUserRadio(name, value) {
  let matched = false;
  document.querySelectorAll(`input[name="${name}"]`).forEach(input => {
    input.checked = input.value === value;
    if (input.checked) matched = true;
  });
  return matched;
}

function updateFacilityUserEditStatus() {
  if (!facilityEditingUser) return;
  const status = document.getElementById('edit-user-status');
  const toggle = document.getElementById('user-edit-status-toggle');
  const active = Boolean(facilityEditingUser.is_active);
  if (status) status.textContent = active ? '有効' : '無効';
  if (toggle) {
    toggle.textContent = active ? '無効化' : '有効化';
    toggle.classList.toggle('is-danger', active);
    toggle.classList.toggle('is-success', !active);
  }
}

function openFacilityUserEditModal(userId) {
  const modal = document.getElementById('user-edit-modal');
  const targetUser = findFacilityUser(userId);
  if (!modal || !targetUser) return;

  facilityEditingUser = { ...targetUser };
  document.getElementById('edit-login-id').textContent = targetUser.login_id || '';
  document.getElementById('edit-user-name').value = targetUser.name || '';
  document.getElementById('edit-user-email').value = targetUser.email || '';

  const displayRole = facilityRoleLabels[targetUser.role] || targetUser.role;
  if (!checkFacilityUserRadio('edit-role', displayRole) && targetUser.role === 'admin') {
    checkFacilityUserRadio('edit-role', '医師');
  }
  checkFacilityUserRadio('edit-admin', targetUser.is_facility_admin ? 'あり' : 'なし');
  updateFacilityUserEditStatus();
  modal.classList.remove('hidden');
  document.getElementById('edit-user-name')?.focus();
}

function closeFacilityUserEditModal() {
  document.getElementById('user-edit-modal')?.classList.add('hidden');
  facilityEditingUser = null;
}

async function saveFacilityUserEdit() {
  if (!facilityEditingUser) return;
  const name = document.getElementById('edit-user-name')?.value.trim() || '';
  const email = document.getElementById('edit-user-email')?.value.trim() || '';
  const selectedRole = document.querySelector('input[name="edit-role"]:checked')?.value || '';
  const admin = document.querySelector('input[name="edit-admin"]:checked')?.value || 'なし';
  if (!name) {
    showToast('利用者名を入力してください', 'error');
    return;
  }

  const roleMap = {
    '医師': 'doctor',
    '医師以外の医療従事者': 'nurse',
    '受付': 'clerk'
  };
  let role = roleMap[selectedRole] || facilityEditingUser.role;
  if (facilityEditingUser.role === 'admin' && selectedRole === '医師') role = 'admin';

  const saveButton = document.getElementById('user-edit-save');
  try {
    if (saveButton) saveButton.disabled = true;
    await FacilityUserAPI.update(facilityEditingUser.id, {
      name,
      name_kana: facilityEditingUser.name_kana || null,
      email: email || null,
      role,
      is_facility_admin: admin === 'あり'
    });
    closeFacilityUserEditModal();
    await renderFacilityUsers();
    showToast('利用者情報を更新しました', 'success');
  } catch (error) {
    showToast(error?.message || '利用者情報を更新できませんでした', 'error');
  } finally {
    if (saveButton) saveButton.disabled = false;
  }
}

async function resetFacilityEditingUserPassword() {
  if (!facilityEditingUser) return;
  const password = prompt('新しいパスワードを8文字以上で入力してください');
  if (password === null) return;
  if (password.length < 8) {
    showToast('パスワードは8文字以上で入力してください', 'error');
    return;
  }
  try {
    await FacilityUserAPI.resetPassword(facilityEditingUser.id, password);
    showToast('パスワードを再設定しました', 'success');
    await renderFacilityUsers();
  } catch (error) {
    showToast(error?.message || 'パスワードを再設定できませんでした', 'error');
  }
}

async function toggleFacilityEditingUserStatus() {
  if (!facilityEditingUser) return;
  const nextActive = !facilityEditingUser.is_active;
  if (!confirm(`この利用者を${nextActive ? '有効' : '無効'}にしますか？`)) return;
  try {
    await FacilityUserAPI.setStatus(facilityEditingUser.id, nextActive);
    showToast('利用者状態を更新しました', 'success');
    closeFacilityUserEditModal();
    await renderFacilityUsers();
  } catch (error) {
    showToast(error?.message || '利用者状態を更新できませんでした', 'error');
  }
}

function closeFacilityUserHistoryModal() {
  document.getElementById('user-history-modal')?.classList.add('hidden');
}

function renderFacilityUserHistoryRows(rows, columnCount, rowRenderer) {
  if (!Array.isArray(rows) || !rows.length) {
    return `<tr><td colspan="${columnCount}" class="facility-empty-cell">履歴はありません</td></tr>`;
  }
  return rows.map(rowRenderer).join('');
}

async function openFacilityUserHistoryModal(userId) {
  const modal = document.getElementById('user-history-modal');
  const loginBody = document.getElementById('user-login-history-body');
  const passwordBody = document.getElementById('user-password-history-body');
  if (!modal || !loginBody || !passwordBody) return;

  loginBody.innerHTML = '<tr><td colspan="3" class="facility-empty-cell">履歴を読み込み中...</td></tr>';
  passwordBody.innerHTML = '<tr><td colspan="2" class="facility-empty-cell">履歴を読み込み中...</td></tr>';
  modal.classList.remove('hidden');
  try {
    const history = await FacilityUserAPI.history(userId);
    loginBody.innerHTML = renderFacilityUserHistoryRows(history?.login_id_history, 3, row => `
      <tr>
        <td>${escapeHtml(formatFacilityHistoryDateTime(row.timestamp))}</td>
        <td>${escapeHtml(row.action || '')}</td>
        <td>${escapeHtml(row.login_id || history?.login_id || '')}</td>
      </tr>
    `);
    passwordBody.innerHTML = renderFacilityUserHistoryRows(history?.password_history, 2, row => `
      <tr>
        <td>${escapeHtml(formatFacilityHistoryDateTime(row.timestamp))}</td>
        <td>${escapeHtml(row.action || '')}</td>
      </tr>
    `);
  } catch (error) {
    const message = escapeHtml(error?.message || '更新履歴を取得できませんでした');
    loginBody.innerHTML = `<tr><td colspan="3" class="facility-empty-cell">${message}</td></tr>`;
    passwordBody.innerHTML = `<tr><td colspan="2" class="facility-empty-cell">${message}</td></tr>`;
  }
}

async function renderFacilityCertificates() {
  const tbody = document.getElementById('facility-certificates-body');
  if (!tbody) return;
  tbody.innerHTML = '<tr><td colspan="5" class="facility-empty-cell">証明書を読み込み中...</td></tr>';
  try {
    const response = await FacilityUserAPI.listCertificates();
    const certificates = response?.data || [];
    const pendingRequests = response?.pending_requests || [];
    if (!certificates.length && !pendingRequests.length) {
      tbody.innerHTML = '<tr><td colspan="5" class="facility-empty-cell">登録済みの証明書はありません</td></tr>';
      return;
    }
    const pendingRows = pendingRequests.map(request => `
      <tr>
        <td title="${escapeHtmlAttribute(request.terminal_name ? `端末名：${request.terminal_name}` : '')}">${escapeHtml(request.common_name || '')}</td>
        <td></td>
        <td></td>
        <td>発行待ち</td>
        <td><button type="button" class="facility-certificate-revoke" data-certificate-request-cancel="${escapeHtmlAttribute(String(request.id || ''))}">取消</button></td>
      </tr>
    `).join('');
    const certificateRows = certificates.map(certificate => {
      const expired = certificate.expires_at && new Date(certificate.expires_at).getTime() <= Date.now();
      const status = certificate.revoked_at ? '無効' : (expired ? '期限切れ' : '有効');
      const commonName = certificate.common_name || certificate.label || '';
      const terminalName = certificate.terminal_name || certificate.label || '';
      return `
        <tr>
          <td title="${escapeHtmlAttribute(terminalName ? `端末名：${terminalName}` : '')}">${escapeHtml(commonName)}</td>
          <td>${escapeHtml(formatFacilityCertificateDateTime(certificate.issued_at))}</td>
          <td>${escapeHtml(formatFacilityCertificateDateTime(certificate.expires_at))}</td>
          <td>${status}</td>
          <td>${status === '有効' ? `<button type="button" class="facility-certificate-revoke" data-certificate-revoke="${escapeHtmlAttribute(String(certificate.id || ''))}">無効化</button>` : ''}</td>
        </tr>
      `;
    }).join('');
    tbody.innerHTML = pendingRows + certificateRows;
    tbody.querySelectorAll('[data-certificate-revoke]').forEach(button => {
      button.addEventListener('click', async () => {
        if (!confirm('この証明書を無効化しますか？')) return;
        try {
          await FacilityUserAPI.revokeCertificate(button.dataset.certificateRevoke);
          showToast('証明書を無効化しました', 'success');
          await renderFacilityCertificates();
        } catch (error) {
          showToast(error?.message || '証明書を無効化できませんでした', 'error');
        }
      });
    });
    tbody.querySelectorAll('[data-certificate-request-cancel]').forEach(button => {
      button.addEventListener('click', async () => {
        if (!confirm('この証明書発行依頼を取り消しますか？')) return;
        try {
          await FacilityUserAPI.cancelCertificateIssueRequest(button.dataset.certificateRequestCancel);
          showToast('証明書発行依頼を取り消しました', 'success');
          await renderFacilityCertificates();
        } catch (error) {
          showToast(error?.message || '証明書発行依頼を取り消せませんでした', 'error');
        }
      });
    });
  } catch (error) {
    tbody.innerHTML = `<tr><td colspan="5" class="facility-empty-cell">${escapeHtml(error?.message || '証明書を取得できませんでした')}</td></tr>`;
  }
}

function formatFacilityCertificateDateTime(value) {
  if (!value) return '';
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return String(value);
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  const hour = String(date.getHours()).padStart(2, '0');
  const minute = String(date.getMinutes()).padStart(2, '0');
  const second = String(date.getSeconds()).padStart(2, '0');
  return `${year}/${month}/${day} ${hour}:${minute}:${second}`;
}

function openCertificateRegisterModal() {
  const modal = document.getElementById('certificate-register-modal');
  if (!modal) return;
  document.getElementById('certificate-terminal-name').value = '';
  modal.classList.remove('hidden');
  document.getElementById('certificate-terminal-name')?.focus();
}

function closeCertificateRegisterModal() {
  document.getElementById('certificate-register-modal')?.classList.add('hidden');
}

async function saveCertificateRegistration() {
  const terminalName = document.getElementById('certificate-terminal-name')?.value.trim() || '';
  const saveButton = document.getElementById('certificate-register-save');
  if (!terminalName) {
    showToast('端末名を入力してください', 'error');
    return;
  }
  if (saveButton) saveButton.disabled = true;
  try {
    const request = await FacilityUserAPI.createCertificateIssueRequest(terminalName);
    const requestFile = {
      request_id: request.request_id,
      facility_code: request.facility_code,
      facility_name: request.facility_name,
      common_name: request.common_name,
      terminal_name: request.terminal_name,
      requested_at: request.requested_at,
      validity: request.validity
    };
    const blob = new Blob([JSON.stringify(requestFile, null, 2)], { type: 'application/json;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `${request.common_name || 'digimaster-certificate'}-request.json`;
    document.body.appendChild(link);
    link.click();
    link.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
    closeCertificateRegisterModal();
    await renderFacilityCertificates();
    showToast(`${request.common_name || '端末証明書'}の発行依頼を登録しました`, 'success');
  } catch (error) {
    showToast(error?.message || '証明書発行依頼を登録できませんでした', 'error');
  } finally {
    if (saveButton) saveButton.disabled = false;
  }
}

function formatFacilityDateTime(date = new Date()) {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  const h = String(date.getHours()).padStart(2, '0');
  const min = String(date.getMinutes()).padStart(2, '0');
  return `${y}/${m}/${d} ${h}:${min}`;
}

function openUserRegisterModal() {
  const modal = document.getElementById('user-register-modal');
  if (!modal) return;

  document.getElementById('register-login-id').value = '';
  document.getElementById('register-user-name').value = '';
  document.getElementById('register-password').value = '';
  document.getElementById('register-email').value = '';
  document.querySelector('input[name="register-role"][value="医師"]')?.click();
  document.querySelector('input[name="register-admin"][value="なし"]')?.click();
  modal.classList.remove('hidden');
  document.getElementById('register-login-id')?.focus();
}

function closeUserRegisterModal() {
  document.getElementById('user-register-modal')?.classList.add('hidden');
}

async function saveUserRegistration() {
  const loginId = document.getElementById('register-login-id')?.value.trim() || '';
  const name = document.getElementById('register-user-name')?.value.trim() || '';
  const password = document.getElementById('register-password')?.value || '';
  const email = document.getElementById('register-email')?.value.trim() || '';
  const role = document.querySelector('input[name="register-role"]:checked')?.value || '医師';
  const admin = document.querySelector('input[name="register-admin"]:checked')?.value || 'なし';

  if (!loginId || !name || !password) {
    showToast('ログインID、利用者名、初期パスワードを入力してください', 'error');
    return;
  }
  if (password.length < 8) {
    showToast('初期パスワードは8文字以上で入力してください', 'error');
    return;
  }

  const roleMap = {
    '医師': 'doctor',
    '医師以外の医療従事者': 'nurse',
    '受付': 'clerk'
  };
  const saveButton = document.getElementById('user-register-save');
  try {
    if (saveButton) saveButton.disabled = true;
    await FacilityUserAPI.create({
      login_id: loginId,
      password,
      name,
      email: email || null,
      role: roleMap[role] || 'clerk',
      is_facility_admin: admin === 'あり'
    });
    closeUserRegisterModal();
    await renderFacilityUsers();
    showToast('利用者を登録しました', 'success');
  } catch (error) {
    showToast(error?.message || '利用者を登録できませんでした', 'error');
  } finally {
    if (saveButton) saveButton.disabled = false;
  }
}

function cloneFacilityMasterDefaults(type) {
  const definition = facilityMasterDefinitions[type];
  return (definition?.defaults || []).map(item => normalizeFacilityLocalMasterItem(item));
}

function normalizeFacilityMasterDateValue(value) {
  if (value instanceof Date && !Number.isNaN(value.getTime())) return getLocalDateString(value);
  const raw = String(value ?? '').trim();
  if (!raw) return '';

  const noExpiryText = raw.replace(/\s+/g, '').toLowerCase();
  if (['なし', '無し', '無期限', 'none', 'null', 'undefined', '-'].includes(noExpiryText)) return '';

  const normalized = raw
    .replace(/[年月]/g, '-')
    .replace(/日$/, '')
    .replace(/[/.]/g, '-')
    .replace(/\s+/g, '');
  const match = normalized.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
  if (!match) return raw;

  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  const date = new Date(year, month - 1, day);
  if (
    Number.isNaN(date.getTime())
    || date.getFullYear() !== year
    || date.getMonth() !== month - 1
    || date.getDate() !== day
  ) {
    return raw;
  }

  return `${match[1]}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
}

function formatFacilityMasterDateDisplay(value, emptyLabel = 'なし') {
  const normalized = normalizeFacilityMasterDateValue(value);
  if (!normalized || normalized === '9999-12-31') return emptyLabel;
  const match = normalized.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!match) return String(value ?? '').trim() || emptyLabel;
  return `${match[1]}年${match[2]}月${match[3]}日`;
}

function isFacilityMasterDateExpired(value, referenceDate = getLocalDateString()) {
  const normalized = normalizeFacilityMasterDateValue(value);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(normalized) || normalized === '9999-12-31') return false;
  return normalized < referenceDate;
}

function isFacilityMasterItemVisible(type, item) {
  const status = String(item?.status || '').trim();
  if (['無効', '削除'].includes(status)) return false;
  if (type === 'doctors' && isFacilityMasterDateExpired(item?.expiry_date || item?.expires || item?.end)) return false;
  return true;
}

function loadFacilityLocalMasters() {
  const emptyMasters = Object.fromEntries(
    Object.keys(facilityMasterDefinitions).map(type => [type, []])
  );
  try {
    const raw = localStorage.getItem(FACILITY_LOCAL_MASTER_STORAGE_KEY);
    if (!raw) return emptyMasters;
    const parsed = JSON.parse(raw);
    return Object.fromEntries(
      Object.keys(facilityMasterDefinitions).map(type => {
        const rows = Array.isArray(parsed[type]) ? parsed[type] : emptyMasters[type];
        return [type, rows.map(item => normalizeFacilityLocalMasterItem(item))];
      })
    );
  } catch (error) {
    console.warn('施設マスタのローカル保存データを読み込めませんでした:', error);
    return emptyMasters;
  }
}

function saveFacilityLocalMasters() {
  try {
    localStorage.setItem(FACILITY_LOCAL_MASTER_STORAGE_KEY, JSON.stringify(facilityLocalMasters));
  } catch (error) {
    console.warn('施設マスタのローカル保存に失敗しました:', error);
  }
}

function normalizeFacilityLocalMasterItem(item) {
  if (typeof item === 'string') return { name: item, detail: '' };
  const payload = item?.payload && typeof item.payload === 'object' ? item.payload : {};
  return {
    id: item?.id || null,
    code: String(item?.code || item?.item_code || '').trim(),
    name: String(item?.name || '').trim(),
    detail: String(item?.detail || '').trim(),
    name_kana: String(item?.name_kana || item?.kana || payload.kana || '').trim(),
    status: String(item?.status || '').trim(),
    effective_date: normalizeFacilityMasterDateValue(item?.effective_date || item?.start || ''),
    expiry_date: normalizeFacilityMasterDateValue(item?.expiry_date || item?.expires || item?.end || ''),
    sort_order: Number.isFinite(Number(item?.sort_order)) ? Number(item.sort_order) : 0,
    payload
  };
}

function normalizeFacilityMasterApiItem(item) {
  return normalizeFacilityLocalMasterItem({
    id: item?.id,
    code: item?.code,
    name: item?.name,
    detail: item?.detail,
    name_kana: item?.name_kana,
    status: item?.status,
    effective_date: item?.effective_date,
    expiry_date: item?.expiry_date,
    sort_order: item?.sort_order,
    payload: item?.payload || {}
  });
}

function buildFacilityMasterApiPayload(type, item, index = 0) {
  const normalized = normalizeFacilityLocalMasterItem(item);
  const payload = { ...(normalized.payload || {}) };
  return {
    code: normalized.code || null,
    name: normalized.name,
    name_kana: normalized.name_kana || null,
    detail: normalized.detail || null,
    status: normalized.status || '有効',
    effective_date: normalizeFacilityMasterDateValue(normalized.effective_date) || null,
    expiry_date: normalizeFacilityMasterDateValue(normalized.expiry_date) || null,
    sort_order: normalized.sort_order || index,
    payload
  };
}

function getFacilityMasterFieldValue(item, key) {
  if (!item || !key) return '';
  if (key.startsWith('payload.')) {
    const payloadKey = key.slice('payload.'.length);
    return item.payload?.[payloadKey] ?? '';
  }
  return item[key] ?? '';
}

function setFacilityMasterFieldValue(item, key, value) {
  if (!key) return;
  if (key.startsWith('payload.')) {
    const payloadKey = key.slice('payload.'.length);
    item.payload = { ...(item.payload || {}), [payloadKey]: value };
    return;
  }
  item[key] = value;
}

function facilityMasterModalRowToItem(type, row, index = 0) {
  const config = facilityMasterListModalConfigs[type];
  const nameKey = config?.columns.find(column => ['name', 'template'].includes(column.key))?.key || 'name';
  const name = String(row?.[nameKey] || '').trim();
  const effectiveDate = normalizeFacilityMasterDateValue(row?.start || row?.effective_date || '');
  const expiryDate = normalizeFacilityMasterDateValue(row?.end || row?.expires || row?.expiry_date || '');
  const item = {
    id: row?.id || null,
    code: row?.code || '',
    name,
    detail: row?.status || row?.kana || expiryDate || '',
    name_kana: row?.kana || '',
    status: row?.status || '有効',
    effective_date: effectiveDate,
    expiry_date: expiryDate,
    sort_order: Number.isInteger(row?.localIndex) ? row.localIndex : index,
    payload: {}
  };
  if (type === 'doctors') {
    item.detail = row?.detail || '';
  }
  if (type === 'materials') {
    item.payload = {
      unit: row?.unit || '',
      film: row?.film || '',
      receiptCode: row?.receiptCode || '',
      price: row?.price || ''
    };
  }
  if (type === 'departments') {
    item.detail = row?.kind || row?.detail || '';
  }
  if (type === 'comments') {
    item.detail = row?.template || name;
  }
  return normalizeFacilityLocalMasterItem(item);
}

function renderFacilityMasterExtraFields(type, item = {}) {
  const container = document.getElementById('facility-master-extra-fields');
  if (!container) return;
  const fields = facilityMasterRegisterFieldConfigs[type] || [];
  if (!fields.length) {
    container.innerHTML = '';
    container.classList.add('hidden');
    return;
  }

  container.innerHTML = fields.map(field => {
    const value = field.type === 'date'
      ? normalizeFacilityMasterDateValue(getFacilityMasterFieldValue(item, field.key))
      : String(getFacilityMasterFieldValue(item, field.key) || '');
    const inputType = field.type || 'text';
    const isReadOnly = field.readOnly || (field.readOnlyOnEdit && facilityEditingMasterIndex !== null);
    const readonlyAttr = isReadOnly ? ' readonly aria-readonly="true"' : '';
    const requiredAttr = field.required ? ' required' : '';
    const placeholderAttr = field.placeholder ? ` placeholder="${escapeHtml(field.placeholder)}"` : '';
    return `
      <label class="facility-register-row facility-master-register-row" data-facility-master-row="${escapeHtml(field.key)}">
        <span>${escapeHtml(field.label)}</span>
        <em>${field.required ? '必須' : ''}</em>
        <input type="${escapeHtml(inputType)}" data-facility-master-field="${escapeHtml(field.key)}" value="${escapeHtml(value)}"${placeholderAttr}${readonlyAttr}${requiredAttr}>
      </label>
    `;
  }).join('');
  container.classList.remove('hidden');
}

function collectFacilityMasterExtraFields(type, item) {
  const nextItem = normalizeFacilityLocalMasterItem(item);
  const fields = facilityMasterRegisterFieldConfigs[type] || [];
  fields.forEach(field => {
    const input = document.querySelector(`[data-facility-master-field="${field.key}"]`);
    const value = input?.value.trim() || '';
    setFacilityMasterFieldValue(
      nextItem,
      field.key,
      field.type === 'date' ? normalizeFacilityMasterDateValue(value) : value
    );
  });
  return normalizeFacilityLocalMasterItem(nextItem);
}

function normalizeFacilitySelfPayNumberText(value) {
  return formatHalfWidthNumericText(String(value ?? '')).replace(/,/g, '');
}

function parseFacilitySelfPayAmount(value) {
  const normalized = normalizeFacilitySelfPayNumberText(value).replace(/[^\d.-]/g, '');
  const amount = Math.floor(Number(normalized));
  return Number.isFinite(amount) ? Math.max(0, amount) : 0;
}

function parseFacilitySelfPayTaxRate(value) {
  if (value === null || value === undefined || value === '') return null;
  const normalized = normalizeFacilitySelfPayNumberText(value).replace(/[^\d.]/g, '');
  if (!normalized) return null;
  const rate = Number(normalized);
  return Number.isFinite(rate) ? rate : null;
}

function formatFacilitySelfPayTaxRate(value) {
  const rate = parseFacilitySelfPayTaxRate(value);
  return rate === null ? '' : `${rate.toLocaleString()}%`;
}

function calculateFacilitySelfPayTaxAmount(price, taxRate) {
  const normalizedPrice = parseFacilitySelfPayAmount(price);
  const normalizedRate = parseFacilitySelfPayTaxRate(taxRate);
  if (!normalizedRate || normalizedPrice <= 0) return '';
  return Math.floor((normalizedPrice * normalizedRate) / (100 + normalizedRate));
}

function normalizeFacilitySelfPayDateValue(value) {
  const text = formatHalfWidthNumericText(String(value || '')).trim();
  if (!text) return null;
  const match = text.match(/^(\d{1,4})[\/.-](\d{1,2})[\/.-](\d{1,2})$/);
  if (!match) return undefined;
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  if (!Number.isInteger(year) || !Number.isInteger(month) || !Number.isInteger(day)) return undefined;
  if (year < 1 || month < 1 || month > 12 || day < 1 || day > 31) return undefined;
  return `${String(year).padStart(4, '0')}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
}

function getFacilityEditingSelfPayItem() {
  if (facilityEditingSelfPayDraft) return facilityEditingSelfPayDraft;
  if (!facilityEditingSelfPayId) return null;
  return facilitySelfPayMasterRows.find(row => String(row.id) === String(facilityEditingSelfPayId)) || null;
}

function getNextFacilitySelfPayMasterCode() {
  const rows = [
    ...facilitySelfPayMasterRows,
    ...facilityMasterListRows,
    ...(facilityMasterListModalConfigs.self_pay?.rows || [])
  ];
  const maxCode = rows.reduce((max, row) => {
    const code = String(row.item_code || row.code || '').trim();
    const match = code.match(/^095(\d{6})$/);
    if (!match) return max;
    return Math.max(max, Number(match[1]));
  }, 0);
  return `095${String(maxCode + 1).padStart(6, '0')}`;
}

function normalizeFacilitySelfPayMasterRow(item = {}, index = 0) {
  const price = parseFacilitySelfPayAmount(item.price ?? item.taxIncluded ?? item.unit_price ?? 0);
  const rawTaxRate = item.tax_rate ?? item.taxRate;
  const taxRate = parseFacilitySelfPayTaxRate(rawTaxRate);
  const storedTaxAmount = item.tax_amount ?? item.taxAmount;
  const taxAmount = storedTaxAmount === null || storedTaxAmount === undefined || storedTaxAmount === ''
    ? calculateFacilitySelfPayTaxAmount(price, taxRate)
    : parseFacilitySelfPayAmount(storedTaxAmount);
  const kana = item.name_kana || item.kana || item.furigana || item.name_short || '';
  return {
    id: item.id || null,
    code: item.item_code || item.code || (index === null ? getNextFacilitySelfPayMasterCode() : formatFacilityMasterModalCode('095', index, 6)),
    name: item.name || '',
    kana,
    start: item.start_date || item.start || '0001-01-01',
    end: item.end_date || item.end || '9999-12-31',
    taxIncluded: `${price.toLocaleString()}.0`,
    taxRate: formatFacilitySelfPayTaxRate(taxRate),
    taxAmount: taxAmount === '' ? '' : taxAmount,
    price,
    rawTaxRate: taxRate,
    category: item.category || '自費',
    sourceType: item.sourceType || 'self_pay'
  };
}

function renderFacilitySelfPayExtraFields(item = {}) {
  const container = document.getElementById('facility-master-extra-fields');
  if (!container) return;
  const sourceItem = item && Object.keys(item).length ? item : { code: getNextFacilitySelfPayMasterCode(), start: '0001-01-01', end: '9999-12-31' };
  const row = normalizeFacilitySelfPayMasterRow(sourceItem, null);
  const taxRate = parseFacilitySelfPayTaxRate(item.tax_rate ?? item.taxRate ?? row.rawTaxRate);
  const taxAmount = item.tax_amount ?? item.taxAmount ?? calculateFacilitySelfPayTaxAmount(row.price, taxRate);
  container.innerHTML = `
    <label class="facility-register-row facility-master-register-row">
      <span>コード</span>
      <em>必須</em>
      <input type="text" data-self-pay-master-field="item_code" value="${escapeHtml(row.code)}">
    </label>
    <label class="facility-register-row facility-master-register-row">
      <span>カナ</span>
      <em></em>
      <input type="text" data-self-pay-master-field="name_kana" value="${escapeHtml(row.kana)}">
    </label>
    <label class="facility-register-row facility-master-register-row">
      <span>開始日</span>
      <em></em>
      <input type="text" data-self-pay-master-field="start_date" placeholder="yyyy/mm/dd" value="${escapeHtml(row.start)}">
    </label>
    <label class="facility-register-row facility-master-register-row">
      <span>終了日</span>
      <em></em>
      <input type="text" data-self-pay-master-field="end_date" placeholder="yyyy/mm/dd" value="${escapeHtml(row.end)}">
    </label>
    <label class="facility-register-row facility-master-register-row">
      <span>税込金額</span>
      <em>必須</em>
      <input type="number" data-self-pay-master-field="price" min="0" step="1" value="${escapeHtml(String(row.price))}">
    </label>
    <div class="facility-register-row facility-master-register-row facility-self-pay-tax-rate-row">
      <span>消費税率</span>
      <em></em>
      <div class="facility-radio-group facility-self-pay-tax-rate-options">
        <label><input type="radio" name="facility-self-pay-tax-rate" value="" ${taxRate === null ? 'checked' : ''}> 未設定</label>
        <label><input type="radio" name="facility-self-pay-tax-rate" value="8" ${taxRate === 8 ? 'checked' : ''}> 8%</label>
        <label><input type="radio" name="facility-self-pay-tax-rate" value="10" ${taxRate === 10 ? 'checked' : ''}> 10%</label>
      </div>
    </div>
    <label class="facility-register-row facility-master-register-row">
      <span>消費税額</span>
      <em></em>
      <input type="number" data-self-pay-master-field="tax_amount" min="0" step="1" value="${taxAmount === '' || taxAmount === null || taxAmount === undefined ? '' : escapeHtml(String(taxAmount))}">
    </label>
  `;
  container.classList.remove('hidden');

  const priceInput = container.querySelector('[data-self-pay-master-field="price"]');
  const taxAmountInput = container.querySelector('[data-self-pay-master-field="tax_amount"]');
  const recalculateTaxAmount = () => {
    if (!taxAmountInput || taxAmountInput.dataset.manual === 'true') return;
    const selectedRate = container.querySelector('input[name="facility-self-pay-tax-rate"]:checked')?.value ?? '';
    taxAmountInput.value = selectedRate ? String(calculateFacilitySelfPayTaxAmount(priceInput?.value, selectedRate)) : '';
  };
  priceInput?.addEventListener('input', recalculateTaxAmount);
  container.querySelectorAll('input[name="facility-self-pay-tax-rate"]').forEach(input => {
    input.addEventListener('change', () => {
      if (taxAmountInput) taxAmountInput.dataset.manual = '';
      recalculateTaxAmount();
    });
  });
  taxAmountInput?.addEventListener('input', () => {
    taxAmountInput.dataset.manual = 'true';
  });
}

function collectFacilitySelfPayMasterPayload(name) {
  const getValue = field => document.querySelector(`[data-self-pay-master-field="${field}"]`)?.value.trim() || '';
  const itemCode = getValue('item_code');
  const priceText = getValue('price');
  const startDate = normalizeFacilitySelfPayDateValue(getValue('start_date'));
  const endDate = normalizeFacilitySelfPayDateValue(getValue('end_date'));
  const taxRateValue = document.querySelector('input[name="facility-self-pay-tax-rate"]:checked')?.value ?? '';
  const taxRate = taxRateValue === '' ? null : parseFacilitySelfPayTaxRate(taxRateValue);
  const taxAmountText = getValue('tax_amount');
  const calculatedTaxAmount = calculateFacilitySelfPayTaxAmount(priceText, taxRate);
  return {
    item_code: itemCode || null,
    name,
    name_short: name.slice(0, 100),
    name_kana: getValue('name_kana') || null,
    price: parseFacilitySelfPayAmount(priceText),
    tax_rate: taxRate,
    tax_amount: taxAmountText ? parseFacilitySelfPayAmount(taxAmountText) : (calculatedTaxAmount === '' ? null : calculatedTaxAmount),
    category: document.getElementById('facility-master-category')?.value.trim() || '自費',
    start_date: startDate,
    end_date: endDate,
    _priceBlank: !priceText,
    _invalidDate: startDate === undefined || endDate === undefined
  };
}

async function refreshFacilityMasterTypeFromApi(type) {
  if (!facilityMasterDefinitions[type] || typeof FacilityMasterAPI === 'undefined') return false;
  try {
    const rows = await FacilityMasterAPI.list(type);
    if (!Array.isArray(rows)) return false;
    facilityLocalMasters[type] = rows.map(normalizeFacilityMasterApiItem);
    facilityMasterApiLoadedTypes.add(type);
    saveFacilityLocalMasters();
    return true;
  } catch (error) {
    console.error(`${type} マスタAPIを読み込めませんでした:`, error);
    facilityMasterApiLoadedTypes.delete(type);
    return false;
  }
}

async function refreshAllFacilityMastersFromApi() {
  const types = Object.keys(facilityMasterDefinitions);
  await Promise.all(types.map(type => refreshFacilityMasterTypeFromApi(type)));
}

function getFacilityMasterItems(type) {
  if (!facilityMasterDefinitions[type]) return [];
  const localRows = Array.isArray(facilityLocalMasters?.[type]) ? facilityLocalMasters[type] : [];
  const hasApi = typeof FacilityMasterAPI !== 'undefined';
  const sourceRows = (hasApi || facilityMasterApiLoadedTypes.has(type))
    ? localRows
    : (localRows.length ? localRows : cloneFacilityMasterDefaults(type));
  return sourceRows
    .map(item => normalizeFacilityLocalMasterItem(item))
    .filter(item => item.name && isFacilityMasterItemVisible(type, item));
}

function getFacilityMasterNames(type) {
  const seen = new Set();
  return getFacilityMasterItems(type)
    .map(item => item.name.trim())
    .filter(name => {
      if (!name || seen.has(name)) return false;
      seen.add(name);
      return true;
    });
}

async function ensureFacilityMasterLoaded(type) {
  if (!facilityMasterDefinitions[type]) return false;
  if (facilityMasterApiLoadedTypes.has(type)) return true;
  return refreshFacilityMasterTypeFromApi(type);
}

function getFacilityMasterTypeFromControl(control) {
  const label = control.closest('tr')?.querySelector('td')?.textContent.trim();
  return facilityMasterImportLabelMap[label] || null;
}

function setFacilityMasterTableHeader(columns) {
  const headerRow = document.querySelector('.facility-master-table thead tr');
  if (!headerRow) return;
  headerRow.closest('table')?.classList.toggle('facility-master-table-wide', columns.length >= 6);
  headerRow.innerHTML = columns.map(column => `<th>${escapeHtml(column)}</th>`).join('') + '<th></th>';
}

function setFacilityMasterListHeading(title, showRegister = true) {
  const heading = document.querySelector('.facility-master-heading h3');
  const registerBtn = document.getElementById('btn-facility-master-register');
  if (heading) heading.textContent = title;
  if (registerBtn) registerBtn.classList.toggle('hidden', !showRegister);
}

function renderFacilityMasterFacilities() {
  facilityActiveMasterType = 'facilities';
  facilityEditingMasterIndex = null;
  const tbody = document.getElementById('facility-master-body');
  if (!tbody) return;

  setFacilityMasterListHeading('施設マスタ', true);
  setFacilityMasterTableHeader(['施設名']);
  tbody.innerHTML = facilityMasterFacilities.map(name => `
    <tr>
      <td>${escapeHtml(name)}</td>
      <td><button type="button" class="facility-row-edit" title="編集"><i class="fas fa-pen"></i></button></td>
    </tr>
  `).join('');
}

function renderFacilityLocalMaster(type) {
  const definition = facilityMasterDefinitions[type];
  const tbody = document.getElementById('facility-master-body');
  if (!definition || !tbody) return;

  facilityActiveMasterType = type;
  facilityEditingMasterIndex = null;
  setFacilityMasterListHeading(`${definition.label}マスタ`, true);
  if (type === 'doctors') {
    setFacilityMasterTableHeader(['コード', '名前', 'ステータス', '有効期限']);
  } else {
    setFacilityMasterTableHeader(definition.columns);
  }

  const rows = (facilityLocalMasters[type] || [])
    .map((item, index) => ({ item: normalizeFacilityLocalMasterItem(item), index }))
    .filter(row => isFacilityMasterItemVisible(type, row.item));
  if (!rows.length) {
    const columnCount = type === 'doctors' ? 5 : definition.columns.length + 1;
    tbody.innerHTML = `<tr><td colspan="${columnCount}" class="facility-master-empty">登録されていません</td></tr>`;
    return;
  }

  tbody.innerHTML = rows.map(({ item, index }) => {
    const actionCell = `
      <td>
        <div class="facility-master-actions">
          <button type="button" class="facility-row-edit" data-facility-master-edit="${index}" title="編集"><i class="fas fa-pen"></i></button>
          <button type="button" class="facility-row-delete" data-facility-master-delete="${index}" title="削除"><i class="fas fa-trash"></i></button>
        </div>
      </td>
    `;
    if (type === 'doctors') {
      return `
        <tr>
          <td>${escapeHtml(item.code || '-')}</td>
          <td>${escapeHtml(item.name)}</td>
          <td>${escapeHtml(item.status || '有効')}</td>
          <td>${escapeHtml(formatFacilityMasterDateDisplay(item.expiry_date))}</td>
          ${actionCell}
        </tr>
      `;
    }
    return `
      <tr>
        <td>${escapeHtml(item.name)}</td>
        <td>${escapeHtml(item.detail || '-')}</td>
        ${actionCell}
      </tr>
    `;
  }).join('');
}

async function renderFacilitySelfPayMaster() {
  facilityActiveMasterType = 'self_pay';
  facilityEditingMasterIndex = null;
  const tbody = document.getElementById('facility-master-body');
  if (!tbody) return;

  setFacilityMasterListHeading('自費マスタ', true);
  setFacilityMasterTableHeader(['コード', '名前', 'フリガナ', '開始日', '終了日', '税込金額', '消費税率', '消費税額']);
  tbody.innerHTML = '<tr><td colspan="9" class="facility-master-empty">自費マスタを読み込み中...</td></tr>';

  try {
    const result = await RecordActionAPI.getSelfPayMaster();
    const rows = Array.isArray(result) ? result : (result.data || []);
    facilitySelfPayMasterRows = rows;
    tbody.innerHTML = rows.length ? rows.map((item, index) => {
      const row = normalizeFacilitySelfPayMasterRow(item, index);
      return `
      <tr>
        <td>${escapeHtml(row.code)}</td>
        <td>${escapeHtml(row.name)}</td>
        <td>${escapeHtml(row.kana)}</td>
        <td>${escapeHtml(row.start)}</td>
        <td>${escapeHtml(row.end)}</td>
        <td class="facility-master-amount">${escapeHtml(row.taxIncluded)}</td>
        <td>${escapeHtml(row.taxRate)}</td>
        <td class="facility-master-amount">${escapeHtml(String(row.taxAmount || ''))}</td>
        <td>
          <div class="facility-master-actions">
            <button type="button" class="facility-row-edit" data-self-pay-master-edit="${escapeHtml(item.id)}" title="編集"><i class="fas fa-pen"></i></button>
            <button type="button" class="facility-row-copy" data-self-pay-master-copy="${escapeHtml(item.id)}" title="コピー">コピー</button>
            <button type="button" class="facility-row-delete" data-self-pay-master-delete="${escapeHtml(item.id)}" title="削除"><i class="fas fa-trash"></i></button>
          </div>
        </td>
      </tr>
    `;
    }).join('') : '<tr><td colspan="9" class="facility-master-empty">登録されていません</td></tr>';
  } catch (error) {
    facilitySelfPayMasterRows = [];
    console.error('自費マスタの読み込みに失敗しました:', error);
    tbody.innerHTML = '<tr><td colspan="9" class="facility-master-empty">自費マスタを読み込めませんでした</td></tr>';
  }
}

function formatFacilityMasterModalCode(prefix, index, width = 6) {
  return `${prefix}${String(index + 1).padStart(width, '0')}`;
}

function getFacilityMasterModalKey(row, config) {
  const code = String(row?.code || '').trim();
  if (code) return `code:${code}`;
  const nameColumn = config.columns.find(column => ['name', 'template'].includes(column.key)) || config.columns[1];
  return `name:${String(row?.[nameColumn?.key] || '').trim()}`;
}

function normalizeFacilityLocalMasterModalRow(type, item, index) {
  const name = String(item?.name || '').trim();
  const detail = String(item?.detail || '').trim();
  const payload = item?.payload || {};
  if (type === 'departments') {
    return {
      code: item.code || formatFacilityMasterModalCode('9', index, 1).slice(0, 2),
      name,
      expires: formatFacilityMasterDateDisplay(item.expiry_date || (detail && detail !== '外来' ? detail : '')),
      localIndex: index
    };
  }
  if (type === 'doctors') {
    return {
      code: item.code || formatFacilityMasterModalCode('9', index, 4),
      name,
      status: item.status || detail || '有効',
      expires: formatFacilityMasterDateDisplay(item.expiry_date),
      localIndex: index
    };
  }
  if (type === 'diagnoses') {
    return {
      code: item.code || formatFacilityMasterModalCode('D9', index, 5),
      name,
      kana: item.name_kana || detail || '',
      start: item.effective_date || '0001-01-01',
      end: item.expiry_date || '9999-12-31',
      localIndex: index
    };
  }
  if (type === 'usages') {
    return {
      code: item.code || formatFacilityMasterModalCode('0019', index, 5),
      name,
      kana: item.name_kana || detail || name,
      start: item.effective_date || '0001-01-01',
      end: item.expiry_date || '9999-12-31',
      localIndex: index
    };
  }
  if (type === 'materials') {
    return {
      code: item.code || formatFacilityMasterModalCode('0599', index, 5),
      name,
      kana: item.name_kana || detail || name,
      unit: payload.unit || '個',
      film: payload.film || 'いいえ',
      start: item.effective_date || '0001-01-01',
      end: item.expiry_date || '9999-12-31',
      receiptCode: payload.receiptCode || '',
      price: payload.price || '0.0',
      localIndex: index
    };
  }
  if (type === 'bodyParts') {
    return {
      code: item.code || formatFacilityMasterModalCode('0029', index, 5),
      name,
      kana: item.name_kana || detail || name,
      start: item.effective_date || '0001-01-01',
      end: item.expiry_date || '9999-12-31',
      localIndex: index
    };
  }
  if (type === 'comments') {
    return {
      code: item.code || formatFacilityMasterModalCode('09929', index, 4),
      template: name,
      start: item.effective_date || '0001-01-01',
      end: item.expiry_date || '9999-12-31',
      localIndex: index
    };
  }
  return { name, detail, localIndex: index };
}

function buildFacilityMasterLocalModalRows(type, config) {
  const localRows = facilityLocalMasters[type] || [];
  if (facilityMasterApiLoadedTypes.has(type)) {
    const rows = localRows.map((item, index) => ({
      ...normalizeFacilityLocalMasterModalRow(type, item, index),
      sourceType: 'api'
    }));
    return type === 'doctors'
      ? rows.filter(row => isFacilityMasterItemVisible(type, facilityMasterModalRowToItem(type, row, row.localIndex ?? 0)))
      : rows;
  }

  const baseKeys = new Set((config.rows || []).map(row => getFacilityMasterModalKey(row, config)));
  const localByKey = new Map(
    localRows.map((item, index) => {
      const row = normalizeFacilityLocalMasterModalRow(type, item, index);
      return [getFacilityMasterModalKey(row, config), { item, index }];
    })
  );

  const baseRows = (config.rows || []).map(row => {
    const key = getFacilityMasterModalKey(row, config);
    const local = localByKey.get(key);
    return {
      ...row,
      localIndex: local?.index ?? null,
      sourceType: local ? 'local' : 'catalog'
    };
  });

  const extraRows = localRows
    .map((item, index) => normalizeFacilityLocalMasterModalRow(type, item, index))
    .filter(row => !baseKeys.has(getFacilityMasterModalKey(row, config)))
    .map(row => ({ ...row, sourceType: 'local' }));

  const rows = [...baseRows, ...extraRows];
  return type === 'doctors'
    ? rows.filter(row => isFacilityMasterItemVisible(type, facilityMasterModalRowToItem(type, row, row.localIndex ?? 0)))
    : rows;
}

async function buildFacilitySelfPayModalRows(config) {
  try {
    const result = await RecordActionAPI.getSelfPayMaster();
    const rows = Array.isArray(result) ? result : (result.data || []);
    if (rows.length) {
      return rows.map((item, index) => normalizeFacilitySelfPayMasterRow(item, index));
    }
    return [];
  } catch (error) {
    console.warn('自費マスター一覧の取得に失敗しました:', error);
    return [];
  }
}

async function buildFacilityMasterModalRows(type) {
  const config = facilityMasterListModalConfigs[type];
  if (!config) return [];
  if (type === 'self_pay') return buildFacilitySelfPayModalRows(config);
  const loaded = await refreshFacilityMasterTypeFromApi(type);
  if (!loaded) return [];
  return buildFacilityMasterLocalModalRows(type, config);
}

function renderFacilityMasterModalAction(row, action, index) {
  if (action === 'edit') {
    return `
      <button type="button" class="facility-master-modal-icon-btn" data-master-modal-edit="${index}" title="編集">
        <i class="fas fa-pen"></i>
      </button>
    `;
  }
  if (action === 'copy') {
    return `
      <button type="button" class="facility-master-modal-copy-btn" data-master-modal-copy="${index}">
        コピー
      </button>
    `;
  }
  if (action === 'departmentNotice') {
    return `
      <button type="button" class="facility-master-modal-copy-btn">
        ${index === 0 ? '全診療科' : '院内掲示'}
      </button>
    `;
  }
  return '';
}

function renderFacilityMasterListModal() {
  const config = facilityMasterListModalConfigs[facilityMasterListActiveType];
  const title = document.getElementById('facility-master-list-title');
  const head = document.getElementById('facility-master-list-head');
  const body = document.getElementById('facility-master-list-body');
  const newBtn = document.getElementById('facility-master-list-new');
  const toolbar = document.querySelector('.facility-master-list-toolbar');
  const dialog = document.querySelector('.facility-master-list-dialog');
  if (!config || !head || !body) return;

  if (title) title.textContent = config.title;
  if (newBtn) newBtn.classList.toggle('hidden', !config.showNew);
  toolbar?.classList.toggle('hidden', !config.showNew);
  if (dialog) {
    dialog.dataset.masterType = facilityMasterListActiveType;
    dialog.classList.toggle('facility-master-list-dialog-no-toolbar', !config.showNew);
  }

  const actionHeaders = (config.actions || []).map(() => '<th class="facility-master-modal-action-head"></th>').join('');
  head.innerHTML = `<tr>${config.columns.map(column => `<th>${escapeHtml(column.label)}</th>`).join('')}${actionHeaders}</tr>`;

  if (!facilityMasterListRows.length) {
    body.innerHTML = `<tr><td colspan="${config.columns.length + (config.actions || []).length}" class="facility-master-empty">登録されていません</td></tr>`;
    return;
  }

  body.innerHTML = facilityMasterListRows.map((row, index) => `
    <tr>
      ${config.columns.map(column => `<td>${escapeHtml(row[column.key] ?? '')}</td>`).join('')}
      ${(config.actions || []).map(action => `<td class="facility-master-modal-action-cell">${renderFacilityMasterModalAction(row, action, index)}</td>`).join('')}
    </tr>
  `).join('');
}

async function refreshFacilityMasterListModal() {
  if (!facilityMasterListActiveType) return;
  facilityMasterListRows = await buildFacilityMasterModalRows(facilityMasterListActiveType);
  renderFacilityMasterListModal();
}

async function showFacilityMasterList(type) {
  if (!type || !facilityMasterListModalConfigs[type]) {
    renderFacilityMasterFacilities();
    return;
  }
  facilityActiveMasterType = type;
  facilityMasterListActiveType = type;
  const modal = document.getElementById('facility-master-list-modal');
  const body = document.getElementById('facility-master-list-body');
  if (!modal) return;
  if (body) body.innerHTML = '<tr><td class="facility-master-empty">読み込み中...</td></tr>';
  modal.classList.remove('hidden');
  await refreshFacilityMasterListModal();
}

function closeFacilityMasterListModal() {
  document.getElementById('facility-master-list-modal')?.classList.add('hidden');
  facilityMasterListActiveType = null;
  facilityMasterListRows = [];
}

function ensureFacilityMasterRowIsEditable(row) {
  const type = facilityMasterListActiveType;
  if (!type || type === 'self_pay' || !facilityMasterDefinitions[type]) return null;
  if (Number.isInteger(row.localIndex)) return row.localIndex;

  const config = facilityMasterListModalConfigs[type];
  const nameKey = config.columns.find(column => ['name', 'template'].includes(column.key))?.key || 'name';
  const name = String(row[nameKey] || '').trim();
  if (!name) return null;
  if (!facilityLocalMasters[type]) facilityLocalMasters[type] = [];
  facilityLocalMasters[type].push(facilityMasterModalRowToItem(type, row, facilityLocalMasters[type].length));
  saveFacilityLocalMasters();
  return facilityLocalMasters[type].length - 1;
}

function editFacilityMasterModalRow(index) {
  const row = facilityMasterListRows[index];
  if (!row) return;

  if (facilityMasterListActiveType === 'self_pay') {
    closeFacilityMasterListModal();
    facilityActiveMasterType = 'self_pay';
    facilityEditingMasterIndex = null;
    facilityEditingSelfPayId = row.id || null;
    facilityEditingSelfPayDraft = row;
    openFacilityMasterRegisterModal();
    return;
  }

  const editableIndex = ensureFacilityMasterRowIsEditable(row);
  if (editableIndex === null) return;
  facilityActiveMasterType = facilityMasterListActiveType;
  facilityEditingMasterIndex = editableIndex;
  openFacilityMasterRegisterModal();
}

async function copyFacilitySelfPayMasterItem(item) {
  const row = normalizeFacilitySelfPayMasterRow(item);
  if (!row.name && row.price <= 0) return false;
  const payload = {
    item_code: null,
    name: `${row.name || '自費項目'} コピー`,
    name_short: `${row.name || '自費項目'} コピー`.slice(0, 100),
    name_kana: row.kana || null,
    price: row.price,
    tax_rate: row.rawTaxRate,
    tax_amount: row.taxAmount === '' ? null : parseFacilitySelfPayAmount(row.taxAmount),
    category: row.category || '自費',
    start_date: normalizeFacilitySelfPayDateValue(row.start),
    end_date: normalizeFacilitySelfPayDateValue(row.end)
  };
  await RecordActionAPI.createSelfPayMaster(payload);
  return true;
}

async function copyFacilityMasterModalRow(index) {
  const row = facilityMasterListRows[index];
  const type = facilityMasterListActiveType;
  if (!row || !type) return;

  if (type === 'self_pay') {
    try {
      await copyFacilitySelfPayMasterItem(row);
      await refreshFacilityMasterListModal();
      await renderFacilitySelfPayMaster();
      showToast('自費マスタをコピーしました', 'success');
    } catch (error) {
      console.error('自費マスタをコピーできませんでした:', error);
      showToast('自費マスタをコピーできませんでした', 'error');
    }
    return;
  }

  if (!facilityMasterDefinitions[type]) return;
  const config = facilityMasterListModalConfigs[type];
  const nameKey = config.columns.find(column => ['name', 'template'].includes(column.key))?.key || 'name';
  const name = row[nameKey] || '';
  if (!name) return;
  const nextItem = {
    name: `${name} コピー`,
    detail: row.kana || row.status || '',
    name_kana: row.kana || '',
    status: row.status || '有効',
    effective_date: row.start || '',
    expiry_date: normalizeFacilityMasterDateValue(row.end || row.expires || ''),
    payload: {
      unit: row.unit,
      film: row.film,
      receiptCode: row.receiptCode,
      price: row.price
    }
  };
  try {
    if (typeof FacilityMasterAPI === 'undefined' || !FacilityMasterAPI.create) {
      throw new Error('施設マスタAPIが利用できません');
    }
    await FacilityMasterAPI.create(type, buildFacilityMasterApiPayload(type, nextItem, facilityLocalMasters[type]?.length || 0));
    const loaded = await refreshFacilityMasterTypeFromApi(type);
    if (!loaded) throw new Error('施設マスタを再取得できません');
  } catch (error) {
    console.error('マスタAPIコピーに失敗しました:', error);
    showToast(`${config.label}マスタをコピーできませんでした`, 'error');
    return;
  }
  saveFacilityLocalMasters();
  await refreshFacilityMasterListModal();
  showToast(`${config.label}マスタをコピーしました`, 'success');
}

function openFacilityMasterRegisterModal() {
  const modal = document.getElementById('facility-master-register-modal');
  if (!modal) return;

  const isSelfPay = facilityActiveMasterType === 'self_pay';
  const definition = facilityMasterDefinitions[facilityActiveMasterType];
  const isLocalMaster = Boolean(definition);
  const selfPayItem = isSelfPay ? getFacilityEditingSelfPayItem() : null;
  const dialog = modal.querySelector('.facility-master-register-dialog');
  if (dialog) dialog.dataset.masterType = facilityActiveMasterType;

  const title = document.getElementById('facility-master-register-title');
  const nameLabel = document.getElementById('facility-master-name-label');
  const detailRow = document.getElementById('facility-master-detail-row');
  const detailLabel = document.getElementById('facility-master-detail-label');
  const priceRow = document.getElementById('facility-master-price-row');
  const categoryRow = document.getElementById('facility-master-category-row');
  const nameInput = document.getElementById('facility-master-name');
  const detailInput = document.getElementById('facility-master-detail');
  const priceInput = document.getElementById('facility-master-price');
  const categoryInput = document.getElementById('facility-master-category');
  const extraFields = document.getElementById('facility-master-extra-fields');

  if (title) {
    title.textContent = isSelfPay
      ? facilityEditingSelfPayId ? '自費マスタ編集' : '自費マスタ登録'
      : isLocalMaster
        ? `${definition.label}マスタ${facilityEditingMasterIndex !== null ? '編集' : '登録'}`
        : '施設マスタ登録';
  }
  if (nameLabel) nameLabel.textContent = isSelfPay ? '名前' : isLocalMaster ? (definition.nameLabel || definition.columns[0]) : '施設名';
  detailRow?.classList.toggle('hidden', !isLocalMaster || Boolean(definition?.hideDetailInRegister));
  priceRow?.classList.add('hidden');
  categoryRow?.classList.add('hidden');
  if (detailLabel && isLocalMaster) detailLabel.textContent = definition.detailLabel || '補足';

  const editingItem = isLocalMaster && facilityEditingMasterIndex !== null
    ? facilityLocalMasters[facilityActiveMasterType]?.[facilityEditingMasterIndex]
    : null;
  if (nameInput) nameInput.value = isSelfPay ? selfPayItem?.name || '' : editingItem?.name || '';
  if (detailInput) detailInput.value = editingItem?.detail || definition?.detailDefault || '';
  if (priceInput) priceInput.value = '';
  if (categoryInput) categoryInput.value = isSelfPay ? selfPayItem?.category || '自費' : '';
  if (isSelfPay) {
    renderFacilitySelfPayExtraFields(selfPayItem || {});
  } else if (isLocalMaster) {
    renderFacilityMasterExtraFields(facilityActiveMasterType, editingItem || {});
  } else {
    if (extraFields) {
      extraFields.innerHTML = '';
      extraFields.classList.add('hidden');
    }
  }

  modal.classList.remove('hidden');
  const codeInput = modal.querySelector('[data-facility-master-field="code"]');
  if (facilityActiveMasterType === 'doctors' && facilityEditingMasterIndex === null && codeInput) {
    codeInput.focus();
  } else {
    nameInput?.focus();
  }
}

function closeFacilityMasterRegisterModal() {
  const modal = document.getElementById('facility-master-register-modal');
  modal?.classList.add('hidden');
  modal?.querySelector('.facility-master-register-dialog')?.removeAttribute('data-master-type');
  facilityEditingMasterIndex = null;
  facilityEditingSelfPayId = null;
  facilityEditingSelfPayDraft = null;
}

async function saveFacilityMasterRegistration() {
  const name = document.getElementById('facility-master-name')?.value.trim() || '';
  if (!name) {
    showToast('名称を入力してください', 'error');
    return;
  }

  if (facilityActiveMasterType === 'self_pay') {
    const payload = collectFacilitySelfPayMasterPayload(name);
    if (!payload.item_code) {
      showToast('コードを入力してください', 'error');
      return;
    }
    if (payload._priceBlank) {
      showToast('金額を入力してください', 'error');
      return;
    }
    if (payload._invalidDate) {
      showToast('日付は yyyy/mm/dd 形式で入力してください', 'error');
      return;
    }
    delete payload._priceBlank;
    delete payload._invalidDate;
    try {
      if (facilityEditingSelfPayId && RecordActionAPI.updateSelfPayMaster) {
        await RecordActionAPI.updateSelfPayMaster(facilityEditingSelfPayId, payload);
      } else {
        await RecordActionAPI.createSelfPayMaster(payload);
      }
      closeFacilityMasterRegisterModal();
      await renderFacilitySelfPayMaster();
      await refreshFacilityMasterListModal();
      showToast('自費マスタを保存しました', 'success');
    } catch (error) {
      console.error('自費マスタの登録に失敗しました:', error);
      showToast('自費マスタを登録できませんでした', 'error');
    }
    return;
  }

  const definition = facilityMasterDefinitions[facilityActiveMasterType];
  if (definition) {
    const existingItem = facilityEditingMasterIndex !== null
      ? facilityLocalMasters[facilityActiveMasterType]?.[facilityEditingMasterIndex]
      : null;
    const detail = definition.hideDetailInRegister
      ? (existingItem?.detail || definition.detailDefault || '')
      : (document.getElementById('facility-master-detail')?.value.trim() || definition.detailDefault || '');
    const nextItem = {
      ...(existingItem || {}),
      name,
      detail,
      status: existingItem?.status || '有効'
    };
    const nextItemWithExtra = collectFacilityMasterExtraFields(facilityActiveMasterType, nextItem);
    if (facilityActiveMasterType === 'doctors' && !nextItemWithExtra.code) {
      showToast('コードを入力してください', 'error');
      return;
    }
    if (!facilityLocalMasters[facilityActiveMasterType]) facilityLocalMasters[facilityActiveMasterType] = [];

    try {
      if (typeof FacilityMasterAPI === 'undefined' || !FacilityMasterAPI.create || !FacilityMasterAPI.update) {
        throw new Error('施設マスタAPIが利用できません');
      }
      if (existingItem?.id) {
        await FacilityMasterAPI.update(
          facilityActiveMasterType,
          existingItem.id,
          buildFacilityMasterApiPayload(facilityActiveMasterType, nextItemWithExtra, facilityEditingMasterIndex || 0)
        );
      } else {
        await FacilityMasterAPI.create(
          facilityActiveMasterType,
          buildFacilityMasterApiPayload(facilityActiveMasterType, nextItemWithExtra, 0)
        );
      }
      const loaded = await refreshFacilityMasterTypeFromApi(facilityActiveMasterType);
      if (!loaded) throw new Error('施設マスタを再取得できません');
    } catch (error) {
      console.error('マスタAPI保存に失敗しました:', error);
      showToast(`${definition.label}マスタを保存できませんでした`, 'error');
      return;
    }

    saveFacilityLocalMasters();
    closeFacilityMasterRegisterModal();
    renderFacilityLocalMaster(facilityActiveMasterType);
    await refreshFacilityMasterListModal();
    showToast(`${definition.label}マスタを保存しました`, 'success');
    return;
  }

  facilityMasterFacilities.unshift(name);
  closeFacilityMasterRegisterModal();
  renderFacilityMasterFacilities();
  await refreshFacilityMasterListModal();
  showToast('施設マスタを登録しました', 'success');
}

function editFacilityLocalMaster(index) {
  if (!facilityMasterDefinitions[facilityActiveMasterType]) return;
  facilityEditingMasterIndex = index;
  openFacilityMasterRegisterModal();
}

async function deleteFacilityLocalMaster(index) {
  const definition = facilityMasterDefinitions[facilityActiveMasterType];
  if (!definition) return;
  const item = facilityLocalMasters[facilityActiveMasterType]?.[index];
  if (!item) return;
  if (!item.id) {
    showToast(`${definition.label}マスタのIDを取得できません。再読み込みしてください`, 'error');
    return;
  }
  if (typeof FacilityMasterAPI === 'undefined' || !FacilityMasterAPI.delete) {
    showToast('施設マスタAPIが利用できません', 'error');
    return;
  }

  try {
    await FacilityMasterAPI.delete(facilityActiveMasterType, item.id);
    const loaded = await refreshFacilityMasterTypeFromApi(facilityActiveMasterType);
    if (!loaded) throw new Error('施設マスタを再取得できません');
  } catch (error) {
    console.error('マスタAPI削除に失敗しました:', error);
    showToast(`${definition.label}マスタから削除できませんでした`, 'error');
    return;
  }
  saveFacilityLocalMasters();
  renderFacilityLocalMaster(facilityActiveMasterType);
  await refreshFacilityMasterListModal();
  showToast(`${definition.label}マスタから削除しました`, 'success');
}

async function deleteFacilitySelfPayMaster(itemId) {
  if (!itemId) return;
  try {
    await RecordActionAPI.deleteSelfPayMaster(itemId);
    await renderFacilitySelfPayMaster();
    await refreshFacilityMasterListModal();
    if (document.querySelector('.action-tab.active')?.dataset.category === 'self_pay') {
      await loadSelfPayItems();
    }
    showToast('自費マスタから削除しました', 'success');
  } catch (error) {
    console.error('自費マスタの削除に失敗しました:', error);
    showToast('自費マスタを削除できませんでした', 'error');
  }
}

function editFacilitySelfPayMaster(itemId) {
  const item = facilitySelfPayMasterRows.find(row => String(row.id) === String(itemId));
  if (!item) return;
  facilityActiveMasterType = 'self_pay';
  facilityEditingMasterIndex = null;
  facilityEditingSelfPayId = item.id;
  facilityEditingSelfPayDraft = null;
  openFacilityMasterRegisterModal();
}

function parseFacilityMasterCsv(text) {
  return text
    .replace(/^\uFEFF/, '')
    .split(/\r?\n/)
    .map(line => line.trim())
    .filter(Boolean)
    .map(line => {
      const columns = [];
      let current = '';
      let quoted = false;
      for (let i = 0; i < line.length; i += 1) {
        const char = line[i];
        const next = line[i + 1];
        if (char === '"' && quoted && next === '"') {
          current += '"';
          i += 1;
        } else if (char === '"') {
          quoted = !quoted;
        } else if (char === ',' && !quoted) {
          columns.push(current.trim());
          current = '';
        } else {
          current += char;
        }
      }
      columns.push(current.trim());
      return columns;
    })
    .filter((columns, index) => index !== 0 || !/コード|名称|項目名|医師名|施設名/.test(columns[0] || ''));
}

function parseFacilitySelfPayCsvRow(columns) {
  const looksExpanded = columns.length >= 6;
  if (!looksExpanded) {
    return {
      item_code: null,
      name: columns[0] || '',
      name_kana: null,
      start_date: null,
      end_date: null,
      price: parseFacilitySelfPayAmount(columns[1] || 0),
      tax_rate: null,
      tax_amount: null,
      category: columns[2] || '自費'
    };
  }
  const taxRate = parseFacilitySelfPayTaxRate(columns[6]);
  const price = parseFacilitySelfPayAmount(columns[5] || 0);
  const calculatedTaxAmount = calculateFacilitySelfPayTaxAmount(price, taxRate);
  return {
    item_code: columns[0] || null,
    name: columns[1] || '',
    name_kana: columns[2] || null,
    start_date: normalizeFacilitySelfPayDateValue(columns[3]) || null,
    end_date: normalizeFacilitySelfPayDateValue(columns[4]) || null,
    price,
    tax_rate: taxRate,
    tax_amount: columns[7] ? parseFacilitySelfPayAmount(columns[7]) : (calculatedTaxAmount === '' ? null : calculatedTaxAmount),
    category: columns[8] || '自費'
  };
}

async function importFacilityMasterCsv(button) {
  const type = getFacilityMasterTypeFromControl(button);
  if (!type) return;
  const input = button.closest('tr')?.querySelector('input[type="file"]');
  const file = input?.files?.[0];
  if (!file) {
    showToast('CSVファイルを選択してください', 'error');
    return;
  }

  try {
    const rows = parseFacilityMasterCsv(await file.text());
    if (!rows.length) {
      showToast('取り込める行がありません', 'error');
      return;
    }

    if (type === 'self_pay') {
      for (const columns of rows) {
        const payload = parseFacilitySelfPayCsvRow(columns);
        if (payload.name && payload.price >= 0) {
          await RecordActionAPI.createSelfPayMaster(payload);
        }
      }
      await renderFacilitySelfPayMaster();
      await refreshFacilityMasterListModal();
      showToast('自費マスタを取り込みました', 'success');
      return;
    }

    const definition = facilityMasterDefinitions[type];
    const items = rows
      .map((columns, index) => ({
        name: columns[0] || '',
        detail: columns[1] || definition.detailDefault || '',
        name_kana: columns[2] || '',
        effective_date: columns[3] || '',
        expiry_date: columns[4] || '',
        sort_order: index
      }))
      .filter(item => item.name);
    try {
      if (typeof FacilityMasterAPI === 'undefined' || !FacilityMasterAPI.bulkImport) {
        throw new Error('施設マスタAPIが利用できません');
      }
      const imported = await FacilityMasterAPI.bulkImport(
        type,
        items.map((item, index) => buildFacilityMasterApiPayload(type, item, index)),
        true
      );
      facilityLocalMasters[type] = Array.isArray(imported)
        ? imported.map(normalizeFacilityMasterApiItem)
        : [];
      facilityMasterApiLoadedTypes.add(type);
    } catch (apiError) {
      console.error('マスタAPI取り込みに失敗しました:', apiError);
      showToast(`${definition.label}マスタを取り込めませんでした`, 'error');
      return;
    }
    saveFacilityLocalMasters();
    renderFacilityLocalMaster(type);
    await refreshFacilityMasterListModal();
    showToast(`${definition.label}マスタを取り込みました`, 'success');
  } catch (error) {
    console.error('CSV取り込みに失敗しました:', error);
    showToast('CSVを取り込めませんでした', 'error');
  }
}

function downloadFacilityMasterFormat(button) {
  const type = getFacilityMasterTypeFromControl(button);
  if (!type) return;
  const headers = type === 'self_pay'
    ? ['コード', '名前', 'カナ', '開始日', '終了日', '税込金額', '消費税率', '消費税額', 'カテゴリ']
    : (facilityMasterDefinitions[type]?.columns || ['名称', '補足']);
  const csv = `${headers.join(',')}\n`;
  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = `${type}_format.csv`;
  document.body.appendChild(link);
  link.click();
  link.remove();
  URL.revokeObjectURL(url);
}

function applyFacilityAccidentSettings() {
  setTextById('accident-code-display', facilityAccidentSettings.laborInsuranceCode);
  const workersDisplay = document.getElementById('accident-method-workers-display');
  const healthDisplay = document.getElementById('accident-method-health-display');
  if (workersDisplay) workersDisplay.checked = facilityAccidentSettings.autoLiabilityCalculation === 'workers_comp';
  if (healthDisplay) healthDisplay.checked = facilityAccidentSettings.autoLiabilityCalculation === 'health_fee';
}

async function renderFacilityAccidentSettings() {
  applyFacilityAccidentSettings();
  if (typeof FacilityAPI === 'undefined' || typeof FacilityAPI.getAccidentSettings !== 'function') return;
  try {
    const settings = await FacilityAPI.getAccidentSettings();
    facilityAccidentSettings.laborInsuranceCode = firstNonEmptyString(
      settings?.labor_insurance_code,
      facilityAccidentSettings.laborInsuranceCode
    );
    facilityAccidentSettings.autoLiabilityCalculation = ['workers_comp', 'health_fee'].includes(settings?.auto_liability_calculation)
      ? settings.auto_liability_calculation
      : 'workers_comp';
    applyFacilityAccidentSettings();
  } catch (error) {
    console.error('労災・自賠責設定取得エラー:', error);
    showToast('労災・自賠責設定を取得できませんでした', 'error');
  }
}

function openAccidentEditModal() {
  const modal = document.getElementById('accident-edit-modal');
  if (!modal) return;

  document.getElementById('accident-code-input').value = facilityAccidentSettings.laborInsuranceCode;
  const selectedMethod = document.querySelector(
    `input[name="accident-method-edit"][value="${facilityAccidentSettings.autoLiabilityCalculation}"]`
  );
  if (selectedMethod) selectedMethod.checked = true;
  modal.classList.remove('hidden');
  document.getElementById('accident-code-input')?.focus();
}

function closeAccidentEditModal() {
  document.getElementById('accident-edit-modal')?.classList.add('hidden');
}

async function saveAccidentSettings() {
  const code = document.getElementById('accident-code-input')?.value.trim() || '';
  const autoLiabilityCalculation = document.querySelector('input[name="accident-method-edit"]:checked')?.value || 'workers_comp';
  if (!code) {
    showToast('労災指定医療機関コードを入力してください', 'error');
    return;
  }

  const saveButton = document.getElementById('accident-edit-save');
  try {
    if (saveButton) saveButton.disabled = true;
    const saved = await FacilityAPI.updateAccidentSettings({
      labor_insurance_code: code,
      auto_liability_calculation: autoLiabilityCalculation
    });
    facilityAccidentSettings.laborInsuranceCode = firstNonEmptyString(saved?.labor_insurance_code, code);
    facilityAccidentSettings.autoLiabilityCalculation = ['workers_comp', 'health_fee'].includes(saved?.auto_liability_calculation)
      ? saved.auto_liability_calculation
      : autoLiabilityCalculation;
    closeAccidentEditModal();
    applyFacilityAccidentSettings();
    showToast('労災・自賠責設定を保存しました', 'success');
  } catch (error) {
    console.error('労災・自賠責設定保存エラー:', error);
    showToast(error?.message || '労災・自賠責設定を保存できませんでした', 'error');
  } finally {
    if (saveButton) saveButton.disabled = false;
  }
}

