  document.getElementById('btn-data-submit-edit')?.addEventListener('click', openFacilityDataSubmissionEditModal);
  document.getElementById('data-submit-edit-close')?.addEventListener('click', closeFacilityDataSubmissionEditModal);
  document.getElementById('data-submit-edit-save')?.addEventListener('click', saveFacilityDataSubmissionSettings);
