  document.getElementById('login-log-prev-date')?.addEventListener('click', () => changeFacilityLoginLogDate(-1));
  document.getElementById('login-log-next-date')?.addEventListener('click', () => changeFacilityLoginLogDate(1));
  document.getElementById('audit-log-prev-date')?.addEventListener('click', () => changeFacilityAuditLogDate(-1));
