function initReception() {
  initReceiptClaimModal();

  // ロゴクリックで当日のTOPページへ
  const logoBtn = document.getElementById('btn-go-today');
  if (logoBtn) {
    logoBtn.addEventListener('click', (e) => {
      e.preventDefault();
      // 今日の日付をセット
      const today = new Date();
      document.getElementById('reception-date').value = getLocalDateString(today);
      updateDateDisplay(today);
      loadReceptions();
    });
  }

  // 患者検索画面（ヘッダーの虫眼鏡アイコンから開く）
  const headerSearchBtn = document.getElementById('btn-header-search');
  const searchModal = document.getElementById('patient-search-modal');
  const searchClose = document.getElementById('search-modal-close');
  const searchInput = document.getElementById('search-query');

  if (headerSearchBtn && searchModal) {
    headerSearchBtn.addEventListener('click', () => {
      searchModal.classList.remove('hidden');
      if (searchInput) searchInput.value = '';
      searchInput?.focus();
      // 初期表示時は全患者を表示
      executePatientSearchNew('');
    });
  }

  const receptionEditHistoryBtn = document.getElementById('btn-reception-edit-history');
  if (receptionEditHistoryBtn) {
    receptionEditHistoryBtn.addEventListener('click', () => {
      if (!isM3FeatureEnabled('receptionEditHistory')) return;
      openReceptionEditHistoryModal();
    });
  }

  document.getElementById('btn-rme-daily-report')?.addEventListener('click', () => {
    openRmeDailyReport();
  });

  if (searchClose) {
    searchClose.addEventListener('click', () => {
      searchModal.classList.add('hidden');
    });
  }

  if (searchModal) {
    searchModal.addEventListener('click', (e) => {
      if (e.target === searchModal) {
        searchModal.classList.add('hidden');
      }
    });
  }

  // 検索入力でリアルタイム検索
  if (searchInput) {
    let searchTimeout;
    searchInput.addEventListener('input', (e) => {
      clearTimeout(searchTimeout);
      searchTimeout = setTimeout(() => {
        executePatientSearchNew(e.target.value);
      }, 300);
    });

    searchInput.addEventListener('keypress', (e) => {
      if (e.key === 'Enter') {
        executePatientSearchNew(e.target.value);
      }
    });
  }

  // Escキーで閉じる
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && searchModal && !searchModal.classList.contains('hidden')) {
      searchModal.classList.add('hidden');
    }
  });

  // ユーザードロップダウン
  const dropdown = document.getElementById('user-dropdown');
  const dropdownBtn = document.getElementById('user-dropdown-btn');

  if (dropdownBtn && dropdown) {
    dropdownBtn.addEventListener('click', (e) => {
      e.preventDefault();
      e.stopPropagation();
      dropdown.classList.toggle('open');
    });

    // 外側クリックで閉じる
    document.addEventListener('click', event => {
      if (dropdown.contains(event.target)) return;
      dropdown.classList.remove('open');
    });
  }

  // ドロップダウンメニュー項目
  const menuLogout = document.getElementById('menu-logout');
  if (menuLogout) {
    menuLogout.addEventListener('click', async (e) => {
      e.preventDefault();
      if (!(await confirmDiscardKarteChangesIfNeeded())) return;
      if (!(await confirmLogout())) return;
      await Storage.clearCurrentUser();
      showLoginScreen();
    });
  }

  const menuPassword = document.getElementById('menu-password');
  if (menuPassword) {
    menuPassword.addEventListener('click', (e) => {
      e.preventDefault();
      showToast('パスワード変更機能は準備中です', 'info');
    });
  }

  const menuFacility = document.getElementById('menu-facility');
  if (menuFacility) {
    menuFacility.addEventListener('click', (e) => {
      e.preventDefault();
      dropdown?.classList.remove('open');
      showFacilityScreen('medical');
    });
  }

  const menuReservationAdmin = document.getElementById('menu-reservation-admin');
  if (menuReservationAdmin) {
    menuReservationAdmin.addEventListener('click', (e) => {
      e.preventDefault();
      dropdown?.classList.remove('open');
      openReservationManagement();
    });
  }

  // 戻るボタン
  const backBtn = document.getElementById('btn-back-to-list');
  if (backBtn) {
    backBtn.addEventListener('click', () => returnToTodayReceptionScreen());
  }

  // 日付ナビゲーション
  const prevBtn = document.getElementById('btn-prev-date');
  const nextBtn = document.getElementById('btn-next-date');
  const dateInput = document.getElementById('reception-date');

  if (prevBtn && dateInput) {
    prevBtn.addEventListener('click', () => {
      const date = parseLocalDate(dateInput.value);
      date.setDate(date.getDate() - 1);
      dateInput.value = getLocalDateString(date);
      updateDateDisplay(date);
      loadReceptions();
    });
  }

  if (nextBtn && dateInput) {
    nextBtn.addEventListener('click', () => {
      const date = parseLocalDate(dateInput.value);
      date.setDate(date.getDate() + 1);
      dateInput.value = getLocalDateString(date);
      updateDateDisplay(date);
      loadReceptions();
    });
  }

  if (dateInput) {
    dateInput.addEventListener('change', () => {
      const date = parseLocalDate(dateInput.value);
      updateDateDisplay(date);
      loadReceptions();
    });
  }

  // 初期表示で日付を更新
  const today = new Date();
  updateDateDisplay(today);
}

// 日付表示を更新
function updateDateDisplay(date) {
  const display = document.getElementById('toolbar-date-display');
  if (display) {
    const days = ['日', '月', '火', '水', '木', '金', '土'];
    const y = date.getFullYear();
    const m = String(date.getMonth() + 1).padStart(2, '0');
    const d = String(date.getDate()).padStart(2, '0');
    const dayName = days[date.getDay()];
    display.textContent = `${y}/${m}/${d} (${dayName})`;
  }
}

function getLocalDateString(date = new Date()) {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
}

function parseLocalDate(value) {
  if (!value) return new Date();
  const [year, month, day] = value.split('-').map(Number);
  if (!year || !month || !day) return new Date(value);
  return new Date(year, month - 1, day);
}

function getDisplayedReceptionDateValue() {
  const dateInput = document.getElementById('reception-date');
  return normalizeKarteDateValue(dateInput?.value) || getLocalDateString();
}

function getPreferredKarteDateForNewContext() {
  const receptionScreen = document.getElementById('reception-screen');
  if (receptionScreen && !receptionScreen.classList.contains('hidden')) {
    return getDisplayedReceptionDateValue();
  }

  return normalizeKarteDateValue(currentKarteDate)
    || normalizeKarteDateValue(document.getElementById('karte-date')?.value)
    || getLocalDateString();
}

function getLocalTimeString(date = new Date()) {
  const h = String(date.getHours()).padStart(2, '0');
  const m = String(date.getMinutes()).padStart(2, '0');
  return `${h}:${m}`;
}

function getFacilityReceptionInitialStatus() {
  const status = m3FeatureSettings?.receptionInitialStatus;
  return ['waiting', 'exam_waiting'].includes(status) ? status : DEFAULT_M3_FEATURE_SETTINGS.receptionInitialStatus;
}

async function createTodayReception(patientId, receptionDate = getDisplayedReceptionDateValue()) {
  const now = new Date();
  return ReceptionAPI.create({
    patient_id: patientId,
    reception_date: normalizeKarteDateValue(receptionDate) || getLocalDateString(now),
    reception_time: getLocalTimeString(now),
    status: getFacilityReceptionInitialStatus()
  });
}

function getCreatedPatientSnapshot(response, fallback = {}) {
  const snapshot = response?.patient || response?.data?.patient || response?.data || response || {};
  return snapshot && typeof snapshot === 'object' && !Array.isArray(snapshot)
    ? { ...fallback, ...snapshot }
    : { ...fallback };
}

function getCreatedReceptionSnapshot(response) {
  const snapshot = getReceptionSnapshotFromApiResponse(response) || response;
  return snapshot && typeof snapshot === 'object' && !Array.isArray(snapshot) ? snapshot : null;
}

function findPostCheckinReception(patientId, createdReception = null, receptionDate = getDisplayedReceptionDateValue()) {
  const createdSnapshot = getCreatedReceptionSnapshot(createdReception);
  const createdReceptionId = createdSnapshot?.id || createdReception?.id || '';
  if (createdReceptionId) {
    const cached = receptionsCache.find(item => String(item.id) === String(createdReceptionId));
    if (cached) return cached;
    upsertReceptionCache({
      ...createdSnapshot,
      id: createdReceptionId,
      patient_id: createdSnapshot?.patient_id || patientId
    });
    return receptionsCache.find(item => String(item.id) === String(createdReceptionId)) || null;
  }

  const targetDate = normalizeKarteDateValue(createdSnapshot?.reception_date || receptionDate);
  const matches = receptionsCache.filter(item => {
    if (String(item.patient_id || '') !== String(patientId || '')) return false;
    if (!targetDate) return true;
    return normalizeKarteDateValue(item.reception_date) === targetDate;
  });
  return matches[0] || receptionsCache.find(item => String(item.patient_id || '') === String(patientId || '')) || null;
}

async function openPostCheckinReceptionRegistration(patientId, createdReception = null) {
  const reception = findPostCheckinReception(patientId, createdReception);
  if (!reception?.id) {
    showToast('受付は完了しましたが、受付登録画面を開けませんでした。受付一覧から保険欄を開いてください', 'info');
    return false;
  }
  await openReceptionEditModal(reception.id, { title: '受付登録' });
  return true;
}

async function returnToTodayReceptionScreen() {
  const today = getLocalDateString();
  const user = Storage.getCurrentUser();
  if (user) {
    await showReceptionScreen(user, { date: today });
  } else {
    const receptionDateInput = document.getElementById('reception-date');
    if (receptionDateInput) receptionDateInput.value = today;
    updateDateDisplay(parseLocalDate(today));
    await loadReceptions();
  }
}

let patientSearchRequestId = 0;

function formatPatientLastReceptionDate(patient) {
  return formatDateSlash(
    patient?.last_reception_date
    || patient?.lastReceptionDate
    || patient?.last_visit_date
    || patient?.last_visit
  );
}

// 患者検索実行（新M3スタイル）
async function executePatientSearchNew(query) {
  const tbody = document.getElementById('search-results-body');
  const noResults = document.getElementById('search-no-results');
  if (!tbody || !noResults) return;

  const searchTerm = String(query || '').trim().toLowerCase();
  const requestId = ++patientSearchRequestId;

  tbody.innerHTML = `
    <tr>
      <td colspan="9" class="search-loading-cell">検索中...</td>
    </tr>
  `;
  noResults.classList.add('hidden');

  const apiPatients = await loadPatients(searchTerm, 100, 0);
  if (requestId !== patientSearchRequestId) return;
  const patients = apiPatients.length ? apiPatients : Storage.getPatients();

  // 検索フィルター（API形式とローカル形式の両方に対応）
  const results = patients.filter(p => {
    if (!searchTerm) return true; // 空欄なら全件表示

    const patientNo = String(p.patient_no || p.id || '').toLowerCase();
    const patientName = String(p.name || '').toLowerCase();
    const patientKana = String(p.name_kana || p.kana || '').toLowerCase();
    const birthDate = p.birth_date || p.birth;

    // 患者番号、名前、フリガナ、電話番号で検索
    if (patientNo.includes(searchTerm)) return true;
    if (patientName.includes(searchTerm)) return true;
    if (patientKana.includes(searchTerm)) return true;
    if (String(p.phone1 || '').includes(searchTerm)) return true;

    // 生年月日検索
    if (birthDate && birthDate.includes(searchTerm)) return true;
    const birthFormatted = formatBirthWithEra(birthDate);
    if (birthFormatted.toLowerCase().includes(searchTerm)) return true;

    return false;
  });

  if (results.length === 0) {
    tbody.innerHTML = '';
    noResults.classList.remove('hidden');
    noResults.innerHTML = `
      <i class="fas fa-search"></i>
      <p>${searchTerm ? '該当する患者が見つかりませんでした' : '検索キーワードを入力してください'}</p>
    `;
    return;
  }

  noResults.classList.add('hidden');

  tbody.innerHTML = results.map(p => {
    // API形式かローカル形式かを判定
    const patientId = p.id;
    const patientNo = p.patient_no || p.id;
    const patientKana = p.name_kana || p.kana || '';
    const birthDate = p.birth_date || p.birth;
    const lastReceptionDate = formatPatientLastReceptionDate(p);

    const age = calculateAge(birthDate);
    const birthDisplay = formatBirthWithEra(birthDate);
    const genderCode = normalizePatientGenderCode(firstNonEmptyString(p.gender, p.sex, p.patient_gender, p.patientGender));
    const genderText = formatPatientGenderLabel(genderCode, { shortLabel: true }) || '-';

    return `
      <tr data-patient-id="${patientId}">
        <td class="col-patient-no">${escapeHtml(patientNo)}</td>
        <td class="col-kana">${escapeHtml(patientKana)}</td>
        <td class="col-name">${escapeHtml(p.name)}</td>
        <td class="col-gender"><span class="gender-badge ${genderCode}">${genderText}</span></td>
        <td class="col-birth">${birthDisplay}</td>
        <td class="col-age">${age}</td>
        <td class="col-last">${escapeHtml(lastReceptionDate)}</td>
        <td class="col-memo">${escapeHtml(p.memo || '')}</td>
        <td class="col-actions">
          <div class="search-action-buttons">
            <button class="search-action-btn" onclick="viewPatientFromSearch('${patientId}')">表示</button>
            <button class="search-action-btn" onclick="editPatientFromSearch('${patientId}')"><i class="fas fa-pen"></i></button>
            <button class="search-action-btn primary" onclick="checkinFromSearch('${patientId}')">受付</button>
            <button class="search-action-btn" onclick="reserveFromSearch('${patientId}')">予約</button>
          </div>
        </td>
      </tr>
    `;
  }).join('');
}

// 生年月日を和暦付きでフォーマット
function formatBirthWithEra(birth) {
  if (!birth) return '-';
  const date = new Date(birth);
  if (Number.isNaN(date.getTime())) return String(birth);
  const year = date.getFullYear();
  const month = date.getMonth() + 1;
  const day = date.getDate();
  const era = getJapaneseEra(year);
  return `${year}/${month}/${day}（${era}）`;
}

// 検索結果から患者を表示
async function viewPatientFromSearch(patientId) {
  if (!(await confirmDiscardKarteChangesIfNeeded())) return;
  const patients = Storage.getPatients();
  const patient = patients.find(p => p.id === patientId);
  if (patient) {
    const targetKarteDate = getPreferredKarteDateForNewContext();
    document.getElementById('patient-search-modal').classList.add('hidden');
    const user = Storage.getCurrentUser();
    showMainScreen(user, { karteDate: targetKarteDate, patientOverview: true });
    document.getElementById('patient-selector').value = patientId;
    currentReception = null;
    selectPatient(patient);
    setKarteNoRecordState(targetKarteDate, { patientOverview: true });
  }
}

// 検索結果から患者情報を編集
function editPatientFromSearch(patientId) {
  // 検索モーダルを閉じる
  document.getElementById('patient-search-modal').classList.add('hidden');
  // 編集モーダルを開く
  editPatient(patientId);
}

// 検索結果から受付
async function checkinFromSearch(patientId) {
  if (!(await confirmDiscardKarteChangesIfNeeded())) return;

  const patients = Storage.getPatients();
  const patient = patients.find(p => p.id === patientId);
  if (!patient) return;

  try {
    showLoading();

    await createTodayReception(patientId);

    // モーダルを閉じる
    document.getElementById('patient-search-modal').classList.add('hidden');

    await returnToTodayReceptionScreen();

    hideLoading();
    showToast(`${patient.name}さんの受付を完了しました`, 'success');
  } catch (error) {
    hideLoading();
    showToast('受付登録に失敗しました: ' + error.message, 'error');
  }
}

