function closeReceptionEditHistoryDetail() {
  document.getElementById('reception-edit-history-detail-modal')?.classList.add('hidden');
}

async function openReceptionEditHistoryDetail(receptionId) {
  if (!receptionId) return;
  const modal = ensureReceptionEditHistoryDetailModal();
  const summaryEl = modal.querySelector('#reception-edit-history-detail-summary');
  const tbody = modal.querySelector('#reception-edit-history-detail-body');
  modal.classList.remove('hidden');
  if (summaryEl) summaryEl.innerHTML = '<div class="reception-edit-history-empty">読み込み中です</div>';
  if (tbody) tbody.innerHTML = '<tr><td colspan="5" class="reception-edit-history-empty">読み込み中です</td></tr>';

  try {
    const result = await ReceptionAPI.getEditHistory(receptionId);
    renderReceptionEditHistoryDetail(result);
  } catch (error) {
    console.error('受付詳細履歴取得エラー:', error);
    if (summaryEl) {
      summaryEl.innerHTML = `<div class="reception-edit-history-empty error">${escapeHtml(error.message || '受付詳細履歴を取得できませんでした')}</div>`;
    }
    if (tbody) tbody.innerHTML = '<tr><td colspan="5" class="reception-edit-history-empty error">受付詳細履歴を取得できませんでした</td></tr>';
  }
}

function renderReceptionEditHistoryDetail(result) {
  const modal = ensureReceptionEditHistoryDetailModal();
  const reception = result?.reception || {};
  const history = Array.isArray(result?.history) ? result.history : [];
  const summaryEl = modal.querySelector('#reception-edit-history-detail-summary');
  const tbody = modal.querySelector('#reception-edit-history-detail-body');
  const status = getReceptionHistoryStatusStyle(reception.status);

  if (summaryEl) {
    summaryEl.innerHTML = `
      <table class="reception-edit-history-summary-table">
        <tbody>
          <tr>
            <th>番号</th>
            <td>${escapeHtml(reception.patient_no || '')}</td>
            <th>患者氏名</th>
            <td>${escapeHtml(reception.patient_name || '')}</td>
            <th>年齢</th>
            <td>${escapeHtml(calculateAge(reception.birth_date))}</td>
          </tr>
          <tr>
            <th>ステータス</th>
            <td><span class="reception-edit-history-status" style="background:${status.bg}; color:${status.text};">${escapeHtml(getReceptionHistoryStatusLabel(reception.status))}</span></td>
            <th>保険</th>
            <td>${escapeHtml(getReceptionHistoryInsuranceText(reception))}</td>
            <th>診療科</th>
            <td>${escapeHtml(reception.department || '')}</td>
          </tr>
          <tr>
            <th>医師</th>
            <td>${escapeHtml(reception.doctor_name || '')}</td>
            <th>作成日時</th>
            <td>${escapeHtml(formatReceptionHistoryDateTime(reception.created_at))}</td>
            <th>最終編集</th>
            <td>${escapeHtml(reception.last_editor_name || '')} ${escapeHtml(formatReceptionHistoryDateTime(reception.last_edited_at))}</td>
          </tr>
        </tbody>
      </table>
    `;
  }

  if (!tbody) return;
  if (!history.length) {
    tbody.innerHTML = '<tr><td colspan="5" class="reception-edit-history-empty">詳細履歴がありません</td></tr>';
    return;
  }

  tbody.innerHTML = history.map(log => {
    const changes = Array.isArray(log.changes) ? log.changes : [];
    const fields = changes.map(change => escapeHtml(change.label || '')).join('<br>') || escapeHtml(log.description || '');
    const before = changes.map(change => escapeHtml(change.before || '') || '&nbsp;').join('<br>');
    const after = changes.map(change => escapeHtml(change.after || '') || '&nbsp;').join('<br>');
    return `
      <tr>
        <td>${escapeHtml(formatReceptionHistoryDateTime(log.edited_at))}</td>
        <td>${escapeHtml(log.editor_name || '')}</td>
        <td>
          <span>${escapeHtml(log.action_label || '')}</span>
          <span class="reception-edit-history-sub">${fields}</span>
        </td>
        <td>${before || ''}</td>
        <td>${after || ''}</td>
      </tr>
    `;
  }).join('');
}

// 受付一覧を表示
function renderReceptionTable() {
  const tbody = document.getElementById('patient-table-body');
  const noPatients = document.getElementById('no-patients');
  const countEl = document.getElementById('patient-count');
  const filteredReceptions = getFilteredReceptions();

  if (receptionsCache.length === 0 || filteredReceptions.length === 0) {
    tbody.innerHTML = '';
    noPatients.classList.add('show');
    const noPatientsText = noPatients.querySelector('p');
    if (noPatientsText) {
      noPatientsText.textContent = receptionsCache.length === 0
        ? '本日の受付患者はいません'
        : '条件に一致する受付患者はいません';
    }
    const activeCount = receptionsCache.filter(r => r.status !== 'cancelled').length;
    countEl.textContent = `0 / ${activeCount}件`;
    applyReceptionColumnVisibility();
    return;
  }

  noPatients.classList.remove('show');

  tbody.innerHTML = filteredReceptions.map((r, index) => {
    const status = statusMap[r.status] || { label: r.status, bg: '#f3f4f6', text: '#374151' };
    const rowNum = String(filteredReceptions.length - index).padStart(3, '0');
    const firstVisitMeta = getReceptionFirstVisitMeta(r.first_visit);
    const insuranceLabel = getReceptionInsuranceLabel(r);
    const lastVisitLabel = getReceptionLastVisitLabel(r);
    const patientMemo = r.patient_memo || '';
    const patientMemoTitle = patientMemo ? patientMemo : '患者メモ';
    const receptionMemo = r.reception_memo || '';
    const receptionMemoTitle = receptionMemo ? receptionMemo : '受付メモ';
    const genderCode = normalizePatientGenderCode(firstNonEmptyString(r.gender, r.patient_gender, r.sex, r.patientGender));
    const patientNameGenderClass = genderCode ? ` patient-name-gender-${genderCode}` : '';

    // 時間をHH:MM形式に
    const formatTime = (t) => t ? t.substring(0, 5) : '';

    return `
      <tr data-patient-id="${r.patient_id}" data-reception-id="${r.id}">
        <td class="col-num">${rowNum}</td>
        <td class="col-appointment">${formatTime(r.appointment_time)}</td>
        <td class="col-time">${formatTime(r.reception_time)}</td>
        <td class="col-status">
          <button class="status-btn" style="background:${status.bg}; color:${status.text};" onclick="showStatusMenu(event, '${r.id}')">
            ${status.label} ▼
          </button>
        </td>
        <td class="col-patient-id">
          <button type="button" class="reception-cell-link reception-open-karte" data-action="open-karte">
            ${escapeHtml(r.patient_no || '')}
          </button>
        </td>
        <td class="col-patient-name">
          <button type="button" class="patient-name-cell reception-name-link reception-open-karte${patientNameGenderClass}" data-action="open-karte">
            <span class="patient-kana">${escapeHtml(r.name_kana || '')}</span>
            <span class="patient-kanji">${escapeHtml(r.patient_name || '')}</span>
          </button>
        </td>
        <td class="col-birth-date">${formatDateSlash(r.birth_date)}</td>
        <td class="col-age">${calculateAge(r.birth_date)}</td>
        <td class="col-insurance">
          <button type="button" class="reception-edit-cell" data-action="edit-reception" title="受付を編集">
            <span>${escapeHtml(insuranceLabel)}</span>
            <i class="fas fa-pen reception-edit-indicator" aria-hidden="true"></i>
          </button>
        </td>
        <td class="col-department">
          <button type="button" class="reception-edit-cell" data-action="edit-reception" title="受付を編集">
            <span>${escapeHtml(r.department || '')}</span>
            <i class="fas fa-pen reception-edit-indicator" aria-hidden="true"></i>
          </button>
        </td>
        <td class="col-doctor">
          <button type="button" class="reception-edit-cell" data-action="edit-reception" title="受付を編集">
            <span>${escapeHtml(r.doctor_name || '')}</span>
            <i class="fas fa-pen reception-edit-indicator" aria-hidden="true"></i>
          </button>
        </td>
        <td class="col-last-visit">${escapeHtml(lastVisitLabel)}</td>
        <td class="col-patient-memo">
          <button type="button"
                  class="patient-memo-cell patient-memo-open ${patientMemo ? 'active' : 'empty'}"
                  data-action="open-patient-memo"
                  title="${escapeHtmlAttribute(patientMemoTitle)}">
            <span>${escapeHtml(patientMemo)}</span>
            <i class="fas fa-pen reception-edit-indicator" aria-hidden="true"></i>
          </button>
        </td>
        <td class="col-reception-memo">
          <button type="button"
                  class="reception-memo-cell ${receptionMemo ? 'active' : ''}"
                  data-action="open-reception-memo"
                  title="${escapeHtml(receptionMemoTitle)}">
            <span>${escapeHtml(receptionMemo)}</span>
            <i class="fas fa-pen reception-edit-indicator" aria-hidden="true"></i>
          </button>
        </td>
        <td class="col-action-icon col-first-visit">
          ${firstVisitMeta.label ? `
            <span class="first-visit-indicator ${firstVisitMeta.className}"
                  title="${escapeHtml(firstVisitMeta.title)}">
              ${escapeHtml(firstVisitMeta.label)}
            </span>
          ` : ''}
        </td>
        <td class="col-action-icon col-terminal"></td>
        <td class="col-action-icon col-payment"></td>
        <td class="col-action-icon">${r.status === 'in_exam' || r.status === 'payment_waiting' ? '<span class="action-label">会計</span>' : ''}</td>
        <td class="col-action-icon"></td>
        <td class="col-action-icon"></td>
        <td class="col-action-icon"></td>
        <td class="col-action-icon"></td>
      </tr>
    `;
  }).join('');

  // キャンセル済みを除いた件数を表示
  const activeCount = receptionsCache.filter(r => r.status !== 'cancelled').length;
  countEl.textContent = `${filteredReceptions.length} / ${activeCount}件`;
  applyReceptionColumnVisibility();

  tbody.querySelectorAll('[data-action="open-karte"]').forEach(button => {
    button.addEventListener('click', event => {
      event.stopPropagation();
      const row = button.closest('tr');
      if (!row) return;
      openPatientKarte(row.dataset.patientId, row.dataset.receptionId);
    });
  });

  tbody.querySelectorAll('[data-action="edit-reception"]').forEach(button => {
    button.addEventListener('click', event => {
      event.stopPropagation();
      const row = button.closest('tr');
      if (!row) return;
      openReceptionEditModal(row.dataset.receptionId);
    });
  });

  tbody.querySelectorAll('[data-action="open-patient-memo"]').forEach(button => {
    button.addEventListener('click', event => {
      event.stopPropagation();
      const row = button.closest('tr');
      if (!row) return;
      openPatientMemoModal(row.dataset.receptionId);
    });
  });

  tbody.querySelectorAll('[data-action="open-reception-memo"]').forEach(button => {
    button.addEventListener('click', event => {
      event.stopPropagation();
      const row = button.closest('tr');
      if (!row) return;
      openReceptionMemoModal(row.dataset.receptionId);
    });
  });
}

const RME_DAILY_REPORT_FILTERS = [
  { id: 'all', label: '全て' },
  { id: 'ckd', label: 'CKD疑い' },
  { id: 'opioid_constipation', label: 'オピオイド誘発性便秘症' },
  { id: 'mash', label: 'MASH/旧NASH' },
  { id: 'dementia', label: 'アルツハイマー型認知症' },
  { id: 'anemia', label: '貧血症状・血液検査値異常' },
  { id: 'thyroid_eye', label: '甲状腺眼症' },
  { id: 'covid_pregnancy', label: 'COVID19（妊婦）' },
  { id: 'high_tg', label: '高TG血症' },
  { id: 'hpp', label: 'HPP疑い' }
];

const rmeDailyReportState = {
  date: '',
  filter: 'all',
  rows: [],
  sourceRows: []
};

function getRmeDailyReportStorageKey(dateValue) {
  return `digimaster.rmeDailyReport.dismissed.${dateValue || getLocalDateString()}`;
}

function getRmeDismissedIds(dateValue = rmeDailyReportState.date) {
  try {
    const raw = localStorage.getItem(getRmeDailyReportStorageKey(dateValue));
    const parsed = raw ? JSON.parse(raw) : [];
    return new Set(Array.isArray(parsed) ? parsed.map(String) : []);
  } catch {
    return new Set();
  }
}

function saveRmeDismissedIds(ids, dateValue = rmeDailyReportState.date) {
  localStorage.setItem(getRmeDailyReportStorageKey(dateValue), JSON.stringify([...ids]));
}

function getRmeDailyReportDateLabel(dateValue) {
  const date = parseLocalDate(dateValue);
  const days = ['日', '月', '火', '水', '木', '金', '土'];
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  return `${y}/${m}/${d} (${days[date.getDay()]})`;
}

function getRmeAgeOnDate(birthDate, dateValue) {
  const ageParts = calculateAgeParts(birthDate, parseLocalDate(dateValue));
  return ageParts ? ageParts.years : null;
}

function getRmePatientNameHtml(row) {
  const genderCode = normalizePatientGenderCode(firstNonEmptyString(row.gender, row.patient_gender, row.sex, row.patientGender));
  const className = genderCode === 'male'
    ? 'male'
    : (genderCode === 'female' ? 'female' : '');
  return `
    <span class="rme-patient-kana">${escapeHtml(firstNonEmptyString(row.patientKana, row.name_kana, row.patient_name_kana, row.kana))}</span>
    <span class="rme-patient-name ${className}">${escapeHtml(firstNonEmptyString(row.patientName, row.patient_name, row.name, row.full_name))}</span>
  `;
}

function getRmePatientSearchText(row = {}) {
  return [
    row.patient_memo,
    row.reception_memo,
    row.memo,
    row.summary,
    row.insurance_type_name,
    row.insurer_name,
    row.department,
    row.doctor_name,
    row.patient_name,
    row.name
  ].filter(Boolean).join(' ');
}

function buildRmeAlertRow(row, category, notification, summary, dateValue) {
  const storedPatient = Storage.getPatients().find(patient => (
    String(patient.id || '') === String(firstNonEmptyString(row.patient_id, row.patientId, ''))
    || String(patient.patient_no || patient.patientNo || '') === String(firstNonEmptyString(row.patient_no, row.patientNo, row.number, ''))
  ));
  const patientId = firstNonEmptyString(row.patient_id, row.patientId, row.id);
  const receptionId = firstNonEmptyString(row.id, row.reception_id);
  const patientNo = firstNonEmptyString(row.patient_no, row.patientNo, row.number, storedPatient?.patient_no, storedPatient?.patientNo, patientId);
  const birthDate = firstNonEmptyString(row.birth_date, row.birthDate, row.birth, storedPatient?.birth_date, storedPatient?.birthDate, storedPatient?.birth);
  return {
    id: [dateValue, category, patientId, receptionId, notification].map(part => String(part || '')).join(':'),
    category,
    notificationId: RME_CATEGORY_MANAGEMENT_IDS[category] || '',
    patientId,
    receptionId,
    patientNo,
    patientName: firstNonEmptyString(row.patient_name, row.name, row.full_name, storedPatient?.name, storedPatient?.patient_name),
    patientKana: firstNonEmptyString(row.name_kana, row.patient_name_kana, row.kana, storedPatient?.name_kana, storedPatient?.kana),
    birthDate,
    gender: firstNonEmptyString(row.gender, row.patient_gender, row.sex, row.patientGender, storedPatient?.gender, storedPatient?.sex),
    age: getRmeAgeOnDate(birthDate, dateValue),
    notification,
    summary,
    source: row
  };
}

function buildRmeAlertRowsFromReception(row, dateValue) {
  const text = getRmePatientSearchText(row);
  const age = getRmeAgeOnDate(firstNonEmptyString(row.birth_date, row.birthDate, row.birth), dateValue);
  const genderCode = normalizePatientGenderCode(firstNonEmptyString(row.gender, row.patient_gender, row.sex, row.patientGender));
  const rows = [];
  const has = pattern => pattern.test(text);

  if ((age != null && age >= 75) || has(/CKD|慢性腎|腎機能|腎不全|高血圧|糖尿/i)) {
    rows.push(buildRmeAlertRow(
      row,
      'ckd',
      'CKD高リスク患者への情報',
      'CKD高リスク患者への腎機能に関する検査をご検討ください。',
      dateValue
    ));
  }

  if ((age != null && age >= 75) || has(/認知症|アルツハイマー|BPSD|幻覚|妄想|焦燥|不安|抑うつ/)) {
    rows.push(buildRmeAlertRow(
      row,
      'dementia',
      '認知症に伴うBPSDに関する疾患情報',
      '認知症に伴う易刺激性・焦燥性興奮、幻覚・妄想、不安・抑うつが疑われます。必要に応じて詳細をご確認ください。',
      dateValue
    ));
  }

  if ((age != null && age >= 40 && has(/糖尿|肥満|肝|脂肪肝|脂質|中性脂肪|TG/i)) || has(/MASH|NASH|線維化|FIB-?4/i)) {
    rows.push(buildRmeAlertRow(
      row,
      'mash',
      '代謝機能障害関連脂肪性肝炎（MASH/旧NASH）疑い患者に関する通知',
      'FIB-4 Indexなどで肝臓の線維化進行が疑われる場合は、追加検査や専門医への紹介をご検討ください。',
      dateValue
    ));
  }

  if (has(/貧血|Hb|ヘモグロビン|鉄欠乏|血液検査/)) {
    rows.push(buildRmeAlertRow(
      row,
      'anemia',
      '貧血症状・血液検査値異常に関する通知',
      '貧血症状または血液検査値異常がある場合は、原因精査や再検査をご検討ください。',
      dateValue
    ));
  }

  if (has(/甲状腺|バセドウ|眼球突出|複視|眼症/)) {
    rows.push(buildRmeAlertRow(
      row,
      'thyroid_eye',
      '甲状腺眼症に関する疾患情報',
      '甲状腺疾患に伴う眼症状がある場合は、眼科または専門医への紹介をご検討ください。',
      dateValue
    ));
  }

  if (genderCode === 'female' && has(/妊娠|妊婦|COVID|コロナ/i)) {
    rows.push(buildRmeAlertRow(
      row,
      'covid_pregnancy',
      'COVID19（妊婦）に関する情報',
      '妊婦のCOVID19関連症状または感染歴がある場合は、重症化リスクやフォロー方針をご確認ください。',
      dateValue
    ));
  }

  if (has(/高TG|高中性脂肪|中性脂肪|トリグリセライド|脂質異常/i)) {
    rows.push(buildRmeAlertRow(
      row,
      'high_tg',
      '高TG血症に関する疾患情報',
      '中性脂肪高値がある場合は、脂質異常症治療中の値や治療方針をご確認ください。',
      dateValue
    ));
  }

  if (has(/HPP|低ALP|低アルカリホスファターゼ|骨折|歯の早期脱落/)) {
    rows.push(buildRmeAlertRow(
      row,
      'hpp',
      'HPP疑い患者への疾患情報',
      'ALP持続低値や骨・歯の症状がある場合は、低ホスファターゼ症の鑑別をご検討ください。',
      dateValue
    ));
  }

  if (has(/オピオイド|麻薬|便秘|酸化マグネシウム|ナルデメジン/)) {
    rows.push(buildRmeAlertRow(
      row,
      'opioid_constipation',
      'オピオイド誘発性便秘症に関する情報',
      'オピオイド使用中の便秘症状がある場合は、排便状況と治療方針をご確認ください。',
      dateValue
    ));
  }

  return rows.slice(0, 2);
}

function getRmeFallbackRowsFromCurrentPatient(dateValue) {
  if (!currentPatient) return [];
  return [{
    ...currentPatient,
    id: currentReception?.id || currentPatient.id,
    patient_id: currentPatient.id,
    patient_no: currentPatient.patient_no,
    patient_name: currentPatient.name,
    name_kana: currentPatient.name_kana || currentPatient.kana,
    birth_date: currentPatient.birth_date || currentPatient.birth,
    gender: currentPatient.gender,
    patient_memo: currentPatient.memo,
    reception_memo: currentReception?.reception_memo,
    department: currentReception?.department,
    doctor_name: currentReception?.doctor_name
  }];
}

async function fetchRmeDailyReportSourceRows(dateValue) {
  const currentDate = getDisplayedReceptionDateValue();
  if (dateValue === currentDate && receptionsCache.length) return receptionsCache;
  if (typeof ReceptionAPI !== 'undefined' && ReceptionAPI?.list) {
    try {
      const result = await ReceptionAPI.list(dateValue);
      const rows = Array.isArray(result?.data) ? result.data : [];
      if (rows.length) return rows;
    } catch (error) {
      console.error('RME日次レポート受付取得エラー:', error);
    }
  }
  if (dateValue === currentDate) return receptionsCache;
  return getRmeFallbackRowsFromCurrentPatient(dateValue);
}

function getDefaultRmeDailyReportDate() {
  if (typeof isKarteScreenVisible === 'function' && isKarteScreenVisible()) {
    return normalizeKarteDateValue(currentKarteDate)
      || normalizeKarteDateValue(document.getElementById('karte-date')?.value)
      || getDisplayedReceptionDateValue();
  }
  return getDisplayedReceptionDateValue();
}

function getRmeVisibleRows() {
  const dismissed = getRmeDismissedIds();
  return rmeDailyReportState.rows.filter(row => {
    if (dismissed.has(String(row.id))) return false;
    if (!isRmeAlertEnabledByFacility(row)) return false;
    return rmeDailyReportState.filter === 'all' || row.category === rmeDailyReportState.filter;
  });
}

function isRmeAlertEnabledByFacility(row = {}) {
  const notificationId = row.notificationId || RME_CATEGORY_MANAGEMENT_IDS[row.category];
  if (!notificationId) return true;
  const setting = facilityRmeNotificationSettings.find(notification => notification.notificationId === notificationId);
  return setting?.management !== 'all_patients_disabled';
}

function renderRmeDailyReportChips() {
  const holder = document.getElementById('rme-daily-filter-chips');
  if (!holder) return;
  const dismissed = getRmeDismissedIds();
  const activeRows = rmeDailyReportState.rows.filter(row => (
    !dismissed.has(String(row.id)) && isRmeAlertEnabledByFacility(row)
  ));
  const counts = activeRows.reduce((map, row) => {
    map[row.category] = (map[row.category] || 0) + 1;
    return map;
  }, {});

  holder.innerHTML = RME_DAILY_REPORT_FILTERS.map(filter => {
    const count = filter.id === 'all' ? activeRows.length : (counts[filter.id] || 0);
    return `
      <button type="button" class="rme-filter-chip ${rmeDailyReportState.filter === filter.id ? 'active' : ''}" data-rme-filter="${escapeHtmlAttribute(filter.id)}">
        <span>${escapeHtml(filter.label)}</span>
        ${count ? `<span class="rme-filter-count">${escapeHtml(String(count))}</span>` : ''}
      </button>
    `;
  }).join('');
}

function renderRmeDailyReportRows() {
  const tbody = document.getElementById('rme-daily-report-body');
  if (!tbody) return;
  const rows = getRmeVisibleRows();
  if (!rows.length) {
    tbody.innerHTML = '<tr><td colspan="6" class="rme-empty">表示対象のRME通知はありません。</td></tr>';
    return;
  }

  tbody.innerHTML = rows.map(row => `
    <tr>
      <td class="rme-patient-no">${escapeHtml(row.patientNo)}</td>
      <td class="rme-patient-cell">${getRmePatientNameHtml(row)}</td>
      <td class="rme-age-cell">${row.age == null ? '-' : escapeHtml(String(row.age))}</td>
      <td>${escapeHtml(row.notification)}</td>
      <td>${escapeHtml(row.summary)}</td>
      <td class="rme-actions">
        <button type="button" class="rme-row-btn" data-rme-dismiss="${escapeHtmlAttribute(row.id)}" title="一覧から削除">
          <i class="fas fa-trash-alt"></i>
        </button>
        <button type="button" class="rme-row-btn" data-rme-open="${escapeHtmlAttribute(row.id)}" title="カルテを開く">
          <i class="fas fa-external-link-alt"></i>
        </button>
      </td>
    </tr>
  `).join('');
}

function renderRmeDailyReport() {
  setTextById('rme-daily-report-date', getRmeDailyReportDateLabel(rmeDailyReportState.date));
  renderRmeDailyReportChips();
  renderRmeDailyReportRows();
}

function ensureRmeDailyReportModal() {
  let modal = document.getElementById('rme-daily-report-modal');
  if (modal) return modal;

  modal = document.createElement('div');
  modal.id = 'rme-daily-report-modal';
  modal.className = 'modal hidden rme-daily-report-modal';
  modal.innerHTML = `
    <div class="modal-content rme-daily-report-dialog" role="dialog" aria-modal="true" aria-labelledby="rme-daily-report-title">
      <div class="modal-header rme-daily-report-header">
        <h3 id="rme-daily-report-title">RMEデイリーレポート</h3>
        <button type="button" class="modal-close" id="rme-daily-report-close">&times;</button>
      </div>
      <div class="rme-daily-toolbar">
        <button type="button" class="rme-date-nav" id="rme-daily-prev" title="前日"><i class="fas fa-chevron-left"></i></button>
        <span class="rme-date-display" id="rme-daily-report-date"></span>
        <button type="button" class="rme-date-nav" id="rme-daily-next" title="翌日"><i class="fas fa-chevron-right"></i></button>
      </div>
      <div class="rme-daily-body">
        <div class="rme-dashboard-banner" id="rme-dashboard-banner">
          <span>CKD診断率ダッシュボードが追加されました。</span>
          <button type="button" class="btn btn-primary btn-sm" id="rme-dashboard-open">ダッシュボードを開く</button>
          <button type="button" class="rme-banner-close" id="rme-banner-close" title="閉じる">&times;</button>
        </div>
        <div class="rme-filter-chips" id="rme-daily-filter-chips"></div>
        <div class="rme-table-wrap">
          <table class="rme-daily-table">
            <thead>
              <tr>
                <th>患者番号</th>
                <th>患者氏名</th>
                <th>年齢</th>
                <th>RME通知</th>
                <th>通知概要</th>
                <th></th>
              </tr>
            </thead>
            <tbody id="rme-daily-report-body">
              <tr><td colspan="6" class="rme-empty">読み込み中...</td></tr>
            </tbody>
          </table>
        </div>
      </div>
      <div class="rme-daily-footer">
        <span>DigiMaster内の受付・患者情報から候補通知を作成しています。</span>
        <button type="button" class="rme-help-link" id="rme-help-link">RMEとは?</button>
      </div>
    </div>
  `;
  document.body.appendChild(modal);

  modal.querySelector('#rme-daily-report-close')?.addEventListener('click', closeRmeDailyReport);
  modal.addEventListener('click', event => {
    if (event.target === modal) closeRmeDailyReport();
  });
  modal.querySelector('#rme-daily-prev')?.addEventListener('click', () => shiftRmeDailyReportDate(-1));
  modal.querySelector('#rme-daily-next')?.addEventListener('click', () => shiftRmeDailyReportDate(1));
  modal.querySelector('#rme-banner-close')?.addEventListener('click', () => {
    modal.querySelector('#rme-dashboard-banner')?.classList.add('hidden');
  });
  modal.querySelector('#rme-dashboard-open')?.addEventListener('click', () => {
    showToast('CKD診断率ダッシュボードは準備中です', 'info');
  });
  modal.querySelector('#rme-help-link')?.addEventListener('click', () => {
    showToast('RMEは、患者情報から診療上の確認候補を出す院内リスク通知として扱っています', 'info');
  });
  modal.querySelector('#rme-daily-filter-chips')?.addEventListener('click', event => {
    const button = event.target.closest('[data-rme-filter]');
    if (!button) return;
    rmeDailyReportState.filter = button.dataset.rmeFilter || 'all';
    renderRmeDailyReport();
  });
  modal.querySelector('#rme-daily-report-body')?.addEventListener('click', event => {
    const dismissButton = event.target.closest('[data-rme-dismiss]');
    if (dismissButton) {
      const dismissed = getRmeDismissedIds();
      dismissed.add(String(dismissButton.dataset.rmeDismiss));
      saveRmeDismissedIds(dismissed);
      renderRmeDailyReport();
      return;
    }

    const openButton = event.target.closest('[data-rme-open]');
    if (!openButton) return;
    const row = rmeDailyReportState.rows.find(item => String(item.id) === String(openButton.dataset.rmeOpen));
    if (!row?.patientId) return;
    closeRmeDailyReport();
    openPatientKarte(row.patientId, row.receptionId);
  });

  return modal;
}

async function loadRmeDailyReport(dateValue = getDisplayedReceptionDateValue()) {
  const modal = ensureRmeDailyReportModal();
  rmeDailyReportState.date = normalizeKarteDateValue(dateValue) || getLocalDateString();
  rmeDailyReportState.sourceRows = [];
  rmeDailyReportState.rows = [];
  renderRmeDailyReport();
  const tbody = modal.querySelector('#rme-daily-report-body');
  if (tbody) tbody.innerHTML = '<tr><td colspan="6" class="rme-empty">読み込み中...</td></tr>';

  const sourceRows = await fetchRmeDailyReportSourceRows(rmeDailyReportState.date);
  rmeDailyReportState.sourceRows = sourceRows;
  rmeDailyReportState.rows = sourceRows
    .flatMap(row => buildRmeAlertRowsFromReception(row, rmeDailyReportState.date));
  renderRmeDailyReport();
}

async function openRmeDailyReport(dateValue = getDefaultRmeDailyReportDate()) {
  const modal = ensureRmeDailyReportModal();
  modal.classList.remove('hidden');
  try {
    await loadFacilityRmeNotificationSettings({ force: true, silent: true });
  } catch {
    // 通知設定を取得できない場合は、既定の全件有効でレポートを表示する。
  }
  await loadRmeDailyReport(dateValue);
}

function closeRmeDailyReport() {
  document.getElementById('rme-daily-report-modal')?.classList.add('hidden');
}

async function shiftRmeDailyReportDate(days) {
  const base = parseLocalDate(rmeDailyReportState.date || getDisplayedReceptionDateValue());
  base.setDate(base.getDate() + days);
  await loadRmeDailyReport(getLocalDateString(base));
}

// ステータス変更メニューを表示
function showStatusMenu(event, receptionId) {
  event.stopPropagation();

  // 既存メニューを削除
  const existingMenu = document.querySelector('.status-menu');
  if (existingMenu) existingMenu.remove();

  const menu = document.createElement('div');
  menu.className = 'status-menu';

  // ステータスオプションを生成
  const statusOptions = Object.entries(statusMap).map(([key, val]) => {
    return `
      <div class="status-menu-item" data-status="${key}">
        <span class="status-menu-dot" style="background:${val.color || val.bg};"></span>
        <span>${val.label}</span>
      </div>
    `;
  }).join('');

  menu.innerHTML = statusOptions;

  // ボタンの位置を基準に配置
  const btn = event.currentTarget;
  const rect = btn.getBoundingClientRect();
  menu.style.position = 'fixed';
  menu.style.left = rect.left + 'px';
  menu.style.top = (rect.bottom + 2) + 'px';

  document.body.appendChild(menu);

  menu.querySelectorAll('.status-menu-item').forEach(item => {
    item.addEventListener('click', async () => {
      const newStatus = item.dataset.status;
      await updateReceptionStatus(receptionId, newStatus);
      menu.remove();
    });
  });

  // 外側クリックで閉じる
  setTimeout(() => {
    document.addEventListener('click', function closeMenu(e) {
      if (!menu.contains(e.target)) {
        menu.remove();
        document.removeEventListener('click', closeMenu);
      }
    });
  }, 0);
}

function showReceptionCancelError(message = '作成済みのカルテがあるため受付取消はできません。\nカルテを削除してから受付取消してください。') {
  return showAppConfirm({ title: '受付取消エラー', message, confirmText: '閉じる', cancelText: null });
}

function hasUnsavedReceptionKarte(receptionId) {
  const reception = receptionsCache.find(row => String(row.id) === String(receptionId));
  if (!reception?.patient_id) return false;
  const date = getKarteDateFromReception(reception);
  const key = getPatientDraftKey(reception.patient_id, date, receptionId);
  const draft = patientBillingData[key];
  return Boolean(draft && !draft.deleted && !draft.recordId);
}

// 受付ステータスを更新
async function updateReceptionStatus(receptionId, status) {
  try {
    if (status === 'cancelled' && hasUnsavedReceptionKarte(receptionId)) {
      await showReceptionCancelError('作成中のカルテがあるため受付取消はできません。\nカルテを削除してから受付取消してください。');
      return;
    }
    await ReceptionAPI.update(receptionId, { status: status });
    await loadReceptions(); // 一覧を再取得
    showToast('ステータスを更新しました', 'success');
  } catch (error) {
    if (status === 'cancelled' && error.detail?.code === 'RECEPTION_HAS_MEDICAL_RECORD') {
      await showReceptionCancelError(error.message);
      return;
    }
    showToast('ステータス更新に失敗しました: ' + error.message, 'error');
  }
}

// 患者のカルテを開く
async function openPatientKarte(patientId, receptionId = null) {
  if (!(await confirmDiscardKarteChangesIfNeeded())) return;

  const patients = Storage.getPatients();
  let patient = patients.find(p => p.id === patientId);

  if (!patient) {
    // キャッシュになければAPIから取得
    try {
      showLoading();
      patient = await PatientAPI.get(patientId);
      hideLoading();
    } catch (error) {
      hideLoading();
      showToast('患者情報の取得に失敗しました', 'error');
      return;
    }
  }

  // 受付データを保存
  if (receptionId) {
    currentReception = receptionsCache.find(r => r.id === receptionId) || null;
  } else {
    currentReception = null;
  }
  const targetKarteDate = getKarteDateFromReception(currentReception)
    || getPreferredKarteDateForNewContext();

  const user = Storage.getCurrentUser();
  showMainScreen(user, { karteDate: targetKarteDate });
  document.getElementById('patient-selector').value = patientId;
  setKarteDate(targetKarteDate);
  selectPatient(patient, { skipSaveCurrentBilling: true, skipLoadBilling: true });
  if (currentPatient?.id) {
    await loadPatientInsurances(currentPatient.id);
  }
  syncCurrentReceptionContextFromPatientData();
  const targetReceptionId = getCurrentReceptionRecordId();

  if (patient.patient_no) {
    await initNewKarteForDate(targetKarteDate, true, { receptionId: targetReceptionId });
  } else {
    currentRecordId = null;
    const key = getPatientDraftKey(patient.id, targetKarteDate, targetReceptionId);
    if (patientBillingData[key]?.deleted) {
      setKarteNoRecordState(targetKarteDate, { preserveDraft: true });
    } else {
      resetKarteEditor();
      loadPatientBilling(patient.id, targetKarteDate, { receptionId: targetReceptionId });
    }
  }
}

