function initTabs() {
  // 患者情報タブ
  document.querySelectorAll('.tab-container .tab').forEach(tab => {
    tab.addEventListener('click', () => {
      const tabId = tab.dataset.tab;

      // 同じコンテナ内のタブをリセット
      tab.closest('.tab-container').querySelectorAll('.tab').forEach(t => t.classList.remove('active'));
      tab.classList.add('active');

      // タブコンテンツ切り替え
      document.querySelectorAll('.tab-pane').forEach(pane => pane.classList.remove('active'));
      document.getElementById(tabId)?.classList.add('active');
    });
  });

  // 算定メニュータブ
  document.querySelectorAll('.menu-tab').forEach(tab => {
    tab.addEventListener('click', () => {
      document.querySelectorAll('.menu-tab').forEach(t => t.classList.remove('active'));
      tab.classList.add('active');
      // TODO: メニューアイテムの切り替え
    });
  });

  // M3風 患者情報ゾーンタブ切り替え
  initPatientZoneTabs();
}

// M3風 患者情報ゾーンタブ切り替え
function initPatientZoneTabs() {
  const tabsWrapper = document.querySelector('.m3-header-zone-patient .m3-panel-tabs-wrapper');
  if (!tabsWrapper) return;

  // タブとコンテンツのマッピング
  const tabMapping = {
    '患者情報': 'patient-info-content',
    '保険等': 'insurance-content',
    '問診': 'interview-content',
    '副作用薬等': 'allergy-content',
    'バイタル': 'vital-content',
    '検査結果': 'labresult-content',
    'PHR': 'phr-content',
    '診療履歴': 'history-content',
    '投薬履歴': 'medication-history-content',
    'ファイル': 'file-content',
    'サマリー': 'summary-content',
    '傷病名': 'disease-content',
    '定期': 'periodic-content',
    'オン資等': 'online-qualification-content'
  };

  // すべてのタブコンテンツを取得
  const allContents = document.querySelectorAll('.m3-panel-left .m3-tab-content');

  tabsWrapper.querySelectorAll('.m3-panel-tab').forEach(tab => {
    tab.addEventListener('click', () => {
      const tabText = tab.textContent.trim();

      // 全タブからactiveを削除
      tabsWrapper.querySelectorAll('.m3-panel-tab').forEach(t => t.classList.remove('active'));
      // クリックしたタブをactive
      tab.classList.add('active');

      // 全コンテンツを非表示
      allContents.forEach(c => c.style.display = 'none');

      // 対応するコンテンツを表示
      const contentId = tabMapping[tabText];
      if (contentId) {
        const content = document.getElementById(contentId);
        if (content) {
          content.style.display = 'flex';
        }
        if (contentId === 'insurance-content' && currentPatient) {
          loadPatientInsurances(currentPatient.id);
        }
        if (contentId === 'interview-content' && currentPatient?.patient_no) {
          loadPatientQuestionnaireResponses(currentPatient.id);
        }
        if (contentId === 'allergy-content' && currentPatient) {
          renderClinicalProfilePanel(currentPatient.id);
        }
        if (contentId === 'vital-content' && currentPatient) {
          renderPatientVitals(currentPatient.id);
        }
        if (contentId === 'disease-content' && currentPatient) {
          loadPatientDiagnoses(currentPatient.id);
        }
        if (contentId === 'medication-history-content' && currentPatient) {
          renderPatientMedicationHistory(currentPatient.id);
        }
        if (contentId === 'file-content') {
          loadPatientFiles(currentPatient?.id);
        }
        if (contentId === 'phr-content') {
          renderPatientPhrPanel(currentPatient?.id);
        }
        if (contentId === 'summary-content') {
          renderPatientSummaryPanel(currentPatient?.id);
        }
        if (contentId === 'periodic-content') {
          renderPatientPeriodicPanel(currentPatient?.id);
        }
        if (contentId === 'online-qualification-content') {
          renderPatientOnlineQualificationPanel(currentPatient?.id);
        }
      } else {
        // 未実装タブは診療履歴を表示してトースト
        const historyContent = document.getElementById('history-content');
        if (historyContent) {
          historyContent.style.display = 'flex';
        }
        showToast(`「${tabText}」タブは準備中です`, 'info');
      }
    });
  });
}

