function initPatientSelector() {
  const selector = document.getElementById('patient-selector');

  selector.addEventListener('change', async () => {
    const patientId = selector.value;
    if (patientId) {
      const previousPatientId = currentPatient?.id || '';
      if (!(await confirmDiscardKarteChangesIfNeeded())) {
        selector.value = previousPatientId;
        return;
      }
      const patients = Storage.getPatients();
      const patient = patients.find(p => p.id === patientId);
      if (patient) {
        const targetKarteDate = getPreferredKarteDateForNewContext();
        currentReception = null;
        setKarteDate(targetKarteDate);
        selectPatient(patient);
        await initNewKarteForDate(targetKarteDate, true);
      }
    } else {
      clearPatientInfo();
    }
  });
}

function updatePatientSelector() {
  const selector = document.getElementById('patient-selector');
  if (!selector) return;
  const patients = Storage.getPatients();

  selector.innerHTML = '<option value="">患者を選択</option>';
  patients.forEach(p => {
    const option = document.createElement('option');
    // API形式: id がUUID、patient_no が患者番号
    // ローカル形式: id が患者番号
    option.value = p.id;
    const displayNo = p.patient_no || p.id;
    option.textContent = `${displayNo} - ${p.name}`;
    selector.appendChild(option);
  });
}

function selectPatient(patient, options = {}) {
  const previousPatientId = currentPatient?.id || '';
  const nextPatientId = patient?.id || '';
  if (options.resetSetTreeExpansion !== false && String(previousPatientId) !== String(nextPatientId)) {
    resetSetTreeExpansionState();
  }

  // API形式かローカル形式かを判定して適切な関数を呼び出す
  if (patient.patient_no) {
    selectPatientFromAPI(patient, options);
  } else {
    selectPatientLocal(patient, options);
  }
}

// API形式の患者データを選択
// ひらがなをカタカナに変換
function toKatakana(str) {
  if (!str) return '';
  return str.replace(/[\u3041-\u3096]/g, ch =>
    String.fromCharCode(ch.charCodeAt(0) + 0x60)
  );
}

function setTextById(id, value) {
  const element = document.getElementById(id);
  if (element) {
    element.textContent = value || '';
  }
}

function formatJapaneseBirthDate(birthDate) {
  if (!birthDate) return '-';
  const date = new Date(birthDate);
  if (Number.isNaN(date.getTime())) return birthDate;

  const year = date.getFullYear();
  const month = date.getMonth() + 1;
  const day = date.getDate();
  const eras = [
    { name: '令和', start: 2019 },
    { name: '平成', start: 1989 },
    { name: '昭和', start: 1926 },
    { name: '大正', start: 1912 },
    { name: '明治', start: 1868 }
  ];
  const era = eras.find(item => year >= item.start);
  const eraText = era ? `${era.name}${year - era.start + 1}年` : '';

  return eraText ? `${year}年(${eraText})${month}月${day}日` : `${year}年${month}月${day}日`;
}

function formatPatientDetailAddress(patient) {
  if (!patient) return '';
  const explicitPostalCode = firstNonEmptyString(
    patient.postal_code,
    patient.postalCode,
    patient.zip_code,
    patient.zipCode
  ).replace(/^〒\s*/, '').trim();
  const rawAddress = firstNonEmptyString(
    patient.address,
    [patient.prefecture, patient.city, patient.address1, patient.address2].filter(Boolean).join(''),
    formatAddress(patient)
  );
  const inlinePostalMatch = String(rawAddress || '').match(/^〒?\s*(\d{3}-?\d{4})\s*/);
  const postalCode = explicitPostalCode || (inlinePostalMatch ? inlinePostalMatch[1] : '');
  const address = String(rawAddress || '')
    .replace(/^〒?\s*\d{3}-?\d{4}\s*/, '')
    .replace(/[\s　]+/g, '')
    .trim();
  return [postalCode, address].filter(Boolean).join(' ');
}

function formatPatientPhones(patient) {
  if (!patient) return '';
  return [patient.phone1, patient.phone2, patient.phone].filter(Boolean).join(' ');
}

function updatePatientDetailPanel(patient) {
  if (!patient) {
    [
      'patient-detail-kana',
      'patient-detail-name',
      'patient-detail-gender',
      'patient-detail-birth',
      'patient-detail-age',
      'patient-detail-address',
      'patient-detail-phone',
      'patient-detail-facility',
      'patient-detail-memo'
    ].forEach(id => setTextById(id, id === 'patient-detail-name' ? '-' : ''));
    return;
  }

  const birthDate = patient.birth_date || patient.birth;
  const ageDisplay = formatAgeForKarte(birthDate);

  setTextById('patient-detail-kana', toKatakana(patient.name_kana || patient.kana || ''));
  setTextById('patient-detail-name', patient.name || '-');
  setTextById('patient-detail-gender', formatPatientGenderLabel(patient) || '-');
  setTextById('patient-detail-birth', formatJapaneseBirthDate(birthDate));
  setTextById('patient-detail-age', ageDisplay);
  setTextById('patient-detail-address', formatPatientDetailAddress(patient));
  setTextById('patient-detail-phone', formatPatientPhones(patient));
  setTextById('patient-detail-facility', patient.facility || patient.facility_name || '');
  setTextById('patient-detail-memo', patient.memo || '');
}

function selectPatientFromAPI(patient, options = {}) {
  currentPatient = patient;

  // ヘッダー更新
  document.getElementById('header-patient-name').textContent = patient.name;
  document.getElementById('header-patient-id').textContent = `ID: ${patient.patient_no}`;
  document.getElementById('header-patient-kana').textContent = toKatakana(patient.name_kana || '');
  document.getElementById('header-patient-age').textContent = formatAgeForKarte(patient.birth_date);

  const genderBadge = document.getElementById('header-patient-gender');
  const genderCode = normalizePatientGenderCode(firstNonEmptyString(patient.gender, patient.sex, patient.patient_gender, patient.patientGender));
  genderBadge.textContent = formatPatientGenderLabel(genderCode, { shortLabel: true }) || '-';
  genderBadge.className = `patient-gender-badge ${genderCode}`.trim();
  updatePatientDetailPanel(patient);
  updateKarteHeaderContext();
  clearClinicalSidebarData();
  loadPatientInsurances(patient.id);
  loadPatientDiagnoses(patient.id);
  loadPatientFiles(patient.id);
  loadPatientQuestionnaireResponses(patient.id);
  loadPatientClinicalProfile(patient.id).then(() => {
    if (String(currentPatient?.id || '') === String(patient.id || '')) {
      checkPrescriptionsRealtime();
    }
  });

  // 新しい患者の算定データを読み込み
  const dateInput = document.getElementById('karte-date');
  const date = dateInput?.value || getLocalDateString();
  if (!options.skipLoadBilling && !document.getElementById('main-screen')?.classList.contains('patient-overview')) {
    loadPatientBilling(patient.id, date);
  }

  // 診療履歴更新
  renderPatientHistoryFromAPI(patient.id);
  refreshClinicalProfileIfVisible(patient.id);
  refreshMedicationHistoryIfVisible(patient.id);
  refreshVitalsIfVisible(patient.id);
  refreshM3AuxiliaryPanelsIfVisible(patient.id);
}

// ローカル形式の患者データを選択（後方互換性）
