function ensureInsuranceHistoryModal() {
  let modal = document.getElementById('insurance-history-modal');
  if (modal) return modal;

  modal = document.createElement('div');
  modal.id = 'insurance-history-modal';
  modal.className = 'modal hidden insurance-history-modal';
  modal.innerHTML = `
    <div class="modal-content insurance-history-dialog" role="dialog" aria-modal="true" aria-labelledby="insurance-history-title">
      <div class="modal-header">
        <h3 id="insurance-history-title">保険更新履歴</h3>
        <button type="button" class="modal-close" id="insurance-history-close" title="閉じる">&times;</button>
      </div>
      <div class="insurance-history-table-wrap">
        <table class="insurance-history-table">
          <thead>
            <tr>
              <th class="insurance-history-time">時間</th>
              <th class="insurance-history-action">種別</th>
              <th class="insurance-history-user">更新者</th>
              <th class="insurance-history-info">保険情報</th>
              <th class="insurance-history-reduction">減免区分</th>
              <th class="insurance-history-category">適用区分</th>
              <th class="insurance-history-date">資格取得日</th>
              <th class="insurance-history-holder">被保険者名</th>
            </tr>
          </thead>
          <tbody id="insurance-history-body">
            <tr class="insurance-history-message"><td colspan="8">更新履歴を読み込んでいます。</td></tr>
          </tbody>
        </table>
      </div>
    </div>
  `;
  modal.querySelector('#insurance-history-close')?.addEventListener('click', closeInsuranceHistoryModal);
  modal.addEventListener('click', event => {
    if (event.target === modal) closeInsuranceHistoryModal();
  });
  document.body.appendChild(modal);
  return modal;
}

function closeInsuranceHistoryModal() {
  document.getElementById('insurance-history-modal')?.classList.add('hidden');
}

function formatInsuranceHistoryTimestamp(value) {
  if (!value) return '';
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return String(value);
  const pad = number => String(number).padStart(2, '0');
  return `${date.getFullYear()}/${pad(date.getMonth() + 1)}/${pad(date.getDate())} ${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}`;
}

function getInsuranceHistoryTypeLabel(data = {}) {
  const labels = {
    social: '社保',
    national: '国保',
    elderly: '後期',
    union: '組合',
    mutual: '共済',
    self_pay: '自費'
  };
  return labels[data.insurance_type] || data.insurance_type_name || data.insurance_type || '';
}

function getInsuranceHistoryInfo(data = {}) {
  const relationship = data.relationship === 'main' ? '本人' : (data.relationship === 'family' ? '家族' : '');
  const memberNumber = [data.symbol, [data.number, data.branch_number].filter(Boolean).join('-')]
    .filter(Boolean)
    .join('・');
  const relationshipAndNumber = [relationship, memberNumber].filter(Boolean).join('・');
  const burden = Number.isFinite(Number(data.burden_ratio)) ? `${Number(data.burden_ratio)}%` : '';
  return [
    getInsuranceHistoryTypeLabel(data),
    data.insurer_number,
    relationshipAndNumber,
    burden,
    data.limit_category
  ].filter(value => value !== null && value !== undefined && String(value).trim() !== '').join(' ');
}

function getInsuranceHistoryReductionLabel(data = {}) {
  const labels = { reduction: '減額', exemption: '免除', other: 'その他' };
  return labels[data.reduction_type] || data.reduction_type || 'なし';
}

function renderInsuranceHistoryRows(history = []) {
  const body = document.getElementById('insurance-history-body');
  if (!body) return;
  if (!history.length) {
    body.innerHTML = '<tr class="insurance-history-message"><td colspan="8">更新履歴はありません。</td></tr>';
    return;
  }

  body.innerHTML = history.map(item => {
    const data = item.insurance_data || {};
    const reason = item.change_reason ? ` title="${escapeHtmlAttribute(item.change_reason)}"` : '';
    return `
      <tr>
        <td>${escapeHtml(formatInsuranceHistoryTimestamp(item.changed_at))}</td>
        <td${reason}>${escapeHtml(item.action_label || '')}</td>
        <td>${escapeHtml(item.changed_by_name || '-')}</td>
        <td${reason}>${escapeHtml(getInsuranceHistoryInfo(data))}</td>
        <td>${escapeHtml(getInsuranceHistoryReductionLabel(data))}</td>
        <td>${escapeHtml(data.limit_category || '')}</td>
        <td>${escapeHtml(formatInsuranceListDate(data.qualification_acquired_date || data.valid_from))}</td>
        <td>${escapeHtml(data.holder_name || '')}</td>
      </tr>
    `;
  }).join('');
}

async function openInsuranceHistoryModal(insuranceId) {
  if (!insuranceId) return;
  if (!window.InsuranceAPI?.history) {
    showToast('保険更新履歴APIが読み込まれていません', 'error');
    return;
  }

  const modal = ensureInsuranceHistoryModal();
  modal.classList.remove('hidden');
  const body = modal.querySelector('#insurance-history-body');
  if (body) body.innerHTML = '<tr class="insurance-history-message"><td colspan="8">更新履歴を読み込んでいます。</td></tr>';
  try {
    const result = await InsuranceAPI.history(insuranceId);
    const history = Array.isArray(result) ? result : (result?.data || []);
    renderInsuranceHistoryRows(history);
  } catch (error) {
    console.error('保険更新履歴取得エラー:', error);
    if (body) {
      body.innerHTML = `<tr class="insurance-history-message error"><td colspan="8">更新履歴の取得に失敗しました。${escapeHtml(error?.message || '')}</td></tr>`;
    }
  }
}

async function loadPatientInsurances(patientId, includeExpiredLaborAuto = includeExpiredLaborAutoInsurances) {
  if (!patientId || !window.InsuranceAPI) {
    currentPatientInsurances = [];
    currentPatientPublicExpenses = [];
    currentPatientReceiptSpecialNotes = [];
    currentPatientReceiptSymptomDetails = [];
    currentPatientReceiptSummaryComments = [];
    currentPatientWelfareInvoiceComments = [];
    currentPatientReceiptCopayments = [];
    renderInsuranceList([]);
    renderLaborAutoInsuranceList([]);
    renderPublicExpenseList([]);
    renderReceiptSpecialNoteList([]);
    renderReceiptSymptomDetailList([]);
    renderReceiptSummaryCommentList([]);
    renderWelfareInvoiceCommentList([]);
    renderReceiptCopaymentList([]);
    updateKarteHeaderContext();
    return;
  }

  try {
    const [insurances, publicExpenses, receiptSpecialNotes, receiptSymptomDetails, receiptSummaryComments, welfareInvoiceComments, receiptCopayments] = await Promise.all([
      InsuranceAPI.list(patientId, true, Boolean(includeExpiredLaborAuto)),
      InsuranceAPI.listPublicExpenses ? InsuranceAPI.listPublicExpenses(patientId, true) : Promise.resolve([]),
      InsuranceAPI.listReceiptSpecialNotes
        ? InsuranceAPI.listReceiptSpecialNotes(patientId, true, includeExpiredReceiptSpecialNotes)
        : Promise.resolve([]),
      InsuranceAPI.listReceiptSymptomDetails
        ? InsuranceAPI.listReceiptSymptomDetails(patientId, true, includeExpiredReceiptSymptomDetails)
        : Promise.resolve([]),
      InsuranceAPI.listReceiptSummaryComments
        ? InsuranceAPI.listReceiptSummaryComments(patientId, true, includeExpiredReceiptSummaryComments)
        : Promise.resolve([]),
      InsuranceAPI.listWelfareInvoiceComments
        ? InsuranceAPI.listWelfareInvoiceComments(patientId, true, includeExpiredWelfareInvoiceComments)
        : Promise.resolve([]),
      InsuranceAPI.listReceiptCopayments
        ? InsuranceAPI.listReceiptCopayments(patientId, true, includePastReceiptCopayments)
        : Promise.resolve([])
    ]);
    currentPatientInsurances = insurances;
    currentPatientPublicExpenses = publicExpenses;
    currentPatientReceiptSpecialNotes = receiptSpecialNotes;
    currentPatientReceiptSymptomDetails = receiptSymptomDetails;
    currentPatientReceiptSummaryComments = receiptSummaryComments;
    currentPatientWelfareInvoiceComments = welfareInvoiceComments;
    currentPatientReceiptCopayments = receiptCopayments;
    syncCurrentReceptionContextFromPatientData();
    renderInsuranceList(currentPatientInsurances);
    renderLaborAutoInsuranceList(currentPatientInsurances);
    renderPublicExpenseList(currentPatientPublicExpenses);
    renderReceiptSpecialNoteList(currentPatientReceiptSpecialNotes);
    renderReceiptSymptomDetailList(currentPatientReceiptSymptomDetails);
    renderReceiptSummaryCommentList(currentPatientReceiptSummaryComments);
    renderWelfareInvoiceCommentList(currentPatientWelfareInvoiceComments);
    renderReceiptCopaymentList(currentPatientReceiptCopayments);
    updateKarteHeaderContext();
    if (String(currentPatient?.id || '') === String(patientId || '') && isPatientZonePanelVisible('online-qualification-content')) {
      renderPatientOnlineQualificationPanel(patientId);
    }
  } catch (error) {
    console.error('保険情報取得エラー:', error);
    currentPatientInsurances = [];
    currentPatientPublicExpenses = [];
    currentPatientReceiptSpecialNotes = [];
    currentPatientReceiptSymptomDetails = [];
    currentPatientReceiptSummaryComments = [];
    currentPatientWelfareInvoiceComments = [];
    currentPatientReceiptCopayments = [];
    renderInsuranceList([]);
    renderLaborAutoInsuranceList([]);
    renderPublicExpenseList([]);
    renderReceiptSpecialNoteList([]);
    renderReceiptSymptomDetailList([]);
    renderReceiptSummaryCommentList([]);
    renderWelfareInvoiceCommentList([]);
    renderReceiptCopaymentList([]);
    updateKarteHeaderContext();
    if (String(currentPatient?.id || '') === String(patientId || '') && isPatientZonePanelVisible('online-qualification-content')) {
      renderPatientOnlineQualificationPanel(patientId);
    }
  }
}

function renderInsuranceList(insurances = []) {
  const container = document.getElementById('insurance-list');
  if (!container) return;
  const medicalInsurances = insurances.filter(item => !isLaborAutoInsurance(item) && isCurrentInsuranceRecord(item));
  updateInsuranceLastConfirmedDate(medicalInsurances);

  if (!medicalInsurances.length) {
    container.innerHTML = '<div class="insurance-empty">有効な医療保険が登録されていません。</div>';
    return;
  }

  container.innerHTML = `
    <table class="insurance-table medical-insurance-table">
      <thead>
        <tr>
          <th>保険者番号</th>
          <th>記号</th>
          <th>番号</th>
          <th>開始日</th>
          <th>終了日</th>
          <th></th>
        </tr>
      </thead>
      <tbody>
        ${medicalInsurances.map(item => `
          <tr>
            <td>${escapeHtml(item.insurer_number || '')}</td>
            <td>${escapeHtml(item.symbol || '')}</td>
            <td>${escapeHtml([item.number, item.branch_number].filter(Boolean).join('-'))}</td>
            <td>${escapeHtml(formatInsuranceListDate(item.valid_from))}</td>
            <td>${escapeHtml(formatInsuranceListDate(item.valid_until))}</td>
            <td class="insurance-row-actions">
              <button type="button" class="m3-icon-btn-sm" data-insurance-history-id="${escapeHtml(item.id)}" title="更新履歴" aria-label="更新履歴"><i class="fas fa-sync-alt"></i></button>
              <button type="button" class="m3-icon-btn-sm" data-insurance-edit-id="${escapeHtml(item.id)}" title="編集"><i class="fas fa-pen"></i></button>
            </td>
          </tr>
        `).join('')}
      </tbody>
    </table>
  `;
}

function isLaborAutoInsurance(insurance = {}) {
  return ['labor', 'workers', 'workers_comp', 'auto', 'automobile'].includes(String(insurance.insurance_type || '').toLowerCase());
}

function isWorkersInsurance(insurance = {}) {
  return ['labor', 'workers', 'workers_comp'].includes(String(insurance.insurance_type || '').toLowerCase());
}

function isCurrentInsuranceRecord(insurance = {}) {
  if (insurance.is_active === false) return false;
  const validUntil = normalizeKarteDateValue(insurance.valid_until);
  if (!validUntil) return true;
  return validUntil >= getLocalDateString(new Date());
}

function renderLaborAutoInsuranceList(insurances = []) {
  const container = document.getElementById('labor-auto-list');
  if (!container) return;

  const laborAutoItems = insurances.filter(item => (
    isLaborAutoInsurance(item)
    && (includeExpiredLaborAutoInsurances || isCurrentInsuranceRecord(item))
  ));
  if (!laborAutoItems.length) {
    container.innerHTML = `<div class="insurance-empty">${includeExpiredLaborAutoInsurances ? '労災・自賠責が登録されていません。' : '有効な労災・自賠責が登録されていません。'}</div>`;
    return;
  }

  container.innerHTML = `
    <table class="insurance-table labor-auto-insurance-table">
      <thead>
        <tr>
          <th>種類</th>
          <th>労保番号・年金番号</th>
          <th>開始日</th>
          <th>終了日</th>
          <th></th>
        </tr>
      </thead>
      <tbody>
        ${laborAutoItems.map(item => {
          const workers = item.workers_comp_details || {};
          const benefitType = workers.benefit_type === 'injury_pension'
            || Boolean(workers.pension_certificate_number)
            ? '傷病年金'
            : '短期';
          const typeLabel = isWorkersInsurance(item) ? `労災・${benefitType}` : '自賠責';
          const policyNumber = firstNonEmptyString(
            workers.labor_insurance_number,
            workers.pension_certificate_number,
            item.number
          );
          return `
            <tr>
              <td>${escapeHtml(typeLabel)}</td>
              <td>${escapeHtml(policyNumber)}</td>
              <td>${escapeHtml(formatInsuranceListDate(item.valid_from || workers.treatment_start_date))}</td>
              <td>${escapeHtml(formatInsuranceListDate(item.valid_until || workers.treatment_end_date))}</td>
              <td class="insurance-row-actions">
                <button type="button" class="m3-icon-btn-sm" data-labor-auto-edit-id="${escapeHtml(item.id)}" title="編集"><i class="fas fa-pen"></i></button>
              </td>
            </tr>
          `;
        }).join('')}
      </tbody>
    </table>
  `;
}

