function receiptSymptomTargetDate(value, fallback = '') {
  const normalized = normalizeKarteDateValue(value) || fallback;
  return normalized ? normalized.replace(/-/g, '/') : '';
}

function receiptSymptomTargetInsuranceLabel(insurance = {}) {
  const workers = insurance.workers_comp_details || {};
  const prefix = isWorkersInsurance(insurance)
    ? `労災 ${workers.benefit_type === 'injury_pension' || workers.pension_certificate_number ? '傷病年金' : '短期'}`
    : '自賠責';
  const start = receiptSymptomTargetDate(insurance.valid_from || workers.treatment_start_date);
  const end = receiptSymptomTargetDate(insurance.valid_until || workers.treatment_end_date, '9999-12-31');
  return `${prefix}${start ? ` ${start}〜${end}` : ''}`;
}

function renderReceiptSymptomDetailInsuranceOptions(selectedId = null, selectedLabel = '') {
  const select = document.getElementById('receipt-symptom-detail-insurance');
  if (!select) return;
  const options = [{ value: 'medical', label: '社保・国保' }];
  currentPatientInsurances.filter(isLaborAutoInsurance).forEach(insurance => {
    options.push({ value: String(insurance.id), label: receiptSymptomTargetInsuranceLabel(insurance) });
  });
  const selectedValue = selectedId ? String(selectedId) : 'medical';
  if (selectedId && !options.some(option => option.value === selectedValue)) {
    options.push({ value: selectedValue, label: selectedLabel || '対象保険' });
  }
  select.innerHTML = options.map(option => (
    `<option value="${escapeHtml(option.value)}">${escapeHtml(option.label)}</option>`
  )).join('');
  select.value = selectedValue;
}

