function updateReceiptSymptomDetailKindState() {
  const kind = document.querySelector('input[name="receipt-symptom-detail-kind"]:checked')?.value || 'symptom_detail';
  const category = document.getElementById('receipt-symptom-detail-category');
  if (!category) return;
  const isInjuryCourse = kind === 'injury_course';
  if (isInjuryCourse) category.value = '90';
  category.disabled = isInjuryCourse;
  category.setAttribute('aria-disabled', String(isInjuryCourse));
}

async function openReceiptSymptomDetailModal(detailId = null) {
  if (!currentPatient) {
    showToast('患者を選択してください', 'error');
    return;
  }
  const detail = detailId
    ? currentPatientReceiptSymptomDetails.find(item => String(item.id) === String(detailId))
    : null;
  if (detailId && !detail) {
    showToast('編集する症状詳記を取得できませんでした。再読み込みしてください', 'error');
    return;
  }
  editingReceiptSymptomDetailId = detail?.id || null;
  document.getElementById('receipt-symptom-detail-form')?.reset();
  await loadReceiptSymptomDetailTypes();
  const recordKind = detail?.record_kind || 'symptom_detail';
  const kindInput = document.querySelector(`input[name="receipt-symptom-detail-kind"][value="${recordKind}"]`);
  if (kindInput) kindInput.checked = true;
  renderReceiptSymptomDetailCategoryOptions(detail?.detail_category_code || (recordKind === 'injury_course' ? '90' : '01'));
  renderReceiptSymptomDetailInsuranceOptions(detail?.target_insurance_id, detail?.target_insurance_label);
  const title = document.getElementById('receipt-symptom-detail-modal-title');
  if (title) title.textContent = detail ? '症状詳記・傷病の経過 編集' : '症状詳記・傷病の経過 新規登録';
  const saveButton = document.getElementById('btn-receipt-symptom-detail-save');
  if (saveButton) saveButton.textContent = detail ? '更新' : '登録';
  document.getElementById('receipt-symptom-detail-content').value = detail?.content || '';
  document.getElementById('receipt-symptom-detail-valid-from').value = receiptSymptomTargetDate(detail?.valid_from, getLocalDateString());
  document.getElementById('receipt-symptom-detail-valid-until').value = receiptSymptomTargetDate(detail?.valid_until);
  updateReceiptSymptomDetailKindState();
  document.getElementById('receipt-symptom-detail-modal')?.classList.remove('hidden');
  const category = document.getElementById('receipt-symptom-detail-category');
  if (category?.disabled) {
    document.getElementById('receipt-symptom-detail-content')?.focus();
  } else {
    category?.focus();
  }
}

