function renderM3StatusOptions(currentValue, values) {
  return values.map(value => `
    <option value="${escapeHtml(value)}"${value === currentValue ? ' selected' : ''}>${escapeHtml(getM3StatusLabel(value))}</option>
  `).join('');
}

async function saveOnlineQualificationPanel() {
  if (!currentPatient?.id) {
    showToast('患者を選択してください', 'error');
    return;
  }
  const auxiliary = getPatientM3Auxiliary(currentPatient.id);
  const payload = {
    qualificationStatus: document.getElementById('online-qualification-status')?.value || 'unchecked',
    insuranceCardStatus: document.getElementById('online-insurance-card-status')?.value || 'unchecked',
    medicalCertificateStatus: document.getElementById('online-medical-certificate-status')?.value || 'unchecked',
    limitCertificateStatus: document.getElementById('online-limit-certificate-status')?.value || 'unchecked',
    electronicPrescriptionStatus: document.getElementById('online-electronic-prescription-status')?.value || 'none',
    pastPrescriptionStatus: document.getElementById('online-past-prescription-status')?.value || 'unchecked',
    note: document.getElementById('online-qualification-note')?.value.trim() || '',
    updatedAt: new Date().toISOString()
  };
  auxiliary.onlineQualification = normalizeOnlineQualificationSettings(payload);
  savePatientM3Auxiliary(currentPatient.id, auxiliary);

  if (currentReception?.id && typeof ReceptionAPI !== 'undefined') {
    try {
      await ReceptionAPI.update(currentReception.id, {
        insurance_card_status: payload.insuranceCardStatus,
        medical_certificate_status: payload.medicalCertificateStatus,
        limit_certificate_status: payload.limitCertificateStatus,
        electronic_prescription_status: payload.electronicPrescriptionStatus,
        past_prescription_status: payload.pastPrescriptionStatus
      });
      currentReception.insurance_card_status = payload.insuranceCardStatus;
      currentReception.medical_certificate_status = payload.medicalCertificateStatus;
      currentReception.limit_certificate_status = payload.limitCertificateStatus;
      currentReception.electronic_prescription_status = payload.electronicPrescriptionStatus;
      currentReception.past_prescription_status = payload.pastPrescriptionStatus;
      const cacheIndex = receptionsCache.findIndex(item => String(item.id) === String(currentReception.id));
      if (cacheIndex >= 0) {
        receptionsCache[cacheIndex] = { ...receptionsCache[cacheIndex], ...currentReception };
      }
      updateKarteHeaderContext();
    } catch (error) {
      console.warn('オン資等の受付保存に失敗しました:', error);
      showToast('オン資等メモは保存しましたが、受付への反映に失敗しました', 'warning');
      renderPatientOnlineQualificationPanel(currentPatient.id);
      return;
    }
  }

  renderPatientOnlineQualificationPanel(currentPatient.id);
  showToast('オン資等を保存しました', 'success');
}

