function getClinicalProfileStore() {
  try {
    const data = JSON.parse(localStorage.getItem(CLINICAL_PROFILE_STORAGE_KEY) || '{}');
    return data && typeof data === 'object' ? data : {};
  } catch (error) {
    console.warn('患者副作用等データ読み込みエラー:', error);
    return {};
  }
}

function persistClinicalProfileStore(store) {
  localStorage.setItem(CLINICAL_PROFILE_STORAGE_KEY, JSON.stringify(store || {}));
}

function getClinicalProfileItemKey(name) {
  return String(name || '').replace(/\s+/g, '').toLowerCase();
}

function normalizeClinicalProfileItems(items) {
  if (!Array.isArray(items)) return [];
  const seen = new Set();
  return items
    .map(item => {
      const name = String(typeof item === 'string' ? item : item?.name || '').trim();
      if (!name) return null;
      const key = getClinicalProfileItemKey(name);
      if (seen.has(key)) return null;
      seen.add(key);
      const source = typeof item === 'object' && item ? item : {};
      return {
        name,
        ...(source.code ? { code: source.code } : {}),
        ...(source.note ? { note: source.note } : {}),
        ...(source.symptoms ? { symptoms: source.symptoms } : {}),
        ...(source.onset ? { onset: source.onset } : {}),
        ...(source.source ? { source: source.source } : {}),
        createdAt: source.createdAt || source.created_at || new Date().toISOString(),
        ...(source.updatedAt || source.updated_at ? { updatedAt: source.updatedAt || source.updated_at } : {})
      };
    })
    .filter(Boolean);
}

function normalizePatientClinicalProfile(profile = {}) {
  return {
    allergies: normalizeClinicalProfileItems(profile.allergies),
    adverseDrugs: normalizeClinicalProfileItems(profile.adverseDrugs || profile.adverse_drugs),
    regularDrugs: normalizeClinicalProfileItems(profile.regularDrugs || profile.regular_drugs),
    pastHistories: normalizeClinicalProfileItems(profile.pastHistories || profile.past_histories)
  };
}

function getPatientClinicalProfile(patientId) {
  const cacheKey = String(patientId || '');
  if (clinicalProfileCache.has(cacheKey)) {
    return normalizePatientClinicalProfile(clinicalProfileCache.get(cacheKey));
  }
  return normalizePatientClinicalProfile();
}

function cachePatientClinicalProfile(patientId, profile) {
  if (!patientId) return null;
  const normalized = normalizePatientClinicalProfile(profile);
  clinicalProfileCache.set(String(patientId), normalized);
  return normalized;
}

function persistPatientClinicalProfileLocal(patientId, profile) {
  if (!patientId) return;
  const store = getClinicalProfileStore();
  store[String(patientId)] = normalizePatientClinicalProfile(profile);
  persistClinicalProfileStore(store);
}

async function loadPatientClinicalProfile(patientId, options = {}) {
  if (!patientId) return normalizePatientClinicalProfile();
  const cacheKey = String(patientId);
  if (!options.force && clinicalProfileCache.has(cacheKey)) {
    return getPatientClinicalProfile(patientId);
  }
  if (!options.force && clinicalProfileLoadPromises.has(cacheKey)) {
    return clinicalProfileLoadPromises.get(cacheKey);
  }
  if (typeof PatientAPI === 'undefined' || !PatientAPI.getClinicalProfile) {
    clinicalProfileLoadErrors.set(cacheKey, '患者副作用等データAPIが利用できません');
    clinicalProfileCache.delete(cacheKey);
    return normalizePatientClinicalProfile();
  }

  const promise = PatientAPI.getClinicalProfile(patientId)
    .then(profile => {
      const normalized = cachePatientClinicalProfile(patientId, profile || {});
      clinicalProfileLoadErrors.delete(cacheKey);
      persistPatientClinicalProfileLocal(patientId, normalized);
      return normalized;
    })
    .catch(error => {
      console.error('患者副作用等データAPI読み込みエラー:', error);
      clinicalProfileLoadErrors.set(cacheKey, error?.message || '患者副作用等データの取得に失敗しました');
      clinicalProfileCache.delete(cacheKey);
      return normalizePatientClinicalProfile();
    })
    .finally(() => {
      clinicalProfileLoadPromises.delete(cacheKey);
    });

  clinicalProfileLoadPromises.set(cacheKey, promise);
  return promise;
}

async function savePatientClinicalProfile(patientId, profile) {
  if (!patientId) return normalizePatientClinicalProfile();
  const cacheKey = String(patientId);
  const normalized = normalizePatientClinicalProfile(profile);

  if (typeof PatientAPI === 'undefined' || !PatientAPI.updateClinicalProfile) {
    const message = '患者副作用等データAPIが利用できません';
    clinicalProfileLoadErrors.set(cacheKey, message);
    showToast(message, 'error');
    throw new Error(message);
  }

  try {
    const savedProfile = await PatientAPI.updateClinicalProfile(patientId, normalized);
    const refreshed = cachePatientClinicalProfile(patientId, savedProfile || normalized);
    clinicalProfileLoadErrors.delete(cacheKey);
    persistPatientClinicalProfileLocal(patientId, refreshed);
    if (String(currentPatient?.id || '') === cacheKey && isClinicalProfileVisible()) {
      await renderClinicalProfilePanel(patientId, { skipLoad: true });
    }
    if (String(currentPatient?.id || '') === cacheKey) {
      checkPrescriptionsRealtime();
    }
    return refreshed;
  } catch (error) {
    console.error('患者副作用等データAPI保存エラー:', error);
    const message = error?.message || '患者副作用等データの保存に失敗しました';
    clinicalProfileLoadErrors.set(cacheKey, message);
    showToast(`患者副作用等データの保存に失敗しました: ${message}`, 'error');
    throw error;
  }
}

function isClinicalProfileVisible() {
  const content = document.getElementById('allergy-content');
  return Boolean(content && content.style.display !== 'none');
}

function refreshClinicalProfileIfVisible(patientId = currentPatient?.id) {
  if (!patientId || !isClinicalProfileVisible()) return;
  renderClinicalProfilePanel(patientId);
}

function renderClinicalProfileList(containerId, items, emptyMessage, options = {}) {
  const container = document.getElementById(containerId);
  if (!container) return;
  const onRemove = options.onRemove || removePatientAllergy;
  if (!items.length) {
    container.innerHTML = `<div class="clinical-profile-empty">${escapeHtml(emptyMessage)}</div>`;
    return;
  }

  container.innerHTML = items.map((item, index) => `
    <div class="clinical-profile-item">
      <span class="clinical-profile-item-name">${escapeHtml(item.name)}</span>
      ${options.removable ? `
        <button type="button" class="clinical-profile-delete" data-clinical-index="${index}" title="削除">
          <i class="fas fa-times"></i>
        </button>
      ` : ''}
    </div>
  `).join('');

  if (options.removable) {
    container.querySelectorAll('.clinical-profile-delete').forEach(button => {
      button.addEventListener('click', event => {
        event.stopPropagation();
        onRemove(Number(button.dataset.clinicalIndex));
      });
    });
  }
}

async function renderClinicalProfilePanel(patientId = currentPatient?.id, options = {}) {
  const cacheKey = String(patientId || '');
  let profile = getPatientClinicalProfile(patientId);
  if (patientId && !options.skipLoad && (options.forceLoad || !clinicalProfileCache.has(cacheKey))) {
    profile = await loadPatientClinicalProfile(patientId, { force: options.forceLoad });
    if (currentPatient?.id && String(currentPatient.id) !== String(patientId)) return;
  }

  const loadError = patientId ? clinicalProfileLoadErrors.get(cacheKey) : '';
  if (loadError) {
    const message = `${loadError}。患者別データを表示できません。`;
    [
      'allergy-list',
      'adverse-drug-list',
      'regular-drug-list',
      'past-history-list'
    ].forEach(containerId => {
      const container = document.getElementById(containerId);
      if (container) container.innerHTML = emptyClinicalMessage(message);
    });
    return;
  }

  renderClinicalProfileList('allergy-list', profile.allergies, 'アレルギーが登録されていません。', {
    removable: true,
    onRemove: removePatientAllergy
  });
  renderClinicalProfileList('adverse-drug-list', profile.adverseDrugs, '副作用薬が登録されていません。', {
    removable: true,
    onRemove: removePatientAdverseDrug
  });
  renderClinicalProfileList('regular-drug-list', profile.regularDrugs, '常用薬が登録されていません。', {
    removable: true,
    onRemove: removePatientRegularDrug
  });
  renderClinicalProfileList('past-history-list', profile.pastHistories, '既往歴が登録されていません。', {
    removable: true,
    onRemove: removePatientPastHistory
  });
}

async function addPatientAllergy(name) {
  if (!currentPatient?.id) {
    showToast('患者を選択してください', 'error');
    return;
  }

  const allergyName = String(name || '').trim();
  if (!allergyName) return;

  const profile = getPatientClinicalProfile(currentPatient.id);
  const exists = profile.allergies.some(item => getClinicalProfileItemKey(item.name) === getClinicalProfileItemKey(allergyName));
  if (!exists) {
    profile.allergies.push({ name: allergyName, createdAt: new Date().toISOString() });
    try {
      await savePatientClinicalProfile(currentPatient.id, profile);
    } catch {
      return;
    }
  }
  closeAllergyAddModal();
}

async function removePatientAllergy(index) {
  if (!currentPatient?.id || !Number.isInteger(index)) return;
  const profile = getPatientClinicalProfile(currentPatient.id);
  if (!profile.allergies[index]) return;
  profile.allergies.splice(index, 1);
  try {
    await savePatientClinicalProfile(currentPatient.id, profile);
  } catch {
    // 保存失敗時は現在の画面状態を維持する。
  }
}

