function getFilteredAllergyMasterItems(keyword = '') {
  const normalizedKeyword = getClinicalProfileItemKey(keyword);
  if (!normalizedKeyword) return ALLERGY_MASTER_ITEMS;
  return ALLERGY_MASTER_ITEMS.filter(item => getClinicalProfileItemKey(item).includes(normalizedKeyword));
}

function getFilteredAdverseDrugMasterItems(keyword = '') {
  const normalizedKeyword = getClinicalProfileItemKey(keyword);
  if (!normalizedKeyword) return ADVERSE_DRUG_MASTER_ITEMS;
  return ADVERSE_DRUG_MASTER_ITEMS.filter(item => getClinicalProfileItemKey(item).includes(normalizedKeyword));
}

function getFilteredRegularDrugMasterItems(keyword = '') {
  return getFilteredAdverseDrugMasterItems(keyword);
}

function getFilteredPastHistoryMasterItems(keyword = '') {
  const normalizedKeyword = getClinicalProfileItemKey(keyword);
  if (!normalizedKeyword) return PAST_HISTORY_MASTER_ITEMS;
  return PAST_HISTORY_MASTER_ITEMS.filter(item => getClinicalProfileItemKey(item).includes(normalizedKeyword));
}

function renderAllergyAddCandidates(keyword = '') {
  const list = document.getElementById('allergy-add-candidate-list');
  if (!list) return;
  const items = getFilteredAllergyMasterItems(keyword);
  if (!items.length) {
    list.innerHTML = '<div class="allergy-candidate-empty">候補がありません。</div>';
    return;
  }
  const currentNames = new Set(getPatientClinicalProfile(currentPatient?.id).allergies.map(item => getClinicalProfileItemKey(item.name)));
  list.innerHTML = items.map(item => {
    const isSelected = currentNames.has(getClinicalProfileItemKey(item));
    return `
      <button type="button" class="allergy-candidate-row${isSelected ? ' selected' : ''}" data-allergy-name="${escapeHtml(item)}">
        ${escapeHtml(item)}
        ${isSelected ? '<span class="allergy-candidate-selected">登録済み</span>' : ''}
      </button>
    `;
  }).join('');
  list.querySelectorAll('.allergy-candidate-row').forEach(button => {
    button.addEventListener('click', () => addPatientAllergy(button.dataset.allergyName));
  });
}

function renderAdverseDrugAddCandidates(keyword = '') {
  const list = document.getElementById('adverse-drug-add-candidate-list');
  if (!list) return;
  const items = getFilteredAdverseDrugMasterItems(keyword);
  if (!items.length) {
    list.innerHTML = '<div class="allergy-candidate-empty">候補がありません。</div>';
    return;
  }
  const currentNames = new Set(getPatientClinicalProfile(currentPatient?.id).adverseDrugs.map(item => getClinicalProfileItemKey(item.name)));
  list.innerHTML = items.map(item => {
    const isSelected = currentNames.has(getClinicalProfileItemKey(item));
    return `
      <button type="button" class="allergy-candidate-row${isSelected ? ' selected' : ''}" data-adverse-drug-name="${escapeHtml(item)}">
        ${escapeHtml(item)}
        ${isSelected ? '<span class="allergy-candidate-selected">登録済み</span>' : ''}
      </button>
    `;
  }).join('');
  list.querySelectorAll('.allergy-candidate-row').forEach(button => {
    button.addEventListener('click', () => addPatientAdverseDrug(button.dataset.adverseDrugName));
  });
}

