function isMedicationHistoryVisible() {
  const content = document.getElementById('medication-history-content');
  return Boolean(content && content.style.display !== 'none');
}

function refreshMedicationHistoryIfVisible(patientId = currentPatient?.id) {
  if (!patientId || (!isMedicationHistoryVisible() && !isMedicationHistoryWindowOpen())) return;
  renderPatientMedicationHistory(patientId);
}

function isVitalPanelVisible() {
  const content = document.getElementById('vital-content');
  return Boolean(content && content.style.display !== 'none');
}

function refreshVitalsIfVisible(patientId = currentPatient?.id) {
  if (!patientId || !isVitalPanelVisible()) return;
  renderPatientVitals(patientId);
}

function getVitalItem(key) {
  return VITAL_ITEMS.find(item => item.key === key) || null;
}

function getDefaultVitalGraphSelection() {
  return VITAL_ITEMS
    .filter(item => item.defaultGraph)
    .map(item => item.key);
}

function getVitalGraphSelection() {
  try {
    const stored = JSON.parse(localStorage.getItem(VITAL_GRAPH_SELECTION_KEY) || 'null');
    if (Array.isArray(stored)) {
      return new Set(stored.filter(key => getVitalItem(key)));
    }
  } catch (error) {
    console.warn('バイタル表示設定の読み込みに失敗しました:', error);
  }
  return new Set(getDefaultVitalGraphSelection());
}

function saveVitalGraphSelection(selection) {
  try {
    localStorage.setItem(VITAL_GRAPH_SELECTION_KEY, JSON.stringify([...selection]));
  } catch (error) {
    console.warn('バイタル表示設定の保存に失敗しました:', error);
  }
}

function parseVitalNumber(value) {
  if (value === null || value === undefined || value === '') return null;
  const normalized = formatHalfWidthNumericText(value).replace(/,/g, '.').replace(/[^\d.+-]/g, '');
  if (!normalized || normalized === '-' || normalized === '+' || normalized === '.') return null;
  const numeric = Number(normalized);
  return Number.isFinite(numeric) ? numeric : null;
}

function formatVitalValue(value) {
  const numeric = parseVitalNumber(value);
  if (numeric === null) return '';
  return Number.isInteger(numeric) ? String(numeric) : String(Number(numeric.toFixed(2)));
}

function formatVitalValueWithUnit(value, item) {
  const text = formatVitalValue(value);
  if (!text) return '';
  if (!item?.unit) return text;
  if (item.unit === '%') return `${text}%`;
  return `${text} ${item.unit}`;
}

function pickVitalValue(source, keys) {
  for (const key of keys) {
    if (source?.[key] !== null && source?.[key] !== undefined && source?.[key] !== '') {
      return source[key];
    }
  }
  return null;
}

function calculateVitalBmi(weight, height) {
  const weightValue = parseVitalNumber(weight);
  const heightValue = parseVitalNumber(height);
  if (!weightValue || !heightValue) return null;
  const meters = heightValue / 100;
  if (!meters) return null;
  return Number((weightValue / (meters * meters)).toFixed(1));
}

function normalizeVitalValues(vitalSigns) {
  const source = normalizeKarteVitalSigns(vitalSigns);
  const bloodPressure = source.blood_pressure || source.bloodPressure || {};
  const values = {
    systolic: parseVitalNumber(pickVitalValue(source, [
      'blood_pressure_systolic', 'bloodPressureSystolic', 'bp_systolic', 'bpSystolic', 'systolic', 'bp_s'
    ]) ?? pickVitalValue(bloodPressure, ['systolic', 's', 'high'])),
    diastolic: parseVitalNumber(pickVitalValue(source, [
      'blood_pressure_diastolic', 'bloodPressureDiastolic', 'bp_diastolic', 'bpDiastolic', 'diastolic', 'bp_d'
    ]) ?? pickVitalValue(bloodPressure, ['diastolic', 'd', 'low'])),
    pulse: parseVitalNumber(pickVitalValue(source, ['pulse', 'pulse_rate', 'pulseRate', 'heart_rate', 'heartRate'])),
    temperature: parseVitalNumber(pickVitalValue(source, ['temperature', 'body_temperature', 'bodyTemperature', 'temp'])),
    spo2: parseVitalNumber(pickVitalValue(source, ['spo2', 'SpO2', 'SPO2', 'oxygen_saturation', 'oxygenSaturation'])),
    weight: parseVitalNumber(pickVitalValue(source, ['weight', 'body_weight', 'bodyWeight'])),
    abdomen: parseVitalNumber(pickVitalValue(source, ['abdominal_circumference', 'abdominalCircumference', 'waist', 'abdomen'])),
    height: parseVitalNumber(pickVitalValue(source, ['height', 'body_height', 'bodyHeight'])),
    head: parseVitalNumber(pickVitalValue(source, ['head_circumference', 'headCircumference', 'head'])),
    chest: parseVitalNumber(pickVitalValue(source, ['chest_circumference', 'chestCircumference', 'chest']))
  };
  values.bmi = calculateVitalBmi(values.weight, values.height);
  return values;
}

function hasVitalValues(values) {
  return VITAL_ITEMS
    .filter(item => item.key !== 'bmi')
    .some(item => parseVitalNumber(values?.[item.key]) !== null);
}

function getVitalMeasuredDate(vitalSigns, fallbackDate = null) {
  const source = normalizeKarteVitalSigns(vitalSigns);
  return normalizeKarteDateValue(
    source.measured_at ||
    source.measuredAt ||
    source.measured_date ||
    source.measuredDate ||
    source.date ||
    fallbackDate
  );
}

function normalizeVitalEntryFromRecord(record) {
  const vitalSigns = normalizeKarteVitalSigns(record?.vital_signs || record?.vitalSigns);
  const values = normalizeVitalValues(vitalSigns);
  if (!hasVitalValues(values)) return null;
  const date = getVitalMeasuredDate(vitalSigns, record?.visit_date || record?.date);
  if (!date) return null;
  return {
    id: record?.id || `${date}-${record?.created_at || ''}`,
    recordId: record?.id || null,
    source: 'record',
    date,
    visitDate: normalizeKarteDateValue(record?.visit_date) || date,
    updatedAt: record?.updated_at || record?.created_at || '',
    values
  };
}

function getCurrentVitalDraftEntry() {
  if (!currentPatient?.id) return null;
  const values = normalizeVitalValues(currentRecordVitalSigns);
  if (!hasVitalValues(values)) return null;
  const date = getVitalMeasuredDate(currentRecordVitalSigns, getCurrentKarteDateValue());
  if (!date) return null;
  return {
    id: currentRecordId || `draft-${date}`,
    recordId: currentRecordId || null,
    source: currentRecordId ? 'record' : 'draft',
    date,
    visitDate: getCurrentKarteDateValue(),
    updatedAt: '',
    values
  };
}

function compareVitalEntriesAsc(a, b) {
  const dateDiff = parseLocalDate(a.date).getTime() - parseLocalDate(b.date).getTime();
  if (dateDiff) return dateDiff;
  return String(a.updatedAt || '').localeCompare(String(b.updatedAt || ''));
}

async function collectPatientVitalEntries(patientId) {
  let records = [];
  if (patientId && window.RecordAPI) {
    const result = await RecordAPI.list(patientId, 100, 0);
    records = Array.isArray(result) ? result : (result.data || []);
  } else {
    records = Storage.getRecords().filter(record => String(record.patientId || record.patient_id) === String(patientId));
  }

  let entries = records
    .map(normalizeVitalEntryFromRecord)
    .filter(Boolean);

  const draftEntry = getCurrentVitalDraftEntry();
  if (draftEntry && String(currentPatient?.id || '') === String(patientId || '')) {
    entries = entries.filter(entry => {
      if (draftEntry.recordId && entry.recordId) return String(entry.recordId) !== String(draftEntry.recordId);
      return !(entry.date === draftEntry.date && !entry.recordId);
    });
    entries.push(draftEntry);
  }

  return entries.sort(compareVitalEntriesAsc);
}

function formatVitalDateShort(dateValue) {
  const date = parseLocalDate(normalizeKarteDateValue(dateValue) || dateValue);
  if (Number.isNaN(date.getTime())) return String(dateValue || '');
  return `${date.getFullYear()}/${date.getMonth() + 1}/${date.getDate()}`;
}

function renderVitalTable(entries) {
  const head = document.getElementById('vital-table-head');
  const body = document.getElementById('vital-data');
  if (!head || !body) return;

  if (!entries.length) {
    head.innerHTML = '<tr><th class="vital-item-head">項目</th></tr>';
    body.innerHTML = '<tr><td class="no-data">バイタルサインが登録されていません。</td></tr>';
    return;
  }

  const selection = getVitalGraphSelection();
  head.innerHTML = `
    <tr>
      <th class="vital-item-head">項目</th>
      ${entries.map(entry => `<th class="vital-date-head">${escapeHtml(formatVitalDateShort(entry.date))}</th>`).join('')}
    </tr>
  `;

  body.innerHTML = VITAL_ITEMS.map(item => `
    <tr>
      <th class="vital-item-cell">
        <label class="vital-check-row">
          <input type="checkbox" data-vital-graph-item="${escapeHtml(item.key)}" ${selection.has(item.key) ? 'checked' : ''}>
          <span>${escapeHtml(item.unit ? `${item.label}(${item.unit})` : item.label)}</span>
        </label>
      </th>
      ${entries.map((entry, index) => {
        const rawValue = entry.values[item.key];
        const valueText = formatVitalValue(rawValue);
        if (!valueText) return '<td class="vital-value-cell empty"></td>';
        return `
          <td class="vital-value-cell">
            <button type="button" class="vital-cell-button" data-vital-entry-index="${index}" data-vital-item-key="${escapeHtml(item.key)}">
              ${escapeHtml(valueText)}
            </button>
          </td>
        `;
      }).join('')}
    </tr>
  `).join('');
}

function getSelectedVitalSeries(entries) {
  const selection = getVitalGraphSelection();
  return VITAL_ITEMS
    .filter(item => selection.has(item.key))
    .map(item => ({
      item,
      points: entries
        .map(entry => ({
          date: entry.date,
          label: formatVitalDateShort(entry.date),
          value: parseVitalNumber(entry.values[item.key])
        }))
        .filter(point => point.value !== null)
    }))
    .filter(series => series.points.length);
}

function buildVitalSvgLineChart(series, options = {}) {
  const width = options.width || 520;
  const height = options.height || 245;
  const padding = { left: 48, right: 18, top: 20, bottom: 44 };
  const allPoints = series.flatMap(row => row.points);
  if (!allPoints.length) return '';

  const dates = allPoints.map(point => parseLocalDate(point.date).getTime()).filter(Number.isFinite);
  let minX = Math.min(...dates);
  let maxX = Math.max(...dates);
  if (minX === maxX) {
    minX -= 86400000;
    maxX += 86400000;
  }

  const values = allPoints.map(point => point.value);
  let minY = Math.min(...values);
  let maxY = Math.max(...values);
  if (minY === maxY) {
    minY -= 1;
    maxY += 1;
  }
  const yPad = Math.max((maxY - minY) * 0.12, 1);
  minY = Math.floor(minY - yPad);
  maxY = Math.ceil(maxY + yPad);

  const plotW = width - padding.left - padding.right;
  const plotH = height - padding.top - padding.bottom;
  const x = date => padding.left + ((parseLocalDate(date).getTime() - minX) / (maxX - minX)) * plotW;
  const y = value => padding.top + (1 - ((value - minY) / (maxY - minY))) * plotH;
  const gridLines = 4;
  const yGrid = Array.from({ length: gridLines + 1 }, (_, index) => {
    const ratio = index / gridLines;
    const value = maxY - (maxY - minY) * ratio;
    const gy = padding.top + plotH * ratio;
    return `
      <line x1="${padding.left}" y1="${gy}" x2="${width - padding.right}" y2="${gy}" stroke="#e5eeee" />
      <text x="${padding.left - 7}" y="${gy + 4}" text-anchor="end" class="vital-chart-axis">${escapeHtml(formatVitalValue(value))}</text>
    `;
  }).join('');

  const dateLabels = [...new Map(allPoints.map(point => [point.date, point.label])).entries()]
    .sort((a, b) => parseLocalDate(a[0]) - parseLocalDate(b[0]));
  const step = Math.max(1, Math.ceil(dateLabels.length / 5));
  const xLabels = dateLabels
    .filter((_, index) => index % step === 0 || index === dateLabels.length - 1)
    .map(([date, label]) => {
      const lx = x(date);
      return `<text x="${lx}" y="${height - 18}" text-anchor="middle" class="vital-chart-axis">${escapeHtml(label.replace(/^\d{4}\//, ''))}</text>`;
    }).join('');

  const paths = series.map(row => {
    const ordered = row.points.slice().sort((a, b) => parseLocalDate(a.date) - parseLocalDate(b.date));
    const points = ordered.map(point => `${x(point.date).toFixed(1)},${y(point.value).toFixed(1)}`).join(' ');
    const dots = ordered.map(point => `
      <circle cx="${x(point.date).toFixed(1)}" cy="${y(point.value).toFixed(1)}" r="3" fill="#fff" stroke="${row.item.color}" stroke-width="1.6">
        <title>${escapeHtml(`${point.label} ${row.item.label} ${formatVitalValueWithUnit(point.value, row.item)}`)}</title>
      </circle>
    `).join('');
    return `
      <polyline points="${points}" fill="none" stroke="${row.item.color}" stroke-width="1.8" />
      ${dots}
    `;
  }).join('');

  const legend = series.map((row, index) => {
    const lx = padding.left + index * 118;
    const ly = height - 5;
    return `
      <g>
        <line x1="${lx}" y1="${ly - 4}" x2="${lx + 18}" y2="${ly - 4}" stroke="${row.item.color}" stroke-width="2" />
        <text x="${lx + 23}" y="${ly}" class="vital-chart-legend">${escapeHtml(row.item.label)}</text>
      </g>
    `;
  }).join('');

  return `
    <svg class="vital-chart-svg" viewBox="0 0 ${width} ${height}" role="img" aria-label="バイタルグラフ">
      <rect x="0" y="0" width="${width}" height="${height}" fill="#fff" />
      ${yGrid}
      <line x1="${padding.left}" y1="${padding.top}" x2="${padding.left}" y2="${padding.top + plotH}" stroke="#a8b7b2" />
      <line x1="${padding.left}" y1="${padding.top + plotH}" x2="${width - padding.right}" y2="${padding.top + plotH}" stroke="#a8b7b2" />
      ${xLabels}
      ${paths}
      ${legend}
    </svg>
  `;
}

function renderVitalGraph(entries = currentVitalEntries) {
  const panel = document.getElementById('vital-graph-panel');
  if (!panel) return;

  const selected = getVitalGraphSelection();
  if (!selected.size) {
    panel.innerHTML = '<div class="vital-chart-empty">グラフ表示する項目にチェックを入れてください。</div>';
    return;
  }

  const series = getSelectedVitalSeries(entries);
  if (!series.length) {
    panel.innerHTML = '<div class="vital-chart-empty">選択中の項目に表示できるバイタル値がありません。</div>';
    return;
  }

  panel.innerHTML = buildVitalSvgLineChart(series);
}

function getPatientAgeYearsOnDate(dateValue) {
  const birthDate = currentPatient?.birth_date || currentPatient?.birth;
  if (!birthDate || !dateValue) return null;
  const birth = parseLocalDate(normalizeKarteDateValue(birthDate) || String(birthDate).slice(0, 10));
  const target = parseLocalDate(normalizeKarteDateValue(dateValue) || dateValue);
  if (Number.isNaN(birth.getTime()) || Number.isNaN(target.getTime()) || target < birth) return null;
  return Number(((target.getTime() - birth.getTime()) / (365.2425 * 24 * 60 * 60 * 1000)).toFixed(2));
}

function buildVitalAgeLineChart(points, item) {
  if (!points.length) return '';
  const width = 520;
  const height = 210;
  const padding = { left: 46, right: 18, top: 18, bottom: 36 };
  const plotW = width - padding.left - padding.right;
  const plotH = height - padding.top - padding.bottom;
  const ordered = points.slice().sort((a, b) => a.age - b.age);
  const maxObservedAge = Math.max(...ordered.map(point => point.age));
  const maxX = Math.max(18, Math.ceil(maxObservedAge));
  const values = ordered.map(point => point.value);
  let minY = Math.min(...values);
  let maxY = Math.max(...values);
  if (minY === maxY) {
    minY -= 1;
    maxY += 1;
  }
  const yPad = Math.max((maxY - minY) * 0.12, 1);
  minY = Math.floor(minY - yPad);
  maxY = Math.ceil(maxY + yPad);
  const x = age => padding.left + (age / maxX) * plotW;
  const y = value => padding.top + (1 - ((value - minY) / (maxY - minY))) * plotH;
  const yGrid = Array.from({ length: 5 }, (_, index) => {
    const ratio = index / 4;
    const value = maxY - (maxY - minY) * ratio;
    const gy = padding.top + plotH * ratio;
    return `
      <line x1="${padding.left}" y1="${gy}" x2="${width - padding.right}" y2="${gy}" stroke="#e5eeee" />
      <text x="${padding.left - 7}" y="${gy + 4}" text-anchor="end" class="vital-chart-axis">${escapeHtml(formatVitalValue(value))}</text>
    `;
  }).join('');
  const xGrid = Array.from({ length: 7 }, (_, index) => Math.round((maxX / 6) * index))
    .filter((age, index, array) => index === 0 || age !== array[index - 1])
    .map(age => {
      const gx = x(age);
      return `
        <line x1="${gx}" y1="${padding.top}" x2="${gx}" y2="${padding.top + plotH}" stroke="#edf3f1" />
        <text x="${gx}" y="${height - 14}" text-anchor="middle" class="vital-chart-axis">${age}</text>
      `;
    }).join('');
  const polyline = ordered.map(point => `${x(point.age).toFixed(1)},${y(point.value).toFixed(1)}`).join(' ');
  const dots = ordered.map(point => `
    <circle cx="${x(point.age).toFixed(1)}" cy="${y(point.value).toFixed(1)}" r="3" fill="#fff" stroke="${item.color}" stroke-width="1.6">
      <title>${escapeHtml(`${formatVitalDateShort(point.date)} ${item.label} ${formatVitalValueWithUnit(point.value, item)} ${point.age}歳`)}</title>
    </circle>
  `).join('');

  return `
    <svg class="vital-chart-svg" viewBox="0 0 ${width} ${height}" role="img" aria-label="${escapeHtml(item.label)}の成長推移">
      <rect x="0" y="0" width="${width}" height="${height}" fill="#fff" />
      ${yGrid}
      ${xGrid}
      <line x1="${padding.left}" y1="${padding.top}" x2="${padding.left}" y2="${padding.top + plotH}" stroke="#a8b7b2" />
      <line x1="${padding.left}" y1="${padding.top + plotH}" x2="${width - padding.right}" y2="${padding.top + plotH}" stroke="#a8b7b2" />
      <polyline points="${polyline}" fill="none" stroke="${item.color}" stroke-width="1.8" />
      ${dots}
      <text x="${width - padding.right}" y="${height - 2}" text-anchor="end" class="vital-chart-axis">年齢</text>
    </svg>
  `;
}

function renderGrowthVitalChart(points, item) {
  if (!points.length) return '';
  return `
    <div class="vital-growth-chart">
      <div class="vital-growth-title">${escapeHtml(item.label)}の推移</div>
      ${buildVitalAgeLineChart(points, item)}
    </div>
  `;
}

function renderVitalGrowth(entries = currentVitalEntries) {
  const panel = document.getElementById('vital-growth-panel');
  if (!panel) return;
  if (!isM3FeatureEnabled('vitalGrowthCurve')) {
    panel.innerHTML = '<div class="vital-chart-empty">成長曲線はその他設定で非表示です。</div>';
    return;
  }

  const birthDate = currentPatient?.birth_date || currentPatient?.birth;
  const ageNow = calculateAgeParts(birthDate);
  if (!birthDate || !ageNow || ageNow.years >= 18) {
    panel.innerHTML = '<div class="vital-chart-empty">成長曲線は18歳未満の患者で表示します。</div>';
    return;
  }

  const heightItem = getVitalItem('height');
  const weightItem = getVitalItem('weight');
  const heightPoints = [];
  const weightPoints = [];
  entries.forEach(entry => {
    const age = getPatientAgeYearsOnDate(entry.date);
    if (age === null) return;
    const height = parseVitalNumber(entry.values.height);
    const weight = parseVitalNumber(entry.values.weight);
    if (height !== null) heightPoints.push({ age, date: entry.date, value: height });
    if (weight !== null) weightPoints.push({ age, date: entry.date, value: weight });
  });

  if (!heightPoints.length && !weightPoints.length) {
    panel.innerHTML = '<div class="vital-chart-empty">身長または体重の記録がありません。</div>';
    return;
  }

  panel.innerHTML = `
    <div class="vital-growth-note">公式基準曲線データは未登録のため、患者本人の身長・体重推移を表示しています。</div>
    ${renderGrowthVitalChart(heightPoints, heightItem)}
    ${renderGrowthVitalChart(weightPoints, weightItem)}
  `;
}

function renderVitalPanels() {
  renderVitalGraph(currentVitalEntries);
  renderVitalGrowth(currentVitalEntries);
}

async function renderPatientVitals(patientId = currentPatient?.id) {
  if (!patientId) {
    clearVitalPanel();
    return;
  }

  const body = document.getElementById('vital-data');
  if (body) {
    body.innerHTML = '<tr><td class="no-data">バイタルサインを読み込み中です。</td></tr>';
  }

  try {
    const entries = await collectPatientVitalEntries(patientId);
    if (String(currentPatient?.id || '') !== String(patientId || '')) return;
    currentVitalEntries = entries;
    renderVitalTable(entries);
    renderVitalPanels();
  } catch (error) {
    console.error('バイタル取得エラー:', error);
    currentVitalEntries = [];
    renderVitalTable([]);
    const panel = document.getElementById('vital-graph-panel');
    if (panel) panel.innerHTML = '<div class="vital-chart-empty">バイタルの取得に失敗しました。</div>';
  }
}

function clearVitalPanel() {
  currentVitalEntries = [];
  const head = document.getElementById('vital-table-head');
  const body = document.getElementById('vital-data');
  if (head) head.innerHTML = '<tr><th class="vital-item-head">項目</th></tr>';
  if (body) body.innerHTML = '<tr><td class="no-data">バイタルサインが登録されていません。</td></tr>';
  const graph = document.getElementById('vital-graph-panel');
  const growth = document.getElementById('vital-growth-panel');
  if (graph) graph.innerHTML = '<div class="vital-chart-empty">グラフ表示する項目にチェックを入れてください。</div>';
  if (growth) {
    growth.innerHTML = isM3FeatureEnabled('vitalGrowthCurve')
      ? '<div class="vital-chart-empty">18歳未満の患者に、身長または体重の記録がある場合に表示します。</div>'
      : '<div class="vital-chart-empty">成長曲線はその他設定で非表示です。</div>';
  }
}

function switchVitalView(view) {
  const nextView = view === 'growth' && !isM3FeatureEnabled('vitalGrowthCurve') ? 'graph' : view;
  document.querySelectorAll('.vital-view-tab').forEach(tab => {
    tab.classList.toggle('active', tab.dataset.vitalView === nextView);
  });
  document.querySelectorAll('[data-vital-panel]').forEach(panel => {
    panel.classList.toggle('hidden', panel.dataset.vitalPanel !== nextView);
  });
}

function setVitalModalValues(modal, entry) {
  const dateInput = modal.querySelector('#vital-measured-date');
  if (dateInput) {
    dateInput.value = entry?.date || getCurrentKarteDateValue();
  }
  VITAL_ITEMS.filter(item => !item.computed).forEach(item => {
    const input = modal.querySelector(`[data-vital-input="${item.key}"]`);
    if (input) input.value = formatVitalValue(entry?.values?.[item.key]);
  });
}

function ensureVitalAddModal() {
  let modal = document.getElementById('vital-add-modal');
  if (modal) return modal;

  modal = document.createElement('div');
  modal.id = 'vital-add-modal';
  modal.className = 'modal hidden';
  modal.innerHTML = `
    <div class="modal-content modal-vital" role="dialog" aria-modal="true" aria-labelledby="vital-add-title">
      <div class="modal-header">
        <h3 id="vital-add-title">バイタル追加</h3>
        <button type="button" class="modal-close" id="vital-add-close" title="閉じる">&times;</button>
      </div>
      <div class="modal-body vital-modal-body">
        <form id="vital-add-form" class="vital-add-form">
          <label class="vital-input-row">
            <span>測定日</span>
            <input type="date" id="vital-measured-date" class="form-input">
            <span></span>
          </label>
          ${VITAL_ITEMS.filter(item => !item.computed).map(item => `
            <label class="vital-input-row">
              <span>${escapeHtml(item.label)}</span>
              <input type="text" inputmode="decimal" class="form-input" data-vital-input="${escapeHtml(item.key)}">
              <span class="vital-input-unit">${escapeHtml(item.unit)}</span>
            </label>
          `).join('')}
        </form>
      </div>
      <div class="modal-footer vital-modal-footer">
        <button type="button" class="btn btn-outline" id="vital-add-cancel">キャンセル</button>
        <button type="button" class="btn btn-primary" id="vital-add-save">登録</button>
        <button type="button" class="btn btn-primary" id="vital-add-copy">登録して複写</button>
      </div>
    </div>
  `;
  document.body.appendChild(modal);

  modal.querySelector('#vital-add-form')?.addEventListener('submit', event => event.preventDefault());
  modal.querySelector('#vital-add-close')?.addEventListener('click', closeVitalAddModal);
  modal.querySelector('#vital-add-cancel')?.addEventListener('click', closeVitalAddModal);
  modal.querySelector('#vital-add-save')?.addEventListener('click', () => saveVitalFromModal(false));
  modal.querySelector('#vital-add-copy')?.addEventListener('click', () => saveVitalFromModal(true));
  modal.addEventListener('click', event => {
    if (event.target === modal) closeVitalAddModal();
  });

  return modal;
}

function openVitalAddModal() {
  if (!currentPatient?.id) {
    showToast('患者を選択してください', 'error');
    return;
  }
  const modal = ensureVitalAddModal();
  setVitalModalValues(modal, getCurrentVitalDraftEntry());
  modal.classList.remove('hidden');
  setTimeout(() => modal.querySelector('#vital-measured-date')?.focus(), 0);
}

function closeVitalAddModal() {
  document.getElementById('vital-add-modal')?.classList.add('hidden');
}

function readVitalModalEntry(modal) {
  const date = normalizeKarteDateValue(modal.querySelector('#vital-measured-date')?.value) || getCurrentKarteDateValue();
  const values = {};
  VITAL_ITEMS.filter(item => !item.computed).forEach(item => {
    const input = modal.querySelector(`[data-vital-input="${item.key}"]`);
    const value = parseVitalNumber(input?.value);
    if (value !== null) values[item.key] = value;
  });
  values.bmi = calculateVitalBmi(values.weight, values.height);
  return { date, values };
}

function applyVitalEntryToCurrentRecord(entry) {
  const payload = normalizeKarteVitalSigns(currentRecordVitalSigns);
  payload.measured_at = entry.date;
  payload.measured_date = entry.date;
  VITAL_ITEMS.filter(item => !item.computed).forEach(item => {
    if (Object.prototype.hasOwnProperty.call(entry.values, item.key)) {
      payload[item.storeKey] = entry.values[item.key];
    } else {
      delete payload[item.storeKey];
    }
  });
  currentRecordVitalSigns = payload;
}

function formatVitalEntryForKarte(entry) {
  const parts = [];
  const systolic = parseVitalNumber(entry.values.systolic);
  const diastolic = parseVitalNumber(entry.values.diastolic);
  if (systolic !== null && diastolic !== null) {
    parts.push(`血圧 ${formatVitalValue(systolic)}/${formatVitalValue(diastolic)} mmHg`);
  } else {
    ['systolic', 'diastolic'].forEach(key => {
      const item = getVitalItem(key);
      const text = formatVitalValueWithUnit(entry.values[key], item);
      if (text) parts.push(`${item.label} ${text}`);
    });
  }
  ['pulse', 'temperature', 'spo2', 'weight', 'height', 'abdomen', 'head', 'chest'].forEach(key => {
    const item = getVitalItem(key);
    const text = formatVitalValueWithUnit(entry.values[key], item);
    if (text) parts.push(`${item.label} ${text}`);
  });
  return parts.length ? `${formatVitalDateShort(entry.date)} ${parts.join('、')}` : '';
}

function ensureKarteEditorReadyForVitalInput() {
  const editor = document.getElementById('karte-editor');
  if (!editor) return;
  const wasEmptyState = editor.classList.contains('karte-empty-state');
  activateKarteEditorForEditing();
  if (wasEmptyState) {
    editor.innerHTML = getKarteTemplate();
    resetKarteFormattingState();
  }
}

function appendTextToKarteEditor(text) {
  const normalizedText = String(text || '').trim();
  if (!normalizedText) return;
  const editor = document.getElementById('karte-editor');
  if (!editor) return;

  if (editor.classList.contains('karte-empty-state')) {
    activateKarteEditorForEditing();
    editor.innerHTML = getKarteTemplate();
  }

  const currentText = (editor.textContent || '').trim();
  const paragraph = document.createElement('p');
  paragraph.textContent = normalizedText;
  if (!currentText) {
    editor.innerHTML = '';
  }
  editor.appendChild(paragraph);
  editor.focus();
  saveCurrentPatientBilling();
}

function appendVitalCellToKarte(entryIndex, itemKey) {
  const entry = currentVitalEntries[Number(entryIndex)];
  const item = getVitalItem(itemKey);
  if (!entry || !item) return;
  const text = formatVitalValueWithUnit(entry.values[item.key], item);
  if (!text) return;
  appendTextToKarteEditor(`${formatVitalDateShort(entry.date)} ${item.label} ${text}`);
  showToast('バイタル値を主訴・所見へ反映しました', 'success');
}

async function persistCurrentVitalRecord() {
  if (!currentPatient?.id || !window.RecordAPI) {
    saveCurrentPatientBilling();
    return null;
  }

  await ensureCurrentReceptionForRecordSave();
  const date = getCurrentKarteDateValue();
  const payload = buildCurrentKarteSavePayload();
  const result = await RecordAPI.save(payload);
  currentRecordId = result.id || currentRecordId;
  currentRecordVisitDate = date;
  clearPatientBillingData(currentPatient.id, date);
  resetKarteDirtyTracking();
  updateKarteHeaderContext('承認');
  return result;
}

async function saveVitalFromModal(copyToKarte) {
  const modal = ensureVitalAddModal();
  const saveButtons = [modal.querySelector('#vital-add-save'), modal.querySelector('#vital-add-copy')].filter(Boolean);
  const entry = readVitalModalEntry(modal);

  if (!hasVitalValues(entry.values)) {
    showToast('バイタル値を1つ以上入力してください', 'error');
    return;
  }

  try {
    saveButtons.forEach(button => button.disabled = true);
    showLoading();
    ensureKarteEditorReadyForVitalInput();
    applyVitalEntryToCurrentRecord(entry);
    if (copyToKarte) {
      appendTextToKarteEditor(formatVitalEntryForKarte(entry));
    } else {
      saveCurrentPatientBilling();
    }
    await persistCurrentVitalRecord();
    hideLoading();
    closeVitalAddModal();
    showToast(copyToKarte ? 'バイタルを登録して主訴・所見へ反映しました' : 'バイタルを登録しました', 'success');
    await renderPatientVitals(currentPatient.id);
    if (currentPatient.patient_no) {
      await renderPatientHistoryFromAPI(currentPatient.id);
    } else {
      renderPatientHistory(currentPatient.id);
    }
  } catch (error) {
    hideLoading();
    saveCurrentPatientBilling();
    console.error('バイタル登録エラー:', error);
    showToast('バイタルの登録に失敗しました: ' + error.message, 'error');
  } finally {
    saveButtons.forEach(button => button.disabled = false);
  }
}

function initVitalPanel() {
  document.getElementById('btn-add-vital')?.addEventListener('click', openVitalAddModal);
  document.getElementById('btn-refresh-vital')?.addEventListener('click', () => renderPatientVitals(currentPatient?.id));
  document.querySelectorAll('.vital-view-tab').forEach(tab => {
    tab.addEventListener('click', () => switchVitalView(tab.dataset.vitalView || 'graph'));
  });

  document.getElementById('vital-data')?.addEventListener('change', event => {
    const checkbox = event.target.closest('[data-vital-graph-item]');
    if (!checkbox) return;
    const selection = new Set(
      [...document.querySelectorAll('[data-vital-graph-item]:checked')]
        .map(input => input.dataset.vitalGraphItem)
        .filter(Boolean)
    );
    saveVitalGraphSelection(selection);
    renderVitalPanels();
  });

  document.getElementById('vital-data')?.addEventListener('click', event => {
    const button = event.target.closest('.vital-cell-button');
    if (!button) return;
    appendVitalCellToKarte(button.dataset.vitalEntryIndex, button.dataset.vitalItemKey);
  });
}

function clearClinicalSidebarData() {
  const containers = [
    ['history-list', '診療履歴がありません。'],
    ['interview-data', '問診票が登録されていません。'],
    ['allergy-list', 'アレルギーが登録されていません。'],
    ['adverse-drug-list', '副作用薬が登録されていません。'],
    ['regular-drug-list', '常用薬が登録されていません。'],
    ['past-history-list', '既往歴が登録されていません。'],
    ['labresult-list', '検査結果が登録されていません。'],
    ['medication-history-list', '投薬履歴が登録されていません。'],
    ['phr-list', 'PHR情報が登録されていません。'],
    ['summary-list', 'サマリーを表示する患者を選択してください。'],
    ['periodic-list', '定期登録がありません。'],
    ['online-qualification-list', 'オン資等の確認状態がありません。'],
    ['file-list', 'ファイルが登録されていません。'],
    ['disease-list', '傷病名が登録されていません。']
  ];

  containers.forEach(([id, message]) => {
    const element = document.getElementById(id);
    if (element) {
      if (id === 'file-list') {
        element.classList.remove('has-files');
        element.innerHTML = renderEmptyPatientFileDropzone();
      } else if (id === 'medication-history-list') {
        element.innerHTML = '<div class="m3-medication-history-empty">投薬履歴が登録されていません。</div>';
      } else if (['allergy-list', 'adverse-drug-list', 'regular-drug-list', 'past-history-list'].includes(id)) {
        element.innerHTML = `<div class="clinical-profile-empty">${escapeHtml(message)}</div>`;
      } else {
        element.innerHTML = emptyClinicalMessage(message);
      }
    }
  });

  clearVitalPanel();
}

let currentPatientFiles = [];
let editingPatientFileNameId = null;
const patientFileObjectUrls = new Map();
let pendingPatientFileUploadFiles = [];
const PATIENT_FILE_ALLOWED_EXTENSIONS = new Set(['txt', 'pdf', 'jpg', 'jpeg', 'png', 'doc', 'docx', 'xls', 'xlsx', 'jfif']);
const PATIENT_FILE_STORAGE_LIMIT_BYTES = 10 * 1024 * 1024 * 1024;

function blobToDataUrl(blob) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result || '');
    reader.onerror = () => reject(reader.error);
    reader.readAsDataURL(blob);
  });
}

function dataUrlToBlob(dataUrl, fallbackType = 'application/octet-stream') {
  const text = String(dataUrl || '');
  const match = text.match(/^data:([^;,]+)?(;base64)?,(.*)$/);
  if (!match) return new Blob([], { type: fallbackType });
  const mimeType = match[1] || fallbackType;
  const isBase64 = Boolean(match[2]);
  const payload = match[3] || '';
  const binary = isBase64 ? atob(payload) : decodeURIComponent(payload);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) {
    bytes[i] = binary.charCodeAt(i);
  }
  return new Blob([bytes], { type: mimeType });
}

function normalizePatientFileRecord(raw = {}) {
  return {
    id: raw.id,
    patient_id: raw.patient_id || raw.patientId,
    record_id: raw.record_id || raw.recordId || null,
    date: normalizeKarteDateValue(raw.date || raw.file_date || raw.fileDate || raw.created_at || raw.createdAt),
    name: raw.name || raw.original_name || raw.originalName || 'ファイル',
    original_name: raw.original_name || raw.originalName || raw.name || '',
    type: raw.type || raw.content_type || raw.contentType || inferFileMimeType(raw.name || raw.original_name || ''),
    content_type: raw.content_type || raw.contentType || raw.type || inferFileMimeType(raw.name || raw.original_name || ''),
    size: Number(raw.size || 0),
    data_url: raw.data_url || raw.dataUrl || '',
    remarks: raw.remarks || '',
    document_kind: raw.document_kind || raw.documentKind || '',
    document_template_id: raw.document_template_id || raw.documentTemplateId || '',
    source_template_name: raw.source_template_name || raw.sourceTemplateName || '',
    output_type: raw.output_type || raw.outputType || '',
    file_category: raw.file_category || raw.fileCategory || '',
    created_at: raw.created_at || raw.createdAt || '',
    updated_at: raw.updated_at || raw.updatedAt || ''
  };
}

function getPatientFilesFromApiResult(result) {
  const rows = Array.isArray(result)
    ? result
    : (Array.isArray(result?.items)
      ? result.items
      : (Array.isArray(result?.data)
        ? result.data
        : (Array.isArray(result?.files) ? result.files : [])));
  return rows
    .map(normalizePatientFileRecord)
    .filter(file => file.id && file.patient_id);
}

function getPatientFileApi() {
  return typeof PatientAPI !== 'undefined' ? PatientAPI : null;
}

function initPatientFilePanel() {
  const input = document.getElementById('patient-file-input');
  const dropzone = document.getElementById('file-list');
  const addButton = document.getElementById('btn-add-patient-file');
  const selectButton = document.getElementById('btn-select-patient-file');
  const refreshButton = document.getElementById('btn-refresh-patient-files');
  const documentCreateButton = document.getElementById('btn-patient-document-create');
  const documentTemplateButton = document.getElementById('btn-patient-document-template');

  if (input) {
    input.accept = Array.from(PATIENT_FILE_ALLOWED_EXTENSIONS).map(ext => `.${ext}`).join(',');
  }

  const openPicker = () => {
    if (!currentPatient) {
      showToast('患者を選択してください', 'error');
      return;
    }
    input?.click();
  };

  addButton?.addEventListener('click', openPicker);
  selectButton?.addEventListener('click', openPicker);
  refreshButton?.addEventListener('click', () => loadPatientFiles(currentPatient?.id));
  dropzone?.addEventListener('click', handlePatientFileActionClick);
  documentCreateButton?.addEventListener('click', (event) => {
    event.preventDefault();
    event.stopPropagation();
    openPatientDocumentCreateModal();
  });
  documentTemplateButton?.addEventListener('pointerdown', (event) => {
    handlePatientDocumentTemplateButtonActivation(event, documentTemplateButton, 'pointer');
  });
  documentTemplateButton?.addEventListener('click', (event) => {
    handlePatientDocumentTemplateButtonActivation(event, documentTemplateButton, 'click');
  });

  input?.addEventListener('change', async () => {
    await addPatientFiles(input.files);
    input.value = '';
  });

  if (dropzone) {
    ['dragenter', 'dragover'].forEach(eventName => {
      dropzone.addEventListener(eventName, (event) => {
        event.preventDefault();
        dropzone.classList.add('dragover');
      });
    });
    ['dragleave', 'drop'].forEach(eventName => {
      dropzone.addEventListener(eventName, (event) => {
        event.preventDefault();
        dropzone.classList.remove('dragover');
      });
    });
    dropzone.addEventListener('drop', (event) => addPatientFiles(event.dataTransfer?.files));
    if (!dropzone.innerHTML.trim() || dropzone.querySelector('.m3-memo-content.empty')) {
      dropzone.classList.remove('has-files');
      dropzone.innerHTML = renderEmptyPatientFileDropzone();
    }
  }
}

async function handlePatientFileActionClick(event) {
  const actionButton = event.target.closest?.('[data-patient-file-action]');
  if (!actionButton || !event.currentTarget.contains(actionButton)) return;

  event.preventDefault();
  event.stopPropagation();

  const fileId = actionButton.dataset.patientFileId;
  if (!fileId) return;

  if (actionButton.dataset.patientFileAction === 'download') {
    downloadPatientFile(fileId);
    return;
  }

  if (actionButton.dataset.patientFileAction === 'edit') {
    await editPatientFileName(fileId);
  }
}

function ensurePatientFileUploadModal() {
  let modal = document.getElementById('patient-file-upload-modal');
  if (modal) return modal;

  modal = document.createElement('div');
  modal.id = 'patient-file-upload-modal';
  modal.className = 'modal hidden patient-file-upload-modal';
  modal.innerHTML = `
    <div class="modal-content modal-patient-file-name">
      <div class="modal-header">
        <h3>添付ファイル追加</h3>
        <button type="button" class="modal-close" id="patient-file-upload-close">&times;</button>
      </div>
      <div class="modal-body">
        <div class="patient-file-upload-list" id="patient-file-upload-list"></div>
        <div class="form-group">
          <label for="patient-file-upload-date">日付</label>
          <input type="date" id="patient-file-upload-date" class="form-input">
        </div>
        <div class="form-group">
          <label for="patient-file-upload-remarks">備考</label>
          <textarea id="patient-file-upload-remarks" class="form-input" rows="3"></textarea>
        </div>
      </div>
      <div class="modal-footer patient-file-name-footer">
        <button type="button" class="btn btn-outline" id="patient-file-upload-cancel">キャンセル</button>
        <button type="button" class="btn btn-primary" id="patient-file-upload-submit">追加</button>
      </div>
    </div>
  `;
  document.body.appendChild(modal);
  modal.querySelector('#patient-file-upload-close')?.addEventListener('click', closePatientFileUploadModal);
  modal.querySelector('#patient-file-upload-cancel')?.addEventListener('click', closePatientFileUploadModal);
  modal.querySelector('#patient-file-upload-submit')?.addEventListener('click', savePendingPatientFileUpload);
  modal.addEventListener('click', event => {
    if (event.target === modal) closePatientFileUploadModal();
  });
  return modal;
}

function openPatientFileUploadModal(files) {
  pendingPatientFileUploadFiles = Array.from(files || []);
  if (!pendingPatientFileUploadFiles.length) return;
  const modal = ensurePatientFileUploadModal();
  const list = modal.querySelector('#patient-file-upload-list');
  const dateInput = modal.querySelector('#patient-file-upload-date');
  const remarksInput = modal.querySelector('#patient-file-upload-remarks');
  if (list) {
    list.innerHTML = pendingPatientFileUploadFiles.map(file => `
      <div class="patient-file-upload-item">
        <span>${escapeHtml(file.name)}</span>
        <small>${escapeHtml(formatFileSize(file.size))}</small>
      </div>
    `).join('');
  }
  if (dateInput) dateInput.value = getCurrentKarteDateValue() || getLocalDateString();
  if (remarksInput) remarksInput.value = '';
  modal.classList.remove('hidden');
  setTimeout(() => remarksInput?.focus(), 0);
}

function closePatientFileUploadModal() {
  document.getElementById('patient-file-upload-modal')?.classList.add('hidden');
  pendingPatientFileUploadFiles = [];
}

async function savePendingPatientFileUpload() {
  const files = [...pendingPatientFileUploadFiles];
  if (!files.length) {
    closePatientFileUploadModal();
    return;
  }
  const submit = document.getElementById('patient-file-upload-submit');
  if (submit) submit.disabled = true;
  try {
    await savePatientFilesWithMetadata(files, {
      date: normalizeKarteDateValue(document.getElementById('patient-file-upload-date')?.value) || getLocalDateString(),
      remarks: document.getElementById('patient-file-upload-remarks')?.value || ''
    });
    closePatientFileUploadModal();
  } finally {
    if (submit) submit.disabled = false;
  }
}

async function addPatientFiles(fileList) {
  if (!currentPatient) {
    showToast('患者を選択してください', 'error');
    return;
  }
  const api = getPatientFileApi();
  if (!api?.addFile) {
    showToast('患者ファイルAPIが利用できません', 'error');
    return;
  }
  const sourceFiles = Array.from(fileList || []).filter(file => file && file.size >= 0);
  const rejected = sourceFiles.filter(file => !isAllowedPatientFileName(file.name));
  if (rejected.length) {
    showToast(`添付できない形式があります: ${getPatientFileAllowedExtensionsLabel()}`, 'error');
  }
  const files = sourceFiles.filter(file => isAllowedPatientFileName(file.name));
  if (!files.length) return;

  openPatientFileUploadModal(files);
}

async function savePatientFilesWithMetadata(files, metadata = {}) {
  const api = getPatientFileApi();
  if (!currentPatient?.id || !api?.addFile) {
    showToast('患者ファイルAPIが利用できません', 'error');
    return;
  }
  let savedCount = 0;
  try {
    const date = normalizeKarteDateValue(metadata.date) || getCurrentKarteDateValue() || getLocalDateString();
    const remarks = String(metadata.remarks || '').trim();
    for (const file of files) {
      const dataUrl = await blobToDataUrl(file);
      await api.addFile(currentPatient.id, {
        record_id: isUuidLike(currentRecordId) ? currentRecordId : null,
        date,
        name: file.name,
        original_name: file.name,
        content_type: file.type || inferFileMimeType(file.name),
        size: file.size,
        data_url: dataUrl,
        remarks,
        file_category: 'attachment',
        output_type: getFileExtension(file.name)
      });
      savedCount += 1;
    }
    await loadPatientFiles(currentPatient.id);
    await loadPatientFileStorageUsage();
    showToast(`${savedCount}件のファイルを追加しました`, 'success');
  } catch (error) {
    console.error('ファイル追加エラー:', error);
    await loadPatientFiles(currentPatient.id);
    const prefix = savedCount > 0 ? `${savedCount}件を追加後、` : '';
    showToast(`${prefix}ファイルの追加に失敗しました: ${error?.message || '不明なエラー'}`, 'error');
  }
}

async function loadPatientFiles(patientId = currentPatient?.id) {
  const container = document.getElementById('file-list');
  if (!container) return;
  if (!patientId) {
    currentPatientFiles = [];
    renderPatientFileStorageUsage(null);
    container.classList.remove('has-files');
    container.innerHTML = renderEmptyPatientFileDropzone();
    return;
  }
  container.classList.remove('has-files');
  container.innerHTML = renderEmptyPatientFileDropzone('ファイルを読み込み中です。');

  try {
    const api = getPatientFileApi();
    if (!api?.listFiles) throw new Error('PatientAPI.listFiles is not available');
    const result = await api.listFiles(patientId);
    currentPatientFiles = getPatientFilesFromApiResult(result)
      .filter(item => String(item.patient_id) === String(patientId))
      .sort((a, b) => String(b.created_at || '').localeCompare(String(a.created_at || '')));
    renderPatientFiles();
    await loadPatientFileStorageUsage();
  } catch (error) {
    console.error('患者ファイル取得エラー:', error);
    currentPatientFiles = [];
    renderPatientFileStorageUsage(null);
    container.classList.remove('has-files');
    container.innerHTML = renderEmptyPatientFileDropzone('ファイルを取得できませんでした。');
  }
}

function renderPatientFileHead() {
  return `
    <div class="patient-file-head">
      <span>日付</span><span>備考</span><span>ファイル名</span><span></span><span></span><span></span>
    </div>
  `;
}

function renderEmptyPatientFileDropzone(message = 'ここにファイルをドロップできます') {
  return `
    <div class="patient-file-table is-empty">
      ${renderPatientFileHead()}
      <div class="patient-file-empty-message">${escapeHtml(message)}</div>
    </div>
  `;
}

function revokePatientFileObjectUrls() {
  patientFileObjectUrls.forEach(url => URL.revokeObjectURL(url));
  patientFileObjectUrls.clear();
}

function getPatientFileObjectUrl(file) {
  if (file?.data_url) return file.data_url;
  if (!file?.blob) return '';
  if (!patientFileObjectUrls.has(file.id)) {
    patientFileObjectUrls.set(file.id, URL.createObjectURL(file.blob));
  }
  return patientFileObjectUrls.get(file.id);
}

function inferFileMimeType(name = '') {
  const lower = name.toLowerCase();
  if (lower.endsWith('.txt')) return 'text/plain';
  if (lower.endsWith('.pdf')) return 'application/pdf';
  if (lower.endsWith('.docx')) return 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';
  if (lower.endsWith('.doc')) return 'application/msword';
  if (lower.endsWith('.xlsx')) return 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';
  if (lower.endsWith('.xls')) return 'application/vnd.ms-excel';
  if (lower.endsWith('.png')) return 'image/png';
  if (lower.endsWith('.jpg') || lower.endsWith('.jpeg') || lower.endsWith('.jfif')) return 'image/jpeg';
  return 'application/octet-stream';
}

function formatFileSize(size) {
  const value = Number(size || 0);
  if (value >= 1024 * 1024) return `${(value / 1024 / 1024).toFixed(1)}MB`;
  if (value >= 1024) return `${Math.ceil(value / 1024)}KB`;
  return `${value}B`;
}

function formatStorageSize(size) {
  const value = Number(size || 0);
  if (value >= 1024 * 1024 * 1024) return `${(value / 1024 / 1024 / 1024).toFixed(2)}GB`;
  if (value >= 1024 * 1024) return `${(value / 1024 / 1024).toFixed(1)}MB`;
  if (value >= 1024) return `${Math.ceil(value / 1024)}KB`;
  return `${value}B`;
}

function renderPatientFileStorageUsage(usage = null) {
  const element = document.getElementById('patient-file-storage-usage');
  if (!element) return;
  if (!usage) {
    element.textContent = '';
    element.title = '';
    return;
  }
  const used = Number(usage.used_bytes ?? usage.usedBytes ?? 0);
  const limit = Number(usage.limit_bytes ?? usage.limitBytes ?? PATIENT_FILE_STORAGE_LIMIT_BYTES);
  element.textContent = `${formatStorageSize(used)} / ${formatStorageSize(limit)}`;
  element.title = `施設ファイル使用量: ${formatStorageSize(used)} / ${formatStorageSize(limit)}`;
}

async function loadPatientFileStorageUsage() {
  const api = getPatientFileApi();
  if (!api?.getFileStorageUsage) {
    renderPatientFileStorageUsage(null);
    return;
  }
  try {
    renderPatientFileStorageUsage(await api.getFileStorageUsage());
  } catch (error) {
    console.error('患者ファイル容量取得エラー:', error);
    renderPatientFileStorageUsage(null);
  }
}

function renderPatientFilePreview(file) {
  const type = file.type || inferFileMimeType(file.name);
  if (type.startsWith('image/')) {
    return `<img src="${getPatientFileObjectUrl(file)}" alt="${escapeHtml(file.name)}">`;
  }
  const lowerName = String(file.name || '').toLowerCase();
  const icon = type.includes('pdf') || lowerName.endsWith('.pdf')
    ? 'fa-file-pdf'
    : lowerName.endsWith('.doc') || lowerName.endsWith('.docx')
      ? 'fa-file-word'
      : lowerName.endsWith('.xls') || lowerName.endsWith('.xlsx')
        ? 'fa-file-excel'
        : 'fa-file-alt';
  return `<span class="patient-file-icon"><i class="fas ${icon}"></i></span>`;
}

function renderPatientFiles() {
  const container = document.getElementById('file-list');
  if (!container) return;
  revokePatientFileObjectUrls();

  if (!currentPatientFiles.length) {
    container.classList.remove('has-files');
    container.innerHTML = renderEmptyPatientFileDropzone();
    return;
  }

  container.classList.add('has-files');
  container.innerHTML = `
    <div class="patient-file-table">
      ${renderPatientFileHead()}
      ${currentPatientFiles.map(file => {
        const typeLabel = file.document_kind === 'referral_letter'
          ? '診療情報提供書'
          : (file.file_category === 'attachment' ? '添付' : '文書');
        const meta = [
          typeLabel,
          file.source_template_name,
          formatFileSize(file.size)
        ].filter(Boolean).join(' / ');
        return `
        <div class="patient-file-row">
          <span class="patient-file-date">${escapeHtml(formatDateSlash(file.date))}</span>
          <span class="patient-file-remarks" title="${escapeHtml(file.remarks || '')}">
            ${file.remarks ? escapeHtml(file.remarks) : '<span class="patient-file-muted">-</span>'}
          </span>
          <span class="patient-file-name" title="${escapeHtml(file.original_name || file.name)}">
            ${escapeHtml(file.name)}
            <small>${escapeHtml(meta)}</small>
          </span>
          <span class="patient-file-preview">${renderPatientFilePreview(file)}</span>
          <button type="button" class="patient-file-action" data-patient-file-action="download" data-patient-file-id="${escapeHtml(file.id)}" title="ダウンロード" aria-label="ダウンロード">
            <i class="fas fa-download"></i>
          </button>
          <button type="button" class="patient-file-action" data-patient-file-action="edit" data-patient-file-id="${escapeHtml(file.id)}" title="ファイル名を編集" aria-label="ファイル名を編集">
            <i class="fas fa-pen"></i>
          </button>
        </div>
      `}).join('')}
    </div>
  `;
}

function findPatientFile(fileId) {
  return currentPatientFiles.find(file => file.id === fileId);
}

function downloadPatientFile(fileId) {
  const file = findPatientFile(fileId);
  if (!file?.blob && !file?.data_url) return;
  const url = file.data_url || URL.createObjectURL(file.blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = file.name || file.original_name || 'download';
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  if (!file.data_url) {
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  }
}

function downloadBlobAsFile(blob, fileName) {
  if (!blob) return;
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = fileName || 'download';
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

function ensurePatientFileNameModal() {
  let modal = document.getElementById('patient-file-name-modal');
  if (modal) return modal;

  modal = document.createElement('div');
  modal.id = 'patient-file-name-modal';
  modal.className = 'modal hidden';
  modal.innerHTML = `
    <div class="modal-content modal-patient-file-name">
      <div class="modal-header">
        <h3>添付ファイル編集</h3>
        <button type="button" class="modal-close" id="patient-file-name-close">&times;</button>
      </div>
      <div class="modal-body">
        <div class="form-group">
          <label for="patient-file-date-input">日付</label>
          <input type="date" id="patient-file-date-input" class="form-input">
        </div>
        <div class="form-group">
          <label for="patient-file-remarks-input">備考</label>
          <textarea id="patient-file-remarks-input" class="form-input" rows="3"></textarea>
        </div>
        <div class="form-group">
          <label for="patient-file-name-input">ファイル名</label>
          <input type="text" id="patient-file-name-input" class="form-input">
        </div>
      </div>
      <div class="modal-footer patient-file-name-footer">
        <button type="button" class="btn btn-danger-soft" id="patient-file-name-delete">削除</button>
        <div class="patient-file-name-actions">
          <button type="button" class="btn btn-outline" id="patient-file-name-cancel">キャンセル</button>
          <button type="button" class="btn btn-primary" id="patient-file-name-save">保存</button>
        </div>
      </div>
    </div>
  `;
  document.body.appendChild(modal);

  const input = modal.querySelector('#patient-file-name-input');
  modal.querySelector('#patient-file-name-close')?.addEventListener('click', closePatientFileNameModal);
  modal.querySelector('#patient-file-name-cancel')?.addEventListener('click', closePatientFileNameModal);
  modal.querySelector('#patient-file-name-save')?.addEventListener('click', savePatientFileNameFromModal);
  modal.querySelector('#patient-file-name-delete')?.addEventListener('click', deletePatientFileFromModal);
  input?.addEventListener('keydown', (event) => {
    if (event.key === 'Enter') {
      event.preventDefault();
      savePatientFileNameFromModal();
    }
    if (event.key === 'Escape') {
      closePatientFileNameModal();
    }
  });
  modal.addEventListener('click', (event) => {
    if (event.target === modal) closePatientFileNameModal();
  });

  return modal;
}

function openPatientFileNameModal(fileId) {
  const file = findPatientFile(fileId);
  if (!file) {
    showToast('編集対象のファイルが見つかりません。再読み込みしてください', 'error');
    return;
  }

  editingPatientFileNameId = fileId;
  const modal = ensurePatientFileNameModal();
  const input = modal.querySelector('#patient-file-name-input');
  const dateInput = modal.querySelector('#patient-file-date-input');
  const remarksInput = modal.querySelector('#patient-file-remarks-input');
  if (input) {
    input.value = file.name || file.original_name || '';
  }
  if (dateInput) dateInput.value = normalizeKarteDateValue(file.date) || getLocalDateString();
  if (remarksInput) remarksInput.value = file.remarks || '';
  modal.classList.remove('hidden');
  setTimeout(() => {
    remarksInput?.focus();
  }, 0);
}

function closePatientFileNameModal() {
  const modal = document.getElementById('patient-file-name-modal');
  modal?.classList.add('hidden');
  editingPatientFileNameId = null;
}

async function savePatientFileNameFromModal() {
  const fileId = editingPatientFileNameId;
  const nameInput = document.getElementById('patient-file-name-input');
  const dateInput = document.getElementById('patient-file-date-input');
  const remarksInput = document.getElementById('patient-file-remarks-input');
  if (!fileId || !nameInput) return;
  const saved = await savePatientFileName(fileId, nameInput.value, {
    date: dateInput?.value || null,
    remarks: remarksInput?.value || ''
  });
  if (saved) closePatientFileNameModal();
}

async function deletePatientFileFromModal() {
  const fileId = editingPatientFileNameId;
  const file = findPatientFile(fileId);
  if (!file) {
    showToast('削除対象のファイルが見つかりません。再読み込みしてください', 'error');
    return;
  }

  const confirmed = await showAppConfirm({
    title: 'ファイルの削除',
    message: `${file.name || file.original_name || 'このファイル'} を削除しますか？`,
    confirmText: '削除',
    cancelText: 'キャンセル'
  });
  if (!confirmed) return;

  closePatientFileNameModal();
  await deletePatientFile(fileId);
}

async function savePatientFileName(fileId, nextName, extra = {}) {
  const file = findPatientFile(fileId);
  if (!file) {
    showToast('編集対象のファイルが見つかりません。再読み込みしてください', 'error');
    return false;
  }
  const trimmed = nextName.trim();
  if (!trimmed) {
    showToast('ファイル名を入力してください', 'error');
    return false;
  }

  try {
    const api = getPatientFileApi();
    if (!currentPatient?.id || !api?.updateFile) {
      throw new Error('患者ファイルAPIが利用できません');
    }
    const payload = {
      name: trimmed,
      date: normalizeKarteDateValue(extra.date) || null,
      remarks: String(extra.remarks || '').trim()
    };
    const updated = normalizePatientFileRecord(await api.updateFile(currentPatient.id, fileId, payload));
    const index = currentPatientFiles.findIndex(item => String(item.id) === String(fileId));
    if (index >= 0) currentPatientFiles[index] = updated;
    await loadPatientFiles(currentPatient.id);
    showToast('ファイル情報を更新しました', 'success');
    return true;
  } catch (error) {
    console.error('患者ファイル名更新エラー:', error);
    showToast(`ファイル情報の更新に失敗しました: ${error?.message || '不明なエラー'}`, 'error');
    return false;
  }
}

async function deletePatientFile(fileId) {
  if (!fileId) return false;

  try {
    const api = getPatientFileApi();
    if (!currentPatient?.id || !api?.deleteFile) {
      throw new Error('患者ファイルAPIが利用できません');
    }
    await api.deleteFile(currentPatient.id, fileId);
    currentPatientFiles = currentPatientFiles.filter(file => String(file.id) !== String(fileId));
    await loadPatientFiles(currentPatient.id);
    await loadPatientFileStorageUsage();
    showToast('ファイルを削除しました', 'info');
    return true;
  } catch (error) {
    console.error('患者ファイル削除エラー:', error);
    showToast(`ファイルの削除に失敗しました: ${error?.message || '不明なエラー'}`, 'error');
    return false;
  }
}

async function editPatientFileName(fileId) {
  openPatientFileNameModal(fileId);
}

window.downloadPatientFile = downloadPatientFile;
window.editPatientFileName = editPatientFileName;
window.deletePatientFile = deletePatientFile;

let currentFacilityDocumentTemplates = [];
let editingFacilityDocumentTemplateId = null;
let pendingFacilityDocumentTemplateFile = null;
let patientDocumentTemplateDropdown = null;
let patientDocumentTemplateLastPointerToggleAt = 0;
let pendingPatientDocumentTemplateForDownload = null;
