function getFileExtension(name = '') {
  const match = String(name).toLowerCase().match(/\.([a-z0-9]+)$/);
  return match ? match[1] : '';
}

function isAllowedPatientFileName(name = '') {
  return PATIENT_FILE_ALLOWED_EXTENSIONS.has(getFileExtension(name));
}

function getPatientFileAllowedExtensionsLabel() {
  return Array.from(PATIENT_FILE_ALLOWED_EXTENSIONS).map(ext => `.${ext}`).join(' / ');
}

function isFacilityDocumentTemplateFile(file) {
  const ext = getFileExtension(file?.name || '');
  return ext === 'docx' || ext === 'xlsx';
}

function getFacilityDocumentTemplateType(fileName = '') {
  const ext = getFileExtension(fileName);
  if (ext === 'docx') return 'Word';
  if (ext === 'xlsx') return 'Excel';
  return '-';
}

function getDocumentDateParts(value) {
  if (!value) return null;
  if (value instanceof Date && !Number.isNaN(value.getTime())) {
    return {
      year: value.getFullYear(),
      month: value.getMonth() + 1,
      day: value.getDate()
    };
  }

  const text = String(value).trim();
  const directMatch = text.match(/^(\d{4})[-/年](\d{1,2})[-/月](\d{1,2})/);
  if (directMatch) {
    const parts = {
      year: Number(directMatch[1]),
      month: Number(directMatch[2]),
      day: Number(directMatch[3])
    };
    if (parts.year && parts.month >= 1 && parts.month <= 12 && parts.day >= 1 && parts.day <= 31) {
      return parts;
    }
  }

  const parsed = new Date(text);
  if (Number.isNaN(parsed.getTime())) return null;
  return {
    year: parsed.getFullYear(),
    month: parsed.getMonth() + 1,
    day: parsed.getDate()
  };
}

function formatDocumentYmdDate(value, options = {}) {
  const parts = getDocumentDateParts(value);
  if (!parts) return '';
  const pad = options.pad === true;
  const month = pad ? String(parts.month).padStart(2, '0') : String(parts.month);
  const day = pad ? String(parts.day).padStart(2, '0') : String(parts.day);
  return `${parts.year}年${month}月${day}日`;
}

function getDocumentJapaneseEra(value) {
  const parts = getDocumentDateParts(value);
  if (!parts) return null;
  const eras = [
    { name: '令和', year: 2019, month: 5, day: 1 },
    { name: '平成', year: 1989, month: 1, day: 8 },
    { name: '昭和', year: 1926, month: 12, day: 25 },
    { name: '大正', year: 1912, month: 7, day: 30 },
    { name: '明治', year: 1868, month: 1, day: 25 }
  ];
  const era = eras.find(item => {
    if (parts.year !== item.year) return parts.year > item.year;
    if (parts.month !== item.month) return parts.month > item.month;
    return parts.day >= item.day;
  });
  if (!era) return null;
  return {
    name: era.name,
    eraYear: parts.year - era.year + 1,
    month: parts.month,
    day: parts.day
  };
}

function formatDocumentEraDate(value, options = {}) {
  const era = getDocumentJapaneseEra(value);
  if (!era) return '';
  const eraYear = options.padYear ? String(era.eraYear).padStart(2, '0') : String(era.eraYear);
  const month = options.padMonth ? String(era.month).padStart(2, '0') : String(era.month);
  const day = options.padDay ? String(era.day).padStart(2, '0') : String(era.day);
  return `${era.name}${eraYear}年${month}月${day}日`;
}

function formatPatientGenderLabel(value, { shortLabel = false } = {}) {
  const rawValue = value && typeof value === 'object'
    ? firstNonEmptyString(value.gender, value.sex, value.patient_gender, value.patientGender)
    : value;
  const code = normalizePatientGenderCode(rawValue);
  if (code === 'male') return shortLabel ? '男' : '男性';
  if (code === 'female') return shortLabel ? '女' : '女性';
  if (code === 'other') return shortLabel ? '他' : 'その他';
  return '';
}

function formatPatientDocumentAddressNoPostal(patient) {
  if (!patient) return '';
  const address = patient.address
    || [patient.prefecture, patient.city, patient.address1, patient.address2].filter(Boolean).join('');
  return String(address || '')
    .replace(/^〒?\d{3}-?\d{4}\s*/, '')
    .trim();
}

function getPatientDocumentAddressParts(patient = {}) {
  const postalCode = firstNonEmptyString(patient.postal_code, patient.postalCode, patient.zip_code, patient.zipCode);
  const rawAddress = formatPatientDocumentAddressNoPostal(patient);
  const tokens = rawAddress.split(/\s+/).filter(Boolean);
  const prefecture = firstNonEmptyString(patient.prefecture, tokens[0]);
  const city = firstNonEmptyString(patient.city, tokens[1]);
  const address1 = firstNonEmptyString(patient.address1, patient.address_1, patient.addressLine1, tokens.slice(2).join(' '), (!prefecture && !city ? rawAddress : ''));
  const address2 = firstNonEmptyString(patient.address2, patient.address_2, patient.addressLine2);
  const fullAddress = [postalCode ? `〒${postalCode}` : '', rawAddress].filter(Boolean).join(' ');
  return { postalCode, prefecture, city, address1, address2, fullAddress, rawAddress };
}

async function loadBuiltinDocumentTemplate(template) {
  const relativePath = `${BUILTIN_DOCUMENT_TEMPLATE_BASE}${template.file_name}`;
  let buffer = null;

  if (window.digimaster?.readAppFile) {
    buffer = window.digimaster.readAppFile(relativePath);
  } else {
    const response = await fetch(relativePath);
    if (!response.ok) {
      throw new Error(`文書ひな形を読み込めません: ${template.display_name}`);
    }
    buffer = await response.arrayBuffer();
  }

  const type = inferFileMimeType(template.file_name);
  const blob = new Blob([buffer], { type });
  return {
    ...template,
    type,
    size: blob.size,
    blob,
    source: 'builtin_document_template'
  };
}

function sanitizeDocumentFileName(value = '') {
  return String(value || '')
    .replace(/[\\/:*?"<>|]/g, '')
    .replace(/\s+/g, '')
    .trim() || '文書';
}

function normalizeFacilityDocumentTemplateRecord(raw = {}) {
  const fileName = raw.file_name || raw.fileName || raw.original_name || raw.originalName || '';
  const contentType = raw.content_type || raw.contentType || raw.type || inferFileMimeType(fileName);
  const dataUrl = raw.data_url || raw.dataUrl || '';
  return {
    id: raw.id,
    display_name: raw.display_name || raw.displayName || raw.name || '',
    original_name: raw.original_name || raw.originalName || fileName,
    file_name: fileName,
    type: contentType,
    content_type: contentType,
    size: Number(raw.size || 0),
    data_url: dataUrl,
    blob: raw.blob || (dataUrl ? dataUrlToBlob(dataUrl, contentType) : null),
    template_type: raw.template_type || raw.templateType || 'custom',
    created_at: raw.created_at || raw.createdAt || '',
    updated_at: raw.updated_at || raw.updatedAt || ''
  };
}

async function loadFacilityDocumentTemplates() {
  try {
    const api = typeof DocumentTemplateAPI !== 'undefined' ? DocumentTemplateAPI : null;
    if (!api?.list) throw new Error('文書ひな形APIが利用できません');
    const result = await api.list();
    const rows = Array.isArray(result)
      ? result
      : (Array.isArray(result?.data) ? result.data : []);
    currentFacilityDocumentTemplates = rows.map(normalizeFacilityDocumentTemplateRecord).sort((a, b) =>
      String(a.display_name || '').localeCompare(String(b.display_name || ''), 'ja')
    );
  } catch (error) {
    console.error('文書ひな形取得エラー:', error);
    currentFacilityDocumentTemplates = [];
    showToast(`文書ひな形を取得できません: ${error?.message || '不明なエラー'}`, 'error');
  }
  return currentFacilityDocumentTemplates;
}

function renderFacilityDocumentParameters() {
  const container = document.getElementById('facility-document-parameter-list');
  if (!container) return;
  container.innerHTML = `
    <table class="facility-document-parameter-table">
      <thead>
        <tr>
          <th>項目</th>
          <th>パラメータ</th>
          <th>反映内容</th>
        </tr>
      </thead>
      <tbody>
        ${FACILITY_DOCUMENT_PARAMETERS.map(parameter => `
          <tr>
            <td>${escapeHtml(parameter.item || '')}</td>
            <td>
              <button
                type="button"
                class="facility-document-parameter-copy"
                data-document-parameter-copy="${escapeHtmlAttribute(parameter.code)}"
                title="コピー"
                aria-label="${escapeHtmlAttribute(`${parameter.code} をコピー`)}"
              >
                <code>${escapeHtml(parameter.code)}</code>
                <i class="fas fa-copy" aria-hidden="true"></i>
              </button>
            </td>
            <td>${escapeHtml(parameter.content || '')}</td>
          </tr>
        `).join('')}
      </tbody>
    </table>
  `;
}

function getPublicExpenseTypeMaster(typeCode) {
  return publicExpenseTypes.find(type => String(type.type_code) === String(typeCode || '')) || null;
}

function hasPublicExpenseMunicipalityChoices(typeCode) {
  return publicExpenseMunicipalityRules.some(rule => String(rule.expense_type) === String(typeCode || ''));
}

function getSelectedPublicExpenseRule() {
  const ruleId = document.getElementById('public-expense-municipality')?.value || '';
  if (!ruleId) return null;
  return publicExpenseMunicipalityRules.find(rule => String(rule.id) === String(ruleId)) || null;
}

function getPublicExpenseDefaultValue(rule, type, key) {
  const ruleValue = rule?.[key];
  if (ruleValue !== null && ruleValue !== undefined && ruleValue !== '') return ruleValue;
  return type?.[key] ?? null;
}

function renderPublicExpenseMunicipalityOptions(selectedRuleId = '') {
  const select = document.getElementById('public-expense-municipality');
  if (!select) return;
  const typeCode = document.getElementById('public-expense-type')?.value || '';
  const rules = publicExpenseMunicipalityRules
    .filter(rule => String(rule.expense_type) === String(typeCode))
    .sort((a, b) => String(a.municipality_code || '').localeCompare(String(b.municipality_code || '')));

  if (!rules.length) {
    select.innerHTML = '<option value="">市町村差分なし</option>';
    select.disabled = true;
    syncPublicExpenseRuleNote();
    return;
  }

  select.disabled = false;
  select.innerHTML = `
    <option value="">市町村を選択</option>
    ${rules.map(rule => `
      <option value="${escapeHtml(rule.id)}">
        ${escapeHtml(`${rule.municipality_name}（${rule.municipality_code}）`)}
      </option>
    `).join('')}
  `;
  if (selectedRuleId) select.value = String(selectedRuleId);
  syncPublicExpenseRuleNote();
}

function syncPublicExpenseRuleNote() {
  const note = document.getElementById('public-expense-rule-note');
  if (!note) return;
  const rule = getSelectedPublicExpenseRule();
  const type = getPublicExpenseTypeMaster(document.getElementById('public-expense-type')?.value);
  if (rule?.requires_local_confirmation) {
    note.textContent = '市町村資料で対象年齢・所得制限・薬局扱い・負担者番号を確認してください。';
  } else {
    note.textContent = type?.remarks || '';
  }
}

function applyPublicExpenseDefaults() {
  const typeCode = document.getElementById('public-expense-type')?.value || '';
  const type = getPublicExpenseTypeMaster(typeCode);
  const rule = getSelectedPublicExpenseRule();
  const noPayerCheckbox = document.getElementById('public-expense-no-payer-number');
  const payerInput = document.getElementById('public-expense-payer-number');
  const hasBurden = [
    getPublicExpenseDefaultValue(rule, type, 'default_burden_ratio'),
    getPublicExpenseDefaultValue(rule, type, 'default_per_visit_limit'),
    getPublicExpenseDefaultValue(rule, type, 'default_daily_limit'),
    getPublicExpenseDefaultValue(rule, type, 'default_monthly_limit'),
    getPublicExpenseDefaultValue(rule, type, 'default_count_limit_per_day'),
    getPublicExpenseDefaultValue(rule, type, 'default_count_limit_per_month'),
    getPublicExpenseDefaultValue(rule, type, 'default_day_limit_per_month')
  ].some(value => value !== null && value !== undefined && value !== '');
  const burdenRadio = document.querySelector(`input[name="public-expense-burden-mode"][value="${hasBurden ? 'has' : 'none'}"]`);
  if (burdenRadio) burdenRadio.checked = true;

  if (payerInput && !payerInput.value && rule?.payer_number && !noPayerCheckbox?.checked) {
    payerInput.value = normalizeDigits(rule.payer_number).slice(0, 8);
  }
  setInputValue('public-expense-ratio-per-visit', getPublicExpenseDefaultValue(rule, type, 'default_burden_ratio') ?? '');
  setInputValue('public-expense-amount-per-visit', getPublicExpenseDefaultValue(rule, type, 'default_per_visit_limit') ?? '');
  setInputValue('public-expense-amount-per-day', getPublicExpenseDefaultValue(rule, type, 'default_daily_limit') ?? '');
  setInputValue('public-expense-count-per-day', getPublicExpenseDefaultValue(rule, type, 'default_count_limit_per_day') ?? '');
  setInputValue('public-expense-amount-per-month', getPublicExpenseDefaultValue(rule, type, 'default_monthly_limit') ?? '');
  setInputValue('public-expense-count-per-month', getPublicExpenseDefaultValue(rule, type, 'default_count_limit_per_month') ?? '');
  setInputValue('public-expense-days-per-month', getPublicExpenseDefaultValue(rule, type, 'default_day_limit_per_month') ?? '');
  setInputValue('public-expense-claim-target', rule?.claim_target || type?.claim_target || 'medical');
  setInputValue('public-expense-prescription-claim-target', rule?.prescription_claim_target || type?.prescription_claim_target || 'same_as_medical');
  syncPublicExpenseRuleNote();
  updatePublicExpenseBurdenFields();
}

function formatPublicExpenseListType(expense = {}) {
  const lawNumber = getPublicExpenseLawNumber(expense);
  const name = expense.expense_type_name || getPublicExpenseDisplayName(expense);
  return [lawNumber, name].filter(Boolean).join(' ');
}

function formatPublicExpenseLimitSummary(expense = {}) {
  const parts = [];
  if (expense.burden_ratio != null) parts.push(`${expense.burden_ratio}%`);
  if (expense.per_visit_limit != null) parts.push(`1回${Number(expense.per_visit_limit).toLocaleString()}円`);
  if (expense.daily_limit != null) parts.push(`1日${Number(expense.daily_limit).toLocaleString()}円`);
  if (expense.monthly_limit != null) parts.push(`月${Number(expense.monthly_limit).toLocaleString()}円`);
  if (expense.count_limit_per_day != null) parts.push(`1日${expense.count_limit_per_day}回`);
  if (expense.count_limit_per_month != null) parts.push(`月${expense.count_limit_per_month}回`);
  if (expense.day_limit_per_month != null) parts.push(`月${expense.day_limit_per_month}日`);
  return parts.join(' / ') || '負担なし';
}

async function writeTextToClipboard(text) {
  const value = String(text || '');
  if (!value) return false;
  if (navigator.clipboard?.writeText) {
    try {
      await navigator.clipboard.writeText(value);
      return true;
    } catch (error) {
      console.warn('クリップボードへのコピーに失敗しました。フォールバックを試します:', error);
    }
  }

  const textarea = document.createElement('textarea');
  textarea.value = value;
  textarea.setAttribute('readonly', '');
  textarea.style.position = 'fixed';
  textarea.style.top = '-1000px';
  textarea.style.left = '-1000px';
  document.body.appendChild(textarea);
  textarea.select();
  let copied = false;
  try {
    copied = document.execCommand('copy');
  } catch (error) {
    copied = false;
  } finally {
    document.body.removeChild(textarea);
  }
  return copied;
}

async function copyFacilityDocumentParameter(code) {
  const value = String(code || '').trim();
  if (!value) return;
  const copied = await writeTextToClipboard(value);
  showToast(copied ? `${value} をコピーしました` : 'パラメータをコピーできませんでした', copied ? 'success' : 'error');
}

async function renderFacilityDocuments() {
  const tbody = document.getElementById('facility-document-template-body');
  if (!tbody) return;
  tbody.innerHTML = '<tr><td colspan="5" class="facility-document-empty">文書ひな形を読み込み中...</td></tr>';
  await loadFacilityDocumentTemplates();
  renderFacilityDocumentParameters();

  if (!currentFacilityDocumentTemplates.length) {
    tbody.innerHTML = '<tr><td colspan="5" class="facility-document-empty">文書ひな形が登録されていません。</td></tr>';
    return;
  }

  tbody.innerHTML = currentFacilityDocumentTemplates.map(template => `
    <tr>
      <td>${escapeHtml(template.display_name)}</td>
      <td>
        <button type="button" class="facility-document-file-link" data-facility-document-download="${escapeHtml(template.id)}">
          ${escapeHtml(template.original_name || template.file_name)}
        </button>
        <small>${escapeHtml(formatFileSize(template.size || 0))}</small>
      </td>
      <td>${escapeHtml(getFacilityDocumentTemplateType(template.file_name || template.original_name))}</td>
      <td>${escapeHtml(formatFacilityDateTime(new Date(template.updated_at || template.created_at || Date.now())))}</td>
      <td class="facility-document-actions">
        <button type="button" class="facility-row-edit" data-facility-document-edit="${escapeHtml(template.id)}" title="編集"><i class="fas fa-pen"></i></button>
        <button type="button" class="facility-row-delete" data-facility-document-delete="${escapeHtml(template.id)}" title="削除"><i class="fas fa-trash-alt"></i></button>
      </td>
    </tr>
  `).join('');
}

function ensureFacilityDocumentTemplateModal() {
  let modal = document.getElementById('facility-document-template-modal');
  if (modal) return modal;

  modal = document.createElement('div');
  modal.id = 'facility-document-template-modal';
  modal.className = 'modal hidden facility-document-template-modal';
  modal.innerHTML = `
    <div class="facility-register-dialog facility-document-template-dialog">
      <div class="facility-register-header">
        <h3 id="facility-document-template-title">文書ひな形追加</h3>
        <button type="button" class="facility-register-close" id="facility-document-template-close">&times;</button>
      </div>
      <div class="facility-register-body">
        <label class="facility-register-row">
          <span>ひな形ファイル</span>
          <div class="facility-document-file-pick">
            <input type="file" id="facility-document-template-file" accept=".docx,.xlsx">
            <small id="facility-document-template-current-file">Word（.docx）またはExcel（.xlsx）を選択してください</small>
          </div>
        </label>
        <label class="facility-register-row">
          <span>表示名</span>
          <input type="text" id="facility-document-template-name" placeholder="紹介状">
        </label>
      </div>
      <div class="facility-register-footer">
        <button type="button" class="btn btn-outline" id="facility-document-template-cancel">キャンセル</button>
        <button type="button" class="facility-save-btn" id="facility-document-template-save">保存</button>
      </div>
    </div>
  `;
  document.body.appendChild(modal);

  modal.querySelector('#facility-document-template-close')?.addEventListener('click', closeFacilityDocumentTemplateModal);
  modal.querySelector('#facility-document-template-cancel')?.addEventListener('click', closeFacilityDocumentTemplateModal);
  modal.querySelector('#facility-document-template-save')?.addEventListener('click', saveFacilityDocumentTemplate);
  modal.querySelector('#facility-document-template-file')?.addEventListener('change', event => {
    pendingFacilityDocumentTemplateFile = event.target.files?.[0] || null;
    const currentFile = modal.querySelector('#facility-document-template-current-file');
    if (currentFile) {
      currentFile.textContent = pendingFacilityDocumentTemplateFile
        ? pendingFacilityDocumentTemplateFile.name
        : 'Word（.docx）またはExcel（.xlsx）を選択してください';
    }
  });
  modal.addEventListener('click', event => {
    if (event.target === modal) closeFacilityDocumentTemplateModal();
  });
  return modal;
}

function openFacilityDocumentTemplateModal(templateId = null) {
  const modal = ensureFacilityDocumentTemplateModal();
  const template = currentFacilityDocumentTemplates.find(item => item.id === templateId);
  editingFacilityDocumentTemplateId = template?.id || null;
  pendingFacilityDocumentTemplateFile = null;
  setTextById('facility-document-template-title', template ? '文書ひな形編集' : '文書ひな形追加');
  const fileInput = modal.querySelector('#facility-document-template-file');
  const nameInput = modal.querySelector('#facility-document-template-name');
  const currentFile = modal.querySelector('#facility-document-template-current-file');
  if (fileInput) fileInput.value = '';
  if (nameInput) {
    nameInput.value = template?.display_name || '';
    nameInput.focus();
  }
  if (currentFile) {
    currentFile.textContent = template
      ? `現在のファイル: ${template.original_name || template.file_name}`
      : 'Word（.docx）またはExcel（.xlsx）を選択してください';
  }
  modal.classList.remove('hidden');
  setTimeout(() => nameInput?.focus(), 0);
}

function closeFacilityDocumentTemplateModal() {
  document.getElementById('facility-document-template-modal')?.classList.add('hidden');
  editingFacilityDocumentTemplateId = null;
  pendingFacilityDocumentTemplateFile = null;
}

async function saveFacilityDocumentTemplate() {
  const nameInput = document.getElementById('facility-document-template-name');
  const displayName = nameInput?.value.trim() || '';
  const existing = currentFacilityDocumentTemplates.find(item => item.id === editingFacilityDocumentTemplateId);
  const file = pendingFacilityDocumentTemplateFile;

  if (!displayName) {
    showToast('表示名を入力してください', 'error');
    nameInput?.focus();
    return;
  }
  if (!existing && !file) {
    showToast('ひな形ファイルを選択してください', 'error');
    return;
  }
  if (file && !isFacilityDocumentTemplateFile(file)) {
    showToast('文書ひな形は .docx または .xlsx を選択してください', 'error');
    return;
  }
  const duplicate = currentFacilityDocumentTemplates.find(item =>
    item.id !== editingFacilityDocumentTemplateId && item.display_name === displayName
  );
  if (duplicate) {
    showToast('同じ表示名の文書ひな形は登録できません', 'error');
    nameInput?.focus();
    return;
  }

  try {
    const api = typeof DocumentTemplateAPI !== 'undefined' ? DocumentTemplateAPI : null;
    if (!api?.create || !api?.update) throw new Error('文書ひな形APIが利用できません');
    const payload = { display_name: displayName };
    if (file) {
      payload.file_name = file.name;
      payload.original_name = file.name;
      payload.content_type = file.type || inferFileMimeType(file.name);
      payload.size = file.size;
      payload.data_url = await blobToDataUrl(file);
      payload.template_type = 'custom';
    }
    if (existing) {
      await api.update(existing.id, payload);
    } else {
      await api.create(payload);
    }
    closeFacilityDocumentTemplateModal();
    await renderFacilityDocuments();
    showToast(existing ? '文書ひな形を更新しました' : '文書ひな形を登録しました', 'success');
  } catch (error) {
    console.error('文書ひな形保存エラー:', error);
    showToast(`文書ひな形を保存できませんでした: ${error?.message || '不明なエラー'}`, 'error');
  }
}

function findFacilityDocumentTemplate(templateId) {
  return currentFacilityDocumentTemplates.find(item => item.id === templateId);
}

function downloadFacilityDocumentTemplate(templateId) {
  const template = findFacilityDocumentTemplate(templateId);
  if (!template?.blob && !template?.data_url) return;
  const blob = template.blob || dataUrlToBlob(template.data_url, template.content_type || inferFileMimeType(template.file_name));
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = template.original_name || template.file_name || `${template.display_name}.docx`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

async function deleteFacilityDocumentTemplate(templateId) {
  const template = findFacilityDocumentTemplate(templateId);
  if (!template) return;
  const confirmed = await showAppConfirm({
    title: '文書ひな形の削除',
    message: `${template.display_name} を削除しますか？`,
    confirmText: '削除',
    cancelText: 'キャンセル'
  });
  if (!confirmed) return;

  try {
    const api = typeof DocumentTemplateAPI !== 'undefined' ? DocumentTemplateAPI : null;
    if (!api?.delete) throw new Error('文書ひな形APIが利用できません');
    await api.delete(templateId);
    await renderFacilityDocuments();
    showToast('文書ひな形を削除しました', 'info');
  } catch (error) {
    console.error('文書ひな形削除エラー:', error);
    showToast(`文書ひな形を削除できませんでした: ${error?.message || '不明なエラー'}`, 'error');
  }
}

function getPatientDocumentApiDiagnoses(result) {
  if (Array.isArray(result?.items)) return result.items;
  if (Array.isArray(result?.data)) return result.data;
  if (Array.isArray(result?.diagnoses)) return result.diagnoses;
  if (Array.isArray(result?.data?.items)) return result.data.items;
  if (Array.isArray(result?.data?.diagnoses)) return result.data.diagnoses;
  return [];
}

function isSamePatientId(left, right) {
  return String(left ?? '') === String(right ?? '');
}

function getPatientDocumentCachedDiagnoses(patientId = currentPatient?.id) {
  if (isSamePatientId(currentPatientDiagnosesPatientId, patientId) && Array.isArray(currentPatientDiagnoses)) {
    return currentPatientDiagnoses.map(normalizeDiagnosisItem);
  }
  return [];
}

function formatPatientDocumentDiagnosisName(item) {
  const diagnosis = normalizeDiagnosisItem(item);
  let name = String(diagnosis.full_name || diagnosis.diagnosis_name || '').trim();
  if (name && diagnosis.is_suspected && !name.includes('疑い')) {
    name = `${name}の疑い`;
  }
  return name;
}

function formatPatientDocumentDiagnosisNames(diagnoses = []) {
  return (diagnoses || [])
    .map(formatPatientDocumentDiagnosisName)
    .filter(Boolean)
    .join('、');
}

async function getPatientDocumentDiagnoses(patientId = currentPatient?.id) {
  if (!patientId) return [];
  const cached = getPatientDocumentCachedDiagnoses(patientId);
  if (cached.length || isSamePatientId(currentPatientDiagnosesPatientId, patientId)) {
    return cached;
  }

  try {
    const api = typeof DiagnosisAPI !== 'undefined' ? DiagnosisAPI : null;
    if (!api?.listByPatient) throw new Error('DiagnosisAPI is not available');
    const result = await api.listByPatient(patientId, { activeOnly: true, includeEnded: true });
    const diagnoses = getPatientDocumentApiDiagnoses(result).map(normalizeDiagnosisItem);
    currentPatientDiagnoses = diagnoses;
    currentPatientDiagnosesPatientId = patientId;
    if (currentPatient && isSamePatientId(currentPatient.id, patientId)) {
      currentPatient.diagnoses = diagnoses;
      currentPatient.diseases = diagnoses;
    }
    return diagnoses;
  } catch (error) {
    console.error('文書出力用の傷病名取得エラー:', error);
    throw new Error(`文書出力用の傷病名を取得できません: ${error?.message || '不明なエラー'}`);
  }
}

function formatPatientDocumentPrescriptionLine(prescription = {}) {
  const name = prescription.drug_name || prescription.name || '';
  const dose = prescription.dosage || prescription.quantity || '';
  const unit = prescription.unit || '';
  const frequency = prescription.frequency || prescription.usage || prescription.usage_name || '';
  const days = prescription.days ? `${prescription.days}日分` : '';
  return [name, [dose, unit].filter(Boolean).join(''), frequency, days]
    .map(value => String(value || '').trim())
    .filter(Boolean)
    .join('　');
}

async function getPatientDocumentLatestPrescriptions(patientId = currentPatient?.id) {
  const pendingLines = (Array.isArray(pendingPrescriptions) ? pendingPrescriptions : [])
    .map(formatPatientDocumentPrescriptionLine)
    .filter(Boolean);
  if (pendingLines.length) return pendingLines.join('\n');
  if (!patientId) return '';

  const api = typeof PatientAPI !== 'undefined' ? PatientAPI : null;
  if (!api?.getPrescriptionHistory) throw new Error('患者処方履歴APIが利用できません');
  const result = await api.getPrescriptionHistory(patientId, 200);
  const rows = Array.isArray(result?.data) ? result.data : (Array.isArray(result) ? result : []);
  if (!rows.length) return '';
  const latestDate = normalizeKarteDateValue(rows[0]?.visit_date || rows[0]?.prescription_date || rows[0]?.created_at);
  return rows
    .filter(row => {
      if (!latestDate) return true;
      return normalizeKarteDateValue(row.visit_date || row.prescription_date || row.created_at) === latestDate;
    })
    .map(formatPatientDocumentPrescriptionLine)
    .filter(Boolean)
    .join('\n');
}

function formatPatientDocumentLabResultLine(item) {
  if (!item) return '';
  if (typeof item === 'string') return item.trim();
  if (typeof item !== 'object') return String(item).trim();
  const name = item.name || item.item_name || item.test_name || item.label || '';
  const value = item.value ?? item.result ?? item.measured_value ?? '';
  const unit = item.unit || '';
  const dateValue = normalizeKarteDateValue(item.date || item.exam_date || item.measured_at || '');
  const main = [name, [value, unit].filter(Boolean).join('')].filter(Boolean).join(' ');
  return [dateValue ? formatDateSlash(dateValue) : '', main].filter(Boolean).join(' ');
}

function collectPatientDocumentLabLinesFromValue(value) {
  if (!value) return [];
  if (typeof value === 'string') {
    return value.split('\n').map(line => line.trim()).filter(Boolean);
  }
  if (Array.isArray(value)) {
    return value.map(formatPatientDocumentLabResultLine).filter(Boolean);
  }
  if (typeof value === 'object') {
    if (value.name || value.item_name || value.test_name || value.label) {
      const line = formatPatientDocumentLabResultLine(value);
      return line ? [line] : [];
    }
    const nestedKeys = ['lab_results', 'labResults', 'tests', 'test_results', 'exam_results', 'inspection_results'];
    return nestedKeys.flatMap(key => collectPatientDocumentLabLinesFromValue(value[key]));
  }
  return [];
}

async function getPatientDocumentLatestLabResults(patientId = currentPatient?.id) {
  const currentLines = collectPatientDocumentLabLinesFromValue(currentRecordVitalSigns);
  if (currentLines.length) return currentLines.join('\n');
  if (!patientId) return '';

  const api = typeof RecordAPI !== 'undefined' ? RecordAPI : null;
  if (!api?.list) throw new Error('カルテAPIが利用できません');
  const result = await api.list(patientId, 30, 0);
  const rows = Array.isArray(result?.data) ? result.data : (Array.isArray(result?.items) ? result.items : (Array.isArray(result) ? result : []));
  for (const record of rows) {
    const vitalSigns = normalizeKarteVitalSigns(record.vital_signs || record.vitalSigns);
    const lines = collectPatientDocumentLabLinesFromValue(vitalSigns);
    if (lines.length) return lines.join('\n');
  }
  return '';
}

function getPatientDocumentCurrentKarteText() {
  const editor = document.getElementById('karte-editor');
  if (!editor || editor.classList.contains('karte-empty-state')) return '';
  const plainClone = editor.cloneNode(true);
  plainClone.querySelectorAll('br').forEach(node => {
    node.replaceWith(document.createTextNode('\n'));
  });
  plainClone.querySelectorAll('p, div, li, tr').forEach(node => {
    node.appendChild(document.createTextNode('\n'));
  });
  const plainText = String(plainClone.textContent || '')
    .replace(/\u00a0/g, ' ')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
  if (!plainText) return '';

  const soap = parseKarteContent(editor.innerHTML);
  const soapSections = [
    ['主訴', soap.subjective],
    ['身体所見', soap.objective],
    ['アセスメント', soap.assessment],
    ['プラン', soap.plan]
  ].filter(([, value]) => String(value || '').trim());
  if (!soapSections.length) return plainText;
  return soapSections
    .map(([label, value]) => `【${label}】\n${String(value || '').trim()}`)
    .join('\n\n');
}

function formatPatientDocumentInsuranceSummary() {
  const insurance = getKarteContextSelectedInsurance();
  return insurance ? formatKarteInsuranceOption(insurance) : '';
}

function formatPatientDocumentPublicExpenseSummary() {
  const publicExpenses = getKarteSelectedPublicExpenses();
  return publicExpenses.map(formatKartePublicExpenseOption).filter(Boolean).join('\n');
}

