function renderPatientDocumentCitationMap(target, rows = []) {
  const container = typeof target === 'string' ? document.getElementById(target) : target;
  if (!container) return;
  container.innerHTML = `
    <div class="patient-document-source-title">引用元</div>
    <div class="patient-document-source-grid">
      ${rows.map(row => `
        <div class="patient-document-source-row">
          <span class="patient-document-source-badge ${escapeHtml(row.type || 'quoted')}">
            ${escapeHtml(PATIENT_DOCUMENT_CITATION_TYPE_LABELS[row.type] || '引用')}
          </span>
          <div>
            <strong>${escapeHtml(row.label)}</strong>
            <small>${escapeHtml(row.source)}</small>
            <p>${escapeHtml(getPatientDocumentCitationValue(row.value)).replace(/\n/g, '<br>')}</p>
          </div>
        </div>
      `).join('')}
    </div>
  `;
}

function refreshPatientDocumentCreateCitationMap() {
  const container = document.getElementById('patient-document-create-source-map');
  if (!container) return;
  const data = collectReferralDocumentFormData();
  const values = getPatientDocumentParameterValues(
    data.date,
    patientDocumentCreateContextCache?.diagnoses || null,
    patientDocumentCreateContextCache?.facility || getLoadedFacilityInfo(),
    {
      latestPrescriptions: data.latestPrescriptions,
      latestLabResults: data.latestLabResults,
      clinicalCourse: data.clinicalCourse,
      doctorName: data.doctorName,
      referralToFacility: data.referralToFacility,
      referralToDoctor: data.referralToDoctor,
      referralPurpose: data.referralPurpose,
      documentRemarks: data.remarks
    }
  );
  patientDocumentCreateValuesCache = values;
  renderPatientDocumentCitationMap(
    container,
    buildPatientDocumentCitationRows(data, values, { templateName: '①診療情報提供書' })
  );
}

function renderPatientDocumentTemplateCitationMap(template = {}) {
  const container = document.getElementById('patient-document-template-source-map');
  if (!container) return;
  const date = getCurrentKarteDateValue() || getLocalDateString();
  const doctorName = document.getElementById('patient-document-template-doctor-name')?.value.trim()
    || getPatientDocumentDoctorDefaultName();
  const values = getPatientDocumentParameterValues(date, null, getLoadedFacilityInfo(), {
    latestPrescriptions: pendingPrescriptions.map(formatPatientDocumentPrescriptionLine).filter(Boolean).join('\n'),
    latestLabResults: collectPatientDocumentLabLinesFromValue(currentRecordVitalSigns).join('\n'),
    clinicalCourse: getPatientDocumentCurrentKarteText(),
    doctorName
  });
  renderPatientDocumentCitationMap(
    container,
    buildPatientDocumentCitationRows({}, values, { templateName: template.display_name || template.original_name || '文書ひな形' })
  );
}

async function getPatientDocumentContextForOutput(documentDate = null) {
  const results = await Promise.allSettled([
    getPatientDocumentDiagnoses(currentPatient?.id),
    requireCurrentFacilityInfoForOutput(),
    getPatientDocumentLatestPrescriptions(currentPatient?.id),
    getPatientDocumentLatestLabResults(currentPatient?.id)
  ]);
  const warnings = [];
  results.forEach(result => {
    if (result.status === 'rejected') {
      warnings.push(result.reason?.message || '文書用データを取得できませんでした');
    }
  });
  return {
    diagnoses: results[0].status === 'fulfilled' ? results[0].value : [],
    facility: results[1].status === 'fulfilled' ? results[1].value : getLoadedFacilityInfo(),
    latestPrescriptions: results[2].status === 'fulfilled' ? results[2].value : '',
    latestLabResults: results[3].status === 'fulfilled' ? results[3].value : '',
    currentKarteText: getPatientDocumentCurrentKarteText(),
    warnings,
    documentDate
  };
}

async function getPatientDocumentParameterValuesForOutput(documentDate = null, extraValues = {}) {
  const context = await getPatientDocumentContextForOutput(documentDate);
  if (context.warnings?.length) {
    showToast(`一部の文書用データを取得できませんでした: ${context.warnings.join(' / ')}`, 'error');
  }
  return getPatientDocumentParameterValues(
    documentDate,
    context.diagnoses,
    context.facility,
    {
      latestPrescriptions: context.latestPrescriptions,
      latestLabResults: context.latestLabResults,
      clinicalCourse: context.currentKarteText,
      ...extraValues
    }
  );
}

function getCurrentMedicalFacilityName() {
  return firstNonEmptyString(getLoadedFacilityInfo().name);
}

function getPatientDocumentParameterValues(documentDate = null, diagnosisSource = null, facilityInfo = getLoadedFacilityInfo(), extraValues = {}) {
  const birthDate = currentPatient?.birth_date || currentPatient?.birth || '';
  const documentDateValue = normalizeKarteDateValue(documentDate) || getCurrentKarteDateValue() || getLocalDateString();
  const patientAge = formatAgeForKarte(birthDate);
  const patientAgeNumber = String(patientAge || '').match(/\d+/)?.[0] || '';
  const currentKarteText = firstNonEmptyString(extraValues.clinicalCourse, extraValues.currentKarteText, getPatientDocumentCurrentKarteText());
  const receptionDate = normalizeKarteDateValue(currentReception?.reception_date || currentReception?.visit_date || documentDateValue);
  const diagnoses = Array.isArray(diagnosisSource)
    ? diagnosisSource.map(normalizeDiagnosisItem)
    : getPatientDocumentCachedDiagnoses(currentPatient?.id);
  const birthParts = getDocumentDateParts(birthDate);
  const birthEra = getDocumentJapaneseEra(birthDate);
  const birthImperialYear = birthEra ? `${birthEra.name}${birthEra.eraYear === 1 ? '元' : birthEra.eraYear}年` : '';
  const patientName = currentPatient?.name || '';
  const patientKana = currentPatient?.name_kana || currentPatient?.kana || '';
  const patientRomaji = firstNonEmptyString(currentPatient?.name_romaji, currentPatient?.nameRomaji, currentPatient?.romaji);
  const patientAddress = getPatientDocumentAddressParts(currentPatient || {});
  const patientPhone = formatPatientPhones(currentPatient || {});
  const values = {
    DK_PATIENT_NUMBER: currentPatient?.patient_no || currentPatient?.id || '',
    DK_PATIENT_NAME: patientName,
    DK_PATIENT_KANA: patientKana,
    DK_PATIENT_BIRTHDAY: formatJapaneseBirthDate(birthDate),
    DK_PATIENT_BIRTHDAY_PLAIN: formatDocumentYmdDate(birthDate),
    DK_PATIENT_BIRTHDAY_ERA: formatDocumentEraDate(birthDate, { padYear: true }),
    DK_PATIENT_AGE: patientAge === '-' ? '' : patientAge,
    DK_PATIENT_AGE_NUMBER: patientAge === '-' ? '' : patientAgeNumber,
    DK_PATIENT_GENDER: formatPatientGenderLabel(currentPatient),
    DK_PATIENT_ADDRESS: formatPatientDetailAddress(currentPatient || {}),
    DK_PATIENT_ADDRESS_NO_POSTAL: formatPatientDocumentAddressNoPostal(currentPatient || {}),
    DK_PATIENT_PHONE: patientPhone,
    DK_TODAY: formatDateSlash(documentDateValue),
    DK_TODAY_JP: formatDocumentYmdDate(documentDateValue, { pad: true }),
    DK_TODAY_ERA: formatDocumentEraDate(documentDateValue, { padYear: true, padMonth: true, padDay: true }),
    DK_DIAGNOSIS_NAME: formatPatientDocumentDiagnosisNames(diagnoses),
    DK_DIAGNOSIS_LIST: formatPatientDocumentDiagnosisNames(diagnoses),
    DK_LATEST_LAB_RESULTS: extraValues.latestLabResults || '',
    DK_LATEST_PRESCRIPTIONS: extraValues.latestPrescriptions || '',
    DK_CURRENT_KARTE_TEXT: currentKarteText,
    DK_CLINICAL_COURSE: currentKarteText,
    DK_RECEPTION_DATE: receptionDate ? formatDateSlash(receptionDate) : '',
    DK_RECEPTION_DEPARTMENT: currentReception?.department || document.getElementById('karte-department')?.value || '',
    DK_INSURANCE_SUMMARY: formatPatientDocumentInsuranceSummary(),
    DK_PUBLIC_EXPENSE_SUMMARY: formatPatientDocumentPublicExpenseSummary(),
    DK_DOCTOR_NAME: extraValues.doctorName || currentReception?.doctor || '',
    DK_REFERRAL_TO_FACILITY: extraValues.referralToFacility || '',
    DK_REFERRAL_TO_DOCTOR: extraValues.referralToDoctor || '',
    DK_REFERRAL_PURPOSE: extraValues.referralPurpose || '',
    DK_DOCUMENT_REMARKS: extraValues.documentRemarks || '',
    DK_FACILITY_NAME: firstNonEmptyString(facilityInfo?.name),
    DK_FACILITY_CODE: firstNonEmptyString(facilityInfo?.code),
    DK_FACILITY_POSTAL_CODE: firstNonEmptyString(facilityInfo?.postalCode),
    DK_FACILITY_ADDRESS: firstNonEmptyString(facilityInfo?.address),
    DK_FACILITY_PHONE: firstNonEmptyString(facilityInfo?.phone),
    DK_FACILITY_FAX: firstNonEmptyString(facilityInfo?.fax),
    DK_FACILITY_EMAIL: firstNonEmptyString(facilityInfo?.email),
    DK_FACILITY_OUTPATIENT_TYPE: firstNonEmptyString(facilityInfo?.outpatientType),
    DK_FACILITY_INVOICE_NUMBER: firstNonEmptyString(facilityInfo?.registrationNumber)
  };
  return {
    ...values,
    DK_PATIENT_FULL_NAME: patientName,
    DK_PATIENT_FULL_NAME_KANA: patientKana,
    DK_PATIENT_FULL_NAME_ROMAJI: patientRomaji,
    DK_PATIENT_BIRTH_DATE_GREGORIAN: values.DK_PATIENT_BIRTHDAY_PLAIN,
    DK_PATIENT_BIRTH_DATE_IMPERIAL: values.DK_PATIENT_BIRTHDAY_ERA,
    DK_PATIENT_BIRTH_YEAR_GREGORIAN: birthParts?.year ? String(birthParts.year) : '',
    DK_PATIENT_BIRTH_YEAR_IMPERIAL: birthImperialYear,
    DK_PATIENT_BIRTH_MONTH: birthParts?.month ? String(birthParts.month) : '',
    DK_PATIENT_BIRTH_DAY_OF_MONTH: birthParts?.day ? String(birthParts.day) : '',
    DK_PATIENT_AGE_YEARS: patientAgeNumber,
    DK_PATIENT_FULL_ADDRESS: patientAddress.fullAddress || values.DK_PATIENT_ADDRESS,
    DK_PATIENT_PREFECTURE: patientAddress.prefecture,
    DK_PATIENT_CITY: patientAddress.city,
    DK_PATIENT_ADDRESS_1: patientAddress.address1,
    DK_PATIENT_ADDRESS_2: patientAddress.address2,
    DK_PATIENT_ZIP_CODE: patientAddress.postalCode,
    DK_PATIENT_PHONE_NUMBER: patientPhone,
    DK_DOCUMENT_DATE_GREGORIAN: values.DK_TODAY_JP,
    DK_DOCUMENT_DATE_IMPERIAL: values.DK_TODAY_ERA
  };
}

function readZipUint16(view, offset) {
  return view.getUint16(offset, true);
}

function readZipUint32(view, offset) {
  return view.getUint32(offset, true);
}

function writeZipUint16(bytes, offset, value) {
  bytes[offset] = value & 0xff;
  bytes[offset + 1] = (value >>> 8) & 0xff;
}

function writeZipUint32(bytes, offset, value) {
  bytes[offset] = value & 0xff;
  bytes[offset + 1] = (value >>> 8) & 0xff;
  bytes[offset + 2] = (value >>> 16) & 0xff;
  bytes[offset + 3] = (value >>> 24) & 0xff;
}

const ZIP_TEXT_ENCODER = new TextEncoder();
const ZIP_TEXT_DECODER = new TextDecoder('utf-8');
let zipCrcTable = null;

function getZipCrcTable() {
  if (zipCrcTable) return zipCrcTable;
  zipCrcTable = new Uint32Array(256);
  for (let n = 0; n < 256; n += 1) {
    let c = n;
    for (let k = 0; k < 8; k += 1) {
      c = (c & 1) ? (0xedb88320 ^ (c >>> 1)) : (c >>> 1);
    }
    zipCrcTable[n] = c >>> 0;
  }
  return zipCrcTable;
}

function crc32(bytes) {
  const table = getZipCrcTable();
  let crc = 0xffffffff;
  for (let i = 0; i < bytes.length; i += 1) {
    crc = table[(crc ^ bytes[i]) & 0xff] ^ (crc >>> 8);
  }
  return (crc ^ 0xffffffff) >>> 0;
}

function findZipEndOfCentralDirectory(bytes) {
  const minOffset = Math.max(0, bytes.length - 0xffff - 22);
  for (let offset = bytes.length - 22; offset >= minOffset; offset -= 1) {
    if (
      bytes[offset] === 0x50 &&
      bytes[offset + 1] === 0x4b &&
      bytes[offset + 2] === 0x05 &&
      bytes[offset + 3] === 0x06
    ) {
      return offset;
    }
  }
  return -1;
}

function parseZipEntries(arrayBuffer) {
  const bytes = new Uint8Array(arrayBuffer);
  const view = new DataView(arrayBuffer);
  const eocdOffset = findZipEndOfCentralDirectory(bytes);
  if (eocdOffset < 0) throw new Error('ZIP終端が見つかりません');
  const totalEntries = readZipUint16(view, eocdOffset + 10);
  let offset = readZipUint32(view, eocdOffset + 16);
  const entries = [];

  for (let index = 0; index < totalEntries; index += 1) {
    if (readZipUint32(view, offset) !== 0x02014b50) throw new Error('ZIP中央ディレクトリを読み込めません');
    const method = readZipUint16(view, offset + 10);
    const compressedSize = readZipUint32(view, offset + 20);
    const nameLength = readZipUint16(view, offset + 28);
    const extraLength = readZipUint16(view, offset + 30);
    const commentLength = readZipUint16(view, offset + 32);
    const localOffset = readZipUint32(view, offset + 42);
    const nameBytes = bytes.slice(offset + 46, offset + 46 + nameLength);
    const name = ZIP_TEXT_DECODER.decode(nameBytes);

    if (readZipUint32(view, localOffset) !== 0x04034b50) throw new Error('ZIPローカルヘッダを読み込めません');
    const localNameLength = readZipUint16(view, localOffset + 26);
    const localExtraLength = readZipUint16(view, localOffset + 28);
    const dataStart = localOffset + 30 + localNameLength + localExtraLength;
    const compressedData = bytes.slice(dataStart, dataStart + compressedSize);

    entries.push({ name, method, compressedData });
    offset += 46 + nameLength + extraLength + commentLength;
  }

  return entries;
}

async function inflateZipEntry(entry) {
  if (entry.method === 0) return entry.compressedData;
  if (entry.method === 8) {
    if (window.digimaster?.inflateRaw) {
      const inflated = await window.digimaster.inflateRaw(entry.compressedData.buffer.slice(
        entry.compressedData.byteOffset,
        entry.compressedData.byteOffset + entry.compressedData.byteLength
      ));
      return new Uint8Array(inflated);
    }

    if (typeof DecompressionStream === 'function') {
      try {
        const stream = new Blob([entry.compressedData])
          .stream()
          .pipeThrough(new DecompressionStream('deflate-raw'));
        return new Uint8Array(await new Response(stream).arrayBuffer());
      } catch (error) {
        console.warn('ブラウザでZIPを展開できませんでした:', error);
      }
    }
  }
  throw new Error(`未対応のZIP圧縮方式です: ${entry.method}`);
}

function shouldReplaceOfficeXml(path) {
  return (
    path === 'word/document.xml' ||
    path.startsWith('word/header') ||
    path.startsWith('word/footer') ||
    path === 'xl/sharedStrings.xml' ||
    path.startsWith('xl/worksheets/')
  ) && path.endsWith('.xml');
}

function escapeOfficeXmlText(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;');
}

function escapeRegExp(value) {
  return String(value ?? '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function replaceOfficeXmlLiteralValue(text, literal, value) {
  if (!literal || value === undefined || value === null) return text;
  const escapedLiteral = escapeRegExp(escapeOfficeXmlText(literal));
  const safeValue = escapeOfficeXmlText(value);
  return text.replace(new RegExp(escapedLiteral, 'g'), safeValue);
}

function replaceFollowingOfficeTextValue(text, label, sampleValue, value, windowSize = 900) {
  if (!label || !sampleValue || value === undefined || value === null || value === '') return text;
  const safeValue = escapeOfficeXmlText(value);
  const labelText = escapeRegExp(escapeOfficeXmlText(label));
  const sampleText = escapeRegExp(escapeOfficeXmlText(sampleValue));
  const pattern = new RegExp(
    `(<[^>]*>${labelText}</[^>]*>[\\s\\S]{0,${windowSize}}?<w:t[^>]*>(?:\\s|　)*)${sampleText}((?:\\s|　)*</w:t>)`,
    'g'
  );
  return text.replace(pattern, `$1${safeValue}$2`);
}

function replaceExactOfficeTextNodeValue(text, sampleValue, value) {
  if (!sampleValue || value === undefined || value === null || value === '') return text;
  const safeValue = escapeOfficeXmlText(value);
  const sampleText = escapeRegExp(escapeOfficeXmlText(sampleValue));
  const pattern = new RegExp(
    `(<(?:\\w+:)?t\\b[^>]*>(?:\\s|　)*)${sampleText}((?:\\s|　)*</(?:\\w+:)?t>)`,
    'g'
  );
  return text.replace(pattern, `$1${safeValue}$2`);
}

