function replaceDocumentParameters(text, values) {
  const replacedExplicitParameters = Object.entries(values).reduce((result, [key, value]) => {
    const escapedKey = key.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const safeValue = escapeOfficeXmlText(value);
    return result
      .replace(new RegExp(`\\{\\{\\s*${escapedKey}\\s*\\}\\}`, 'g'), safeValue)
      .replace(new RegExp(escapedKey, 'g'), safeValue);
  }, text);
  return replaceDocumentSamplePatientValues(replacedExplicitParameters, values);
}

async function materializeZipEntries(entries, parameterValues) {
  const outputEntries = [];
  for (const entry of entries) {
    let content = await inflateZipEntry(entry);
    if (shouldReplaceOfficeXml(entry.name)) {
      const text = ZIP_TEXT_DECODER.decode(content);
      const replaced = replaceDocumentParameters(text, parameterValues);
      if (replaced !== text) {
        content = ZIP_TEXT_ENCODER.encode(replaced);
      }
    }
    outputEntries.push({
      name: entry.name,
      nameBytes: ZIP_TEXT_ENCODER.encode(entry.name),
      content,
      crc: crc32(content)
    });
  }
  return outputEntries;
}

function buildStoredZip(entries) {
  let localSize = 0;
  let centralSize = 0;
  entries.forEach(entry => {
    localSize += 30 + entry.nameBytes.length + entry.content.length;
    centralSize += 46 + entry.nameBytes.length;
  });
  const totalSize = localSize + centralSize + 22;
  const bytes = new Uint8Array(totalSize);
  let offset = 0;
  const centralRecords = [];

  entries.forEach(entry => {
    const localOffset = offset;
    writeZipUint32(bytes, offset, 0x04034b50); offset += 4;
    writeZipUint16(bytes, offset, 20); offset += 2;
    writeZipUint16(bytes, offset, 0x0800); offset += 2;
    writeZipUint16(bytes, offset, 0); offset += 2;
    writeZipUint16(bytes, offset, 0); offset += 2;
    writeZipUint16(bytes, offset, 0); offset += 2;
    writeZipUint32(bytes, offset, entry.crc); offset += 4;
    writeZipUint32(bytes, offset, entry.content.length); offset += 4;
    writeZipUint32(bytes, offset, entry.content.length); offset += 4;
    writeZipUint16(bytes, offset, entry.nameBytes.length); offset += 2;
    writeZipUint16(bytes, offset, 0); offset += 2;
    bytes.set(entry.nameBytes, offset); offset += entry.nameBytes.length;
    bytes.set(entry.content, offset); offset += entry.content.length;
    centralRecords.push({ ...entry, localOffset });
  });

  const centralOffset = offset;
  centralRecords.forEach(entry => {
    writeZipUint32(bytes, offset, 0x02014b50); offset += 4;
    writeZipUint16(bytes, offset, 20); offset += 2;
    writeZipUint16(bytes, offset, 20); offset += 2;
    writeZipUint16(bytes, offset, 0x0800); offset += 2;
    writeZipUint16(bytes, offset, 0); offset += 2;
    writeZipUint16(bytes, offset, 0); offset += 2;
    writeZipUint16(bytes, offset, 0); offset += 2;
    writeZipUint32(bytes, offset, entry.crc); offset += 4;
    writeZipUint32(bytes, offset, entry.content.length); offset += 4;
    writeZipUint32(bytes, offset, entry.content.length); offset += 4;
    writeZipUint16(bytes, offset, entry.nameBytes.length); offset += 2;
    writeZipUint16(bytes, offset, 0); offset += 2;
    writeZipUint16(bytes, offset, 0); offset += 2;
    writeZipUint16(bytes, offset, 0); offset += 2;
    writeZipUint16(bytes, offset, 0); offset += 2;
    writeZipUint32(bytes, offset, 0); offset += 4;
    writeZipUint32(bytes, offset, entry.localOffset); offset += 4;
    bytes.set(entry.nameBytes, offset); offset += entry.nameBytes.length;
  });
  const centralEnd = offset;

  writeZipUint32(bytes, offset, 0x06054b50); offset += 4;
  writeZipUint16(bytes, offset, 0); offset += 2;
  writeZipUint16(bytes, offset, 0); offset += 2;
  writeZipUint16(bytes, offset, entries.length); offset += 2;
  writeZipUint16(bytes, offset, entries.length); offset += 2;
  writeZipUint32(bytes, offset, centralEnd - centralOffset); offset += 4;
  writeZipUint32(bytes, offset, centralOffset); offset += 4;
  writeZipUint16(bytes, offset, 0);

  return bytes.buffer;
}

async function createOfficeDocumentBlobFromTemplate(template, parameterValues) {
  const ext = getFileExtension(template.original_name || template.file_name);
  if (!['docx', 'xlsx'].includes(ext)) return template.blob;
  try {
    const buffer = await template.blob.arrayBuffer();
    const entries = parseZipEntries(buffer);
    const materialized = await materializeZipEntries(entries, parameterValues);
    const output = buildStoredZip(materialized);
    return new Blob([output], { type: template.type || inferFileMimeType(template.file_name) });
  } catch (error) {
    console.error('文書ひな形のパラメータ反映エラー:', error);
    throw new Error(`文書ひな形に患者情報を反映できません: ${error?.message || '不明なエラー'}`);
  }
}

