function getDiagnosisEditModifierItems() {
  const seen = new Set(DIAGNOSIS_EDIT_MODIFIER_ITEMS.map(item => `${item.modifier_type}:${item.name}`));
  const bodyPartItems = getFacilityMasterItems('bodyParts')
    .map((item, index) => ({
      code: `BODY_PART_${String(item.code || index + 1).replace(/[^A-Za-z0-9_-]/g, '_')}`,
      name: item.name,
      modifier_type: 'prefix',
      position: '前'
    }))
    .filter(item => {
      const key = `${item.modifier_type}:${item.name}`;
      if (!item.name || seen.has(key)) return false;
      seen.add(key);
      return true;
    });
  return [...DIAGNOSIS_EDIT_MODIFIER_ITEMS, ...bodyPartItems];
}

function refreshDiagnosisEditCommentOptions() {
  const list = document.getElementById('diagnosis-edit-comment-options');
  if (!list) return;
  const seen = new Set();
  const options = getFacilityMasterItems('comments')
    .map(item => item.detail || item.name)
    .map(value => String(value || '').trim())
    .filter(value => {
      if (!value || seen.has(value)) return false;
      seen.add(value);
      return true;
    });
  list.innerHTML = options
    .map(value => `<option value="${escapeHtml(value)}"></option>`)
    .join('');
}

