function normalizeDiagnosisMasterItem(item) {
  return {
    disease_code: item.disease_code || item.code || item.c || '',
    name: item.name || item.disease_name || item.n || '',
    name_kana: item.name_kana || item.kana || item.k || '',
    name_short: item.name_short || item.short || item.s || '',
    icd10_code: item.icd10_code || item.i || '',
    is_active: item.is_active ?? item.a ?? true
  };
}

function getOfficialDiagnosisMasterItems() {
  return (window.OFFICIAL_DIAGNOSIS_MASTER?.items || []).map(normalizeDiagnosisMasterItem);
}

function searchOfficialDiagnosisMaster(query, limit = 50) {
  const items = getOfficialDiagnosisMasterItems().filter(item => item.is_active !== false);
  const q = String(query || '').trim().toLowerCase();

  if (!q) {
    const byName = new Map(items.map(item => [item.name, item]));
    return COMMON_DIAGNOSIS_NAMES.map(name => byName.get(name)).filter(Boolean).slice(0, limit);
  }

  const scored = [];
  items.forEach(item => {
    const name = item.name || '';
    const kana = item.name_kana || '';
    const shortName = item.name_short || '';
    const code = item.disease_code || '';
    const icd10 = item.icd10_code || '';
    const haystack = `${name} ${kana} ${shortName} ${code} ${icd10}`.toLowerCase();
    if (!haystack.includes(q)) return;
    const score = name === query ? 0 : name.startsWith(query) ? 1 : kana.startsWith(query) ? 2 : 3;
    scored.push({ item, score });
  });

  return scored
    .sort((a, b) => a.score - b.score || a.item.name.length - b.item.name.length || a.item.name.localeCompare(b.item.name, 'ja'))
    .slice(0, limit)
    .map(entry => entry.item);
}

function searchLocalDiagnosisMaster(query, limit = 50) {
  const q = String(query || '').trim().toLowerCase();
  const rows = getFacilityMasterItems('diagnoses')
    .map(item => normalizeDiagnosisMasterItem({
      disease_code: item.code,
      name: item.name,
      name_kana: item.name_kana,
      is_active: true
    }));

  if (!q) return rows.slice(0, limit);

  return rows
    .filter(item => {
      const haystack = `${item.name || ''} ${item.name_kana || ''} ${item.disease_code || ''}`.toLowerCase();
      return haystack.includes(q);
    })
    .slice(0, limit);
}

function mergeDiagnosisMasterItems(primary = [], secondary = [], limit = 50) {
  const merged = [];
  const seen = new Set();
  [...primary, ...secondary].forEach(item => {
    const normalized = normalizeDiagnosisMasterItem(item);
    const key = normalized.name || normalized.disease_code;
    if (!key || seen.has(key)) return;
    seen.add(key);
    merged.push(normalized);
  });
  return merged.slice(0, limit);
}

function normalizeDiagnosisItem(item) {
  item = item || {};
  const prefixModifiers = normalizeDiagnosisModifierList(item.prefix_modifiers);
  const suffixModifiers = normalizeDiagnosisModifierList(item.suffix_modifiers);
  const diagnosisName = item.diagnosis_name || item.disease_name || item.name || '';
  return {
    ...item,
    id: item.id || item.diagnosis_id || item.local_id || '',
    diagnosis_code: item.diagnosis_code || item.disease_code || '',
    diagnosis_name: diagnosisName,
    department: item.department || item.department_name || item.clinical_department || '',
    visit_type: item.visit_type || 'outpatient',
    insurance_scope: item.insurance_scope || 'social-national',
    insurance_none: item.insurance_none === true,
    prefix_modifiers: prefixModifiers,
    suffix_modifiers: suffixModifiers,
    full_name: item.full_name || buildDiagnosisFullName(diagnosisName, prefixModifiers, suffixModifiers),
    diagnosis_category: item.diagnosis_category || (item.is_main ? 'main' : 'sub'),
    is_suspected: item.is_suspected === true,
    start_date: item.start_date || item.onset_date || '',
    end_date: item.end_date || item.outcome_date || '',
    outcome: item.outcome || 'continuing',
    is_local: item.is_local === true
  };
}

function normalizeDiagnosisModifierList(value) {
  if (!value) return [];
  let source = value;
  if (typeof source === 'string') {
    try {
      source = JSON.parse(source);
    } catch {
      source = [];
    }
  }
  if (!Array.isArray(source)) return [];
  return source
    .map((item, index) => {
      if (typeof item === 'string') {
        return { code: `LOCAL_MOD_${index + 1}`, name: item };
      }
      const name = item?.name || item?.modifier_name || '';
      return {
        code: item?.code || item?.modifier_code || `LOCAL_MOD_${index + 1}`,
        name
      };
    })
    .filter(item => item.name);
}

function buildDiagnosisFullName(name, prefixModifiers = [], suffixModifiers = []) {
  const prefix = normalizeDiagnosisModifierList(prefixModifiers).map(item => item.name).join('');
  const suffix = normalizeDiagnosisModifierList(suffixModifiers).map(item => item.name).join('');
  return `${prefix}${name || ''}${suffix}`;
}

function getCurrentDiagnosisDepartment() {
  const headerDepartment = document.getElementById('karte-context-department')?.textContent?.trim();
  return currentReception?.department
    || document.getElementById('karte-department')?.value
    || (headerDepartment && headerDepartment !== '-' ? headerDepartment : '')
    || '内科';
}

function getDiagnosisDepartmentOptions(selectedDepartment = '') {
  const masterDepartments = (facilityLocalMasters.departments || [])
    .filter(item => item && item.name)
    .map(item => item.name);
  const values = [
    selectedDepartment,
    currentReception?.department,
    document.getElementById('karte-department')?.value,
    document.getElementById('karte-context-department')?.textContent?.trim(),
    ...masterDepartments,
    '内科',
    '在宅',
    '発熱外来',
    '夜間休日外来',
    '美容施術'
  ];
  return Array.from(new Set(values.map(value => String(value || '').trim()).filter(Boolean)));
}

function syncCurrentPatientDiagnosesState(diagnoses) {
  if (!currentPatient) return;
  const normalized = diagnoses.map(normalizeDiagnosisItem);
  currentPatient.diagnoses = normalized;
  currentPatient.diseases = normalized;
  currentPatientDiagnoses = normalized;
  currentPatientDiagnosesPatientId = currentPatient.id;
}

async function loadPatientDiagnoses(patientId = currentPatient?.id) {
  const container = document.getElementById('disease-list');
  if (!container || !patientId) return;

  container.innerHTML = emptyClinicalMessage('傷病名を読み込み中です。');

  try {
    const api = typeof DiagnosisAPI !== 'undefined' ? DiagnosisAPI : null;
    if (!api?.listByPatient) throw new Error('DiagnosisAPI is not available');
    const result = await api.listByPatient(patientId, { activeOnly: true, includeEnded: true });
    const diagnoses = (result.items || result.data || result.diagnoses || []).map(normalizeDiagnosisItem);
    currentPatientDiagnoses = diagnoses;
    currentPatientDiagnosesPatientId = patientId;
    if (currentPatient?.id === patientId) {
      currentPatient.diagnoses = diagnoses;
    }
    renderDiseaseList(diagnoses);
    refreshProcedureWarningIndicators();
  } catch (error) {
    console.error('傷病名API取得エラー:', error);
    currentPatientDiagnoses = [];
    currentPatientDiagnosesPatientId = patientId;
    container.innerHTML = emptyClinicalMessage('傷病名を取得できませんでした。');
    refreshProcedureWarningIndicators();
  }
}

function formatDiagnosisOutcome(outcome) {
  const labels = {
    continuing: '継続',
    cured: '治癒',
    discontinued: '中止',
    improved: '軽快',
    died: '死亡',
    transferred: '移行',
    other: 'その他'
  };
  return labels[outcome] || '継続';
}

function renderDiseaseList(diagnoses = currentPatientDiagnoses) {
  const container = document.getElementById('disease-list');
  if (!container) return;

  const rows = (diagnoses || []).map(normalizeDiagnosisItem);
  if (!rows.length) {
    const selectAll = document.getElementById('diagnosis-select-all');
    if (selectAll) selectAll.checked = false;
    container.innerHTML = emptyClinicalMessage('傷病名が登録されていません。');
    return;
  }

  container.innerHTML = `
    <div class="diagnosis-table">
      <div class="diagnosis-table-head">
        <span></span><span>主併</span><span>傷病名</span><span>疑い</span><span>開始日</span><span>転帰日</span><span>転帰</span><span>診療科</span><span></span>
      </div>
      ${rows.map((diagnosis, index) => `
        <div class="diagnosis-row ${diagnosis.diagnosis_category === 'main' ? 'is-main' : ''}">
          <span class="diagnosis-select-cell"><input type="checkbox" class="diagnosis-row-select" data-diagnosis-index="${index}" aria-label="傷病名選択" onchange="syncDiagnosisSelectionFromRows()"></span>
          <span class="diagnosis-kind">${diagnosis.diagnosis_category === 'main' ? '主病' : ''}</span>
          <span class="diagnosis-row-name">${escapeHtml(diagnosis.full_name || diagnosis.diagnosis_name)}</span>
          <span class="diagnosis-suspect">${diagnosis.is_suspected ? '疑い' : ''}</span>
          <span class="diagnosis-date">${escapeHtml(formatDateSlash(diagnosis.start_date))}</span>
          <span class="diagnosis-date">${escapeHtml(formatDateSlash(diagnosis.end_date))}</span>
          <span class="diagnosis-outcome">${escapeHtml(formatDiagnosisOutcome(diagnosis.outcome))}</span>
          <span class="diagnosis-department">${escapeHtml(diagnosis.department || getCurrentDiagnosisDepartment())}</span>
          <button class="diagnosis-edit-btn" onclick="openDiagnosisEditModal(${index})" title="編集">
            <i class="fas fa-pen"></i>
          </button>
        </div>
      `).join('')}
    </div>
  `;
}

function getSelectedDiagnosisIndices() {
  return Array.from(document.querySelectorAll('.diagnosis-row-select:checked'))
    .map(input => Number(input.dataset.diagnosisIndex))
    .filter(index => Number.isInteger(index) && currentPatientDiagnoses[index]);
}

function syncDiagnosisSelectionFromRows() {
  const selectAll = document.getElementById('diagnosis-select-all');
  if (!selectAll) return;
  const checkboxes = Array.from(document.querySelectorAll('.diagnosis-row-select'));
  selectAll.checked = checkboxes.length > 0 && checkboxes.every(input => input.checked);
}

function toggleAllDiagnosisSelections(event) {
  const checked = event?.target?.checked === true;
  document.querySelectorAll('.diagnosis-row-select').forEach(input => {
    input.checked = checked;
  });
}

function ensureDiagnosisModal() {
  let modal = document.getElementById('diagnosis-modal');
  if (modal) return modal;

  modal = document.createElement('div');
  modal.id = 'diagnosis-modal';
  modal.className = 'modal hidden diagnosis-modal';
  modal.innerHTML = `
    <div class="modal-content diagnosis-modal-content">
      <div class="modal-header">
        <h3>傷病名新規登録</h3>
        <button type="button" class="modal-close" onclick="closeDiagnosisModal()">&times;</button>
      </div>
      <div class="diagnosis-search-header">
        <div class="diagnosis-search-box">
          <i class="fas fa-search"></i>
          <input type="text" id="diagnosis-search-input" placeholder="キーワードを入力してください">
        </div>
      </div>
      <div class="diagnosis-result-list" id="diagnosis-search-results"></div>
    </div>
  `;
  document.body.appendChild(modal);

  const input = modal.querySelector('#diagnosis-search-input');
  input?.addEventListener('input', () => {
    clearTimeout(diagnosisSearchTimer);
    diagnosisSearchTimer = setTimeout(() => searchAndRenderDiagnosisMaster(input.value), 160);
  });

  return modal;
}

function openDiagnosisModal() {
  if (!currentPatient) {
    showToast('患者を選択してください', 'error');
    return;
  }

  const modal = ensureDiagnosisModal();
  modal.classList.remove('hidden');
  const input = document.getElementById('diagnosis-search-input');
  if (input) {
    input.value = '';
    input.focus();
  }
  searchAndRenderDiagnosisMaster('');
}

function closeDiagnosisModal() {
  document.getElementById('diagnosis-modal')?.classList.add('hidden');
}

