function formatQuestionnaireAnswer(value) {
  if (Array.isArray(value)) return value.join('、');
  if (value && typeof value === 'object') {
    return Object.entries(value)
      .filter(([, v]) => v !== '' && v !== null && v !== undefined)
      .map(([key, v]) => `${key}: ${Array.isArray(v) ? v.join('、') : v}`)
      .join(' / ');
  }
  return String(value ?? '');
}

function renderQuestionnaireResponseCard(response) {
  const labels = response.item_labels || {};
  const answers = Object.entries(response.responses || {});
  const answerHtml = answers.length
    ? answers.map(([key, value]) => `
        <div class="m3-patient-row">
          <span class="m3-patient-label">${escapeHtml(labels[key] || key)}</span>
          <span class="m3-patient-value">${escapeHtml(formatQuestionnaireAnswer(value))}</span>
        </div>
      `).join('')
    : '<div class="m3-memo-content empty"><p>回答内容がありません。</p></div>';

  return `
    <div class="questionnaire-response-card">
      <div class="history-card-header">
        <span class="history-date">${escapeHtml(response.questionnaire_name || '問診票')}</span>
        <span class="history-insurance">${escapeHtml(response.completed_at ? new Date(response.completed_at).toLocaleString('ja-JP') : '')}</span>
      </div>
      <div class="history-card-info">
        ${escapeHtml(response.department_name || '')}
      </div>
      <div class="m3-patient-table">${answerHtml}</div>
    </div>
  `;
}

async function loadPatientQuestionnaireResponses(patientId) {
  const container = document.getElementById('interview-data');
  if (!container || !patientId || !window.QuestionnaireAPI) return;

  container.innerHTML = emptyClinicalMessage('問診回答を読み込み中です。');

  try {
    const responses = await QuestionnaireAPI.listResponsesByPatient(patientId);
    if (!responses.length) {
      container.innerHTML = emptyClinicalMessage('問診票が登録されていません。');
      return;
    }
    container.innerHTML = responses.map(renderQuestionnaireResponseCard).join('');
  } catch (error) {
    console.error('問診回答取得エラー:', error);
    container.innerHTML = emptyClinicalMessage('問診回答の取得に失敗しました。');
  }
}

const historyRecordDetailCache = new Map();
const recordUpdateHistoryCache = new Map();

function getHistoryFirstText(...values) {
  for (const value of values) {
    const text = String(value ?? '').trim();
    if (text) return text;
  }
  return '';
}

function parseRecordHistoryData(value) {
  if (!value) return {};
  if (typeof value === 'object') return value;
  try {
    const parsed = JSON.parse(value);
    return parsed && typeof parsed === 'object' ? parsed : {};
  } catch {
    return {};
  }
}

function formatRecordHistoryTitleDate(dateValue) {
  const normalized = normalizeKarteDateValue(dateValue);
  if (!normalized) return '';
  const date = parseLocalDate(normalized);
  return `${date.getFullYear()}年${date.getMonth() + 1}月${date.getDate()}日`;
}

function formatRecordHistoryDateTime(value) {
  if (!value) return '';
  if (typeof formatReceptionHistoryDateTime === 'function') {
    return formatReceptionHistoryDateTime(value);
  }
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return String(value);
  return date.toLocaleString('ja-JP');
}

function getRecordHistoryPatientLabel(record = {}) {
  const patientNo = getHistoryFirstText(record.patient_no, currentPatient?.patient_no);
  const patientName = getHistoryFirstText(record.patient_name, record.name, currentPatient?.name);
  return [patientNo ? `ID: ${patientNo}` : '', patientName].filter(Boolean).join('　') || '-';
}

function getRecordHistoryStatusLabel(record = {}) {
  if (record.is_deleted === true || String(record.is_deleted).toLowerCase() === 'true') return '削除';
  const status = String(record.status || '').toLowerCase();
  if (status === 'confirmed' || status === 'locked') return '承認';
  if (status === 'draft') return '未承認';
  return record.status ? String(record.status) : '未承認';
}

function getRecordHistoryTabLabel(record = {}) {
  const selectedInsurance = record.insurance_id ? getPatientInsuranceById(record.insurance_id) : null;
  const derivedInsuranceLabel = getReceptionInsuranceLabel(record);
  const publicExpenseIds = [
    record.public_expense_1_id,
    record.public_expense_id,
    record.public_expense_2_id,
    record.public_expense_3_id
  ].filter(Boolean);
  const publicExpenseLabelFromIds = publicExpenseIds
    .map(id => getPatientPublicExpenseById(id))
    .filter(Boolean)
    .map(expense => {
      const name = getPublicExpenseDisplayName(expense);
      const lawNumber = getPublicExpenseLawNumber(expense);
      return lawNumber ? `${name}（${lawNumber}）` : name;
    })
    .join(' ');
  const derivedPublicExpenseLabel = getHistoryFirstText(record.public_expense_type, record.public_expense_type_name)
    ? getPublicExpenseDisplayName({
      expense_type: record.public_expense_type,
      expense_type_name: record.public_expense_type_name,
      name: record.public_expense_type
    })
    : '';
  const insuranceLabel = getHistoryFirstText(
    record.insurance_label,
    selectedInsurance ? getReceptionInsuranceLabel(selectedInsurance) : '',
    derivedInsuranceLabel !== '保険無し' ? derivedInsuranceLabel : '',
    getKarteInsuranceShortLabel()
  );
  const publicExpenseLabel = getHistoryFirstText(
    record.public_expense_label,
    publicExpenseLabelFromIds,
    derivedPublicExpenseLabel,
    getKartePublicExpenseShortLabel('')
  );
  return [insuranceLabel, publicExpenseLabel].filter(Boolean).join(' ') || '-';
}

function formatRecordHistoryContextLine(record = {}) {
  const visitType = getHistoryFirstText(record.visit_type, record.visitType, currentReception?.visit_type, '外来');
  const department = getHistoryFirstText(record.department, currentReception?.department, '内科');
  const doctorName = getHistoryFirstText(
    record.doctor_name,
    record.doctor,
    currentReception?.doctor_name_override,
    currentReception?.doctor_name,
    currentReception?.doctor
  );
  const status = getRecordHistoryStatusLabel(record);
  const confirmedAt = getHistoryFirstText(record.confirmed_at, record.confirmedAt);
  const statusText = confirmedAt && status === '承認'
    ? `${status}（${formatRecordHistoryDateTime(confirmedAt)}）`
    : status;
  return [
    visitType,
    department,
    doctorName ? formatKarteDoctorName(doctorName) : '',
    getRecordHistoryTabLabel(record),
    statusText
  ].filter(Boolean).join('　');
}

function formatRecordHistoryEditorLine(record = {}, options = {}) {
  const at = getHistoryFirstText(
    options.changedAt,
    record.__historyChangedAt,
    record.updated_at,
    record.updatedAt,
    record.created_at,
    record.createdAt
  );
  const by = getHistoryFirstText(
    options.changedBy,
    record.__historyChangedBy,
    record.updated_by_name,
    record.created_by_name,
    record.doctor_name
  );
  return [formatRecordHistoryDateTime(at), by].filter(Boolean).join(' ');
}

function hasRecordHistoryOrders(record = {}) {
  return (Array.isArray(record.billings) && record.billings.length > 0)
    || (Array.isArray(record.prescriptions) && record.prescriptions.length > 0);
}

function buildRecordHistorySnapshotFromVersion(currentRecord, version) {
  const data = parseRecordHistoryData(version?.data);
  const snapshot = {
    ...currentRecord,
    ...data,
    id: currentRecord.id,
    record_id: currentRecord.id,
    patient_id: currentRecord.patient_id,
    patient_no: currentRecord.patient_no,
    patient_name: currentRecord.patient_name,
    name_kana: currentRecord.name_kana,
    gender: currentRecord.gender,
    birth_date: currentRecord.birth_date,
    doctor_name: data.doctor_name || currentRecord.doctor_name,
    created_by_name: data.created_by_name || currentRecord.created_by_name,
    updated_by_name: data.updated_by_name || currentRecord.updated_by_name,
    confirmed_by_name: data.confirmed_by_name || currentRecord.confirmed_by_name,
    __historyVersion: version?.version,
    __historyChangedAt: version?.created_at,
    __historyChangedBy: version?.changed_by_name,
    __ordersSnapshotMissing: !Array.isArray(data.billings) && !Array.isArray(data.prescriptions)
  };
  snapshot.billings = Array.isArray(data.billings) ? data.billings : [];
  snapshot.prescriptions = Array.isArray(data.prescriptions) ? data.prescriptions : [];
  return snapshot;
}

function renderRecordHistorySnapshot(record = {}, options = {}) {
  const label = options.label ? `<span class="record-history-label">${escapeHtml(options.label)}</span>` : '';
  const tabLabel = options.tabLabel || getRecordHistoryTabLabel(record);
  const warning = record.__ordersSnapshotMissing
    ? '<div class="record-history-note">この履歴は旧形式のため、処置・行為のスナップショットがありません。</div>'
    : '';
  return `
    <div class="record-history-snapshot${options.compact ? ' compact' : ''}" data-record-id="${escapeHtml(record.id || record.record_id || '')}">
      <div class="record-history-tabbar">
        <span class="record-history-tab">${escapeHtml(tabLabel)}</span>
        ${label}
      </div>
      <div class="record-history-meta-line">${escapeHtml(formatRecordHistoryEditorLine(record, options))}</div>
      <div class="record-history-context-line">${escapeHtml(formatRecordHistoryContextLine(record))}</div>
      ${warning}
      ${renderHistoryCardBody(record)}
    </div>
  `;
}

function ensureRecordUpdateHistoryModal() {
  let modal = document.getElementById('record-update-history-modal');
  if (modal) return modal;

  modal = document.createElement('div');
  modal.id = 'record-update-history-modal';
  modal.className = 'modal hidden record-update-history-modal';
  modal.innerHTML = `
    <div class="modal-content record-update-history-content" role="dialog" aria-modal="true" aria-labelledby="record-update-history-title">
      <div class="modal-header">
        <h3 id="record-update-history-title">更新履歴</h3>
        <button type="button" class="modal-close" id="record-update-history-close" title="閉じる">&times;</button>
      </div>
      <div class="record-update-history-body">
        <div class="record-update-history-list" id="record-update-history-list">
          <div class="record-update-history-empty">更新履歴を読み込み中です。</div>
        </div>
      </div>
    </div>
  `;

  modal.querySelector('#record-update-history-close')?.addEventListener('click', closeRecordUpdateHistoryModal);
  modal.addEventListener('click', event => {
    if (event.target === modal) closeRecordUpdateHistoryModal();
  });
  document.body.appendChild(modal);
  return modal;
}

function closeRecordUpdateHistoryModal() {
  document.getElementById('record-update-history-modal')?.classList.add('hidden');
}

async function openRecordUpdateHistoryModal(recordId = currentRecordId) {
  if (!currentPatient?.id) {
    showToast('患者を選択してください', 'error');
    return;
  }
  const targetRecordId = recordId || currentRecordId;
  if (!targetRecordId) {
    showToast('保存済みカルテを選択してください', 'error');
    return;
  }
  if (!RecordAPI?.versions) {
    showToast('更新履歴APIが利用できません', 'error');
    return;
  }

  const modal = ensureRecordUpdateHistoryModal();
  modal.classList.remove('hidden');
  const list = modal.querySelector('#record-update-history-list');
  if (list) list.innerHTML = '<div class="record-update-history-empty">更新履歴を読み込み中です。</div>';

  try {
    const [recordResult, versionResult] = await Promise.all([
      RecordAPI.get(targetRecordId),
      RecordAPI.versions(targetRecordId)
    ]);

    const currentRecord = recordResult.data || recordResult;
    const versions = Array.isArray(versionResult) ? versionResult : (versionResult.data || []);
    recordUpdateHistoryCache.set(String(targetRecordId), { currentRecord, versions });
    renderRecordUpdateHistoryModal(currentRecord, versions);
  } catch (error) {
    console.error('更新履歴取得エラー:', error);
    if (list) {
      list.innerHTML = `<div class="record-update-history-empty error">更新履歴の取得に失敗しました。${escapeHtml(error?.message || '')}</div>`;
    }
  }
}

function renderRecordUpdateHistoryModal(currentRecord, versions = []) {
  const modal = ensureRecordUpdateHistoryModal();
  const title = modal.querySelector('#record-update-history-title');
  if (title) {
    const dateLabel = formatRecordHistoryTitleDate(currentRecord.visit_date);
    const patientName = getHistoryFirstText(currentRecord.patient_name, currentPatient?.name);
    title.textContent = `更新履歴（${[dateLabel, patientName].filter(Boolean).join('　')}）`;
  }

  const list = modal.querySelector('#record-update-history-list');
  if (!list) return;

  const currentSnapshot = {
    ...currentRecord,
    __historyChangedAt: currentRecord.updated_at || currentRecord.created_at,
    __historyChangedBy: currentRecord.updated_by_name || currentRecord.created_by_name || currentRecord.doctor_name
  };
  const versionSnapshots = versions
    .map(version => buildRecordHistorySnapshotFromVersion(currentRecord, version))
    .sort((a, b) => Number(b.__historyVersion || 0) - Number(a.__historyVersion || 0));

  const snapshots = [
    { record: currentSnapshot, label: '現在' },
    ...versionSnapshots.map(snapshot => ({ record: snapshot, label: `v${snapshot.__historyVersion || '-'}` }))
  ];

  const historyNote = versions.length
    ? ''
    : '<div class="record-update-history-note">過去の更新履歴はありません。現在のカルテ内容を表示しています。</div>';
  list.innerHTML = `
    <div class="record-update-history-patient">${escapeHtml(getRecordHistoryPatientLabel(currentRecord))}</div>
    ${historyNote}
    ${snapshots.map(item => renderRecordHistorySnapshot(item.record, { label: item.label })).join('')}
  `;
}

// APIから診療履歴を取得
async function renderPatientHistoryFromAPI(patientId) {
  const container = document.getElementById('history-list');
  if (!container) return;

  bindHistoryCardActions(container);
  container.innerHTML = emptyClinicalMessage('診療履歴を読み込み中です。');
  historyRecordDetailCache.clear();

  try {
    const result = await RecordAPI.list(patientId);
    const records = Array.isArray(result) ? result : (result.data || []);

    if (records.length === 0) {
      container.innerHTML = emptyClinicalMessage('診療履歴がありません。');
      return;
    }

    const detailedRecords = await Promise.all(records.map(loadHistoryRecordDetailForDisplay));
    if (currentPatient?.id && currentPatient.id !== patientId) return;

    detailedRecords.sort(compareHistoryRecordsDesc);
    container.innerHTML = detailedRecords.map(renderHistoryCard).join('');

  } catch (error) {
    console.error('診療履歴取得エラー:', error);
    container.innerHTML = emptyClinicalMessage('履歴の取得に失敗しました。');
  }
}

async function loadHistoryRecordDetailForDisplay(record) {
  if (!record?.id) return record;
  const recordId = String(record.id);
  const cached = historyRecordDetailCache.get(recordId);
  if (cached) {
    return { ...record, ...cached, __detailLoaded: true };
  }

  if (Array.isArray(record.billings) && Array.isArray(record.prescriptions)) {
    const detailedRecord = { ...record, __detailLoaded: true };
    historyRecordDetailCache.set(recordId, detailedRecord);
    return detailedRecord;
  }

  try {
    const detailResult = await RecordAPI.get(record.id);
    const detail = detailResult.data || detailResult;
    const detailedRecord = {
      ...record,
      ...detail,
      billings: detail.billings || [],
      prescriptions: detail.prescriptions || [],
      __detailLoaded: true
    };
    historyRecordDetailCache.set(recordId, detailedRecord);
    return detailedRecord;
  } catch (error) {
    console.warn('診療履歴詳細取得エラー:', record.id, error);
    return {
      ...record,
      billings: record.billings || [],
      prescriptions: record.prescriptions || [],
      __detailLoaded: false
    };
  }
}

const deletedRecordDetailCache = new Map();

function ensureDeletedRecordRestoreModal() {
  let modal = document.getElementById('deleted-record-restore-modal');
  if (modal) return modal;

  modal = document.createElement('div');
  modal.id = 'deleted-record-restore-modal';
  modal.className = 'modal hidden deleted-record-restore-modal';
  modal.innerHTML = `
    <div class="modal-content deleted-record-restore-content" role="dialog" aria-modal="true" aria-labelledby="deleted-record-restore-title">
      <div class="modal-header">
        <h3 id="deleted-record-restore-title">削除カルテの復元</h3>
        <button type="button" class="modal-close" id="deleted-record-restore-close" title="閉じる">&times;</button>
      </div>
      <div class="deleted-record-restore-body">
        <div class="deleted-record-restore-head">
          <div>
            <div class="deleted-record-restore-patient" id="deleted-record-restore-patient">-</div>
            <div class="deleted-record-restore-note" id="deleted-record-restore-count"></div>
          </div>
          <button type="button" class="deleted-record-restore-refresh" id="deleted-record-restore-refresh" title="再読み込み">
            <i class="fas fa-sync-alt"></i>
            <span>再読み込み</span>
          </button>
        </div>
        <div class="deleted-record-restore-list" id="deleted-record-restore-list"></div>
        <div class="deleted-record-restore-preview" id="deleted-record-restore-preview"></div>
      </div>
    </div>
  `;

  modal.querySelector('#deleted-record-restore-close')?.addEventListener('click', closeDeletedRecordRestoreModal);
  modal.querySelector('#deleted-record-restore-refresh')?.addEventListener('click', () => renderDeletedRecordRestoreList({ force: true }));
  modal.addEventListener('click', event => {
    if (event.target === modal) closeDeletedRecordRestoreModal();
  });
  modal.querySelector('#deleted-record-restore-list')?.addEventListener('click', event => {
    const previewButton = event.target.closest('[data-preview-record-id]');
    if (previewButton) {
      event.preventDefault();
      const record = deletedRecordDetailCache.get(String(previewButton.dataset.previewRecordId));
      if (record) {
        renderDeletedRecordRestorePreview(record);
        highlightDeletedRecordRestoreRow(record.id);
      }
      return;
    }
    const button = event.target.closest('[data-restore-record-id]');
    if (!button) return;
    event.preventDefault();
    restoreDeletedRecordFromModal(button.dataset.restoreRecordId, button);
  });

  document.body.appendChild(modal);
  return modal;
}

function closeDeletedRecordRestoreModal() {
  document.getElementById('deleted-record-restore-modal')?.classList.add('hidden');
}

async function openDeletedRecordRestoreModal() {
  if (!currentPatient?.id) {
    showToast('患者を選択してください', 'error');
    return;
  }
  if (!RecordAPI?.listDeleted || !RecordAPI?.restore) {
    showToast('削除カルテ復元APIが利用できません', 'error');
    return;
  }

  const modal = ensureDeletedRecordRestoreModal();
  const patientLabel = [
    currentPatient.patient_no ? `ID: ${currentPatient.patient_no}` : '',
    currentPatient.name || ''
  ].filter(Boolean).join('　') || currentPatient.id;
  const patientEl = modal.querySelector('#deleted-record-restore-patient');
  if (patientEl) patientEl.textContent = patientLabel;
  const countEl = modal.querySelector('#deleted-record-restore-count');
  if (countEl) countEl.textContent = '';
  modal.classList.remove('hidden');
  await renderDeletedRecordRestoreList({ force: true });
}

async function renderDeletedRecordRestoreList({ force = false } = {}) {
  const list = document.getElementById('deleted-record-restore-list');
  if (!list || !currentPatient?.id) return;

  if (force) deletedRecordDetailCache.clear();
  const patientId = currentPatient.id;
  list.innerHTML = '<div class="deleted-record-restore-empty">削除済みカルテを読み込み中です。</div>';

  try {
    const result = await RecordAPI.listDeleted({ patient_id: patientId, limit: 100 });
    const records = Array.isArray(result) ? result : (result.data || []);
    if (String(currentPatient?.id || '') !== String(patientId)) return;
    const countEl = document.getElementById('deleted-record-restore-count');
    if (countEl) countEl.textContent = `削除済み ${records.length}件`;

    if (records.length === 0) {
      list.innerHTML = '<div class="deleted-record-restore-empty">削除済みカルテはありません。</div>';
      renderDeletedRecordRestorePreview(null);
      return;
    }

    const detailedRecords = await Promise.all(records.map(loadDeletedRecordDetailForRestore));
    detailedRecords.sort(compareDeletedRecordsDesc);
    list.innerHTML = detailedRecords.map(renderDeletedRecordRestoreCard).join('');
    renderDeletedRecordRestorePreview(detailedRecords[0]);
    highlightDeletedRecordRestoreRow(detailedRecords[0]?.id);
  } catch (error) {
    console.error('削除カルテ取得エラー:', error);
    list.innerHTML = '<div class="deleted-record-restore-empty error">削除済みカルテの取得に失敗しました。</div>';
    renderDeletedRecordRestorePreview(null);
  }
}

async function loadDeletedRecordDetailForRestore(record) {
  if (!record?.id) return record;
  const recordId = String(record.id);
  const cached = deletedRecordDetailCache.get(recordId);
  if (cached) {
    return { ...record, ...cached, __detailLoaded: true };
  }

  try {
    const detailResult = await RecordAPI.get(record.id, { includeDeleted: true });
    const detail = detailResult.data || detailResult;
    const detailedRecord = {
      ...record,
      ...detail,
      billings: detail.billings || [],
      prescriptions: detail.prescriptions || [],
      __detailLoaded: true
    };
    deletedRecordDetailCache.set(recordId, detailedRecord);
    return detailedRecord;
  } catch (error) {
    console.warn('削除カルテ詳細取得エラー:', record.id, error);
    return {
      ...record,
      billings: record.billings || [],
      prescriptions: record.prescriptions || [],
      __detailLoaded: false
    };
  }
}

function compareDeletedRecordsDesc(a, b) {
  const dateA = new Date(a.deleted_at || a.updated_at || a.visit_date || 0).getTime();
  const dateB = new Date(b.deleted_at || b.updated_at || b.visit_date || 0).getTime();
  if (dateA !== dateB) return dateB - dateA;
  return compareHistoryRecordsDesc(a, b);
}

function formatDeletedRecordRestoreMeta(record) {
  const status = record.status === 'confirmed' ? '承認' : record.status === 'locked' ? 'ロック' : '未承認';
  const deletedAt = record.deleted_at || record.updated_at;
  const deletedAtText = deletedAt ? new Date(deletedAt).toLocaleString('ja-JP') : '';
  return [
    record.department || '内科',
    record.doctor_name ? formatKarteDoctorName(record.doctor_name) : '',
    status,
    deletedAtText ? `削除日時 ${deletedAtText}` : ''
  ].filter(Boolean).join('　');
}

function renderDeletedRecordRestoreCard(record) {
  const detailWarning = record.__detailLoaded ? '' : '<div class="deleted-record-restore-warning">詳細の一部を取得できませんでした。</div>';
  return `
    <div class="deleted-record-restore-row" data-id="${escapeHtml(record.id)}">
      <div class="deleted-record-restore-row-main">
        <span class="deleted-record-restore-date">${formatDateWithDay(record.visit_date)}</span>
        <span class="deleted-record-restore-meta">${escapeHtml(formatDeletedRecordRestoreMeta(record))}</span>
        ${detailWarning}
      </div>
      <div class="deleted-record-restore-row-actions">
        <button type="button" class="deleted-record-restore-secondary" data-preview-record-id="${escapeHtml(record.id)}">
          <i class="fas fa-search"></i>
          <span>参照</span>
        </button>
        <button type="button" class="deleted-record-restore-btn" data-restore-record-id="${escapeHtml(record.id)}">
          <i class="fas fa-undo-alt"></i>
          <span>復元</span>
        </button>
      </div>
    </div>
  `;
}

function highlightDeletedRecordRestoreRow(recordId) {
  document.querySelectorAll('.deleted-record-restore-row').forEach(row => {
    row.classList.toggle('selected', String(row.dataset.id || '') === String(recordId || ''));
  });
}

function renderDeletedRecordRestorePreview(record) {
  const preview = document.getElementById('deleted-record-restore-preview');
  if (!preview) return;
  if (!record) {
    preview.innerHTML = '<div class="deleted-record-restore-empty">参照する削除済みカルテを選択してください。</div>';
    return;
  }

  const deletedAt = record.deleted_at || record.updated_at;
  preview.innerHTML = `
    <div class="deleted-record-restore-preview-title">
      <span>${escapeHtml(formatDateWithDay(record.visit_date))}</span>
      <span>${escapeHtml(deletedAt ? `削除日時 ${formatRecordHistoryDateTime(deletedAt)}` : '')}</span>
    </div>
    ${renderRecordHistorySnapshot(record, { label: '削除済み', changedAt: deletedAt, changedBy: record.deleted_by_name || record.updated_by_name })}
  `;
}

async function restoreDeletedRecordFromModal(recordId, button = null) {
  if (!recordId || !currentPatient?.id) return;
  const confirmed = await showAppConfirm({
    title: '削除カルテの復元',
    message: 'この削除済みカルテを復元して開きますか？',
    confirmText: '復元',
    cancelText: 'キャンセル'
  });
  if (!confirmed) return;
  if (!(await confirmDiscardKarteChangesIfNeeded())) return;

  const originalHtml = button?.innerHTML;
  try {
    if (button) {
      button.disabled = true;
      button.innerHTML = '<i class="fas fa-spinner fa-spin"></i><span>復元中</span>';
    }
    showLoading();
    await RecordAPI.restore(recordId);
    deletedRecordDetailCache.delete(String(recordId));
    historyRecordDetailCache.delete(String(recordId));

    if (currentPatient.patient_no) {
      await renderPatientHistoryFromAPI(currentPatient.id);
    } else {
      renderPatientHistory(currentPatient.id);
    }
    await loadRecordDetail(recordId);
    closeDeletedRecordRestoreModal();
    showToast('カルテを復元しました', 'success');
  } catch (error) {
    console.error('削除カルテ復元エラー:', error);
    showToast('カルテの復元に失敗しました: ' + (error?.message || '不明なエラー'), 'error');
  } finally {
    hideLoading();
    if (button) {
      button.disabled = false;
      button.innerHTML = originalHtml || '<i class="fas fa-undo-alt"></i><span>復元</span>';
    }
  }
}

let currentMedicationHistoryMatrix = {
  patientId: null,
  months: [],
  rows: []
};
let medicationHistoryWindowRef = null;

function buildMedicationHistoryMonths(anchorDateValue = getCurrentKarteDateValue()) {
  const anchor = parseLocalDate(normalizeKarteDateValue(anchorDateValue) || getLocalDateString());
  anchor.setDate(1);

  const months = [];
  for (let offset = 11; offset >= 0; offset -= 1) {
    const date = new Date(anchor.getFullYear(), anchor.getMonth() - offset, 1);
    const year = date.getFullYear();
    const month = date.getMonth() + 1;
    months.push({
      key: `${year}-${String(month).padStart(2, '0')}`,
      year,
      month
    });
  }
  return months;
}

function groupMedicationHistoryYears(months) {
  return months.reduce((groups, month) => {
    const last = groups[groups.length - 1];
    if (last && last.year === month.year) {
      last.span += 1;
    } else {
      groups.push({ year: month.year, span: 1 });
    }
    return groups;
  }, []);
}

function normalizeMedicationHistoryDrugName(value) {
  return String(value || '')
    .replace(/\s+/g, ' ')
    .trim();
}

function getMedicationHistoryDrugName(prescription = {}) {
  return normalizeMedicationHistoryDrugName(
    prescription.drug_name
    || prescription.name
    || prescription.medication_name
    || prescription.item_name
    || prescription.display_name
  );
}

function getMedicationHistoryRecordDate(record = {}) {
  return normalizeKarteDateValue(record.visit_date || record.date || record.created_at);
}

function buildMedicationHistoryRows(records = [], months = buildMedicationHistoryMonths()) {
  const monthKeys = new Set(months.map(month => month.key));
  const rowsByName = new Map();
  let firstSeenOrder = 0;

  records.forEach(record => {
    const recordDate = getMedicationHistoryRecordDate(record);
    if (!recordDate) return;
    const monthKey = recordDate.slice(0, 7);
    if (!monthKeys.has(monthKey)) return;

    (record.prescriptions || []).forEach(prescription => {
      const drugName = getMedicationHistoryDrugName(prescription);
      if (!drugName) return;
      const normalizedKey = drugName.replace(/\s+/g, '').toLowerCase();
      if (!rowsByName.has(normalizedKey)) {
        rowsByName.set(normalizedKey, {
          name: drugName,
          months: new Set(),
          monthRecords: new Map(),
          latestDate: recordDate,
          firstSeenOrder: firstSeenOrder++
        });
      }
      const row = rowsByName.get(normalizedKey);
      row.months.add(monthKey);
      if (!row.monthRecords.has(monthKey)) {
        row.monthRecords.set(monthKey, []);
      }
      row.monthRecords.get(monthKey).push({
        recordId: record.id || record.record_id || '',
        recordDate,
        drugName
      });
      if (recordDate > row.latestDate) {
        row.latestDate = recordDate;
        row.name = drugName;
      }
    });
  });

  return Array.from(rowsByName.values())
    .sort((left, right) => {
      if (left.latestDate !== right.latestDate) return right.latestDate.localeCompare(left.latestDate);
      return left.firstSeenOrder - right.firstSeenOrder;
    });
}

function getMedicationHistoryMonthRecords(row, monthKey) {
  if (!row || !monthKey) return [];
  if (row.monthRecords instanceof Map) {
    return row.monthRecords.get(monthKey) || [];
  }
  if (row.monthRecords && typeof row.monthRecords === 'object') {
    return row.monthRecords[monthKey] || [];
  }
  return row.months?.has?.(monthKey) ? [{ recordId: '', recordDate: '' }] : [];
}

function renderMedicationHistoryMonthMark(row, month) {
  const records = getMedicationHistoryMonthRecords(row, month.key)
    .filter(record => record && record.recordId)
    .sort((left, right) => String(right.recordDate || '').localeCompare(String(left.recordDate || '')));
  if (!records.length) {
    return row.months?.has?.(month.key) ? '<span class="medication-history-check disabled">✓</span>' : '';
  }
  const record = records[0];
  const title = `${record.recordDate || month.key} のカルテを開く`;
  return `
    <button type="button" class="medication-history-check" data-record-id="${escapeHtml(record.recordId)}" title="${escapeHtml(title)}" aria-label="${escapeHtml(title)}" onclick="event.stopPropagation(); openMedicationHistoryLinkedRecordFromWindow(this.dataset.recordId);">
      ✓
    </button>
  `;
}

function renderMedicationHistoryMatrix(rows, months) {
  if (!rows.length) {
    return '<div class="m3-medication-history-empty">投薬履歴が登録されていません。</div>';
  }

  const yearGroups = groupMedicationHistoryYears(months);
  return `
    <div class="medication-history-table-wrap">
      <table class="medication-history-table">
        <thead>
          <tr>
            <th class="medication-history-drug-head" rowspan="2">
              <div class="medication-history-drug-head-inner">
                <span>医薬品名</span>
                <button type="button" class="medication-history-window-btn" id="btn-open-medication-history-window" title="新しいウィンドウで開く">
                  <i class="fas fa-up-right-from-square"></i>
                </button>
              </div>
            </th>
            ${yearGroups.map(group => `<th class="medication-history-year-head" colspan="${group.span}">${group.year}</th>`).join('')}
          </tr>
          <tr>
            ${months.map(month => `<th class="medication-history-month-head">${month.month}</th>`).join('')}
          </tr>
        </thead>
        <tbody>
          ${rows.map(row => `
            <tr>
              <td class="medication-history-drug-cell">
                <div class="medication-history-drug-cell-inner">
                  <span class="medication-history-drug-badge">薬</span>
                  <span class="medication-history-drug-name">${escapeHalfWidthNumericText(row.name)}</span>
                </div>
              </td>
              ${months.map(month => `
                <td class="medication-history-month-cell">
                  ${renderMedicationHistoryMonthMark(row, month)}
                </td>
              `).join('')}
            </tr>
          `).join('')}
        </tbody>
      </table>
    </div>
  `;
}

function isRecordInMedicationHistoryMonths(record, monthKeys) {
  const recordDate = getMedicationHistoryRecordDate(record);
  return Boolean(recordDate && monthKeys.has(recordDate.slice(0, 7)));
}

async function fetchPatientRecordsForMedicationHistory(patientId, months) {
  if (typeof PatientAPI !== 'undefined' && PatientAPI.getPrescriptionHistory) {
    const result = await PatientAPI.getPrescriptionHistory(patientId, 200);
    const prescriptions = Array.isArray(result) ? result : (result.data || []);
    return prescriptions.map(prescription => ({
      id: prescription.record_id || '',
      record_id: prescription.record_id || '',
      visit_date: normalizeKarteDateValue(prescription.visit_date || prescription.prescription_date || prescription.created_at),
      billings: [],
      prescriptions: [prescription],
      __detailLoaded: true
    }));
  }

  const earliestMonthKey = months[0]?.key;
  const records = [];
  const pageSize = 100;

  for (let offset = 0; offset < 500; offset += pageSize) {
    const result = await RecordAPI.list(patientId, pageSize, offset);
    const page = Array.isArray(result) ? result : (result.data || []);
    records.push(...page);

    const reachedEnd = page.length < pageSize;
    const reachedOlderRecord = earliestMonthKey && page.some(record => {
      const recordDate = getMedicationHistoryRecordDate(record);
      return recordDate && recordDate.slice(0, 7) < earliestMonthKey;
    });

    if (reachedEnd || reachedOlderRecord) break;
  }

  return records;
}

async function renderPatientMedicationHistory(patientId) {
  const container = document.getElementById('medication-history-list');
  if (!container) return;

  const months = buildMedicationHistoryMonths();
  const monthKeys = new Set(months.map(month => month.key));
  currentMedicationHistoryMatrix = { patientId, months, rows: [] };

  if (!patientId) {
    container.innerHTML = '<div class="m3-medication-history-empty">投薬履歴が登録されていません。</div>';
    refreshMedicationHistoryWindow();
    return;
  }

  container.innerHTML = '<div class="m3-medication-history-empty">投薬履歴を読み込み中です。</div>';

  try {
    let records = [];
    if (typeof RecordAPI !== 'undefined') {
      records = await fetchPatientRecordsForMedicationHistory(patientId, months);
      records = records.filter(record => isRecordInMedicationHistoryMonths(record, monthKeys));
      records = await Promise.all(records.map(loadHistoryRecordDetailForDisplay));
    } else {
      records = Storage.getRecords().filter(record => String(record.patientId || record.patient_id) === String(patientId));
    }

    if (currentPatient?.id && String(currentPatient.id) !== String(patientId)) return;

    const rows = buildMedicationHistoryRows(records, months);
    currentMedicationHistoryMatrix = { patientId, months, rows };
    container.innerHTML = renderMedicationHistoryMatrix(rows, months);
    container.querySelector('#btn-open-medication-history-window')?.addEventListener('click', openMedicationHistoryWindow);
    refreshMedicationHistoryWindow();
  } catch (error) {
    console.error('投薬履歴取得エラー:', error);
    container.innerHTML = '<div class="m3-medication-history-empty">投薬履歴の取得に失敗しました。</div>';
    refreshMedicationHistoryWindow();
  }
}

function buildMedicationHistoryWindowHtml() {
  const patientLabel = currentPatient
    ? [currentPatient.patient_no ? `ID: ${currentPatient.patient_no}` : '', currentPatient.name || ''].filter(Boolean).join('　')
    : '';
  const matrixHtml = renderMedicationHistoryMatrix(currentMedicationHistoryMatrix.rows, currentMedicationHistoryMatrix.months)
    .replace('id="btn-open-medication-history-window"', 'id="btn-open-medication-history-window-copy" style="display:none"');
  return `
    <!doctype html>
    <html lang="ja">
      <head>
        <meta charset="utf-8">
        <title>投薬履歴</title>
        <style>
          body { margin: 0; font-family: "Yu Gothic UI", "Meiryo", sans-serif; color: #102018; background: #fff; }
          .window-title { padding: 10px 12px; border-bottom: 1px solid #ccd8d4; font-size: 14px; font-weight: 700; }
          .window-patient { margin-left: 10px; color: #334155; font-weight: 400; }
          .m3-medication-history-empty { padding: 18px; color: #7b8580; font-size: 13px; }
          .medication-history-table-wrap { width: 100%; overflow: auto; }
          .medication-history-table { width: max-content; min-width: 100%; border-collapse: collapse; table-layout: fixed; font-size: 12px; }
          .medication-history-table th, .medication-history-table td { box-sizing: border-box; border-right: 1px solid #d5dfdc; border-bottom: 1px solid #d5dfdc; background: #fff; }
          .medication-history-drug-head { width: 290px; min-width: 290px; height: 38px; padding: 0; text-align: left; vertical-align: bottom; font-weight: 500; }
          .medication-history-drug-head-inner { display: flex; align-items: flex-end; justify-content: space-between; height: 100%; padding: 0 8px 5px; }
          .medication-history-year-head { height: 18px; color: #334155; text-align: center; font-weight: 400; }
          .medication-history-month-head { width: 27px; min-width: 27px; height: 22px; text-align: center; font-weight: 400; }
          .medication-history-drug-cell { width: 290px; min-width: 290px; min-height: 35px; padding: 0 8px; white-space: normal; }
          .medication-history-drug-cell-inner { display: flex; align-items: flex-start; gap: 5px; min-height: 35px; padding: 5px 0; }
          .medication-history-month-cell { width: 27px; min-width: 27px; height: 35px; text-align: center; }
          .medication-history-drug-badge { display: inline-flex; align-items: center; justify-content: center; flex: 0 0 22px; width: 22px; height: 22px; border-radius: 2px; background: #9b72d6; color: #fff; font-size: 12px; }
          .medication-history-drug-name { flex: 1 1 auto; min-width: 0; line-height: 1.25; word-break: break-all; }
          .medication-history-check { display: inline-flex; align-items: center; justify-content: center; width: 14px; height: 14px; padding: 0; border: 0; border-radius: 50%; background: #202624; color: #fff; font-size: 10px; font-weight: 700; line-height: 14px; cursor: pointer; }
          .medication-history-check.disabled { cursor: default; opacity: .72; }
        </style>
      </head>
      <body>
        <div class="window-title">投薬履歴<span class="window-patient">${escapeHtml(patientLabel)}</span></div>
        ${matrixHtml}
        <script>
          function openMedicationHistoryLinkedRecordFromWindow(recordId) {
            var targetWindow = window.opener && window.opener.openMedicationHistoryLinkedRecord ? window.opener : window;
            if (targetWindow.openMedicationHistoryLinkedRecord) {
              targetWindow.openMedicationHistoryLinkedRecord(recordId);
            }
          }
        </script>
      </body>
    </html>
  `;
}

function openMedicationHistoryWindow() {
  const opened = window.open('', '_blank', 'width=900,height=520');
  if (!opened) {
    showToast('新しいウィンドウを開けませんでした', 'error');
    return;
  }
  medicationHistoryWindowRef = opened;
  opened.document.open();
  opened.document.write(buildMedicationHistoryWindowHtml());
  opened.document.close();
}

function isMedicationHistoryWindowOpen() {
  return Boolean(medicationHistoryWindowRef && !medicationHistoryWindowRef.closed);
}

function refreshMedicationHistoryWindow() {
  if (!isMedicationHistoryWindowOpen()) {
    medicationHistoryWindowRef = null;
    return;
  }
  medicationHistoryWindowRef.document.open();
  medicationHistoryWindowRef.document.write(buildMedicationHistoryWindowHtml());
  medicationHistoryWindowRef.document.close();
}

async function openMedicationHistoryLinkedRecord(recordId) {
  if (!recordId) return;
  try {
    if (window.focus) window.focus();
    await loadRecordDetail(recordId);
    showToast('投薬履歴のカルテを開きました', 'success');
  } catch (error) {
    console.error('投薬履歴カルテ読み込みエラー:', error);
    showToast('カルテの読み込みに失敗しました', 'error');
  }
}

function openMedicationHistoryLinkedRecordFromWindow(recordId) {
  openMedicationHistoryLinkedRecord(recordId);
}

window.openMedicationHistoryLinkedRecord = openMedicationHistoryLinkedRecord;
window.openMedicationHistoryLinkedRecordFromWindow = openMedicationHistoryLinkedRecordFromWindow;

function renderHistoryCopyControl(record, type) {
  const recordId = record?.id || record?.record_id || '';
  if (!recordId) {
    return '<i class="fas fa-share" aria-hidden="true"></i>';
  }

  const label = type === 'orders' ? '処置・行為を複写' : '主訴・所見を複写';
  return `
    <button type="button"
            class="history-copy-btn"
            data-history-copy-record-id="${escapeHtml(recordId)}"
            data-history-copy-type="${escapeHtml(type)}"
            title="${label}"
            aria-label="${label}">
      <i class="fas fa-share" aria-hidden="true"></i>
    </button>
  `;
}

function renderHistoryCardBody(record, options = {}) {
  const copyEnabled = options.copyEnabled === true;
  const soapCopyControl = copyEnabled ? renderHistoryCopyControl(record, 'soap') : '<i class="fas fa-share" aria-hidden="true"></i>';
  const ordersCopyControl = copyEnabled ? renderHistoryCopyControl(record, 'orders') : '<i class="fas fa-share" aria-hidden="true"></i>';

  return `
    <div class="history-columns">
      <div class="history-col-left">
        <div class="history-col-header">
          <span>主訴・所見</span>
          ${soapCopyControl}
        </div>
        <div class="history-soap-content">
          ${formatSOAPDisplay(record)}
        </div>
      </div>
      <div class="history-col-right">
        <div class="history-col-header">
          <span>処置・行為</span>
          ${ordersCopyControl}
        </div>
        <div class="history-billing-list">
          ${formatBillingItemsDetailed(record.billings || [], record.prescriptions || [], {
            copyEnabled,
            recordId: record?.id || record?.record_id || ''
          })}
        </div>
      </div>
    </div>
  `;
}

function renderHistoryCard(record) {
  const isActive = currentRecordId && record.id === currentRecordId;
  const insuranceLabel = getRecordHistoryTabLabel(record);
  return `
    <div class="history-card expanded ${isActive ? 'active' : ''}" data-id="${escapeHtml(record.id)}">
      <div class="history-card-header">
        <span class="history-date">${formatDateWithDay(record.visit_date)}</span>
        <span class="history-insurance">${escapeHtml(insuranceLabel || '-')}</span>
        <div class="history-card-actions">
          <button type="button" class="btn-icon-xs" data-history-update-record-id="${escapeHtml(record.id)}" title="更新履歴"><i class="fas fa-redo"></i></button>
          <button type="button" class="btn-icon-xs" data-history-edit-record-id="${escapeHtml(record.id)}" title="編集"><i class="fas fa-pen"></i></button>
        </div>
      </div>
      <div class="history-card-info">
        ${escapeHtml(formatHistoryRecordMeta(record, insuranceLabel))}
      </div>
      <div class="history-card-body" data-detail-loaded="${record.__detailLoaded ? 'true' : 'false'}">
        ${renderHistoryCardBody(record, { copyEnabled: true })}
      </div>
    </div>
  `;
}

function bindHistoryCardActions(container) {
  if (!container || container.dataset.historyCardActionsBound === 'true') return;
  container.dataset.historyCardActionsBound = 'true';
  const findHistoryItemCopyTarget = target => target?.closest?.('[data-history-copy-item-record-id]') || null;
  const copyHistoryItemFromElement = async itemCopyTarget => {
    if (!itemCopyTarget) return;
    await copyHistoryRecordItemToCurrentKarte(
      itemCopyTarget.dataset.historyCopyItemRecordId,
      itemCopyTarget.dataset.historyCopyItemKind,
      itemCopyTarget.dataset.historyCopyItemIndex,
      itemCopyTarget
    );
  };

  container.addEventListener('click', async event => {
    const itemCopyTarget = findHistoryItemCopyTarget(event.target);
    if (itemCopyTarget) {
      event.preventDefault();
      event.stopPropagation();
      await copyHistoryItemFromElement(itemCopyTarget);
      return;
    }

    const copyButton = event.target.closest('[data-history-copy-record-id]');
    if (copyButton) {
      event.preventDefault();
      event.stopPropagation();
      await copyHistoryRecordSectionToCurrentKarte(
        copyButton.dataset.historyCopyRecordId,
        copyButton.dataset.historyCopyType,
        copyButton
      );
      return;
    }

    const updateButton = event.target.closest('[data-history-update-record-id]');
    if (updateButton) {
      event.preventDefault();
      event.stopPropagation();
      await openRecordUpdateHistoryModal(updateButton.dataset.historyUpdateRecordId);
      return;
    }

    const editButton = event.target.closest('[data-history-edit-record-id]');
    if (editButton) {
      event.preventDefault();
      event.stopPropagation();
      await openHistoryRecordForEditing(editButton.dataset.historyEditRecordId, editButton);
      return;
    }

    const header = event.target.closest('.history-card-header');
    if (header && container.contains(header)) {
      await toggleHistoryCard(header);
    }
  });
  container.addEventListener('keydown', async event => {
    if (event.key !== 'Enter' && event.key !== ' ') return;
    const itemCopyTarget = findHistoryItemCopyTarget(event.target);
    if (!itemCopyTarget) return;
    event.preventDefault();
    event.stopPropagation();
    await copyHistoryItemFromElement(itemCopyTarget);
  });
}

function compareHistoryRecordsDesc(a, b) {
  const dateA = new Date(a.visit_date || a.created_at || 0).getTime();
  const dateB = new Date(b.visit_date || b.created_at || 0).getTime();
  if (dateA !== dateB) return dateB - dateA;
  return new Date(b.created_at || 0).getTime() - new Date(a.created_at || 0).getTime();
}

function formatHistoryRecordMeta(record, insuranceLabel = '') {
  const status = record.status === 'confirmed' ? '承認' : '未承認';
  return [
    record.department || '内科',
    record.doctor_name ? formatKarteDoctorName(record.doctor_name) : '',
    insuranceLabel,
    status
  ].filter(Boolean).join('　');
}

// 診療履歴は常時展開表示。外部から呼ばれた場合も右側カルテには反映しない。
async function toggleHistoryCard(header) {
  const card = header.closest('.history-card');
  if (!card) return;
  card.classList.add('expanded');
  await ensureHistoryCardDetail(card);
}

async function ensureHistoryCardDetail(card) {
  const recordId = card?.dataset?.id;
  const body = card?.querySelector('.history-card-body');
  if (!recordId || !body || body.dataset.detailLoaded === 'true') return;

  body.innerHTML = '<div class="history-empty-row">診療履歴を読み込み中です。</div>';

  try {
    const record = await loadHistoryRecordDetailForDisplay({ id: recordId });
    body.innerHTML = renderHistoryCardBody(record, { copyEnabled: true });
    body.dataset.detailLoaded = record.__detailLoaded ? 'true' : 'false';
  } catch (error) {
    console.error('診療履歴詳細表示エラー:', error);
    body.innerHTML = '<div class="history-empty-row">診療履歴の表示に失敗しました。</div>';
    body.dataset.detailLoaded = 'false';
  }
}

function hasHistoryRecordSoap(record = {}) {
  return ['subjective', 'objective', 'assessment', 'plan']
    .some(key => String(record[key] || '').trim());
}

function buildKarteEditorHtmlFromRecord(record = {}) {
  return [
    ['主訴', record.subjective],
    ['身体所見', record.objective],
    ['アセスメント', record.assessment],
    ['プラン', record.plan]
  ]
    .map(([label, value]) => (
      `
        <p><strong>【${escapeHtml(label)}】</strong></p>
        <div class="karte-soap-section-body">${sanitizeStoredKarteSoapHtml(value) || '<p><br></p>'}</div>
      `
    ))
    .join('\n');
}

async function loadHistoryRecordDetailForCopy(recordId) {
  if (!recordId) return null;
  const key = String(recordId);
  const cached = historyRecordDetailCache.get(key);
  try {
    const detailResult = await RecordAPI.get(recordId);
    const detail = detailResult.data || detailResult;
    const detailedRecord = {
      ...(cached || {}),
      ...detail,
      billings: detail.billings || cached?.billings || [],
      prescriptions: detail.prescriptions || cached?.prescriptions || [],
      __detailLoaded: true
    };
    historyRecordDetailCache.set(key, detailedRecord);
    return detailedRecord;
  } catch (error) {
    if (cached) {
      return { ...cached, __detailLoaded: true };
    }
    throw error;
  }
}

function copyHistoryRecordSoapToCurrentKarte(record) {
  const editor = document.getElementById('karte-editor');
  if (!editor) {
    showToast('カルテ入力欄が見つかりません', 'error');
    return false;
  }
  if (!hasHistoryRecordSoap(record)) {
    showToast('複写できる主訴・所見がありません', 'info');
    return false;
  }

  const shouldReplace = isKarteEditorBlank(editor);
  activateKarteEditorForEditing();
  const sourceHtml = buildKarteEditorHtmlFromRecord(record);

  if (shouldReplace) {
    editor.innerHTML = sourceHtml;
  } else {
    editor.insertAdjacentHTML('beforeend', `<p><br></p>${sourceHtml}`);
  }

  saveCurrentPatientBilling();
  showToast('主訴・所見を複写しました', 'success');
  return true;
}

function prepareHistoryBillingForCopy(billing) {
  const item = cloneKarteSetOrderItem(billing);
  delete item.id;
  delete item.billing_id;
  delete item.record_id;
  item.source = 'history_copy';
  return item;
}

function prepareHistoryPrescriptionForCopy(prescription) {
  const item = cloneKarteSetOrderItem(prescription);
  delete item.id;
  delete item.prescription_id;
  delete item.record_id;
  item.source = 'history_copy';
  return item;
}

function buildHistoryOrdersForCopy(record = {}) {
  const billingEntries = (record.billings || [])
    .filter(billing => !isPrescriptionDrugFeeBillingItem(billing))
    .map((billing, index) => createBillingAppendEntry(prepareHistoryBillingForCopy(billing), index))
    .filter(Boolean);
  const prescriptionEntries = (record.prescriptions || [])
    .map((prescription, index) => createPrescriptionAppendEntry(prepareHistoryPrescriptionForCopy(prescription), index))
    .filter(Boolean);

  remapKarteSetAppendGroups(billingEntries, prescriptionEntries);

  const billings = billingEntries.map(entry => {
    entry.item.source = 'history_copy';
    assignProcedureEntryOrderForAppend(entry.item);
    return syncActionDerivedFields(entry.item);
  });
  const prescriptions = prescriptionEntries.map(entry => {
    entry.item.source = 'history_copy';
    assignProcedureEntryOrderForAppend(entry.item);
    return syncPrescriptionDerivedFields(ensurePrescriptionIdentity(entry.item));
  });

  return { billings, prescriptions };
}

function buildHistoryOrderItemForCopy(record = {}, itemKind, itemIndex) {
  const index = Number(itemIndex);
  if (!Number.isInteger(index) || index < 0) {
    return { billings: [], prescriptions: [] };
  }

  if (itemKind === 'prescription') {
    const prescription = (record.prescriptions || [])[index];
    const entry = prescription
      ? createPrescriptionAppendEntry(prepareHistoryPrescriptionForCopy(prescription), index)
      : null;
    if (!entry) return { billings: [], prescriptions: [] };
    clearKarteSetPrescriptionGroup(entry.item);
    entry.item.source = 'history_copy';
    assignProcedureEntryOrderForAppend(entry.item);
    return {
      billings: [],
      prescriptions: [syncPrescriptionDerivedFields(ensurePrescriptionIdentity(entry.item))]
    };
  }

  const billing = (record.billings || [])[index];
  if (!billing || isPrescriptionDrugFeeBillingItem(billing)) {
    return { billings: [], prescriptions: [] };
  }
  const entry = createBillingAppendEntry(prepareHistoryBillingForCopy(billing), index);
  if (!entry) return { billings: [], prescriptions: [] };
  clearKarteSetBillingGroup(entry.item);
  entry.item.source = 'history_copy';
  assignProcedureEntryOrderForAppend(entry.item);
  return {
    billings: [syncActionDerivedFields(entry.item)],
    prescriptions: []
  };
}

function appendCopiedHistoryOrdersToCurrentKarte(copied, message) {
  if (!copied.billings.length && !copied.prescriptions.length) {
    showToast('複写できる処置・行為がありません', 'info');
    return false;
  }

  activateKarteEditorForEditing();
  selectedProcedureGroupAnchorId = null;
  selectedPrescriptionGroupAnchorId = null;
  selectedActions.push(...copied.billings);
  pendingPrescriptions.push(...copied.prescriptions);

  renderSelectedActionsInProcedure();
  renderPendingPrescriptionsInProcedure();
  updateTotalPoints();
  updateSelectedList();
  saveCurrentPatientBilling();
  refreshKarteValidationWarningsForCurrentOrders();
  showToast(message || '処置・行為を複写しました', 'success');
  return true;
}

function copyHistoryRecordOrdersToCurrentKarte(record) {
  return appendCopiedHistoryOrdersToCurrentKarte(
    buildHistoryOrdersForCopy(record),
    '処置・行為を複写しました'
  );
}

function copyHistoryRecordOrderItemToCurrentKarte(record, itemKind, itemIndex) {
  return appendCopiedHistoryOrdersToCurrentKarte(
    buildHistoryOrderItemForCopy(record, itemKind, itemIndex),
    itemKind === 'prescription' ? '処方を複写しました' : '算定を複写しました'
  );
}

async function copyHistoryRecordItemToCurrentKarte(recordId, itemKind, itemIndex, target = null) {
  if (!currentPatient?.id) {
    showToast('患者を選択してください', 'error');
    return;
  }
  if (!recordId) return;

  const originalOpacity = target?.style?.opacity;
  try {
    if (target) {
      target.style.opacity = '0.55';
    }

    const record = await loadHistoryRecordDetailForCopy(recordId);
    if (!record) {
      showToast('複写元のカルテを取得できません', 'error');
      return;
    }
    if (record.patient_id && String(record.patient_id) !== String(currentPatient.id)) {
      showToast('別患者の履歴は複写できません', 'error');
      return;
    }

    copyHistoryRecordOrderItemToCurrentKarte(record, itemKind, itemIndex);
  } catch (error) {
    console.error('診療履歴算定複写エラー:', error);
    showToast('算定の複写に失敗しました', 'error');
  } finally {
    if (target) {
      target.style.opacity = originalOpacity || '';
    }
  }
}

async function copyHistoryRecordSectionToCurrentKarte(recordId, copyType, button = null) {
  if (!currentPatient?.id) {
    showToast('患者を選択してください', 'error');
    return;
  }
  if (!recordId) return;

  const originalHtml = button?.innerHTML;
  try {
    if (button) {
      button.disabled = true;
      button.innerHTML = '<i class="fas fa-spinner fa-spin" aria-hidden="true"></i>';
    }

    const record = await loadHistoryRecordDetailForCopy(recordId);
    if (!record) {
      showToast('複写元のカルテを取得できません', 'error');
      return;
    }
    if (record.patient_id && String(record.patient_id) !== String(currentPatient.id)) {
      showToast('別患者の履歴は複写できません', 'error');
      return;
    }

    if (copyType === 'orders') {
      copyHistoryRecordOrdersToCurrentKarte(record);
    } else {
      copyHistoryRecordSoapToCurrentKarte(record);
    }
  } catch (error) {
    console.error('診療履歴複写エラー:', error);
    showToast('診療履歴の複写に失敗しました', 'error');
  } finally {
    if (button) {
      button.disabled = false;
      button.innerHTML = originalHtml || '<i class="fas fa-share" aria-hidden="true"></i>';
    }
  }
}

function clearActiveHistorySelection() {
  document.querySelectorAll('.history-card, .history-item').forEach(item => {
    item.classList.remove('active');
    if (!item.classList.contains('history-card')) {
      item.classList.remove('expanded');
    }
  });
}

function setActiveHistoryRecord(recordId) {
  clearActiveHistorySelection();
  document.querySelectorAll(`[data-id="${recordId}"]`).forEach(item => {
    item.classList.add('active');
    if (item.classList.contains('history-card')) {
      item.classList.add('expanded');
    }
  });
}

// 日付を曜日付きでフォーマット
function formatDateWithDay(dateStr) {
  if (!dateStr) return '';
  const date = new Date(dateStr);
  const days = ['日', '月', '火', '水', '木', '金', '土'];
  const y = date.getFullYear();
  const m = date.getMonth() + 1;
  const d = date.getDate();
  const day = days[date.getDay()];
  return `${y}/${m}/${d} (${day})`;
}

function formatMultilineHistoryText(value) {
  return sanitizeStoredKarteSoapHtml(value);
}

function renderHistorySoapSection(label, value) {
  const body = formatMultilineHistoryText(value);
  if (!body) return '';
  const labelHtml = label ? `<div class="history-soap-label">${escapeHtml(label)}</div>` : '';
  return `
    <div class="history-soap-section">
      ${labelHtml}
      <div class="history-soap-text">${body}</div>
    </div>
  `;
}

// SOAP形式でフォーマット（シンプル）
function formatSOAP(record) {
  let text = '';
  if (record.subjective) {
    text += `【主訴】\n${record.subjective}\n\n`;
  }
  if (record.objective) {
    text += `【身体所見】\n${record.objective}\n\n`;
  }
  if (record.assessment) {
    text += `【アセスメント＆プラン】\n${record.assessment}`;
  }
  if (record.plan) {
    text += `\n${record.plan}`;
  }
  return escapeHtml(text.trim() || '記載なし');
}

// SOAP形式でフォーマット（詳細表示用）
function formatSOAPDisplay(record) {
  const apText = [record.assessment, record.plan].filter(Boolean).join('\n');
  const html = [
    renderHistorySoapSection('【主訴】', record.subjective),
    renderHistorySoapSection('【身体所見】', record.objective),
    renderHistorySoapSection('【アセスメント＆プラン】', apText)
  ].filter(Boolean).join('');

  return html || '<div class="history-empty-row">記載なし</div>';
}

// 算定項目をフォーマット（シンプル）
function formatBillingItems(billings) {
  if (!billings || billings.length === 0) {
    return '<div class="history-item"><span style="color:#888;">算定項目なし</span></div>';
  }
  return billings.map(b => `
    <div class="history-item">
      <span class="history-item-icon shinsatsu">診</span>
      <span class="history-item-name">${escapeHalfWidthNumericText(b.billing_name)}</span>
      <span class="history-item-points">${b.points}点</span>
    </div>
  `).join('');
}

function buildHistoryOrderItemCopyAttributes(options = {}) {
  if (!options.copyEnabled || !options.recordId) return '';
  const attrs = [
    `data-history-copy-item-record-id="${escapeHtml(options.recordId)}"`,
    `data-history-copy-item-kind="${escapeHtml(options.kind || '')}"`,
    `data-history-copy-item-index="${escapeHtml(String(options.index ?? ''))}"`,
    'role="button"',
    'tabindex="0"',
    'title="クリックで複写"'
  ];
  return ` ${attrs.join(' ')}`;
}

// 算定項目をフォーマット（詳細表示用）
function formatBillingItemsDetailed(billings, prescriptions, options = {}) {
  const rows = [
    ...(prescriptions || []).map((item, index) => ({
      kind: 'prescription',
      index,
      item,
      order: getProcedureEntrySortOrder(item, 'prescription', index)
    })),
    ...(billings || []).map((item, index) => ({
      kind: 'billing',
      index,
      item,
      order: getProcedureEntrySortOrder(item, 'action', index)
    }))
  ].sort((a, b) => {
    if (a.order !== b.order) return a.order - b.order;
    return a.kind.localeCompare(b.kind);
  });

  let html = rows.map(row => (
    row.kind === 'prescription'
      ? formatHistoryPrescriptionRow(row.item, { ...options, kind: row.kind, index: row.index })
      : formatHistoryBillingRow(row.item, { ...options, kind: row.kind, index: row.index })
  )).join('');

  if (!html) {
    html = '<div class="history-empty-row">処置・行為なし</div>';
  }

  return html;
}

function formatHistoryPrescriptionRow(prescription, options = {}) {
  const quantity = formatHistoryPrescriptionQuantity(prescription);
  const instructions = prescription.instructions || prescription.note || '';
  const dispensingType = normalizePrescriptionDispensingType(prescription);
  const frequency = prescription.frequency || '';
  return `
    <div class="history-prescription-row"${buildHistoryOrderItemCopyAttributes(options)}>
      <div class="history-prescription-main">
        <span class="billing-icon billing-icon-yellow">薬</span>
        <span class="billing-name">${escapeHalfWidthNumericText(prescription.drug_name || prescription.name || '')}</span>
        <span class="billing-qty">${escapeHalfWidthNumericText(quantity)}</span>
      </div>
      ${instructions ? `
        <div class="history-prescription-sub">
          <i class="fas fa-comment-dots"></i>
          <span>${escapeHtml(instructions)}</span>
        </div>
      ` : ''}
      <div class="history-prescription-usage">
        <span>${escapeHtml(dispensingType)}</span>
        <span>${escapeHalfWidthNumericText(frequency)}</span>
      </div>
    </div>
  `;
}

function formatHistoryPrescriptionQuantity(prescription) {
  const quantity = prescription.total_quantity ?? prescription.quantity ?? prescription.dosage_quantity ?? '';
  const unit = prescription.unit || prescription.dosage_unit || '';
  if (quantity === '' || quantity === null || quantity === undefined) return '';
  return formatHalfWidthNumericText([String(quantity), unit].filter(Boolean).join(' '));
}

function formatHistoryBillingRow(billing, options = {}) {
  const quantity = Number(billing.quantity || 1);
  const points = Number(billing.points || 0);
  const copyOptions = isPrescriptionDrugFeeBillingItem(billing)
    ? { ...options, copyEnabled: false }
    : options;
  return `
    <div class="billing-row"${buildHistoryOrderItemCopyAttributes(copyOptions)}>
      <span class="billing-icon billing-icon-blue">診</span>
      <span class="billing-name">${escapeHalfWidthNumericText(billing.billing_name || billing.name || '')}</span>
      <span class="billing-points">${points > 0 ? `${points}点` : ''}</span>
      <span class="billing-count">${quantity > 0 ? `${quantity}回` : ''}</span>
    </div>
  `;
}

window.toggleHistoryCard = toggleHistoryCard;

function hydrateOrderStateFromRecord(record) {
  setKarteClaimType(record.receipt_claim_type);
  currentRecordVitalSigns = normalizeKarteVitalSigns(record?.vital_signs || record?.vitalSigns);
  setPrescriptionRemarksValue(getPrescriptionRemarksFromRecord(record));

  const recordBillings = Array.isArray(record.billings) ? record.billings : [];
  const recordDate = normalizeKarteDateValue(record.visit_date) || getCurrentKarteDateValue();
  const draftKey = getPatientDraftKey(
    record.patient_id || currentPatient?.id,
    recordDate,
    record.reception_id || record.receptionId || getCurrentReceptionRecordId()
  );
  const draft = draftKey ? patientBillingData[draftKey] : null;
  const savedBillingDisplay = recordBillings.length === 0 ? getCompletedBillingDisplayData() : null;
  const savedDisplayItems = hasBillingDisplayItems(savedBillingDisplay)
    ? (savedBillingDisplay.billing?.items || [])
    : [];
  const sourceBillings = recordBillings.length > 0
    ? recordBillings
    : (
      Array.isArray(draft?.selectedActions) && draft.selectedActions.length > 0
        ? draft.selectedActions
        : savedDisplayItems
    );
  const sourceBillingsForActions = sourceBillings.filter(billing => !isPrescriptionDrugFeeBillingItem(billing));

  selectedActions = sourceBillingsForActions.map(billing => {
    const isSelfPay = Boolean(billing.is_self_pay || billing.isSelfPay || billing.item_type === 'self_pay' || billing.category === '自費');
    const unitAmount = isSelfPay
      ? Number(billing.unit_price || billing.price || billing.amount || 0)
      : Number(billing.amount || billing.price || billing.unit_price || 0);
    return normalizeOrderAction({
      code: billing.billing_code || billing.code,
      name: billing.billing_name || billing.name,
      points: billing.points ?? billing.score,
      amount: unitAmount,
      price: unitAmount,
      unit_price: unitAmount,
      quantity: billing.quantity || 1,
      category: billing.category || (isSelfPay ? '自費' : '診察'),
      item_type: billing.item_type || (isSelfPay ? 'self_pay' : ''),
      isSelfPay,
      comments: billing.comments || billing.comment_names || [],
      comment_codes: billing.comment_codes || [],
      free_comment: billing.free_comment || '',
      receipt_position: billing.receipt_position || 'summary',
      do_not_bill: Boolean(billing.do_not_bill),
      billing_group_id: billing.billing_group_id || billing.billingGroupId || '',
      billing_group_parent_id: billing.billing_group_parent_id || billing.billingGroupParentId || '',
      billing_group_label: billing.billing_group_label || billing.billingGroupLabel || '',
      procedure_order: billing.procedure_order || billing.procedureOrder || billing.sort_order || billing.sortOrder || null,
      source: billing.source || billing.billing_source || ''
    }, 'exam');
  });
  selectedActions = selectedActions.map(action => syncActionDerivedFields(action));
  selectedProcedureGroupAnchorId = null;

  pendingPrescriptions.length = 0;
  procedureEntryOrderCounter = 0;
  pendingPrescriptions.push(...JSON.parse(JSON.stringify(record.prescriptions || []))
    .map(prescription => syncPrescriptionDerivedFields(ensurePrescriptionIdentity(prescription))));
  selectedPrescriptionGroupAnchorId = null;

  renderSelectedActionsInProcedure();
  renderPendingPrescriptionsInProcedure();
  updateTotalPoints();
  updateSelectedList();
  refreshKarteValidationWarningsForCurrentOrders();
  refreshVitalsIfVisible(record?.patient_id || currentPatient?.id);
}

function buildKarteContextFromRecord(record = {}) {
  const cachedReception = record.reception_id
    ? receptionsCache.find(item => String(item.id) === String(record.reception_id))
    : null;
  const insuranceId = record.insurance_id || cachedReception?.insurance_id || '';
  const publicExpenseIds = [
    record.public_expense_1_id,
    record.public_expense_id,
    cachedReception?.public_expense_1_id,
    cachedReception?.public_expense_id
  ].filter(Boolean);
  const doctorName = getHistoryFirstText(
    record.doctor_name,
    record.doctor,
    cachedReception?.doctor_name_override,
    cachedReception?.doctor_name,
    cachedReception?.doctor
  );

  return {
    ...(cachedReception || {}),
    id: record.reception_id || cachedReception?.id || '',
    source: record.reception_id || cachedReception?.id ? 'reception' : 'record',
    patient_id: record.patient_id || currentPatient?.id || '',
    patient_no: record.patient_no || currentPatient?.patient_no || '',
    patient_name: record.patient_name || currentPatient?.name || '',
    reception_date: normalizeKarteDateValue(record.visit_date) || cachedReception?.reception_date || getCurrentKarteDateValue(),
    visit_date: normalizeKarteDateValue(record.visit_date) || cachedReception?.visit_date || getCurrentKarteDateValue(),
    visit_type: record.visit_type || cachedReception?.visit_type || '外来',
    department: record.department || cachedReception?.department || document.getElementById('karte-department')?.value || '内科',
    doctor_name: doctorName,
    doctor: doctorName,
    doctor_name_override: cachedReception?.doctor_name_override || '',
    insurance_id: insuranceId || null,
    insurance_type: record.insurance_type || cachedReception?.insurance_type || '',
    public_expense_1_id: publicExpenseIds[0] || null,
    public_expense_2_id: record.public_expense_2_id || cachedReception?.public_expense_2_id || null,
    public_expense_3_id: record.public_expense_3_id || cachedReception?.public_expense_3_id || null,
    insurance_card_status: insuranceId
      ? (cachedReception?.insurance_card_status || 'confirmed')
      : (cachedReception?.insurance_card_status || 'unchecked'),
    medical_certificate_status: publicExpenseIds.length
      ? (cachedReception?.medical_certificate_status || 'confirmed')
      : (cachedReception?.medical_certificate_status || 'none'),
    limit_certificate_status: cachedReception?.limit_certificate_status || 'unchecked',
    electronic_prescription_status: cachedReception?.electronic_prescription_status || 'none',
    past_prescription_status: cachedReception?.past_prescription_status || 'unchecked',
    labor_auto_insurance: cachedReception?.labor_auto_insurance || 'none',
    save_mode: cachedReception?.save_mode || 'normal'
  };
}

async function applyKarteContextFromRecord(record = {}, isCurrentRequest = () => true) {
  if (currentPatient?.id && String(record.patient_id || '') === String(currentPatient.id || '') && window.InsuranceAPI) {
    if (!currentPatientInsurances.length && !currentPatientPublicExpenses.length) {
      await loadPatientInsurances(currentPatient.id);
    }
  }

  if (!isCurrentRequest()) return;
  currentReception = buildKarteContextFromRecord(record);
  if (currentReception.id && currentReception.source === 'reception') {
    upsertReceptionCache(currentReception);
  }
  syncCurrentReceptionContextFromPatientData();

  const department = document.getElementById('karte-department');
  if (department && currentReception.department) {
    department.value = currentReception.department;
  }
  updateKarteHeaderContext(getRecordHistoryStatusLabel(record));
}

async function openHistoryRecordForEditing(recordId, button = null) {
  if (!recordId) return;
  const originalHtml = button?.innerHTML;
  try {
    if (button) {
      button.disabled = true;
      button.innerHTML = '<i class="fas fa-spinner fa-spin"></i>';
    }
    showLoading();
    const record = await loadRecordDetail(recordId);
    if (record) {
      showToast('履歴カルテを編集表示に切り替えました', 'success');
    }
  } catch (error) {
    console.error('履歴カルテ編集表示エラー:', error);
    showToast('履歴カルテの読み込みに失敗しました', 'error');
  } finally {
    hideLoading();
    if (button) {
      button.disabled = false;
      button.innerHTML = originalHtml || '<i class="fas fa-pen"></i>';
    }
  }
}

// カルテ詳細を読み込んでエディタに表示
async function loadRecordDetail(recordId, options = {}) {
  const requestId = options.requestId ?? ++karteInitializationRequestId;
  const patientId = currentPatient?.id;
  const isCurrentRequest = () => requestId === karteInitializationRequestId && currentPatient?.id === patientId;
  try {
    if (!(await confirmDiscardKarteChangesIfNeeded())) return null;
    if (!isCurrentRequest()) return null;
    resetSetTreeExpansionState();
    const record = options.record || await RecordAPI.get(recordId);
    if (!isCurrentRequest()) return null;
    await applyKarteContextFromRecord(record, isCurrentRequest);
    if (!isCurrentRequest()) return null;
    currentRecordId = record.id || recordId;
    currentRecordVisitDate = normalizeKarteDateValue(record.visit_date);

    // エディタにカルテ内容を表示
    const editor = document.getElementById('karte-editor');
    if (editor) {
      activateKarteEditorForEditing();
      editor.innerHTML = buildKarteEditorHtmlFromRecord(record);
    }

    // 日付を設定
    setKarteDate(currentRecordVisitDate || record.visit_date);
    const draftKey = getPatientDraftKey(patientId, getCurrentKarteDateValue());
    if (patientBillingData[draftKey]?.deleted) {
      clearPatientBillingData(patientId, getCurrentKarteDateValue());
    }

    // そのカルテ日付の処方・算定だけを画面状態へ復元
    hydrateOrderStateFromRecord(record);
    const recordBillingId = (record.billings || [])
      .map(item => item.billing_id || item.billingId)
      .find(Boolean);
    currentBilling = recordBillingId
      ? { id: recordBillingId, billingId: recordBillingId }
      : null;
    resetKarteDirtyTracking();

    // 選択中の履歴をハイライト
    setActiveHistoryRecord(recordId);
    return record;

  } catch (error) {
    if (!isCurrentRequest()) return null;
    console.error('カルテ詳細取得エラー:', error);
    showToast('カルテの読み込みに失敗しました', 'error');
    throw error;
  }
}

// 処方一覧を表示
function displayPrescriptions(prescriptions) {
  const container = document.getElementById('selected-list');
  if (!container) return;

  const prescHtml = prescriptions.map(p => `
    <div class="prescription-item">
      <span class="rx-icon">Rx</span>
      <span class="rx-name">${escapeHalfWidthNumericText(p.drug_name)}</span>
      <span class="rx-detail">${escapeHalfWidthNumericText(`${p.dosage || ''} ${p.frequency || ''} ${formatPrescriptionDuration(p.days, p.frequency, '分')}`)}</span>
    </div>
  `).join('');

  container.innerHTML = prescHtml || '<p class="no-data">処方なし</p>';
}

// 算定一覧を表示
function displayBillings(billings) {
  const container = document.getElementById('selected-list');
  const totalEl = document.getElementById('total-points');
  if (!container) return;

  const billHtml = billings.map(b => `
    <div class="menu-item selected">
      <span class="item-icon">診</span>
      <span class="item-name">${escapeHalfWidthNumericText(b.billing_name)}</span>
      <span class="item-points">${b.points}点</span>
    </div>
  `).join('');

  container.innerHTML = billHtml || '<p class="no-data">算定なし</p>';

  const total = billings.reduce((sum, b) => sum + (b.points * b.quantity), 0);
  if (totalEl) {
    totalEl.textContent = `合計: ${total}点`;
  }
}

