function renderPatientHistory(patientId) {
  const records = Storage.getRecords().filter(r => r.patientId === patientId);
  const container = document.getElementById('history-list');
  if (!container) return;
  bindHistoryCardActions(container);

  if (records.length === 0) {
    container.innerHTML = emptyClinicalMessage('診療履歴がありません。');
    return;
  }

  records.sort((a, b) => new Date(b.date) - new Date(a.date));

  container.innerHTML = records.map(r => `
    <div class="history-item" data-id="${r.id}">
      <div class="history-date">
        <span class="history-date-text">${r.date}</span>
        <span class="history-status">承認</span>
      </div>
      <div class="history-content">
        ${r.department || '内科'} ${r.doctor || ''}<br>
        ${escapeHtml(r.content?.substring(0, 50) || '')}...
      </div>
    </div>
  `).join('');
}

// ====================================
// 算定メニュー
// ====================================
function initMenuItems() {
  document.querySelectorAll('.menu-item').forEach(item => {
    item.addEventListener('click', () => {
      const name = item.querySelector('.item-name').textContent;
      const points = parseInt(item.dataset.points);

      // 選択状態をトグル
      if (item.classList.contains('selected')) {
        item.classList.remove('selected');
        selectedItems = selectedItems.filter(i => i.name !== name);
      } else {
        item.classList.add('selected');
        selectedItems.push({ name, points });
      }

      updateSelectedList();
      saveCurrentPatientBilling();
    });
  });
}

function updateSelectedList() {
  const container = document.getElementById('selected-list');
  const totalEl = document.getElementById('total-points');

  if (!container) return;

  if (selectedItems.length === 0) {
    container.innerHTML = '<p class="no-data" style="padding:10px;">選択なし</p>';
    if (totalEl) totalEl.textContent = '合計: 0点';
    return;
  }

  container.innerHTML = selectedItems.map(item => `
    <div class="menu-item selected" style="margin-bottom:2px;">
      <span class="item-icon">診</span>
      <span class="item-name">${escapeHalfWidthNumericText(item.name)}</span>
      <span class="item-points">${item.points}点</span>
    </div>
  `).join('');

  const total = selectedItems.reduce((sum, item) => sum + item.points, 0);
  if (totalEl) totalEl.textContent = `合計: ${total}点`;
}

// ====================================
// モーダル（患者登録）
// ====================================
function syncPatientModalActions() {
  const isEditing = document.getElementById('patient-modal')?.dataset.editMode === 'true';
  const saveButton = document.getElementById('btn-register');
  const checkinButton = document.getElementById('btn-register-checkin');
  if (saveButton) saveButton.textContent = isEditing ? '更新' : '登録';
  if (checkinButton) {
    checkinButton.classList.toggle('hidden', isEditing);
    checkinButton.disabled = isEditing;
  }
}

function initModal() {
  const modal = document.getElementById('patient-modal');
  const closeBtn = document.getElementById('modal-close');
  const cancelBtn = document.getElementById('btn-cancel');
  const registerBtn = document.getElementById('btn-register');
  const registerCheckinBtn = document.getElementById('btn-register-checkin');

  // 閉じるボタン
  closeBtn.addEventListener('click', () => modal.classList.add('hidden'));
  cancelBtn.addEventListener('click', () => modal.classList.add('hidden'));

  // モーダル外クリックで閉じる
  modal.addEventListener('click', (e) => {
    if (e.target === modal) modal.classList.add('hidden');
  });

  // 登録ボタン
  registerBtn.addEventListener('click', () => registerPatient(false));
  registerCheckinBtn.addEventListener('click', () => registerPatient(true));
  document.getElementById('btn-check-online')?.addEventListener('click', () => {
    markExternalIntegrationUnavailable('オンライン資格確認', { context: 'patient_registration' });
  });

  // 患者番号自動生成
  const patientIdInput = document.getElementById('patient-id');
  if (!patientIdInput.value) {
    patientIdInput.value = generatePatientId();
  }

  // 郵便番号検索
  const postalSearchBtn = document.getElementById('btn-postal-search');
  const postalCodeInput = document.getElementById('postal-code');

  if (postalSearchBtn) {
    postalSearchBtn.addEventListener('click', searchPostalCode);
  }

  // 郵便番号入力時に自動検索（ハイフン含めて7-8文字で）
  if (postalCodeInput) {
    postalCodeInput.addEventListener('input', (e) => {
      const value = e.target.value.replace(/-/g, '');
      if (value.length === 7) {
        searchPostalCode();
      }
    });
  }

  // 生年月日コンボボックス初期化
  initBirthDateComboboxes();
  initPatientFormValidation();
  setDefaultPatientGenderIfUnset();
  setDefaultPatientBirthYearIfUnset();
}

// 生年月日コンボボックスを初期化
function initBirthDateComboboxes() {
  // 年のドロップダウン生成（古い順）
  const yearDropdown = document.getElementById('year-dropdown');
  if (yearDropdown && yearDropdown.children.length === 0) {
    const currentYear = new Date().getFullYear();
    for (let year = 1920; year <= currentYear; year++) {
      const div = document.createElement('div');
      div.className = 'combobox-option';
      div.dataset.value = year;
      div.textContent = `${year}(${getJapaneseEra(year)})`;
      yearDropdown.appendChild(div);
    }
  }

  // 月のドロップダウン生成
  const monthDropdown = document.getElementById('month-dropdown');
  if (monthDropdown && monthDropdown.children.length === 0) {
    for (let month = 1; month <= 12; month++) {
      const div = document.createElement('div');
      div.className = 'combobox-option';
      div.dataset.value = month;
      div.textContent = month;
      monthDropdown.appendChild(div);
    }
  }

  // 日のドロップダウン生成
  const dayDropdown = document.getElementById('day-dropdown');
  if (dayDropdown && dayDropdown.children.length === 0) {
    for (let day = 1; day <= 31; day++) {
      const div = document.createElement('div');
      div.className = 'combobox-option';
      div.dataset.value = day;
      div.textContent = day;
      dayDropdown.appendChild(div);
    }
  }

  // コンボボックスのイベント設定
  document.querySelectorAll('.combobox').forEach(combobox => {
    const input = combobox.querySelector('.combobox-input');
    const btn = combobox.querySelector('.combobox-btn');
    const dropdown = combobox.querySelector('.combobox-dropdown');
    const setOptionsVisibility = (filter = '') => {
      const normalizedFilter = String(filter || '').normalize('NFKC').trim().toLowerCase();
      dropdown.querySelectorAll('.combobox-option').forEach(opt => {
        const value = String(opt.dataset.value || '').normalize('NFKC').toLowerCase();
        const text = String(opt.textContent || '').normalize('NFKC').toLowerCase();
        opt.style.display = !normalizedFilter || value.includes(normalizedFilter) || text.includes(normalizedFilter) ? '' : 'none';
      });
    };
    const hasExactOption = () => {
      const normalizedValue = String(input.value || '').normalize('NFKC').trim();
      if (!normalizedValue) return false;
      const numericValue = /^\d+$/.test(normalizedValue) ? String(Number(normalizedValue)) : normalizedValue;
      return [...dropdown.querySelectorAll('.combobox-option')].some(opt =>
        String(opt.dataset.value || '') === normalizedValue
        || String(opt.dataset.value || '') === numericValue
      );
    };
    const highlightCurrentOption = () => {
      const currentValue = String(input.value || '').normalize('NFKC').trim();
      const numericValue = /^\d+$/.test(currentValue) ? String(Number(currentValue)) : currentValue;
      let selectedOption = null;
      dropdown.querySelectorAll('.combobox-option').forEach(opt => {
        opt.classList.remove('highlighted', 'selected');
        if (String(opt.dataset.value || '') === currentValue || String(opt.dataset.value || '') === numericValue) {
          opt.classList.add('selected');
          selectedOption = opt;
        }
      });
      if (selectedOption) {
        selectedOption.scrollIntoView({
          block: input.id === 'birth-year' ? 'start' : 'nearest'
        });
      }
    };

    // ボタンクリックでドロップダウン開閉
    btn.addEventListener('click', (e) => {
      e.preventDefault();
      e.stopPropagation();
      const wasOpen = combobox.classList.contains('open');
      closeAllComboboxes();
      if (!wasOpen) {
        setOptionsVisibility();
        combobox.classList.add('open');
        highlightCurrentOption();
      }
    });

    // 入力フィールドクリックでも開く
    input.addEventListener('click', () => {
      closeAllComboboxes();
      setOptionsVisibility();
      combobox.classList.add('open');
      highlightCurrentOption();
    });

    // オプションクリック
    dropdown.addEventListener('click', (e) => {
      if (e.target.classList.contains('combobox-option')) {
        input.value = e.target.dataset.value;
        input.dispatchEvent(new Event('input', { bubbles: true }));
        combobox.classList.remove('open');
        input.focus();
      }
    });

    // 入力時にフィルター
    input.addEventListener('input', () => {
      if (hasExactOption()) {
        setOptionsVisibility();
        highlightCurrentOption();
      } else {
        setOptionsVisibility(input.value);
      }
      combobox.classList.add('open');
    });

    // キーボード操作
    input.addEventListener('keydown', (e) => {
      if (e.key === 'ArrowDown') {
        e.preventDefault();
        combobox.classList.add('open');
        const visible = [...dropdown.querySelectorAll('.combobox-option')].filter(o => o.style.display !== 'none');
        const current = dropdown.querySelector('.combobox-option.highlighted');
        let next = current ? visible[visible.indexOf(current) + 1] : visible[0];
        if (next) {
          dropdown.querySelectorAll('.combobox-option').forEach(o => o.classList.remove('highlighted'));
          next.classList.add('highlighted');
          next.scrollIntoView({ block: 'nearest' });
        }
      } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        const visible = [...dropdown.querySelectorAll('.combobox-option')].filter(o => o.style.display !== 'none');
        const current = dropdown.querySelector('.combobox-option.highlighted');
        let prev = current ? visible[visible.indexOf(current) - 1] : visible[visible.length - 1];
        if (prev) {
          dropdown.querySelectorAll('.combobox-option').forEach(o => o.classList.remove('highlighted'));
          prev.classList.add('highlighted');
          prev.scrollIntoView({ block: 'nearest' });
        }
      } else if (e.key === 'Enter') {
        e.preventDefault();
        const highlighted = dropdown.querySelector('.combobox-option.highlighted');
        if (highlighted) {
          input.value = highlighted.dataset.value;
          input.dispatchEvent(new Event('input', { bubbles: true }));
          combobox.classList.remove('open');
        }
      } else if (e.key === 'Escape') {
        combobox.classList.remove('open');
      }
    });
  });

  // 外側クリックで閉じる
  document.addEventListener('click', (e) => {
    if (!e.target.closest('.combobox')) {
      closeAllComboboxes();
    }
  });
}

function closeAllComboboxes() {
  document.querySelectorAll('.combobox').forEach(c => c.classList.remove('open'));
}

// 西暦から和暦を取得
function getJapaneseEra(year) {
  if (year >= 2019) {
    return `令和${year - 2018}`;
  } else if (year >= 1989) {
    return `平成${year - 1988}`;
  } else if (year >= 1926) {
    return `昭和${year - 1925}`;
  } else if (year >= 1912) {
    return `大正${year - 1911}`;
  } else if (year >= 1868) {
    return `明治${year - 1867}`;
  }
  return '';
}

// 郵便番号から住所を検索
function searchPostalCode() {
  const postalCode = document.getElementById('postal-code').value.replace(/-/g, '');

  if (postalCode.length !== 7) {
    showToast('郵便番号は7桁で入力してください', 'error');
    return;
  }

  // zipcloud API を使用（JSONP）
  const script = document.createElement('script');
  script.src = `https://zipcloud.ibsnet.co.jp/api/search?zipcode=${postalCode}&callback=handlePostalResult`;
  document.body.appendChild(script);
  script.remove();
}

// 郵便番号検索結果のコールバック
window.handlePostalResult = function(data) {
  if (data.status === 200 && data.results) {
    const result = data.results[0];

    // 都道府県をセット
    const prefectureSelect = document.getElementById('prefecture');
    for (let option of prefectureSelect.options) {
      if (option.value === result.address1) {
        option.selected = true;
        break;
      }
    }

    // 市区町村をセット
    document.getElementById('city').value = result.address2;

    // 番地に町域をセット
    document.getElementById('address1').value = result.address3;

    // 市区町村フィールドにフォーカス
    document.getElementById('address1').focus();
  } else {
    showToast('該当する住所が見つかりませんでした', 'error');
  }
};

function showPatientModal() {
  const modal = document.getElementById('patient-modal');
  const searchModal = document.getElementById('patient-search-modal');
  if (searchModal) {
    searchModal.classList.add('hidden');
  }
  modal.dataset.editMode = '';
  modal.dataset.editPatientId = '';
  syncPatientModalActions();
  document.getElementById('modal-title').textContent = '患者情報登録';
  document.getElementById('patient-form')?.reset();
  clearPatientFormErrors();
  setDefaultPatientGenderIfUnset();
  setDefaultPatientBirthYearIfUnset();
  document.getElementById('patient-id').disabled = false;
  document.getElementById('patient-id').value = generatePatientId();
  modal.classList.remove('hidden');
  document.getElementById('patient-name')?.focus();
}

function generatePatientId() {
  const patients = Storage.getPatients();
  const maxId = patients.reduce((max, p) => {
    const rawId = p.patient_no || p.id || '';
    if (!/^\d+$/.test(String(rawId))) return max;
    const num = parseInt(String(rawId), 10);
    return num > max ? num : max;
  }, 0);
  return String(maxId + 1).padStart(5, '0');
}

function normalizePatientIdentityValue(value) {
  return String(value || '')
    .normalize('NFKC')
    .replace(/[\s\u3000]+/g, '')
    .toUpperCase();
}

function normalizePatientKanaIdentityValue(value) {
  return normalizePatientIdentityValue(value).replace(/[ぁ-ゖ]/g, char =>
    String.fromCharCode(char.charCodeAt(0) + 0x60)
  );
}

function getPatientIdentityBirthDate(patient) {
  return String(patient?.birth_date || patient?.birth || '').slice(0, 10);
}

function findDuplicatePatientForRegistration({ name, kana, birthDate }, excludePatientId = null) {
  const normalizedName = normalizePatientIdentityValue(name);
  const normalizedKana = normalizePatientKanaIdentityValue(kana);
  if (!normalizedName || !birthDate) return null;

  return Storage.getPatients().find(patient => {
    if (excludePatientId && String(patient.id) === String(excludePatientId)) return false;
    if (patient.is_active === false) return false;
    if (getPatientIdentityBirthDate(patient) !== birthDate) return false;

    const patientName = normalizePatientIdentityValue(patient.name);
    const patientKana = normalizePatientKanaIdentityValue(patient.name_kana || patient.kana);
    return patientName === normalizedName || (normalizedKana && patientKana === normalizedKana);
  }) || null;
}

function buildDuplicatePatientMessage(patient) {
  const patientNo = patient?.patient_no || patient?.id || '-';
  const name = patient?.name || '同一患者';
  return `同じ氏名・生年月日の患者が既に登録されています（患者番号: ${patientNo}、氏名: ${name}）`;
}

const PATIENT_FORM_FIELD_INPUT_IDS = Object.freeze({
  patientNo: ['patient-id'],
  name: ['patient-name'],
  kana: ['patient-kana'],
  birthDate: ['birth-year', 'birth-month', 'birth-day'],
  postalCode: ['postal-code'],
  phone1: ['phone1'],
  phone2: ['phone2']
});
const DEFAULT_PATIENT_BIRTH_YEAR = '1972';

function getPatientFormValue(id) {
  return String(document.getElementById(id)?.value ?? '').trim();
}

function getPatientFormFieldControls(field) {
  if (field === 'gender') {
    const radios = Array.from(document.querySelectorAll('#patient-modal input[name="gender"]'));
    const group = document.querySelector('#patient-modal .radio-group-patient');
    return { controls: radios, visualControls: group ? [group] : [] };
  }
  const controls = (PATIENT_FORM_FIELD_INPUT_IDS[field] || [])
    .map(id => document.getElementById(id))
    .filter(Boolean);
  return { controls, visualControls: controls };
}

function setPatientFieldError(field, message = '') {
  const error = document.querySelector(`[data-patient-error-for="${field}"]`);
  if (error) {
    error.textContent = message;
    error.classList.toggle('hidden', !message);
  }
  const { controls, visualControls } = getPatientFormFieldControls(field);
  controls.forEach(control => {
    if (message) {
      control.setAttribute('aria-invalid', 'true');
    } else {
      control.removeAttribute('aria-invalid');
    }
  });
  visualControls.forEach(control => control.classList.toggle('patient-field-invalid', Boolean(message)));
}

function clearPatientFieldError(field) {
  setPatientFieldError(field, '');
}

function clearPatientFormErrors() {
  document.querySelectorAll('[data-patient-error-for]').forEach(error => {
    const field = error.dataset.patientErrorFor;
    if (field) clearPatientFieldError(field);
  });
}

function setDefaultPatientGenderIfUnset(defaultGender = 'male') {
  const checked = document.querySelector('#patient-modal input[name="gender"]:checked');
  if (checked) return;
  const defaultRadio = document.querySelector(`#patient-modal input[name="gender"][value="${defaultGender}"]`);
  if (defaultRadio) defaultRadio.checked = true;
}

function setDefaultPatientBirthYearIfUnset(defaultYear = DEFAULT_PATIENT_BIRTH_YEAR) {
  const birthYearInput = document.getElementById('birth-year');
  if (birthYearInput && !birthYearInput.value) birthYearInput.value = defaultYear;
}

function isValidFullWidthKanaName(value) {
  return /^[ァ-ヶー・ヴヵヶ　\s]+$/.test(value);
}

function validatePatientBirthDate() {
  const yearText = getPatientFormValue('birth-year').normalize('NFKC');
  const monthText = getPatientFormValue('birth-month').normalize('NFKC');
  const dayText = getPatientFormValue('birth-day').normalize('NFKC');
  const missing = [];
  if (!yearText) missing.push('年');
  if (!monthText) missing.push('月');
  if (!dayText) missing.push('日');
  if (missing.length > 0) {
    return {
      valid: false,
      message: `生年月日の${missing.join('・')}を入力してください。`,
      focusId: !yearText ? 'birth-year' : !monthText ? 'birth-month' : 'birth-day'
    };
  }

  if (!/^\d{4}$/.test(yearText)) {
    return { valid: false, message: '生年月日の年は西暦4桁で入力してください。', focusId: 'birth-year' };
  }
  if (!/^\d{1,2}$/.test(monthText)) {
    return { valid: false, message: '生年月日の月は数字で入力してください。', focusId: 'birth-month' };
  }
  if (!/^\d{1,2}$/.test(dayText)) {
    return { valid: false, message: '生年月日の日は数字で入力してください。', focusId: 'birth-day' };
  }

  const year = Number(yearText);
  const month = Number(monthText);
  const day = Number(dayText);
  const currentYear = new Date().getFullYear();
  if (!Number.isInteger(year) || year < 1868 || year > currentYear) {
    return { valid: false, message: `生年月日の年は1868〜${currentYear}年で入力してください。`, focusId: 'birth-year' };
  }
  if (!Number.isInteger(month) || month < 1 || month > 12) {
    return { valid: false, message: '生年月日の月は1〜12で入力してください。', focusId: 'birth-month' };
  }
  if (!Number.isInteger(day) || day < 1 || day > 31) {
    return { valid: false, message: '生年月日の日は1〜31で入力してください。', focusId: 'birth-day' };
  }

  const candidate = new Date(year, month - 1, day);
  if (
    candidate.getFullYear() !== year
    || candidate.getMonth() !== month - 1
    || candidate.getDate() !== day
  ) {
    return { valid: false, message: '生年月日の日付が不正です。', focusId: 'birth-day' };
  }
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  if (candidate > today) {
    return { valid: false, message: '生年月日は未来の日付にできません。', focusId: 'birth-year' };
  }

  return {
    valid: true,
    birthDate: `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`
  };
}

function isValidOptionalPostalCode(value) {
  const normalized = String(value || '').normalize('NFKC').trim();
  return !normalized || /^\d{3}-?\d{4}$/.test(normalized);
}

function isValidOptionalPhoneNumber(value) {
  const normalized = String(value || '').normalize('NFKC').trim();
  if (!normalized) return true;
  if (!/^[0-9+\-()\s]+$/.test(normalized)) return false;
  const digits = normalized.replace(/\D/g, '');
  if (normalized.startsWith('+')) return digits.length >= 10 && digits.length <= 15;
  return digits.length >= 10 && digits.length <= 11;
}

function validatePatientForm({ includePatientNo = true } = {}) {
  clearPatientFormErrors();
  setDefaultPatientGenderIfUnset();

  const values = {
    patientNo: getPatientFormValue('patient-id'),
    name: getPatientFormValue('patient-name'),
    kana: getPatientFormValue('patient-kana'),
    gender: document.querySelector('#patient-modal input[name="gender"]:checked')?.value || '',
    postalCode: getPatientFormValue('postal-code'),
    phone1: getPatientFormValue('phone1'),
    phone2: getPatientFormValue('phone2')
  };
  const errors = [];

  const addError = (field, message, focusId = null) => {
    errors.push({ field, message, focusId });
    setPatientFieldError(field, message);
  };

  if (includePatientNo && !values.patientNo) {
    addError('patientNo', '患者番号を入力してください。', 'patient-id');
  }
  if (!values.name) {
    addError('name', '漢字氏名を入力してください。', 'patient-name');
  }
  if (!values.kana) {
    addError('kana', 'カナ氏名を入力してください。', 'patient-kana');
  } else if (!isValidFullWidthKanaName(values.kana)) {
    addError('kana', 'カナ氏名は全角カナで入力してください。', 'patient-kana');
  }
  if (!values.gender) {
    addError('gender', '性別を選択してください。');
  }

  const birthDateResult = validatePatientBirthDate();
  if (!birthDateResult.valid) {
    addError('birthDate', birthDateResult.message, birthDateResult.focusId);
  } else {
    values.birthDate = birthDateResult.birthDate;
  }

  if (!isValidOptionalPostalCode(values.postalCode)) {
    addError('postalCode', '郵便番号は7桁で入力してください。', 'postal-code');
  }
  if (!isValidOptionalPhoneNumber(values.phone1)) {
    addError('phone1', '電話番号1は数字・ハイフンで入力してください。', 'phone1');
  }
  if (!isValidOptionalPhoneNumber(values.phone2)) {
    addError('phone2', '電話番号2は数字・ハイフンで入力してください。', 'phone2');
  }

  const firstError = errors[0];
  const firstElement = firstError?.focusId
    ? document.getElementById(firstError.focusId)
    : getPatientFormFieldControls(firstError?.field).controls[0];

  return {
    valid: errors.length === 0,
    values,
    errors,
    firstElement,
    summary: errors.length === 1
      ? errors[0].message
      : `${errors.length}件の入力内容を確認してください。`
  };
}

function initPatientFormValidation() {
  const form = document.getElementById('patient-form');
  if (!form || form.dataset.patientValidationInitialized === 'true') return;
  form.dataset.patientValidationInitialized = 'true';

  [
    ['patient-id', 'patientNo'],
    ['patient-name', 'name'],
    ['patient-kana', 'kana'],
    ['birth-year', 'birthDate'],
    ['birth-month', 'birthDate'],
    ['birth-day', 'birthDate'],
    ['postal-code', 'postalCode'],
    ['phone1', 'phone1'],
    ['phone2', 'phone2']
  ].forEach(([id, field]) => {
    const input = document.getElementById(id);
    if (!input) return;
    input.addEventListener('input', () => clearPatientFieldError(field));
    input.addEventListener('change', () => clearPatientFieldError(field));
  });
  document.querySelectorAll('#patient-modal input[name="gender"]').forEach(input => {
    input.addEventListener('change', () => clearPatientFieldError('gender'));
  });
}

async function registerPatient(checkin) {
  const form = document.getElementById('patient-form');
  const modal = document.getElementById('patient-modal');

  // 編集モードかどうかをチェック
  const isEditMode = modal.dataset.editMode === 'true';
  const editPatientId = modal.dataset.editPatientId;

  if (isEditMode) {
    // 編集モードの場合は更新処理
    await updatePatient();
    return;
  }

  const validation = validatePatientForm({ includePatientNo: true });
  if (!validation.valid) {
    showToast(validation.summary, 'error');
    validation.firstElement?.focus();
    return;
  }

  const { patientNo, name, kana, gender, birthDate } = validation.values;
  const duplicatePatient = findDuplicatePatientForRegistration({ name, kana, birthDate });
  if (duplicatePatient) {
    const message = buildDuplicatePatientMessage(duplicatePatient);
    setPatientFieldError('name', message);
    showToast(message, 'error');
    document.getElementById('patient-name')?.focus();
    return;
  }

  // 住所を結合
  const address = [
    document.getElementById('prefecture').value,
    document.getElementById('city').value,
    document.getElementById('address1').value,
    document.getElementById('address2').value
  ].filter(Boolean).join(' ');

  const patientData = {
    patient_no: patientNo,
    name: name,
    name_kana: kana,
    gender: gender,
    birth_date: birthDate,
    postal_code: document.getElementById('postal-code').value,
    address: address,
    phone1: document.getElementById('phone1').value,
    phone2: document.getElementById('phone2').value
  };

  try {
    showLoading();
    const result = await PatientAPI.create(patientData);
    const createdPatient = getCreatedPatientSnapshot(result, patientData);
    const createdPatientId = createdPatient?.id;
    let createdReception = null;
    let checkinError = null;

    if (checkin) {
      if (createdPatientId) {
        try {
          createdReception = await createTodayReception(createdPatientId);
        } catch (error) {
          checkinError = error;
        }
      } else {
        checkinError = new Error('登録した患者IDを取得できませんでした');
      }
    }

    // モーダルを閉じる
    modal.classList.add('hidden');
    form.reset();
    setDefaultPatientGenderIfUnset();
    setDefaultPatientBirthYearIfUnset();

    // 患者データを再取得
    await loadPatients();

    // 患者セレクター更新
    updatePatientSelector();

    if (checkin) {
      await returnToTodayReceptionScreen();
    } else {
      await loadReceptions();
    }

    hideLoading();
    if (checkinError) {
      showToast('患者登録は完了しましたが、受付に失敗しました: ' + checkinError.message, 'error');
    } else {
      showToast(checkin ? '患者登録と受付を完了しました' : '患者を登録しました', 'success');
      if (checkin && createdPatientId) {
        await openPostCheckinReceptionRegistration(createdPatientId, createdReception);
      }
    }
  } catch (error) {
    hideLoading();
    const message = error.status === 409 ? error.message : '登録に失敗しました: ' + error.message;
    showToast(message, 'error');
  }
}

// ====================================
// カルテ日付変更機能
// ====================================
let currentKarteDate = null; // 現在のカルテ日付
let karteInitializationRequestId = 0;

function initKarteDatePicker() {
  const dateDisplay = document.getElementById('karte-date-display');
  const dateInput = document.getElementById('karte-date');

  if (!dateDisplay || !dateInput) return;

  // 初期日付を設定
  setKarteDate(getLocalDateString());

  // 日付変更時の処理
  dateInput.addEventListener('change', async (e) => {
    const newDate = e.target.value;
    const oldDate = currentKarteDate;

    if (newDate === oldDate) return;

    if (!(await confirmDiscardKarteChangesIfNeeded())) {
      dateInput.value = oldDate;
      return;
    }

    // 日付を更新
    setKarteDate(newDate);

    // その日の既存カルテだけを読み込み、なければ白紙にする
    await initNewKarteForDate(newDate, true);
  });
}

// カルテに入力内容があるかチェック
function checkKarteHasContent() {
  const editor = document.getElementById('karte-editor');
  if (!editor) return false;

  // テンプレートの初期状態と比較
  const template = getKarteTemplate();
  const currentContent = editor.innerHTML;

  // 簡易比較（テキストコンテンツで比較）
  const templateText = template.replace(/<[^>]*>/g, '').trim();
  const currentText = currentContent.replace(/<[^>]*>/g, '').trim();

  return currentText !== templateText || Boolean(editor.querySelector('.karte-schema-image'));
}

// カルテ日付の表示を更新
function updateKarteDateDisplay(date) {
  const display = document.getElementById('karte-date-display');
  if (!display) return;

  display.textContent = formatDateJapanese(date);
}

function getCurrentKarteDateValue() {
  const dateInput = document.getElementById('karte-date');
  return normalizeKarteDateValue(currentKarteDate)
    || normalizeKarteDateValue(dateInput?.value)
    || getLocalDateString();
}

function normalizeKarteDateValue(value) {
  if (!value) return null;
  if (value instanceof Date && !Number.isNaN(value.getTime())) {
    return getLocalDateString(value);
  }

  const text = String(value).trim();
  const isoMatch = text.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (isoMatch) {
    return `${isoMatch[1]}-${isoMatch[2]}-${isoMatch[3]}`;
  }

  const parsed = new Date(text);
  if (!Number.isNaN(parsed.getTime())) {
    return getLocalDateString(parsed);
  }

  return null;
}

function getKarteDateFromReception(reception) {
  return normalizeKarteDateValue(
    reception?.reception_date ||
    reception?.reservation_date ||
    reception?.visit_date
  );
}

function setKarteDate(dateValue) {
  const normalizedDate = normalizeKarteDateValue(dateValue) || getLocalDateString();
  const dateInput = document.getElementById('karte-date');
  if (dateInput) {
    dateInput.value = normalizedDate;
  }
  currentKarteDate = normalizedDate;
  updateKarteDateDisplay(parseLocalDate(normalizedDate));
  updateKarteHeaderContext();
  return normalizedDate;
}

function formatKarteNoRecordDateLabel(dateValue) {
  const normalizedDate = normalizeKarteDateValue(dateValue) || getLocalDateString();
  return formatDateJapanese(parseLocalDate(normalizedDate)).replace('(', '（').replace(')', '）');
}

function ensureKarteNoRecordTitle() {
  const contextRow = document.getElementById('karte-context-row');
  if (!contextRow) return null;

  let title = document.getElementById('karte-no-record-title');
  if (!title) {
    title = document.createElement('div');
    title.id = 'karte-no-record-title';
    title.className = 'karte-no-record-title hidden';
    title.textContent = 'カルテ編集';
    contextRow.appendChild(title);
  }
  return title;
}

function setKarteTabActiveState(hasActiveKarte) {
  if (hasActiveKarte) document.getElementById('main-screen')?.classList.remove('patient-overview');
  document.getElementById('karte-insurance-tab')?.classList.toggle('hidden', !hasActiveKarte);
  document.getElementById('btn-karte-tab-close')?.classList.toggle('hidden', !hasActiveKarte);

  const contextRow = document.getElementById('karte-context-row');
  const noRecordTitle = ensureKarteNoRecordTitle();
  contextRow?.classList.toggle('karte-no-record-context', !hasActiveKarte);
  noRecordTitle?.classList.toggle('hidden', hasActiveKarte);
}

function setKarteEditorActiveState(isActive) {
  const editor = document.getElementById('karte-editor');
  if (!editor) return;
  editor.contentEditable = isActive ? 'true' : 'false';
  editor.classList.toggle('karte-empty-state', !isActive);
}

function setKarteNoRecordState(dateValue = getCurrentKarteDateValue(), options = {}) {
  karteInitializationRequestId += 1;
  const patientOverview = options.patientOverview === true;
  document.getElementById('main-screen')?.classList.toggle('patient-overview', patientOverview);
  setKarteClaimType('normal');
  resetSetTreeExpansionState();
  const date = setKarteDate(dateValue);
  // Viewing a patient must not delete a saved draft for the selected date.
  if (currentPatient && !patientOverview && !options.preserveDraft) {
    clearPatientBillingData(currentPatient.id, date);
  }

  currentRecordId = null;
  currentRecordVisitDate = null;
  currentRecordVitalSigns = {};
  setPrescriptionRemarksValue('');
  selectedItems = [];
  selectedActions = [];
  selectedProcedureGroupAnchorId = null;
  selectedPrescriptionGroupAnchorId = null;
  pendingPrescriptions.length = 0;
  procedureEntryOrderCounter = 0;

  setKarteEditorActiveState(false);
  const editor = document.getElementById('karte-editor');
  if (editor) {
    const message = options.message || `${formatKarteNoRecordDateLabel(date)}のカルテはありません。`;
    editor.innerHTML = patientOverview ? '' : `<div class="karte-empty-message">${escapeHtml(message)}</div>`;
  }

  renderSelectedActionsInProcedure();
  renderPendingPrescriptionsInProcedure();
  updateSelectedList();
  updateTotalPoints();
  clearActiveHistorySelection();
  resetKarteValidationWarnings();
  resetKarteDirtyTracking();
  updateKarteHeaderContext('未承認');
  setKarteTabActiveState(false);
  refreshVitalsIfVisible(currentPatient?.id);
}

function activateKarteEditorForEditing() {
  setKarteEditorActiveState(true);
  setKarteTabActiveState(true);
}

function getVisitTimeForCalculation() {
  const candidates = [
    currentReception?.appointment_time,
    currentReception?.reception_time,
    currentReception?.created_at
  ];

  for (const value of candidates) {
    if (!value) continue;
    const text = String(value);
    const match = text.match(/(\d{1,2}):(\d{2})(?::(\d{2}))?/);
    if (match) {
      return `${match[1].padStart(2, '0')}:${match[2]}:${match[3] || '00'}`;
    }

    const parsed = new Date(text);
    if (!Number.isNaN(parsed.getTime())) {
      return [
        String(parsed.getHours()).padStart(2, '0'),
        String(parsed.getMinutes()).padStart(2, '0'),
        String(parsed.getSeconds()).padStart(2, '0')
      ].join(':');
    }
  }

  const now = new Date();
  return [
    String(now.getHours()).padStart(2, '0'),
    String(now.getMinutes()).padStart(2, '0'),
    String(now.getSeconds()).padStart(2, '0')
  ].join(':');
}

function getVisitDatetimeForCalculation(dateStr = getCurrentKarteDateValue()) {
  return `${dateStr}T${getVisitTimeForCalculation()}`;
}

// 日付を日本語形式でフォーマット
function formatDateJapanese(date) {
  const days = ['日', '月', '火', '水', '木', '金', '土'];
  const year = date.getFullYear();
  const month = date.getMonth() + 1;
  const day = date.getDate();
  const dayOfWeek = days[date.getDay()];

  return `${year}/${month}/${day}(${dayOfWeek})`;
}

// 削除済みの受付は、新規受付と区別して未作成状態を維持する。
async function initNewKarteForDate(dateStr, restoreDraftForEmptyDate = false, options = {}) {
  const requestId = ++karteInitializationRequestId;
  if (options.resetSetTreeExpansion !== false) resetSetTreeExpansionState();
  dateStr = setKarteDate(dateStr);
  const targetReceptionId = options.receptionId || getCurrentReceptionRecordId();
  const patientId = currentPatient?.id;
  const isCurrentRequest = () => requestId === karteInitializationRequestId
    && currentPatient?.id === patientId && getCurrentKarteDateValue() === dateStr;

  if (!currentPatient) {
    // 患者未選択時は単にエディタをリセット
    currentRecordId = null;
    currentRecordVisitDate = null;
    resetKarteEditor();
    resetKarteDirtyTracking();
    updateKarteHeaderContext('未承認');
    showToast('新しいカルテを開始しました', 'info');
    return;
  }

  try {
    // 受付から開いた場合は受付IDのカルテだけを検索する。
    const recordsResult = await RecordAPI.list(
      patientId,
      50,
      0,
      targetReceptionId ? { reception_id: targetReceptionId } : { visit_date: dateStr }
    );
    if (!isCurrentRequest()) return;
    const records = Array.isArray(recordsResult) ? recordsResult : (recordsResult.data || []);
    const existingRecord = targetReceptionId
      ? records.find(r => String(r.reception_id || r.receptionId || '') === String(targetReceptionId))
      : records.find(r => normalizeKarteDateValue(r.visit_date) === dateStr);

    if (existingRecord) {
      // 既存カルテがあれば読み込む（算定もカルテから読み込まれる）
      const record = await loadRecordDetail(existingRecord.id, { requestId });
      if (!record || !isCurrentRequest()) return;
      currentRecordId = existingRecord.id;
      currentRecordVisitDate = dateStr;
      updateKarteHeaderContext('承認');
    } else {
      const key = getPatientDraftKey(patientId, dateStr, targetReceptionId);
      const draft = patientBillingData[key];
      let deleted = draft?.deleted === true;
      if (!deleted) {
        const deletedResult = await RecordAPI.listDeleted({
          patient_id: patientId,
          ...(targetReceptionId ? { reception_id: targetReceptionId } : { visit_date: dateStr }),
          limit: 1
        });
        if (!isCurrentRequest()) return;
        const deletedRecords = Array.isArray(deletedResult) ? deletedResult : (deletedResult.data || []);
        deleted = deletedRecords.length > 0;
      }
      const restoredDraft = restoreDraftForEmptyDate && hasPatientDraft(patientId, dateStr, targetReceptionId)
        && (!deleted || (draft.allowAfterDeletion === true && !draft.recordId));
      if (deleted && !restoredDraft) {
        rememberDeletedKarte(patientId, dateStr, targetReceptionId);
        setKarteNoRecordState(dateStr, { preserveDraft: true });
        return;
      }

      currentRecordId = null;
      currentRecordVisitDate = null;
      if (restoredDraft) {
        loadPatientBilling(patientId, dateStr, { receptionId: targetReceptionId });
      } else {
        clearPatientBillingData(patientId, dateStr, { receptionId: targetReceptionId });
        resetKarteEditor();
      }
      clearActiveHistorySelection();
      resetKarteDirtyTracking();
      if (restoredDraft) markKarteDirty();
      updateKarteHeaderContext('未承認');
    }

  } catch (error) {
    if (!isCurrentRequest()) return;
    console.error('カルテ初期化エラー:', error);
    setKarteNoRecordState(dateStr, { preserveDraft: true, message: 'カルテを読み込めませんでした。再読み込みしてください。' });
    showToast('カルテの読み込みに失敗しました', 'error');
  }
}

// カルテエディタの内容のみリセット（算定は保持）
function resetKarteEditorContentOnly() {
  const editor = document.getElementById('karte-editor');
  if (editor) {
    activateKarteEditorForEditing();
    editor.innerHTML = getKarteTemplate();
  }
  resetKarteFormattingState();

  // 合計点数はリセットしない（算定から再計算されるため）
}

// カルテエディタをリセット
function resetKarteEditor() {
  setKarteClaimType('normal');
  const editor = document.getElementById('karte-editor');
  if (editor) {
    activateKarteEditorForEditing();
    editor.innerHTML = getKarteTemplate();
  }
  resetKarteFormattingState();

  currentRecordId = null;
  currentRecordVisitDate = null;
  currentRecordVitalSigns = {};
  setPrescriptionRemarksValue('');

  // 選択済み算定をクリア
  selectedItems = [];
  selectedActions = [];
  selectedProcedureGroupAnchorId = null;
  selectedPrescriptionGroupAnchorId = null;
  updateSelectedList();

  // 処方をクリア
  pendingPrescriptions.length = 0;
  procedureEntryOrderCounter = 0;
  renderPendingPrescriptionsInProcedure();
  const rxList = document.getElementById('current-rx-list');
  if (rxList) {
    rxList.innerHTML = '<p class="no-data">処方なし</p>';
  }
  resetKarteValidationWarnings();

  // 合計点数をリセット
  const totalPoints = document.getElementById('total-points');
  if (totalPoints) {
    totalPoints.textContent = '合計: 0点';
  }
}

function normalizePrescriptionForSave(prescription) {
  syncPrescriptionDerivedFields(prescription);
  const quantity = Number(prescription.dosage_quantity || prescription.quantity || parseFloat(prescription.dosage));
  const days = Number(prescription.days);
  const totalQuantity = Number(prescription.total_quantity);
  const dispensingType = normalizePrescriptionDispensingType(prescription);
  const comments = getPrescriptionComments(prescription);
  const enteredComments = getEnteredProcedureComments(comments);
  const claimCommentCodes = getClaimCommentCodes(enteredComments);
  const claimFreeComment = getClaimFreeCommentText(enteredComments);
  const unitPrice = getPrescriptionUnitPrice(prescription);
  const totalPrice = calculatePrescriptionDrugTotalPrice(prescription);
  const requirements = getPrescriptionRequirementState(prescription);
  const isTemporary = Boolean(prescription.is_temporary || prescription.isTemporary || prescription.temporary);
  const refillAllowed = Boolean(prescription.refill_allowed || prescription.refillAllowed || prescription.is_refill || prescription.isRefill);
  const hasCommentRows = comments.length > 0;
  const genericName = firstNonEmptyString(prescription.generic_name, prescription.genericName);

  return {
    drug_code: prescription.drug_code || prescription.code || null,
    drug_name: prescription.drug_name || prescription.name || '',
    generic_name: genericName || null,
    dosage: prescription.dosage || (quantity ? `${quantity}${prescription.unit || prescription.dosage_unit || ''}` : null),
    unit: prescription.unit || prescription.dosage_unit || null,
    frequency: prescription.frequency || null,
    days: Number.isFinite(days) && days > 0 ? days : null,
    total_quantity: Number.isFinite(totalQuantity) ? totalQuantity : null,
    unit_price: unitPrice > 0 ? unitPrice : null,
    drug_price: unitPrice > 0 ? unitPrice : null,
    total_price: totalPrice > 0 ? totalPrice : null,
    is_generic: Boolean(prescription.is_generic),
    generic_prescription_code: prescription.generic_prescription_code || prescription.genericPrescriptionCode || null,
    generic_prescription_name: prescription.generic_prescription_name || prescription.genericPrescriptionName || null,
    generic_prescription_addition_category: prescription.generic_prescription_addition_category || prescription.genericPrescriptionAdditionCategory || null,
    generic_prescription_lowest_price: prescription.generic_prescription_lowest_price ?? prescription.genericPrescriptionLowestPrice ?? null,
    generic_prescription_master_note: prescription.generic_prescription_master_note || prescription.genericPrescriptionMasterNote || null,
    generic_prescription_master_version: prescription.generic_prescription_master_version || prescription.genericPrescriptionMasterVersion || null,
    generic_class: prescription.generic_class || prescription.genericClass || prescription.generic_type || prescription.genericType || null,
    drug_type: inferPrescriptionDrugType(prescription),
    instructions: prescription.instructions || prescription.note || null,
    dispensing_type: dispensingType,
    prescription_type: dispensingType,
    is_temporary: isTemporary,
    temporary: isTemporary,
    refill_allowed: refillAllowed,
    is_refill: refillAllowed,
    refill_count: Number(prescription.refill_count || prescription.refillCount || 0) || null,
    requires_comment: requirements.requiresComment,
    comment_required: requirements.requiresComment,
    selectable_comment_required: requirements.requiresComment,
    long_term_listed: requirements.longTermListed,
    long_term_patient_choice: requirements.longTermPatientChoice,
    generic_change_allowed: requirements.genericChangeAllowed,
    generic_change_reason: requirements.genericChangeReason || null,
    prescription_group_id: prescription.prescription_group_id || '',
    prescription_group_parent_id: prescription.prescription_group_parent_id || '',
    prescription_group_label: prescription.prescription_group_label || '',
    comment_codes: hasCommentRows ? claimCommentCodes : (prescription.comment_codes || []),
    comments: enteredComments,
    free_comment: (hasCommentRows ? claimFreeComment : prescription.free_comment) || null,
    receipt_position: hasCommentRows
      ? getClaimReceiptPosition(enteredComments, prescription.receipt_position)
      : normalizeReceiptPosition(prescription.receipt_position || 'summary'),
    procedure_order: readProcedureEntryOrder(prescription),
    sort_order: readProcedureEntryOrder(prescription)
  };
}

function buildBillingItemsForSave() {
  const orderItems = buildBillingItemsFromCurrentOrders();
  const items = orderItems.length ? orderItems : selectedItems.map(item => ({
    code: item.code,
    name: item.name,
    points: Number(item.points || 0),
    quantity: Number(item.quantity || 1),
    category: item.category || '診察',
    comments: item.comments || [],
    comment_codes: item.comment_codes || [],
    free_comment: item.free_comment || '',
    receipt_position: item.receipt_position || 'summary',
    do_not_bill: Boolean(item.do_not_bill),
    billing_group_id: item.billing_group_id || item.billingGroupId || '',
    billing_group_parent_id: item.billing_group_parent_id || item.billingGroupParentId || '',
    billing_group_label: item.billing_group_label || item.billingGroupLabel || '',
    drug_quantity: item.drug_quantity ?? null,
    drug_unit: item.drug_unit || null,
    procedure_order: readProcedureEntryOrder(item),
    sort_order: readProcedureEntryOrder(item),
    source: item.source || ''
  }));

  return items
    .filter(item => item.name)
    .map(sourceItem => {
      const item = enrichStandardBillingAction(sourceItem);
      const isSelfPay = Boolean(item.isSelfPay || item.item_type === 'self_pay' || item.category === '自費');
      const isDrug = item.item_type === 'drug';
      const unitAmount = Number(item.unit_price || item.price || item.amount || 0);
      const comments = normalizeActionComments(item.comments || []);
      const enteredComments = getEnteredProcedureComments(comments);
      const claimCommentCodes = getClaimCommentCodes(enteredComments);
      const claimFreeComment = getClaimFreeCommentText(enteredComments);
      const hasCommentRows = comments.length > 0;
      return {
        billing_code: item.code || (isSelfPay ? 'SELF' : 'A000'),
        billing_name: item.name,
        points: Number(item.points || 0),
        quantity: Number(item.quantity || 1),
        category: item.category || (isSelfPay ? '自費' : '診察'),
        amount: unitAmount,
        unit_price: unitAmount,
        item_type: item.item_type || (isSelfPay ? 'self_pay' : ''),
        is_self_pay: isSelfPay,
        drug_quantity: isDrug ? (item.drug_quantity ?? item.quantity ?? null) : null,
        drug_unit: isDrug ? (item.drug_unit || '') : null,
        comment_codes: hasCommentRows ? claimCommentCodes : (item.comment_codes || []),
        comments: enteredComments,
        free_comment: (hasCommentRows ? claimFreeComment : item.free_comment) || null,
        receipt_position: hasCommentRows
          ? getClaimReceiptPosition(enteredComments, item.receipt_position)
          : normalizeReceiptPosition(item.receipt_position || 'summary'),
        do_not_bill: Boolean(item.do_not_bill),
        billing_group_id: item.billing_group_id || item.billingGroupId || '',
        billing_group_parent_id: item.billing_group_parent_id || item.billingGroupParentId || '',
        billing_group_label: item.billing_group_label || item.billingGroupLabel || '',
        procedure_order: readProcedureEntryOrder(item),
        sort_order: readProcedureEntryOrder(item),
        source: item.source || ''
      };
    });
}

function buildCurrentKarteSavePayload() {
  const editor = document.getElementById('karte-editor');
  const content = editor ? editor.innerHTML : getKarteTemplate();
  const date = setKarteDate(getCurrentKarteDateValue());
  const recordIdForSave = currentRecordId && currentRecordVisitDate === date
    ? currentRecordId
    : null;
  const soapData = parseKarteContent(content);
  const context = getKarteContextPayloadFromState();

  return {
    ...context,
    record_id: recordIdForSave,
    ...(karteClaimTypeState.dirty ? { receipt_claim_type: karteClaimTypeState.value } : {}),
    patient_id: currentPatient.id,
    reception_id: context.reception_id,
    visit_date: date,
    visit_type: '外来',
    department: context.department || document.getElementById('karte-department')?.value || '内科',
    subjective: soapData.subjective,
    objective: soapData.objective,
    assessment: soapData.assessment,
    plan: soapData.plan,
    vital_signs: buildKarteVitalSignsPayload(),
    prescriptions: pendingPrescriptions
      .map(normalizePrescriptionForSave)
      .filter(item => item.drug_name),
    billings: buildBillingItemsForSave()
  };
}

function getPlainTextFromHtml(html) {
  const div = document.createElement('div');
  div.innerHTML = html || '';
  return (div.textContent || div.innerText || '').replace(/\u00a0/g, ' ').trim();
}

function normalizeDiagnosisForKarteSet(diagnosis) {
  const normalized = normalizeDiagnosisItem(diagnosis);
  const diagnosisName = normalized.diagnosis_name || normalized.full_name || '';
  return {
    diagnosis_code: normalized.diagnosis_code || null,
    diagnosis_name: diagnosisName,
    full_name: normalized.full_name || buildDiagnosisFullName(diagnosisName, normalized.prefix_modifiers, normalized.suffix_modifiers),
    department: normalized.department || getCurrentDiagnosisDepartment(),
    visit_type: normalized.visit_type || 'outpatient',
    insurance_scope: normalized.insurance_scope || 'social-national',
    insurance_none: normalized.insurance_none === true,
    icd10_code: normalized.icd10_code || null,
    prefix_modifiers: normalizeDiagnosisModifierList(normalized.prefix_modifiers),
    suffix_modifiers: normalizeDiagnosisModifierList(normalized.suffix_modifiers),
    diagnosis_category: normalized.diagnosis_category || 'sub',
    is_suspected: normalized.is_suspected === true,
    is_acute: normalized.is_acute === true || diagnosisName.includes('急性'),
    start_date: normalizeKarteDateValue(normalized.start_date) || getCurrentKarteDateValue() || getLocalDateString(),
    end_date: normalizeKarteDateValue(normalized.end_date) || null,
    outcome: normalized.outcome || 'continuing',
    receipt_comment: normalized.receipt_comment || null
  };
}

function getKarteSetRegisterDiagnosisSource() {
  return karteSetRegisterDiagnoses;
}

function getKarteSetRegisterSelectedDiagnoses() {
  return karteSetRegisterDiagnoses.map(normalizeDiagnosisForKarteSet);
}

function buildCurrentKarteSetPayload(setName, options = {}) {
  const editor = document.getElementById('karte-editor');
  const content = editor ? editor.innerHTML : getKarteTemplate();
  const soapData = parseKarteContent(content);
  const diagnoses = Array.isArray(options.diagnoses)
    ? options.diagnoses
    : getKarteSetRegisterSelectedDiagnoses();

  return {
    set_name: setName,
    department: document.getElementById('karte-department')?.value || currentReception?.department || '内科',
    karte_html: content,
    subjective: soapData.subjective,
    objective: soapData.objective,
    assessment: soapData.assessment,
    plan: soapData.plan,
    diagnoses,
    prescriptions: pendingPrescriptions
      .map(normalizePrescriptionForSave)
      .filter(item => item.drug_name),
    billings: buildBillingItemsForSave()
  };
}

function hasMeaningfulKarteSetPayload(payload) {
  const text = getPlainTextFromHtml(payload.karte_html);
  const templateText = getPlainTextFromHtml(getKarteTemplate());
  return (
    (text && text !== templateText) ||
    (payload.diagnoses || []).length > 0 ||
    (payload.billings || []).length > 0 ||
    (payload.prescriptions || []).length > 0
  );
}

function getDefaultKarteSetName() {
  const date = getCurrentKarteDateValue().replace(/-/g, '/');
  const firstBilling = buildBillingItemsForSave()[0]?.billing_name;
  const firstPrescription = pendingPrescriptions[0]?.drug_name;
  return `${date} ${firstBilling || firstPrescription || 'カルテセット'}`;
}

