function saveKarteSetFolderFromModal() {
  const modal = ensureKarteSetFolderModal();
  const nameInput = modal.querySelector('#karte-set-folder-name');
  const parentSelect = modal.querySelector('#karte-set-folder-parent');
  const rawName = nameInput?.value.trim() || '';
  if (!rawName) {
    showToast('フォルダ名を入力してください', 'error');
    nameInput?.focus();
    return;
  }

  const cleanName = normalizeOrderSetFolderSegment(rawName);
  const parent = parentSelect?.value || '';
  const folderPath = parent ? `${parent}/${cleanName}` : cleanName;

  orderSetViewState.folders = Array.from(new Set([...(orderSetViewState.folders || []), folderPath]));
  saveOrderSetViewState();
  renderKarteSetRegisterFolders();
  renderKarteSetEditFolders();

  const targetSelect = document.getElementById(karteSetFolderModalTargetSelectId);
  if (targetSelect) targetSelect.value = folderPath;

  closeKarteSetFolderModal();
}

function openKarteSetRegisterModal() {
  if (!currentPatient) {
    showToast('患者を選択してください', 'error');
    return;
  }

  const modal = ensureKarteSetRegisterModal();
  karteSetRegisterDiagnoses = [];
  const input = modal.querySelector('#karte-set-register-name');
  if (input) {
    input.value = getDefaultKarteSetName();
  }
  renderKarteSetRegisterFolders();
  renderKarteSetRegisterDiagnoses();
  modal.classList.remove('hidden');
  input?.focus();
  input?.select();
}

function closeKarteSetRegisterModal() {
  document.getElementById('karte-set-register-modal')?.classList.add('hidden');
}

