async function openKarteSetDiagnosisAddModal() {
  const modal = ensureKarteSetDiagnosisAddModal();
  const input = modal.querySelector('#karte-set-diagnosis-keyword');
  if (input) input.value = '';
  modal.classList.remove('hidden');
  input?.focus();
  await searchAndRenderKarteSetDiagnosisMaster('');
}

function closeKarteSetDiagnosisAddModal() {
  document.getElementById('karte-set-diagnosis-add-modal')?.classList.add('hidden');
}

async function searchAndRenderKarteSetDiagnosisMaster(query) {
  const resultsEl = document.getElementById('karte-set-diagnosis-results');
  if (!resultsEl) return;
  resultsEl.innerHTML = '<div class="diagnosis-loading">検索中...</div>';

  let items = [];
  const trimmed = String(query || '').trim();
  await ensureFacilityMasterLoaded('diagnoses');
  const api = typeof DiagnosisAPI !== 'undefined' ? DiagnosisAPI : null;
  if (trimmed && api?.searchMaster) {
    try {
      const apiItems = await api.searchMaster(trimmed, 60);
      items = (Array.isArray(apiItems) ? apiItems : (apiItems.items || apiItems.data || [])).map(normalizeDiagnosisMasterItem);
    } catch (error) {
      console.warn('セット用傷病名マスターAPI検索エラー、ローカル検索します:', error);
    }
  }

  if (!items.length) {
    items = mergeDiagnosisMasterItems(
      searchLocalDiagnosisMaster(trimmed, 60),
      searchOfficialDiagnosisMaster(trimmed, 60),
      60
    );
  } else {
    items = mergeDiagnosisMasterItems(searchLocalDiagnosisMaster(trimmed, 60), items, 60);
  }

  karteSetDiagnosisSearchResults = items;
  renderKarteSetDiagnosisResults(items, trimmed);
}

function renderKarteSetDiagnosisResults(items, query) {
  const resultsEl = document.getElementById('karte-set-diagnosis-results');
  if (!resultsEl) return;

  if (!items.length) {
    resultsEl.innerHTML = `<div class="diagnosis-empty">${escapeHtml(query ? '該当する傷病名がありません' : '傷病名を検索してください')}</div>`;
    return;
  }

  resultsEl.innerHTML = items.map((item, index) => `
    <div class="karte-set-diagnosis-result-row">
      <span>${escapeHtml(item.name)}</span>
      <div class="karte-set-diagnosis-result-actions">
        <button type="button" onclick="selectKarteSetDiagnosisCandidate(${index}, 'sub')">確定</button>
        <button type="button" onclick="selectKarteSetDiagnosisCandidate(${index}, 'main')">主病</button>
        <button type="button" onclick="selectKarteSetDiagnosisCandidate(${index}, 'suspected')">疑い</button>
      </div>
    </div>
  `).join('');
}

function selectKarteSetDiagnosisCandidate(index, mode = 'sub') {
  const item = karteSetDiagnosisSearchResults[index];
  if (!item) return;

  const diagnosis = normalizeDiagnosisForKarteSet({
    diagnosis_code: item.disease_code || null,
    diagnosis_name: item.name,
    department: getCurrentDiagnosisDepartment(),
    icd10_code: item.icd10_code || null,
    diagnosis_category: mode === 'main' ? 'main' : 'sub',
    is_suspected: mode === 'suspected',
    is_acute: item.name.includes('急性'),
    start_date: getCurrentKarteDateValue() || getLocalDateString(),
    outcome: 'continuing'
  });

  const newKey = getDiagnosisSetDuplicateKey(diagnosis);
  if (karteSetRegisterDiagnoses.some(existing => getDiagnosisSetDuplicateKey(existing) === newKey)) {
    showToast('同じ傷病名はすでにセットに入っています', 'info');
    return;
  }

  karteSetRegisterDiagnoses.push(diagnosis);
  renderKarteSetRegisterDiagnoses();
  showToast(`${item.name}${mode === 'suspected' ? ' 疑い' : ''}をセットに追加しました`, 'success');
}

function removeKarteSetRegisterDiagnosis(index) {
  if (!Number.isInteger(index) || index < 0 || index >= karteSetRegisterDiagnoses.length) return;
  karteSetRegisterDiagnoses.splice(index, 1);
  renderKarteSetRegisterDiagnoses();
}

function editKarteSetRegisterDiagnosis(index) {
  const diagnosis = karteSetRegisterDiagnoses[index];
  if (!diagnosis) return;

  const currentName = diagnosis.diagnosis_name || diagnosis.full_name || '';
  const nextName = prompt('傷病名を入力してください', currentName)?.trim();
  if (!nextName) return;

  const currentMode = diagnosis.is_suspected ? '疑い' : diagnosis.diagnosis_category === 'main' ? '主病' : '確定';
  const nextModeInput = prompt('区分を入力してください（確定 / 主病 / 疑い）', currentMode);
  if (nextModeInput === null) return;
  const nextMode = nextModeInput.trim();

  karteSetRegisterDiagnoses[index] = normalizeDiagnosisForKarteSet({
    ...diagnosis,
    diagnosis_name: nextName,
    full_name: buildDiagnosisFullName(nextName, diagnosis.prefix_modifiers, diagnosis.suffix_modifiers),
    diagnosis_category: nextMode === '主病' ? 'main' : 'sub',
    is_suspected: nextMode === '疑い'
  });
  renderKarteSetRegisterDiagnoses();
}

function getCreatedKarteSetId(response, setName, folder) {
  const directId = response?.id || response?.data?.id || response?.item?.id || response?.set?.id || response?.karte_set?.id;
  if (directId) return directId;
  const folderText = folder ? `フォルダ: ${folder}` : '';
  const matched = karteSets.find(set => (
    set?.set_name === setName &&
    (!folder || getOrderSetFolder('karte', set) === folder || set?.description === folderText || String(set?.description || '').includes(folder))
  ));
  return matched?.id || null;
}

async function saveCurrentKarteSetFromModal() {
  const nameInput = document.getElementById('karte-set-register-name');
  const folderSelect = document.getElementById('karte-set-register-folder');
  const trimmedName = nameInput?.value.trim();
  if (!trimmedName) {
    showToast('セット名を入力してください', 'error');
    nameInput?.focus();
    return;
  }

  const selectedDiagnoses = getKarteSetRegisterSelectedDiagnoses();
  const payload = buildCurrentKarteSetPayload(trimmedName, { diagnoses: selectedDiagnoses });
  const folder = folderSelect?.value || '';
  payload.folder = folder || null;
  if (!hasMeaningfulKarteSetPayload(payload)) {
    showToast('セット登録できるカルテ内容・算定・処方がありません', 'info');
    return;
  }

  try {
    showLoading();
    const createdSet = await KarteSetAPI.create(payload);
    await loadActionSets();
    const createdSetId = getCreatedKarteSetId(createdSet, trimmedName, folder);
    if (folder && createdSetId) {
      orderSetViewState.setFolders = orderSetViewState.setFolders || {};
      orderSetViewState.setFolders[`karte:${createdSetId}`] = folder;
      saveOrderSetViewState();
    }
    hideLoading();
    closeKarteSetRegisterModal();

    const setTab = Array.from(document.querySelectorAll('.m3-header-zone-order .m3-panel-tab'))
      .find(tab => tab.textContent.trim() === 'セット');
    if (setTab && !setTab.classList.contains('active')) {
      setTab.click();
    } else {
      currentOrderCategory = 'set';
      renderSetTree();
    }

    showToast('カルテ・算定・処方をセット登録しました', 'success');
  } catch (error) {
    hideLoading();
    console.error('カルテセット登録エラー:', error);
    showToast('セット登録に失敗しました: ' + error.message, 'error');
  }
}

function registerCurrentKarteSet() {
  openKarteSetRegisterModal();
}

function hasMixedPrescriptionDispensingTypes(prescriptions = []) {
  const dispensingTypes = prescriptions
    .filter(prescription => prescription && (prescription.drug_name || prescription.name))
    .map(prescription => normalizePrescriptionDispensingType(prescription));
  return dispensingTypes.includes('院内') && dispensingTypes.includes('院外');
}

function isDispensingMixWarning(warning) {
  return warning?.type === 'dispensing_mix'
    || warning?.category === 'dispensing_mix'
    || warning?.warning_type === 'dispensing_mix'
    || warning?.category === '院内処方・院外処方の併用チェック';
}

function buildDispensingMixWarnings(prescriptions = []) {
  if (prescriptions === pendingPrescriptions) {
    syncAllPrescriptionGroupSharedFields();
  }

  const drugs = prescriptions
    .filter(prescription => prescription && (prescription.drug_name || prescription.name))
    .map(prescription => ({
      name: prescription.drug_name || prescription.name,
      dispensingType: normalizePrescriptionDispensingType(prescription)
    }));

  if (!hasMixedPrescriptionDispensingTypes(prescriptions)) return [];

  return drugs.map(drug => ({
    type: 'dispensing_mix',
    itemName: drug.name,
    category: '院内処方・院外処方の併用チェック',
    message: '同一カルテ内に院内処方・院外処方の両方が含まれています。',
    level: 'warning'
  }));
}

function buildCalculationWarningRowsForSave() {
  if (!Array.isArray(calculationWarnings)) return [];
  const categoryLabels = {
    exclusive: '同時算定チェック',
    combine: '併算定チェック',
    limit: '回数制限チェック',
    age: '年齢制限チェック',
    diagnosis: '傷病名チェック',
    comment: '選択式コメント確認'
  };

  return calculationWarnings
    .filter(warning => warning && warning.passed !== true && warning.message)
    .map(warning => ({
      itemName: warning.item_name || warning.target_name || warning.action_name || warning.rule_name || '処置行為',
      category: categoryLabels[warning.category] || warning.warning_type || warning.prohibition_name || warning.rule_name || '算定チェック',
      message: warning.message,
      level: warning.level === 'error' ? 'error' : 'warning'
    }));
}

function buildDrugWarningRowsForSave() {
  if (!Array.isArray(drugWarnings)) return [];

  return pendingPrescriptions.flatMap(prescription => getDrugWarningsForPrescription(prescription));
}

function buildInitialDiagnosisRemainsWarningRowsForSave() {
  return selectedActions.flatMap(action => buildInitialDiagnosisRemainsWarnings(action));
}

function buildCommentAppendWarningRowsForSave() {
  return [
    ...selectedActions.flatMap(action => getCommentAppendWarningsForEntry(action, 'action')),
    ...pendingPrescriptions.flatMap(prescription => getCommentAppendWarningsForEntry(prescription, 'prescription'))
  ];
}

function isKarteSavePrescriptionAuditCheckEnabled() {
  return isFacilityOtherSettingEnabled('chartPrescriptionAuditCheck');
}

function isKarteSaveCalculationCheckEnabled() {
  return isFacilityOtherSettingEnabled('chartCalculationCheck');
}

function isAnyKarteSaveWarningCheckEnabled() {
  return isKarteSavePrescriptionAuditCheckEnabled() || isKarteSaveCalculationCheckEnabled();
}

function buildKarteSaveWarnings() {
  const warnings = [];
  if (isKarteSavePrescriptionAuditCheckEnabled()) {
    warnings.push(
      ...buildDispensingMixWarnings(pendingPrescriptions),
      ...buildDrugWarningRowsForSave()
    );
  }
  if (isKarteSaveCalculationCheckEnabled()) {
    warnings.push(
      ...buildCommentAppendWarningRowsForSave(),
      ...buildCalculationWarningRowsForSave(),
      ...buildInitialDiagnosisRemainsWarningRowsForSave()
    );
  }
  return dedupeKarteWarningRows([
    ...warnings
  ]);
}

async function saveAndConfirmCurrentKarte(triggerButton = null) {
  if (karteClaimTypeState.saving) {
    showToast('請求区分を保存中です。完了してから保存してください', 'info');
    return;
  }
  if (!currentPatient) {
    showToast('患者を選択してください', 'error');
    return;
  }
  if (document.getElementById('karte-editor')?.classList.contains('karte-empty-state')) {
    showToast('保存するカルテがありません', 'info');
    return;
  }

  const date = getCurrentKarteDateValue();
  if (isAnyKarteSaveWarningCheckEnabled()) {
    await ensureFacilityWarningsLoadedForKarte();
    const warningLoadBlockMessage = getFacilityWarningsLoadBlockMessage();
    if (warningLoadBlockMessage) {
      showToast(warningLoadBlockMessage, 'error');
      return;
    }
    lastCheckTimestamp = 0;
    lastDrugCheckTimestamp = 0;
    if (isKarteSaveCalculationCheckEnabled()) await checkActionsRealtime();
    if (isKarteSavePrescriptionAuditCheckEnabled()) await checkPrescriptionsRealtime();
    const saveWarnings = buildKarteSaveWarnings();
    if (saveWarnings.length > 0) {
      const shouldContinue = await showKarteWarningListDialog(saveWarnings);
      if (!shouldContinue) return;
    }
  }

  const originalContent = triggerButton?.innerHTML;
  const originalText = triggerButton?.textContent;

  try {
    if (triggerButton) {
      triggerButton.disabled = true;
      triggerButton.textContent = '保存中...';
    }
    showLoading();

    await ensureCurrentReceptionForRecordSave();
    const payload = buildCurrentKarteSavePayload();
    const result = await RecordAPI.save(payload);
    currentRecordId = result.id;
    currentRecordVisitDate = date;
    const persistedBillingId = result.billing_id || result.billingId;
    if (persistedBillingId) {
      currentBilling = {
        ...(currentBilling || {}),
        id: persistedBillingId,
        billingId: persistedBillingId
      };
    }
    karteClaimTypeState.dirty = false;

    clearPatientBillingData(currentPatient.id, date);
    resetKarteDirtyTracking();
    updateKarteHeaderContext('承認');
    hideLoading();
    showToast('カルテを保存して確定しました', 'success');

    if (currentPatient.patient_no) {
      await renderPatientHistoryFromAPI(currentPatient.id);
    } else {
      renderPatientHistory(currentPatient.id);
    }
    setActiveHistoryRecord(currentRecordId);
    refreshVitalsIfVisible(currentPatient.id);
  } catch (error) {
    hideLoading();
    saveCurrentPatientBilling();
    showToast('保存に失敗しました: ' + error.message, 'error');
  } finally {
    if (triggerButton) {
      triggerButton.disabled = false;
      if (originalContent?.includes('<')) {
        triggerButton.innerHTML = originalContent;
      } else {
        triggerButton.textContent = originalText || '保存';
      }
    }
  }
}

function handleKarteSaveShortcut(event) {
  const isSaveShortcut = (event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 's';
  if (!isSaveShortcut) return;

  const mainScreen = document.getElementById('main-screen');
  if (mainScreen?.classList.contains('hidden')) return;

  event.preventDefault();
  saveAndConfirmCurrentKarte();
}

// ====================================
// カルテ機能
// ====================================
const KARTE_DEFAULT_FONT_SIZE = 14;
const KARTE_MIN_FONT_SIZE = 10;
const KARTE_MAX_FONT_SIZE = 24;
const KARTE_FONT_SIZE_STEP = 1;
let currentKarteFontSize = KARTE_DEFAULT_FONT_SIZE;
let savedKarteSelectionRange = null;

function getKarteEditorElement() {
  return document.getElementById('karte-editor');
}

function isNodeInsideKarteEditor(node) {
  const editor = getKarteEditorElement();
  return Boolean(editor && node && (node === editor || editor.contains(node)));
}

function saveKarteSelection() {
  const selection = window.getSelection();
  if (!selection || selection.rangeCount === 0) return;
  const range = selection.getRangeAt(0);
  if (!isNodeInsideKarteEditor(range.commonAncestorContainer)) return;
  savedKarteSelectionRange = range.cloneRange();
}

function restoreKarteSelection() {
  const editor = getKarteEditorElement();
  if (!editor) return false;

  const selection = window.getSelection();
  if (!selection) return false;

  editor.focus();
  selection.removeAllRanges();

  if (savedKarteSelectionRange && isNodeInsideKarteEditor(savedKarteSelectionRange.commonAncestorContainer)) {
    selection.addRange(savedKarteSelectionRange);
    return true;
  }

  const range = document.createRange();
  range.selectNodeContents(editor);
  range.collapse(false);
  selection.addRange(range);
  savedKarteSelectionRange = range.cloneRange();
  return true;
}

function clampKarteFontSize(size) {
  const numericSize = Number(size);
  if (!Number.isFinite(numericSize)) return KARTE_DEFAULT_FONT_SIZE;
  return Math.min(KARTE_MAX_FONT_SIZE, Math.max(KARTE_MIN_FONT_SIZE, numericSize));
}

function updateKarteFontSizeDisplay(size = currentKarteFontSize) {
  const display = document.getElementById('karte-font-size-display');
  if (display) display.textContent = String(clampKarteFontSize(size));
}

function resetKarteFormattingState() {
  currentKarteFontSize = KARTE_DEFAULT_FONT_SIZE;
  savedKarteSelectionRange = null;
  updateKarteFontSizeDisplay();
}

function replaceExecCommandFontSize(editor, size) {
  editor.querySelectorAll('font[size="7"]').forEach(el => {
    el.removeAttribute('size');
    el.style.fontSize = `${size}px`;
  });
}

function commitKarteFormattingChange() {
  saveKarteSelection();
  markKarteDirty();
  saveCurrentPatientBilling();
}

function applyKarteTextColor(color) {
  const editor = getKarteEditorElement();
  if (!editor || !restoreKarteSelection()) return;
  document.execCommand('styleWithCSS', false, true);
  document.execCommand('foreColor', false, color);
  commitKarteFormattingChange();
}

function applyKarteFontSize(size) {
  const editor = getKarteEditorElement();
  if (!editor || !restoreKarteSelection()) return;
  const nextSize = clampKarteFontSize(size);
  currentKarteFontSize = nextSize;
  updateKarteFontSizeDisplay(nextSize);
  document.execCommand('fontSize', false, '7');
  replaceExecCommandFontSize(editor, nextSize);
  commitKarteFormattingChange();
}

function getSelectionFontSize() {
  const selection = window.getSelection();
  if (!selection || selection.rangeCount === 0) return currentKarteFontSize;
  let node = selection.anchorNode;
  if (!isNodeInsideKarteEditor(node)) return currentKarteFontSize;
  if (node.nodeType === Node.TEXT_NODE) node = node.parentElement;
  const computedSize = node ? parseInt(window.getComputedStyle(node).fontSize, 10) : currentKarteFontSize;
  return clampKarteFontSize(computedSize);
}

function initKarteFormattingToolbar() {
  const editor = getKarteEditorElement();
  if (!editor) return;

  currentKarteFontSize = KARTE_DEFAULT_FONT_SIZE;
  updateKarteFontSizeDisplay();

  editor.addEventListener('mouseup', () => {
    saveKarteSelection();
    currentKarteFontSize = getSelectionFontSize();
    updateKarteFontSizeDisplay();
  });
  editor.addEventListener('keyup', () => {
    saveKarteSelection();
    currentKarteFontSize = getSelectionFontSize();
    updateKarteFontSizeDisplay();
  });
  editor.addEventListener('focus', saveKarteSelection);

  document.querySelectorAll('[data-karte-color]').forEach(btn => {
    btn.addEventListener('mousedown', event => event.preventDefault());
    btn.addEventListener('click', () => {
      applyKarteTextColor(btn.dataset.karteColor || '#000000');
    });
  });

  document.getElementById('btn-karte-font-smaller')?.addEventListener('mousedown', event => event.preventDefault());
  document.getElementById('btn-karte-font-smaller')?.addEventListener('click', () => {
    applyKarteFontSize(currentKarteFontSize - KARTE_FONT_SIZE_STEP);
  });

  document.getElementById('btn-karte-font-larger')?.addEventListener('mousedown', event => event.preventDefault());
  document.getElementById('btn-karte-font-larger')?.addEventListener('click', () => {
    applyKarteFontSize(currentKarteFontSize + KARTE_FONT_SIZE_STEP);
  });
}

function initKarte() {
  const confirmBtn = document.getElementById('btn-confirm');
  const tempSaveBtn = document.getElementById('btn-temp-save');

  // 日付表示クリックで日付変更
  initKarteDatePicker();

  const editor = document.getElementById('karte-editor');
  editor?.addEventListener('input', () => saveCurrentPatientBilling());
  document.getElementById('karte-department')?.addEventListener('change', () => saveCurrentPatientBilling());
  document.addEventListener('keydown', handleKarteSaveShortcut);
  initKarteHeaderActions();
  initKarteFormattingToolbar();

  if (confirmBtn) {
    confirmBtn.addEventListener('click', () => saveAndConfirmCurrentKarte(confirmBtn));
  }

  if (tempSaveBtn) {
    tempSaveBtn.addEventListener('click', () => saveAndConfirmCurrentKarte(tempSaveBtn));
  }

}

const KARTE_CLAIM_TYPES = new Set(['normal', 'resubmit', 'resubmit_paper', 'month_delay']);
let karteClaimTypeState = { value: 'normal', dirty: false, saving: false };

function setKarteClaimType(value, dirty = false) {
  const normalized = KARTE_CLAIM_TYPES.has(value) ? value : 'normal';
  karteClaimTypeState = { value: normalized, dirty, saving: false };
  const select = document.getElementById('karte-claim-type');
  if (select) {
    select.value = normalized;
    select.disabled = false;
  }
}

async function handleKarteClaimTypeChange(event) {
  const select = event.target;
  const next = select.value;
  const state = karteClaimTypeState;
  if (!currentPatient || !KARTE_CLAIM_TYPES.has(next) || state.saving) {
    select.value = state.value;
    return;
  }
  if (next === state.value) return;
  const recordId = currentRecordVisitDate === getCurrentKarteDateValue() ? currentRecordId : null;
  if (!isUuidLike(recordId)) {
    setKarteClaimType(next, true);
    saveCurrentPatientBilling();
    return;
  }

  const patientId = currentPatient.id;
  const date = getCurrentKarteDateValue();
  const draftKey = getCurrentBillingKey();
  const isSameContext = () => karteClaimTypeState === state
    && currentPatient?.id === patientId && currentRecordId === recordId
    && getCurrentKarteDateValue() === date;
  state.saving = true;
  select.disabled = true;
  try {
    await ReceiptClaimAPI.updateRecordClaimType(recordId, next);
    // Update only an existing draft; do not create an unsaved clinical edit.
    if (patientBillingData[draftKey]?.recordId === recordId) {
      patientBillingData[draftKey].receiptClaimType = next;
      patientBillingData[draftKey].receiptClaimTypeDirty = false;
      persistPatientBillingDraftData();
    }
    receiptClaimState.preview = null;
    if (isSameContext()) {
      state.value = next;
      state.dirty = false;
      showToast('請求区分を保存しました', 'success');
    }
  } catch (error) {
    if (isSameContext()) {
      select.value = state.value;
      showToast('請求区分を保存できませんでした: ' + error.message, 'error');
    }
  } finally {
    if (isSameContext()) {
      state.saving = false;
      select.disabled = false;
    }
  }
}

function initKarteHeaderActions() {
  document.getElementById('btn-karte-refresh')?.addEventListener('click', async () => {
    if (!currentPatient) {
      showToast('患者を選択してください', 'error');
      return;
    }
    if (!(await confirmDiscardKarteChangesIfNeeded())) return;
    await initNewKarteForDate(getCurrentKarteDateValue(), true);
    if (currentPatient?.id) {
      await loadPatientInsurances(currentPatient.id);
    }
  });

  document.getElementById('btn-regular-register')?.addEventListener('click', openPeriodicRegisterModal);
  document.getElementById('btn-set-register')?.addEventListener('click', registerCurrentKarteSet);
  document.getElementById('btn-karte-list')?.addEventListener('click', showKarteHistoryTab);
  document.getElementById('btn-open-record-update-history')?.addEventListener('click', openRecordUpdateHistoryModal);
  document.getElementById('btn-open-deleted-records')?.addEventListener('click', openDeletedRecordRestoreModal);
  document.getElementById('btn-karte-context-edit')?.addEventListener('click', openKarteContextModal);
  document.getElementById('btn-add-schema')?.addEventListener('mousedown', event => event.preventDefault());
  document.getElementById('btn-add-schema')?.addEventListener('click', openKarteSchemaPickerModal);
  document.getElementById('karte-claim-type')?.addEventListener('change', handleKarteClaimTypeChange);
  document.getElementById('btn-karte-tab-add')?.addEventListener('click', openKarteAddModal);
  document.getElementById('btn-karte-tab-close')?.addEventListener('click', deleteCurrentKarteFromTab);
  document.getElementById('btn-clear-soap')?.addEventListener('click', async () => {
    const confirmed = await showAppConfirm({
      title: '主訴・所見の削除',
      message: '主訴・所見を削除しますか？',
      confirmText: '削除',
      cancelText: 'キャンセル'
    });
    if (!confirmed) return;
    resetKarteEditorContentOnly();
    markKarteDirty();
    saveCurrentPatientBilling();
    showToast('主訴・所見を削除しました', 'info');
  });
  document.getElementById('btn-clear-procedure')?.addEventListener('click', () => {
    if (!selectedActions.length && !pendingPrescriptions.length) {
      showToast('削除する処置・行為・薬がありません', 'info');
      return;
    }
    deleteAllProcedureItems();
  });
}

async function deleteCurrentKarteFromTab() {
  if (!currentPatient) {
    showToast('患者を選択してください', 'error');
    return;
  }

  const ok = await showKarteDeleteDialog();
  if (!ok) return;

  const date = getCurrentKarteDateValue();
  const patient = currentPatient;
  const receptionId = getCurrentReceptionRecordId();
  const recordId = currentRecordId;
  const requestId = ++karteInitializationRequestId;

  try {
    showLoading();
    if (recordId) {
      await RecordAPI.delete(recordId);
    }
    rememberDeletedKarte(patient.id, date, receptionId);
    if (requestId !== karteInitializationRequestId || currentPatient?.id !== patient.id
        || getCurrentKarteDateValue() !== date) return;
    setKarteNoRecordState(date, { preserveDraft: true });
    if (currentPatient.patient_no) {
      await renderPatientHistoryFromAPI(currentPatient.id);
    } else {
      renderPatientHistory(currentPatient.id);
    }
  } catch (error) {
    console.error('カルテ削除エラー:', error);
    showToast('カルテの削除に失敗しました: ' + error.message, 'error');
  } finally {
    hideLoading();
  }
}

function isUuidLike(value) {
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(String(value || ''));
}

function getRecordReceptionIdFromContext(reception = currentReception) {
  const id = reception?.id;
  if (reception?.source !== 'reception' || !isUuidLike(id)) return null;
  const receptionDate = normalizeKarteDateValue(getKarteDateFromReception(reception));
  const currentDate = normalizeKarteDateValue(getCurrentKarteDateValue());
  if (receptionDate && currentDate && receptionDate !== currentDate) return null;
  return id;
}

function getCurrentReceptionRecordId() {
  return getRecordReceptionIdFromContext(currentReception);
}

function getKarteContextValue(key, fallback = '') {
  return currentReception?.[key] ?? fallback;
}

function getKarteDoctorOptions(selectedName = '') {
  const rows = [
    ...getFacilityMasterItems('doctors'),
    ...cloneFacilityMasterDefaults('doctors').filter(row => isFacilityMasterItemVisible('doctors', row)),
    ...(facilityMasterListModalConfigs.doctors?.rows || [])
      .map((row, index) => facilityMasterModalRowToItem('doctors', row, index))
      .filter(row => isFacilityMasterItemVisible('doctors', row))
  ];
  const seen = new Set();
  const options = [];
  rows.forEach(row => {
    const name = String(row?.name || row?.doctor_name || '').trim();
    if (!name || seen.has(name)) return;
    seen.add(name);
    options.push({
      id: getKarteDoctorUserId(row),
      name
    });
  });
  if (selectedName && !seen.has(selectedName)) {
    options.unshift({ id: '', name: selectedName });
  }
  return options;
}

function getKarteDoctorUserId(row = {}) {
  const id = row?.doctor_user_id || row?.doctorUserId || row?.user_id || row?.userId || row?.user?.id || '';
  return isUuidLike(id) ? id : '';
}

function normalizeKarteDoctorNameKey(value) {
  return String(value || '')
    .replace(/\u3000/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function getKarteDoctorPayloadFromName(name) {
  const doctorName = String(name || '').trim();
  const doctorKey = normalizeKarteDoctorNameKey(doctorName);
  const doctorOption = getKarteDoctorOptions(doctorName)
    .find(option => normalizeKarteDoctorNameKey(option.name) === doctorKey);
  return {
    doctor_id: isUuidLike(doctorOption?.id) ? doctorOption.id : null,
    doctor_name_override: doctorName || null
  };
}

function getKarteDoctorPayloadFromSelect(select, fallbackName = '') {
  const selectedDoctorOption = select?.selectedOptions?.[0];
  const doctorName = String(select?.value || fallbackName || '').trim();
  const doctorId = selectedDoctorOption?.dataset?.doctorId || '';
  return {
    doctor_id: isUuidLike(doctorId) ? doctorId : null,
    doctor_name_override: doctorName || null
  };
}

function getKarteDepartmentOptions(selectedDepartment = '') {
  const rows = [
    ...(facilityLocalMasters.departments || []),
    ...(facilityMasterDefinitions.departments?.defaults || []),
    ...(facilityMasterListModalConfigs.departments?.rows || [])
  ];
  const values = [
    selectedDepartment,
    currentReception?.department,
    document.getElementById('karte-department')?.value,
    ...rows.map(row => row?.name || row?.department_name)
  ];
  return Array.from(new Set(values.map(value => String(value || '').trim()).filter(Boolean)));
}

function formatKarteReceptionOption(reception = {}) {
  const no = reception.reception_number || reception.number || reception['受付番号'] || '';
  const time = normalizeReceptionTimeForPayload(reception.reception_time || reception.appointment_time || reception.created_at) || '--:--';
  const department = reception.department || '診療科未設定';
  const doctor = reception.doctor_name || reception.doctor || '';
  return [no, time, department, doctor].filter(Boolean).join(' ');
}

function formatKarteInsuranceOption(insurance = {}) {
  const parts = [
    insurance.insurer_name || insurance.insurance_type_name || insurance.insurance_type,
    insurance.insurer_number,
    insurance.symbol,
    insurance.number,
    insurance.burden_ratio != null ? `${insurance.burden_ratio}%` : ''
  ];
  return parts.filter(Boolean).join(' ');
}

function formatKartePublicExpenseOption(expense = {}) {
  const lawNumber = getPublicExpenseLawNumber(expense);
  const name = getPublicExpenseDisplayName(expense);
  const recipientNumber = expense.recipient_number || expense.beneficiary_number || '';
  const burden = formatPublicExpenseLimitSummary(expense);
  const parts = [
    lawNumber ? `${name}（${lawNumber}）` : name,
    expense.municipality_name,
    recipientNumber,
    burden
  ];
  return parts.filter(Boolean).join(' ');
}

function getKarteContextSelectedInsurance() {
  return getReceptionSelectedInsurance(currentReception);
}

function getKarteContextPayloadFromState() {
  const insurance = getKarteContextSelectedInsurance();
  const publicExpenseIds = getReceptionSelectedPublicExpenseIds(currentReception);
  const noInsuranceStatuses = ['none', 'no_insurance', 'unregistered'];
  const noPublicExpenseStatuses = ['none', 'no_public_expense', 'unregistered'];
  const doctorPayload = getKarteDoctorPayloadFromName(
    currentReception?.doctor_name_override || currentReception?.doctor_name || currentReception?.doctor || ''
  );
  return {
    reception_id: getCurrentReceptionRecordId(),
    department: currentReception?.department || document.getElementById('karte-department')?.value || '内科',
    doctor_id: doctorPayload.doctor_id,
    doctor_name_override: doctorPayload.doctor_name_override || '',
    insurance_id: insurance?.id || null,
    public_expense_id: publicExpenseIds[0] || null,
    public_expense_1_id: publicExpenseIds[0] || null,
    public_expense_2_id: publicExpenseIds[1] || null,
    public_expense_3_id: publicExpenseIds[2] || null,
    insurance_card_status: insurance
      ? (noInsuranceStatuses.includes(currentReception?.insurance_card_status) ? 'unchecked' : (currentReception?.insurance_card_status || 'unchecked'))
      : (currentReception?.insurance_card_status || 'none'),
    medical_certificate_status: publicExpenseIds.length
      ? (noPublicExpenseStatuses.includes(currentReception?.medical_certificate_status) ? 'unchecked' : (currentReception?.medical_certificate_status || 'unchecked'))
      : (currentReception?.medical_certificate_status || 'none'),
    limit_certificate_status: currentReception?.limit_certificate_status || '',
    electronic_prescription_status: currentReception?.electronic_prescription_status || '',
    past_prescription_status: currentReception?.past_prescription_status || '',
    labor_auto_insurance: currentReception?.labor_auto_insurance || 'none',
    save_mode: currentReception?.save_mode || 'normal'
  };
}

function setKarteContextModalOptions(select, options, selectedValue = '', emptyLabel = '') {
  if (!select) return;
  select.innerHTML = [
    emptyLabel ? `<option value="">${escapeHtml(emptyLabel)}</option>` : '',
    ...options.map(option => {
      const value = String(option.value ?? option.id ?? option.name ?? '');
      const label = String(option.label ?? option.name ?? value);
      const selected = String(selectedValue || '') === value ? ' selected' : '';
      const attrs = option.doctorId ? ` data-doctor-id="${escapeHtml(option.doctorId)}"` : '';
      return `<option value="${escapeHtml(value)}"${selected}${attrs}>${escapeHtml(label)}</option>`;
    })
  ].join('');
}

