function getKarteContextCurrentReceptionOptions() {
  const rows = receptionsCache.filter(item => !currentPatient?.id || String(item.patient_id) === String(currentPatient.id));
  if (currentReception && !rows.some(item => String(item.id) === String(currentReception.id))) {
    rows.unshift(currentReception);
  }
  return rows;
}

function populateKarteContextModal() {
  const modal = ensureKarteContextModal();
  const context = getKarteContextPayloadFromState();
  const receptions = getKarteContextCurrentReceptionOptions();
  const insuranceSelectedValue = context.insurance_id || (
    shouldTreatReceptionAsNoInsurance(currentReception)
      ? ''
      : getPrimaryPatientInsurance()?.id || ''
  );
  setKarteContextModalOptions(
    modal.querySelector('#karte-context-reception-select'),
    receptions.map(item => ({ value: item.id, label: formatKarteReceptionOption(item) })),
    currentReception?.id || '',
    receptions.length ? '' : '受付未登録'
  );
  setKarteContextModalOptions(
    modal.querySelector('#karte-context-insurance-select'),
    currentPatientInsurances.map(item => ({ value: item.id, label: formatKarteInsuranceOption(item) })),
    insuranceSelectedValue,
    '保険無し'
  );
  const publicExpenseOptions = currentPatientPublicExpenses.map(item => ({ value: item.id, label: formatKartePublicExpenseOption(item) }));
  setKarteContextModalOptions(modal.querySelector('#karte-context-public-expense-1'), publicExpenseOptions, context.public_expense_1_id || '', '公費無し');
  setKarteContextModalOptions(modal.querySelector('#karte-context-public-expense-2'), publicExpenseOptions, context.public_expense_2_id || '', '公費無し');
  setKarteContextModalOptions(modal.querySelector('#karte-context-public-expense-3'), publicExpenseOptions, context.public_expense_3_id || '', '公費無し');

  const laborAuto = modal.querySelector('#karte-context-labor-auto');
  const draft = modal.querySelector('#karte-context-draft');
  if (laborAuto) laborAuto.value = context.labor_auto_insurance || 'none';
  if (draft) draft.checked = context.save_mode === 'draft';
}

