function getKarteAddReceptionOptions() {
  const currentDate = getCurrentKarteDateValue();
  const rows = getKarteContextCurrentReceptionOptions()
    .filter(item => {
      const receptionDate = getKarteDateFromReception(item);
      return !receptionDate || receptionDate === currentDate;
    });
  const seen = new Set();
  const options = [];

  rows.forEach((item, index) => {
    const key = String(item?.id || `current-${index}`);
    if (seen.has(key)) return;
    seen.add(key);
    options.push(item);
  });

  if (!options.length && currentReception) {
    options.push(currentReception);
  }

  return options;
}

function getKarteAddReceptionOptionValue(reception, index = 0) {
  return reception?.id ? String(reception.id) : `__current_reception_${index}`;
}

function getKarteAddReceptionByValue(value) {
  const options = getKarteAddReceptionOptions();
  return options.find((item, index) => getKarteAddReceptionOptionValue(item, index) === value)
    || options[0]
    || currentReception
    || {};
}

function formatKarteAddReceptionOption(reception = {}) {
  const formatted = formatKarteReceptionOption(reception);
  if (formatted && !formatted.startsWith('--:--')) return formatted;
  const patientName = currentPatient?.name || reception.patient_name || '';
  return [formatKarteNoRecordDateLabel(getCurrentKarteDateValue()), patientName]
    .filter(Boolean)
    .join(' ')
    || '受付未登録';
}

function formatKarteAddAmount(value) {
  const amount = Math.max(0, Number(value || 0) || 0);
  return `${amount.toLocaleString()} 円`;
}

function getKarteAddInsuranceSelectedValue(reception = {}) {
  if (Object.prototype.hasOwnProperty.call(reception, 'insurance_id')) {
    return reception.insurance_id || '';
  }
  return currentReception?.insurance_id || getPrimaryPatientInsurance()?.id || '';
}

function populateKarteAddModal(selectedReceptionValue = null) {
  const modal = ensureKarteAddModal();
  const receptions = getKarteAddReceptionOptions();
  const fallbackValue = currentReception
    ? getKarteAddReceptionOptionValue(
      currentReception,
      receptions.findIndex(item => item === currentReception)
    )
    : '';
  const selectedValue = selectedReceptionValue || fallbackValue || (receptions[0] ? getKarteAddReceptionOptionValue(receptions[0], 0) : '');
  const selectedReception = getKarteAddReceptionByValue(selectedValue);

  setKarteContextModalOptions(
    modal.querySelector('#karte-add-reception-select'),
    receptions.map((item, index) => ({
      value: getKarteAddReceptionOptionValue(item, index),
      label: formatKarteAddReceptionOption(item)
    })),
    selectedValue,
    receptions.length ? '' : '受付未登録'
  );

  setKarteContextModalOptions(
    modal.querySelector('#karte-add-insurance-select'),
    currentPatientInsurances.map(item => ({ value: item.id, label: formatKarteInsuranceOption(item) })),
    getKarteAddInsuranceSelectedValue(selectedReception),
    '保険無し'
  );

  const publicExpenseOptions = currentPatientPublicExpenses.map(item => ({ value: item.id, label: formatKartePublicExpenseOption(item) }));
  setKarteContextModalOptions(modal.querySelector('#karte-add-public-expense-1'), publicExpenseOptions, selectedReception.public_expense_1_id || '', '公費無し');
  setKarteContextModalOptions(modal.querySelector('#karte-add-public-expense-2'), publicExpenseOptions, selectedReception.public_expense_2_id || '', '公費無し');
  setKarteContextModalOptions(modal.querySelector('#karte-add-public-expense-3'), publicExpenseOptions, selectedReception.public_expense_3_id || '', '公費無し');

  ['1', '2', '3'].forEach(number => {
    setTextById(`karte-add-public-amount-${number}`, formatKarteAddAmount(selectedReception[`public_expense_${number}_other_amount`]));
  });

  const laborAuto = modal.querySelector('#karte-add-labor-auto');
  const draft = modal.querySelector('#karte-add-draft');
  if (laborAuto) laborAuto.value = selectedReception.labor_auto_insurance || currentReception?.labor_auto_insurance || 'none';
  if (draft) draft.checked = (currentReception?.save_mode || 'normal') === 'draft';
}

function readKarteAddModalPayload() {
  const modal = ensureKarteAddModal();
  const selectedReception = getKarteAddReceptionByValue(modal.querySelector('#karte-add-reception-select')?.value || '');
  const insuranceId = modal.querySelector('#karte-add-insurance-select')?.value || null;
  const doctorPayload = getKarteDoctorPayloadFromName(
    selectedReception.doctor_name_override || selectedReception.doctor_name || selectedReception.doctor || ''
  );
  return {
    reception: selectedReception,
    department: selectedReception.department || currentReception?.department || document.getElementById('karte-department')?.value || '内科',
    doctor_id: doctorPayload.doctor_id,
    doctor_name_override: doctorPayload.doctor_name_override || '',
    insurance_id: insuranceId,
    public_expense_1_id: modal.querySelector('#karte-add-public-expense-1')?.value || null,
    public_expense_2_id: modal.querySelector('#karte-add-public-expense-2')?.value || null,
    public_expense_3_id: modal.querySelector('#karte-add-public-expense-3')?.value || null,
    public_expense_1_other_amount: Math.max(0, Number(selectedReception.public_expense_1_other_amount || 0) || 0),
    public_expense_2_other_amount: Math.max(0, Number(selectedReception.public_expense_2_other_amount || 0) || 0),
    public_expense_3_other_amount: Math.max(0, Number(selectedReception.public_expense_3_other_amount || 0) || 0),
    labor_auto_insurance: modal.querySelector('#karte-add-labor-auto')?.value || 'none',
    insurance_card_status: insuranceId ? (selectedReception.insurance_card_status || currentReception?.insurance_card_status || '') : 'none',
    medical_certificate_status: selectedReception.medical_certificate_status || currentReception?.medical_certificate_status || '',
    save_mode: modal.querySelector('#karte-add-draft')?.checked ? 'draft' : 'normal'
  };
}

async function openKarteAddModal() {
  if (!currentPatient) {
    showToast('患者を選択してください', 'error');
    return;
  }
  if (currentPatient?.id) {
    await loadPatientInsurances(currentPatient.id);
  }
  populateKarteAddModal();
  ensureKarteAddModal().classList.remove('hidden');
}

function closeKarteAddModal() {
  document.getElementById('karte-add-modal')?.classList.add('hidden');
}

async function addKarteFromModal() {
  if (!currentPatient) {
    showToast('患者を選択してください', 'error');
    return;
  }
  if (!(await confirmDiscardKarteChangesIfNeeded())) return;

  const addButton = document.getElementById('karte-add-submit');
  const payload = readKarteAddModalPayload();
  const selectedReception = payload.reception || {};
  const date = getCurrentKarteDateValue();

  try {
    if (addButton) {
      addButton.disabled = true;
      addButton.textContent = '追加中...';
    }

    currentReception = {
      ...(currentReception || {}),
      ...selectedReception,
      patient_id: currentPatient.id,
      reception_date: getKarteDateFromReception(selectedReception) || date,
      visit_date: date,
      department: payload.department,
      doctor_id: payload.doctor_id,
      doctor_name_override: payload.doctor_name_override,
      doctor_name: payload.doctor_name_override || selectedReception.doctor_name || currentReception?.doctor_name || '',
      doctor: payload.doctor_name_override || selectedReception.doctor || currentReception?.doctor || '',
      insurance_id: payload.insurance_id,
      public_expense_1_id: payload.public_expense_1_id,
      public_expense_2_id: payload.public_expense_2_id,
      public_expense_3_id: payload.public_expense_3_id,
      public_expense_1_other_amount: payload.public_expense_1_other_amount,
      public_expense_2_other_amount: payload.public_expense_2_other_amount,
      public_expense_3_other_amount: payload.public_expense_3_other_amount,
      labor_auto_insurance: payload.labor_auto_insurance,
      insurance_card_status: payload.insurance_card_status,
      medical_certificate_status: payload.medical_certificate_status,
      save_mode: payload.save_mode
    };

    const departmentInput = document.getElementById('karte-department');
    if (departmentInput) departmentInput.value = payload.department;

    karteInitializationRequestId += 1;
    clearPatientBillingData(currentPatient.id, date);
    resetKarteEditor();
    updateKarteHeaderContext('未承認');
    saveCurrentPatientBilling({ allowAfterDeletion: true });
    resetKarteDirtyTracking();
    closeKarteAddModal();
  } catch (error) {
    console.error('カルテ追加エラー:', error);
    showToast('カルテの追加に失敗しました: ' + error.message, 'error');
  } finally {
    if (addButton) {
      addButton.disabled = false;
      addButton.textContent = '追加';
    }
  }
}

