async function getPatientForReceptionEdit(reception) {
  if (!reception?.patient_id) return null;
  let patient = Storage.getPatients().find(item => String(item.id) === String(reception.patient_id));
  if (patient) return patient;
  try {
    patient = await withPatientMemoTimeout(PatientAPI.get(reception.patient_id));
    const patients = Storage.getPatients();
    if (!patients.some(item => String(item.id) === String(patient.id))) {
      Storage.setPatients([...patients, patient]);
    }
    return patient;
  } catch (error) {
    console.warn('受付編集用患者取得エラー:', error);
    return buildPatientFromReception(reception);
  }
}

