function populatePatientMemoFacilityOptions(patient) {
  const select = document.getElementById('patient-memo-facility');
  if (!select) return;
  const user = Storage.getCurrentUser();
  const options = [
    patient?.facility,
    patient?.facility_name,
    user?.facility_name,
    ...(Array.isArray(facilityMasterFacilities) ? facilityMasterFacilities : [])
  ].filter(Boolean);
  const uniqueOptions = Array.from(new Set(options.map(value => String(value).trim()).filter(Boolean)));
  select.innerHTML = '<option value="">未選択</option>' + uniqueOptions
    .map(name => `<option value="${escapeHtml(name)}">${escapeHtml(name)}</option>`)
    .join('');
  select.value = patient?.facility || patient?.facility_name || '';
}

function withPatientMemoTimeout(promise, label = '患者情報', timeoutMs = 6000) {
  let timeoutId = null;
  const timeout = new Promise((_, reject) => {
    timeoutId = setTimeout(() => reject(new Error(`${label}の応答がありません`)), timeoutMs);
  });
  return Promise.race([promise, timeout]).finally(() => clearTimeout(timeoutId));
}

function buildPatientFromReception(reception) {
  if (!reception?.patient_id) return null;
  return {
    id: reception.patient_id,
    patient_no: reception.patient_no,
    name: reception.patient_name,
    name_kana: reception.name_kana,
    gender: reception.gender || reception.patient_gender || reception.sex || '',
    birth_date: reception.birth_date,
    memo: reception.patient_memo || '',
    facility: reception.facility || reception.facility_name || '',
    facility_name: reception.facility_name || reception.facility || ''
  };
}

function getPatientMemoPatientFromReception(reception) {
  if (!reception?.patient_id) return null;
  const storedPatient = Storage.getPatients()
    .find(item => String(item.id) === String(reception.patient_id));
  const fallbackPatient = buildPatientFromReception(reception);
  const patient = {
    ...fallbackPatient,
    ...(storedPatient || {})
  };

  if (Object.prototype.hasOwnProperty.call(reception, 'patient_memo')) {
    patient.memo = reception.patient_memo || '';
  } else if (patient.memo === undefined || patient.memo === null) {
    patient.memo = '';
  }

  patient.facility = patient.facility || reception.facility || reception.facility_name || '';
  patient.facility_name = patient.facility_name || patient.facility || '';
  return patient;
}

