function updatePatientMemoCache(patientId, memo, facilityName = '') {
  const patients = Storage.getPatients();
  const index = patients.findIndex(item => String(item.id) === String(patientId));
  if (index >= 0) {
    patients[index] = {
      ...patients[index],
      memo,
      facility: facilityName || patients[index].facility,
      facility_name: facilityName || patients[index].facility_name
    };
    Storage.setPatients(patients);
  } else {
    const fallbackPatient = patientMemoEditState.patient
      || (currentPatient && String(currentPatient.id) === String(patientId) ? currentPatient : null);
    if (fallbackPatient) {
      Storage.setPatients([
        ...patients,
        {
          ...fallbackPatient,
          memo,
          facility: facilityName || fallbackPatient.facility,
          facility_name: facilityName || fallbackPatient.facility_name
        }
      ]);
    }
  }

  receptionsCache = receptionsCache.map(item => (
    String(item.patient_id) === String(patientId)
      ? { ...item, patient_memo: memo }
      : item
  ));

  if (currentPatient && String(currentPatient.id) === String(patientId)) {
    currentPatient = {
      ...currentPatient,
      memo,
      facility: facilityName || currentPatient.facility,
      facility_name: facilityName || currentPatient.facility_name
    };
    updatePatientDetailPanel(currentPatient);
  }
}

async function savePatientSummaryEditModal() {
  const { patient } = patientSummaryEditState;
  if (!patient?.id) {
    showToast('保存対象の患者が見つかりません', 'error');
    return;
  }

  const memo = document.getElementById('patient-summary-text')?.value || '';
  const saveButton = document.getElementById('patient-summary-save');

  try {
    if (saveButton) {
      saveButton.disabled = true;
      saveButton.textContent = '更新中...';
    }
    const auxiliary = getPatientM3Auxiliary(patient.id);
    auxiliary.summary = {
      text: memo,
      updatedAt: new Date().toISOString()
    };
    savePatientM3Auxiliary(patient.id, auxiliary);
    if (currentPatient && String(currentPatient.id) === String(patient.id)) {
      currentPatient = {
        ...currentPatient,
        summary: memo
      };
    }
    closePatientSummaryEditModal();
    await renderPatientSummaryPanel(patient.id);
    showToast('サマリーを更新しました', 'success');
  } catch (error) {
    console.error('サマリー保存エラー:', error);
    showToast('サマリーの保存に失敗しました: ' + error.message, 'error');
  } finally {
    hideLoading();
    if (saveButton) {
      saveButton.disabled = false;
      saveButton.textContent = '更新';
    }
  }
}

