function appendReceptionMemoLabel() {
  const input = document.getElementById('reception-memo-label');
  const textarea = document.getElementById('reception-memo-text');
  if (!input || !textarea) return;

  const label = input.value.trim();
  if (!label) {
    input.focus();
    return;
  }

  const current = textarea.value || '';
  const separator = current && !current.endsWith('\n') ? '\n' : '';
  textarea.value = `${current}${separator}【${label}】`;
  input.value = '';
  textarea.focus();
}

