async function loadReceptionEditInsuranceData(patientId) {
  if (!patientId || !window.InsuranceAPI) {
    currentPatientInsurances = [];
    currentPatientPublicExpenses = [];
    return;
  }
  try {
    const [insurances, publicExpenses] = await Promise.all([
      InsuranceAPI.list(patientId, true, false),
      InsuranceAPI.listPublicExpenses ? InsuranceAPI.listPublicExpenses(patientId, true) : Promise.resolve([])
    ]);
    currentPatientInsurances = insurances || [];
    currentPatientPublicExpenses = publicExpenses || [];
  } catch (error) {
    console.warn('受付編集用保険取得エラー:', error);
    currentPatientInsurances = [];
    currentPatientPublicExpenses = [];
  }
}

async function openReceptionEditModal(receptionId, options = {}) {
  const reception = receptionsCache.find(item => String(item.id) === String(receptionId));
  if (!reception) {
    showToast('受付情報が見つかりません', 'error');
    return;
  }

  currentReception = reception;
  const patient = await getPatientForReceptionEdit(reception);
  currentPatient = patient;
  await loadReceptionEditInsuranceData(reception.patient_id);
  syncCurrentReceptionContextFromPatientData();

  receptionEditState = {
    reception: currentReception,
    patient,
    title: options.title || '受付編集'
  };
  populateReceptionEditModal();
  ensureReceptionEditModal().classList.remove('hidden');
}

function populateReceptionEditModal() {
  const modal = ensureReceptionEditModal();
  const reception = receptionEditState.reception || currentReception || {};
  const patient = receptionEditState.patient || currentPatient || {};
  const insuranceSelectedValue = reception.insurance_id || (
    shouldTreatReceptionAsNoInsurance(reception)
      ? ''
      : getPrimaryPatientInsurance()?.id || ''
  );
  setTextById('reception-edit-title', receptionEditState.title || '受付編集');
  setTextById('reception-edit-date', formatDateSlash(reception.reception_date || getCurrentKarteDateValue()));
  setTextById('reception-edit-patient', patient.name || reception.patient_name || '-');

  setKarteContextModalOptions(
    modal.querySelector('#reception-edit-doctor'),
    getKarteDoctorOptions(reception.doctor_name || reception.doctor_name_override).map(item => ({
      value: item.name,
      label: item.name,
      doctorId: item.id
    })),
    reception.doctor_name_override || reception.doctor_name || '',
    '未設定'
  );
  setKarteContextModalOptions(
    modal.querySelector('#reception-edit-department'),
    getKarteDepartmentOptions(reception.department).map(name => ({ value: name, label: name })),
    reception.department || '内科'
  );
  setKarteContextModalOptions(
    modal.querySelector('#reception-edit-insurance'),
    currentPatientInsurances.map(item => ({ value: item.id, label: formatKarteInsuranceOption(item) })),
    insuranceSelectedValue,
    '保険無し'
  );
  const publicExpenseOptions = currentPatientPublicExpenses.map(item => ({ value: item.id, label: formatKartePublicExpenseOption(item) }));
  setKarteContextModalOptions(modal.querySelector('#reception-edit-public-expense-1'), publicExpenseOptions, reception.public_expense_1_id || '', '公費無し');
  setKarteContextModalOptions(modal.querySelector('#reception-edit-public-expense-2'), publicExpenseOptions, reception.public_expense_2_id || '', '公費無し');
  setKarteContextModalOptions(modal.querySelector('#reception-edit-public-expense-3'), publicExpenseOptions, reception.public_expense_3_id || '', '公費無し');

  const laborAuto = modal.querySelector('#reception-edit-labor-auto');
  if (laborAuto) laborAuto.value = reception.labor_auto_insurance || 'none';
  ['1', '2', '3'].forEach(number => {
    const input = modal.querySelector(`#reception-edit-public-amount-${number}`);
    if (input) input.value = Number(reception[`public_expense_${number}_other_amount`] || 0);
  });

  const setChecked = (selector, checked) => {
    const input = modal.querySelector(selector);
    if (input) input.checked = Boolean(checked);
  };
  setChecked('#reception-edit-confirm-insurance', reception.insurance_card_status === 'confirmed');
  setChecked('#reception-edit-confirm-limit', reception.limit_certificate_status === 'confirmed');
  setChecked('#reception-edit-confirm-eprescription', reception.electronic_prescription_status === 'requested');
  setChecked('#reception-edit-confirm-past', reception.past_prescription_status === 'confirmed');
}

function readReceptionEditPayload() {
  const modal = ensureReceptionEditModal();
  const doctorSelect = modal.querySelector('#reception-edit-doctor');
  const doctorPayload = getKarteDoctorPayloadFromSelect(doctorSelect);
  const insuranceId = modal.querySelector('#reception-edit-insurance')?.value || null;
  const publicExpenseIds = [
    modal.querySelector('#reception-edit-public-expense-1')?.value || null,
    modal.querySelector('#reception-edit-public-expense-2')?.value || null,
    modal.querySelector('#reception-edit-public-expense-3')?.value || null
  ];
  const currentMedicalCertificateStatus = currentReception?.medical_certificate_status || '';
  return {
    department: modal.querySelector('#reception-edit-department')?.value || currentReception?.department || '内科',
    doctor_id: doctorPayload.doctor_id,
    doctor_name_override: doctorPayload.doctor_name_override,
    insurance_id: insuranceId,
    public_expense_1_id: publicExpenseIds[0],
    public_expense_2_id: publicExpenseIds[1],
    public_expense_3_id: publicExpenseIds[2],
    public_expense_1_other_amount: Math.max(0, Number(modal.querySelector('#reception-edit-public-amount-1')?.value || 0) || 0),
    public_expense_2_other_amount: Math.max(0, Number(modal.querySelector('#reception-edit-public-amount-2')?.value || 0) || 0),
    public_expense_3_other_amount: Math.max(0, Number(modal.querySelector('#reception-edit-public-amount-3')?.value || 0) || 0),
    labor_auto_insurance: modal.querySelector('#reception-edit-labor-auto')?.value || 'none',
    insurance_card_status: insuranceId
      ? (modal.querySelector('#reception-edit-confirm-insurance')?.checked ? 'confirmed' : 'unchecked')
      : 'none',
    medical_certificate_status: publicExpenseIds.filter(Boolean).length
      ? (['none', 'no_public_expense', 'unregistered'].includes(currentMedicalCertificateStatus) ? 'unchecked' : (currentMedicalCertificateStatus || 'unchecked'))
      : 'none',
    limit_certificate_status: modal.querySelector('#reception-edit-confirm-limit')?.checked ? 'confirmed' : 'unchecked',
    electronic_prescription_status: modal.querySelector('#reception-edit-confirm-eprescription')?.checked ? 'requested' : 'none',
    past_prescription_status: modal.querySelector('#reception-edit-confirm-past')?.checked ? 'confirmed' : 'unchecked',
    save_mode: currentReception?.save_mode || 'normal'
  };
}

async function saveReceptionEditModal() {
  const saveButton = document.getElementById('reception-edit-save');
  const payload = readReceptionEditPayload();
  const apiPayload = buildReceptionApiPayloadFromContext(payload);
  const wasExistingReception = Boolean(currentReception?.source === 'reception' && currentReception.id);
  try {
    if (saveButton) {
      saveButton.disabled = true;
      saveButton.textContent = '登録中...';
    }
    const fallbackReception = {
      ...(currentReception || {}),
      ...payload,
      ...apiPayload,
      ...buildReceptionContextPatch({ ...(currentReception || {}), ...payload, ...apiPayload }),
      doctor_name: apiPayload.doctor_name_override || currentReception?.doctor_name || '',
      doctor: apiPayload.doctor_name_override || currentReception?.doctor || ''
    };
    const receptionId = await ensureCurrentReceptionForContext(apiPayload);
    fallbackReception.id = receptionId || fallbackReception.id;
    if (receptionId && window.ReceptionAPI && wasExistingReception) {
      const result = await ReceptionAPI.update(receptionId, apiPayload);
      mergeCurrentReceptionFromApiResponse(result, fallbackReception);
    } else if (!receptionId) {
      currentReception = fallbackReception;
      upsertReceptionCache(currentReception);
    }
    closeReceptionEditModal();
    renderReceptionTable();
    updateKarteHeaderContext();
    showToast('受付情報を更新しました', 'success');
  } catch (error) {
    console.error('受付編集エラー:', error);
    showToast('受付情報の更新に失敗しました: ' + error.message, 'error');
  } finally {
    if (saveButton) {
      saveButton.disabled = false;
      saveButton.textContent = '登録';
    }
  }
}

window.openReceptionEditModal = openReceptionEditModal;

async function ensureCurrentReceptionForContext(payload = getKarteContextPayloadFromState()) {
  if (!currentPatient || !window.ReceptionAPI) return null;
  if (currentReception?.source === 'reception' && currentReception.id) return currentReception.id;

  const previousReception = currentReception || {};
  const previousId = currentReception?.id;
  const apiPayload = buildReceptionApiPayloadFromContext(payload);
  const created = await ReceptionAPI.create({
    reservation_id: currentReception?.source === 'reservation' ? currentReception.id : (currentReception?.reservation_id || null),
    patient_id: currentPatient.id,
    reception_date: getCurrentKarteDateValue(),
    reception_time: normalizeReceptionTimeForPayload(currentReception?.reception_time || currentReception?.created_at),
    appointment_time: normalizeReceptionTimeForPayload(currentReception?.appointment_time),
    status: previousReception?.status || getFacilityReceptionInitialStatus(),
    reception_memo: currentReception?.reception_memo || null,
    first_visit: getReceptionFirstVisitForPayload(),
    ...apiPayload
  });

  const fallbackReception = {
    ...previousReception,
    ...payload,
    ...apiPayload,
    id: created?.id,
    patient_id: currentPatient.id,
    first_visit: created?.first_visit ?? previousReception?.first_visit ?? null,
    source: 'reception',
    status: previousReception?.status || getFacilityReceptionInitialStatus()
  };
  if (previousId) {
    receptionsCache = receptionsCache.filter(item => String(item.id) !== String(previousId));
  }
  mergeCurrentReceptionFromApiResponse(created, fallbackReception);
  return currentReception?.id || created?.id || null;
}

async function ensureCurrentReceptionForRecordSave() {
  if (!currentPatient || !currentReception) return getCurrentReceptionRecordId();
  if (currentReception.source === 'reception') {
    const context = getKarteContextPayloadFromState();
    const apiPayload = buildReceptionApiPayloadFromContext(context);
    applyCurrentReceptionContextPatch({ ...context, ...apiPayload });
    if (window.ReceptionAPI && currentReception.id) {
      const result = await ReceptionAPI.update(currentReception.id, apiPayload);
      mergeCurrentReceptionFromApiResponse(result, currentReception);
    }
    return getCurrentReceptionRecordId();
  }
  if (currentReception.source !== 'reservation') return getCurrentReceptionRecordId();
  return await ensureCurrentReceptionForContext(getKarteContextPayloadFromState());
}

function readKarteContextModalPayload() {
  const modal = ensureKarteContextModal();
  const doctorSelect = modal.querySelector('#karte-context-doctor-select');
  const doctorName = doctorSelect?.value || currentReception?.doctor_name_override || currentReception?.doctor_name || currentReception?.doctor || '';
  const doctorPayload = getKarteDoctorPayloadFromSelect(doctorSelect, doctorName);
  const insuranceId = modal.querySelector('#karte-context-insurance-select')?.value || null;
  const publicExpenseIds = [
    modal.querySelector('#karte-context-public-expense-1')?.value || null,
    modal.querySelector('#karte-context-public-expense-2')?.value || null,
    modal.querySelector('#karte-context-public-expense-3')?.value || null
  ];
  const currentInsuranceStatus = currentReception?.insurance_card_status || '';
  const currentMedicalCertificateStatus = currentReception?.medical_certificate_status || '';
  return {
    department: modal.querySelector('#karte-context-department-select')?.value || currentReception?.department || document.getElementById('karte-department')?.value || '内科',
    doctor_id: doctorPayload.doctor_id,
    doctor_name_override: doctorPayload.doctor_name_override,
    insurance_id: insuranceId,
    public_expense_1_id: publicExpenseIds[0],
    public_expense_2_id: publicExpenseIds[1],
    public_expense_3_id: publicExpenseIds[2],
    insurance_card_status: insuranceId
      ? (['none', 'no_insurance', 'unregistered'].includes(currentInsuranceStatus) ? 'unchecked' : (currentInsuranceStatus || 'unchecked'))
      : 'none',
    medical_certificate_status: publicExpenseIds.filter(Boolean).length
      ? (['none', 'no_public_expense', 'unregistered'].includes(currentMedicalCertificateStatus) ? 'unchecked' : (currentMedicalCertificateStatus || 'unchecked'))
      : 'none',
    limit_certificate_status: currentReception?.limit_certificate_status || '',
    electronic_prescription_status: currentReception?.electronic_prescription_status || '',
    past_prescription_status: currentReception?.past_prescription_status || '',
    labor_auto_insurance: modal.querySelector('#karte-context-labor-auto')?.value || 'none',
    save_mode: modal.querySelector('#karte-context-draft')?.checked ? 'draft' : 'normal'
  };
}

async function saveKarteContextModal() {
  const saveButton = document.getElementById('karte-context-save');
  const payload = readKarteContextModalPayload();
  const apiPayload = buildReceptionApiPayloadFromContext(payload);
  const wasExistingReception = Boolean(currentReception?.source === 'reception' && currentReception.id);
  try {
    if (saveButton) {
      saveButton.disabled = true;
      saveButton.textContent = '更新中...';
    }
    const fallbackReception = {
      ...(currentReception || {}),
      ...payload,
      ...apiPayload,
      ...buildReceptionContextPatch({ ...(currentReception || {}), ...payload, ...apiPayload }),
      doctor_name: apiPayload.doctor_name_override || currentReception?.doctor_name || '',
      doctor: apiPayload.doctor_name_override || currentReception?.doctor || '',
      department: apiPayload.department
    };
    const receptionId = await ensureCurrentReceptionForContext(apiPayload);
    fallbackReception.id = receptionId || fallbackReception.id;
    if (receptionId && window.ReceptionAPI && wasExistingReception) {
      const result = await ReceptionAPI.update(receptionId, apiPayload);
      mergeCurrentReceptionFromApiResponse(result, fallbackReception);
    } else if (!receptionId) {
      currentReception = fallbackReception;
      upsertReceptionCache(currentReception);
    }
    const departmentInput = document.getElementById('karte-department');
    if (departmentInput) departmentInput.value = payload.department;
    updateKarteHeaderContext();
    saveCurrentPatientBilling();
    closeKarteContextModal();
    showToast('カルテ情報を更新しました', 'success');
  } catch (error) {
    console.error('カルテ更新エラー:', error);
    showToast('カルテ情報の更新に失敗しました: ' + error.message, 'error');
  } finally {
    if (saveButton) {
      saveButton.disabled = false;
      saveButton.textContent = '更新';
    }
  }
}

