const EXPLICIT_EXTERNAL_USAGE_OPTIONS = typeof window !== 'undefined' && Array.isArray(window.EXPLICIT_EXTERNAL_USAGE_OPTIONS)
  ? window.EXPLICIT_EXTERNAL_USAGE_OPTIONS
  : [];

const EXPLICIT_ORAL_USAGE_OPTIONS = typeof window !== 'undefined' && Array.isArray(window.EXPLICIT_ORAL_USAGE_OPTIONS)
  ? window.EXPLICIT_ORAL_USAGE_OPTIONS
  : [];
const EXPLICIT_ORAL_USAGE_OPTIONS_BY_TIMES = typeof window !== 'undefined' && window.EXPLICIT_ORAL_USAGE_OPTIONS_BY_TIMES
  ? window.EXPLICIT_ORAL_USAGE_OPTIONS_BY_TIMES
  : {};
const EXPLICIT_ORAL_USAGE_OPTION_SET = new Set(EXPLICIT_ORAL_USAGE_OPTIONS.map(option => String(option || '').trim()).filter(Boolean));

function normalizePrescriptionFrequencyText(frequency = '') {
  return String(frequency || '')
    .replace(/[０-９]/g, ch => String.fromCharCode(ch.charCodeAt(0) - 0xFEE0))
    .replace(/[Ａ-Ｚａ-ｚ]/g, ch => String.fromCharCode(ch.charCodeAt(0) - 0xFEE0))
    .replace(/[（）]/g, ch => (ch === '（' ? '(' : ')'))
    .replace(/[～〜]/g, '-')
    .replace(/\s+/g, '')
    .trim();
}

function stripPrescriptionRoutePrefix(frequency = '') {
  return String(frequency || '').replace(/^(\[(電|内|外|注|頓)\]\s*)+/, '').trim();
}

function normalizePrescriptionUsageKey(frequency = '') {
  return normalizePrescriptionFrequencyText(stripPrescriptionRoutePrefix(frequency));
}

function getPrescriptionDailyTimesRange(frequency = '') {
  const normalized = normalizePrescriptionFrequencyText(frequency);
  const rangeMatch = normalized.match(/1日(\d+)(?:[-~](\d+))?回/);
  if (rangeMatch) {
    const first = Number(rangeMatch[1]);
    const second = rangeMatch[2] ? Number(rangeMatch[2]) : first;
    const min = Math.min(first, second);
    const max = Math.max(first, second);
    return Number.isFinite(min) && min > 0
      ? { min, max, exact: min === max, variable: false }
      : null;
  }
  if (/1日数回/.test(normalized)) {
    return { min: 4, max: Number.POSITIVE_INFINITY, exact: false, variable: true };
  }
  if (/1日[○〇]回/.test(normalized)) {
    return { min: null, max: null, exact: false, variable: true };
  }
  return null;
}

function getPrescriptionTimesPerDay(frequency = '') {
  const range = getPrescriptionDailyTimesRange(frequency);
  return Number.isFinite(range?.min) ? range.min : 1;
}

function prescriptionUsageDailyTimesMatches(option = '', key = '') {
  const range = getPrescriptionDailyTimesRange(option);
  if (!range) return false;
  const min = Number.isFinite(range.min) ? range.min : null;
  const max = Number.isFinite(range.max) ? range.max : min;
  if (min === null || max === null) return false;
  if (key === 'once') return min <= 1 && max >= 1;
  if (key === 'twice') return min <= 2 && max >= 2;
  if (key === 'three') return min <= 3 && max >= 3;
  if (key === 'fourMore') return max >= 4;
  return false;
}

function getPrescriptionUsageTimesFilterKey(option = '') {
  if (prescriptionUsageDailyTimesMatches(option, 'once')) return 'once';
  if (prescriptionUsageDailyTimesMatches(option, 'twice')) return 'twice';
  if (prescriptionUsageDailyTimesMatches(option, 'three')) return 'three';
  if (prescriptionUsageDailyTimesMatches(option, 'fourMore')) return 'fourMore';
  return '';
}

function isAsNeededPrescriptionFrequency(frequency = '') {
  const value = normalizePrescriptionFrequencyText(frequency);
  if (/\[頓\]/.test(value) || value.includes('頓服') || value.includes('頓用')) return true;
  if (/\[(外|注)\]/.test(value)) return false;
  return /(発熱時|疼痛時|痛む時|頭痛時|歯痛時|胸痛時|腹痛時|腰痛時|関節痛時|嘔気時|吐き気時|嘔吐時|便秘時|下痢時|不眠時|不安時|発作時|喘息発作時|必要時|症状ある時|めまい時|かゆい時|けいれん時|血圧上昇時|血糖上昇時)/.test(value);
}

function isExplicitAsNeededUsageOption(option = '') {
  return isAsNeededPrescriptionFrequency(option);
}

function isExplicitOralUsageOption(option = '') {
  const text = String(option || '').trim();
  const normalized = normalizePrescriptionFrequencyText(text);
  if (/\[(外|注|頓)\]/.test(normalized) || isAsNeededPrescriptionFrequency(text)) return false;
  if (/\[内\]/.test(normalized)) return true;
  if (isInjectionUsageOption(text) || isExternalUsageOption(text)) return false;
  return normalized.includes('内服')
    || normalized.includes('服用')
    || normalized.includes('舌下')
    || normalized.includes('バッカル')
    || EXPLICIT_ORAL_USAGE_OPTION_SET.has(text);
}

function isExplicitExternalUsageOption(option = '') {
  return isExternalUsageOption(option);
}

function getPrescriptionUsageRouteType(option = '') {
  const normalized = normalizePrescriptionFrequencyText(option);
  if (/\[注\]/.test(normalized)) return 'injection';
  if (/\[外\]/.test(normalized)) return 'external';
  if (/\[頓\]/.test(normalized)) return 'asNeeded';
  if (/\[内\]/.test(normalized)) return isAsNeededPrescriptionFrequency(option) ? 'asNeeded' : 'oral';
  if (isInjectionUsageOption(option)) return 'injection';
  if (isExternalUsageOption(option)) return 'external';
  if (isAsNeededPrescriptionFrequency(option)) return 'asNeeded';
  if (isExplicitOralUsageOption(option)) return 'oral';
  return 'other';
}

function uniquePrescriptionUsageOptions(options) {
  const seen = new Set();
  return options.filter(option => {
    const value = String(option || '').trim();
    if (!value || seen.has(value)) return false;
    seen.add(value);
    return true;
  });
}

function getExplicitAsNeededUsageOptions(baseOptions = getDrugUsageMasterOptions()) {
  return uniquePrescriptionUsageOptions([
    ...baseOptions.filter(isExplicitAsNeededUsageOption),
    ...EXPLICIT_AS_NEEDED_USAGE_OPTIONS
  ]);
}

function getExplicitOralUsageOptions(baseOptions = getDrugUsageMasterOptions()) {
  return uniquePrescriptionUsageOptions([
    ...baseOptions.filter(isExplicitOralUsageOption),
    ...EXPLICIT_ORAL_USAGE_OPTIONS
  ]);
}

function getExplicitOralUsageOptionsByTimes(key, baseOptions = getDrugUsageMasterOptions()) {
  const explicitOptions = Array.isArray(EXPLICIT_ORAL_USAGE_OPTIONS_BY_TIMES[key])
    ? EXPLICIT_ORAL_USAGE_OPTIONS_BY_TIMES[key]
    : [];
  return uniquePrescriptionUsageOptions([
    ...baseOptions.filter(option => isExplicitOralUsageOption(option) && prescriptionUsageDailyTimesMatches(option, key)),
    ...explicitOptions.filter(option => isExplicitOralUsageOption(option) && prescriptionUsageDailyTimesMatches(option, key))
  ]);
}

function isExplicitOralUsageOptionByTimes(option, key) {
  return isExplicitOralUsageOption(option) && prescriptionUsageDailyTimesMatches(option, key);
}

function getExplicitExternalUsageOptions(baseOptions = getDrugUsageMasterOptions()) {
  return uniquePrescriptionUsageOptions([
    ...baseOptions.filter(isExplicitExternalUsageOption),
    ...EXPLICIT_EXTERNAL_USAGE_OPTIONS
  ]);
}

function getPrescriptionUsageRouteSortRank(option = '') {
  const route = getPrescriptionUsageRouteType(option);
  if (route === 'oral') return 0;
  if (route === 'asNeeded') return 1;
  if (route === 'external') return 2;
  if (route === 'injection') return 3;
  return 4;
}

function getPrescriptionUsagePeriodSortRank(option = '') {
  const normalized = normalizePrescriptionFrequencyText(option);
  if (getPrescriptionDailyTimesRange(option)) return 0;
  if (/隔日/.test(normalized)) return 1;
  if (/(週|週間)/.test(normalized)) return 2;
  if (/(月|ヶ月|ヵ月|4週)/.test(normalized)) return 3;
  if (/(医師の指示|指示通り|適宜|用法なし)/.test(normalized)) return 5;
  return 4;
}

function getPrescriptionUsageTimesSortRank(option = '') {
  const range = getPrescriptionDailyTimesRange(option);
  if (!range) return 99;
  if (Number.isFinite(range.min)) return Math.min(range.min, 20);
  return 98;
}

function getPrescriptionUsageTimingSortRank(option = '') {
  const normalized = normalizePrescriptionUsageKey(option);
  const rules = [
    [/毎食後|朝昼夕食後/, 10],
    [/毎食前|朝昼夕食前/, 20],
    [/毎食直後|朝昼夕食直後/, 30],
    [/毎食直前|朝昼夕食直前/, 40],
    [/毎食間|朝昼夕食間/, 50],
    [/起床時|起床/, 100],
    [/朝食前30分前/, 110],
    [/朝食直前/, 120],
    [/朝食前/, 130],
    [/朝食事中/, 140],
    [/朝食直後/, 150],
    [/朝食後/, 160],
    [/朝/, 170],
    [/昼食直前/, 210],
    [/昼食前/, 220],
    [/昼食事中/, 230],
    [/昼食直後/, 240],
    [/昼食後/, 250],
    [/昼/, 260],
    [/夕食直前/, 310],
    [/夕食前/, 320],
    [/夕食事中/, 330],
    [/夕食直後/, 340],
    [/夕食後/, 350],
    [/夕|夜/, 360],
    [/就寝前|寝る前/, 400],
    [/空腹時/, 430],
    [/食間/, 440],
    [/時間毎|毎\d+時間|決まった時刻/, 500],
    [/哺乳時/, 520],
    [/医師の指示|指示通り/, 900],
    [/適宜|用法なし/, 920]
  ];
  const match = rules.find(([pattern]) => pattern.test(normalized));
  return match ? match[1] : 800;
}

function comparePrescriptionUsageOptions(left, right) {
  const leftText = String(left?.option ?? left ?? '');
  const rightText = String(right?.option ?? right ?? '');
  const leftKey = [
    getPrescriptionUsageRouteSortRank(leftText),
    getPrescriptionUsagePeriodSortRank(leftText),
    getPrescriptionUsageTimesSortRank(leftText),
    /\[電\]/.test(normalizePrescriptionFrequencyText(leftText)) ? 1 : 0,
    getPrescriptionUsageTimingSortRank(leftText)
  ];
  const rightKey = [
    getPrescriptionUsageRouteSortRank(rightText),
    getPrescriptionUsagePeriodSortRank(rightText),
    getPrescriptionUsageTimesSortRank(rightText),
    /\[電\]/.test(normalizePrescriptionFrequencyText(rightText)) ? 1 : 0,
    getPrescriptionUsageTimingSortRank(rightText)
  ];
  for (let i = 0; i < leftKey.length; i += 1) {
    if (leftKey[i] !== rightKey[i]) return leftKey[i] - rightKey[i];
  }
  const labelCompare = normalizePrescriptionUsageKey(leftText)
    .localeCompare(normalizePrescriptionUsageKey(rightText), 'ja-JP', { numeric: true, sensitivity: 'base' });
  if (labelCompare) return labelCompare;
  return (left.index ?? 0) - (right.index ?? 0);
}

function sortPrescriptionUsageOptions(options) {
  return uniquePrescriptionUsageOptions(options)
    .map((option, index) => ({ option, index }))
    .sort(comparePrescriptionUsageOptions)
    .map(entry => entry.option);
}

function getPrescriptionDurationUnit(frequency = '') {
  return isAsNeededPrescriptionFrequency(frequency) ? '回' : '日';
}

function formatPrescriptionDuration(value, frequency = '', suffix = '') {
  if (!value) return '';
  return formatHalfWidthNumericText(`${value}${getPrescriptionDurationUnit(frequency)}${suffix}`);
}

function getDrugUsageMasterOptions() {
  const masterOptions = getFacilityMasterNames('usages');
  return masterOptions.length ? masterOptions : FALLBACK_DRUG_USAGE_OPTIONS;
}

function isInjectionUsageOption(option) {
  const normalized = normalizePrescriptionFrequencyText(option);
  return /\[注\]/.test(normalized) || /(注|点滴|静注|筋注|皮下注)/.test(normalized);
}

function isExternalUsageOption(option) {
  const normalized = normalizePrescriptionFrequencyText(option);
  return /\[外\]/.test(normalized)
    || /(外用|塗布|貼付|湿布|撒布|噴霧|消毒|点眼|点鼻|点耳|吸入|うがい|含嗽|トローチ|坐|耳|鼻|眼|膣|肛門|患部|貼付|浣腸)/.test(normalized);
}

function pickDrugUsageOption(predicate, fallback) {
  const options = getDrugUsageMasterOptions();
  return options.find(predicate)
    || options.find(option => normalizePrescriptionUsageKey(option) === normalizePrescriptionUsageKey(fallback))
    || fallback;
}

function getPreferredDrugUsageDefault(drug = {}, fallback = '1日3回毎食後') {
  const name = drug.name || drug.drug_name || '';
  if (/(注|点滴|静注|筋注|皮下注|注射)/.test(name)) {
    return pickDrugUsageOption(option => /医師.*指示|指示通り/.test(option) && isInjectionUsageOption(option), fallback);
  }
  if (/(テープ|パップ|ゲル|軟膏|クリーム|ローション|点眼|点鼻|吸入|坐剤|坐薬|貼付)/.test(name)) {
    return pickDrugUsageOption(option => getPrescriptionTimesPerDay(option) === 2 && isExternalUsageOption(option), fallback);
  }
  return pickDrugUsageOption(option => getPrescriptionTimesPerDay(option) === 3 && /(毎食後|食後)/.test(option), fallback);
}

function populateDrugFrequencySelect(selectedValue = '') {
  const select = document.getElementById('drug-frequency');
  if (!select) return;
  const defaultValue = getPreferredDrugUsageDefault({}, '1日3回毎食後');
  const currentValue = String(selectedValue || '').trim() || defaultValue;
  const options = sortPrescriptionUsageOptions(includeCurrentUsage(getDrugUsageMasterOptions(), currentValue));
  select.innerHTML = options
    .map(option => `<option value="${escapeHtml(option)}">${escapeHalfWidthNumericText(option)}</option>`)
    .join('');
  select.value = options.includes(currentValue) ? currentValue : (options[0] || '');
}

async function refreshDrugFrequencyOptionsFromFacilityMaster(selectedValue = '') {
  const select = document.getElementById('drug-frequency');
  const currentValue = selectedValue || select?.value || '';
  await ensureFacilityMasterLoaded('usages');
  populateDrugFrequencySelect(currentValue);
}

function normalizeKarteVitalSigns(value) {
  if (!value) return {};
  if (typeof value === 'string') {
    try {
      return normalizeKarteVitalSigns(JSON.parse(value));
    } catch (error) {
      return {};
    }
  }
  if (typeof value === 'object' && !Array.isArray(value)) {
    return { ...value };
  }
  return {};
}

function normalizePrescriptionRemarksText(value) {
  return String(value || '')
    .replace(/\r\n?/g, '\n')
    .split('\n')
    .map(line => line.trim())
    .filter(Boolean)
    .join('\n');
}

function getPrescriptionRemarksInput() {
  return document.getElementById('prescription-remarks-input');
}

function hasPrescriptionRemarkLine(value, text) {
  const remark = normalizePrescriptionRemarksText(text);
  if (!remark) return false;
  return normalizePrescriptionRemarksText(value).split('\n').includes(remark);
}

function syncPrescriptionOnePackageCheckbox() {
  const checked = hasPrescriptionRemarkLine(getPrescriptionRemarksValue(), PRESCRIPTION_REMARK_ONE_PACKAGE_TEXT);
  ['rx-one-package', 'karte-rx-one-package-remark'].forEach(id => {
    const checkbox = document.getElementById(id);
    if (checkbox) checkbox.checked = checked;
  });
}

function getPrescriptionRemarksValue() {
  const input = getPrescriptionRemarksInput();
  return normalizePrescriptionRemarksText(input ? input.value : currentPrescriptionRemarks);
}

function setPrescriptionRemarksValue(value) {
  currentPrescriptionRemarks = normalizePrescriptionRemarksText(value);
  const input = getPrescriptionRemarksInput();
  if (input) input.value = currentPrescriptionRemarks;
  syncPrescriptionOnePackageCheckbox();
}

function syncPrescriptionRemarksStateFromInput() {
  setPrescriptionRemarksValue(getPrescriptionRemarksValue());
  return currentPrescriptionRemarks;
}

function appendPrescriptionRemark(text, options = {}) {
  const remark = normalizePrescriptionRemarksText(text);
  if (!remark) return;
  const lines = getPrescriptionRemarksValue().split('\n').filter(Boolean);
  if (!lines.includes(remark)) {
    lines.push(remark);
    setPrescriptionRemarksValue(lines.join('\n'));
  } else {
    syncPrescriptionOnePackageCheckbox();
  }
  if (options.save !== false) saveCurrentPatientBilling();
}

function removePrescriptionRemark(text, options = {}) {
  const remark = normalizePrescriptionRemarksText(text);
  if (!remark) return;
  const nextValue = getPrescriptionRemarksValue()
    .split('\n')
    .filter(line => line && line !== remark)
    .join('\n');
  setPrescriptionRemarksValue(nextValue);
  if (options.save !== false) saveCurrentPatientBilling();
}

function getPrescriptionCommentRemarkBaseText(comment) {
  const enteredText = normalizePrescriptionRemarksText(
    comment?.prescriptionRemarkText
    || comment?.prescription_remark_text
    || comment?.freeText
    || comment?.free_text
    || ''
  ).replace(/^フリーコメント[:：]\s*/, '');
  if (enteredText) return enteredText;
  if (isEditableProcedureComment(comment)) return '';
  return normalizePrescriptionRemarksText(comment?.template || comment?.name || '');
}

function getPrescriptionCommentRemarkLine(prescription, comment) {
  if (
    !comment?.printToPrescriptionRemarks
    && !comment?.print_to_prescription_remarks
    && !comment?.prescriptionRemark
    && !comment?.prescription_remark
    && !comment?.prescription_remarks
  ) {
    return '';
  }
  const text = getPrescriptionCommentRemarkBaseText(comment);
  if (!text) return '';
  return text;
}

function getPrescriptionCommentRemarkLines() {
  const lines = [];
  (pendingPrescriptions || []).forEach(prescription => {
    getPrescriptionComments(prescription).forEach(comment => {
      const line = getPrescriptionCommentRemarkLine(prescription, comment);
      if (line) lines.push(line);
    });
  });
  return lines;
}

function getEffectivePrescriptionRemarksValue() {
  const lines = [];
  getPrescriptionRemarksValue().split('\n').forEach(line => {
    if (line && !lines.includes(line)) lines.push(line);
  });
  getPrescriptionCommentRemarkLines().forEach(line => {
    if (line && !lines.includes(line)) lines.push(line);
  });
  return normalizePrescriptionRemarksText(lines.join('\n'));
}

function setPrescriptionOnePackageRemarkEnabled(enabled) {
  if (enabled) {
    appendPrescriptionRemark(PRESCRIPTION_REMARK_ONE_PACKAGE_TEXT);
  } else {
    removePrescriptionRemark(PRESCRIPTION_REMARK_ONE_PACKAGE_TEXT);
  }
}

function getPrescriptionRemarksFromRecord(record) {
  const vitalSigns = normalizeKarteVitalSigns(record?.vital_signs || record?.vitalSigns);
  return normalizePrescriptionRemarksText(
    record?.prescription_remarks
      || record?.prescriptionRemarks
      || vitalSigns.prescription_remarks
      || vitalSigns.prescriptionRemarks
      || ''
  );
}

function buildKarteVitalSignsPayload() {
  const payload = normalizeKarteVitalSigns(currentRecordVitalSigns);
  const remarks = syncPrescriptionRemarksStateFromInput();
  delete payload.prescriptionRemarks;
  if (remarks) {
    payload.prescription_remarks = remarks;
  } else {
    delete payload.prescription_remarks;
  }
  return Object.keys(payload).length ? payload : null;
}

// 処方モーダルを表示
function showPrescriptionDialog() {
  if (!currentPatient) {
    showToast('患者を選択してください', 'error');
    return;
  }

  const modal = document.getElementById('prescription-modal');
  modal.classList.remove('hidden');
  setPrescriptionRemarksValue(currentPrescriptionRemarks);

  // 入力をリセット
  document.getElementById('drug-search-input').value = '';
  document.getElementById('drug-search-results').innerHTML = '';
  hideDrugDetailPanel();
  refreshDrugFrequencyOptionsFromFacilityMaster()
    .then(() => calculateTotalQuantity())
    .catch(error => console.warn('用法マスタの読み込みに失敗しました:', error));

  // 処方履歴を取得
  loadPrescriptionHistory();

  // 現在の処方を表示
  renderCurrentPrescriptions();
}

// 処方モーダルを閉じる
function closePrescriptionModal() {
  document.getElementById('prescription-modal').classList.add('hidden');
}

// 処方履歴を取得
async function loadPrescriptionHistory() {
  if (!currentPatient) return;

  const historyList = document.getElementById('prescription-history-list');
  historyList.innerHTML = '<div class="loading"><i class="fas fa-spinner fa-spin"></i> 読み込み中...</div>';

  try {
    const result = await PrescriptionAPI.getHistory(currentPatient.id, 20);
    prescriptionHistory = result.data || [];

    if (prescriptionHistory.length === 0) {
      historyList.innerHTML = '<div class="no-data">過去の処方がありません</div>';
      return;
    }

    // 日付ごとにグループ化
    const grouped = {};
    prescriptionHistory.forEach(p => {
      const date = p.visit_date || p.created_at?.split('T')[0] || '-';
      if (!grouped[date]) {
        grouped[date] = [];
      }
      grouped[date].push(p);
    });

    historyList.innerHTML = Object.entries(grouped).map(([date, items]) => `
      <div class="rx-history-group">
        <div class="rx-history-date">${formatDateWithDay(date)}</div>
        <div class="rx-history-items">
          ${items.map(p => `
            <div class="rx-history-item" data-prescription-id="${p.id}">
              <span class="rx-name">${escapeHalfWidthNumericText(p.drug_name)}</span>
              <span class="rx-detail">${escapeHalfWidthNumericText(`${p.dosage || ''} ${p.frequency || ''} ${formatPrescriptionDuration(p.days, p.frequency, '分')}`)}</span>
              <button class="btn-do-rx" onclick="doPrescription('${p.id}')" title="この処方を追加">
                <i class="fas fa-redo"></i> Do
              </button>
            </div>
          `).join('')}
        </div>
      </div>
    `).join('');

  } catch (error) {
    console.error('処方履歴取得エラー:', error);
    historyList.innerHTML = '<div class="no-data">履歴の取得に失敗しました</div>';
  }
}

// Do処方（過去の処方を複製）
function doPrescription(prescriptionId) {
  const original = prescriptionHistory.find(p => p.id === prescriptionId);
  if (!original) return;

  const newPrescription = {
    drug_name: original.drug_name,
    drug_code: original.drug_code,
    dosage: original.dosage,
    dosage_unit: original.dosage_unit || '錠',
    frequency: original.frequency,
    days: original.days,
    total_quantity: original.total_quantity,
    dispensing_type: original.dispensing_type || original.prescription_type || '院外',
    drug_type: original.drug_type || inferPrescriptionDrugType(original),
    is_generic: original.is_generic || false,
    generic_name: original.generic_name || original.genericName || '',
    generic_class: original.generic_class || original.genericClass || '',
    generic_prescription_code: original.generic_prescription_code || original.genericPrescriptionCode || '',
    generic_prescription_name: original.generic_prescription_name || original.genericPrescriptionName || '',
    generic_prescription_addition_category: original.generic_prescription_addition_category || original.genericPrescriptionAdditionCategory || '',
    generic_prescription_lowest_price: original.generic_prescription_lowest_price ?? original.genericPrescriptionLowestPrice ?? '',
    generic_prescription_master_note: original.generic_prescription_master_note || original.genericPrescriptionMasterNote || '',
    generic_prescription_master_version: original.generic_prescription_master_version || original.genericPrescriptionMasterVersion || '',
    comment_codes: original.comment_codes || original.commentCodes || [],
    comments: original.comments || original.comment_names || [],
    free_comment: original.free_comment || original.freeComment || '',
    receipt_position: original.receipt_position || original.receiptPosition || 'summary',
    note: original.note || ''
  };

  addPrescriptionToPending(newPrescription, { checkDuplicate: false });
  renderCurrentPrescriptions();
  showToast('処方を追加しました', 'success');
}

// 薬剤検索
let drugSearchTimeout = null;
function initDrugSearch() {
  const searchInput = document.getElementById('drug-search-input');
  const resultsContainer = document.getElementById('drug-search-results');

  if (!searchInput) return;

  searchInput.addEventListener('input', (e) => {
    clearTimeout(drugSearchTimeout);
    const query = e.target.value.trim();

    if (query.length < 2) {
      resultsContainer.innerHTML = '';
      return;
    }

    drugSearchTimeout = setTimeout(async () => {
      resultsContainer.innerHTML = '<div class="loading"><i class="fas fa-spinner fa-spin"></i> 検索中...</div>';

      try {
        const result = await PrescriptionAPI.searchDrugs(query);
        const drugs = result.data || [];

        if (drugs.length === 0) {
          resultsContainer.innerHTML = '<div class="no-results">該当する薬剤が見つかりません</div>';
          return;
        }

        resultsContainer.innerHTML = drugs.map(drug => {
          const drugHint = formatHalfWidthNumericText(
            drug.therapeutic_name
            || drug.generic_name
            || String(drug.efficacy_effect || '').replace(/\s+/g, ' ').slice(0, 48)
          );
          return `
            <div class="drug-result-item" onclick="selectDrug(${JSON.stringify(drug).replace(/"/g, '&quot;')})">
              <div class="drug-result-name">${escapeHalfWidthNumericText(drug.name)}</div>
              <div class="drug-result-info">
                <span class="drug-code">${drug.yj_code || drug.hot_code || '-'}</span>
                <span class="drug-unit">${drug.unit || '-'}</span>
                <span class="drug-price">${drug.price ? drug.price + '円' : '-'}</span>
                ${drugHint ? `<span class="drug-hit-hint">${escapeHalfWidthNumericText(drugHint)}</span>` : ''}
              </div>
            </div>
          `;
        }).join('');

      } catch (error) {
        console.error('薬剤検索エラー:', error);
        resultsContainer.innerHTML = '<div class="no-results">薬剤マスターの検索に失敗しました</div>';
      }
    }, 300);
  });
}

// 薬剤を選択
function selectDrug(drug) {
  selectedDrug = drug;

  // 検索結果をクリア
  document.getElementById('drug-search-results').innerHTML = '';
  document.getElementById('drug-search-input').value = '';

  // 詳細パネルを表示
  showDrugDetailPanel(drug);
}

// 薬剤詳細パネルを表示
function showDrugDetailPanel(drug) {
  const panel = document.getElementById('drug-detail-panel');
  panel.classList.remove('hidden');

  document.getElementById('selected-drug-name').textContent = formatHalfWidthNumericText(drug.name);
  document.getElementById('selected-drug-unit').textContent = drug.unit || '-';

  // 単位を設定
  const unitSelect = document.getElementById('drug-dosage-unit');
  if (drug.unit) {
    for (let option of unitSelect.options) {
      if (option.value === drug.unit) {
        option.selected = true;
        break;
      }
    }
  }

  const normalizedDrug = normalizeDrugForOrder(drug);
  const defaults = getDrugPrescriptionDefaults(normalizedDrug);
  populateDrugFrequencySelect(defaults.frequency);

  // 総量を計算
  calculateTotalQuantity();
}

// 薬剤詳細パネルを非表示
function hideDrugDetailPanel() {
  document.getElementById('drug-detail-panel').classList.add('hidden');
  selectedDrug = null;
}

function createProcedurePrescriptionId() {
  return `rx_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
}

function ensurePrescriptionIdentity(prescription) {
  if (!prescription) return null;
  prescription.prescription_item_id = prescription.prescription_item_id
    || prescription.prescriptionItemId
    || prescription.local_id
    || createProcedurePrescriptionId();
  prescription.prescriptionItemId = prescription.prescription_item_id;
  prescription.prescription_group_id = prescription.prescription_group_id || prescription.prescriptionGroupId || '';
  prescription.prescriptionGroupId = prescription.prescription_group_id;
  prescription.prescription_group_parent_id = prescription.prescription_group_parent_id || prescription.prescriptionGroupParentId || '';
  prescription.prescriptionGroupParentId = prescription.prescription_group_parent_id;
  prescription.prescription_group_label = prescription.prescription_group_label || prescription.prescriptionGroupLabel || '';
  prescription.prescriptionGroupLabel = prescription.prescription_group_label;
  return prescription;
}

function getPrescriptionGroupId(prescription) {
  return prescription?.prescription_group_id || prescription?.prescriptionGroupId || '';
}

function getPrescriptionSelectionKey(prescription) {
  ensurePrescriptionIdentity(prescription);
  const groupId = getPrescriptionGroupId(prescription);
  return groupId ? `rxmanual:${groupId}` : `rxsingle:${prescription.prescription_item_id}`;
}

function getPrescriptionGroupLabel(prescription) {
  return prescription?.prescription_group_label || prescription?.prescriptionGroupLabel || '';
}

function isPrescriptionManualGroupChild(prescription) {
  return Boolean(prescription?.prescription_group_parent_id || prescription?.prescriptionGroupParentId);
}

function getSelectedPrescriptionGroupAnchor() {
  if (!selectedPrescriptionGroupAnchorId) return null;
  pendingPrescriptions.forEach(prescription => ensurePrescriptionIdentity(prescription));
  const anchor = pendingPrescriptions.find(prescription => prescription.prescription_item_id === selectedPrescriptionGroupAnchorId);
  if (!anchor) selectedPrescriptionGroupAnchorId = null;
  return anchor || null;
}

function getSelectedPrescriptionSelectionKey() {
  const anchor = getSelectedPrescriptionGroupAnchor();
  return anchor ? getPrescriptionSelectionKey(anchor) : '';
}

function ensureProcedureGroupForPrescriptionTarget(anchor) {
  if (!anchor) return null;
  ensureProcedureActionIdentity(anchor);
  let groupId = getManualBillingGroupId(anchor);
  const groupLabel = getManualBillingGroupLabel(anchor) || anchor.name || '算定';

  if (!groupId) {
    groupId = `manual_${anchor.procedure_item_id}`;
    anchor.billing_group_id = groupId;
    anchor.billingGroupId = groupId;
    anchor.billing_group_parent_id = '';
    anchor.billingGroupParentId = '';
    anchor.billing_group_label = groupLabel;
    anchor.billingGroupLabel = groupLabel;
  }

  selectedActions.forEach(action => {
    if (action !== anchor && getManualBillingGroupId(action) !== groupId) return;
    ensureProcedureActionIdentity(action);
    action.billing_group_id = groupId;
    action.billingGroupId = groupId;
    action.billing_group_label = groupLabel;
    action.billingGroupLabel = groupLabel;
  });

  return { groupId, groupLabel };
}

function assignPrescriptionToSelectedGroup(prescription) {
  const anchor = getSelectedPrescriptionGroupAnchor();
  if (!anchor || anchor === prescription) return false;

  ensurePrescriptionIdentity(anchor);
  ensurePrescriptionIdentity(prescription);
  const groupId = getPrescriptionGroupId(anchor) || `rxmanual_${anchor.prescription_item_id}`;
  const existingParent = pendingPrescriptions.find(member =>
    getPrescriptionGroupId(member) === groupId && !isPrescriptionManualGroupChild(member)
  );
  const parent = existingParent || anchor;
  ensurePrescriptionIdentity(parent);
  const groupLabel = getPrescriptionGroupLabel(parent) || getPrescriptionGroupLabel(anchor) || parent.drug_name || anchor.drug_name || '処方';

  pendingPrescriptions.forEach(member => {
    if (member !== anchor && getPrescriptionGroupId(member) !== groupId) return;
    ensurePrescriptionIdentity(member);
    member.prescription_group_id = groupId;
    member.prescriptionGroupId = groupId;
    member.prescription_group_label = groupLabel;
    member.prescriptionGroupLabel = groupLabel;
    if (member === parent) {
      member.prescription_group_parent_id = '';
      member.prescriptionGroupParentId = '';
    }
  });

  prescription.prescription_group_id = groupId;
  prescription.prescriptionGroupId = groupId;
  prescription.prescription_group_parent_id = parent.prescription_item_id;
  prescription.prescriptionGroupParentId = parent.prescription_item_id;
  prescription.prescription_group_label = groupLabel;
  prescription.prescriptionGroupLabel = groupLabel;
  syncPrescriptionGroupSharedFields(groupId, parent);
  return true;
}

function assignPrescriptionToSelectedProcedureGroup(prescription) {
  const actionAnchor = getSelectedProcedureGroupAnchor();
  const target = ensureProcedureGroupForPrescriptionTarget(actionAnchor);
  if (!target) return false;

  ensurePrescriptionIdentity(prescription);
  const { groupId, groupLabel } = target;
  const existingParent = pendingPrescriptions.find(member =>
    getPrescriptionGroupId(member) === groupId && !isPrescriptionManualGroupChild(member)
  );

  pendingPrescriptions.forEach(member => {
    if (getPrescriptionGroupId(member) !== groupId) return;
    ensurePrescriptionIdentity(member);
    member.prescription_group_id = groupId;
    member.prescriptionGroupId = groupId;
    member.prescription_group_label = groupLabel;
    member.prescriptionGroupLabel = groupLabel;
    if (!existingParent || member === existingParent) {
      member.prescription_group_parent_id = '';
      member.prescriptionGroupParentId = '';
    } else {
      member.prescription_group_parent_id = existingParent.prescription_item_id;
      member.prescriptionGroupParentId = existingParent.prescription_item_id;
    }
  });

  prescription.prescription_group_id = groupId;
  prescription.prescriptionGroupId = groupId;
  prescription.prescription_group_parent_id = existingParent ? existingParent.prescription_item_id : '';
  prescription.prescriptionGroupParentId = prescription.prescription_group_parent_id;
  prescription.prescription_group_label = groupLabel;
  prescription.prescriptionGroupLabel = groupLabel;
  syncPrescriptionGroupSharedFields(groupId, existingParent || prescription);
  return true;
}

function addPrescriptionToPending(prescription, options = {}) {
  assignMissingProcedureEntryOrdersFromDom();
  const normalized = syncPrescriptionDerivedFields(ensurePrescriptionIdentity(prescription));
  if (options.checkDuplicate) {
    const key = normalized.drug_code || normalized.drug_name;
    const exists = pendingPrescriptions.some(p => (p.drug_code || p.drug_name) === key || p.drug_name === normalized.drug_name);
    if (exists) {
      if (options.showDuplicateToast !== false) {
        showToast(`${normalized.drug_name}は既に追加されています`, 'info');
      }
      return { added: false, grouped: false };
    }
  }

  const grouped = assignPrescriptionToSelectedGroup(normalized)
    || assignPrescriptionToSelectedProcedureGroup(normalized);
  assignProcedureEntryOrderForAppend(normalized);
  pendingPrescriptions.push(normalized);
  if (grouped) rememberPrescriptionGroupSuggestion(getPrescriptionGroupId(normalized));
  return { added: true, grouped };
}

// 総量を計算
function calculateTotalQuantity() {
  const dosage = parseFloat(document.getElementById('drug-dosage').value) || 1;
  const days = parseInt(document.getElementById('drug-days').value) || 7;
  const frequency = document.getElementById('drug-frequency').value;
  const unit = document.getElementById('drug-dosage-unit').value;
  const durationUnitLabel = document.getElementById('drug-days-unit-label');
  if (durationUnitLabel) {
    durationUnitLabel.textContent = `${getPrescriptionDurationUnit(frequency)}分`;
  }

  const drugType = inferPrescriptionDrugType({ ...selectedDrug, frequency, unit });
  const total = drugType === '外用' ? calculatePrescriptionQuantity(dosage, frequency, days, drugType)
    : dosage * getPrescriptionTimesPerDay(frequency) * days;
  document.getElementById('drug-total-qty').textContent = `${total}${unit}`;
}

// 処方に薬剤を追加
function addDrugToPrescription() {
  if (!selectedDrug) return;

  const normalizedDrug = normalizeDrugForOrder(selectedDrug);
  const defaults = getDrugPrescriptionDefaults(normalizedDrug);
  const dosage = document.getElementById('drug-dosage').value;
  const unit = document.getElementById('drug-dosage-unit').value;
  const frequency = document.getElementById('drug-frequency').value;
  const days = normalizePrescriptionDays({
    ...normalizedDrug, frequency, unit, days: parseInt(document.getElementById('drug-days').value)
  });
  const isGeneric = document.getElementById('drug-generic').checked;
  const note = document.getElementById('drug-note').value;
  const genericChangeAllowed = readOptionalBooleanFlag(normalizedDrug, ['generic_change_allowed', 'genericChangeAllowed']);
  const longTermListed = readOptionalBooleanFlag(normalizedDrug, [
    'long_term_listed',
    'longTermListed',
    'long_term_listed_drug',
    'is_long_term_listed'
  ]);

  const drugType = inferPrescriptionDrugType({ ...normalizedDrug, frequency, unit });
  const totalQty = drugType === '外用' ? calculatePrescriptionQuantity(parseFloat(dosage), frequency, days, drugType)
    : parseFloat(dosage) * getPrescriptionTimesPerDay(frequency) * days;

  const prescription = {
    drug_name: normalizedDrug.name,
    drug_code: normalizedDrug.code || normalizedDrug.yj_code || normalizedDrug.hot_code,
    yj_code: normalizedDrug.yj_code || normalizedDrug.yjCode || '',
    hot_code: normalizedDrug.hot_code || normalizedDrug.hotCode || '',
    receipt_code: normalizedDrug.receipt_code || normalizedDrug.receiptCode || '',
    dosage: `${dosage}${unit}`,
    dosage_quantity: parseFloat(dosage) || 1,
    dosage_unit: unit,
    unit,
    frequency: frequency,
    days: days,
    total_quantity: totalQty,
    dispensing_type: selectedDrug.dispensing_type || defaults.dispensingType || '院外',
    drug_type: inferPrescriptionDrugType({
      ...normalizedDrug,
      drug_name: normalizedDrug.name,
      frequency,
      unit
    }),
    is_generic: isGeneric,
    generic_name: normalizedDrug.generic_name || normalizedDrug.genericName || '',
    generic_class: normalizedDrug.generic_class || normalizedDrug.genericClass || normalizedDrug.generic_type || '',
    generic_prescription_code: normalizedDrug.generic_prescription_code || normalizedDrug.genericPrescriptionCode || '',
    generic_prescription_name: normalizedDrug.generic_prescription_name || normalizedDrug.genericPrescriptionName || '',
    generic_prescription_addition_category: normalizedDrug.generic_prescription_addition_category || normalizedDrug.genericPrescriptionAdditionCategory || '',
    generic_prescription_lowest_price: normalizedDrug.generic_prescription_lowest_price ?? normalizedDrug.genericPrescriptionLowestPrice ?? '',
    generic_prescription_master_note: normalizedDrug.generic_prescription_master_note || normalizedDrug.genericPrescriptionMasterNote || '',
    generic_prescription_master_version: normalizedDrug.generic_prescription_master_version || normalizedDrug.genericPrescriptionMasterVersion || '',
    long_term_listed: Boolean(longTermListed),
    long_term_patient_choice: false,
    generic_change_allowed: genericChangeAllowed === null ? true : genericChangeAllowed,
    generic_change_reason: normalizedDrug.generic_change_reason || normalizedDrug.genericChangeReason || '',
    requires_comment: Boolean(normalizedDrug.requires_comment || normalizedDrug.comment_required || normalizedDrug.selectable_comment_required),
    comment_required: Boolean(normalizedDrug.comment_required || normalizedDrug.requires_comment || normalizedDrug.selectable_comment_required),
    selectable_comment_required: Boolean(normalizedDrug.selectable_comment_required || normalizedDrug.comment_required || normalizedDrug.requires_comment),
    is_temporary: false,
    refill_allowed: false,
    is_refill: false,
    refill_count: null,
    note: note
  };

  addPrescriptionToPending(prescription, { checkDuplicate: false });
  renderCurrentPrescriptions();

  // パネルを閉じて次の入力へ
  hideDrugDetailPanel();
  document.getElementById('drug-search-input').focus();

  showToast('処方を追加しました', 'success');
}

function formatPrescriptionListNumber(value) {
  const number = Number(value);
  if (!Number.isFinite(number)) return String(value || '').trim();
  return Number.isInteger(number) ? String(number) : String(number).replace(/\.0+$/, '');
}

function formatPrescriptionDoseForList(prescription) {
  const rawUnit = prescription.unit || prescription.dosage_unit || '';
  const unit = rawUnit && rawUnit !== '-' ? rawUnit : '';
  const rawQuantity = prescription.dosage_quantity ?? prescription.quantity;
  const quantity = rawQuantity !== undefined && rawQuantity !== null && rawQuantity !== ''
    ? formatPrescriptionListNumber(rawQuantity)
    : '';
  if (quantity === '1' && !unit) return formatHalfWidthNumericText(String(prescription.dosage || '').trim());
  if (quantity) return formatHalfWidthNumericText([quantity, unit].filter(Boolean).join(' '));
  return formatHalfWidthNumericText(String(prescription.dosage || '').trim());
}

function normalizePrescriptionUnitLabel(value) {
  return formatHalfWidthNumericText(String(value || '-').trim() || '-');
}

function isCapsulePrescriptionUnit(value) {
  return normalizePrescriptionUnitLabel(value).replace(/\s+/g, '') === 'カプセル';
}

function renderPrescriptionUnitLabel(value) {
  const unit = normalizePrescriptionUnitLabel(value);
  if (isCapsulePrescriptionUnit(unit)) {
    return '<span class="rx-unit-line">カプ</span><span class="rx-unit-line">セル</span>';
  }
  return escapeHtml(unit);
}

function getPrescriptionUnitClass(value) {
  return isCapsulePrescriptionUnit(value) ? ' rx-unit-stacked' : '';
}

function formatPrescriptionUsageSummaryForList(prescription) {
  const dispensing = prescription.dispensing_type || '院外';
  const frequency = prescription.frequency || '';
  const days = prescription.days
    ? `${formatPrescriptionListNumber(prescription.days)} ${getPrescriptionDurationUnit(frequency)}`
    : '';
  return formatHalfWidthNumericText([dispensing, frequency, days].filter(Boolean).join(' '));
}

function renderCurrentPrescriptionDrugLine(prescription, originalIndex) {
  const dose = formatPrescriptionDoseForList(prescription);
  return `
    <div class="current-rx-drug-line" data-index="${originalIndex}">
      <span class="current-rx-icon">薬</span>
      <span class="current-rx-name">${escapeHalfWidthNumericText(prescription.drug_name)}</span>
      ${dose ? `<span class="current-rx-dose">${escapeHtml(dose)}</span>` : ''}
      <button class="current-rx-remove" onclick="event.stopPropagation(); removePrescription(${originalIndex})" title="この薬を削除" aria-label="この薬を削除">
        <i class="fas fa-times"></i>
      </button>
    </div>
  `;
}

function renderCurrentPrescriptionUsageLine(prescription) {
  const summary = formatPrescriptionUsageSummaryForList(prescription);
  if (!summary) return '';
  return `<div class="current-rx-usage-line">${escapeHtml(summary)}</div>`;
}

// 現在の処方リストを表示
function renderCurrentPrescriptions() {
  const container = document.getElementById('current-prescription-list');
  const countEl = document.getElementById('rp-count');

  if (pendingPrescriptions.length === 0) {
    container.innerHTML = `
      <div class="no-prescription-message">
        <i class="fas fa-pills"></i>
        <p>薬剤を検索して追加してください</p>
      </div>
    `;
    countEl.textContent = '0件';
    return;
  }

  countEl.textContent = `${pendingPrescriptions.length}件`;
  const selectedGroupKey = getSelectedPrescriptionSelectionKey();

  container.innerHTML = groupPendingPrescriptionsForDisplay().map(group => {
    const useSharedSummary = group.isManual && group.prescriptions.length > 1;
    const summarySource = useSharedSummary
      ? (group.prescriptions.find(({ prescription }) => !isPrescriptionManualGroupChild(prescription)) || group.prescriptions[0]).prescription
      : null;
    const groupClasses = [
      'current-rx-compact-group',
      group.isManual ? 'manual-grouped' : '',
      group.key === selectedGroupKey ? 'is-group-anchor-selected' : ''
    ].filter(Boolean).join(' ');
    const groupAnchorIndex = group.prescriptions[0]?.originalIndex;
    const groupClickAttr = groupAnchorIndex !== undefined
      ? ` onclick="selectPrescriptionGroupAnchor(event, ${groupAnchorIndex})" title="クリックして追加先の薬グループにする"`
      : '';

    return `
      <div class="${groupClasses}" data-group-key="${escapeHtml(group.key)}"${groupClickAttr}>
        ${group.prescriptions.map(({ prescription, originalIndex }) => `
          ${renderCurrentPrescriptionDrugLine(prescription, originalIndex)}
          ${useSharedSummary ? '' : renderCurrentPrescriptionUsageLine(prescription)}
          ${prescription.note ? `<div class="current-rx-note">${escapeHalfWidthNumericText(prescription.note)}</div>` : ''}
        `).join('')}
        ${useSharedSummary ? renderCurrentPrescriptionUsageLine(summarySource) : ''}
      </div>
    `;
  }).join('');
}

// 処方を削除
function removePrescription(index) {
  const prescription = pendingPrescriptions[index];
  ensurePrescriptionIdentity(prescription);
  const removedGroupId = getPrescriptionGroupId(prescription);
  const removedAnchorId = prescription?.prescription_item_id;
  pendingPrescriptions.splice(index, 1);
  if (selectedPrescriptionGroupAnchorId === removedAnchorId) {
    selectedPrescriptionGroupAnchorId = null;
  }
  normalizePrescriptionGroupAfterChange(removedGroupId);
  renderCurrentPrescriptions();
}

// 処方を保存
async function savePrescriptions() {
  if (pendingPrescriptions.length === 0) {
    showToast('処方が入力されていません', 'error');
    return;
  }

  // 一包化・ジェネリック設定を適用
  const genericAll = document.getElementById('rx-generic-all').checked;
  const onePackage = document.getElementById('rx-one-package').checked;

  if (genericAll) {
    pendingPrescriptions.forEach(p => p.is_generic = true);
  }
  if (onePackage) {
    appendPrescriptionRemark(PRESCRIPTION_REMARK_ONE_PACKAGE_TEXT, { save: false });
  }
  syncPrescriptionRemarksStateFromInput();

  // 処置・行為パネルに処方を表示
  resetDrugWarningsForPrescriptionEdit();
  renderPendingPrescriptionsInProcedure();
  updateTotalPoints();
  saveCurrentPatientBilling();
  checkPrescriptionsRealtime();

  // モーダルを閉じる
  closePrescriptionModal();

  showToast(`${pendingPrescriptions.length}件の処方を追加しました`, 'success');
}

function groupPendingPrescriptionsForDisplay() {
  const grouped = [];
  const indexByKey = new Map();

  pendingPrescriptions.forEach((prescription, originalIndex) => {
    ensurePrescriptionIdentity(prescription);
    const groupId = getPrescriptionGroupId(prescription);
    const key = groupId ? `rxmanual:${groupId}` : `rxsingle:${prescription.prescription_item_id || originalIndex}`;
    let groupIndex = indexByKey.get(key);
    if (groupIndex === undefined) {
      groupIndex = grouped.length;
      indexByKey.set(key, groupIndex);
      grouped.push({
        key,
        isManual: Boolean(groupId),
        entryOrder: getProcedureEntrySortOrder(prescription, 'prescription', originalIndex),
        prescriptions: []
      });
    }
    grouped[groupIndex].prescriptions.push({ prescription, originalIndex });
    grouped[groupIndex].entryOrder = Math.min(
      grouped[groupIndex].entryOrder,
      getProcedureEntrySortOrder(prescription, 'prescription', originalIndex)
    );
  });

  grouped.forEach(group => {
    if (!group.isManual) return;
    group.prescriptions.sort((left, right) => left.originalIndex - right.originalIndex);
  });

  return grouped.sort((left, right) => left.entryOrder - right.entryOrder);
}

function promotePrescriptionGroupAnchor(prescription) {
  const groupId = getPrescriptionGroupId(prescription);
  if (!groupId) return;
  ensurePrescriptionIdentity(prescription);
  const groupLabel = prescription.drug_name || getPrescriptionGroupLabel(prescription) || '処方';

  pendingPrescriptions.forEach(member => {
    if (getPrescriptionGroupId(member) !== groupId) return;
    ensurePrescriptionIdentity(member);
    member.prescription_group_id = groupId;
    member.prescriptionGroupId = groupId;
    member.prescription_group_label = groupLabel;
    member.prescriptionGroupLabel = groupLabel;
    if (member === prescription) {
      member.prescription_group_parent_id = '';
      member.prescriptionGroupParentId = '';
    } else {
      member.prescription_group_parent_id = prescription.prescription_item_id;
      member.prescriptionGroupParentId = prescription.prescription_item_id;
    }
  });
}

function selectPrescriptionGroupAnchor(event, index) {
  if (shouldIgnoreProcedureRowSelection(event)) return;
  const prescription = pendingPrescriptions[index];
  if (!prescription) return;
  ensurePrescriptionIdentity(prescription);
  const selectedKey = getSelectedPrescriptionSelectionKey();
  const clickedKey = getPrescriptionSelectionKey(prescription);

  if (selectedKey === clickedKey) {
    selectedPrescriptionGroupAnchorId = null;
    renderCurrentPrescriptions();
    renderPendingPrescriptionsInProcedure();
    return;
  }

  selectedProcedureGroupAnchorId = null;
  const groupId = getPrescriptionGroupId(prescription);
  if (groupId) {
    const parent = pendingPrescriptions.find(member =>
      getPrescriptionGroupId(member) === groupId && !isPrescriptionManualGroupChild(member)
    ) || prescription;
    ensurePrescriptionIdentity(parent);
    selectedPrescriptionGroupAnchorId = parent.prescription_item_id;
  } else {
    selectedPrescriptionGroupAnchorId = prescription.prescription_item_id;
  }
  renderCurrentPrescriptions();
  renderSelectedActionsInProcedure();
  renderPendingPrescriptionsInProcedure();
}

function clearPrescriptionGroupSelectionIfOutside(event) {
  if (!selectedPrescriptionGroupAnchorId) return;
  if (event?.target?.closest?.('.rx-claim-group')) return;
  if (event?.target?.closest?.('.current-rx-compact-group')) return;
  if (event?.target?.closest?.('.rx-usage-dialog-overlay')) return;
  if (event?.target?.closest?.('#prescription-modal')) return;
  if (event?.target?.closest?.('#category-tree')) return;
  if (event?.target?.closest?.('.m3-panel-right')) return;
  selectedPrescriptionGroupAnchorId = null;
  renderCurrentPrescriptions();
  renderPendingPrescriptionsInProcedure();
}

function normalizePrescriptionGroupAfterChange(groupId) {
  if (!groupId) return;
  const members = pendingPrescriptions.filter(prescription => getPrescriptionGroupId(prescription) === groupId);
  if (members.length <= 1) {
    members.forEach(prescription => {
      prescription.prescription_group_id = '';
      prescription.prescriptionGroupId = '';
      prescription.prescription_group_parent_id = '';
      prescription.prescriptionGroupParentId = '';
      prescription.prescription_group_label = '';
      prescription.prescriptionGroupLabel = '';
    });
    return;
  }

  let parent = members.find(prescription => !isPrescriptionManualGroupChild(prescription));
  if (!parent || !pendingPrescriptions.includes(parent)) {
    parent = members[0];
  }
  promotePrescriptionGroupAnchor(parent);
  rememberPrescriptionGroupSuggestion(groupId, { bump: false });
}

// 処置・行為パネルに処方を表示
function renderPendingPrescriptionsInProcedure() {
  const container = document.getElementById('procedure-items');
  if (!container) return;

  // 既存の処方表示を削除
  container.querySelectorAll('.rx-claim-group, .rx-procedure-item').forEach(el => el.remove());
  if (pendingPrescriptions.length === 0) return;

  syncAllPrescriptionGroupSharedFields();

  const selectedGroupKey = getSelectedPrescriptionSelectionKey();

  groupPendingPrescriptionsForDisplay().forEach(group => {
    const prescriptionGroupId = getPrescriptionGroupId(group.prescriptions[0]?.prescription);
    const groupEl = document.createElement('div');
    groupEl.className = [
      'rx-claim-group',
      group.prescriptions.length > 1 ? 'grouped' : '',
      group.isManual ? 'manual-grouped' : '',
      group.key === selectedGroupKey ? 'is-group-anchor-selected' : ''
    ].filter(Boolean).join(' ');
    groupEl.dataset.groupKey = group.key;
    groupEl.dataset.entryOrder = String(group.entryOrder);
    groupEl.dataset.manualGroupId = prescriptionGroupId || '';
    const useSharedControls = group.isManual && group.prescriptions.length > 1;
    const groupAnchorIndex = group.prescriptions[0]?.originalIndex;
    if (groupAnchorIndex !== undefined) {
      groupEl.title = 'クリックして追加先の薬グループにする';
      groupEl.onclick = event => selectPrescriptionGroupAnchor(event, groupAnchorIndex);
    }

    group.prescriptions.forEach(({ prescription: p, originalIndex: i }) => {
      syncPrescriptionDerivedFields(p);
      const durationUnit = getPrescriptionDurationUnit(p.frequency);
      const unitLabel = p.unit || p.dosage_unit || '-';
      const commentsHtml = renderPrescriptionComments(p, i);
      const rowClass = [
        isPrescriptionManualGroupChild(p) ? 'is-manual-group-child' : ''
      ].filter(Boolean).join(' ');
      const rowClassAttr = rowClass ? ` ${rowClass}` : '';
      const item = document.createElement('div');
      item.className = `m3-proc-item rx-procedure-item rx-edit-item procedure-entry-row${rowClassAttr}`;
      item.dataset.index = i;
      item.dataset.code = p.drug_code || '';
      item.title = 'クリックして追加先の薬グループにする';
      item.innerHTML = `
        <div class="rx-proc-main">
          ${renderPrescriptionActionIcon(i)}
          <span class="rx-prescription-text">
            <span class="rx-drug-mainline"><span class="m3-proc-name rx-drug-name">${escapeHalfWidthNumericText(p.drug_name)}</span>${renderPrescriptionWarnings(p, i)}</span>
          </span>
          <span class="rx-dose-cluster">
            <input class="rx-dose-input" type="text" inputmode="decimal" data-numeric-pad="decimal" data-min="0" value="${Number(p.dosage_quantity) || 1}" autocomplete="off"
                   onchange="updatePrescriptionProcedureItem(${i}, 'dosage_quantity', this.value)">
            <span class="rx-unit${getPrescriptionUnitClass(unitLabel)}">${renderPrescriptionUnitLabel(unitLabel)}</span>
          </span>
          <button class="proc-item-delete-btn" onclick="event.stopPropagation(); deletePrescriptionProcedureItem(${i})" title="この薬を削除">
            <i class="fas fa-times"></i>
          </button>
          ${commentsHtml}
        </div>
        ${useSharedControls ? '' : `
        <div class="rx-proc-controls">
          <select class="rx-dispensing-select" onchange="updatePrescriptionProcedureItem(${i}, 'dispensing_type', this.value)">
            ${renderSelectOptions(['院外', '院内'], p.dispensing_type || '院外')}
          </select>
          ${renderPrescriptionUsagePicker(i, p)}
          <span class="rx-days-cluster">
            <input class="rx-days-input" type="text" inputmode="numeric" data-numeric-pad="integer" data-min="1" value="${normalizePrescriptionDays(p) ?? ''}" autocomplete="off"
                   onchange="updatePrescriptionProcedureItem(${i}, 'days', this.value)">
            <span class="rx-days-label">${durationUnit}</span>
          </span>
        </div>
        `}
      `;

      const mainLine = item.querySelector('.rx-proc-main');
      if (mainLine) {
        mainLine.onclick = event => {
          if (shouldIgnoreProcedureRowSelection(event)) return;
          event.stopPropagation();
          selectPrescriptionGroupAnchor(event, i);
        };
      }

      groupEl.appendChild(item);
    });

    if (useSharedControls) {
      const shared = group.prescriptions.find(({ prescription }) => !isPrescriptionManualGroupChild(prescription))
        || group.prescriptions[0];
      const p = shared.prescription;
      const i = shared.originalIndex;
      const durationUnit = getPrescriptionDurationUnit(p.frequency);
      const controls = document.createElement('div');
      controls.className = 'rx-proc-controls rx-shared-controls';
      controls.innerHTML = `
        <select class="rx-dispensing-select" onchange="updatePrescriptionProcedureItem(${i}, 'dispensing_type', this.value)">
          ${renderSelectOptions(['院外', '院内'], p.dispensing_type || '院外')}
        </select>
        ${renderPrescriptionUsagePicker(i, p)}
        <span class="rx-days-cluster">
          <input class="rx-days-input" type="text" inputmode="numeric" data-numeric-pad="integer" data-min="1" value="${normalizePrescriptionDays(p) ?? ''}" autocomplete="off"
                 onchange="updatePrescriptionProcedureItem(${i}, 'days', this.value)">
          <span class="rx-days-label">${durationUnit}</span>
        </span>
        <button type="button" class="rx-group-delete-btn" onclick="event.stopPropagation(); deletePrescriptionGroup('${escapeHtml(prescriptionGroupId)}')" title="この薬グループを削除" aria-label="この薬グループを削除">
          <i class="fas fa-trash"></i>
        </button>
      `;
      groupEl.appendChild(controls);
    }

    const linkedActionGroup = prescriptionGroupId
      ? Array.from(container.querySelectorAll('.procedure-action-group'))
        .find(element => element.dataset.manualGroupId === prescriptionGroupId)
      : null;
    if (linkedActionGroup) {
      linkedActionGroup.insertAdjacentElement('afterend', groupEl);
    } else {
      insertProcedureElement(container, groupEl);
    }
  });
}

function renderSelectOptions(options, selectedValue) {
  return options.map(option => {
    const selected = option === selectedValue ? 'selected' : '';
    return `<option value="${escapeHtml(option)}" ${selected}>${escapeHalfWidthNumericText(option)}</option>`;
  }).join('');
}

function getDrugUsageOptions(prescription) {
  const allOptions = getDrugUsageMasterOptions();
  const drugType = typeof inferPrescriptionDrugType === 'function'
    ? inferPrescriptionDrugType(prescription)
    : '';
  let options = allOptions;

  if (drugType === '注射') {
    const injectionOptions = allOptions.filter(isInjectionUsageOption);
    options = injectionOptions.length ? injectionOptions : allOptions;
  } else if (drugType === '外用') {
    const externalOptions = getExplicitExternalUsageOptions(allOptions);
    options = externalOptions.length ? externalOptions : allOptions;
  } else if (drugType === '頓服') {
    const asNeededOptions = getExplicitAsNeededUsageOptions(allOptions);
    options = asNeededOptions.length ? asNeededOptions : allOptions;
  } else if (drugType === '内服') {
    const oralOptions = getExplicitOralUsageOptions(allOptions);
    options = oralOptions.length ? oralOptions : allOptions;
  }

  return includeCurrentUsage(options, prescription.frequency);
}

function includeCurrentUsage(options, currentUsage) {
  if (currentUsage && !options.includes(currentUsage)) {
    return [currentUsage, ...options];
  }
  return options;
}

function renderPrescriptionUsagePicker(index, prescription) {
  const value = prescription.frequency || '[内] 1日3回毎食後';
  return `
    <button type="button" class="rx-usage-picker" onclick="openPrescriptionUsageDialog(event, ${index})" title="用法を選択">
      <span>${escapeHalfWidthNumericText(value)}</span>
    </button>
  `;
}

let prescriptionUsageDialogState = {
  index: null,
  query: '',
  filters: []
};

const PRESCRIPTION_USAGE_FILTERS = [
  { key: 'oral', label: '内服' },
  { key: 'once', label: '1回' },
  { key: 'twice', label: '2回' },
  { key: 'three', label: '3回' },
  { key: 'fourMore', label: '4回以上' },
  { key: 'asNeeded', label: '頓服' },
  { key: 'external', label: '外用・その他' }
];

function getPrescriptionUsageFilterMatch(option, key) {
  const text = String(option || '');
  const route = getPrescriptionUsageRouteType(text);
  if (key === 'oral') return route === 'oral';
  if (key === 'once') return prescriptionUsageDailyTimesMatches(text, 'once');
  if (key === 'twice') return prescriptionUsageDailyTimesMatches(text, 'twice');
  if (key === 'three') return prescriptionUsageDailyTimesMatches(text, 'three');
  if (key === 'fourMore') return prescriptionUsageDailyTimesMatches(text, 'fourMore');
  if (key === 'asNeeded') return route === 'asNeeded';
  if (key === 'external') return route === 'external' || route === 'injection';
  return true;
}

function getFilteredPrescriptionUsageOptions() {
  const prescription = pendingPrescriptions[prescriptionUsageDialogState.index];
  if (!prescription) return [];
  const query = String(prescriptionUsageDialogState.query || '').trim().toLowerCase();
  const filters = prescriptionUsageDialogState.filters || [];
  const routeFilters = filters.filter(key => ['oral', 'asNeeded', 'external'].includes(key));
  const timesFilters = filters.filter(key => ['once', 'twice', 'three', 'fourMore'].includes(key));
  const drugType = typeof inferPrescriptionDrugType === 'function'
    ? inferPrescriptionDrugType(prescription)
    : '';

  let baseOptions = getDrugUsageOptions(prescription);
  if (routeFilters.includes('oral') || routeFilters.includes('asNeeded') || routeFilters.includes('external')) {
    baseOptions = uniquePrescriptionUsageOptions([
      ...baseOptions,
      ...(routeFilters.includes('oral') ? getExplicitOralUsageOptions(baseOptions) : []),
      ...(routeFilters.includes('asNeeded') ? getExplicitAsNeededUsageOptions(baseOptions) : []),
      ...(routeFilters.includes('external') ? getExplicitExternalUsageOptions(baseOptions) : [])
    ]);
  }
  if (drugType === '内服' || routeFilters.includes('oral')) {
    const explicitTimesOptions = timesFilters.flatMap(key => getExplicitOralUsageOptionsByTimes(key, baseOptions));
    if (explicitTimesOptions.length) {
      baseOptions = uniquePrescriptionUsageOptions([
        ...baseOptions,
        ...explicitTimesOptions
      ]);
    }
  }

  return sortPrescriptionUsageOptions(baseOptions.filter(option => {
    const lower = String(option || '').toLowerCase();
    if (query && !lower.includes(query)) return false;
    const routeOk = routeFilters.length === 0 || routeFilters.some(key => getPrescriptionUsageFilterMatch(option, key));
    const timesOk = timesFilters.length === 0 || timesFilters.some(key => getPrescriptionUsageFilterMatch(option, key));
    return routeOk && timesOk;
  }));
}

function ensurePrescriptionUsageDialog() {
  let dialog = document.getElementById('rx-usage-dialog');
  if (dialog) return dialog;

  dialog = document.createElement('div');
  dialog.id = 'rx-usage-dialog';
  dialog.className = 'rx-usage-dialog-overlay hidden';
  dialog.innerHTML = `
    <div class="rx-usage-dialog" role="dialog" aria-modal="true" aria-labelledby="rx-usage-dialog-title">
      <div class="rx-usage-dialog-header">
        <h3 id="rx-usage-dialog-title">用法</h3>
        <button type="button" class="rx-usage-dialog-close" title="閉じる" aria-label="閉じる">&times;</button>
      </div>
      <input id="rx-usage-search-input" class="rx-usage-search-input" type="search" placeholder="キーワードを入力してください" autocomplete="off">
      <div class="rx-usage-filter-row">
        ${PRESCRIPTION_USAGE_FILTERS.map(filter => `
          <label class="rx-usage-filter">
            <input type="checkbox" value="${filter.key}">
            <span>${filter.label}</span>
          </label>
        `).join('')}
      </div>
      <div id="rx-usage-option-list" class="rx-usage-option-list"></div>
    </div>
  `;

  dialog.querySelector('.rx-usage-dialog-close')?.addEventListener('click', closePrescriptionUsageDialog);
  dialog.addEventListener('click', event => {
    if (event.target === dialog) closePrescriptionUsageDialog();
  });
  dialog.querySelector('#rx-usage-search-input')?.addEventListener('input', event => {
    prescriptionUsageDialogState.query = event.target.value || '';
    renderPrescriptionUsageOptions();
  });
  dialog.querySelector('.rx-usage-filter-row')?.addEventListener('change', () => {
    prescriptionUsageDialogState.filters = Array.from(dialog.querySelectorAll('.rx-usage-filter input:checked')).map(input => input.value);
    renderPrescriptionUsageOptions();
  });
  dialog.querySelector('#rx-usage-option-list')?.addEventListener('click', event => {
    const option = event.target.closest('[data-rx-usage-option]');
    if (!option) return;
    selectPrescriptionUsageOption(option.dataset.rxUsageOption || '');
  });

  document.body.appendChild(dialog);
  return dialog;
}

function openPrescriptionUsageDialog(event, index) {
  event?.preventDefault();
  event?.stopPropagation();
  if (!pendingPrescriptions[index]) return;
  const dialog = ensurePrescriptionUsageDialog();
  prescriptionUsageDialogState = { index, query: '', filters: [] };
  const input = dialog.querySelector('#rx-usage-search-input');
  if (input) input.value = '';
  dialog.querySelectorAll('.rx-usage-filter input').forEach(checkbox => {
    checkbox.checked = false;
  });
  renderPrescriptionUsageOptions();
  dialog.classList.remove('hidden');
  input?.focus();
}

function closePrescriptionUsageDialog() {
  document.getElementById('rx-usage-dialog')?.classList.add('hidden');
  prescriptionUsageDialogState = { index: null, query: '', filters: [] };
}

function renderPrescriptionUsageOptions() {
  const dialog = ensurePrescriptionUsageDialog();
  const list = dialog.querySelector('#rx-usage-option-list');
  if (!list) return;
  const prescription = pendingPrescriptions[prescriptionUsageDialogState.index];
  const selected = prescription?.frequency || '';
  const options = getFilteredPrescriptionUsageOptions();

  if (!options.length) {
    list.innerHTML = '<div class="rx-usage-empty">該当する用法がありません</div>';
    return;
  }

  list.innerHTML = options.map(option => `
    <button type="button" class="rx-usage-option ${option === selected ? 'selected' : ''}" data-rx-usage-option="${escapeHtml(option)}">
      ${escapeHalfWidthNumericText(option)}
    </button>
  `).join('');
}

function selectPrescriptionUsageOption(value) {
  const index = prescriptionUsageDialogState.index;
  if (index === null || !value) return;
  updatePrescriptionProcedureItem(index, 'frequency', value);
  closePrescriptionUsageDialog();
}

window.openPrescriptionUsageDialog = openPrescriptionUsageDialog;
window.closePrescriptionUsageDialog = closePrescriptionUsageDialog;

function updatePrescriptionProcedureItem(index, field, value) {
  const prescription = pendingPrescriptions[index];
  if (!prescription) return;
  ensurePrescriptionIdentity(prescription);
  const groupId = getPrescriptionGroupId(prescription);

  if (field === 'dosage_quantity') {
    prescription.dosage_quantity = Number(value) || 1;
    prescription.dosage = `${prescription.dosage_quantity}${prescription.unit || prescription.dosage_unit || ''}`;
  } else if (field === 'days') {
    prescription.days = normalizePrescriptionDays({ ...prescription, days: value }, 1);
  } else if (field === 'dispensing_type') {
    prescription.dispensing_type = value;
    prescription.prescription_type = value;
  } else {
    prescription[field] = value;
  }

  prescription.drug_type = inferPrescriptionDrugType(prescription);

  prescription.total_quantity = calculatePrescriptionQuantity(
    prescription.dosage_quantity,
    prescription.frequency,
    prescription.days,
    prescription.drug_type
  );

  if (groupId && ['dispensing_type', 'frequency', 'days'].includes(field)) {
    pendingPrescriptions.forEach(member => {
      if (member === prescription || getPrescriptionGroupId(member) !== groupId) return;
      ensurePrescriptionIdentity(member);
      if (field === 'days') {
        member.days = normalizePrescriptionDays({ ...member, days: value }, 1);
      } else if (field === 'dispensing_type') {
        member.dispensing_type = value;
        member.prescription_type = value;
      } else {
        member[field] = value;
      }
      member.drug_type = inferPrescriptionDrugType(member);
      member.total_quantity = calculatePrescriptionQuantity(
        member.dosage_quantity,
        member.frequency,
        member.days,
        member.drug_type
      );
    });
    rememberPrescriptionGroupSuggestion(groupId, { bump: false });
  } else if (groupId) {
    rememberPrescriptionGroupSuggestion(groupId, { bump: false });
  }

  resetDrugWarningsForPrescriptionEdit();
  renderPendingPrescriptionsInProcedure();
  renderCurrentPrescriptions();
  updateTotalPoints();
  saveCurrentPatientBilling();
  checkPrescriptionsRealtime();
}

function deletePrescriptionProcedureItem(index) {
  const prescription = pendingPrescriptions[index];
  if (!prescription) return;

  const removedGroupId = getPrescriptionGroupId(prescription);
  const removedAnchorId = prescription.prescription_item_id;
  pendingPrescriptions.splice(index, 1);
  if (selectedPrescriptionGroupAnchorId === removedAnchorId) {
    selectedPrescriptionGroupAnchorId = null;
  }
  normalizePrescriptionGroupAfterChange(removedGroupId);
  resetDrugWarningsForPrescriptionEdit();
  renderPendingPrescriptionsInProcedure();
  renderCurrentPrescriptions();
  updateTotalPoints();
  saveCurrentPatientBilling();
  checkPrescriptionsRealtime();
  showToast(`${prescription.drug_name}を削除しました`, 'info');
}

function deletePrescriptionGroup(groupId) {
  const targetGroupId = String(groupId || '');
  if (!targetGroupId) return;

  const removed = [];
  for (let index = pendingPrescriptions.length - 1; index >= 0; index -= 1) {
    const prescription = pendingPrescriptions[index];
    if (getPrescriptionGroupId(prescription) !== targetGroupId) continue;
    removed.push(prescription);
    pendingPrescriptions.splice(index, 1);
  }

  if (!removed.length) return;
  if (removed.some(prescription => prescription.prescription_item_id === selectedPrescriptionGroupAnchorId)) {
    selectedPrescriptionGroupAnchorId = null;
  }

  resetDrugWarningsForPrescriptionEdit();
  renderPendingPrescriptionsInProcedure();
  renderCurrentPrescriptions();
  updateTotalPoints();
  saveCurrentPatientBilling();
  checkPrescriptionsRealtime();
  showToast(`${removed.length}件の薬を削除しました`, 'info');
}

