// 処方モーダルの初期化
function initPrescriptionModal() {
  const modal = document.getElementById('prescription-modal');
  if (!modal) return;

  // 閉じるボタン
  document.getElementById('prescription-modal-close')?.addEventListener('click', closePrescriptionModal);
  document.getElementById('btn-rx-cancel')?.addEventListener('click', closePrescriptionModal);

  // モーダル外クリックで閉じる
  modal.addEventListener('click', (e) => {
    if (e.target === modal) closePrescriptionModal();
  });

  // 薬剤追加ボタン
  document.getElementById('btn-add-drug')?.addEventListener('click', addDrugToPrescription);
  document.getElementById('btn-cancel-drug')?.addEventListener('click', hideDrugDetailPanel);

  // 保存ボタン
  document.getElementById('btn-rx-save')?.addEventListener('click', savePrescriptions);
  document.getElementById('prescription-remarks-input')?.addEventListener('input', () => {
    syncPrescriptionRemarksStateFromInput();
    saveCurrentPatientBilling();
  });
  document.getElementById('btn-rx-add-one-package-remark')?.addEventListener('click', () => {
    appendPrescriptionRemark(PRESCRIPTION_REMARK_ONE_PACKAGE_TEXT);
  });
  document.getElementById('rx-one-package')?.addEventListener('change', event => {
    setPrescriptionOnePackageRemarkEnabled(event.target.checked);
  });
  document.getElementById('karte-rx-one-package-remark')?.addEventListener('change', event => {
    setPrescriptionOnePackageRemarkEnabled(event.target.checked);
  });

  populateDrugFrequencySelect();
  refreshDrugFrequencyOptionsFromFacilityMaster()
    .then(() => calculateTotalQuantity())
    .catch(error => console.warn('用法マスタの読み込みに失敗しました:', error));

  // 用量・日数変更時に総量を再計算
  document.getElementById('drug-dosage')?.addEventListener('input', calculateTotalQuantity);
  document.getElementById('drug-days')?.addEventListener('input', calculateTotalQuantity);
  document.getElementById('drug-frequency')?.addEventListener('change', calculateTotalQuantity);

  // 薬剤検索の初期化
  initDrugSearch();

  // 履歴トグル
  document.getElementById('toggle-rx-history')?.addEventListener('click', () => {
    const list = document.getElementById('prescription-history-list');
    list.classList.toggle('collapsed');
  });
}

