let currentOrderCategory = 'exam'; // 現在選択中のカテゴリ
let orderZoneEntryVersion = 0;
let orderCategories = {}; // カテゴリ別の診療行為リスト
let actionSets = []; // セット一覧
let karteSets = []; // カルテ本文・算定・処方を含むセット一覧
let selectedActions = []; // 選択された診療行為
let selectedProcedureGroupAnchorId = null;
