function renderDrugList(drugs) {
  const container = document.getElementById('category-tree');
  if (!container) return;

  currentDrugOrderList = drugs
    .map(drug => normalizeDrugForOrder(drug))
    .filter(drug => drug.name)
    .sort(compareDrugOrder);

  if (currentDrugOrderList.length === 0) {
    container.innerHTML = '<div class="no-data">該当する薬剤がありません</div>';
    return;
  }

  const groupSuggestionsHtml = renderProcedureGroupSuggestionRows(
    getPrescriptionGroupSuggestionsForDrugs(currentDrugOrderList)
  );

  container.innerHTML = `
    <div class="m3-drug-list">
      ${groupSuggestionsHtml}
      ${currentDrugOrderList.map((drug, index) => `
        <div class="m3-drug-item ${drug.commonPreset ? 'frequent' : ''}" data-drug-index="${index}" onclick="selectDrugFromOrderIndex(${index})">
          <span class="m3-drug-icon">薬</span>
          <span class="m3-drug-text">
            <span class="m3-drug-name">${escapeHtml(formatDrugListName(drug))}</span>
            <span class="m3-drug-default">${escapeHtml(formatDrugUsageLine(drug))}</span>
          </span>
        </div>
      `).join('')}
    </div>
  `;
}

function normalizeDrugForOrder(drug, forcedPreset = null) {
  const name = drug.name || drug.drug_name || '';
  const code = drug.drug_code || drug.code || drug.yj_code || drug.hot_code || '';
  const commonPreset = forcedPreset || drug.commonPreset || getDrugCommonPreset(name);
  return {
    ...drug,
    id: drug.id || code || name,
    code,
    drug_code: code,
    name,
    category: drug.category || inferDrugCategory(name),
    unit: drug.unit || commonPreset?.unit || inferDrugUnit(name),
    price: drug.price ?? drug.drug_price ?? null,
    commonPreset
  };
}

function getDrugCommonPreset(name) {
  return commonDrugPresets.find(preset => preset.pattern.test(name)) || null;
}

function compareDrugOrder(a, b) {
  const rankA = a.commonPreset ? a.commonPreset.rank : 9999;
  const rankB = b.commonPreset ? b.commonPreset.rank : 9999;
  if (rankA !== rankB) return rankA - rankB;
  return a.name.localeCompare(b.name, 'ja');
}

function comparePresetDrugCandidate(a, b, preset) {
  const aSelected = /（選）|\(選\)/.test(a.name) ? 1 : 0;
  const bSelected = /（選）|\(選\)/.test(b.name) ? 1 : 0;
  if (aSelected !== bSelected) return aSelected - bSelected;

  const aPreferred = preset.prefer && preset.prefer.test(a.name) ? 0 : 1;
  const bPreferred = preset.prefer && preset.prefer.test(b.name) ? 0 : 1;
  if (aPreferred !== bPreferred) return aPreferred - bPreferred;

  return a.name.length - b.name.length || a.name.localeCompare(b.name, 'ja');
}

function getDrugPrescriptionDefaults(drug) {
  const preset = drug.commonPreset;
  const quantity = preset?.quantity ?? 1;
  const unit = preset?.unit || (drug.unit && drug.unit !== '-' ? drug.unit : '');
  const frequency = preset?.frequency || getDefaultDrugUsage(drug);
  const days = normalizePrescriptionDays({ ...drug, frequency, unit, days: preset?.days });
  const dispensingType = preset?.dispensing_type || '院外';

  return { quantity, unit, frequency, days, dispensingType };
}

function formatDrugListName(drug) {
  const defaults = getDrugPrescriptionDefaults(drug);
  const dose = formatPrescriptionDoseForList({
    dosage_quantity: defaults.quantity,
    unit: defaults.unit
  });
  return formatHalfWidthNumericText([drug.name, dose].filter(Boolean).join(' '));
}

function formatDrugUsageLine(drug) {
  const defaults = getDrugPrescriptionDefaults(drug);
  return formatHalfWidthNumericText(`${defaults.dispensingType} ${defaults.frequency} ${formatPrescriptionDuration(defaults.days, defaults.frequency)}`);
}

function inferDrugCategory(name) {
  if (/(注|点滴|静注|筋注|皮下注|注射)/.test(name)) return '注射';
  if (/(テープ|パップ|ゲル|軟膏|クリーム|ローション|外用|点眼|点鼻|吸入|坐剤|坐薬|貼付)/.test(name)) return '外用';
  if (/(錠|カプセル|Cap|散|細粒|顆粒|ドライシロップ|シロップ|内用液|経口|丸|末)/.test(name)) return '内服';
  return 'その他';
}

function inferDrugUnit(name) {
  if (/(カプセル|Cap)/.test(name)) return 'Cap';
  if (/錠/.test(name)) return '錠';
  if (/(散|細粒|顆粒|ドライシロップ|シロップ|軟膏|クリーム|ゲル|ローション)/.test(name)) return 'g';
  if (/(テープ|パップ|貼付)/.test(name)) return '枚';
  if (/(点眼|点鼻|注|点滴|内用液)/.test(name)) return 'mL';
  if (/(坐剤|坐薬)/.test(name)) return '個';
  return '-';
}

// 薬剤カテゴリのアイコン
function getCategoryDrugIcon(category) {
  const icons = {
    '内服': '内',
    '外用': '外',
    '注射': '注',
    'その他': '他'
  };
  return icons[category] || '薬';
}

// 薬剤カテゴリの開閉
function toggleDrugCategory(header) {
  const items = header.nextElementSibling;
  const icon = header.querySelector('i');

  if (items.style.display === 'none') {
    items.style.display = 'block';
    icon.className = 'fas fa-chevron-down';
  } else {
    items.style.display = 'none';
    icon.className = 'fas fa-chevron-right';
  }
}

// オーダーゾーンから薬剤を選択（処方追加）
function selectDrugFromOrderIndex(index) {
  const drug = currentDrugOrderList[index];
  if (!drug) return;
  selectDrugFromOrder(drug);
}

function selectDrugFromOrder(drug) {
  const normalizedDrug = normalizeDrugForOrder(drug);
  const prescription = createPrescriptionFromDrug(normalizedDrug);
  const { added } = addPrescriptionToPending(prescription, { checkDuplicate: true });
  if (!added) return;

  renderSelectedActionsInProcedure();
  updateTotalPoints();
  saveCurrentPatientBilling();
  showToast(`${normalizedDrug.name}を追加しました`, 'success');

  // 処方チェック（相互作用・投与日数）を実行
  checkPrescriptionsRealtime();
}

function createPrescriptionFromDrug(drug) {
  const defaults = getDrugPrescriptionDefaults(drug);
  const quantity = defaults.quantity;
  const days = defaults.days;
  const frequency = defaults.frequency;
  const unit = defaults.unit;
  const totalQuantity = calculatePrescriptionQuantity(
    quantity, frequency, days, inferPrescriptionDrugType({ ...drug, frequency, unit })
  );
  const unitPrice = getPrescriptionUnitPrice(drug);
  const genericChangeAllowed = readOptionalBooleanFlag(drug, ['generic_change_allowed', 'genericChangeAllowed']);
  const longTermListed = readOptionalBooleanFlag(drug, [
    'long_term_listed',
    'longTermListed',
    'long_term_listed_drug',
    'is_long_term_listed'
  ]);

  return {
    item_type: 'drug',
    drug_name: drug.name,
    drug_code: (drug.drug_code || drug.code || drug.id || '').toString(),
    yj_code: drug.yj_code || drug.yjCode || '',
    hot_code: drug.hot_code || drug.hotCode || '',
    receipt_code: drug.receipt_code || drug.receiptCode || '',
    dosage_quantity: quantity,
    dosage: `${quantity}${unit}`,
    unit,
    dosage_unit: unit,
    frequency,
    days,
    total_quantity: totalQuantity,
    unit_price: unitPrice > 0 ? unitPrice : null,
    drug_price: unitPrice > 0 ? unitPrice : null,
    price: unitPrice > 0 ? unitPrice : null,
    total_price: unitPrice > 0 ? unitPrice * totalQuantity : null,
    dispensing_type: defaults.dispensingType,
    drug_type: inferPrescriptionDrugType({
      ...drug,
      drug_name: drug.name,
      frequency,
      unit
    }),
    is_generic: !!drug.is_generic,
    generic_name: drug.generic_name || drug.genericName || '',
    generic_class: drug.generic_class || drug.genericClass || drug.generic_type || drug.genericType || '',
    generic_prescription_code: drug.generic_prescription_code || drug.genericPrescriptionCode || '',
    generic_prescription_name: drug.generic_prescription_name || drug.genericPrescriptionName || '',
    generic_prescription_addition_category: drug.generic_prescription_addition_category || drug.genericPrescriptionAdditionCategory || '',
    generic_prescription_lowest_price: drug.generic_prescription_lowest_price ?? drug.genericPrescriptionLowestPrice ?? '',
    generic_prescription_master_note: drug.generic_prescription_master_note || drug.genericPrescriptionMasterNote || '',
    generic_prescription_master_version: drug.generic_prescription_master_version || drug.genericPrescriptionMasterVersion || '',
    manufacturer: drug.manufacturer || drug.maker || drug.maker_name || '',
    distributor: drug.distributor || '',
    dosage_form: drug.dosage_form || drug.dosageForm || '',
    therapeutic_category: drug.therapeutic_category || drug.therapeuticCategory || '',
    therapeutic_name: drug.therapeutic_name || drug.therapeuticName || '',
    efficacy_effect: drug.efficacy_effect || drug.efficacyEffects || drug.efficacy || drug.effect || '',
    usage_dosage: drug.usage_dosage || drug.usageDosage || drug.dosage_usage || drug.dosageUsage || '',
    side_effects: drug.side_effects || drug.sideEffects || drug.adverse_reactions || drug.adverseReactions || '',
    application_precautions: drug.application_precautions || drug.applicationPrecautions || drug.precautions || '',
    detail_info: drug.detail_info || drug.detailInfo || drug.drug_information || drug.drugInformation || '',
    drug_information_source: drug.drug_information_source || drug.drugInformationSource || '',
    drug_information_updated_at: drug.drug_information_updated_at || drug.drugInformationUpdatedAt || '',
    is_narcotic: Boolean(drug.is_narcotic || drug.isNarcotic),
    is_psychotropic: Boolean(drug.is_psychotropic || drug.isPsychotropic),
    effective_date: drug.effective_date || drug.effectiveDate || '',
    expiry_date: drug.expiry_date || drug.expiryDate || '',
    long_term_listed: Boolean(longTermListed),
    long_term_patient_choice: false,
    generic_change_allowed: genericChangeAllowed === null ? true : genericChangeAllowed,
    generic_change_reason: drug.generic_change_reason || drug.genericChangeReason || '',
    requires_comment: Boolean(drug.requires_comment || drug.comment_required || drug.selectable_comment_required),
    comment_required: Boolean(drug.comment_required || drug.requires_comment || drug.selectable_comment_required),
    selectable_comment_required: Boolean(drug.selectable_comment_required || drug.comment_required || drug.requires_comment),
    is_temporary: false,
    refill_allowed: false,
    is_refill: false,
    refill_count: null,
    instructions: ''
  };
}

function getDefaultDrugUsage(drug) {
  const name = drug.name || '';
  if (/(テープ|パップ|ゲル|軟膏|クリーム|ローション|点眼|点鼻|吸入|坐剤|坐薬|貼付)/.test(name)) {
    return getPreferredDrugUsageDefault(drug, '[外] 1日2回');
  }
  if (/(注|点滴|静注|筋注|皮下注|注射)/.test(name)) {
    return getPreferredDrugUsageDefault(drug, '[注] 医師の指示通り');
  }
  return getPreferredDrugUsageDefault(drug, '[内] 1日3回毎食後');
}

function getPrescriptionInputQuantity(prescription) {
  const total = Number(prescription.total_quantity ?? prescription.totalQuantity);
  const savedTopicalTotal = inferPrescriptionDrugType(prescription) === '外用'
    && Number.isFinite(total) && total > 0 ? total : null;
  return Number(prescription.dosage_quantity || prescription.quantity || savedTopicalTotal || parseFloat(prescription.dosage));
}

function normalizePrescriptionDays(prescription, fallback = 7) {
  const days = Number(prescription.days);
  if (inferPrescriptionDrugType(prescription) === '外用') {
    return Number.isFinite(days) && days > 0 ? days : null;
  }
  return days || fallback;
}

function calculatePrescriptionQuantity(quantity, frequency, days, drugType = null) {
  const dose = Number(quantity) || 1;
  // Topical quantity is the total supplied, independent of application frequency/duration.
  if (drugType === '外用') return dose;
  const dayCount = Number(days) || 1;
  if (isAsNeededPrescriptionFrequency(frequency)) {
    return dose * dayCount;
  }
  return dose * getPrescriptionTimesPerDay(frequency) * dayCount;
}

window.toggleDrugCategory = toggleDrugCategory;
window.selectDrugFromOrderIndex = selectDrugFromOrderIndex;
window.selectDrugFromOrder = selectDrugFromOrder;

// カテゴリ別に診療行為を取得
async function loadMedicalActionsByCategory(category) {
  const entryVersion = orderZoneEntryVersion;
  const container = document.getElementById('category-tree');
  if (!container) return;

  container.innerHTML = '<div class="loading"><i class="fas fa-spinner fa-spin"></i> 読み込み中...</div>';

  try {
    const result = await RecordActionAPI.search('', category, 100);
    if (entryVersion !== orderZoneEntryVersion) return;
    const actions = getActionsFromResult(result, category);

    if (actions.length === 0) {
      container.innerHTML = '<div class="no-data">該当する診療行為がありません</div>';
      return;
    }

    renderMedicalActions(actions, category);

  } catch (error) {
    console.error('診療行為取得エラー:', error);
    if (entryVersion !== orderZoneEntryVersion) return;
    container.innerHTML = '<div class="no-data">診療行為マスターの読み込みに失敗しました</div>';
  }
}

// 診療行為を表示
function renderMedicalActions(actions, fallbackCategory = currentOrderCategory) {
  const container = document.getElementById('category-tree');
  if (!container) return;

  const normalizedActions = actions.map(rawAction => normalizeOrderAction(rawAction, fallbackCategory));
  const groupSuggestionsHtml = renderProcedureGroupSuggestionRows(
    getBillingGroupSuggestionsForActions(normalizedActions, fallbackCategory)
  );

  container.innerHTML = `
    <div class="m3-order-list">
      ${groupSuggestionsHtml}
      ${normalizedActions.map(action => {
        const pointsText = formatOrderActionPoints(action);
        return `
        <div class="m3-order-item"
             data-code="${action.code}"
             onclick="addMedicalActionToRecord(${JSON.stringify(action).replace(/"/g, '&quot;')})">
          <span class="m3-order-icon ${getProcedureIconClass(action.category)}">${getCategoryIcon(action.category)}</span>
          <span class="m3-order-text">
            <span class="m3-order-name">${escapeHalfWidthNumericText(action.name)}</span>
            <span class="m3-order-points">${pointsText}</span>
          </span>
        </div>
      `;
      }).join('')}
    </div>
  `;
}

function createProcedureActionId() {
  return `proc_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
}

function ensureProcedureActionIdentity(action) {
  if (!action) return null;
  action.procedure_item_id = action.procedure_item_id || action.procedureItemId || action.local_id || createProcedureActionId();
  action.procedureItemId = action.procedure_item_id;
  return action;
}

function getSelectedProcedureGroupAnchor() {
  if (!selectedProcedureGroupAnchorId) return null;
  const anchor = selectedActions.find(action => action.procedure_item_id === selectedProcedureGroupAnchorId);
  if (!anchor) selectedProcedureGroupAnchorId = null;
  return anchor || null;
}

function getProcedureSelectionKey(action) {
  ensureProcedureActionIdentity(action);
  const groupId = getManualBillingGroupId(action);
  return groupId ? `manual:${groupId}` : `single:${action.procedure_item_id}`;
}

function getSelectedProcedureSelectionKey() {
  const anchor = getSelectedProcedureGroupAnchor();
  return anchor ? getProcedureSelectionKey(anchor) : '';
}

function getManualBillingGroupId(action) {
  return action?.billing_group_id || action?.billingGroupId || '';
}

function getManualBillingGroupLabel(action) {
  return action?.billing_group_label || action?.billingGroupLabel || '';
}

function isManualBillingGroupChild(action) {
  return Boolean(action?.billing_group_parent_id || action?.billingGroupParentId);
}

function assignActionToSelectedProcedureGroup(action) {
  const anchor = getSelectedProcedureGroupAnchor();
  if (!anchor || anchor === action) return false;

  ensureProcedureActionIdentity(anchor);
  ensureProcedureActionIdentity(action);
  const groupId = getManualBillingGroupId(anchor) || `manual_${anchor.procedure_item_id}`;
  const groupLabel = getManualBillingGroupLabel(anchor) || anchor.name || '算定';

  anchor.billing_group_id = groupId;
  anchor.billingGroupId = groupId;
  anchor.billing_group_parent_id = '';
  anchor.billingGroupParentId = '';
  anchor.billing_group_label = groupLabel;
  anchor.billingGroupLabel = groupLabel;

  action.billing_group_id = groupId;
  action.billingGroupId = groupId;
  action.billing_group_parent_id = anchor.procedure_item_id;
  action.billingGroupParentId = anchor.procedure_item_id;
  action.billing_group_label = groupLabel;
  action.billingGroupLabel = groupLabel;
  return true;
}

function addActionToSelectedActions(action, options = {}) {
  assignMissingProcedureEntryOrdersFromDom();
  const normalized = ensureProcedureActionIdentity(normalizeOrderAction(action));
  const exists = selectedActions.some(a => (a.code || a.name) === (normalized.code || normalized.name));
  if (exists) {
    if (options.showDuplicateToast !== false) {
      showToast(`${normalized.name}は既に追加されています`, 'info');
    }
    return false;
  }

  const grouped = options.assignToSelectedGroup === false
    ? false
    : assignActionToSelectedProcedureGroup(normalized);
  assignProcedureEntryOrderForAppend(normalized);
  selectedActions.push(normalized);
  if (grouped) rememberBillingGroupSuggestion(getManualBillingGroupId(normalized));
  if (options.showToast !== false) {
    showToast(`${normalized.name}を追加しました`, 'success');
  }
  return true;
}

// 診療行為をカルテに追加（クリックで即追加）
function addMedicalActionToRecord(action, options = {}) {
  if (!addActionToSelectedActions(action, { showToast: false, ...options })) {
    return;
  }

  renderSelectedActionsInProcedure();
  updateTotalPoints();
  saveCurrentPatientBilling();

  // リアルタイム算定チェックを実行
  checkActionsRealtime();
}

window.addMedicalActionToRecord = addMedicalActionToRecord;

// ====================================
// リアルタイム算定チェック
// ====================================
let calculationWarnings = [];
let lastCheckTimestamp = 0;
let calculationCheckRequestId = 0;
const CHECK_DEBOUNCE_MS = 500;

async function checkActionsRealtime() {
  const requestId = ++calculationCheckRequestId;
  if (!currentPatient || selectedActions.length === 0) {
    clearCalculationWarningPanel();
    return;
  }

  // デバウンス: 連続追加時に毎回チェックしない
  const now = Date.now();
  if (now - lastCheckTimestamp < CHECK_DEBOUNCE_MS) {
    clearTimeout(window._checkActionsTimeout);
    window._checkActionsTimeout = setTimeout(() => {
      if (requestId === calculationCheckRequestId) {
        checkActionsRealtime();
      }
    }, CHECK_DEBOUNCE_MS);
    return;
  }
  lastCheckTimestamp = now;

  try {
    const billableActions = buildActionAutoCalculationPayloads();
    const actionCodes = billableActions
      .map(a => a.code)
      .filter(Boolean);
    const prescriptionPayloads = buildPrescriptionAutoCalculationPayloads();

    if (actionCodes.length === 0 && billableActions.length === 0 && prescriptionPayloads.length === 0) {
      clearCalculationWarningPanel();
      return;
    }

    const diagnoses = String(currentPatientDiagnosesPatientId || '') === String(currentPatient.id || '')
      ? currentPatientDiagnoses
      : [];

    const result = await CalculationsAPI.checkRealtime({
      patient_id: currentPatient.id,
      record_id: currentRecordId || null,
      action_codes: actionCodes,
      actions: billableActions,
      prescriptions: prescriptionPayloads,
      diagnoses: (diagnoses || []).map(diagnosis => ({
        diagnosis_name: diagnosis.diagnosis_name || diagnosis.name || '',
        full_name: diagnosis.full_name || diagnosis.display_name || diagnosis.name || '',
        start_date: normalizeKarteDateValue(diagnosis.start_date || diagnosis.diagnosis_date || ''),
        diagnosis_date: normalizeKarteDateValue(diagnosis.diagnosis_date || diagnosis.start_date || ''),
        is_suspected: Boolean(diagnosis.is_suspected),
        is_deleted: Boolean(diagnosis.is_deleted)
      })),
      birth_date: currentPatient.birth_date,
      gender: currentPatient.gender,
      body_weight_kg: getCurrentPrescriptionAuditWeightKg(),
      check_date: getCurrentKarteDateValue()
    });

    if (requestId !== calculationCheckRequestId) return;

    if (result.error_count > 0 || result.warning_count > 0) {
      calculationWarnings = result.results || [];
      showCalculationWarnings(calculationWarnings);
    } else {
      clearCalculationWarningPanel();
    }
  } catch (e) {
    if (requestId !== calculationCheckRequestId) return;
    console.warn('算定チェックエラー:', e);
    // チェックエラーでもUIには影響しない
  }
}

function showCalculationWarnings(warnings) {
  calculationWarnings = (warnings || []).filter(isActiveRealtimeWarning);
  const panel = document.getElementById('calculation-warnings');
  if (panel) panel.classList.add('hidden');
  renderSelectedActionsInProcedure();
}

function clearCalculationWarningPanel() {
  const hadWarnings = Array.isArray(calculationWarnings) && calculationWarnings.length > 0;
  calculationWarnings = [];
  clearTimeout(window._checkActionsTimeout);
  window._checkActionsTimeout = null;
  lastCheckTimestamp = 0;
  const panel = document.getElementById('calculation-warnings');
  if (panel) {
    panel.classList.add('hidden');
    const body = panel.querySelector('.warning-body');
    if (body) body.innerHTML = '';
  }
  if (hadWarnings && isKarteScreenVisible()) {
    renderSelectedActionsInProcedure();
  }
}

function resetCalculationWarningState() {
  calculationCheckRequestId += 1;
  clearCalculationWarningPanel();
}

function hideCalculationWarnings() {
  resetCalculationWarningState();
}

function createCalculationWarningPanel() {
  const panel = document.createElement('div');
  panel.id = 'calculation-warnings';
  panel.className = 'calculation-warning-panel hidden';
  panel.innerHTML = `
    <div class="warning-header">
      <i class="fas fa-exclamation-triangle"></i>
      <span>算定チェック警告</span>
      <button class="warning-close" onclick="hideCalculationWarnings()">&times;</button>
    </div>
    <div class="warning-body"></div>
  `;

  // カルテエリアの近くに挿入
  const procedureArea = document.querySelector('.procedure-section') ||
                        document.querySelector('.karte-content') ||
                        document.getElementById('main-screen');
  if (procedureArea) {
    procedureArea.insertBefore(panel, procedureArea.firstChild);
  } else {
    document.body.appendChild(panel);
  }

  return panel;
}

window.hideCalculationWarnings = hideCalculationWarnings;

// ====================================
// 処方チェック（相互作用・投与日数）
// ====================================
let drugWarnings = [];
let lastDrugCheckTimestamp = 0;
let drugCheckRequestId = 0;

function getCurrentPrescriptionAuditWeightKg() {
  const latestVitals = Array.isArray(currentVitalEntries) && currentVitalEntries.length
    ? currentVitalEntries[currentVitalEntries.length - 1]?.values
    : null;
  const sources = [
    currentRecordVitalSigns,
    latestVitals,
    currentPatient?.vital_signs,
    currentPatient?.vitalSigns,
    currentPatient?.vitals,
    currentPatient
  ];
  for (const source of sources) {
    const value = parseVitalNumber(pickVitalValue(source, ['weight', 'body_weight', 'bodyWeight', 'weight_kg', 'weightKg']));
    if (value !== null && value > 0) return value;
  }
  return null;
}

async function checkPrescriptionsRealtime() {
  const requestId = ++drugCheckRequestId;
  if (pendingPrescriptions.length === 0) {
    clearDrugWarningPanel();
    return;
  }

  // デバウンス
  const now = Date.now();
  if (now - lastDrugCheckTimestamp < CHECK_DEBOUNCE_MS) {
    clearTimeout(window._checkDrugsTimeout);
    window._checkDrugsTimeout = setTimeout(() => {
      if (requestId === drugCheckRequestId) {
        checkPrescriptionsRealtime();
      }
    }, CHECK_DEBOUNCE_MS);
    return;
  }
  lastDrugCheckTimestamp = now;

  const warnings = buildDispensingMixWarnings(pendingPrescriptions);

  try {
    // 薬剤コードを抽出
    const drugCodes = pendingPrescriptions
      .map(p => p.drug_code)
      .filter(Boolean);

    const prescriptionPayloads = buildPrescriptionAutoCalculationPayloads();
    const drugs = prescriptionPayloads.map(p => ({
      drug_code: p.drug_code || '',
      drug_name: p.drug_name || p.name || '',
      days: p.days || 1,
      dose_quantity: p.quantity || null,
      dose_unit: p.unit || '',
      frequency: p.frequency || '',
      therapeutic_category: p.therapeutic_category || '',
      therapeutic_category_code: p.therapeutic_category_code || ''
    }));
    const billableActions = buildActionAutoCalculationPayloads();
    const actionCodes = billableActions
      .map(action => action.code)
      .filter(Boolean);

    // 相互作用チェック（2剤以上）と患者副作用等チェック（1剤から）
    if (drugCodes.length >= 2 || currentPatient?.id) {
      const interactions = await CalculationsAPI.checkDrugInteraction(drugCodes, {
        patient_id: currentPatient?.id || null,
        drugs
      });
      if (interactions && interactions.length > 0) {
        warnings.push(...interactions.map(i => ({
          type: i.category || i.type || 'interaction',
          ...i
        })));
      }
    }

    // 投与日数チェック
    const durationResults = await CalculationsAPI.checkDrugDuration(drugs);
    if (durationResults && durationResults.length > 0) {
      warnings.push(...durationResults.map(d => ({
        type: 'duration',
        ...d
      })));
    }

    if (typeof CalculationsAPI !== 'undefined' && CalculationsAPI.checkRealtime) {
      const diagnoses = String(currentPatientDiagnosesPatientId || '') === String(currentPatient?.id || '')
        ? currentPatientDiagnoses
        : [];
      const realtimeResult = await CalculationsAPI.checkRealtime({
        patient_id: currentPatient?.id || null,
        record_id: currentRecordId || null,
        action_codes: actionCodes,
        actions: billableActions,
        prescriptions: prescriptionPayloads,
        diagnoses: (diagnoses || []).map(diagnosis => ({
          diagnosis_name: diagnosis.diagnosis_name || diagnosis.name || '',
          full_name: diagnosis.full_name || diagnosis.display_name || diagnosis.name || '',
          start_date: normalizeKarteDateValue(diagnosis.start_date || diagnosis.diagnosis_date || ''),
          diagnosis_date: normalizeKarteDateValue(diagnosis.diagnosis_date || diagnosis.start_date || ''),
          is_suspected: Boolean(diagnosis.is_suspected),
          is_deleted: Boolean(diagnosis.is_deleted)
        })),
        birth_date: currentPatient?.birth_date || currentPatient?.birth || null,
        gender: currentPatient?.gender || '',
        body_weight_kg: getCurrentPrescriptionAuditWeightKg(),
        check_date: getCurrentKarteDateValue()
      });
      const realtimeWarnings = (realtimeResult?.results || [])
        .filter(isActiveRealtimeWarning)
        .filter(warning => warning.rule_code !== 'REALTIME_DISPENSING_MIX')
        .map(warning => ({
          type: warning.category || warning.type || 'comment',
          ...warning
        }));
      warnings.push(...realtimeWarnings);
    }

    if (requestId !== drugCheckRequestId) return;

    if (warnings.length > 0) {
      showDrugWarnings(warnings);
    } else {
      clearDrugWarningPanel();
    }
  } catch (e) {
    if (requestId !== drugCheckRequestId) return;
    console.warn('処方チェックエラー:', e);

    if (warnings.length > 0) {
      showDrugWarnings(warnings);
    } else {
      clearDrugWarningPanel();
    }
  }
}

function showDrugWarnings(warnings) {
  drugWarnings = (warnings || []).filter(isActiveRealtimeWarning);
  const panel = document.getElementById('drug-warnings');
  if (panel) panel.classList.add('hidden');
  renderPendingPrescriptionsInProcedure();
}

function clearDrugWarningPanel(options = {}) {
  const hadWarnings = Array.isArray(drugWarnings) && drugWarnings.length > 0;
  drugWarnings = [];
  clearTimeout(window._checkDrugsTimeout);
  window._checkDrugsTimeout = null;
  lastDrugCheckTimestamp = 0;
  const panel = document.getElementById('drug-warnings');
  if (panel) {
    panel.classList.add('hidden');
    const body = panel.querySelector('.warning-body');
    if (body) body.innerHTML = '';
  }
  if (options.render !== false && hadWarnings && isKarteScreenVisible()) {
    renderPendingPrescriptionsInProcedure();
  }
}

function resetDrugWarningsForPrescriptionEdit() {
  drugCheckRequestId += 1;
  clearDrugWarningPanel({ render: false });
}

function resetDrugWarningState() {
  drugCheckRequestId += 1;
  clearDrugWarningPanel();
}

function hideDrugWarnings() {
  resetDrugWarningState();
}

function createDrugWarningPanel() {
  const panel = document.createElement('div');
  panel.id = 'drug-warnings';
  panel.className = 'drug-warning-panel hidden';
  panel.innerHTML = `
    <div class="warning-header">
      <i class="fas fa-pills"></i>
      <span>処方チェック警告</span>
      <button class="warning-close" onclick="hideDrugWarnings()">&times;</button>
    </div>
    <div class="warning-body"></div>
  `;

  // 処方エリアの近くに挿入
  const prescriptionArea = document.querySelector('.prescription-section') ||
                          document.querySelector('.procedure-section') ||
                          document.getElementById('main-screen');
  if (prescriptionArea) {
    prescriptionArea.insertBefore(panel, prescriptionArea.firstChild);
  } else {
    document.body.appendChild(panel);
  }

  return panel;
}

window.hideDrugWarnings = hideDrugWarnings;

// カテゴリアイコンを取得
function getCategoryIcon(category) {
  const categoryLabel = normalizeOrderCategoryLabel(category);
  const icons = {
    '診察': '診',
    '投薬': '薬',
    '検査': '検',
    '処置': '処',
    '注射': '注',
    '画像': '画',
    '手術': '手',
    '麻酔': '麻',
    'リハビリ': 'リ',
    '在宅': '在',
    '自費': '自'
  };
  return icons[categoryLabel] || '他';
}

function getProcedureIconClass(category) {
  const categoryLabel = normalizeOrderCategoryLabel(category);
  if (categoryLabel === '診察') return 'blue';
  if (categoryLabel === '在宅') return 'home';
  if (categoryLabel === '投薬') return 'purple';
  if (categoryLabel === '検査') return 'lime';
  if (categoryLabel === '画像') return 'rose';
  if (categoryLabel === '注射') return 'green';
  if (categoryLabel === '処置') return 'cyan';
  if (categoryLabel === '手術') return 'yellow';
  if (categoryLabel === '麻酔') return 'orange';
  if (categoryLabel === '自費' || categoryLabel === 'その他') return 'pink';
  return '';
}

function getProcedureDisplayCategory(action) {
  if (/外来・在宅ベースアップ評価料/.test(action.name || '')) return 'その他';
  return action.category || 'その他';
}

function getActionClaimGroupKey(action, originalIndex = '') {
  const manualGroupId = getManualBillingGroupId(action);
  if (manualGroupId) return `manual:${manualGroupId}`;
  ensureProcedureActionIdentity(action);
  return `single:${action.procedure_item_id || originalIndex}`;
}

function getActionClaimGroupLabel(action) {
  const manualGroupLabel = getManualBillingGroupLabel(action);
  if (manualGroupLabel) return manualGroupLabel;
  if (/外来・在宅ベースアップ評価料/.test(action.name || '')) return 'その他';
  return action.name || action.category || 'その他';
}

function groupSelectedActionsForDisplay() {
  const grouped = [];
  const indexByKey = new Map();

  selectedActions.forEach((action, originalIndex) => {
    const key = getActionClaimGroupKey(action, originalIndex);
    let groupIndex = indexByKey.get(key);
    if (groupIndex === undefined) {
      groupIndex = grouped.length;
      indexByKey.set(key, groupIndex);
      grouped.push({
        key,
        label: getActionClaimGroupLabel(action),
        category: action.category || 'その他',
        isManual: Boolean(getManualBillingGroupId(action)),
        entryOrder: getProcedureEntrySortOrder(action, 'action', originalIndex),
        actions: []
      });
    }
    grouped[groupIndex].actions.push({ action, originalIndex });
    grouped[groupIndex].entryOrder = Math.min(
      grouped[groupIndex].entryOrder,
      getProcedureEntrySortOrder(action, 'action', originalIndex)
    );
  });

  grouped.forEach(group => {
    if (!group.isManual) return;
    group.actions.sort((left, right) => left.originalIndex - right.originalIndex);
  });

  return grouped.sort((left, right) => left.entryOrder - right.entryOrder);
}

function getProcedureActionTag(action) {
  if (action.category === '検査' || action.category === '画像') return '診療行為';
  return '';
}

function shouldShowProcedureQuantityFooter(group) {
  return group.isManual && group.actions.length > 1;
}

function renderProcedureRowMoveButtons(originalIndex, rowIndex, rowCount) {
  return '';
}

const PROCEDURE_COMMENT_POSITION_LABELS = {
  summary: '摘要欄内',
  top: '上部',
  bottom: '下部'
};

const PRESCRIPTION_COMMENT_REMARK_LABEL = '処方箋備考';
const PROCEDURE_FREE_COMMENT_TEMPLATE = 'フリーコメント';
const PROCEDURE_KARTE_COMMENT_TEMPLATE = 'カルテコメント';
const DIGIKAR_COMMENT_APPEND_ERROR_CODE = 'RC0002';
const PRESCRIPTION_USAGE_COMMENT_TEMPLATES = [
  '用法コメント(電子処方箋)',
  '頓用の条件指定',
  '投与タイミング',
  '投与時刻',
  '投与間隔',
  '部位',
  '部位(左・右・両)'
];
const PRESCRIPTION_COMMENT_TOP_TEMPLATES = [
  PROCEDURE_FREE_COMMENT_TEMPLATE,
  ...PRESCRIPTION_USAGE_COMMENT_TEMPLATES,
  PROCEDURE_KARTE_COMMENT_TEMPLATE
];

function normalizeReceiptPosition(position) {
  return Object.prototype.hasOwnProperty.call(PROCEDURE_COMMENT_POSITION_LABELS, position) ? position : 'summary';
}

function splitProcedureTextComment(value) {
  const text = String(value || '').trim();
  const templatePattern = PRESCRIPTION_COMMENT_TOP_TEMPLATES.map(escapeRegExp).join('|');
  const match = text.match(new RegExp(`^(${templatePattern})[:：]\\s*([\\s\\S]*)$`));
  return match ? { template: match[1], freeText: match[2] || '' } : { template: '', freeText: '' };
}

function splitReceiptCommentAppendTemplate(value) {
  const text = normalizeCommentMasterTemplate(value);
  const match = text.match(/^(.+?)[;；]\s*(.*)$/);
  if (!match) return { fixedText: text, appendGuide: '', hasSeparator: false };
  return {
    fixedText: normalizeCommentMasterTemplate(match[1]),
    appendGuide: normalizeCommentMasterTemplate(match[2]),
    hasSeparator: true
  };
}

function looksLikeReceiptCommentPlaceholderText(value) {
  const text = normalizeCommentMasterTemplate(value);
  const normalizedText = text.normalize('NFKC');
  if (!text) return true;
  return /[*＊]{2,}/.test(text)
    || /\b(?:yy|mm|dd|hh)\b/i.test(normalizedText)
    || text.includes('（元号）')
    || text.includes('(元号)')
    || text.includes('"年"')
    || text.includes('"月"')
    || text.includes('"日"');
}

function isReceiptCommentAppendTemplateText(value) {
  const parts = splitReceiptCommentAppendTemplate(value);
  return Boolean(parts.fixedText && parts.hasSeparator);
}

function findReceiptCommentAppendMasterRow(comment) {
  const rows = Array.isArray(facilityCommentMasterRows) ? facilityCommentMasterRows : [];
  const code = String(comment?.code || comment?.comment_code || '').trim();
  if (code) {
    const rowByCode = rows.find(row =>
      String(row.code || '').trim() === code
      && isReceiptCommentAppendTemplateText(row.template)
    );
    if (rowByCode) return rowByCode;
  }

  const template = normalizeCommentMasterTemplate(comment?.template || comment?.comment_template || '');
  if (isReceiptCommentAppendTemplateText(template)) {
    return { code, template };
  }

  const name = normalizeCommentMasterTemplate(comment?.name || comment?.comment_name || template);
  if (!name) return null;
  return rows.find(row => {
    if (!isReceiptCommentAppendTemplateText(row.template)) return false;
    const label = splitReceiptCommentAppendTemplate(row.template).fixedText;
    return name === label
      || name.startsWith(`${label}：`)
      || name.startsWith(`${label}:`)
      || template === label
      || template.startsWith(`${label}：`)
      || template.startsWith(`${label}:`);
  }) || null;
}

function getReceiptCommentAppendParts(comment) {
  const template = normalizeCommentMasterTemplate(comment?.template || comment?.comment_template || '');
  if (isReceiptCommentAppendTemplateText(template)) {
    return splitReceiptCommentAppendTemplate(template);
  }

  const masterRow = findReceiptCommentAppendMasterRow(comment);
  if (masterRow) {
    return splitReceiptCommentAppendTemplate(masterRow.template);
  }

  const fallback = normalizeCommentMasterTemplate(comment?.name || comment?.comment_name || template || '');
  return {
    fixedText: fallback,
    appendGuide: '',
    hasSeparator: false
  };
}

function isReceiptCommentAppendTemplate(comment) {
  if (!comment || ['free', 'karte'].includes(getProcedureCommentKind(comment))) return false;
  return Boolean(findReceiptCommentAppendMasterRow(comment));
}

function getReceiptCommentAppendLabel(comment) {
  const parts = getReceiptCommentAppendParts(comment);
  return parts.fixedText || normalizeCommentMasterTemplate(comment?.name || comment?.comment_name || comment?.template || '');
}

function getReceiptCommentAppendedText(comment) {
  const explicitText = getCommentFreeText(comment);
  if (explicitText) return explicitText;

  const label = getReceiptCommentAppendLabel(comment);
  const name = normalizeCommentMasterTemplate(comment?.name || comment?.comment_name || '');
  if (label && name.startsWith(label)) {
    return normalizeCommentMasterTemplate(name.slice(label.length).replace(/^[:：;；]\s*/, ''));
  }
  return '';
}

function looksLikeReceiptCommentPlaceholder(value, comment = null) {
  const text = normalizeCommentMasterTemplate(value);
  if (!text) return true;
  const appendGuide = getReceiptCommentAppendParts(comment).appendGuide;
  if (appendGuide && text === appendGuide) return true;
  return looksLikeReceiptCommentPlaceholderText(text);
}

function normalizeProcedureCommentKind(kind) {
  const value = String(kind || '').trim().toLowerCase();
  if (['karte', 'chart', 'medical_record', 'カルテ', 'カルテコメント'].includes(value)) return 'karte';
  if (['free', 'receipt_free', 'free_comment', 'フリー', 'フリーコメント'].includes(value)) return 'free';
  if (['receipt', 'claim', 'レセプト', '摘要'].includes(value)) return 'receipt';
  return '';
}

function inferProcedureCommentKind(template, name = '') {
  const templateText = String(template || '').trim();
  const nameText = String(name || '').trim();
  if (
    templateText === PROCEDURE_KARTE_COMMENT_TEMPLATE
    || nameText === PROCEDURE_KARTE_COMMENT_TEMPLATE
    || nameText.startsWith(`${PROCEDURE_KARTE_COMMENT_TEMPLATE}：`)
    || nameText.startsWith(`${PROCEDURE_KARTE_COMMENT_TEMPLATE}:`)
  ) return 'karte';
  if (
    templateText === PROCEDURE_FREE_COMMENT_TEMPLATE
    || nameText === PROCEDURE_FREE_COMMENT_TEMPLATE
    || nameText.startsWith(`${PROCEDURE_FREE_COMMENT_TEMPLATE}：`)
    || nameText.startsWith(`${PROCEDURE_FREE_COMMENT_TEMPLATE}:`)
  ) return 'free';
  return 'receipt';
}

function getProcedureCommentKind(comment) {
  const inferred = inferProcedureCommentKind(
    comment?.template || comment?.comment_template || '',
    comment?.name || comment?.comment_name || ''
  );
  if (inferred === 'karte' || inferred === 'free') return inferred;

  const explicit = normalizeProcedureCommentKind(comment?.commentKind || comment?.comment_kind || comment?.kind);
  if (explicit) return explicit;
  return inferred;
}

function isProcedureTextCommentTemplate(name) {
  return PRESCRIPTION_COMMENT_TOP_TEMPLATES.includes(normalizeCommentMasterTemplate(name));
}

function isProcedureFreeInputPlaceholder(name) {
  return normalizeCommentMasterTemplate(name) === 'コメント';
}

function isKarteProcedureComment(comment) {
  return getProcedureCommentKind(comment) === 'karte';
}

function isPrescriptionRemarkOnlyComment(comment) {
  return Boolean(
    comment?.printToPrescriptionRemarks
    || comment?.print_to_prescription_remarks
    || comment?.prescriptionRemark
    || comment?.prescription_remark
    || comment?.prescription_remarks
  );
}

function isGenericNamePrescriptionComment(comment) {
  const code = String(comment?.code || comment?.comment_code || '').trim();
  const template = normalizeCommentMasterTemplate(
    comment?.template || comment?.comment_template || comment?.name || comment?.comment_name || ''
  );
  return code === '099209908' || template === '一般名記載';
}

function getClaimProcedureComments(comments) {
  return getEnteredProcedureComments(comments).filter(comment =>
    !isKarteProcedureComment(comment)
    && !isPrescriptionRemarkOnlyComment(comment)
  );
}

function getCommentFreeText(comment) {
  return String(comment?.freeText || comment?.free_text || '').trim();
}

function isEditableProcedureComment(comment) {
  return Boolean(
    getCommentFreeText(comment)
    || isProcedureTextCommentTemplate(comment?.template)
    || isReceiptCommentAppendTemplate(comment)
    || isProcedureFreeInputPlaceholder(comment?.template)
    || isProcedureFreeInputPlaceholder(comment?.name || comment?.comment_name)
  );
}

function isBlankProcedureTextComment(comment) {
  return isEditableProcedureComment(comment) && !getCommentFreeText(comment);
}

function getEnteredProcedureComments(comments) {
  return normalizeActionComments(comments).filter(comment => !isBlankProcedureTextComment(comment));
}

function getClaimCommentCodes(comments) {
  return getClaimProcedureComments(comments).map(comment => comment.code).filter(Boolean);
}

function getClaimFreeCommentText(comments) {
  return getClaimProcedureComments(comments).map(getCommentFreeText).filter(Boolean).join('\n');
}

function getClaimReceiptPosition(comments, fallback = 'summary') {
  const receiptComment = getClaimProcedureComments(comments).find(comment => normalizeReceiptPosition(comment.position));
  return normalizeReceiptPosition(receiptComment?.position || fallback);
}

function getKarteCommentText(comments) {
  return normalizeActionComments(comments)
    .filter(isKarteProcedureComment)
    .map(getCommentFreeText)
    .filter(Boolean)
    .join('\n');
}

function getProcedureCommentDisplayRank(comment) {
  const kind = getProcedureCommentKind(comment);
  if (kind === 'free') return 0;
  if (kind === 'karte') return 2;
  return 1;
}

function getProcedureCommentDisplayName(comment) {
  const freeText = getCommentFreeText(comment);
  if (isReceiptCommentAppendTemplate(comment)) {
    return freeText || getReceiptCommentAppendLabel(comment);
  }
  if (freeText && isProcedureTextCommentTemplate(comment?.template)) return freeText;
  return comment?.name || comment?.template || '';
}

function getProcedureCommentIconKind(comment) {
  if (isKarteProcedureComment(comment)) return 'karte';

  const template = normalizeCommentMasterTemplate(
    comment?.template || comment?.comment_template || comment?.name || comment?.comment_name || ''
  );
  if (
    getProcedureCommentKind(comment) === 'free'
    || template === PROCEDURE_FREE_COMMENT_TEMPLATE
    || isProcedureFreeInputPlaceholder(template)
  ) {
    return 'free';
  }

  return 'document';
}

function getProcedureCommentIconClass(comment) {
  const iconKind = getProcedureCommentIconKind(comment);
  if (iconKind === 'free') return 'fas fa-comment-dots';
  if (iconKind === 'karte') return 'fas fa-file-medical';
  return 'fas fa-clipboard-list';
}

function getProcedureCommentIconLabel(comment) {
  const iconKind = getProcedureCommentIconKind(comment);
  if (iconKind === 'free') return 'フリーコメント';
  if (iconKind === 'karte') return 'カルテコメント';
  return 'レセプト・処方箋コメント';
}

function getProcedureCommentInputValue(comment) {
  if (isReceiptCommentAppendTemplate(comment)) {
    const appendedText = getReceiptCommentAppendedText(comment);
    return looksLikeReceiptCommentPlaceholder(appendedText, comment) ? '' : appendedText;
  }
  if (isProcedureFreeInputPlaceholder(comment?.template) || isProcedureFreeInputPlaceholder(comment?.name || comment?.comment_name)) {
    return getCommentFreeText(comment);
  }
  if (!isEditableProcedureComment(comment)) {
    return getProcedureCommentDisplayName(comment);
  }
  const freeText = getCommentFreeText(comment);
  if (freeText) return freeText;
  const splitName = splitProcedureTextComment(comment?.name || '');
  return splitName.freeText || '';
}

function autoResizeProcedureCommentInput(textarea) {
  if (!textarea) return;
  textarea.style.height = '25px';
  const nextHeight = Math.min(Math.max(textarea.scrollHeight, 25), 120);
  textarea.style.height = `${nextHeight}px`;
}

function getProcedureTextCommentTemplate(kind) {
  return getProcedureCommentKind({ commentKind: kind }) === 'karte'
    ? PROCEDURE_KARTE_COMMENT_TEMPLATE
    : PROCEDURE_FREE_COMMENT_TEMPLATE;
}

function findProcedureTextCommentMasterRow(template) {
  return facilityCommentMasterRows.find(row => row.template === template)
    || {
      code: template === PROCEDURE_KARTE_COMMENT_TEMPLATE ? 'LOCAL_KARTE_COMMENT' : 'LOCAL_FREE_COMMENT',
      template,
      typeLabel: '',
      targetName: '',
      targetCategory: '',
      payload: {}
    };
}

function buildPrescriptionUsageCommentRow(template, index) {
  return {
    index: `rx-comment-${index}`,
    code: `LOCAL_RX_COMMENT_${String(index + 1).padStart(2, '0')}`,
    template,
    name: template,
    typeLabel: '',
    targetName: '',
    targetCategory: '投薬',
    start: '0001-01-01',
    end: '9999-12-31',
    searchText: template,
    payload: { source: 'm3_prescription_comment_menu' }
  };
}

function getPrescriptionCommentTopRows() {
  return PRESCRIPTION_COMMENT_TOP_TEMPLATES.map((template, index) => {
    const masterRow = findProcedureCommentMasterRowByTemplate(template);
    if (masterRow) {
      return {
        ...masterRow,
        index: facilityCommentMasterRows.indexOf(masterRow),
        typeLabel: '',
        targetName: '',
        targetCategory: '',
        searchText: masterRow.searchText || template
      };
    }
    return buildPrescriptionUsageCommentRow(template, index);
  });
}

function getProcedureCommentOptionSortRank(option) {
  const template = normalizeCommentMasterTemplate(option?.template || option?.name || '');
  if (m3CommentAddTemplateOrder.has(template)) return m3CommentAddTemplateOrder.get(template);
  const index = PRESCRIPTION_COMMENT_TOP_TEMPLATES.indexOf(template);
  return index === -1 ? 1000 : index;
}

function findProcedureCommentMasterRowByTemplate(template) {
  const normalizedTemplate = normalizeCommentMasterTemplate(template);
  return facilityCommentMasterRows.find(row =>
    normalizeCommentMasterTemplate(row.template) === normalizedTemplate
  );
}

function normalizeActionComments(comments) {
  if (!Array.isArray(comments)) return [];
  return comments
    .map((comment, index) => {
      if (typeof comment === 'string') {
        const splitComment = splitProcedureTextComment(comment);
        const template = splitComment.template || comment;
        const freeText = splitComment.freeText || '';
        const commentKind = inferProcedureCommentKind(template, comment);
        return {
          code: `LOCAL_COMMENT_${String(index + 1).padStart(3, '0')}`,
          name: comment,
          template,
          position: 'summary',
          typeLabel: '',
          freeText,
          commentKind,
          comment_kind: commentKind
        };
      }
      const rawName = comment.name || comment.comment_name || '';
      const splitName = splitProcedureTextComment(rawName);
      const splitTemplate = splitProcedureTextComment(comment.template || comment.comment_template || '');
      const template = comment.template || comment.comment_template || splitName.template || rawName;
      const freeText = comment.freeText || comment.free_text || splitName.freeText || splitTemplate.freeText || '';
      const displayName = comment.name || comment.comment_name || (freeText ? `${template || 'コメント'}：${freeText}` : template);
      const commentKind = normalizeProcedureCommentKind(comment.commentKind || comment.comment_kind || comment.kind)
        || inferProcedureCommentKind(template, displayName);
      const printToPrescriptionRemarks = Boolean(
        comment.printToPrescriptionRemarks
        || comment.print_to_prescription_remarks
        || comment.prescriptionRemark
        || comment.prescription_remark
        || comment.prescription_remarks
      );
      const prescriptionRemarkText = comment.prescriptionRemarkText
        || comment.prescription_remark_text
        || comment.prescriptionRemarksText
        || comment.prescription_remarks_text
        || '';
      return {
        code: comment.code || comment.comment_code || `LOCAL_COMMENT_${String(index + 1).padStart(3, '0')}`,
        name: displayName,
        template,
        position: normalizeReceiptPosition(comment.position || comment.receipt_position),
        typeLabel: comment.typeLabel || comment.type_label || '',
        freeText,
        commentKind,
        comment_kind: commentKind,
        printToPrescriptionRemarks,
        print_to_prescription_remarks: printToPrescriptionRemarks,
        prescriptionRemark: printToPrescriptionRemarks,
        prescription_remark: printToPrescriptionRemarks,
        prescriptionRemarkText,
        prescription_remark_text: prescriptionRemarkText,
        targetName: comment.targetName || comment.target_name || '',
        targetCategory: comment.targetCategory || comment.target_category || '',
        payload: comment.payload || {}
      };
    })
    .filter(comment => comment.name || comment.template || comment.freeText);
}

function getActionComments(action) {
  if (!action) return [];
  const hadCommentArray = Array.isArray(action.comments);
  if (!Array.isArray(action.comments)) {
    action.comments = normalizeActionComments(action.comments || action.comment_names || []);
  } else {
    action.comments = normalizeActionComments(action.comments);
  }
  if (!hadCommentArray && !action.comments.length && (action.free_comment || action.freeComment)) {
    action.comments = normalizeActionComments([{
      code: 'LOCAL_FREE_COMMENT',
      name: `フリーコメント：${action.free_comment || action.freeComment}`,
      template: 'フリーコメント',
      position: action.receipt_position || action.receiptPosition || 'summary',
      freeText: action.free_comment || action.freeComment
    }]);
  }
  return action.comments;
}

function getPrescriptionComments(prescription) {
  if (!prescription) return [];
  const hadCommentArray = Array.isArray(prescription.comments);
  const rawComments = Array.isArray(prescription.comments) && prescription.comments.length
    ? prescription.comments
    : (prescription.comment_names || prescription.commentNames || prescription.comments || []);
  prescription.comments = normalizeActionComments(rawComments);
  if (!hadCommentArray && !prescription.comments.length && (prescription.free_comment || prescription.freeComment)) {
    prescription.comments = normalizeActionComments([{
      code: 'LOCAL_FREE_COMMENT',
      name: `フリーコメント：${prescription.free_comment || prescription.freeComment}`,
      template: 'フリーコメント',
      position: prescription.receipt_position || prescription.receiptPosition || 'summary',
      freeText: prescription.free_comment || prescription.freeComment
    }]);
  }
  return prescription.comments;
}

function isActionDoNotBill(action) {
  return Boolean(action?.do_not_bill || action?.doNotBill || action?.excludeFromBilling || action?.excluded_from_billing);
}

function syncActionDerivedFields(action) {
  ensureProcedureActionIdentity(action);
  const comments = getActionComments(action);
  action.comment_codes = getClaimCommentCodes(comments);
  action.receipt_position = getClaimReceiptPosition(comments);
  action.free_comment = getClaimFreeCommentText(comments);
  action.freeComment = action.free_comment;
  action.karte_comment = getKarteCommentText(comments);
  action.karteComment = action.karte_comment;
  action.do_not_bill = isActionDoNotBill(action);
  action.doNotBill = action.do_not_bill;
  action.billing_group_id = action.billing_group_id || action.billingGroupId || '';
  action.billingGroupId = action.billing_group_id;
  action.billing_group_parent_id = action.billing_group_parent_id || action.billingGroupParentId || '';
  action.billingGroupParentId = action.billing_group_parent_id;
  action.billing_group_label = action.billing_group_label || action.billingGroupLabel || '';
  action.billingGroupLabel = action.billing_group_label;
  return action;
}

function syncPrescriptionDerivedFields(prescription) {
  if (!prescription) return prescription;
  ensurePrescriptionIdentity(prescription);
  if (inferPrescriptionDrugType(prescription) === '外用') {
    const quantity = getPrescriptionInputQuantity(prescription);
    if (Number.isFinite(quantity) && quantity > 0) {
      prescription.dosage_quantity = quantity;
      prescription.dosage = `${quantity}${prescription.unit || prescription.dosage_unit || ''}`;
      prescription.total_quantity = quantity;
    }
    prescription.days = normalizePrescriptionDays(prescription);
  }
  const comments = getPrescriptionComments(prescription);
  const requirements = getPrescriptionRequirementState(prescription);
  applyGeneralPrescriptionMasterFields(prescription);
  const genericName = firstNonEmptyString(prescription.generic_name, prescription.genericName);
  if (genericName) {
    prescription.generic_name = genericName;
    prescription.genericName = genericName;
  }
  prescription.generic_prescription_code = firstNonEmptyString(prescription.generic_prescription_code, prescription.genericPrescriptionCode);
  prescription.genericPrescriptionCode = prescription.generic_prescription_code;
  prescription.generic_prescription_name = firstNonEmptyString(prescription.generic_prescription_name, prescription.genericPrescriptionName);
  prescription.genericPrescriptionName = prescription.generic_prescription_name;
  prescription.generic_prescription_addition_category = firstNonEmptyString(
    prescription.generic_prescription_addition_category,
    prescription.genericPrescriptionAdditionCategory
  );
  prescription.genericPrescriptionAdditionCategory = prescription.generic_prescription_addition_category;
  prescription.generic_prescription_master_note = firstNonEmptyString(
    prescription.generic_prescription_master_note,
    prescription.genericPrescriptionMasterNote
  );
  prescription.genericPrescriptionMasterNote = prescription.generic_prescription_master_note;
  prescription.generic_prescription_master_version = firstNonEmptyString(
    prescription.generic_prescription_master_version,
    prescription.genericPrescriptionMasterVersion
  );
  prescription.genericPrescriptionMasterVersion = prescription.generic_prescription_master_version;
  prescription.generic_prescription_lowest_price = prescription.generic_prescription_lowest_price
    ?? prescription.genericPrescriptionLowestPrice
    ?? '';
  prescription.genericPrescriptionLowestPrice = prescription.generic_prescription_lowest_price;
  prescription.comment_codes = getClaimCommentCodes(comments);
  prescription.commentCodes = prescription.comment_codes;
  prescription.receipt_position = getClaimReceiptPosition(comments);
  prescription.receiptPosition = prescription.receipt_position;
  prescription.free_comment = getClaimFreeCommentText(comments);
  prescription.freeComment = prescription.free_comment;
  prescription.karte_comment = getKarteCommentText(comments);
  prescription.karteComment = prescription.karte_comment;
  prescription.drug_type = prescription.drug_type || inferPrescriptionDrugType(prescription);
  prescription.long_term_listed = requirements.longTermListed;
  prescription.longTermListed = requirements.longTermListed;
  prescription.long_term_patient_choice = requirements.longTermPatientChoice;
  prescription.longTermPatientChoice = requirements.longTermPatientChoice;
  prescription.requires_comment = requirements.requiresComment;
  prescription.requiresComment = requirements.requiresComment;
  prescription.comment_required = requirements.requiresComment;
  prescription.commentRequired = requirements.requiresComment;
  prescription.selectable_comment_required = requirements.requiresComment;
  prescription.selectableCommentRequired = requirements.requiresComment;
  prescription.generic_change_allowed = requirements.genericChangeAllowed;
  prescription.genericChangeAllowed = requirements.genericChangeAllowed;
  prescription.generic_change_reason = requirements.genericChangeReason;
  prescription.genericChangeReason = requirements.genericChangeReason;
  prescription.is_temporary = Boolean(prescription.is_temporary || prescription.isTemporary || prescription.temporary);
  prescription.isTemporary = prescription.is_temporary;
  prescription.temporary = prescription.is_temporary;
  prescription.refill_allowed = Boolean(prescription.refill_allowed || prescription.refillAllowed || prescription.is_refill || prescription.isRefill);
  prescription.refillAllowed = prescription.refill_allowed;
  prescription.is_refill = prescription.refill_allowed;
  prescription.isRefill = prescription.refill_allowed;
  return prescription;
}

function normalizeProcedureCommentOption(row, index) {
  return {
    index,
    code: row.code,
    name: row.template,
    typeLabel: row.typeLabel || '',
    targetName: row.targetName || '',
    targetCategory: row.targetCategory || '',
    start: row.start,
    end: row.end,
    searchText: row.searchText || [
      row.code,
      row.template,
      row.typeLabel,
      row.targetName,
      row.targetCategory
    ].filter(Boolean).join(' '),
    payload: row.payload || {}
  };
}

function getProcedureCommentOptions() {
  return m3CommentAddTemplates.map((template, index) => {
    const masterRow = findProcedureCommentMasterRowByTemplate(template);
    const row = masterRow
      ? {
          ...masterRow,
          index: facilityCommentMasterRows.indexOf(masterRow),
          searchText: [masterRow.searchText, template].filter(Boolean).join(' ')
        }
      : buildM3CommentAddRow(template, index);
    return normalizeProcedureCommentOption(row, row.index ?? index);
  });
}

function renderProcedureActionIcon(displayCategory, iconClass, originalIndex) {
  return `
    <button type="button" class="m3-proc-icon proc-action-menu-btn ${iconClass}" onclick="toggleProcedureActionMenu(event, ${originalIndex})" title="メニュー" aria-label="診療行為メニュー">
      ${getCategoryIcon(displayCategory)}<span class="proc-icon-caret">▼</span>
    </button>
  `;
}

function renderPrescriptionActionIcon(originalIndex) {
  return `
    <button type="button" class="m3-proc-icon proc-action-menu-btn purple" onclick="toggleProcedureActionMenu(event, ${originalIndex}, 'prescription')" title="メニュー" aria-label="処方メニュー">
      薬<span class="proc-icon-caret">▼</span>
    </button>
  `;
}

function renderProcedureEntryComments(entry, originalIndex, {
  getComments = getActionComments,
  removeHandlerName = 'removeProcedureActionComment',
  updateHandlerName = 'updateProcedureActionCommentText',
  entryKind = 'action',
  includeDoNotBill = false
} = {}) {
  const comments = getComments(entry);
  const doNotBill = includeDoNotBill && isActionDoNotBill(entry);
  if (!comments.length && !doNotBill) return '';

  const doNotBillHtml = doNotBill
    ? '<span class="procedure-not-billable-badge">算定しない</span>'
    : '';
  const displayComments = comments
    .map((comment, commentIndex) => ({ comment, commentIndex }));

  const commentHtml = displayComments.map(({ comment, commentIndex }) => {
    const commentKind = getProcedureCommentKind(comment);
    const isKarteComment = commentKind === 'karte';
    const positionLabel = isKarteComment
      ? 'カルテ'
      : isPrescriptionRemarkOnlyComment(comment)
        ? PRESCRIPTION_COMMENT_REMARK_LABEL
        : (PROCEDURE_COMMENT_POSITION_LABELS[normalizeReceiptPosition(comment.position)] || '摘要欄内');
    const displayName = getProcedureCommentDisplayName(comment);
    const isEditableText = isEditableProcedureComment(comment);
    const isGenericNameComment = isGenericNamePrescriptionComment(comment);
    const typeLabel = !isGenericNameComment && !isEditableText && comment.typeLabel
      ? `<span class="procedure-action-comment-type">${escapeHtml(comment.typeLabel)}</span>`
      : '';
    const prescriptionRemarkLabel = isPrescriptionRemarkOnlyComment(comment) && !isKarteComment && !isGenericNameComment && !isEditableText
      ? `<span class="procedure-action-comment-prescription">${PRESCRIPTION_COMMENT_REMARK_LABEL}</span>`
      : '';
    const iconKind = getProcedureCommentIconKind(comment);
    const iconLabel = getProcedureCommentIconLabel(comment);
    const showPositionLabel = false;
    const inputPlaceholder = isReceiptCommentAppendTemplate(comment)
      ? getReceiptCommentAppendLabel(comment)
      : '';
    const metaHtml = (typeLabel || prescriptionRemarkLabel || showPositionLabel)
      ? `
          <span class="procedure-action-comment-meta">
            ${typeLabel}
            ${prescriptionRemarkLabel}
            ${showPositionLabel ? `<span class="procedure-action-comment-position">${escapeHtml(positionLabel)}</span>` : ''}
          </span>
        `
      : '';
    const bodyHtml = isEditableText
      ? `<textarea class="procedure-action-comment-input" rows="1" placeholder="${escapeHtmlAttribute(inputPlaceholder)}" data-entry-kind="${escapeHtmlAttribute(entryKind)}" data-entry-index="${originalIndex}" data-comment-index="${commentIndex}" oninput="autoResizeProcedureCommentInput(this)" onfocus="autoResizeProcedureCommentInput(this)" onchange="${updateHandlerName}(${originalIndex}, ${commentIndex}, this.value)" onclick="event.stopPropagation();" onkeydown="event.stopPropagation();">${escapeHtml(getProcedureCommentInputValue(comment))}</textarea>`
      : `<span class="procedure-action-comment-name">${escapeHtml(displayName)}</span>`;
    const rowClass = [
      'procedure-action-comment-row',
      `procedure-action-comment-${commentKind}`,
      `procedure-action-comment-visual-${iconKind}`,
      isEditableText ? 'is-editable-text-comment' : '',
      isGenericNameComment ? 'is-generic-name-comment' : ''
    ].filter(Boolean).join(' ');
    return `
      <div class="${escapeHtmlAttribute(rowClass)}">
        <span class="procedure-action-comment-icon" title="${escapeHtmlAttribute(iconLabel)}" aria-label="${escapeHtmlAttribute(iconLabel)}"><i class="${escapeHtmlAttribute(getProcedureCommentIconClass(comment))}" aria-hidden="true"></i></span>
        <span class="procedure-action-comment-body">
          ${metaHtml}
          ${bodyHtml}
        </span>
        <button type="button" class="procedure-action-comment-remove" onclick="${removeHandlerName}(${originalIndex}, ${commentIndex}, event)" title="コメントを削除" aria-label="コメントを削除">&times;</button>
      </div>
    `;
  }).join('');

  return `<div class="procedure-action-comments">${doNotBillHtml}${commentHtml}</div>`;
}

function renderProcedureActionComments(action, originalIndex) {
  return renderProcedureEntryComments(action, originalIndex, {
    getComments: getActionComments,
    removeHandlerName: 'removeProcedureActionComment',
    entryKind: 'action',
    includeDoNotBill: true
  });
}

function renderPrescriptionComments(prescription, originalIndex) {
  return renderProcedureEntryComments(prescription, originalIndex, {
    getComments: getPrescriptionComments,
    removeHandlerName: 'removePrescriptionComment',
    updateHandlerName: 'updatePrescriptionCommentText',
    entryKind: 'prescription'
  });
}

function ensureProcedureActionMenu() {
  let menu = document.getElementById('procedure-action-menu');
  if (menu) return menu;

  menu = document.createElement('div');
  menu.id = 'procedure-action-menu';
  menu.className = 'procedure-action-menu hidden';
  menu.innerHTML = `
    <button type="button" data-procedure-action-menu="free-comment" data-action-menu-only>フリーコメント</button>
    <button type="button" data-procedure-action-menu="karte-comment" data-action-menu-only>カルテコメント</button>
    <button type="button" data-procedure-action-menu="comment">コメントを検索して追加</button>
    <button type="button" data-procedure-action-menu="generic-name-prescription" data-prescription-menu-only>一般名記載</button>
    <button type="button" data-procedure-action-menu="master-info" data-prescription-menu-only>マスタ情報</button>
    <button type="button" data-procedure-action-menu="long-term-listed" data-prescription-advanced-menu>長期収載理由</button>
    <button type="button" data-procedure-action-menu="long-term-patient-choice" data-prescription-advanced-menu>患者希望（選定療養）</button>
    <button type="button" data-procedure-action-menu="comment-required" data-prescription-advanced-menu>コメント要にする</button>
    <button type="button" data-procedure-action-menu="temporary-prescription" data-prescription-advanced-menu>臨時投薬にする</button>
    <button type="button" data-procedure-action-menu="refill-prescription" data-prescription-advanced-menu>リフィル可にする</button>
    <button type="button" data-procedure-action-menu="do-not-bill" data-action-menu-only>算定しない</button>
    <button type="button" data-procedure-action-menu="detail">詳細情報</button>
  `;
  menu.addEventListener('click', (event) => {
    const button = event.target.closest('[data-procedure-action-menu]');
    if (!button) return;
    event.preventDefault();
    event.stopPropagation();
    const index = Number(menu.dataset.index);
    const kind = menu.dataset.kind || 'action';
    const command = button.dataset.procedureActionMenu;
    closeProcedureActionMenu();
    if (command === 'free-comment') {
      addProcedureTextComment(index, kind, 'free');
    } else if (command === 'karte-comment') {
      addProcedureTextComment(index, kind, 'karte');
    } else if (command === 'comment') {
      openProcedureCommentDialog(index, kind);
    } else if (command === 'generic-name-prescription' && kind === 'prescription') {
      addGenericNamePrescriptionComment(index);
    } else if (command === 'master-info' && kind === 'prescription') {
      showPrescriptionMasterInfo(index);
    } else if (command === 'long-term-listed' && kind === 'prescription') {
      addLongTermListedReasonComment(index);
    } else if (command === 'long-term-patient-choice' && kind === 'prescription') {
      addLongTermPatientChoiceComment(index);
    } else if (command === 'comment-required' && kind === 'prescription') {
      togglePrescriptionCommentRequired(index);
    } else if (command === 'temporary-prescription' && kind === 'prescription') {
      togglePrescriptionTemporary(index);
    } else if (command === 'refill-prescription' && kind === 'prescription') {
      togglePrescriptionRefill(index);
    } else if (command === 'do-not-bill' && kind === 'action') {
      toggleProcedureDoNotBill(index);
    } else if (command === 'detail') {
      showProcedureEntryDetail(index, kind);
    }
  });

  document.body.appendChild(menu);
  document.addEventListener('click', closeProcedureActionMenu);
  window.addEventListener('resize', closeProcedureActionMenu);
  return menu;
}

function closeProcedureActionMenu() {
  const menu = document.getElementById('procedure-action-menu');
  menu?.classList.add('hidden');
  procedureActionMenuState = { index: null, kind: 'action' };
}

function getProcedureEntryByKind(index, kind = 'action') {
  return kind === 'prescription'
    ? pendingPrescriptions[index]
    : selectedActions[index];
}

function toggleProcedureActionMenu(event, index, kind = 'action') {
  event.preventDefault();
  event.stopPropagation();
  const menu = ensureProcedureActionMenu();
  const normalizedKind = kind === 'prescription' ? 'prescription' : 'action';
  if (
    procedureActionMenuState.index === index
    && procedureActionMenuState.kind === normalizedKind
    && !menu.classList.contains('hidden')
  ) {
    closeProcedureActionMenu();
    return;
  }

  const entry = getProcedureEntryByKind(index, normalizedKind);
  if (!entry) return;

  procedureActionMenuState = { index, kind: normalizedKind };
  menu.dataset.index = String(index);
  menu.dataset.kind = normalizedKind;
  const isPrescriptionMenu = normalizedKind === 'prescription';
  const setMenuButtonHidden = (button, shouldHide) => {
    button.hidden = shouldHide;
    button.style.display = shouldHide ? 'none' : '';
  };
  menu.querySelectorAll('[data-action-menu-only]').forEach(button => {
    setMenuButtonHidden(button, isPrescriptionMenu);
  });
  menu.querySelectorAll('[data-prescription-menu-only]').forEach(button => {
    setMenuButtonHidden(button, !isPrescriptionMenu);
  });
  menu.querySelectorAll('[data-prescription-advanced-menu]').forEach(button => {
    setMenuButtonHidden(button, true);
  });
  const commentButton = menu.querySelector('[data-procedure-action-menu="comment"]');
  if (commentButton) {
    commentButton.textContent = isPrescriptionMenu ? 'コメントを追加' : 'コメントを検索して追加';
  }
  const doNotBillButton = menu.querySelector('[data-procedure-action-menu="do-not-bill"]');
  if (doNotBillButton) {
    doNotBillButton.textContent = normalizedKind === 'action' && isActionDoNotBill(entry) ? '算定する' : '算定しない';
  }
  if (normalizedKind === 'prescription') {
    const requirements = getPrescriptionRequirementState(entry);
    const commentRequiredButton = menu.querySelector('[data-procedure-action-menu="comment-required"]');
    if (commentRequiredButton) {
      commentRequiredButton.textContent = requirements.requiresComment ? 'コメント要を解除' : 'コメント要にする';
    }
    const temporaryButton = menu.querySelector('[data-procedure-action-menu="temporary-prescription"]');
    if (temporaryButton) {
      temporaryButton.textContent = entry.is_temporary || entry.isTemporary || entry.temporary ? '臨時投薬を解除' : '臨時投薬にする';
    }
    const refillButton = menu.querySelector('[data-procedure-action-menu="refill-prescription"]');
    if (refillButton) {
      refillButton.textContent = entry.refill_allowed || entry.refillAllowed || entry.is_refill || entry.isRefill ? 'リフィル可を解除' : 'リフィル可にする';
    }
  }

  const rect = event.currentTarget.getBoundingClientRect();
  menu.style.left = `${Math.min(rect.left, window.innerWidth - 190)}px`;
  menu.style.top = `${rect.bottom + 4}px`;
  menu.classList.remove('hidden');
}

function ensureProcedureCommentDialog() {
  let dialog = document.getElementById('procedure-comment-dialog');
  if (dialog) return dialog;

  dialog = document.createElement('div');
  dialog.id = 'procedure-comment-dialog';
  dialog.className = 'procedure-comment-overlay hidden';
  dialog.innerHTML = `
    <div class="procedure-comment-modal" role="dialog" aria-modal="true" aria-labelledby="procedure-comment-title">
      <div class="procedure-comment-header">
        <h3 id="procedure-comment-title">コメント追加</h3>
        <button type="button" class="procedure-comment-close" title="閉じる" aria-label="閉じる">&times;</button>
      </div>
      <div class="procedure-comment-prescription-remark-row hidden">
        <label>
          <input id="procedure-comment-prescription-remark" type="checkbox">
          処方箋備考欄に記載する
        </label>
      </div>
      <div class="procedure-comment-position">
        <span class="procedure-comment-position-label">レセプト記載位置</span>
        <label><input type="radio" name="procedure-comment-position" value="summary" checked> 摘要欄内</label>
        <label><input type="radio" name="procedure-comment-position" value="top"> 上部</label>
        <label><input type="radio" name="procedure-comment-position" value="bottom"> 下部</label>
      </div>
      <label class="procedure-comment-search">
        <i class="fas fa-search" aria-hidden="true"></i>
        <input id="procedure-comment-search-input" type="search" placeholder="キーワードを入力してください" autocomplete="off">
      </label>
      <div id="procedure-comment-list" class="procedure-comment-list"></div>
    </div>
  `;

  dialog.querySelector('.procedure-comment-close')?.addEventListener('click', closeProcedureCommentDialog);
  dialog.addEventListener('click', (event) => {
    if (event.target === dialog) closeProcedureCommentDialog();
  });
  dialog.querySelector('#procedure-comment-search-input')?.addEventListener('input', (event) => {
    procedureCommentDialogState.query = event.target.value || '';
    renderProcedureCommentOptions();
  });
  dialog.querySelector('#procedure-comment-prescription-remark')?.addEventListener('change', (event) => {
    procedureCommentDialogState.printToPrescriptionRemarks = Boolean(event.target.checked);
  });
  dialog.querySelector('#procedure-comment-list')?.addEventListener('click', (event) => {
    const option = event.target.closest('[data-comment-option-index]');
    if (!option) return;
    selectProcedureCommentOption(Number(option.dataset.commentOptionIndex));
  });
  document.body.appendChild(dialog);
  return dialog;
}

function openProcedureCommentDialog(itemIndex, kind = 'action') {
  const normalizedKind = kind === 'prescription' ? 'prescription' : 'action';
  if (!getProcedureEntryByKind(itemIndex, normalizedKind)) return;
  const dialog = ensureProcedureCommentDialog();
  procedureCommentDialogState = {
    kind: normalizedKind,
    itemIndex,
    actionIndex: normalizedKind === 'action' ? itemIndex : null,
    query: '',
    printToPrescriptionRemarks: false
  };
  const input = dialog.querySelector('#procedure-comment-search-input');
  if (input) input.value = '';
  const prescriptionRemarkRow = dialog.querySelector('.procedure-comment-prescription-remark-row');
  const prescriptionRemarkCheckbox = dialog.querySelector('#procedure-comment-prescription-remark');
  if (prescriptionRemarkRow) {
    prescriptionRemarkRow.classList.toggle('hidden', normalizedKind !== 'prescription');
  }
  if (prescriptionRemarkCheckbox) {
    prescriptionRemarkCheckbox.checked = false;
  }
  const positionRow = dialog.querySelector('.procedure-comment-position');
  if (positionRow) {
    positionRow.classList.toggle('hidden', normalizedKind === 'prescription');
  }
  dialog.querySelector('input[name="procedure-comment-position"][value="summary"]')?.click();
  renderProcedureCommentOptions();
  dialog.classList.remove('hidden');
  input?.focus();
}

function closeProcedureCommentDialog() {
  document.getElementById('procedure-comment-dialog')?.classList.add('hidden');
  procedureCommentDialogState = {
    kind: 'action',
    itemIndex: null,
    actionIndex: null,
    query: '',
    printToPrescriptionRemarks: false
  };
  procedureCommentVisibleOptions = [];
}

function getSelectedProcedureCommentPosition() {
  const dialog = ensureProcedureCommentDialog();
  const selected = dialog.querySelector('input[name="procedure-comment-position"]:checked')?.value;
  return normalizeReceiptPosition(selected);
}

function isPrescriptionRemarkCommentEnabled() {
  const dialog = ensureProcedureCommentDialog();
  return Boolean(dialog.querySelector('#procedure-comment-prescription-remark')?.checked);
}

function focusProcedureCommentInput(targetKind, targetIndex, commentIndex) {
  window.setTimeout(() => {
    const selector = `.procedure-action-comment-input[data-entry-kind="${targetKind}"][data-entry-index="${targetIndex}"][data-comment-index="${commentIndex}"]`;
    const input = document.querySelector(selector);
    if (!input) return;
    input.focus();
    input.select();
  }, 0);
}

function renderProcedureCommentOptions() {
  const dialog = ensureProcedureCommentDialog();
  const list = dialog.querySelector('#procedure-comment-list');
  if (!list) return;
  const query = String(procedureCommentDialogState.query || '').trim().toLowerCase();
  const options = getProcedureCommentOptions().filter(option => {
    if (!query) return true;
    return String(option.searchText || '').toLowerCase().includes(query);
  });
  const visibleOptions = query ? options.slice(0, 300) : options.slice(0, 120);
  procedureCommentVisibleOptions = visibleOptions;

  if (!options.length) {
    list.innerHTML = '<div class="procedure-comment-empty">該当するコメントがありません</div>';
    return;
  }

  list.innerHTML = visibleOptions.map((option, visibleIndex) => `
    <button type="button" class="procedure-comment-option" data-comment-option-index="${visibleIndex}">
      ${option.typeLabel ? `<span class="procedure-comment-type-tag">${escapeHtml(option.typeLabel)}</span>` : ''}
      ${option.targetName ? `<span class="procedure-comment-target">${escapeHtml(option.targetName)}</span>` : ''}
      <span class="procedure-comment-option-name">${escapeHtml(option.name)}</span>
    </button>
  `).join('');
}

function appendProcedureCommentToTarget(targetKind, targetIndex, option, overrides = {}) {
  const normalizedKind = targetKind === 'prescription' ? 'prescription' : 'action';
  const target = getProcedureEntryByKind(targetIndex, normalizedKind);
  if (!target || !option) return false;

  const template = option.template || overrides.template || PROCEDURE_FREE_COMMENT_TEMPLATE;
  const appendLabel = getReceiptCommentAppendLabel({ template, name: option.name, commentKind: 'receipt' });
  const requiresAppendText = isReceiptCommentAppendTemplate({ template, name: option.name, commentKind: 'receipt' });
  const freeText = String(overrides.freeText || '').trim();
  const displayName = overrides.displayName || (
    requiresAppendText
      ? appendLabel
      : (
    freeText && isProcedureTextCommentTemplate(template)
      ? `${template}：${freeText}`
      : template
      )
  );
  const commentKind = overrides.commentKind
    ? normalizeProcedureCommentKind(overrides.commentKind)
    : inferProcedureCommentKind(template, displayName);
  const position = normalizeReceiptPosition(overrides.position || getSelectedProcedureCommentPosition());
  const printToPrescriptionRemarks = Boolean(
    normalizedKind === 'prescription'
    && (overrides.printToPrescriptionRemarks ?? isPrescriptionRemarkCommentEnabled())
  );
  const hasPrescriptionRemarkTextOverride = Object.prototype.hasOwnProperty.call(overrides, 'prescriptionRemarkText');
  const prescriptionRemarkText = printToPrescriptionRemarks
    ? normalizePrescriptionRemarksText(hasPrescriptionRemarkTextOverride ? overrides.prescriptionRemarkText : (freeText || template || displayName))
    : '';
  const comments = normalizedKind === 'prescription'
    ? getPrescriptionComments(target)
    : getActionComments(target);
  const newCommentIndex = comments.length;

  comments.push({
    code: option.code,
    name: displayName,
    template,
    position,
    typeLabel: option.typeLabel || '',
    freeText,
    free_text: freeText,
    commentKind,
    comment_kind: commentKind,
    printToPrescriptionRemarks,
    print_to_prescription_remarks: printToPrescriptionRemarks,
    prescriptionRemark: printToPrescriptionRemarks,
    prescription_remark: printToPrescriptionRemarks,
    prescriptionRemarkText,
    prescription_remark_text: prescriptionRemarkText,
    targetName: option.targetName || '',
    targetCategory: option.targetCategory || '',
    payload: option.payload || {}
  });

  if (normalizedKind === 'prescription') {
    ensurePrescriptionIdentity(target);
    selectedProcedureGroupAnchorId = null;
    const groupId = getPrescriptionGroupId(target);
    if (groupId) {
      const parent = pendingPrescriptions.find(member =>
        getPrescriptionGroupId(member) === groupId && !isPrescriptionManualGroupChild(member)
      ) || target;
      ensurePrescriptionIdentity(parent);
      selectedPrescriptionGroupAnchorId = parent.prescription_item_id;
    } else {
      selectedPrescriptionGroupAnchorId = target.prescription_item_id;
    }
    syncPrescriptionDerivedFields(target);
    renderPendingPrescriptionsInProcedure();
    renderCurrentPrescriptions();
    checkPrescriptionsRealtime();
  } else {
    ensureProcedureActionIdentity(target);
    selectedPrescriptionGroupAnchorId = null;
    const groupId = getManualBillingGroupId(target);
    if (groupId) {
      const parent = selectedActions.find(member =>
        getManualBillingGroupId(member) === groupId && !isManualBillingGroupChild(member)
      ) || target;
      ensureProcedureActionIdentity(parent);
      selectedProcedureGroupAnchorId = parent.procedure_item_id;
    } else {
      selectedProcedureGroupAnchorId = target.procedure_item_id;
    }
    syncActionDerivedFields(target);
    renderSelectedActionsInProcedure();
  }
  updateTotalPoints();
  saveCurrentPatientBilling();
  if (!document.getElementById('billing-modal')?.classList.contains('hidden')) {
    calculateBilling();
  }
  if (overrides.focusAfterAdd) {
    focusProcedureCommentInput(normalizedKind, targetIndex, newCommentIndex);
  }
  return true;
}

function addProcedureTextComment(itemIndex, kind = 'action', commentKind = 'free') {
  const normalizedKind = kind === 'prescription' ? 'prescription' : 'action';
  const target = getProcedureEntryByKind(itemIndex, normalizedKind);
  if (!target) return;

  const template = getProcedureTextCommentTemplate(commentKind);
  const option = findProcedureTextCommentMasterRow(template);
  const appendOption = {
    ...option,
    typeLabel: '',
    targetName: '',
    targetCategory: ''
  };
  const added = appendProcedureCommentToTarget(normalizedKind, itemIndex, appendOption, {
    freeText: '',
    displayName: template,
    commentKind: inferProcedureCommentKind(template, template),
    position: 'summary',
    printToPrescriptionRemarks: false,
    focusAfterAdd: true
  });
  if (added) showToast(`${template}欄を追加しました`, 'success');
}

function selectProcedureCommentOption(optionIndex) {
  const targetKind = procedureCommentDialogState.kind === 'prescription' ? 'prescription' : 'action';
  const targetIndex = procedureCommentDialogState.itemIndex ?? procedureCommentDialogState.actionIndex;
  const target = getProcedureEntryByKind(targetIndex, targetKind);
  const option = procedureCommentVisibleOptions[optionIndex] || facilityCommentMasterRows[optionIndex];
  if (!target || !option) return;

  let freeText = '';
  const appendLabel = getReceiptCommentAppendLabel({ template: option.template, name: option.name, commentKind: 'receipt' });
  const requiresAppendText = isReceiptCommentAppendTemplate({ template: option.template, name: option.name, commentKind: 'receipt' });
  let displayName = requiresAppendText ? appendLabel : option.template;
  const isTextCommentTemplate = isProcedureTextCommentTemplate(option.template) || requiresAppendText;
  if (isTextCommentTemplate) {
    freeText = '';
    displayName = requiresAppendText ? appendLabel : option.template;
  }

  const commentKind = inferProcedureCommentKind(option.template, displayName);
  const position = getSelectedProcedureCommentPosition();
  const printToPrescriptionRemarks = targetKind === 'prescription' && isPrescriptionRemarkCommentEnabled();
  const prescriptionRemarkText = printToPrescriptionRemarks
    ? normalizePrescriptionRemarksText(isTextCommentTemplate ? freeText : (freeText || option.template || displayName))
    : '';
  const appendOption = isTextCommentTemplate
    ? {
        ...option,
        typeLabel: '',
        targetName: '',
        targetCategory: ''
      }
    : option;
  appendProcedureCommentToTarget(targetKind, targetIndex, appendOption, {
    freeText,
    displayName,
    commentKind,
    position,
    printToPrescriptionRemarks,
    prescriptionRemarkText,
    focusAfterAdd: isTextCommentTemplate
  });
  closeProcedureCommentDialog();
  showToast(isTextCommentTemplate ? 'コメント欄を追加しました' : 'コメントを追加しました', 'success');
}

function commitPrescriptionMetadataChange(prescriptionIndex, toastMessage = '') {
  const prescription = pendingPrescriptions[prescriptionIndex];
  if (!prescription) return;
  syncPrescriptionDerivedFields(prescription);
  renderPendingPrescriptionsInProcedure();
  renderCurrentPrescriptions();
  updateTotalPoints();
  saveCurrentPatientBilling();
  if (!document.getElementById('billing-modal')?.classList.contains('hidden')) {
    calculateBilling();
  }
  checkPrescriptionsRealtime();
  if (toastMessage) showToast(toastMessage, 'success');
}

function prescriptionHasMatchingComment(prescription, matcher) {
  return getPrescriptionComments(prescription).some(comment => matcher(comment));
}

function addPrescriptionCommentOnce(prescriptionIndex, option, overrides = {}) {
  const prescription = pendingPrescriptions[prescriptionIndex];
  if (!prescription || !option) return false;
  const optionCode = String(option.code || '').trim();
  const optionTemplate = normalizeCommentMasterTemplate(option.template || option.name || '');
  const alreadyExists = prescriptionHasMatchingComment(prescription, comment => {
    const commentCode = String(comment?.code || '').trim();
    const commentTemplate = normalizeCommentMasterTemplate(comment?.template || comment?.name || '');
    return (optionCode && commentCode === optionCode)
      || (optionTemplate && commentTemplate === optionTemplate);
  });

  if (alreadyExists) {
    commitPrescriptionMetadataChange(prescriptionIndex);
    return true;
  }
  return appendProcedureCommentToTarget('prescription', prescriptionIndex, option, overrides);
}

function getGenericNamePrescriptionCommentOption() {
  return findProcedureCommentMasterRowByTemplate('一般名記載')
    || {
      code: commentMasterOfficialOverrides['一般名記載']?.code || '099209908',
      template: '一般名記載',
      start: commentMasterOfficialOverrides['一般名記載']?.start || '2012-04-01',
      end: commentMasterOfficialOverrides['一般名記載']?.end || '9999-12-31',
      typeLabel: '摘要',
      targetName: '投薬',
      targetCategory: '投薬',
      payload: { source: 'm3_drug_icon_menu' }
    };
}

function markPrescriptionGenericName(prescription) {
  if (!prescription) return;
  const genericName = getPrescriptionGeneralNameSource(prescription);
  if (genericName) {
    prescription.generic_name = genericName;
    prescription.genericName = genericName;
  }
  applyGeneralPrescriptionMasterFields(prescription);
}

function addGenericNamePrescriptionComment(prescriptionIndex) {
  const prescription = pendingPrescriptions[prescriptionIndex];
  if (!prescription) return;
  markPrescriptionGenericName(prescription);
  const option = getGenericNamePrescriptionCommentOption();
  const added = addPrescriptionCommentOnce(prescriptionIndex, option, {
    commentKind: 'receipt',
    position: 'summary',
    printToPrescriptionRemarks: false
  });
  if (!added) {
    commitPrescriptionMetadataChange(prescriptionIndex, '一般名記載にしました');
    return;
  }
  showToast('一般名記載を追加しました', 'success');
}

function chooseLongTermListedReasonOption() {
  const options = findLongTermListedCommentOptions({ patientChoice: false }).slice(0, 8);
  if (!options.length) {
    return {
      code: '820101325',
      template: '医療上の必要性があると医師又は歯科医師が判断したため',
      typeLabel: '長期収載',
      start: '2026-06-01',
      end: '9999-12-31'
    };
  }
  if (options.length === 1) return options[0];

  const message = [
    '長期収載品の理由コメントを選択してください。',
    '',
    ...options.map((option, index) => `${index + 1}. ${option.template || option.name}`)
  ].join('\n');
  const input = window.prompt(message, '1');
  if (input === null) return null;
  const selectedIndex = Number(input) - 1;
  if (!Number.isInteger(selectedIndex) || !options[selectedIndex]) return null;
  return options[selectedIndex];
}

function addLongTermListedReasonComment(prescriptionIndex) {
  const prescription = pendingPrescriptions[prescriptionIndex];
  if (!prescription) return;
  const option = chooseLongTermListedReasonOption();
  if (!option) return;
  markPrescriptionLongTermListed(prescription, {
    patientChoice: false,
    reason: option.template || option.name || ''
  });
  const added = addPrescriptionCommentOnce(prescriptionIndex, option, {
    commentKind: 'receipt',
    position: 'summary',
    printToPrescriptionRemarks: false
  });
  if (added) showToast('長期収載品の理由コメントを追加しました', 'success');
}

function addLongTermPatientChoiceComment(prescriptionIndex) {
  const prescription = pendingPrescriptions[prescriptionIndex];
  if (!prescription) return;
  const option = findLongTermListedCommentOptions({ patientChoice: true })[0] || {
    code: '820101320',
    template: '患者希望（長期収載品：選定療養）',
    typeLabel: '長期収載',
    start: '2026-06-01',
    end: '9999-12-31'
  };
  markPrescriptionLongTermListed(prescription, {
    patientChoice: true,
    reason: option.template || option.name || ''
  });
  const added = addPrescriptionCommentOnce(prescriptionIndex, option, {
    commentKind: 'receipt',
    position: 'summary',
    printToPrescriptionRemarks: false
  });
  if (added) showToast('患者希望（選定療養）コメントを追加しました', 'success');
}

function togglePrescriptionCommentRequired(prescriptionIndex) {
  const prescription = pendingPrescriptions[prescriptionIndex];
  if (!prescription) return;
  const current = getPrescriptionRequirementState(prescription).requiresComment;
  const next = !current;
  prescription.requires_comment = next;
  prescription.requiresComment = next;
  prescription.comment_required = next;
  prescription.commentRequired = next;
  prescription.selectable_comment_required = next;
  prescription.selectableCommentRequired = next;
  commitPrescriptionMetadataChange(
    prescriptionIndex,
    next ? '処方をコメント要にしました' : '処方のコメント要を解除しました'
  );
}

function togglePrescriptionTemporary(prescriptionIndex) {
  const prescription = pendingPrescriptions[prescriptionIndex];
  if (!prescription) return;
  const next = !Boolean(prescription.is_temporary || prescription.isTemporary || prescription.temporary);
  prescription.is_temporary = next;
  prescription.isTemporary = next;
  prescription.temporary = next;
  commitPrescriptionMetadataChange(
    prescriptionIndex,
    next ? '臨時投薬にしました' : '臨時投薬を解除しました'
  );
}

function getRefillCommentOption(count) {
  const normalizedCount = String(count || '').trim();
  const fullWidthCount = normalizedCount.replace(/[0-9]/g, char =>
    String.fromCharCode(char.charCodeAt(0) + 0xFEE0)
  );
  return facilityCommentMasterRows.find(row => {
    const template = row.template || '';
    return template.includes('リフィル可')
      && (template.includes(`（${normalizedCount}回）`) || template.includes(`（${fullWidthCount}回）`));
  });
}

function togglePrescriptionRefill(prescriptionIndex) {
  const prescription = pendingPrescriptions[prescriptionIndex];
  if (!prescription) return;
  const current = Boolean(prescription.refill_allowed || prescription.refillAllowed || prescription.is_refill || prescription.isRefill);
  if (current) {
    prescription.refill_allowed = false;
    prescription.refillAllowed = false;
    prescription.is_refill = false;
    prescription.isRefill = false;
    prescription.refill_count = null;
    prescription.refillCount = null;
    const comments = getPrescriptionComments(prescription);
    prescription.comments = comments.filter(comment => !getProcedureCommentSearchText(comment).includes('リフィル可'));
    commitPrescriptionMetadataChange(prescriptionIndex, 'リフィル可を解除しました');
    return;
  }

  const input = window.prompt('リフィル回数を入力してください（2または3）', String(prescription.refill_count || prescription.refillCount || 2));
  if (input === null) return;
  const refillCount = Number(input);
  if (![2, 3].includes(refillCount)) {
    showToast('リフィル回数は2または3で入力してください', 'error');
    return;
  }
  prescription.refill_allowed = true;
  prescription.refillAllowed = true;
  prescription.is_refill = true;
  prescription.isRefill = true;
  prescription.refill_count = refillCount;
  prescription.refillCount = refillCount;

  const option = getRefillCommentOption(refillCount);
  if (option) {
    addPrescriptionCommentOnce(prescriptionIndex, option, {
      commentKind: 'receipt',
      position: 'summary',
      printToPrescriptionRemarks: false
    });
  } else {
    commitPrescriptionMetadataChange(prescriptionIndex);
  }
  showToast('リフィル可にしました', 'success');
}

function removeProcedureActionComment(actionIndex, commentIndex, event) {
  event?.preventDefault();
  event?.stopPropagation();
  const action = selectedActions[actionIndex];
  if (!action) return;
  const comments = getActionComments(action);
  comments.splice(commentIndex, 1);
  syncActionDerivedFields(action);
  renderSelectedActionsInProcedure();
  updateTotalPoints();
  saveCurrentPatientBilling();
  showToast('コメントを削除しました', 'info');
}

function updateProcedureEntryCommentText(entry, commentIndex, value) {
  const comments = Array.isArray(entry?.comments) ? entry.comments : [];
  const comment = comments[commentIndex];
  if (!comment) return false;

  const text = String(value || '').trim();
  const kind = getProcedureCommentKind(comment);
  const template = comment.template || getProcedureTextCommentTemplate(kind);
  comment.template = template;
  comment.freeText = text;
  comment.free_text = text;
  if (isReceiptCommentAppendTemplate(comment)) {
    const label = getReceiptCommentAppendLabel(comment);
    comment.name = text ? `${label}：${text}` : label;
  } else {
    comment.name = isProcedureTextCommentTemplate(template) && text
      ? `${template}：${text}`
      : (text || template);
  }
  comment.commentKind = kind || inferProcedureCommentKind(template, comment.name);
  comment.comment_kind = comment.commentKind;
  if (isPrescriptionRemarkOnlyComment(comment)) {
    comment.prescriptionRemarkText = normalizePrescriptionRemarksText(text || template);
    comment.prescription_remark_text = comment.prescriptionRemarkText;
  }
  return true;
}

function updateProcedureActionCommentText(actionIndex, commentIndex, value) {
  const action = selectedActions[actionIndex];
  if (!action || !updateProcedureEntryCommentText(action, commentIndex, value)) return;
  syncActionDerivedFields(action);
  renderSelectedActionsInProcedure();
  updateTotalPoints();
  saveCurrentPatientBilling();
  if (!document.getElementById('billing-modal')?.classList.contains('hidden')) {
    calculateBilling();
  }
}

function removePrescriptionComment(prescriptionIndex, commentIndex, event) {
  event?.preventDefault();
  event?.stopPropagation();
  const prescription = pendingPrescriptions[prescriptionIndex];
  if (!prescription) return;
  const comments = getPrescriptionComments(prescription);
  comments.splice(commentIndex, 1);
  syncPrescriptionDerivedFields(prescription);
  renderPendingPrescriptionsInProcedure();
  renderCurrentPrescriptions();
  updateTotalPoints();
  saveCurrentPatientBilling();
  if (!document.getElementById('billing-modal')?.classList.contains('hidden')) {
    calculateBilling();
  }
  checkPrescriptionsRealtime();
  showToast('コメントを削除しました', 'info');
}

function updatePrescriptionCommentText(prescriptionIndex, commentIndex, value) {
  const prescription = pendingPrescriptions[prescriptionIndex];
  if (!prescription || !updateProcedureEntryCommentText(prescription, commentIndex, value)) return;
  syncPrescriptionDerivedFields(prescription);
  renderPendingPrescriptionsInProcedure();
  renderCurrentPrescriptions();
  updateTotalPoints();
  saveCurrentPatientBilling();
  if (!document.getElementById('billing-modal')?.classList.contains('hidden')) {
    calculateBilling();
  }
  checkPrescriptionsRealtime();
}

function toggleProcedureDoNotBill(index) {
  const action = selectedActions[index];
  if (!action) return;
  action.do_not_bill = !isActionDoNotBill(action);
  action.doNotBill = action.do_not_bill;
  renderSelectedActionsInProcedure();
  updateTotalPoints();
  saveCurrentPatientBilling();
  if (!document.getElementById('billing-modal')?.classList.contains('hidden')) {
    calculateBilling();
  }
  showToast(action.do_not_bill ? '算定しないにしました' : '算定対象に戻しました', 'info');
}

function showProcedureActionDetail(index) {
  const action = selectedActions[index];
  if (!action) return;
  const comments = getActionComments(action);
  const lines = [
    `名称: ${action.name || ''}`,
    `コード: ${action.code || '-'}`,
    `区分: ${action.category || '-'}`,
    `点数: ${Number(action.points || 0)}点`,
    `回数: ${Number(action.quantity || 1)}回`,
    `算定: ${isActionDoNotBill(action) ? '算定しない' : '算定する'}`
  ];
  if (comments.length) {
    lines.push('コメント:');
    comments.forEach(comment => {
      const isKarteComment = isKarteProcedureComment(comment);
      const positionLabel = isKarteComment
        ? 'カルテ'
        : isPrescriptionRemarkOnlyComment(comment)
          ? PRESCRIPTION_COMMENT_REMARK_LABEL
          : (PROCEDURE_COMMENT_POSITION_LABELS[normalizeReceiptPosition(comment.position)] || '摘要欄内');
      lines.push(`- ${positionLabel} ${getProcedureCommentDisplayName(comment)}`);
    });
  }
  window.alert(lines.join('\n'));
}

function normalizePrescriptionInfoPayload(value) {
  if (!value) return null;
  if (typeof value === 'object') return value;
  if (typeof value !== 'string') return null;
  try {
    const parsed = JSON.parse(value);
    return parsed && typeof parsed === 'object' ? parsed : null;
  } catch (error) {
    return null;
  }
}

function getPrescriptionInfoSources(prescription, master) {
  const sources = [prescription, master];
  [prescription, master].forEach(source => {
    if (!source || typeof source !== 'object') return;
    [
      source.payload,
      source.metadata,
      source.drug_master,
      source.drugMaster,
      source.master,
      source.raw
    ].forEach(value => {
      const parsed = normalizePrescriptionInfoPayload(value);
      if (parsed) sources.push(parsed);
    });
  });
  return sources.filter(source => source && typeof source === 'object');
}

function readRawPrescriptionInfoField(prescription, master, keys = []) {
  const sources = getPrescriptionInfoSources(prescription, master);
  for (const source of sources) {
    for (const key of keys) {
      if (Object.prototype.hasOwnProperty.call(source, key)) {
        return source[key];
      }
    }
  }
  return null;
}

function firstPrescriptionInfoValue(...values) {
  for (const value of values) {
    if (Array.isArray(value)) {
      const items = value
        .map(item => firstPrescriptionInfoValue(item))
        .filter(Boolean);
      if (items.length) return items.join('\n');
      continue;
    }
    if (value === undefined || value === null) continue;
    if (typeof value === 'boolean') {
      if (value) return 'あり';
      continue;
    }
    if (typeof value === 'object') {
      const named = firstPrescriptionInfoValue(value.name, value.label, value.text, value.value);
      if (named) return named;
      continue;
    }
    const text = String(value).trim();
    if (!text || text === '-' || text.toLowerCase() === 'null' || text.toLowerCase() === 'undefined') continue;
    return text;
  }
  return '';
}

function readPrescriptionInfoField(prescription, master, keys = []) {
  for (const source of getPrescriptionInfoSources(prescription, master)) {
    for (const key of keys) {
      const value = firstPrescriptionInfoValue(source[key]);
      if (value) return value;
    }
  }
  return '';
}

const prescriptionDrugInfoLabels = [
  '商品名',
  '一般名',
  'メーカー',
  '効能・効果',
  '用法・用量',
  '副作用',
  '適用上の注意',
  '警告',
  '禁忌',
  '用法・用量に関連する注意',
  '重要な基本的注意',
  '特定の背景を有する患者に関する注意',
  '相互作用',
  '過量投与',
  '取扱い上の注意',
  '保険給付上の注意'
];

function parsePrescriptionDrugInfoText(value) {
  const text = firstPrescriptionInfoValue(value);
  if (!text) return {};

  const sections = {};
  let currentLabel = '';
  text.split(/\r?\n/).forEach(line => {
    const trimmed = line.trim();
    if (!trimmed || trimmed === '薬剤情報') return;
    const heading = trimmed.match(/^【([^】]+)】(.*)$/);
    const label = heading
      ? prescriptionDrugInfoLabels.find(item => item === heading[1])
      : prescriptionDrugInfoLabels.find(item => trimmed === item || trimmed.startsWith(`${item}:`) || trimmed.startsWith(`${item}：`) || trimmed.startsWith(`${item}\t`));
    if (label) {
      currentLabel = label;
      const body = (heading ? heading[2] : trimmed.slice(label.length)).replace(/^[\t 　:：]+/, '');
      sections[label] = [sections[label], body].filter(Boolean).join('\n');
      return;
    }
    if (currentLabel) {
      sections[currentLabel] = [sections[currentLabel], line].filter(Boolean).join('\n');
    }
  });
  return sections;
}

function readPrescriptionDetailSourceText(prescription, master) {
  return readPrescriptionInfoField(prescription, master, [
    'drug_information',
    'drugInformation',
    'drug_info',
    'drugInfo',
    'detail_info',
    'detailInfo',
    'description',
    'description_text'
  ]);
}

function readPrescriptionDrugInfoSection(prescription, master, label, keys, parsedSections) {
  return firstPrescriptionInfoValue(
    readPrescriptionInfoField(prescription, master, keys),
    parsedSections[label]
  );
}

function isTruthyPrescriptionInfoFlag(value) {
  if (value === true || value === 1) return true;
  const text = String(value || '').trim().toLowerCase();
  return ['1', 'true', 'yes', 'y', 'あり', '有', '対象', '○'].includes(text);
}

function readPrescriptionInfoFlagLabel(prescription, master, explicitKeys, flagKeys, trueLabel) {
  const explicit = readPrescriptionInfoField(prescription, master, explicitKeys);
  if (explicit) return explicit;
  return flagKeys.some(key => isTruthyPrescriptionInfoFlag(readRawPrescriptionInfoField(prescription, master, [key])))
    ? trueLabel
    : '';
}

function formatPrescriptionGenericNameForMaster(value, prescription = null, master = null) {
  const text = firstPrescriptionInfoValue(value);
  const masterItem = prescription ? findGeneralPrescriptionMasterItemForPrescription(prescription, master) : null;
  const standardName = firstNonEmptyString(masterItem?.standard_name, masterItem?.standardName, text);
  return standardName ? ensureGeneralNamePrescriptionPrefix(standardName) : '';
}

function formatPrescriptionInfoPrice(value) {
  const amount = normalizeDrugPriceValue(value);
  if (amount <= 0) return '';
  return Number.isInteger(amount) ? String(amount) : String(amount);
}

let prescriptionInfoRequestId = 0;
let prescriptionInfoReturnFocus = null;

function ensurePrescriptionInfoModal() {
  let overlay = document.getElementById('prescription-info-modal');
  if (overlay) return overlay;

  overlay = document.createElement('div');
  overlay.id = 'prescription-info-modal';
  overlay.className = 'prescription-info-overlay hidden';
  overlay.innerHTML = `
    <div class="prescription-info-modal" role="dialog" aria-modal="true" aria-labelledby="prescription-info-title">
      <div class="prescription-info-header">
        <h3 id="prescription-info-title"></h3>
        <button type="button" class="prescription-info-close" title="閉じる" aria-label="閉じる">&times;</button>
      </div>
      <div class="prescription-info-body" tabindex="0" aria-label="薬剤情報の本文"></div>
      <div class="prescription-info-footer hidden">
        <span class="prescription-info-source"></span>
        <button type="button" class="btn prescription-info-footer-close">閉じる</button>
      </div>
    </div>
  `;
  overlay.addEventListener('click', event => {
    if (event.target === overlay) closePrescriptionInfoModal();
  });
  overlay.querySelector('.prescription-info-close')?.addEventListener('click', closePrescriptionInfoModal);
  overlay.querySelector('.prescription-info-footer-close')?.addEventListener('click', closePrescriptionInfoModal);
  overlay.addEventListener('keydown', event => {
    if (event.key === 'Escape') {
      event.preventDefault();
      event.stopPropagation();
      closePrescriptionInfoModal();
    } else if (event.key === 'Tab') {
      const first = overlay.querySelector('.prescription-info-close');
      const last = overlay.querySelector('.prescription-info-footer').classList.contains('hidden')
        ? overlay.querySelector('.prescription-info-body')
        : overlay.querySelector('.prescription-info-footer-close');
      if (event.shiftKey && document.activeElement === first) {
        event.preventDefault();
        last.focus();
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault();
        first.focus();
      }
    }
  });
  document.body.appendChild(overlay);
  return overlay;
}

function closePrescriptionInfoModal() {
  prescriptionInfoRequestId += 1;
  document.getElementById('prescription-info-modal')?.classList.add('hidden');
  if (prescriptionInfoReturnFocus?.isConnected) prescriptionInfoReturnFocus.focus();
  prescriptionInfoReturnFocus = null;
}

function renderPrescriptionInfoRows(rows) {
  return `
    <table class="prescription-info-table">
      <tbody>
        ${rows.map(row => {
          const label = Array.isArray(row) ? row[0] : row.label;
          const value = Array.isArray(row) ? row[1] : row.value;
          const rowOptions = Array.isArray(row) ? (row[2] || {}) : row;
          const plain = rowOptions.plain || !label;
          const classes = [
            plain ? 'prescription-info-row-plain' : '',
            rowOptions.long ? 'prescription-info-row-long' : ''
          ].filter(Boolean).join(' ');
          const displayValue = firstPrescriptionInfoValue(value);
          return `
            <tr class="${classes}">
              <th scope="row">${escapeHtml(label || '')}</th>
              <td>${escapeHtml(rowOptions.preserveText ? displayValue : formatHalfWidthNumericText(displayValue))}</td>
            </tr>
          `;
        }).join('')}
      </tbody>
    </table>
  `;
}

function openPrescriptionInfoModal({ title, rows = [], variant = 'master', showFooter = false, status = '', error = false, source = '' }) {
  const overlay = ensurePrescriptionInfoModal();
  const wasHidden = overlay.classList.contains('hidden');
  if (wasHidden) prescriptionInfoReturnFocus = document.activeElement;
  const modal = overlay.querySelector('.prescription-info-modal');
  modal?.classList.toggle('prescription-info-modal-detail', variant === 'detail');
  overlay.querySelector('#prescription-info-title').textContent = title;
  const body = overlay.querySelector('.prescription-info-body');
  body.innerHTML = status
    ? `<p class="prescription-info-status" role="${error ? 'alert' : 'status'}">${escapeHtml(status)}</p>`
    : renderPrescriptionInfoRows(rows);
  body.setAttribute('aria-busy', status && !error ? 'true' : 'false');
  overlay.querySelector('.prescription-info-source').textContent = source;
  overlay.querySelector('.prescription-info-footer')?.classList.toggle('hidden', !showFooter);
  body.scrollTop = 0;
  overlay.classList.remove('hidden');
  if (wasHidden) overlay.querySelector('.prescription-info-close').focus();
  return ++prescriptionInfoRequestId;
}

function getPrescriptionInfoCodeKeys() {
  return ['drug_code', 'code', 'yj_code', 'yjCode', 'hot_code', 'hotCode', 'receipt_code', 'receiptCode'];
}

function findPrescriptionCurrentDrugMasterRow(prescription) {
  if (!prescription) return null;
  const prescriptionKeys = getPrescriptionInfoCodeKeys()
    .map(key => String(prescription[key] || '').trim())
    .filter(Boolean);
  const name = String(prescription.drug_name || prescription.name || '').trim();

  return (currentDrugOrderList || []).find(drug => {
    const drugKeys = getPrescriptionInfoCodeKeys()
      .map(key => String(drug[key] || '').trim())
      .filter(Boolean);
    const drugName = String(drug.drug_name || drug.name || '').trim();
    return prescriptionKeys.length
      ? prescriptionKeys.some(key => drugKeys.includes(key))
      : (name && drugName === name);
  }) || null;
}

async function resolvePrescriptionDrugMasterRow(prescription, { requireFresh = false } = {}) {
  const cached = findPrescriptionCurrentDrugMasterRow(prescription) || {};
  const code = readPrescriptionInfoField(prescription, cached, ['drug_code', 'code']);
  if (!code || typeof PrescriptionAPI === 'undefined' || typeof PrescriptionAPI.getDrug !== 'function') {
    if (requireFresh) throw new Error('Drug master lookup unavailable');
    return cached;
  }

  try {
    const result = await PrescriptionAPI.getDrug(code);
    const fetched = result?.data || result || {};
    if (requireFresh) {
      if (String(fetched.drug_code || '') !== String(code)) throw new Error('Drug master code mismatch');
      return fetched;
    }
    return { ...cached, ...fetched };
  } catch (error) {
    if (requireFresh) throw error;
    console.warn('医薬品マスタ詳細取得エラー:', error);
    return cached;
  }
}

function getPrescriptionInfoDrugName(prescription, master) {
  return readPrescriptionInfoField(prescription, master, ['drug_name', 'name', 'name_short', 'nameShort']);
}

function getPrescriptionInfoGenericName(prescription, master) {
  return readPrescriptionInfoField(prescription, master, ['generic_name', 'genericName', 'common_name', 'commonName']);
}

function getPrescriptionInfoManufacturer(prescription, master) {
  return readPrescriptionInfoField(prescription, master, ['manufacturer', 'maker', 'maker_name', 'makerName', 'company', 'company_name']);
}

function buildPrescriptionMasterInfoRows(prescription, master) {
  const unitPrice = getPrescriptionUnitPrice(prescription);
  const masterPrice = readRawPrescriptionInfoField(prescription, master, ['price', 'unit_price', 'unitPrice', 'drug_price', 'drugPrice']);
  const genericName = getPrescriptionInfoGenericName(prescription, master);
  const generalPrescriptionMaster = findGeneralPrescriptionMasterItemForPrescription(prescription, master);
  const generalPrescriptionLowestPrice = generalPrescriptionMaster?.lowest_price
    ?? generalPrescriptionMaster?.lowestPrice
    ?? readRawPrescriptionInfoField(prescription, master, [
      'generic_prescription_lowest_price',
      'genericPrescriptionLowestPrice',
      'lowest_price',
      'lowestPrice',
      'minimum_price',
      'minimumPrice',
      'minimum_drug_price'
    ]);
  return [
    ['医薬品コード', readPrescriptionInfoField(prescription, master, ['drug_code', 'code'])],
    ['名称', getPrescriptionInfoDrugName(prescription, master)],
    ['単位名', readPrescriptionInfoField(prescription, master, ['unit', 'dosage_unit', 'unit_name', 'unitName'])],
    ['薬価', formatPrescriptionInfoPrice(unitPrice || masterPrice)],
    ['麻毒区分', readPrescriptionInfoFlagLabel(
      prescription,
      master,
      ['narcotic_category', 'narcoticCategory', 'ma_doku_kubun', 'narcotic_type', 'narcoticType'],
      ['is_narcotic', 'isNarcotic', 'is_poison', 'isPoison', 'is_stimulant', 'isStimulant'],
      '麻薬'
    )],
    ['向精神薬区分', readPrescriptionInfoFlagLabel(
      prescription,
      master,
      ['psychotropic_category', 'psychotropicCategory', 'psychotropic_type', 'psychotropicType'],
      ['is_psychotropic', 'isPsychotropic'],
      '向精神薬'
    )],
    ['一般名', formatPrescriptionGenericNameForMaster(genericName, prescription, master)],
    ['一般処方加算区分', firstNonEmptyString(generalPrescriptionMaster?.addition_category, generalPrescriptionMaster?.additionCategory) || readPrescriptionInfoField(prescription, master, [
      'generic_prescription_addition_category',
      'genericPrescriptionAdditionCategory',
      'generic_addition_category',
      'genericAdditionCategory'
    ])],
    ['最低薬価', formatPrescriptionInfoPrice(generalPrescriptionLowestPrice)],
    ['▪同一規格品情報', readPrescriptionInfoField(prescription, master, ['same_standard_info', 'sameStandardInfo', 'same_standard_drugs', 'sameStandardDrugs'])]
  ];
}

function getPrescriptionInfoEffectText(prescription, master) {
  return readPrescriptionInfoField(prescription, master, [
    'efficacy_effect',
    'efficacyEffects',
    'efficacy',
    'effect',
    'effects',
    'indication',
    'indications',
    'effect_text',
    'effectText'
  ]);
}

function buildPrescriptionDrugSupplementalText(prescription, master) {
  const supplementalRows = [
    ['薬効分類', readPrescriptionInfoField(prescription, master, ['therapeutic_name', 'therapeuticName'])],
    ['薬効分類コード', readPrescriptionInfoField(prescription, master, ['therapeutic_category', 'therapeuticCategory'])],
    ['剤形', readPrescriptionInfoField(prescription, master, ['dosage_form', 'dosageForm'])],
    ['レセプト電算コード', readPrescriptionInfoField(prescription, master, ['receipt_code', 'receiptCode'])],
    ['YJコード', readPrescriptionInfoField(prescription, master, ['yj_code', 'yjCode'])],
    ['HOTコード', readPrescriptionInfoField(prescription, master, ['hot_code', 'hotCode'])],
    ['経過措置終了日', readPrescriptionInfoField(prescription, master, ['expiry_date', 'expiryDate'])]
  ].filter(([, value]) => value);

  if (supplementalRows.length) {
    return supplementalRows.map(([label, value]) => `${label}: ${value}`).join('\n');
  }
  return '薬剤マスタに詳細情報が登録されていません。';
}

function appendPrescriptionDrugInfoSection(base, label, text) {
  const value = firstPrescriptionInfoValue(text);
  if (!value || base.includes(value)) return base;
  return [base, `（${label}）\n${value}`].filter(Boolean).join('\n\n');
}

function buildPrescriptionDetailInfoRows(prescription, master) {
  // Clinical text must come from the fetched product, not a saved prescription snapshot.
  if (master && Object.keys(master).length) prescription = master;
  const parsedSections = parsePrescriptionDrugInfoText(readPrescriptionDetailSourceText(prescription, master));
  let usageDosage = readPrescriptionDrugInfoSection(prescription, master, '用法・用量', [
    'usage_dosage',
    'usageDosage',
    'dosage_usage',
    'dosageUsage',
    'usage_and_dosage',
    'usageAndDosage',
    'dose_and_administration',
    'doseAndAdministration',
    'dosage_detail',
    'dosageDetail'
  ], parsedSections);
  usageDosage = appendPrescriptionDrugInfoSection(usageDosage, '用法・用量に関連する注意',
    readPrescriptionDrugInfoSection(prescription, master, '用法・用量に関連する注意', ['dosage_precautions', 'dosagePrecautions'], parsedSections));
  const sideEffects = readPrescriptionDrugInfoSection(prescription, master, '副作用', [
    'side_effects',
    'sideEffects',
    'adverse_reactions',
    'adverseReactions',
    'adverse_effects',
    'adverseEffects'
  ], parsedSections);
  let applicationPrecautions = readPrescriptionDrugInfoSection(prescription, master, '適用上の注意', [
    'application_precautions',
    'applicationPrecautions',
    'precautions',
    'cautions',
    'precautions_for_use',
    'precautionsForUse'
  ], parsedSections);
  [
    ['警告', ['warnings']],
    ['禁忌', ['contraindications']],
    ['重要な基本的注意', ['important_precautions', 'importantPrecautions']],
    ['特定の背景を有する患者に関する注意', ['specific_populations', 'specificPopulations']],
    ['相互作用', ['interactions']],
    ['過量投与', ['overdosage']],
    ['取扱い上の注意', ['storage_precautions', 'storagePrecautions']],
    ['保険給付上の注意', ['insurance_note', 'insuranceNote']]
  ].forEach(([label, keys]) => {
    applicationPrecautions = appendPrescriptionDrugInfoSection(applicationPrecautions, label,
      readPrescriptionDrugInfoSection(prescription, master, label, keys, parsedSections));
  });
  const rows = [
    ['商品名', firstPrescriptionInfoValue(getPrescriptionInfoDrugName(prescription, master), parsedSections['商品名']), { preserveText: true }],
    ['一般名', firstPrescriptionInfoValue(getPrescriptionInfoGenericName(prescription, master).replace(/^【般】/, ''), parsedSections['一般名']), { preserveText: true }],
    ['メーカー', firstPrescriptionInfoValue(getPrescriptionInfoManufacturer(prescription, master), parsedSections['メーカー']), { preserveText: true }],
    ['効能・効果', firstPrescriptionInfoValue(getPrescriptionInfoEffectText(prescription, master), parsedSections['効能・効果']), { long: true, preserveText: true }],
    ['用法・用量', usageDosage, { long: true, preserveText: true }],
    ['副作用', sideEffects, { long: true, preserveText: true }],
    ['適用上の注意', applicationPrecautions, { long: true, preserveText: true }]
  ];
  const hasRegisteredDetail = rows.slice(3).some(([, value]) => firstPrescriptionInfoValue(value));
  if (!hasRegisteredDetail) {
    rows.push(['補足情報', buildPrescriptionDrugSupplementalText(prescription, master), { long: true, preserveText: true }]);
  }
  return rows.map(([label, value, options]) => [label, value || '登録情報なし', options]);
}

async function showPrescriptionInfo(index, variant) {
  const prescription = pendingPrescriptions[index];
  if (!prescription) return;
  const isDetail = variant === 'detail';
  const options = { title: isDetail ? '薬剤情報' : '医薬品マスタ情報', variant, showFooter: isDetail };
  const requestId = openPrescriptionInfoModal({ ...options, status: '薬剤情報を読み込んでいます。' });
  try {
    const master = await resolvePrescriptionDrugMasterRow(prescription, { requireFresh: isDetail });
    if (requestId !== prescriptionInfoRequestId) return;
    const sourceName = readPrescriptionInfoField(master, null, ['drug_information_source']);
    const updatedAt = readPrescriptionInfoField(master, null, ['drug_information_updated_at']);
    openPrescriptionInfoModal({
      ...options,
      rows: isDetail ? buildPrescriptionDetailInfoRows(prescription, master) : buildPrescriptionMasterInfoRows(prescription, master),
      source: isDetail ? [sourceName, updatedAt ? `情報更新日：${updatedAt}` : ''].filter(Boolean).join(' / ') : ''
    });
  } catch (error) {
    if (requestId !== prescriptionInfoRequestId) return;
    openPrescriptionInfoModal({ ...options, error: true, status: '薬剤情報を取得できませんでした。接続と医薬品コードを確認し、詳細情報を開き直してください。' });
  }
}

async function showPrescriptionMasterInfo(index) {
  return showPrescriptionInfo(index, 'master');
}

async function showPrescriptionDetail(index) {
  return showPrescriptionInfo(index, 'detail');
}

function showProcedureEntryDetail(index, kind = 'action') {
  if (kind === 'prescription') {
    showPrescriptionDetail(index);
    return;
  }
  showProcedureActionDetail(index);
}

function readProcedureEntryOrder(item) {
  const value = Number(item?.procedure_order ?? item?.procedureOrder ?? item?.sort_order ?? item?.sortOrder);
  return Number.isFinite(value) && value > 0 ? value : null;
}

function setProcedureEntryOrder(item, order) {
  if (!item || !Number.isFinite(Number(order))) return;
  const value = Number(order);
  item.procedure_order = value;
  item.procedureOrder = value;
}

function refreshProcedureEntryOrderCounter() {
  const maxOrder = [...selectedActions, ...pendingPrescriptions]
    .map(readProcedureEntryOrder)
    .filter(value => Number.isFinite(value))
    .reduce((max, value) => Math.max(max, value), procedureEntryOrderCounter);
  procedureEntryOrderCounter = maxOrder;
}

function nextProcedureEntryOrder() {
  refreshProcedureEntryOrderCounter();
  procedureEntryOrderCounter += 1;
  return procedureEntryOrderCounter;
}

function isAutoCalculatedProcedureAction(item) {
  const source = String(item?.source || item?.billing_source || '').trim();
  if (source === 'auto_calculation') return true;

  const name = String(item?.name || item?.billing_name || '');
  return /^(調剤料|薬剤料|処方料|初診料|再診料|外来感染対策向上加算|連携強化加算|発熱患者等対応加算|乳幼児加算|医療情報取得加算|機能強化加算|休日加算|時間外加算|深夜加算)/.test(name);
}

function getProcedureEntrySortOrder(item, kind, originalIndex = 0) {
  const assigned = readProcedureEntryOrder(item);
  if (assigned !== null) return assigned;

  const fallbackIndex = Number(originalIndex) || 0;
  if (kind === 'prescription') return 500000 + fallbackIndex;
  if (kind === 'action' && isAutoCalculatedProcedureAction(item)) return 900000 + fallbackIndex;
  return 100000 + fallbackIndex;
}

function assignMissingProcedureEntryOrdersFromDom() {
  refreshProcedureEntryOrderCounter();
  const container = document.getElementById('procedure-items');
  if (container) {
    container.querySelectorAll('.procedure-entry-row[data-index]').forEach(row => {
      const index = Number(row.dataset.index);
      if (!Number.isInteger(index)) return;
      const item = row.classList.contains('rx-procedure-item')
        ? pendingPrescriptions[index]
        : selectedActions[index];
      if (item && readProcedureEntryOrder(item) === null) {
        setProcedureEntryOrder(item, nextProcedureEntryOrder());
      }
    });
  }

  selectedActions.forEach(action => {
    if (readProcedureEntryOrder(action) === null) {
      setProcedureEntryOrder(action, nextProcedureEntryOrder());
    }
  });
  pendingPrescriptions.forEach(prescription => {
    if (readProcedureEntryOrder(prescription) === null) {
      setProcedureEntryOrder(prescription, nextProcedureEntryOrder());
    }
  });
}

function assignProcedureEntryOrderForAppend(item) {
  assignMissingProcedureEntryOrdersFromDom();
  if (readProcedureEntryOrder(item) === null) {
    setProcedureEntryOrder(item, nextProcedureEntryOrder());
  }
}

function insertProcedureElement(container, element) {
  const allBtn = container.querySelector('.proc-delete-all-btn');
  const order = Number(element?.dataset?.entryOrder);
  if (Number.isFinite(order)) {
    const orderedSiblings = Array.from(container.children)
      .filter(child => child !== allBtn && child.dataset?.entryOrder !== undefined);
    const nextSibling = orderedSiblings.find(child => {
      const siblingOrder = Number(child.dataset.entryOrder);
      return Number.isFinite(siblingOrder) && siblingOrder > order;
    });
    if (nextSibling) {
      container.insertBefore(element, nextSibling);
      return;
    }
  }

  if (allBtn) {
    container.insertBefore(element, allBtn);
  } else {
    container.appendChild(element);
  }
}

function normalizeDrugPriceValue(value) {
  if (value === undefined || value === null || value === '') return 0;
  const amount = Number(String(value).replace(/[^\d.-]/g, ''));
  return Number.isFinite(amount) && amount > 0 ? amount : 0;
}

function getPrescriptionUnitPrice(prescription) {
  const directPrice = normalizeDrugPriceValue(
    prescription?.unit_price
    ?? prescription?.unitPrice
    ?? prescription?.drug_price
    ?? prescription?.drugPrice
    ?? prescription?.price
  );
  if (directPrice > 0) return directPrice;

  const code = String(prescription?.drug_code || prescription?.code || '').trim();
  const name = String(prescription?.drug_name || prescription?.name || '').trim();
  const cached = (currentDrugOrderList || []).find(drug => {
    const drugCode = String(drug.drug_code || drug.code || '').trim();
    const drugName = String(drug.drug_name || drug.name || '').trim();
    return (code && drugCode === code) || (name && drugName === name);
  });
  return normalizeDrugPriceValue(cached?.price ?? cached?.unit_price ?? cached?.drug_price);
}

function setPrescriptionUnitPrice(prescription, unitPrice) {
  const price = normalizeDrugPriceValue(unitPrice);
  if (!prescription || price <= 0) return;
  prescription.unit_price = price;
  prescription.unitPrice = price;
  prescription.drug_price = price;
  prescription.drugPrice = price;
  prescription.price = price;
}

function getPrescriptionPriceLookupKeys(prescription) {
  return [
    prescription?.drug_code,
    prescription?.code,
    prescription?.yj_code,
    prescription?.hot_code,
    prescription?.drug_name,
    prescription?.name
  ]
    .map(value => String(value || '').trim())
    .filter(Boolean);
}

async function ensureInternalPrescriptionPricesForBilling() {
  if (typeof PrescriptionAPI === 'undefined') return false;

  const targets = (pendingPrescriptions || []).filter(prescription =>
    normalizePrescriptionDispensingType(prescription) === '院内'
    && getPrescriptionPriceLookupKeys(prescription).length > 0
  );
  if (targets.length === 0) return false;

  let updated = false;
  for (const prescription of targets) {
    const dated = await PrescriptionAPI.getDatedDrugPrice(
      prescription.drug_code || prescription.code, getCurrentKarteDateValue());
    setPrescriptionUnitPrice(prescription, dated.price);
    prescription.total_price = Number(dated.price) * calculatePrescriptionDrugTotalQuantity(prescription);
    updated = true;
  }

  return updated;
}

function calculatePrescriptionDrugTotalQuantity(prescription) {
  if (inferPrescriptionDrugType(prescription) === '外用') {
    return Number(prescription?.dosage_quantity ?? prescription?.quantity ?? parseFloat(prescription?.dosage)) || 0;
  }
  const existing = Number(prescription?.total_quantity ?? prescription?.totalQuantity);
  if (Number.isFinite(existing) && existing > 0) return existing;
  return calculatePrescriptionQuantity(
    prescription?.dosage_quantity ?? prescription?.quantity ?? parseFloat(prescription?.dosage),
    prescription?.frequency,
    prescription?.days
  );
}

function calculatePrescriptionDrugTotalPrice(prescription) {
  const unitPrice = getPrescriptionUnitPrice(prescription);
  if (unitPrice <= 0) return 0;
  return unitPrice * calculatePrescriptionDrugTotalQuantity(prescription);
}

function calculateDrugFeePointsFromPrice(priceYen) {
  const price = Number(priceYen);
  if (!Number.isFinite(price) || price <= 0) return 0;
  if (price <= 15) return 1;
  return 1 + Math.ceil((price - 15) / 10);
}

function getInternalPrescriptionFeeBasis(prescription) {
  const unitPrice = getPrescriptionUnitPrice(prescription);
  if (unitPrice <= 0) return null;

  const drugType = inferPrescriptionDrugType(prescription);
  const dosageQuantity = Number(prescription?.dosage_quantity ?? prescription?.quantity ?? parseFloat(prescription?.dosage) ?? 1) || 1;
  const days = Math.max(1, Number(prescription?.days || 1) || 1);
  const timesPerDay = Math.max(1, getPrescriptionTimesPerDay(prescription?.frequency));

  if (drugType === '外用') {
    return {
      unitPrice,
      drugType,
      basisPrice: unitPrice * calculatePrescriptionDrugTotalQuantity(prescription),
      units: 1,
      unitLabel: '調剤'
    };
  }

  if (drugType === '頓服' || isAsNeededPrescriptionFrequency(prescription?.frequency)) {
    return {
      unitPrice,
      drugType: '頓服',
      basisPrice: unitPrice * dosageQuantity,
      units: days,
      unitLabel: '回'
    };
  }

  return {
    unitPrice,
    drugType: drugType === '注射' ? '注射' : '内服',
    basisPrice: unitPrice * dosageQuantity * timesPerDay,
    units: days,
    unitLabel: '日'
  };
}

function getInternalPrescriptionDrugFeeGroupKey(prescription, index) {
  const drugType = inferPrescriptionDrugType(prescription);
  if (drugType === '内服' && !isAsNeededPrescriptionFrequency(prescription?.frequency)) {
    const groupId = getPrescriptionGroupId(prescription);
    if (groupId) return `oral:${groupId}:${prescription.days}:${prescription.frequency}`;
  }
  return `${drugType || 'drug'}:${prescription?.prescription_item_id || prescription?.drug_code || index}`;
}

function buildInternalPrescriptionDrugFeeBillingItems() {
  const groups = new Map();
  (pendingPrescriptions || []).forEach((prescription, index) => {
    if (normalizePrescriptionDispensingType(prescription) !== '院内') return;
    const basis = getInternalPrescriptionFeeBasis(prescription);
    if (!basis) return;

    const key = getInternalPrescriptionDrugFeeGroupKey(prescription, index);
    const group = groups.get(key) || {
      key,
      prescriptions: [],
      drugType: basis.drugType,
      basisPrice: 0,
      units: basis.units,
      unitLabel: basis.unitLabel
    };
    group.prescriptions.push(prescription);
    group.basisPrice += basis.basisPrice;
    group.units = Math.max(group.units, basis.units);
    group.unitLabel = basis.unitLabel;
    groups.set(key, group);
  });

  return Array.from(groups.values())
    .flatMap((group, groupIndex) => {
      const unitPoints = calculateDrugFeePointsFromPrice(group.basisPrice);
      const units = Math.max(1, Number(group.units || 1));
      const subtotal = unitPoints * units;
      if (subtotal <= 0) return [];

      return group.prescriptions.map((member, index) => {
        const last = index === group.prescriptions.length - 1;
        const basis = getInternalPrescriptionFeeBasis(member);
        const memberPoints = last ? unitPoints : 0;
        return {
        code: member.drug_code || member.code,
        name: `薬剤料（院内）：${member.drug_name || member.name}`,
        category: group.drugType,
        points: memberPoints,
        quantity: units,
        subtotal: memberPoints * units,
        subtotalAmount: memberPoints * units * 10,
        isSelfPay: false,
        item_type: 'drug',
        drug_code: member.drug_code || member.code || '',
        drug_name: member.drug_name || member.name,
        drug_quantity: basis.basisPrice / basis.unitPrice,
        drug_unit: member.unit,
        billing_group_id: `rx:${groupIndex}`,
        billing_group_parent_id: last ? null : `rx:${groupIndex}`,
        unit_price: Number(group.basisPrice.toFixed(2)),
        drug_price: Number(group.basisPrice.toFixed(2)),
        receipt_position: 'summary',
        comments: [],
        comment_codes: [],
        free_comment: '',
        source: 'internal_prescription_drug_fee'
      };
      });
    })
    .filter(Boolean);
}

function isPrescriptionDrugFeeBillingItem(item) {
  return item?.item_type === 'drug'
    || item?.source === 'internal_prescription_drug_fee'
    || String(item?.name || item?.billing_name || '').startsWith('薬剤料（院内）');
}

function buildBillingItemsFromCurrentOrders() {
  const actionItems = selectedActions
    .filter(action => !isPrescriptionDrugFeeBillingItem(action))
    .map(action => {
      syncActionDerivedFields(action);
      const quantity = Number(action.quantity || 1);
      const points = Number(action.points || 0);
      const isSelfPay = action.isSelfPay || action.item_type === 'self_pay' || action.category === '自費';
      const amount = Number(action.unit_price || action.price || action.amount || 0);
      const doNotBill = isActionDoNotBill(action);
      const comments = getActionComments(action);
      const enteredComments = getEnteredProcedureComments(comments);
      const claimCommentCodes = getClaimCommentCodes(enteredComments);
      const claimFreeComment = getClaimFreeCommentText(enteredComments);
      const hasCommentRows = comments.length > 0;
      return {
        code: action.code,
        category: action.category || '診察',
        name: action.name,
        points,
        amount,
        isSelfPay,
        item_type: action.item_type || (isSelfPay ? 'self_pay' : ''),
        quantity,
        subtotal: doNotBill ? 0 : points * quantity,
        subtotalAmount: doNotBill ? 0 : (isSelfPay ? amount * quantity : points * quantity * 10),
        comments: enteredComments,
        comment_codes: hasCommentRows ? claimCommentCodes : (action.comment_codes || []),
        free_comment: (hasCommentRows ? claimFreeComment : action.free_comment) || '',
        receipt_position: hasCommentRows
          ? getClaimReceiptPosition(enteredComments, action.receipt_position)
          : normalizeReceiptPosition(action.receipt_position || 'summary'),
        do_not_bill: doNotBill,
        billing_group_id: action.billing_group_id || '',
        billing_group_parent_id: action.billing_group_parent_id || '',
        billing_group_label: action.billing_group_label || '',
        procedure_order: readProcedureEntryOrder(action),
        sort_order: readProcedureEntryOrder(action),
        source: action.source || ''
      };
    });

  return [
    ...actionItems,
    ...buildInternalPrescriptionDrugFeeBillingItems()
  ];
}

function calculateCurrentOrderPoints() {
  return buildBillingItemsFromCurrentOrders().reduce((sum, item) => sum + (item.subtotal || 0), 0);
}

// 診療行為の選択を切り替え
// 処置・行為パネルに選択した診療行為を表示
function renderSelectedActionsInProcedure() {
  const container = document.getElementById('procedure-items');
  if (!container) return;

  // 既存の行為表示をクリア（処方以外）
  container.querySelectorAll('.procedure-action-group, .procedure-action-item, .procedure-derived-item').forEach(el => el.remove());

  // 下部の全削除ボタンは上部ツールバーと重複するため表示しない。
  container.querySelector('.proc-delete-all-btn')?.remove();

  const selectedProcedureKey = getSelectedProcedureSelectionKey();

  groupSelectedActionsForDisplay().forEach(group => {
    const wrapper = document.createElement('div');
    wrapper.className = [
      'procedure-action-group',
      group.actions.length > 1 ? 'grouped' : '',
      group.isManual ? 'manual-grouped' : '',
      group.key === selectedProcedureKey ? 'is-group-anchor-selected' : ''
    ].filter(Boolean).join(' ');
    wrapper.dataset.groupKey = group.key;
    wrapper.dataset.entryOrder = String(group.entryOrder);
    wrapper.dataset.manualGroupId = group.isManual
      ? (getManualBillingGroupId(group.actions[0]?.action) || '')
      : '';
    const groupAnchorIndex = group.actions[0]?.originalIndex;
    if (groupAnchorIndex !== undefined) {
      wrapper.title = 'クリックして追加先のグループにする';
      wrapper.onclick = event => selectProcedureGroupAnchor(event, groupAnchorIndex);
    }

    const rows = group.actions.map(({ action, originalIndex }, rowIndex) => {
      if (!action.quantity) action.quantity = 1;
      syncActionDerivedFields(action);
      const displayCategory = getProcedureDisplayCategory(action);
      const iconClass = getProcedureIconClass(displayCategory);
      const points = Number(action.points || 0);
      const amount = Number(action.amount || action.price || action.unit_price || 0);
      const isSelfPay = action.isSelfPay || action.item_type === 'self_pay' || action.category === '自費';
      const doNotBill = isActionDoNotBill(action);
      const displayValue = doNotBill
        ? '算定外'
        : (isSelfPay && amount > 0 ? `¥${amount.toLocaleString()}` : (points > 0 ? points + '点' : '-'));
      const tag = getProcedureActionTag(action);
      const tagHtml = tag ? `<span class="proc-kind-tag">${escapeHtml(tag)}</span>` : '';
      const warningHtml = renderProcedureActionWarnings(action, originalIndex);
      const commentsHtml = renderProcedureActionComments(action, originalIndex);
      const rowClass = [
        doNotBill ? 'is-not-billable' : '',
        isManualBillingGroupChild(action) ? 'is-manual-group-child' : ''
      ].filter(Boolean).join(' ');
      const rowClassAttr = rowClass ? ` ${rowClass}` : '';
      if (isSelfPay) {
        return `
          <div class="m3-proc-item procedure-action-item self-pay-proc-item procedure-entry-row${rowClassAttr}" data-index="${originalIndex}" data-code="${escapeHtml(action.code || '')}">
            ${renderProcedureRowMoveButtons(originalIndex, rowIndex, group.actions.length)}
            ${renderProcedureActionIcon(displayCategory, iconClass, originalIndex)}
            <span class="procedure-action-text">
              <span class="procedure-action-mainline"><span class="m3-proc-name">${escapeHalfWidthNumericText(action.name)}</span>${warningHtml}</span>
              ${commentsHtml}
            </span>
            <div class="self-pay-proc-controls">
              <label class="self-pay-proc-field">
                <input class="self-pay-proc-input self-pay-proc-amount" type="text" inputmode="numeric" data-numeric-pad="integer" data-min="0" value="${amount}" autocomplete="off"
                       oninput="updateSelfPayActionAmount(${originalIndex}, this.value)">
                <span>円</span>
              </label>
              <label class="self-pay-proc-field">
                <input class="self-pay-proc-input self-pay-proc-quantity" type="text" inputmode="numeric" data-numeric-pad="integer" data-min="1" value="${Number(action.quantity || 1)}" autocomplete="off"
                       oninput="updateSelfPayActionQuantity(${originalIndex}, this.value)">
                <span>回</span>
              </label>
            </div>
            <button type="button" class="proc-item-delete-btn" onclick="event.stopPropagation(); deleteProcedureItem(${originalIndex})" title="この項目を削除">
              <i class="fas fa-times"></i>
            </button>
          </div>
        `;
      }
      return `
        <div class="m3-proc-item procedure-action-item procedure-entry-row${rowClassAttr}" data-index="${originalIndex}" data-code="${escapeHtml(action.code || '')}">
          ${renderProcedureRowMoveButtons(originalIndex, rowIndex, group.actions.length)}
          ${renderProcedureActionIcon(displayCategory, iconClass, originalIndex)}
          <span class="procedure-action-text">
            <span class="procedure-action-mainline">${tagHtml}<span class="m3-proc-name">${escapeHalfWidthNumericText(action.name)}</span>${warningHtml}</span>
            ${commentsHtml}
          </span>
          <span class="m3-proc-pts">${displayValue}</span>
          <button type="button" class="proc-item-delete-btn" onclick="event.stopPropagation(); deleteProcedureItem(${originalIndex})" title="この項目を削除">
            <i class="fas fa-times"></i>
          </button>
        </div>
      `;
    }).join('');

    const groupQuantity = Number(group.actions[0]?.action.quantity || 1);
    const footer = shouldShowProcedureQuantityFooter(group) ? `
      <div class="procedure-group-footer">
        <span class="proc-group-count-cluster">
          <input class="proc-group-count-input" type="text" inputmode="numeric" data-numeric-pad="integer" data-min="1" value="${groupQuantity}" autocomplete="off"
                 onchange="updateProcedureGroupQuantity('${escapeHtml(group.key)}', this.value)">
          <span class="proc-group-count-unit">回</span>
        </span>
        <button type="button" class="procedure-group-delete-btn" onclick="event.stopPropagation(); deleteProcedureGroup('${escapeHtml(group.key)}')" title="${escapeHtml(group.label)}を削除">
          <i class="fas fa-trash"></i>
        </button>
      </div>
    ` : '';

    wrapper.innerHTML = rows + footer;
    insertProcedureElement(container, wrapper);
  });

  renderPendingPrescriptionsInProcedure();
}

function updateSelfPayActionAmount(index, value) {
  const action = selectedActions[index];
  if (!action) return;
  const amount = Math.max(0, Math.floor(Number(value) || 0));
  action.amount = amount;
  action.price = amount;
  action.unit_price = amount;
  action.isSelfPay = true;
  action.item_type = 'self_pay';
  action.category = '自費';
  updateTotalPoints();
  saveCurrentPatientBilling();
  if (!document.getElementById('billing-modal')?.classList.contains('hidden')) {
    calculateBilling();
  }
}

function updateSelfPayActionQuantity(index, value) {
  const action = selectedActions[index];
  if (!action) return;
  const quantity = Math.max(1, Math.floor(Number(value) || 1));
  action.quantity = quantity;
  action.isSelfPay = true;
  action.item_type = 'self_pay';
  action.category = '自費';
  updateTotalPoints();
  saveCurrentPatientBilling();
  if (!document.getElementById('billing-modal')?.classList.contains('hidden')) {
    calculateBilling();
  }
}

window.updateSelfPayActionAmount = updateSelfPayActionAmount;
window.updateSelfPayActionQuantity = updateSelfPayActionQuantity;

function shouldIgnoreProcedureRowSelection(event) {
  return Boolean(event?.target?.closest('button, input, select, textarea, a, label'));
}

function promoteManualBillingGroupAnchor(action) {
  const groupId = getManualBillingGroupId(action);
  if (!groupId) return;
  ensureProcedureActionIdentity(action);
  const groupLabel = action.name || getManualBillingGroupLabel(action) || '算定';

  selectedActions.forEach(member => {
    if (getManualBillingGroupId(member) !== groupId) return;
    ensureProcedureActionIdentity(member);
    member.billing_group_id = groupId;
    member.billingGroupId = groupId;
    member.billing_group_label = groupLabel;
    member.billingGroupLabel = groupLabel;
    if (member === action) {
      member.billing_group_parent_id = '';
      member.billingGroupParentId = '';
    } else {
      member.billing_group_parent_id = action.procedure_item_id;
      member.billingGroupParentId = action.procedure_item_id;
    }
  });
}

function selectProcedureGroupAnchor(event, index) {
  if (shouldIgnoreProcedureRowSelection(event)) return;
  const action = selectedActions[index];
  if (!action) return;
  syncActionDerivedFields(action);
  ensureProcedureActionIdentity(action);
  const selectedKey = getSelectedProcedureSelectionKey();
  const clickedKey = getProcedureSelectionKey(action);

  if (selectedKey === clickedKey) {
    selectedProcedureGroupAnchorId = null;
    renderSelectedActionsInProcedure();
    return;
  }

  selectedPrescriptionGroupAnchorId = null;
  const groupId = getManualBillingGroupId(action);
  if (groupId) {
    const parent = selectedActions.find(member =>
      getManualBillingGroupId(member) === groupId && !isManualBillingGroupChild(member)
    ) || action;
    ensureProcedureActionIdentity(parent);
    selectedProcedureGroupAnchorId = parent.procedure_item_id;
  } else {
    selectedProcedureGroupAnchorId = action.procedure_item_id;
  }
  renderSelectedActionsInProcedure();
  renderPendingPrescriptionsInProcedure();
}

function normalizeManualBillingGroupAfterChange(groupId) {
  if (!groupId) return;
  const members = selectedActions.filter(action => getManualBillingGroupId(action) === groupId);
  if (members.length <= 1) {
    members.forEach(action => {
      action.billing_group_id = '';
      action.billingGroupId = '';
      action.billing_group_parent_id = '';
      action.billingGroupParentId = '';
      action.billing_group_label = '';
      action.billingGroupLabel = '';
    });
    return;
  }

  let parent = members.find(action => !isManualBillingGroupChild(action));
  if (!parent || !selectedActions.includes(parent)) {
    parent = members[0];
  }
  ensureProcedureActionIdentity(parent);
  const groupLabel = getManualBillingGroupLabel(parent) || parent.name || '算定';
  parent.billing_group_id = groupId;
  parent.billingGroupId = groupId;
  parent.billing_group_parent_id = '';
  parent.billingGroupParentId = '';
  parent.billing_group_label = groupLabel;
  parent.billingGroupLabel = groupLabel;

  members.forEach(action => {
    if (action === parent) return;
    action.billing_group_id = groupId;
    action.billingGroupId = groupId;
    action.billing_group_parent_id = parent.procedure_item_id;
    action.billingGroupParentId = parent.procedure_item_id;
    action.billing_group_label = groupLabel;
    action.billingGroupLabel = groupLabel;
  });
  rememberBillingGroupSuggestion(groupId, { bump: false });
}

function moveProcedureItemInGroup(index, direction) {
  const currentIndex = Number(index);
  const step = Number(direction);
  const action = selectedActions[currentIndex];
  if (!action || !step) return;

  const groupKey = getActionClaimGroupKey(action);
  const groupIndexes = selectedActions
    .map((item, itemIndex) => ({ item, itemIndex }))
    .filter(({ item }) => getActionClaimGroupKey(item) === groupKey)
    .map(({ itemIndex }) => itemIndex);
  const position = groupIndexes.indexOf(currentIndex);
  const nextPosition = position + step;
  if (position < 0 || nextPosition < 0 || nextPosition >= groupIndexes.length) return;

  const targetIndex = groupIndexes[nextPosition];
  [selectedActions[currentIndex], selectedActions[targetIndex]] = [selectedActions[targetIndex], selectedActions[currentIndex]];
  renderSelectedActionsInProcedure();
  updateTotalPoints();
  saveCurrentPatientBilling();
  checkActionsRealtime();
}

// 処置行為を削除
function deleteProcedureItem(index) {
  if (selectedActions[index]) {
    const action = selectedActions[index];
    const removedGroupId = getManualBillingGroupId(action);
    const removedAnchorId = action.procedure_item_id;
    selectedActions.splice(index, 1);
    if (selectedProcedureGroupAnchorId === removedAnchorId) {
      selectedProcedureGroupAnchorId = null;
    }
    normalizeManualBillingGroupAfterChange(removedGroupId);
    renderSelectedActionsInProcedure();
    updateTotalPoints();
    saveCurrentPatientBilling();
    showToast(`${action.name}を削除しました`, 'info');
  }
}

// 全ての処置行為・薬を削除
async function deleteAllProcedureItems() {
  const hasActions = selectedActions.length > 0;
  const hasPrescriptions = pendingPrescriptions.length > 0;
  if (!hasActions && !hasPrescriptions) return;

  const deleteTargetLabel = hasActions && hasPrescriptions
    ? '算定項目と薬'
    : hasPrescriptions
      ? '薬'
      : '算定項目';

  const confirmed = await showAppConfirm({
    title: `${deleteTargetLabel}の全削除`,
    message: `全ての${deleteTargetLabel}を削除しますか？`,
    confirmText: '削除',
    cancelText: 'キャンセル'
  });
  if (!confirmed) return;

  selectedActions = [];
  selectedProcedureGroupAnchorId = null;
  selectedPrescriptionGroupAnchorId = null;
  pendingPrescriptions.length = 0;
  procedureEntryOrderCounter = 0;
  renderSelectedActionsInProcedure();
  updateTotalPoints();
  saveCurrentPatientBilling();
  checkActionsRealtime();
  checkPrescriptionsRealtime();
  showToast(`全ての${deleteTargetLabel}を削除しました`, 'info');
}

window.moveProcedureItemInGroup = moveProcedureItemInGroup;
window.selectProcedureGroupAnchor = selectProcedureGroupAnchor;
window.deleteProcedureItem = deleteProcedureItem;
window.deleteAllProcedureItems = deleteAllProcedureItems;
window.toggleProcedureActionMenu = toggleProcedureActionMenu;
window.removeProcedureActionComment = removeProcedureActionComment;
window.removePrescriptionComment = removePrescriptionComment;
window.updateProcedureActionCommentText = updateProcedureActionCommentText;
window.updatePrescriptionCommentText = updatePrescriptionCommentText;
window.autoResizeProcedureCommentInput = autoResizeProcedureCommentInput;

function updateProcedureGroupQuantity(groupKey, value) {
  const quantity = Math.max(1, Number(value) || 1);
  let updatedGroupId = '';
  selectedActions.forEach(action => {
    if (getActionClaimGroupKey(action) === groupKey) {
      action.quantity = quantity;
      updatedGroupId = getManualBillingGroupId(action) || updatedGroupId;
    }
  });
  if (updatedGroupId) rememberBillingGroupSuggestion(updatedGroupId, { bump: false });
  renderSelectedActionsInProcedure();
  updateTotalPoints();
  saveCurrentPatientBilling();
}

function deleteProcedureGroup(groupKey) {
  const removed = selectedActions.filter(action => getActionClaimGroupKey(action) === groupKey);
  selectedActions = selectedActions.filter(action => getActionClaimGroupKey(action) !== groupKey);
  if (removed.some(action => action.procedure_item_id === selectedProcedureGroupAnchorId)) {
    selectedProcedureGroupAnchorId = null;
  }
  renderSelectedActionsInProcedure();
  updateTotalPoints();
  saveCurrentPatientBilling();
  if (removed.length) showToast(`${getActionClaimGroupLabel(removed[0])}の算定を削除しました`, 'info');
}

window.updateProcedureGroupQuantity = updateProcedureGroupQuantity;
window.deleteProcedureGroup = deleteProcedureGroup;

// 合計点数を更新
function updateTotalPoints() {
  const total = calculateCurrentOrderPoints();

  // selectedItemsも更新（後方互換性）
  selectedItems = buildBillingItemsFromCurrentOrders().map(item => ({
    name: item.name,
    code: item.code,
    points: item.points,
    amount: item.amount,
    isSelfPay: item.isSelfPay,
    item_type: item.item_type,
    quantity: item.quantity || 1,
    comments: item.comments || [],
    comment_codes: item.comment_codes || [],
    free_comment: item.free_comment || '',
    receipt_position: item.receipt_position || 'summary',
    do_not_bill: Boolean(item.do_not_bill),
    billing_group_id: item.billing_group_id || '',
    billing_group_parent_id: item.billing_group_parent_id || '',
    billing_group_label: item.billing_group_label || '',
    procedure_order: readProcedureEntryOrder(item),
    sort_order: readProcedureEntryOrder(item),
    source: item.source || ''
  }));

  // 表示を更新
  const totalEl = document.getElementById('total-points');
  if (totalEl) {
    totalEl.textContent = `合計: ${total}点`;
  }
}

// 診療行為を検索
async function searchMedicalActions(query) {
  const entryVersion = orderZoneEntryVersion;
  if (currentOrderCategory === 'medication') {
    await loadDrugsForMedication(query || '');
    return;
  }

  if (!query || query.length < 2) {
    if (currentOrderCategory === 'set') {
      renderSetTree();
    } else {
      await loadMedicalActionsByCategory(currentOrderCategory);
    }
    return;
  }

  const container = document.getElementById('category-tree');
  if (!container) return;

  container.innerHTML = '<div class="loading"><i class="fas fa-spinner fa-spin"></i> 検索中...</div>';

  try {
    if (currentOrderCategory === 'medication') {
      await loadDrugsForMedication(query);
      return;
    }

    const result = await RecordActionAPI.search(query, currentOrderCategory === 'set' ? null : currentOrderCategory, 50);
    if (entryVersion !== orderZoneEntryVersion) return;
    const actions = getActionsFromResult(result, currentOrderCategory);

    if (actions.length === 0) {
      container.innerHTML = '<div class="no-data">該当する診療行為がありません</div>';
      return;
    }

    renderMedicalActions(actions, currentOrderCategory);

  } catch (error) {
    console.error('検索エラー:', error);
    if (entryVersion !== orderZoneEntryVersion) return;
    container.innerHTML = '<div class="no-data">診療行為マスターの検索に失敗しました</div>';
  }
}

// 全タブ横断の候補を表示
async function loadAllMedicalActions() {
  const entryVersion = orderZoneEntryVersion;
  const container = document.getElementById('category-tree');
  if (!container) return;

  document.querySelectorAll('.m3-header-zone-order .m3-panel-tab').forEach(tab => tab.classList.remove('active'));
  currentOrderCategory = 'all';
  container.innerHTML = '<div class="loading"><i class="fas fa-spinner fa-spin"></i> 全カテゴリを読み込み中...</div>';

  const categories = ['exam', 'home', 'injection', 'treatment', 'surgery', 'anesthesia', 'test', 'imaging', 'rehab'];
  const loaded = [];

  for (const category of categories) {
    try {
      const result = await RecordActionAPI.search('', category, 12);
      if (entryVersion !== orderZoneEntryVersion) return;
      loaded.push(...getActionsFromResult(result, category));
    } catch (error) {
      console.warn('診療行為カテゴリ取得エラー:', category, error);
    }
  }

  if (entryVersion !== orderZoneEntryVersion) return;
  const unique = [];
  const seen = new Set();
  loaded.forEach(rawAction => {
    const action = normalizeOrderAction(rawAction);
    const key = action.code || action.name;
    if (!key || seen.has(key)) return;
    seen.add(key);
    unique.push(action);
  });

  if (unique.length === 0) {
    container.innerHTML = '<div class="no-data">表示できる診療行為がありません</div>';
    return;
  }

  renderMedicalActions(unique);
}

// セット一覧を取得
async function loadActionSets(options = {}) {
  const entryVersion = orderZoneEntryVersion;
  const shouldRender = options.render ?? currentOrderCategory === 'set';
  const [actionSetResult, karteSetResult] = await Promise.allSettled([
    RecordActionAPI.getSets(),
    typeof KarteSetAPI !== 'undefined' ? KarteSetAPI.list() : Promise.resolve([])
  ]);

  if (actionSetResult.status === 'fulfilled') {
    const result = actionSetResult.value;
    actionSets = (Array.isArray(result) ? result : (result.data || [])).filter(isVisibleOrderSet);
  } else {
    console.error('診療行為セット取得エラー:', actionSetResult.reason);
    actionSets = [];
  }

  if (karteSetResult.status === 'fulfilled') {
    const result = karteSetResult.value;
    karteSets = (Array.isArray(result) ? result : (result.data || [])).filter(isVisibleOrderSet);
  } else {
    console.error('カルテセット取得エラー:', karteSetResult.reason);
    karteSets = [];
  }

  if (shouldRender && entryVersion === orderZoneEntryVersion) {
    renderSetTree();
  }
}

function getOrderSetKey(kind, set) {
  return `${kind}:${set?.id || ''}`;
}

function getOrderSetDisplayName(kind, set) {
  const key = getOrderSetKey(kind, set);
  return orderSetViewState.setNameOverrides[key] || set?.set_name || set?.name || 'セット';
}

function normalizeOrderSetFolderName(value) {
  return String(value || '').trim();
}

function normalizeOrderSetFolderSegment(value) {
  return String(value || '')
    .replace(/[\\/]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function formatOrderSetFolderLabel(folder) {
  return normalizeOrderSetFolderName(folder).split('/').filter(Boolean).join(' / ');
}

function getOrderSetFolderFromDescription(set) {
  const description = String(set?.description || '').trim();
  const match = description.match(/^フォルダ:\s*(.+)$/);
  return match ? normalizeOrderSetFolderName(match[1]) : '';
}

function getOrderSetFolder(kind, set, key = getOrderSetKey(kind, set)) {
  return normalizeOrderSetFolderName(set?.folder)
    || normalizeOrderSetFolderName(orderSetViewState.setFolders?.[key])
    || getOrderSetFolderFromDescription(set);
}

function getAllOrderSetFolderNames() {
  const savedFolders = (orderSetViewState.folders || []).map(normalizeOrderSetFolderName).filter(Boolean);
  const detected = [
    ...karteSets.map(set => getOrderSetFolder('karte', set)),
    ...actionSets.map(set => getOrderSetFolder('action', set))
  ].map(normalizeOrderSetFolderName).filter(Boolean);
  const setParents = [
    ...karteSets.map(set => ({ kind: 'karte', set })),
    ...actionSets.map(set => ({ kind: 'action', set }))
  ].map(({ kind, set }) => {
    const key = getOrderSetKey(kind, set);
    if ((orderSetViewState.hiddenSetKeys || []).includes(key)) return '';
    const name = normalizeOrderSetFolderSegment(getOrderSetDisplayName(kind, set));
    if (!name) return '';
    const folder = getOrderSetFolder(kind, set, key);
    return folder ? `${folder}/${name}` : name;
  }).filter(Boolean);
  const expandWithParents = folders => folders.flatMap(folder => {
    const parts = folder.split('/').map(part => part.trim()).filter(Boolean);
    return parts.map((_, index) => parts.slice(0, index + 1).join('/'));
  });

  return Array.from(new Set([
    ...expandWithParents(savedFolders),
    ...expandWithParents(detected),
    ...expandWithParents(setParents)
  ]))
    .sort((a, b) => {
      const aSavedIndex = savedFolders.indexOf(a);
      const bSavedIndex = savedFolders.indexOf(b);
      if (aSavedIndex !== -1 || bSavedIndex !== -1) {
        if (aSavedIndex === -1) return 1;
        if (bSavedIndex === -1) return -1;
        return aSavedIndex - bSavedIndex;
      }
      return a.localeCompare(b, 'ja');
    });
}

function getVisibleOrderSetEntries() {
  const hiddenKeys = new Set(orderSetViewState.hiddenSetKeys || []);
  const entries = [
    ...karteSets.map(set => {
      const key = getOrderSetKey('karte', set);
      return { kind: 'karte', set, key, folder: getOrderSetFolder('karte', set, key) };
    }),
    ...actionSets.map(set => {
      const key = getOrderSetKey('action', set);
      return { kind: 'action', set, key, folder: getOrderSetFolder('action', set, key) };
    })
  ].filter(entry => !hiddenKeys.has(entry.key));

  const savedOrder = orderSetViewState.topOrder || [];
  const orderIndex = new Map(savedOrder.map((key, index) => [key, index]));
  const sourceIndex = new Map(entries.map((entry, index) => [entry.key, index]));
  return entries.sort((a, b) => {
    const aIndex = orderIndex.has(a.key) ? orderIndex.get(a.key) : Number.MAX_SAFE_INTEGER;
    const bIndex = orderIndex.has(b.key) ? orderIndex.get(b.key) : Number.MAX_SAFE_INTEGER;
    if (aIndex !== bIndex) return aIndex - bIndex;
    return (sourceIndex.get(a.key) || 0) - (sourceIndex.get(b.key) || 0);
  });
}

function getActionSetItemKey(item, index) {
  return String(item?.action?.code || item?.code || item?.action_code || `${index}:${item?.name || item?.action?.name || 'item'}`);
}

function getActionSetItemName(item) {
  return item?.name || item?.action?.name || item?.action_name || 'セット項目';
}

function getSetItemHierarchyLabels(name) {
  const normalized = String(name || '')
    .replace(/\u3000/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  if (!normalized) return ['セット項目'];

  const parts = normalized.split(' ');
  if (parts.length <= 1) return [normalized];
  return parts.map((_, index) => parts.slice(0, index + 1).join(' '));
}

function isOrderSetNodeHidden(setKey, nodePath) {
  const hidden = new Set(orderSetViewState.hiddenNodeKeys || []);
  const pathParts = String(nodePath || '').split('/').filter(Boolean);
  return pathParts.some((_, index) => hidden.has(`${setKey}|${pathParts.slice(0, index + 1).join('/')}`));
}

function getNodeOrderStorageKey(setKey, parentPath) {
  return `${setKey}|${parentPath || 'root'}`;
}

function applyNodeOrder(nodes, setKey, parentPath = '') {
  const saved = orderSetViewState.nodeOrders?.[getNodeOrderStorageKey(setKey, parentPath)] || [];
  const orderIndex = new Map(saved.map((key, index) => [key, index]));
  nodes.sort((a, b) => {
    const aIndex = orderIndex.has(a.nodeKey) ? orderIndex.get(a.nodeKey) : Number.MAX_SAFE_INTEGER;
    const bIndex = orderIndex.has(b.nodeKey) ? orderIndex.get(b.nodeKey) : Number.MAX_SAFE_INTEGER;
    if (aIndex !== bIndex) return aIndex - bIndex;
    return a.label.localeCompare(b.label, 'ja');
  });
  nodes.forEach(node => applyNodeOrder(node.children, setKey, node.nodePath));
  return nodes;
}

function buildActionSetTree(set, setKey) {
  const root = { children: [], childMap: new Map(), nodePath: '' };
  (set.items || []).forEach((item, index) => {
    const itemKey = getActionSetItemKey(item, index);
    const labels = getSetItemHierarchyLabels(getActionSetItemName(item));
    let parent = root;
    let parentPath = '';

    labels.forEach((label, labelIndex) => {
      const isLeaf = labelIndex === labels.length - 1;
      const nodeKey = isLeaf ? `item:${itemKey}` : `group:${label}`;
      const nodePath = parentPath ? `${parentPath}/${nodeKey}` : nodeKey;

      if (!parent.childMap.has(nodeKey)) {
        parent.childMap.set(nodeKey, {
          nodeKey,
          nodePath,
          parentPath,
          label,
          children: [],
          childMap: new Map(),
          itemIndex: null,
          itemKey: null
        });
        parent.children.push(parent.childMap.get(nodeKey));
      }

      const node = parent.childMap.get(nodeKey);
      if (isLeaf) {
        node.itemIndex = index;
        node.itemKey = itemKey;
        node.item = item;
      }
      parent = node;
      parentPath = nodePath;
    });
  });

  const pruneHidden = (nodes) => nodes
    .filter(node => !isOrderSetNodeHidden(setKey, node.nodePath))
    .map(node => ({ ...node, children: pruneHidden(node.children) }));

  root.children = pruneHidden(root.children);
  return applyNodeOrder(root.children, setKey);
}

function getNodeDisplayLabel(setKey, node) {
  return orderSetViewState.nodeLabelOverrides?.[`${setKey}|${node.nodePath}`] || node.label;
}

function renderMoveButtons(attrs, index, total) {
  const common = Object.entries(attrs)
    .map(([key, value]) => `${key}="${escapeHtml(value)}"`)
    .join(' ');
  return `
    <span class="m3-tree-order-buttons">
      <button type="button" class="m3-tree-move-btn" ${common} data-direction="-1" ${index <= 0 ? 'disabled' : ''} title="上へ" aria-label="上へ"><i class="fas fa-caret-up"></i></button>
      <button type="button" class="m3-tree-move-btn" ${common} data-direction="1" ${index >= total - 1 ? 'disabled' : ''} title="下へ" aria-label="下へ"><i class="fas fa-caret-down"></i></button>
    </span>
  `;
}

function renderActionSetNode(set, setKey, node, depth, index, siblingsTotal) {
  const hasChildren = node.children.length > 0;
  const label = getNodeDisplayLabel(setKey, node);
  const moveAttrs = {
    'data-tree-action': 'move-node',
    'data-set-key': setKey,
    'data-parent-path': node.parentPath || '',
    'data-node-key': node.nodeKey
  };
  const applyAttrs = node.itemIndex !== null
    ? `data-tree-action="apply-node" data-set-id="${escapeHtml(set.id)}" data-item-index="${escapeHtml(node.itemIndex)}"`
    : 'data-tree-action="toggle"';

  return `
    <div class="m3-tree-node-item" data-node-path="${escapeHtml(node.nodePath)}">
      <div class="m3-tree-row m3-tree-leaf ${hasChildren ? 'has-children' : 'is-leaf'}" style="--tree-depth:${depth}">
        ${renderMoveButtons(moveAttrs, index, siblingsTotal)}
        <button type="button" class="m3-tree-toggle ${hasChildren ? '' : 'spacer'}" data-tree-action="${hasChildren ? 'toggle' : 'noop'}" title="${hasChildren ? '開閉' : ''}">
          ${hasChildren ? '<i class="fas fa-caret-right"></i>' : ''}
        </button>
        <span class="m3-tree-label" ${applyAttrs}>${escapeHtml(label)}</span>
        <span class="karte-set-actions">
          <button type="button" class="karte-set-action-btn" data-tree-action="edit-node" data-set-key="${escapeHtml(setKey)}" data-node-path="${escapeHtml(node.nodePath)}" data-current-label="${escapeHtml(label)}" title="編集" aria-label="編集">
            <i class="fas fa-pencil-alt"></i>
          </button>
          <button type="button" class="karte-set-action-btn danger" data-tree-action="delete-node" data-set-key="${escapeHtml(setKey)}" data-node-path="${escapeHtml(node.nodePath)}" data-current-label="${escapeHtml(label)}" title="削除" aria-label="削除">
            <i class="fas fa-trash-alt"></i>
          </button>
        </span>
      </div>
      ${hasChildren ? `<div class="m3-tree-children">${node.children.map((child, childIndex) => renderActionSetNode(set, setKey, child, depth + 1, childIndex, node.children.length)).join('')}</div>` : ''}
    </div>
  `;
}

function getTreeDepthInlineStyle(depth) {
  const level = Number(depth || 0);
  return level > 0 ? ` style="padding-left: calc(4px + (${level} * 14px));"` : '';
}

function renderOrderSetEntry(entry, index, total, depth = 0) {
  const { kind, set, key } = entry;
  const isActionSet = kind === 'action';
  const name = getOrderSetDisplayName(kind, set);
  const nodes = isActionSet ? buildActionSetTree(set, key) : [];
  const hasChildren = nodes.length > 0;
  const moveAttrs = {
    'data-tree-action': 'move-set',
    'data-set-key': key
  };

  return `
    <div class="m3-tree-item" data-set-key="${escapeHtml(key)}" data-set-kind="${escapeHtml(kind)}" data-set-id="${escapeHtml(set.id)}">
      <div class="m3-tree-row m3-tree-header ${isActionSet ? 'action-set-header' : 'karte-set-header'}"${getTreeDepthInlineStyle(depth)}>
        ${renderMoveButtons(moveAttrs, index, total)}
        <button type="button" class="m3-tree-toggle ${hasChildren ? '' : 'spacer'}" data-tree-action="${hasChildren ? 'toggle' : 'noop'}" title="${hasChildren ? '開閉' : ''}">
          ${hasChildren ? '<i class="fas fa-caret-right"></i>' : ''}
        </button>
        <span class="karte-set-name" data-tree-action="${kind === 'karte' ? 'apply-karte-set' : hasChildren ? 'toggle' : 'noop'}" data-set-id="${escapeHtml(set.id)}">${escapeHtml(name)}</span>
        <span class="karte-set-actions">
          <button type="button" class="karte-set-action-btn" data-tree-action="edit-set" data-set-key="${escapeHtml(key)}" data-set-kind="${escapeHtml(kind)}" data-set-id="${escapeHtml(set.id)}" title="編集" aria-label="編集">
            <i class="fas fa-pencil-alt"></i>
          </button>
          <button type="button" class="karte-set-action-btn danger" data-tree-action="delete-set" data-set-key="${escapeHtml(key)}" data-set-kind="${escapeHtml(kind)}" data-set-id="${escapeHtml(set.id)}" title="削除" aria-label="削除">
            <i class="fas fa-trash-alt"></i>
          </button>
        </span>
      </div>
      ${hasChildren ? `<div class="m3-tree-children">${nodes.map((node, nodeIndex) => renderActionSetNode(set, key, node, 1, nodeIndex, nodes.length)).join('')}</div>` : ''}
    </div>
  `;
}

function renderOrderSetFolder(folder, folderEntries, allEntries, depth = 0) {
  return `
    <div class="m3-tree-item m3-set-folder" data-folder-name="${escapeHtml(folder)}">
      <div class="m3-tree-row m3-tree-header set-folder-header"${getTreeDepthInlineStyle(depth)}>
        <button type="button" class="m3-tree-toggle" data-tree-action="toggle" title="開閉">
          <i class="fas fa-caret-right"></i>
        </button>
        <span class="karte-set-name" data-tree-action="toggle">${escapeHtml(formatOrderSetFolderLabel(folder).split(' / ').pop() || folder)}</span>
      </div>
      <div class="m3-tree-children">
        ${folderEntries.map(entry => renderOrderSetEntry(entry, allEntries.findIndex(item => item.key === entry.key), allEntries.length, depth + 1)).join('')}
      </div>
    </div>
  `;
}

function buildOrderSetFolderTree(folderGroups) {
  const root = { children: [], childMap: new Map(), entries: [], path: '' };

  for (const [folderPath, entries] of folderGroups.entries()) {
    const parts = normalizeOrderSetFolderName(folderPath).split('/').map(part => part.trim()).filter(Boolean);
    let parent = root;
    let path = '';
    parts.forEach(part => {
      path = path ? `${path}/${part}` : part;
      if (!parent.childMap.has(part)) {
        const node = { label: part, path, children: [], childMap: new Map(), entries: [] };
        parent.childMap.set(part, node);
        parent.children.push(node);
      }
      parent = parent.childMap.get(part);
    });
    parent.entries.push(...entries);
  }

  const savedFolders = orderSetViewState.folders || [];
  const sortNodes = nodes => {
    nodes.sort((a, b) => {
      const aIndex = savedFolders.indexOf(a.path);
      const bIndex = savedFolders.indexOf(b.path);
      if (aIndex !== -1 || bIndex !== -1) {
        if (aIndex === -1) return 1;
        if (bIndex === -1) return -1;
        return aIndex - bIndex;
      }
      return a.label.localeCompare(b.label, 'ja');
    });
    nodes.forEach(node => sortNodes(node.children));
    return nodes;
  };

  return sortNodes(root.children);
}

function renderOrderSetFolderNode(node, allEntries, depth = 0) {
  const nestedFolders = node.children.map(child => renderOrderSetFolderNode(child, allEntries, depth + 1)).join('');
  const setRows = node.entries
    .map(entry => renderOrderSetEntry(entry, allEntries.findIndex(item => item.key === entry.key), allEntries.length, depth + 1))
    .join('');

  return `
    <div class="m3-tree-item m3-set-folder" data-folder-name="${escapeHtml(node.path)}">
      <div class="m3-tree-row m3-tree-header set-folder-header"${getTreeDepthInlineStyle(depth)}>
        <button type="button" class="m3-tree-toggle" data-tree-action="toggle" title="開閉">
          <i class="fas fa-caret-right"></i>
        </button>
        <span class="karte-set-name" data-tree-action="toggle">${escapeHtml(node.label)}</span>
      </div>
      <div class="m3-tree-children">
        ${nestedFolders}${setRows}
      </div>
    </div>
  `;
}

function getSetTreeExpansionKey(item) {
  if (!item) return '';
  if (item.classList.contains('m3-set-folder')) {
    return item.dataset.folderName ? `folder:${item.dataset.folderName}` : '';
  }
  if (item.classList.contains('m3-tree-node-item')) {
    const setItem = item.closest('.m3-tree-item[data-set-key]');
    return setItem?.dataset?.setKey && item.dataset.nodePath
      ? `node:${setItem.dataset.setKey}|${item.dataset.nodePath}`
      : '';
  }
  if (item.classList.contains('m3-tree-item')) {
    return item.dataset.setKey ? `set:${item.dataset.setKey}` : '';
  }
  return '';
}

function setSetTreeItemExpanded(item, expanded) {
  const children = item?.querySelector(':scope > .m3-tree-children');
  const icon = item?.querySelector(':scope > .m3-tree-row .m3-tree-toggle i');
  if (!children || !icon) return;

  children.classList.toggle('hidden', !expanded);
  item.classList.toggle('expanded', expanded);
  icon.className = expanded ? 'fas fa-caret-down' : 'fas fa-caret-right';
}

function captureSetTreeExpansion(container = document.getElementById('category-tree')) {
  if (!container?.classList?.contains('m3-set-tree')) return;
  if (!container.querySelector('.m3-tree-item, .m3-tree-node-item')) return;

  const expandedKeys = [];
  container.querySelectorAll('.m3-tree-item.expanded, .m3-tree-node-item.expanded').forEach(item => {
    const children = item.querySelector(':scope > .m3-tree-children');
    if (!children || children.classList.contains('hidden')) return;
    const key = getSetTreeExpansionKey(item);
    if (key) expandedKeys.push(key);
  });
  orderSetViewState.expandedTreeKeys = Array.from(new Set(expandedKeys));
  saveOrderSetViewState();
}

function applySetTreeExpansion(container) {
  const expandedKeys = new Set(orderSetViewState.expandedTreeKeys || []);
  container.querySelectorAll('.m3-tree-item, .m3-tree-node-item').forEach(item => {
    if (!item.querySelector(':scope > .m3-tree-children')) return;
    setSetTreeItemExpanded(item, expandedKeys.has(getSetTreeExpansionKey(item)));
  });
}

function rememberSetTreeItemExpansion(item, expanded) {
  const key = getSetTreeExpansionKey(item);
  if (!key) return;
  const expandedKeys = new Set(orderSetViewState.expandedTreeKeys || []);
  if (expanded) {
    expandedKeys.add(key);
  } else {
    expandedKeys.delete(key);
  }
  orderSetViewState.expandedTreeKeys = Array.from(expandedKeys);
  saveOrderSetViewState();
}

// セットツリーを表示
function renderSetTree() {
  const container = document.getElementById('category-tree');
  if (!container) return;
  captureSetTreeExpansion(container);

  const entries = getVisibleOrderSetEntries();
  if (entries.length === 0) {
    container.innerHTML = '<div class="no-data">セットがありません</div>';
    return;
  }

  const folderGroups = new Map();
  const rootCandidates = [];
  const rootEntries = [];
  entries.forEach(entry => {
    if (entry.folder) {
      if (!folderGroups.has(entry.folder)) folderGroups.set(entry.folder, []);
      folderGroups.get(entry.folder).push(entry);
    } else {
      rootCandidates.push(entry);
    }
  });

  rootCandidates.forEach(entry => {
    const candidateFolder = normalizeOrderSetFolderSegment(getOrderSetDisplayName(entry.kind, entry.set));
    const actsAsParent = candidateFolder && Array.from(folderGroups.keys())
      .some(folder => folder === candidateFolder || folder.startsWith(`${candidateFolder}/`));

    if (actsAsParent) {
      if (!folderGroups.has(candidateFolder)) folderGroups.set(candidateFolder, []);
      folderGroups.get(candidateFolder).unshift(entry);
    } else {
      rootEntries.push(entry);
    }
  });

  const folderTree = buildOrderSetFolderTree(folderGroups);

  const html = [
    ...folderTree.map(folder => renderOrderSetFolderNode(folder, entries)),
    ...rootEntries.map(entry => renderOrderSetEntry(entry, entries.findIndex(item => item.key === entry.key), entries.length))
  ].join('');

  container.classList.add('m3-set-tree');
  container.innerHTML = html;
  applySetTreeExpansion(container);
  bindSetTreeActionButtons(container);
}

function moveOrderSet(setKey, direction) {
  const entries = getVisibleOrderSetEntries();
  const keys = entries.map(entry => entry.key);
  const index = keys.indexOf(setKey);
  const nextIndex = index + Number(direction);
  if (index < 0 || nextIndex < 0 || nextIndex >= keys.length) return;

  [keys[index], keys[nextIndex]] = [keys[nextIndex], keys[index]];
  orderSetViewState.topOrder = keys;
  saveOrderSetViewState();
  renderSetTree();
}

function findActionSetEntry(setKey) {
  return getVisibleOrderSetEntries().find(entry => entry.key === setKey && entry.kind === 'action');
}

function findTreeNodeByPath(nodes, nodePath) {
  for (const node of nodes) {
    if (node.nodePath === nodePath) return node;
    const found = findTreeNodeByPath(node.children || [], nodePath);
    if (found) return found;
  }
  return null;
}

function moveOrderSetNode(setKey, parentPath, nodeKey, direction) {
  const entry = findActionSetEntry(setKey);
  if (!entry) return;

  const tree = buildActionSetTree(entry.set, setKey);
  const siblings = parentPath
    ? (findTreeNodeByPath(tree, parentPath)?.children || [])
    : tree;
  const keys = siblings.map(node => node.nodeKey);
  const index = keys.indexOf(nodeKey);
  const nextIndex = index + Number(direction);
  if (index < 0 || nextIndex < 0 || nextIndex >= keys.length) return;

  [keys[index], keys[nextIndex]] = [keys[nextIndex], keys[index]];
  orderSetViewState.nodeOrders[getNodeOrderStorageKey(setKey, parentPath)] = keys;
  saveOrderSetViewState();
  renderSetTree();
}

async function editOrderSet(kind, setId, setKey) {
  if (kind === 'karte') {
    await editKarteSetName(setId);
    return;
  }

  const entry = findActionSetEntry(setKey);
  if (!entry) return;
  const currentName = getOrderSetDisplayName(kind, entry.set);
  const nextName = prompt('セット名を入力してください', currentName)?.trim();
  if (!nextName || nextName === currentName) return;

  orderSetViewState.setNameOverrides[setKey] = nextName;
  saveOrderSetViewState();
  renderSetTree();
  showToast('セット名を更新しました', 'success');
}

async function deleteOrderSet(kind, setId, setKey) {
  if (kind === 'karte') {
    await deleteKarteSet(setId);
    return;
  }

  const entry = findActionSetEntry(setKey);
  const name = entry ? getOrderSetDisplayName(kind, entry.set) : 'セット';
  const ok = await showAppConfirm({
    title: 'セット削除',
    message: `${name} をセット一覧から削除しますか？`,
    confirmText: '削除',
    cancelText: 'キャンセル'
  });
  if (!ok) return;

  orderSetViewState.hiddenSetKeys = Array.from(new Set([...(orderSetViewState.hiddenSetKeys || []), setKey]));
  saveOrderSetViewState();
  renderSetTree();
  showToast('セットを削除しました', 'success');
}

function editOrderSetNode(setKey, nodePath, currentLabel) {
  const nextLabel = prompt('項目名を入力してください', currentLabel)?.trim();
  if (!nextLabel || nextLabel === currentLabel) return;
  orderSetViewState.nodeLabelOverrides[`${setKey}|${nodePath}`] = nextLabel;
  saveOrderSetViewState();
  renderSetTree();
  showToast('項目名を更新しました', 'success');
}

async function deleteOrderSetNode(setKey, nodePath, currentLabel) {
  const ok = await showAppConfirm({
    title: '項目削除',
    message: `${currentLabel} をセット一覧から削除しますか？`,
    confirmText: '削除',
    cancelText: 'キャンセル'
  });
  if (!ok) return;

  orderSetViewState.hiddenNodeKeys = Array.from(new Set([...(orderSetViewState.hiddenNodeKeys || []), `${setKey}|${nodePath}`]));
  saveOrderSetViewState();
  renderSetTree();
  showToast('項目を削除しました', 'success');
}

function bindSetTreeActionButtons(container) {
  if (container.dataset.setTreeBound === '1') return;
  container.dataset.setTreeBound = '1';

  container.addEventListener('click', async (event) => {
    const trigger = event.target.closest('[data-tree-action]');
    if (!trigger || !container.contains(trigger)) return;

    const action = trigger.dataset.treeAction;
    if (!action || action === 'noop') return;
    event.preventDefault();
    event.stopPropagation();

    if (action === 'toggle') {
      toggleTreeItem(trigger);
      return;
    }
    if (action === 'apply-karte-set') {
      await applyKarteSet(trigger.dataset.setId);
      return;
    }
    if (action === 'apply-node') {
      await applySetItem(trigger.dataset.setId, Number(trigger.dataset.itemIndex));
      return;
    }
    if (action === 'move-set') {
      moveOrderSet(trigger.dataset.setKey, Number(trigger.dataset.direction));
      return;
    }
    if (action === 'move-node') {
      moveOrderSetNode(trigger.dataset.setKey, trigger.dataset.parentPath || '', trigger.dataset.nodeKey, Number(trigger.dataset.direction));
      return;
    }
    if (action === 'edit-set') {
      await editOrderSet(trigger.dataset.setKind, trigger.dataset.setId, trigger.dataset.setKey);
      return;
    }
    if (action === 'delete-set') {
      await deleteOrderSet(trigger.dataset.setKind, trigger.dataset.setId, trigger.dataset.setKey);
      return;
    }
    if (action === 'edit-node') {
      editOrderSetNode(trigger.dataset.setKey, trigger.dataset.nodePath, trigger.dataset.currentLabel || 'セット項目');
      return;
    }
    if (action === 'delete-node') {
      await deleteOrderSetNode(trigger.dataset.setKey, trigger.dataset.nodePath, trigger.dataset.currentLabel || 'セット項目');
    }
  });
}

function bindKarteSetActionButtons(container) {
  container.querySelectorAll('[data-karte-set-edit]').forEach(button => {
    button.addEventListener('click', (event) => {
      event.preventDefault();
      event.stopPropagation();
      editKarteSetName(button.dataset.karteSetEdit);
    });
  });

  container.querySelectorAll('[data-karte-set-delete]').forEach(button => {
    button.addEventListener('click', (event) => {
      event.preventDefault();
      event.stopPropagation();
      deleteKarteSet(button.dataset.karteSetDelete);
    });
  });
}

function ensureKarteSetEditModal() {
  let modal = document.getElementById('karte-set-edit-modal');
  if (modal) return modal;

  modal = document.createElement('div');
  modal.id = 'karte-set-edit-modal';
  modal.className = 'modal hidden karte-set-edit-modal';
  modal.innerHTML = `
    <div class="karte-set-small-dialog">
      <div class="karte-set-register-header">
        <h3>セット編集</h3>
        <button type="button" class="karte-set-register-close" id="karte-set-edit-close" aria-label="閉じる">&times;</button>
      </div>
      <div class="karte-set-register-body">
        <label class="karte-set-register-row">
          <span>セット名</span>
          <input type="text" id="karte-set-edit-name">
        </label>
        <label class="karte-set-register-row">
          <span>フォルダ</span>
          <div class="karte-set-register-inline">
            <select id="karte-set-edit-folder"></select>
            <button type="button" class="karte-set-register-plus" id="karte-set-edit-folder-add" title="フォルダ追加">＋</button>
          </div>
        </label>
      </div>
      <div class="karte-set-register-footer">
        <button type="button" class="btn btn-outline" id="karte-set-edit-cancel">キャンセル</button>
        <button type="button" class="btn btn-primary" id="karte-set-edit-save">保存</button>
      </div>
    </div>
  `;
  document.body.appendChild(modal);

  modal.querySelector('#karte-set-edit-close')?.addEventListener('click', closeKarteSetEditModal);
  modal.querySelector('#karte-set-edit-cancel')?.addEventListener('click', closeKarteSetEditModal);
  modal.querySelector('#karte-set-edit-save')?.addEventListener('click', saveKarteSetEditFromModal);
  modal.querySelector('#karte-set-edit-folder-add')?.addEventListener('click', () => {
    karteSetFolderModalTargetSelectId = 'karte-set-edit-folder';
    openKarteSetFolderModal(document.getElementById('karte-set-edit-folder')?.value || '');
  });
  modal.addEventListener('click', event => {
    if (event.target === modal) closeKarteSetEditModal();
  });

  return modal;
}

function renderKarteSetEditFolders() {
  const select = document.getElementById('karte-set-edit-folder');
  if (!select) return;
  const folders = getAllOrderSetFolderNames();
  const currentValue = select.value || '';
  select.innerHTML = `
    <option value="">未選択</option>
    ${folders.map(folder => `<option value="${escapeHtml(folder)}">${escapeHtml(formatOrderSetFolderLabel(folder))}</option>`).join('')}
  `;
  select.value = folders.includes(currentValue) ? currentValue : '';
}

function openKarteSetEditModal(setId) {
  const set = karteSets.find(item => String(item.id) === String(setId));
  if (!set) return;

  const currentName = set.set_name || set.name || 'カルテセット';
  const setKey = getOrderSetKey('karte', set);
  const currentFolder = getOrderSetFolder('karte', set, setKey);
  karteSetEditState = { setId: set.id };

  const modal = ensureKarteSetEditModal();
  const nameInput = modal.querySelector('#karte-set-edit-name');
  if (nameInput) nameInput.value = currentName;
  renderKarteSetEditFolders();
  const folderSelect = modal.querySelector('#karte-set-edit-folder');
  if (folderSelect) folderSelect.value = currentFolder;

  modal.classList.remove('hidden');
  nameInput?.focus();
  nameInput?.select();
}

function closeKarteSetEditModal() {
  document.getElementById('karte-set-edit-modal')?.classList.add('hidden');
  karteSetEditState = { setId: null };
}

async function saveKarteSetEditFromModal() {
  const set = karteSets.find(item => String(item.id) === String(karteSetEditState.setId));
  if (!set) return;

  const currentName = set.set_name || set.name || 'カルテセット';
  const setKey = getOrderSetKey('karte', set);
  const currentFolder = getOrderSetFolder('karte', set, setKey);
  const nextName = document.getElementById('karte-set-edit-name')?.value.trim();
  const nextFolder = document.getElementById('karte-set-edit-folder')?.value || '';

  if (!nextName) {
    showToast('セット名を入力してください', 'error');
    document.getElementById('karte-set-edit-name')?.focus();
    return;
  }

  const updatePayload = {};
  if (nextName !== currentName) updatePayload.set_name = nextName;
  if (nextFolder !== currentFolder) updatePayload.folder = nextFolder || null;
  if (!Object.keys(updatePayload).length) return;

  try {
    showLoading();
    await KarteSetAPI.update(set.id, updatePayload);
    orderSetViewState.setFolders = orderSetViewState.setFolders || {};
    if (nextFolder) {
      orderSetViewState.folders = Array.from(new Set([...(orderSetViewState.folders || []), nextFolder]));
      orderSetViewState.setFolders[setKey] = nextFolder;
    } else {
      delete orderSetViewState.setFolders[setKey];
    }
    saveOrderSetViewState();
    await loadActionSets();
    hideLoading();
    closeKarteSetEditModal();
    showToast('セットを更新しました', 'success');
  } catch (error) {
    hideLoading();
    console.error('カルテセット編集エラー:', error);
    showToast('セットの更新に失敗しました: ' + error.message, 'error');
  }
}

function editKarteSetName(setId) {
  openKarteSetEditModal(setId);
}

async function deleteKarteSet(setId) {
  const set = karteSets.find(item => String(item.id) === String(setId));
  if (!set) return;

  const setName = set.set_name || set.name || 'カルテセット';
  const ok = await showAppConfirm({
    title: 'セット削除',
    message: `${setName} を削除しますか？`,
    confirmText: '削除',
    cancelText: 'キャンセル'
  });
  if (!ok) return;

  try {
    showLoading();
    await KarteSetAPI.delete(set.id);
    await loadActionSets();
    hideLoading();
    showToast('セットを削除しました', 'success');
  } catch (error) {
    hideLoading();
    console.error('カルテセット削除エラー:', error);
    showToast('セットの削除に失敗しました: ' + error.message, 'error');
  }
}

function composeKarteHtmlFromSet(set) {
  if (set.karte_html) return set.karte_html;

  const sections = [
    ['主訴', set.subjective],
    ['身体所見', set.objective],
    ['アセスメント', set.assessment],
    ['プラン', set.plan]
  ].filter(([, value]) => value);

  if (sections.length === 0) return getKarteTemplate();

  return sections
    .map(([label, value]) => `<p><strong>【${escapeHtml(label)}】</strong></p><p>${escapeHtml(value).replace(/\n/g, '<br>')}</p>`)
    .join('');
}

function normalizeBillingFromKarteSet(item) {
  const isSelfPay = Boolean(item.is_self_pay || item.isSelfPay || item.item_type === 'self_pay' || item.category === '自費');
  const unitAmount = Number(item.unit_price ?? item.price ?? item.amount ?? 0);
  return normalizeOrderAction({
    code: item.billing_code || item.code,
    name: item.billing_name || item.name,
    points: item.points,
    amount: unitAmount,
    price: unitAmount,
    unit_price: unitAmount,
    quantity: item.quantity || 1,
    category: item.category || (isSelfPay ? '自費' : '診察'),
    item_type: item.item_type || (isSelfPay ? 'self_pay' : ''),
    isSelfPay,
    comments: item.comments || item.comment_names || [],
    comment_codes: item.comment_codes || [],
    free_comment: item.free_comment || '',
    receipt_position: item.receipt_position || 'summary',
    do_not_bill: Boolean(item.do_not_bill),
    billing_group_id: item.billing_group_id || item.billingGroupId || '',
    billing_group_parent_id: item.billing_group_parent_id || item.billingGroupParentId || '',
    billing_group_label: item.billing_group_label || item.billingGroupLabel || ''
  }, 'set');
}

function normalizePrescriptionFromKarteSet(item) {
  const quantity = getPrescriptionInputQuantity(item);
  const days = Number(item.days);

  return {
    ...item,
    drug_code: item.drug_code || item.code || null,
    drug_name: item.drug_name || item.name || '',
    name: item.drug_name || item.name || '',
    dosage_quantity: Number.isFinite(quantity) && quantity > 0 ? quantity : 1,
    unit: item.unit || item.dosage_unit || '錠',
    dosage_unit: item.dosage_unit || item.unit || '錠',
    frequency: item.frequency || '[内] 1日3回毎食後',
    days: inferPrescriptionDrugType(item) === '外用' ? normalizePrescriptionDays(item)
      : (Number.isFinite(days) && days > 0 ? days : 7),
    dispensing_type: item.dispensing_type || '院外',
    instructions: item.instructions || item.note || null,
    is_generic: Boolean(item.is_generic),
    generic_name: item.generic_name || item.genericName || '',
    generic_class: item.generic_class || item.genericClass || '',
    generic_prescription_code: item.generic_prescription_code || item.genericPrescriptionCode || '',
    generic_prescription_name: item.generic_prescription_name || item.genericPrescriptionName || '',
    generic_prescription_addition_category: item.generic_prescription_addition_category || item.genericPrescriptionAdditionCategory || '',
    generic_prescription_lowest_price: item.generic_prescription_lowest_price ?? item.genericPrescriptionLowestPrice ?? '',
    generic_prescription_master_note: item.generic_prescription_master_note || item.genericPrescriptionMasterNote || '',
    generic_prescription_master_version: item.generic_prescription_master_version || item.genericPrescriptionMasterVersion || '',
    comments: item.comments || item.comment_names || [],
    comment_codes: item.comment_codes || [],
    free_comment: item.free_comment || '',
    receipt_position: item.receipt_position || 'summary',
    requires_comment: Boolean(item.requires_comment || item.comment_required || item.selectable_comment_required),
    long_term_listed: Boolean(item.long_term_listed || item.longTermListed),
    long_term_patient_choice: Boolean(item.long_term_patient_choice || item.longTermPatientChoice),
    generic_change_allowed: readOptionalBooleanFlag(item, ['generic_change_allowed', 'genericChangeAllowed']) ?? true,
    generic_change_reason: item.generic_change_reason || item.genericChangeReason || '',
    is_temporary: Boolean(item.is_temporary || item.isTemporary || item.temporary),
    refill_allowed: Boolean(item.refill_allowed || item.refillAllowed || item.is_refill || item.isRefill),
    refill_count: Number(item.refill_count || item.refillCount || 0) || null
  };
}

function cloneKarteSetOrderItem(item) {
  try {
    return JSON.parse(JSON.stringify(item || {}));
  } catch (error) {
    return { ...(item || {}) };
  }
}

function getKarteSetAppendSourceId(item, keys, fallback) {
  const found = keys.map(key => item?.[key]).find(value => value !== null && value !== undefined && value !== '');
  return String(found || fallback);
}

function clearKarteSetBillingGroup(action) {
  action.billing_group_id = '';
  action.billingGroupId = '';
  action.billing_group_parent_id = '';
  action.billingGroupParentId = '';
  action.billing_group_label = '';
  action.billingGroupLabel = '';
}

function clearKarteSetPrescriptionGroup(prescription) {
  prescription.prescription_group_id = '';
  prescription.prescriptionGroupId = '';
  prescription.prescription_group_parent_id = '';
  prescription.prescriptionGroupParentId = '';
  prescription.prescription_group_label = '';
  prescription.prescriptionGroupLabel = '';
}

function createBillingAppendEntry(item, index) {
  const normalized = normalizeBillingFromKarteSet(cloneKarteSetOrderItem(item));
  if (!normalized.name) return null;

  const entry = {
    kind: 'billing',
    item: normalized,
    sourceId: getKarteSetAppendSourceId(normalized, ['procedure_item_id', 'procedureItemId', 'local_id'], `billing:${index}`),
    groupId: String(normalized.billing_group_id || normalized.billingGroupId || ''),
    parentSourceId: String(normalized.billing_group_parent_id || normalized.billingGroupParentId || '')
  };

  delete normalized.procedure_item_id;
  delete normalized.procedureItemId;
  delete normalized.local_id;
  ensureProcedureActionIdentity(normalized);
  return entry;
}

function createPrescriptionAppendEntry(item, index) {
  const normalized = normalizePrescriptionFromKarteSet(cloneKarteSetOrderItem(item));
  if (!normalized.drug_name) return null;

  const entry = {
    kind: 'prescription',
    item: normalized,
    sourceId: getKarteSetAppendSourceId(normalized, ['prescription_item_id', 'prescriptionItemId', 'local_id'], `prescription:${index}`),
    groupId: String(normalized.prescription_group_id || normalized.prescriptionGroupId || ''),
    parentSourceId: String(normalized.prescription_group_parent_id || normalized.prescriptionGroupParentId || '')
  };

  delete normalized.prescription_item_id;
  delete normalized.prescriptionItemId;
  delete normalized.local_id;
  syncPrescriptionDerivedFields(ensurePrescriptionIdentity(normalized));
  return entry;
}

function findKarteSetAppendParent(entries) {
  if (!entries.length) return null;
  return entries.find(entry => !entry.parentSourceId)
    || entries.find(candidate => entries.some(entry => entry.parentSourceId === candidate.sourceId))
    || entries[0];
}

function assignBillingAppendGroup(entries, groupId, groupLabel) {
  if (!entries.length) return;
  const parent = findKarteSetAppendParent(entries) || entries[0];
  entries.forEach(entry => {
    const action = entry.item;
    action.billing_group_id = groupId;
    action.billingGroupId = groupId;
    action.billing_group_parent_id = entry === parent ? '' : parent.item.procedure_item_id;
    action.billingGroupParentId = action.billing_group_parent_id;
    action.billing_group_label = groupLabel;
    action.billingGroupLabel = groupLabel;
  });
}

function assignPrescriptionAppendGroup(entries, groupId, groupLabel) {
  if (!entries.length) return;
  const parent = findKarteSetAppendParent(entries) || entries[0];
  entries.forEach(entry => {
    const prescription = entry.item;
    prescription.prescription_group_id = groupId;
    prescription.prescriptionGroupId = groupId;
    prescription.prescription_group_parent_id = entry === parent ? '' : parent.item.prescription_item_id;
    prescription.prescriptionGroupParentId = prescription.prescription_group_parent_id;
    prescription.prescription_group_label = groupLabel;
    prescription.prescriptionGroupLabel = groupLabel;
  });
}

function remapKarteSetAppendGroups(billingEntries, prescriptionEntries) {
  const groups = new Map();
  [...billingEntries, ...prescriptionEntries].forEach(entry => {
    if (!entry.groupId) {
      if (entry.kind === 'billing') clearKarteSetBillingGroup(entry.item);
      if (entry.kind === 'prescription') clearKarteSetPrescriptionGroup(entry.item);
      return;
    }
    if (!groups.has(entry.groupId)) {
      groups.set(entry.groupId, { billings: [], prescriptions: [] });
    }
    const group = groups.get(entry.groupId);
    if (entry.kind === 'billing') {
      group.billings.push(entry);
    } else {
      group.prescriptions.push(entry);
    }
  });

  groups.forEach((group, oldGroupId) => {
    const anchor = findKarteSetAppendParent(group.billings)
      || findKarteSetAppendParent(group.prescriptions);
    if (!anchor) return;
    const anchorId = anchor.kind === 'billing'
      ? anchor.item.procedure_item_id
      : anchor.item.prescription_item_id;
    const prefix = group.billings.length > 0 || !String(oldGroupId).startsWith('rxmanual_')
      ? 'manual'
      : 'rxmanual';
    const groupId = `${prefix}_${anchorId}`;
    const groupLabel = getManualBillingGroupLabel(group.billings[0]?.item)
      || getPrescriptionGroupLabel(group.prescriptions[0]?.item)
      || group.billings[0]?.item?.name
      || group.prescriptions[0]?.item?.drug_name
      || 'セット';

    assignBillingAppendGroup(group.billings, groupId, groupLabel);
    assignPrescriptionAppendGroup(group.prescriptions, groupId, groupLabel);
  });
}

function buildKarteSetOrdersForAppend(set) {
  const billingEntries = (set.billings || [])
    .map(createBillingAppendEntry)
    .filter(Boolean);
  const prescriptionEntries = (set.prescriptions || [])
    .map(createPrescriptionAppendEntry)
    .filter(Boolean);

  remapKarteSetAppendGroups(billingEntries, prescriptionEntries);

  return {
    billings: billingEntries.map(entry => syncActionDerivedFields(entry.item)),
    prescriptions: prescriptionEntries.map(entry => syncPrescriptionDerivedFields(ensurePrescriptionIdentity(entry.item)))
  };
}

function normalizeDiagnosisFromKarteSet(item) {
  const normalized = normalizeDiagnosisItem(item);
  const diagnosisName = normalized.diagnosis_name || normalized.full_name || item?.name || '';
  return {
    patient_id: currentPatient?.id,
    record_id: currentRecordId || null,
    diagnosis_code: normalized.diagnosis_code || null,
    diagnosis_name: diagnosisName,
    department: normalized.department || getCurrentDiagnosisDepartment(),
    visit_type: normalized.visit_type || 'outpatient',
    insurance_scope: normalized.insurance_scope || 'social-national',
    insurance_none: normalized.insurance_none === true,
    icd10_code: normalized.icd10_code || null,
    prefix_modifiers: normalizeDiagnosisModifierList(normalized.prefix_modifiers),
    suffix_modifiers: normalizeDiagnosisModifierList(normalized.suffix_modifiers),
    diagnosis_category: normalized.diagnosis_category || 'sub',
    is_suspected: normalized.is_suspected === true,
    is_acute: normalized.is_acute === true || diagnosisName.includes('急性'),
    start_date: normalizeKarteDateValue(normalized.start_date) || getCurrentKarteDateValue() || getLocalDateString(),
    end_date: normalizeKarteDateValue(normalized.end_date) || null,
    outcome: normalized.outcome || 'continuing',
    receipt_comment: normalized.receipt_comment || null
  };
}

function getDiagnosisSetDuplicateKey(diagnosis) {
  const normalized = normalizeDiagnosisItem(diagnosis);
  return [
    normalized.full_name || normalized.diagnosis_name || '',
    normalized.department || getCurrentDiagnosisDepartment(),
    normalized.is_suspected ? 'suspected' : 'confirmed'
  ].map(value => String(value || '').trim()).join('|');
}

async function applyDiagnosesFromKarteSet(set) {
  const diagnoses = (set.diagnoses || []).map(normalizeDiagnosisFromKarteSet)
    .filter(item => item.diagnosis_name);
  if (!diagnoses.length || !currentPatient) return 0;

  if (currentPatientDiagnosesPatientId !== currentPatient.id) {
    try {
      currentPatientDiagnoses = await getPatientDocumentDiagnoses(currentPatient.id);
      currentPatientDiagnosesPatientId = currentPatient.id;
    } catch (error) {
      console.error('カルテセット適用前の傷病名取得エラー:', error);
      showToast('傷病名を取得できないため、セット内の傷病名は登録できません', 'error');
      return 0;
    }
  }

  const existingKeys = new Set(currentPatientDiagnoses.map(getDiagnosisSetDuplicateKey));
  const api = typeof DiagnosisAPI !== 'undefined' ? DiagnosisAPI : null;
  let addedCount = 0;

  for (const payload of diagnoses) {
    const key = getDiagnosisSetDuplicateKey(payload);
    if (existingKeys.has(key)) continue;

    try {
      if (!api?.create) throw new Error('DiagnosisAPI is not available');
      const created = await api.create(payload);
      currentPatientDiagnoses.push(normalizeDiagnosisItem(created.data || created.item || created));
    } catch (error) {
      console.error('カルテセット傷病名登録エラー:', error);
      showToast(`傷病名「${payload.diagnosis_name}」を登録できませんでした`, 'error');
      continue;
    }

    existingKeys.add(key);
    addedCount += 1;
  }

  if (addedCount > 0) {
    syncCurrentPatientDiagnosesState(currentPatientDiagnoses);
    renderDiseaseList(currentPatientDiagnoses);
    refreshProcedureWarningIndicators();
    refreshKarteSetRegisterDiagnosesIfOpen();
  }

  return addedCount;
}

async function applyKarteSet(setId) {
  if (!currentPatient) {
    showToast('患者を選択してください', 'error');
    return;
  }

  const set = karteSets.find(item => String(item.id) === String(setId));
  if (!set) return;

  const editor = document.getElementById('karte-editor');
  if (editor && isKarteEditorBlank(editor)) {
    activateKarteEditorForEditing();
    editor.innerHTML = composeKarteHtmlFromSet(set);
  }

  const department = document.getElementById('karte-department');
  if (department && set.department) {
    department.value = set.department;
  }

  const appendedOrders = buildKarteSetOrdersForAppend(set);
  assignMissingProcedureEntryOrdersFromDom();
  [...appendedOrders.billings, ...appendedOrders.prescriptions].forEach(assignProcedureEntryOrderForAppend);
  selectedActions.push(...appendedOrders.billings);
  selectedProcedureGroupAnchorId = null;
  selectedPrescriptionGroupAnchorId = null;

  pendingPrescriptions.push(...appendedOrders.prescriptions);
  await applyDiagnosesFromKarteSet(set);

  renderSelectedActionsInProcedure();
  renderPendingPrescriptionsInProcedure();
  updateSelectedList();
  updateTotalPoints();
  saveCurrentPatientBilling();
  markKarteDirty();
  checkActionsRealtime();
  checkPrescriptionsRealtime();

  if (typeof KarteSetAPI !== 'undefined') {
    KarteSetAPI.markUsed(set.id)
      .then(() => loadActionSets({ render: currentOrderCategory === 'set' }))
      .catch(error => {
        console.warn('カルテセット使用回数更新エラー:', error);
      });
  }

}

// ツリー項目の展開/折りたたみ
function toggleTreeItem(header) {
  const item = header.closest('.m3-tree-item, .m3-tree-node-item');
  if (!item) return;
  const children = item.querySelector(':scope > .m3-tree-children');
  const icon = item.querySelector(':scope > .m3-tree-row .m3-tree-toggle i');
  if (!children || !icon) return;

  const isExpanded = item.classList.contains('expanded') && !children.classList.contains('hidden');
  if (!isExpanded) {
    setSetTreeItemExpanded(item, true);
    rememberSetTreeItemExpansion(item, true);
  } else {
    setSetTreeItemExpanded(item, false);
    rememberSetTreeItemExpansion(item, false);
  }
}

// セット項目を適用
async function applySetItem(setId, itemIndex) {
  const set = actionSets.find(item => item.id === setId);
  const setItem = set?.items?.[itemIndex];
  if (!setItem) return;

  if (setItem.action) {
    addMedicalActionToRecord(setItem.action);
  } else if (Array.isArray(setItem.actions)) {
    showToast('このセット項目は正式な算定マスターに紐づいていないため追加できません', 'warning');
  }
}

function toggleMedicalAction(action) {
  addMedicalActionToRecord(action);
}

