// ====================================
// 会計機能
// ====================================
let currentBilling = null; // 現在の会計情報
let currentPaymentMethod = 'cash'; // 支払い方法
const COMPLETED_BILLING_DISPLAY_STORAGE_KEY = 'digimaster.completedBillingDisplayData.v1';
let completedBillingDisplayData = loadCompletedBillingDisplayData();

function loadCompletedBillingDisplayData() {
  try {
    const parsed = JSON.parse(localStorage.getItem(COMPLETED_BILLING_DISPLAY_STORAGE_KEY) || '{}');
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
  } catch (error) {
    console.warn('完了済み会計表示データを読み込めませんでした:', error);
    return {};
  }
}

function persistCompletedBillingDisplayData() {
  try {
    const entries = Object.entries(completedBillingDisplayData);
    const cappedEntries = entries.slice(-500);
    completedBillingDisplayData = Object.fromEntries(cappedEntries);
    localStorage.setItem(COMPLETED_BILLING_DISPLAY_STORAGE_KEY, JSON.stringify(completedBillingDisplayData));
  } catch (error) {
    console.warn('完了済み会計表示データを保存できませんでした:', error);
  }
}

function cloneBillingDisplayValue(value) {
  return value ? JSON.parse(JSON.stringify(value)) : null;
}

function getBillingDisplayBilling(data) {
  return data?.billing || data || null;
}

function hasBillingDisplayItems(data) {
  const billing = getBillingDisplayBilling(data);
  if (!billing) return false;
  const items = Array.isArray(billing.items) ? billing.items : [];
  return items.length > 0
    || Number(billing.totalPoints || 0) > 0
    || Number(billing.totalAmount || 0) > 0
    || Number(billing.patientAmount || 0) > 0;
}

function getBillingItemComparisonKey(item) {
  const code = String(item?.code || item?.billing_code || '').trim();
  const name = String(item?.name || item?.billing_name || '').trim();
  const quantity = Number(item?.quantity || 1);
  const points = Number(item?.points ?? item?.score ?? 0);
  const amount = Number(item?.amount ?? item?.unit_price ?? item?.price ?? 0);
  const isSelfPay = Boolean(item?.isSelfPay || item?.is_self_pay || item?.item_type === 'self_pay' || item?.category === '自費');
  const doNotBill = Boolean(item?.do_not_bill || item?.doNotBill);
  return [
    code || name,
    name,
    Number.isFinite(quantity) ? quantity : 1,
    Number.isFinite(points) ? points : 0,
    Number.isFinite(amount) ? amount : 0,
    isSelfPay ? 'self' : 'insurance',
    doNotBill ? 'no-bill' : 'bill'
  ].join('|');
}

function getBillingItemsComparisonKeys(items) {
  return (Array.isArray(items) ? items : [])
    .map(getBillingItemComparisonKey)
    .sort();
}

function doBillingItemsMatchSavedDisplay(currentItems, savedDisplayData) {
  const savedItems = getBillingDisplayBilling(savedDisplayData)?.items || [];
  const currentKeys = getBillingItemsComparisonKeys(currentItems);
  const savedKeys = getBillingItemsComparisonKeys(savedItems);
  if (currentKeys.length === 0 || savedKeys.length === 0) return false;
  if (currentKeys.length !== savedKeys.length) return false;
  return currentKeys.every((key, index) => key === savedKeys[index]);
}

function isCurrentBillingForCurrentPatient() {
  if (!currentBilling || !currentPatient?.id) return false;
  return String(currentBilling.patientId || '') === String(currentPatient.id);
}

function getCurrentBillingVisitDate() {
  return normalizeKarteDateValue(
    (getCurrentReceptionRecordId() ? getKarteDateFromReception(currentReception) : null) ||
    getCurrentKarteDateValue() ||
    (isCurrentBillingForCurrentPatient() ? currentBilling?.visitDate : null)
  ) || getCurrentKarteDateValue();
}

function getCurrentBillingReceptionId() {
  const currentReceptionId = getCurrentReceptionRecordId();
  if (currentReceptionId) return currentReceptionId;
  return isCurrentBillingForCurrentPatient() ? currentBilling?.receptionId || '' : '';
}

function getBillingDisplayDataKeys(
  patientId = currentPatient?.id,
  date = getCurrentBillingVisitDate(),
  receptionId = getCurrentBillingReceptionId()
) {
  const normalizedDate = normalizeKarteDateValue(date);
  const keys = [];
  if (receptionId) {
    keys.push(`reception:${receptionId}`);
    if (patientId && normalizedDate) {
      keys.push(`patient:${patientId}:date:${normalizedDate}:reception:${receptionId}`);
    }
  } else if (patientId && normalizedDate) {
    keys.push(`patient:${patientId}:date:${normalizedDate}`);
    keys.push(`${patientId}_${normalizedDate}`);
  }
  return [...new Set(keys)];
}

function getBillingDisplayDataKey(patientId = currentPatient?.id, date = getCurrentBillingVisitDate()) {
  return getBillingDisplayDataKeys(patientId, date)[0] || '';
}

function getCompletedBillingDisplayData() {
  let exactFallback = null;
  for (const key of getBillingDisplayDataKeys()) {
    const data = completedBillingDisplayData[key];
    if (!data) continue;
    if (hasBillingDisplayItems(data)) return data;
    exactFallback = exactFallback || data;
  }

  const patientId = currentPatient?.id ? String(currentPatient.id) : '';
  const normalizedDate = normalizeKarteDateValue(getCurrentBillingVisitDate());
  const receptionId = getCurrentBillingReceptionId();
  const candidates = Object.values(completedBillingDisplayData)
    .filter(data => {
      const billing = getBillingDisplayBilling(data);
      if (!billing) return false;
      const dataPatientId = String(data.patientId || billing.patientId || '');
      const dataDate = normalizeKarteDateValue(data.visitDate || billing.visitDate);
      const dataReceptionId = String(data.receptionId || billing.receptionId || '');
      if (patientId && dataPatientId !== patientId) return false;
      if (normalizedDate && dataDate !== normalizedDate) return false;
      if (receptionId && dataReceptionId !== String(receptionId)) return false;
      return true;
    })
    .sort((left, right) => {
      const leftTime = Date.parse(left.savedAt || left.billing?.savedAt || '') || 0;
      const rightTime = Date.parse(right.savedAt || right.billing?.savedAt || '') || 0;
      return rightTime - leftTime;
    });

  return candidates[0] || exactFallback;
}

function saveCompletedBillingDisplayData(paymentData = null, options = {}) {
  const keys = getBillingDisplayDataKeys();
  if (keys.length === 0 || !currentBilling) return;
  const existingData = getCompletedBillingDisplayData();
  const status = options.status || (paymentData ? 'payment_done' : (currentBilling.paymentStatus || 'calculated'));
  const billing = {
    ...cloneBillingDisplayValue(currentBilling),
    patientId: currentPatient?.id || currentBilling.patientId || '',
    receptionId: getCurrentReceptionRecordId() || currentBilling.receptionId || '',
    visitDate: getCurrentBillingVisitDate(),
    paymentStatus: status === 'payment_done' ? 'payment_done' : (currentBilling.paymentStatus || status)
  };
  if (!hasBillingDisplayItems({ billing }) && hasBillingDisplayItems(existingData)) {
    return;
  }
  const data = {
    billing,
    patientId: billing.patientId,
    receptionId: billing.receptionId,
    visitDate: billing.visitDate,
    status,
    payment: paymentData ? cloneBillingDisplayValue(paymentData) : cloneBillingDisplayValue(existingData?.payment),
    paymentMethod: currentPaymentMethod,
    receivedAmount: currentPaymentMethod === 'cash'
      ? Number(document.getElementById('payment-received')?.value || 0)
      : Number(currentBilling.patientAmount || 0),
    savedAt: new Date().toISOString()
  };

  keys.forEach(key => {
    completedBillingDisplayData[key] = cloneBillingDisplayValue(data);
  });
  persistCompletedBillingDisplayData();
}

function restoreCompletedBillingDisplayData(data = getCompletedBillingDisplayData()) {
  if (!data?.billing) return false;
  currentBilling = cloneBillingDisplayValue(data.billing);
  if (data.paymentMethod) switchPaymentMethod(data.paymentMethod);

  const receivedInput = document.getElementById('payment-received');
  if (receivedInput && Number.isFinite(Number(data.receivedAmount))) {
    receivedInput.value = Number(data.receivedAmount);
  }

  renderBillingDetails(currentBilling.items || []);
  renderBillingCalculationSummary(currentBilling);
  calculateChange();
  return true;
}

function isCurrentReceptionPaymentDone() {
  return currentReception?.status === 'payment_done' || currentReception?.payment_status === 'payment_done';
}

function renderBillingCalculationSummary(billing = currentBilling) {
  if (!billing) return;
  document.getElementById('calc-total-points').textContent = `${Number(billing.totalPoints || 0).toLocaleString()}点`;
  document.getElementById('calc-total-amount').textContent = `¥${Number(billing.totalAmount || 0).toLocaleString()}`;
  document.getElementById('calc-patient-amount').textContent = `¥${Number(billing.patientAmount || 0).toLocaleString()}`;
}

// 会計モーダルを表示
async function showBillingModal() {
  if (!currentPatient) {
    showToast('患者を選択してください', 'error');
    return;
  }

  if (currentPatientInsurances.length === 0) {
    await loadPatientInsurances(currentPatient.id);
  }
  syncCurrentReceptionContextFromPatientData();

  const canProceed = await prepareCurrentKarteForBillingModal();
  if (!canProceed) return;

  const modal = document.getElementById('billing-modal');
  modal.classList.remove('hidden');

  // 患者情報を表示
  document.getElementById('billing-patient-name').textContent = currentPatient.name;
  document.getElementById('billing-patient-id').textContent = `ID: ${currentPatient.patient_no || currentPatient.id}`;
  const selectedInsurance = getKarteContextSelectedInsurance();
  const insuranceLabel = selectedInsurance
    ? `保険: ${selectedInsurance.insurance_type_name || selectedInsurance.insurance_type} ${selectedInsurance.burden_ratio || 30}%`
    : (shouldTreatReceptionAsNoInsurance(currentReception) ? '保険: なし' : '保険: 未登録');
  const publicExpenseLabel = getKartePublicExpenseShortLabel('');
  document.getElementById('billing-insurance-info').textContent = [
    insuranceLabel,
    publicExpenseLabel ? `公費: ${publicExpenseLabel}` : ''
  ].filter(Boolean).join(' / ');

  // 会計計算を実行。会計ボタンでは自動算定項目を追加しない。
  await calculateBilling();
}

function hasCurrentKarteSavableContent() {
  return checkKarteHasContent()
    || selectedActions.length > 0
    || pendingPrescriptions.length > 0
    || Boolean(buildKarteVitalSignsPayload());
}

function shouldPersistCurrentKarteBeforeBillingModal() {
  if (!currentPatient || !hasCurrentKarteSavableContent()) return false;
  const date = getCurrentKarteDateValue();
  return karteDirty
    || !currentRecordId
    || currentRecordVisitDate !== date
    || hasPatientDraft(currentPatient.id, date, getCurrentReceptionRecordId());
}

async function persistCurrentKarteBeforeBillingModal() {
  if (!shouldPersistCurrentKarteBeforeBillingModal()) return true;

  const date = getCurrentKarteDateValue();
  try {
    showLoading();
    await ensureCurrentReceptionForRecordSave();
    const payload = buildCurrentKarteSavePayload();
    const result = await RecordAPI.save(payload);
    if (!result?.id) {
      throw new Error('カルテ保存結果にカルテIDがありません');
    }

    currentRecordId = result.id;
    currentRecordVisitDate = date;
    const persistedBillingId = result.billing_id || result.billingId;
    if (persistedBillingId) {
      currentBilling = {
        ...(currentBilling || {}),
        id: persistedBillingId,
        billingId: persistedBillingId
      };
    }
    clearPatientBillingData(currentPatient.id, date);
    resetKarteDirtyTracking();
    updateKarteHeaderContext('承認');

    if (currentPatient.patient_no) {
      await renderPatientHistoryFromAPI(currentPatient.id);
    } else {
      renderPatientHistory(currentPatient.id);
    }
    setActiveHistoryRecord(currentRecordId);
    refreshVitalsIfVisible(currentPatient.id);
    showToast('会計前にカルテを保存しました', 'success');
    return true;
  } catch (error) {
    console.error('会計前カルテ保存エラー:', error);
    saveCurrentPatientBilling();
    showToast('会計前のカルテ保存に失敗しました: ' + error.message, 'error');
    return false;
  } finally {
    hideLoading();
  }
}

async function confirmKarteWarningsBeforeBillingModal() {
  if (!isAnyKarteSaveWarningCheckEnabled()) return true;
  await ensureFacilityWarningsLoadedForKarte();
  const warningLoadBlockMessage = getFacilityWarningsLoadBlockMessage();
  if (warningLoadBlockMessage) {
    showToast(warningLoadBlockMessage, 'error');
    return false;
  }

  lastCheckTimestamp = 0;
  lastDrugCheckTimestamp = 0;
  if (isKarteSaveCalculationCheckEnabled()) await checkActionsRealtime();
  if (isKarteSavePrescriptionAuditCheckEnabled()) await checkPrescriptionsRealtime();
  const saveWarnings = buildKarteSaveWarnings();
  if (saveWarnings.length === 0) return true;

  return showKarteWarningListDialog(saveWarnings, {
    title: '会計前の警告一覧',
    introText: '会計前に確認が必要な警告があります。下記をご確認ください。',
    confirmText: '会計へ進む'
  });
}

async function prepareCurrentKarteForBillingModal() {
  const saved = await persistCurrentKarteBeforeBillingModal();
  if (!saved) return false;
  return await confirmKarteWarningsBeforeBillingModal();
}

// 会計モーダルを閉じる
function closeBillingModal() {
  document.getElementById('billing-modal').classList.add('hidden');
}

function roundPatientPaymentAmount(amount) {
  const value = Number(amount);
  if (!Number.isFinite(value)) return 0;
  return Math.round(value / 10) * 10;
}

// 会計計算
async function calculateBilling() {
  const tbody = document.getElementById('billing-details-body');
  tbody.innerHTML = '<tr><td colspan="5" class="loading"><i class="fas fa-spinner fa-spin"></i> 計算中...</td></tr>';

  try {
    const updatedPrescriptionPrices = await ensureInternalPrescriptionPricesForBilling();
    if (updatedPrescriptionPrices) {
      saveCurrentPatientBilling();
    }

    // 選択された診療行為と処方から明細を作成
    const billingItems = buildBillingItemsFromCurrentOrders();
    const persistedBillingId = currentBilling?.id || currentBilling?.billingId || null;
    const completedDisplayData = getCompletedBillingDisplayData();
    const hasCompletedBillingDisplay = completedDisplayData?.status === 'payment_done'
      || completedDisplayData?.billing?.paymentStatus === 'payment_done'
      || Boolean(completedDisplayData?.payment);
    const hasSavedBillingDisplay = hasBillingDisplayItems(completedDisplayData);
    const shouldRestoreSavedDisplay = completedDisplayData && hasSavedBillingDisplay && (
      billingItems.length === 0 ||
      ((hasCompletedBillingDisplay || isCurrentReceptionPaymentDone()) && doBillingItemsMatchSavedDisplay(billingItems, completedDisplayData))
    );
    if (shouldRestoreSavedDisplay) {
      restoreCompletedBillingDisplayData(completedDisplayData);
      return;
    }

    // 合計計算
    const totalPoints = billingItems
      .filter(item => !item.isSelfPay)
      .reduce((sum, item) => sum + item.subtotal, 0);
    const insuranceTargetAmount = totalPoints * 10;
    const selfPayAmount = billingItems
      .filter(item => item.isSelfPay)
      .reduce((sum, item) => sum + (item.subtotalAmount || 0), 0);
    const totalAmount = insuranceTargetAmount + selfPayAmount;

    const selectedInsurance = getKarteContextSelectedInsurance();
    const burdenRatio = selectedInsurance
      ? (selectedInsurance.burden_ratio ?? inferBurdenRatio(currentPatient, selectedInsurance.insurance_type, selectedInsurance.insurer_number))
      : 100;
    const patientRatio = burdenRatio / 100;
    const insurancePatientAmount = Math.floor(insuranceTargetAmount * patientRatio);
    const patientAmount = roundPatientPaymentAmount(insurancePatientAmount + selfPayAmount);
    const insuranceAmount = Math.max(0, totalAmount - patientAmount);

    currentBilling = {
      ...(persistedBillingId ? { id: persistedBillingId, billingId: persistedBillingId } : {}),
      patientId: currentPatient?.id || '',
      receptionId: getCurrentReceptionRecordId() || '',
      visitDate: getCurrentKarteDateValue(),
      items: billingItems,
      totalPoints,
      totalAmount,
      patientAmount,
      insuranceAmount,
      insurancePatientAmount,
      selfPayAmount,
      burdenRatio,
      insuranceId: selectedInsurance?.id || null,
      publicExpenseIds: getReceptionSelectedPublicExpenseIds(currentReception)
    };

    if (persistedBillingId) {
      const serverBilling = await BillingAPI.get(persistedBillingId);
      applyServerBillingToCurrentBilling(serverBilling);
      if (hasBillingDisplayItems({ billing: currentBilling })) {
        saveCompletedBillingDisplayData(null, { status: 'calculated' });
      }
      return;
    }

    if (currentBilling.publicExpenseIds.length) {
      throw new Error('公費適用後の患者負担額をサーバーから確認できません');
    }

    // 明細テーブルを表示
    renderBillingDetails(billingItems);

    // 計算結果を表示
    renderBillingCalculationSummary(currentBilling);
    calculateChange();
    if (hasBillingDisplayItems({ billing: currentBilling })) {
      saveCompletedBillingDisplayData(null, { status: 'calculated' });
    }

  } catch (error) {
    console.error('会計計算エラー:', error);
    showToast('会計計算に失敗しました', 'error');
  }
}

// 明細テーブルを表示
function renderBillingDetails(items) {
  const tbody = document.getElementById('billing-details-body');

  if (items.length === 0) {
    tbody.innerHTML = '<tr><td colspan="5" class="no-data">明細がありません</td></tr>';
    return;
  }

  tbody.innerHTML = items.map(item => `
    <tr>
      <td class="col-category">
        <span class="category-badge ${getProcedureIconClass(item.category)}">${getCategoryIcon(item.category)}</span>
      </td>
      <td class="col-name">${escapeHalfWidthNumericText(item.name)}</td>
      <td class="col-points">${item.isSelfPay ? '-' : item.points + '点'}</td>
      <td class="col-qty">${item.quantity}</td>
      <td class="col-subtotal">${item.isSelfPay ? `¥${(item.subtotalAmount || 0).toLocaleString()}` : item.subtotal + '点'}</td>
    </tr>
  `).join('');
}

// 支払い方法を切り替え
function switchPaymentMethod(method) {
  currentPaymentMethod = method;

  // タブの状態を更新
  document.querySelectorAll('.payment-tab').forEach(tab => {
    tab.classList.toggle('active', tab.dataset.method === method);
  });

  // フォームの表示を切り替え
  document.getElementById('payment-cash-form').classList.toggle('hidden', method !== 'cash');
  document.getElementById('payment-card-form').classList.toggle('hidden', method !== 'card');
  document.getElementById('payment-qr-form').classList.toggle('hidden', method !== 'qr');
  document.getElementById('payment-ic-form').classList.toggle('hidden', method !== 'ic');
}

// お釣りを計算
function calculateChange() {
  if (!currentBilling) return;

  const received = parseFloat(document.getElementById('payment-received').value) || 0;
  const change = received - currentBilling.patientAmount;

  document.getElementById('payment-change').textContent = change >= 0 ? `¥${change.toLocaleString()}` : '-';
  document.getElementById('payment-change').classList.toggle('negative', change < 0);
}

function normalizeReceptionTimeForPayload(value) {
  if (!value) return null;
  const match = String(value).match(/(\d{1,2}):(\d{2})(?::\d{2})?/);
  if (!match) return null;
  return `${match[1].padStart(2, '0')}:${match[2]}`;
}

function getReceptionFirstVisitForPayload() {
  if (currentReception?.source === 'reservation') return null;
  const value = currentReception?.first_visit;
  if (value === undefined || value === null || value === '') return null;
  return value === true || value === 1 || value === '1';
}

async function markCurrentReceptionPaymentDone() {
  if (!currentPatient) return;

  const context = getKarteContextPayloadFromState();
  const apiPayload = buildReceptionApiPayloadFromContext(context);

  if (currentReception?.id) {
    try {
      const result = await ReceptionAPI.update(currentReception.id, {
        ...apiPayload,
        status: 'payment_done'
      });
      mergeCurrentReceptionFromApiResponse(result, {
        ...currentReception,
        ...context,
        ...apiPayload,
        status: 'payment_done'
      });
      return;
    } catch (error) {
      if (!String(error.message || '').includes('受付が見つかりません')) {
        throw error;
      }
    }
  }

  const doctorPayload = getKarteDoctorPayloadFromName(
    currentReception?.doctor_name_override || currentReception?.doctor_name || currentReception?.doctor || ''
  );
  const created = await ReceptionAPI.create({
    reservation_id: currentReception?.source === 'reservation'
      ? currentReception.id
      : (currentReception?.reservation_id || null),
    patient_id: currentPatient.id,
    reception_date: getCurrentKarteDateValue(),
    reception_time: normalizeReceptionTimeForPayload(currentReception?.reception_time || currentReception?.created_at),
    appointment_time: normalizeReceptionTimeForPayload(currentReception?.appointment_time),
    status: getFacilityReceptionInitialStatus(),
    department: apiPayload.department || currentReception?.department || document.getElementById('karte-department')?.value || '内科',
    doctor_id: apiPayload.doctor_id || doctorPayload.doctor_id,
    doctor_name_override: apiPayload.doctor_name_override || doctorPayload.doctor_name_override,
    insurance_id: apiPayload.insurance_id,
    public_expense_1_id: apiPayload.public_expense_1_id,
    public_expense_2_id: apiPayload.public_expense_2_id,
    public_expense_3_id: apiPayload.public_expense_3_id,
    public_expense_1_other_amount: apiPayload.public_expense_1_other_amount,
    public_expense_2_other_amount: apiPayload.public_expense_2_other_amount,
    public_expense_3_other_amount: apiPayload.public_expense_3_other_amount,
    insurance_card_status: apiPayload.insurance_card_status,
    medical_certificate_status: apiPayload.medical_certificate_status,
    limit_certificate_status: apiPayload.limit_certificate_status,
    electronic_prescription_status: apiPayload.electronic_prescription_status,
    past_prescription_status: apiPayload.past_prescription_status,
    labor_auto_insurance: apiPayload.labor_auto_insurance,
    save_mode: apiPayload.save_mode,
    reception_memo: currentReception?.reception_memo || currentReception?.reservation_memo || null,
    first_visit: getReceptionFirstVisitForPayload()
  });

  const updated = await ReceptionAPI.update(created.id, {
    ...apiPayload,
    status: 'payment_done'
  });
  mergeCurrentReceptionFromApiResponse(updated, {
    ...(currentReception || {}),
    ...context,
    ...apiPayload,
    id: created.id,
    first_visit: created.first_visit ?? currentReception?.first_visit ?? null,
    status: 'payment_done'
  });
}

function normalizeServerBillingItemForDisplay(item) {
  const itemType = item?.item_type || '';
  const isSelfPay = itemType === 'self_pay' || item?.category === '自費';
  const points = Number(item?.unit_score ?? item?.points ?? 0);
  const quantity = Number(item?.quantity || 1);
  const subtotal = Number(item?.score ?? (points * quantity));
  const subtotalAmount = Number(item?.amount ?? (isSelfPay ? 0 : subtotal * 10));

  return {
    code: item?.code || '',
    category: item?.category || (isSelfPay ? '自費' : '診察'),
    name: item?.name || '',
    points,
    amount: isSelfPay ? subtotalAmount : 0,
    quantity,
    subtotal: isSelfPay ? 0 : subtotal,
    subtotalAmount,
    isSelfPay,
    item_type: itemType
  };
}

function applyServerBillingToCurrentBilling(serverBilling) {
  if (!serverBilling) return null;

  const selfPayAmount = Number(serverBilling.self_pay_amount || 0);
  const insuranceTotalAmount = Number(serverBilling.total_amount || 0);
  const patientBurden = Number(serverBilling.patient_burden_adjusted ?? serverBilling.patient_burden ?? 0);
  const finalAmount = Number(serverBilling.final_amount ?? (patientBurden + selfPayAmount));
  const serverItems = Array.isArray(serverBilling.items) && serverBilling.items.length
    ? serverBilling.items.map(normalizeServerBillingItemForDisplay)
    : (currentBilling?.items || []);

  currentBilling = {
    ...(currentBilling || {}),
    id: serverBilling.id,
    billingId: serverBilling.id,
    patientId: serverBilling.patient_id || currentPatient?.id || '',
    receptionId: serverBilling.reception_id || serverBilling.receptionId || getCurrentReceptionRecordId() || currentBilling?.receptionId || '',
    visitDate: serverBilling.billing_date || getCurrentKarteDateValue(),
    items: serverItems,
    totalPoints: Number(serverBilling.total_score || 0),
    totalAmount: insuranceTotalAmount + selfPayAmount,
    final_amount: finalAmount,
    unpaid_amount: Number(serverBilling.unpaid_amount ?? 0),
    paid_amount: Number(serverBilling.paid_amount ?? 0),
    patientAmount: finalAmount,
    insuranceAmount: Number(serverBilling.insurance_amount || 0),
    insurancePatientAmount: patientBurden,
    selfPayAmount,
    burdenRatio: Number(serverBilling.burden_ratio || currentBilling?.burdenRatio || 100),
    paymentStatus: serverBilling.payment_status || currentBilling?.paymentStatus || 'unpaid'
  };

  renderBillingDetails(currentBilling.items || []);
  renderBillingCalculationSummary(currentBilling);
  calculateChange();
  return currentBilling;
}

async function confirmKarteWarningsBeforeBillingPayment() {
  if (!isAnyKarteSaveWarningCheckEnabled()) return true;
  await ensureFacilityWarningsLoadedForKarte();
  const warningLoadBlockMessage = getFacilityWarningsLoadBlockMessage();
  if (warningLoadBlockMessage) {
    showToast(warningLoadBlockMessage, 'error');
    return false;
  }
  lastCheckTimestamp = 0;
  lastDrugCheckTimestamp = 0;
  if (isKarteSaveCalculationCheckEnabled()) await checkActionsRealtime();
  if (isKarteSavePrescriptionAuditCheckEnabled()) await checkPrescriptionsRealtime();
  const saveWarnings = buildKarteSaveWarnings();
  if (saveWarnings.length === 0) return true;
  return showKarteWarningListDialog(saveWarnings);
}

async function persistCurrentKarteBillingForPayment() {
  const date = getCurrentKarteDateValue();
  await ensureCurrentReceptionForRecordSave();
  const payload = buildCurrentKarteSavePayload();
  if (!payload.billings?.length) {
    throw new Error('会計明細がありません');
  }

  const result = await RecordAPI.save(payload);
  if (!result?.id) {
    throw new Error('カルテ保存結果にカルテIDがありません');
  }

  currentRecordId = result.id;
  currentRecordVisitDate = date;

  const billingId = result.billing_id || result.billingId || currentBilling?.id || currentBilling?.billingId;
  if (!billingId) {
    throw new Error('会計IDを取得できませんでした');
  }

  const serverBilling = await BillingAPI.get(billingId);
  return applyServerBillingToCurrentBilling(serverBilling);
}

function applyConfirmedReceptionStatus(confirmationResult) {
  const receptionId = confirmationResult?.reception_id;
  if (!receptionId || confirmationResult?.reception_status !== 'payment_done') return false;

  if (!currentReception?.id || String(currentReception.id) === String(receptionId)) {
    currentReception = {
      ...(currentReception || {}),
      id: receptionId,
      status: 'payment_done',
      source: 'reception'
    };
    upsertReceptionCache(currentReception);
  }
  return true;
}

async function restorePaidDraftBillingForConfirmation() {
  const billingId = currentBilling?.id || currentBilling?.billingId;
  if (!billingId) return null;

  const serverBilling = await BillingAPI.get(billingId);
  const finalAmount = Number(serverBilling?.final_amount ?? serverBilling?.patient_burden ?? 0);
  const paidAmount = Number(serverBilling?.paid_amount ?? 0);
  const isPaidDraft = serverBilling?.status === 'draft'
    && (
      serverBilling?.payment_status === 'paid'
      || (finalAmount > 0 && paidAmount >= finalAmount)
    );

  if (!isPaidDraft) return null;
  return applyServerBillingToCurrentBilling(serverBilling);
}

function getPaymentAmountForApi(billing = currentBilling) {
  return Math.round(Number(
    billing?.unpaid_amount
    ?? billing?.unpaidAmount
    ?? billing?.final_amount
    ?? billing?.patientAmount
    ?? 0
  ));
}

function buildPaymentDetailForApi(method) {
  const values = [];
  if (method === 'card') {
    const cardType = document.getElementById('card-type')?.value;
    const paymentType = document.getElementById('card-payment-type')?.value;
    const approvalNo = document.getElementById('card-approval-no')?.value;
    if (cardType) values.push(`card:${cardType}`);
    if (paymentType) values.push(`type:${paymentType}`);
    if (approvalNo) values.push(`approval:${approvalNo}`);
  } else if (method === 'qr') {
    const service = document.getElementById('qr-service')?.value;
    const transactionId = document.getElementById('qr-transaction-id')?.value;
    if (service) values.push(`qr:${service}`);
    if (transactionId) values.push(`tx:${transactionId}`);
  } else if (method === 'ic') {
    const icType = document.getElementById('ic-type')?.value;
    if (icType) values.push(`ic:${icType}`);
  }
  return values.length ? values.join(' / ').slice(0, 100) : null;
}

function buildPaymentRequestForApi(paymentAmount) {
  const receivedAmount = currentPaymentMethod === 'cash'
    ? Math.round(Number(document.getElementById('payment-received')?.value || 0))
    : paymentAmount;

  return {
    payment_amount: paymentAmount,
    payment_method: currentPaymentMethod || 'cash',
    received_amount: receivedAmount,
    payment_detail: buildPaymentDetailForApi(currentPaymentMethod)
  };
}

// 会計を完了
async function completeBilling() {
  if (!currentBilling || !hasBillingDisplayItems({ billing: currentBilling })) {
    const restored = restoreCompletedBillingDisplayData(getCompletedBillingDisplayData());
    if (restored && hasBillingDisplayItems({ billing: currentBilling })) {
      showToast('保存済みの会計明細を復元しました', 'info');
    }
  }

  if (!currentBilling || !hasBillingDisplayItems({ billing: currentBilling })) {
    showToast('会計情報がありません', 'error');
    return;
  }

  try {
    const shouldContinue = await confirmKarteWarningsBeforeBillingPayment();
    if (!shouldContinue) return;

    showLoading();
    const persistedBilling = await restorePaidDraftBillingForConfirmation()
      || await persistCurrentKarteBillingForPayment();
    const billingId = persistedBilling?.id || currentBilling?.id || currentBilling?.billingId;
    const paymentAmount = getPaymentAmountForApi(persistedBilling || currentBilling);
    if (!billingId || paymentAmount < 0) {
      throw new Error('入金対象の会計が見つかりません');
    }

    if (paymentAmount === 0) {
      const confirmationResult = await BillingAPI.confirm(billingId);
      applyServerBillingToCurrentBilling(await BillingAPI.get(billingId));
      currentBilling.paymentStatus = 'paid';
      saveCompletedBillingDisplayData(null, { status: 'payment_done' });
      clearPatientBillingData(currentPatient.id, getCurrentKarteDateValue());
      resetKarteDirtyTracking();
      updateKarteHeaderContext('承認');

      try {
        if (!applyConfirmedReceptionStatus(confirmationResult)) {
          await markCurrentReceptionPaymentDone();
        }
      } catch (statusError) {
        console.warn('受付ステータス更新エラー:', statusError);
        showToast('会計は確定しましたが、受付ステータス更新に失敗しました', 'warning');
      }

      hideLoading();
      closeBillingModal();
      showToast('患者負担0円で会計が完了しました', 'success');
      await loadReceptions();
      return;
    }

    if (currentPaymentMethod === 'cash') {
      const received = Math.round(Number(document.getElementById('payment-received')?.value || 0));
      if (received < paymentAmount) {
        hideLoading();
        showToast('お預かり金額が不足しています', 'error');
        return;
      }
    }

    const paymentData = buildPaymentRequestForApi(paymentAmount);
    const paymentResult = await BillingAPI.createPayment(billingId, paymentData);
    const confirmationResult = await BillingAPI.confirm(billingId);
    applyServerBillingToCurrentBilling(await BillingAPI.get(billingId));
    currentBilling.paymentStatus = 'payment_done';

    const displayPaymentData = {
      ...paymentData,
      amount: paymentAmount,
      method: currentPaymentMethod,
      payment_id: paymentResult?.payment_id,
      change_amount: paymentResult?.change_amount || 0
    };
    currentBilling.payment = displayPaymentData;
    saveCompletedBillingDisplayData(displayPaymentData, { status: 'payment_done' });
    clearPatientBillingData(currentPatient.id, getCurrentKarteDateValue());
    resetKarteDirtyTracking();
    updateKarteHeaderContext('承認');

    try {
      if (!applyConfirmedReceptionStatus(confirmationResult)) {
        await markCurrentReceptionPaymentDone();
      }
    } catch (statusError) {
      console.warn('受付ステータス更新エラー:', statusError);
      showToast('入金は保存しましたが、受付ステータス更新に失敗しました', 'warning');
    }

    hideLoading();

    closeBillingModal();
    showToast('会計が完了しました', 'success');

    // 受付一覧を更新
    await loadReceptions();

  } catch (error) {
    hideLoading();
    console.error('会計処理エラー:', error);
    showToast('会計処理に失敗しました', 'error');
  }
}

function formatJapaneseEraDate(value = getLocalDateString()) {
  const normalized = normalizeKarteDateValue(value) || getLocalDateString();
  const date = parseLocalDate(normalized);
  if (Number.isNaN(date.getTime())) return formatDateSlash(normalized);

  const eras = [
    { name: '令和', start: '2019-05-01', year: 2019 },
    { name: '平成', start: '1989-01-08', year: 1989 },
    { name: '昭和', start: '1926-12-25', year: 1926 },
    { name: '大正', start: '1912-07-30', year: 1912 },
    { name: '明治', start: '1868-01-25', year: 1868 }
  ];
  const era = eras.find(item => date >= parseLocalDate(item.start));
  if (!era) return `${date.getFullYear()}年${date.getMonth() + 1}月${date.getDate()}日`;
  const eraYear = date.getFullYear() - era.year + 1;
  return `${era.name} ${eraYear === 1 ? '元' : eraYear}年 ${date.getMonth() + 1}月 ${date.getDate()}日`;
}

function getFacilityInfoForPrint(facility = getLoadedFacilityInfo()) {
  const userFacility = getCurrentUserFacilitySnapshot();
  const formFacility = getFacilitySettingsFormSnapshot();
  return {
    name: firstNonEmptyString(facility?.name, userFacility.name, formFacility.name),
    code: firstNonEmptyString(facility?.code, userFacility.code, formFacility.code),
    postalCode: firstNonEmptyString(facility?.postalCode, userFacility.postalCode, formFacility.postalCode),
    address: firstNonEmptyString(facility?.address, userFacility.address, formFacility.address),
    phone: firstNonEmptyString(facility?.phone, userFacility.phone, formFacility.phone),
    fax: firstNonEmptyString(facility?.fax, userFacility.fax, formFacility.fax),
    email: firstNonEmptyString(facility?.email, userFacility.email, formFacility.email),
    outpatientType: firstNonEmptyString(facility?.outpatientType, userFacility.outpatientType, formFacility.outpatientType),
    registrationNumber: firstNonEmptyString(facility?.registrationNumber, userFacility.registrationNumber, formFacility.registrationNumber)
  };
}

function getPrintableFacilityInfo(facility = getLoadedFacilityInfo()) {
  return getFacilityInfoForPrint(facility);
}

async function ensureFacilityInfoForPrintableDocument() {
  try {
    await requireCurrentFacilityInfoForOutput();
    return true;
  } catch (error) {
    console.error('帳票出力用の施設情報取得エラー:', error);
    showToast(error?.message || '施設情報を取得できないため帳票を出力できません', 'error');
    return false;
  }
}

const RECEIPT_POINT_ROWS = [
  '初・再診料',
  '医学管理料',
  '在宅医療',
  '投薬',
  '注射',
  '処置',
  '手術',
  '麻酔',
  '検査',
  '画像診断',
  'リハビリテーション',
  '精神科専門療法',
  '放射線治療',
  '病理診断',
  '入院料等',
  'その他'
];

function getReceiptPointCategory(item) {
  if (!item || item.isSelfPay) return null;
  const code = String(item.code || '').toUpperCase();
  const text = `${item.category || ''} ${item.name || ''}`;

  if (/入院/.test(text) || /^A[1-9]/.test(code)) return '入院料等';
  if (/医学管理|管理料|指導料/.test(text) || /^B/.test(code)) return '医学管理料';
  if (/在宅|往診|訪問診療/.test(text) || /^C/.test(code)) return '在宅医療';
  if (/投薬|処方|調剤|薬/.test(text) || /^F/.test(code)) return '投薬';
  if (/注射|点滴|静注|筋注|皮下注/.test(text) || /^G/.test(code)) return '注射';
  if (/処置/.test(text) || /^J/.test(code)) return '処置';
  if (/手術/.test(text) || /^K/.test(code)) return '手術';
  if (/麻酔/.test(text) || /^L/.test(code)) return '麻酔';
  if (/検査/.test(text) || /^D/.test(code)) return '検査';
  if (/画像|レントゲン|Ｘ線|X線|CT|MRI/.test(text) || /^E/.test(code)) return '画像診断';
  if (/リハビリ/.test(text) || /^H/.test(code)) return 'リハビリテーション';
  if (/精神科|精神/.test(text) || /^I/.test(code)) return '精神科専門療法';
  if (/放射線/.test(text) || /^M/.test(code)) return '放射線治療';
  if (/病理/.test(text) || /^N/.test(code)) return '病理診断';
  if (/初診|再診|外来診療料|診察|時間外|休日|深夜|乳幼児|医療情報取得|機能強化|感染対策|明細書発行/.test(text) || /^A/.test(code)) {
    return '初・再診料';
  }
  return 'その他';
}

function buildReceiptPointSummary() {
  const summary = Object.fromEntries(RECEIPT_POINT_ROWS.map(label => [label, 0]));
  (currentBilling?.items || []).forEach(item => {
    const category = getReceiptPointCategory(item);
    if (!category) return;
    summary[category] += Number(item.subtotal || 0);
  });
  return summary;
}

function formatReceiptPoints(value) {
  const points = Number(value || 0);
  return points > 0 ? points.toLocaleString() : '';
}

function formatReceiptAmount(value, blankZero = true) {
  const amount = Number(value || 0);
  if (blankZero && amount === 0) return '';
  return amount.toLocaleString();
}

function getReceiptInsuranceTypeLabel(insurance) {
  const typeLabels = {
    social: '社会保険',
    national: '国民健康保険',
    elderly: '後期高齢者医療',
    labor: '労災',
    auto: '自賠責',
    self_pay: '自費'
  };
  return insurance?.insurance_type_name
    || insurance?.insurer_name
    || typeLabels[insurance?.insurance_type]
    || insurance?.insurance_type
    || currentReception?.insurance_type_name
    || currentReception?.insurance_type
    || '未登録';
}

function getReceiptRelationshipLabel(insurance) {
  const value = insurance?.relationship || currentReception?.relationship || '';
  if (value === 'main') return '本人';
  if (value === 'family') return '家族';
  return '';
}

function getReceiptBurdenLabel(insurance) {
  const ratio = insurance?.burden_ratio ?? currentBilling?.burdenRatio ?? currentReception?.burden_ratio;
  if (ratio === null || ratio === undefined || ratio === '') return '';
  const numeric = Number(ratio);
  if (Number.isFinite(numeric) && numeric === 0) return '負担なし';
  return Number.isFinite(numeric) ? `${numeric}%` : String(ratio);
}

function getReceiptVisitDepartment() {
  return currentReception?.department || document.getElementById('karte-department')?.value || '';
}

function getReceiptPaymentSummary() {
  const selfPayAmount = currentBilling?.selfPayAmount ?? (currentBilling?.items || [])
    .filter(item => item.isSelfPay)
    .reduce((sum, item) => sum + Number(item.subtotalAmount || 0), 0);
  const insurancePatientAmount = Math.max(0, Number(currentBilling?.patientAmount || 0) - Number(selfPayAmount || 0));

  return {
    insurancePatientAmount,
    nonInsuranceAmount: Number(selfPayAmount || 0),
    selectedMedicalCareAmount: 0,
    otherNonInsuranceAmount: 0,
    currentChargeAmount: Number(currentBilling?.patientAmount || 0),
    previousBalance: 0,
    totalChargeAmount: Number(currentBilling?.patientAmount || 0),
    adjustmentAmount: 0,
    receivedAmount: Number(currentBilling?.patientAmount || 0)
  };
}

function buildReceiptPointRowsHtml(summary) {
  return RECEIPT_POINT_ROWS.map(label => `
    <tr>
      <th>${escapeHtml(label)}</th>
      <td>${formatReceiptPoints(summary[label])}</td>
      <td class="unit">点</td>
    </tr>
  `).join('');
}

function buildReceiptAmountRowsHtml(rows) {
  return rows.map(([label, amount]) => `
    <tr>
      <th>${escapeHtml(label)}</th>
      <td>${formatReceiptAmount(amount)}</td>
      <td class="unit">円</td>
    </tr>
  `).join('');
}

const printablePdfPreviewUrls = [];

function openPrintableHtml(html, title = '帳票', autoPrint = true) {
  const printWindow = window.open('', '_blank');
  if (!printWindow) {
    showToast('帳票画面を開けませんでした', 'error');
    return null;
  }

  printWindow.document.write(html);
  printWindow.document.close();
  printWindow.focus();

  if (autoPrint) {
    setTimeout(() => printWindow.print(), 250);
  }

  return printWindow;
}

function writePdfPreviewStatus(previewWindow, title, message) {
  if (!previewWindow || previewWindow.closed) return;
  const safeTitle = escapeHtml(title || '帳票');
  const safeMessage = escapeHtml(message || '');
  previewWindow.document.open();
  previewWindow.document.write(`
    <!DOCTYPE html>
    <html lang="ja">
    <head>
      <meta charset="UTF-8">
      <title>${safeTitle}</title>
      <style>
        body {
          margin: 0;
          min-height: 100vh;
          display: grid;
          place-items: center;
          background: #2f3134;
          color: #fff;
          font-family: "Yu Gothic", "Meiryo", sans-serif;
        }
        .message {
          padding: 18px 24px;
          border-radius: 6px;
          background: rgba(255, 255, 255, 0.12);
          box-shadow: 0 8px 28px rgba(0, 0, 0, 0.25);
          font-size: 14px;
        }
      </style>
    </head>
    <body>
      <div class="message">${safeMessage}</div>
    </body>
    </html>
  `);
  previewWindow.document.close();
}

function buildPdfBlobFromBase64(base64, mimeType = 'application/pdf') {
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return new Blob([bytes], { type: mimeType });
}

function rememberPrintablePdfPreviewUrl(url) {
  printablePdfPreviewUrls.push(url);
  while (printablePdfPreviewUrls.length > 10) {
    URL.revokeObjectURL(printablePdfPreviewUrls.shift());
  }
  setTimeout(() => {
    URL.revokeObjectURL(url);
    const index = printablePdfPreviewUrls.indexOf(url);
    if (index !== -1) printablePdfPreviewUrls.splice(index, 1);
  }, 10 * 60 * 1000);
}

function isMissingPdfIpcHandlerError(error) {
  return String(error?.message || error || '').includes('No handler registered')
    && String(error?.message || error || '').includes('documents:');
}

async function openPrintableHtmlAsPdfInBrowser(html, defaultFileName, title = '帳票', pdfOptions = {}) {
  if (!window.digimaster?.renderHtmlAsPdf) {
    openPrintableHtml(html, title, false);
    showToast('PDF表示機能が使えないため、帳票HTMLを表示しました', 'info');
    return;
  }

  const previewWindow = window.open('', '_blank');
  if (!previewWindow) {
    showToast('PDF表示ウィンドウを開けませんでした', 'error');
    return;
  }

  writePdfPreviewStatus(previewWindow, title, 'PDFを作成しています...');

  try {
    const result = await window.digimaster.renderHtmlAsPdf({ html, defaultFileName, ...pdfOptions });
    if (result?.success === false) {
      throw new Error(result.error || 'PDFデータを作成できませんでした');
    }
    if (!result?.base64) {
      throw new Error('PDFデータが返りませんでした');
    }

    const blob = buildPdfBlobFromBase64(result.base64, result.mimeType);
    const url = URL.createObjectURL(blob);
    rememberPrintablePdfPreviewUrl(url);
    previewWindow.location.replace(url);
    showToast(`${title}を表示しました`, 'success');
  } catch (error) {
    console.error('PDF表示エラー:', error);
    if (isMissingPdfIpcHandlerError(error)) {
      if (!previewWindow.closed) {
        previewWindow.document.open();
        previewWindow.document.write(html);
        previewWindow.document.close();
        previewWindow.focus();
      }
      showToast('PDF表示機能の反映にはアプリの完全再起動が必要です。今回は帳票HTMLを表示しました', 'info');
      return;
    }
    writePdfPreviewStatus(previewWindow, title, 'PDFの表示に失敗しました');
    const message = error?.message ? `PDFの表示に失敗しました: ${error.message}` : 'PDFの表示に失敗しました';
    showToast(message, 'error');
  }
}

function buildPrintableDocumentFileName(label) {
  const patientName = sanitizeDocumentFileName(currentPatient?.name || '患者');
  const date = (normalizeKarteDateValue(getCurrentKarteDateValue()) || getLocalDateString()).replaceAll('-', '');
  return `${sanitizeDocumentFileName(label)}_${patientName}_${date}.pdf`;
}

async function savePrintableHtmlAsPdf(html, defaultFileName, successMessage = 'PDFを保存しました', pdfOptions = {}) {
  if (!window.digimaster?.saveHtmlAsPdf) {
    const fallbackTitle = String(defaultFileName || '帳票').replace(/\.pdf$/i, '');
    openPrintableHtml(html, fallbackTitle, true);
    showToast('WEB版ではPDF保存ダイアログが未接続のため、開いた印刷画面でPDF保存を選んでください', 'info');
    return;
  }

  try {
    const result = await window.digimaster.saveHtmlAsPdf({ html, defaultFileName, ...pdfOptions });
    if (result?.canceled) return;
    if (result?.success === false) {
      throw new Error(result.error || 'PDFを保存できませんでした');
    }
    showToast(successMessage, 'success');
  } catch (error) {
    console.error('PDF保存エラー:', error);
    if (isMissingPdfIpcHandlerError(error)) {
      const fallbackTitle = String(defaultFileName || '帳票').replace(/\.pdf$/i, '');
      openPrintableHtml(html, fallbackTitle, true);
      showToast('PDF保存機能が使えないため、開いた印刷画面でPDF保存を選んでください', 'info');
      return;
    }
    const message = error?.message ? `PDFの保存に失敗しました: ${error.message}` : 'PDFの保存に失敗しました';
    showToast(message, 'error');
  }
}

