function getBillingOperationElements() {
  return {
    modal: document.getElementById('billing-operation-modal'),
    title: document.getElementById('billing-operation-title'),
    body: document.getElementById('billing-operation-body'),
    result: document.getElementById('billing-operation-result')
  };
}

let billingOperationMonthlyInvoices = [];
let billingOperationStatsSnapshot = null;
let billingOperationUnpaidRows = [];
let billingOperationRecalculateResult = null;

function openBillingOperationModal(title) {
  const elements = getBillingOperationElements();
  if (!elements.modal || !elements.body || !elements.result) return null;
  if (elements.title) elements.title.textContent = title || '会計管理';
  elements.body.innerHTML = '<div class="billing-operation-empty">読み込み中...</div>';
  elements.result.innerHTML = '';
  elements.modal.classList.remove('hidden');
  return elements;
}

function closeBillingOperationModal() {
  const elements = getBillingOperationElements();
  elements.modal?.classList.add('hidden');
  if (elements.body) elements.body.innerHTML = '';
  if (elements.result) elements.result.innerHTML = '';
}

function setBillingOperationResult(html) {
  const result = document.getElementById('billing-operation-result');
  if (result) result.innerHTML = html || '';
}

function closeOfficeReportMenus() {
  document.getElementById('user-dropdown')?.classList.remove('open');
  document.getElementById('user-dropdown-main')?.classList.remove('open');
  document.getElementById('office-report-menu')?.classList.remove('open');
  document.getElementById('office-report-menu-btn')?.setAttribute('aria-expanded', 'false');
}

function openOfficeReportPendingPanel(title, message) {
  const elements = openBillingOperationModal(title);
  if (!elements) {
    showToast(message, 'info');
    return;
  }
  elements.body.innerHTML = `<div class="billing-operation-note">${escapeHtml(message)}</div>`;
  elements.result.innerHTML = '';
}

async function handleOfficeReportMenuAction(action) {
  closeOfficeReportMenus();
  switch (action) {
    case 'monthly':
      await openAccountingStatsPanel('月計表');
      break;
    case 'business-report':
      await openAccountingStatsPanel('経営データ集計');
      showToast('期間を確認して「経営データZIP」からダウンロードできます', 'info');
      break;
    case 'carryover-list':
      await openAccountingStatsPanel('繰越金有り患者一覧表');
      showToast('未収がある患者は「未収CSV」から確認できます', 'info');
      break;
    case 'generic-drug-usage':
      openOfficeReportPendingPanel('後発品使用量集計表', '後発品使用量集計表の出力本体は準備中です。サンプル帳票に合わせて次に実装します。');
      break;
    case 'psychotropic-list':
      openOfficeReportPendingPanel('向精神薬投与患者一覧', '向精神薬投与患者一覧の出力本体は準備中です。サンプル帳票に合わせて次に実装します。');
      break;
    case 'efp-file':
      openOfficeReportPendingPanel('EFPファイル', 'EFPファイルの出力本体は準備中です。レセプト提出データ側の実装に合わせてつなぎます。');
      break;
    default:
      showToast('この帳票メニューは準備中です', 'info');
      break;
  }
}

function initOfficeReportMenu() {
  const menu = document.getElementById('office-report-menu');
  const menuButton = document.getElementById('office-report-menu-btn');
  if (menu && menuButton && menu.dataset.officeReportMenuBound !== 'true') {
    menu.dataset.officeReportMenuBound = 'true';
    menuButton.addEventListener('click', event => {
      event.preventDefault();
      event.stopPropagation();
      const shouldOpen = !menu.classList.contains('open');
      closeOfficeReportMenus();
      menu.classList.toggle('open', shouldOpen);
      menuButton.setAttribute('aria-expanded', shouldOpen ? 'true' : 'false');
    });

    document.addEventListener('click', event => {
      if (!menu.contains(event.target)) closeOfficeReportMenus();
    }, true);

    document.addEventListener('keydown', event => {
      if (event.key !== 'Escape' || !menu.classList.contains('open')) return;
      closeOfficeReportMenus();
      menuButton.focus();
    });
  }

  document.querySelectorAll('[data-office-report-action]').forEach(item => {
    if (item.dataset.officeReportBound === 'true') return;
    item.dataset.officeReportBound = 'true';
    item.addEventListener('click', async (event) => {
      event.preventDefault();
      event.stopPropagation();
      await handleOfficeReportMenuAction(item.dataset.officeReportAction);
    });
  });
}

function formatAccountingAmount(value) {
  const amount = Number(value || 0);
  return `¥${Number.isFinite(amount) ? amount.toLocaleString() : '0'}`;
}

function parseAccountingAmount(value) {
  const normalized = String(value || '').replace(/[^\d.-]/g, '');
  const amount = Math.round(Number(normalized || 0));
  return Number.isFinite(amount) ? amount : 0;
}

function formatAccountingDateTime(value) {
  if (!value) return '-';
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return String(value);
  return date.toLocaleString('ja-JP', {
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false
  });
}

function formatAccountingDate(value) {
  if (!value) return '-';
  return formatDateSlash(value) || String(value);
}

function formatAccountingDateForFile(value) {
  const normalized = normalizeKarteDateValue(value) || getLocalDateString();
  return normalized.replaceAll('-', '');
}

function formatAccountingMonthForFile(value) {
  const source = String(value || getAccountingMonthInputValue()).slice(0, 7);
  return source.replace(/[^\d]/g, '') || formatAccountingDateForFile().slice(0, 6);
}

function accountingCsvCell(value) {
  const text = value == null ? '' : String(value);
  return `"${text.replace(/"/g, '""')}"`;
}

function downloadAccountingCsv(fileName, headers, rows) {
  const lines = [
    headers.map(accountingCsvCell).join(','),
    ...rows.map(row => row.map(accountingCsvCell).join(','))
  ];
  const blob = new Blob([`\uFEFF${lines.join('\r\n')}`], { type: 'text/csv;charset=utf-8' });
  downloadBlobAsFile(blob, fileName);
}

function getAccountingPatientLabel() {
  return [currentPatient?.patient_no, currentPatient?.name].filter(Boolean).join('_') || '患者';
}

function formatReceiptSplitTypeLabel(type) {
  const labels = {
    receipt: '領収書',
    detail: '明細書',
    both: '領収書・明細書'
  };
  return labels[type] || type || '-';
}

function formatMonthlyInvoiceStatus(status) {
  const labels = {
    draft: '下書き',
    issued: '発行済み',
    paid: '入金済み',
    cancelled: '取消'
  };
  return labels[status] || status || '-';
}

function formatUnpaidStatus(status) {
  const labels = {
    active: '未収',
    partial: '一部回収',
    collected: '回収済み',
    written_off: '貸倒'
  };
  return labels[status] || status || '-';
}

function getAccountingDateInputValue(value = null) {
  return normalizeKarteDateValue(value || currentBilling?.visitDate || getCurrentKarteDateValue()) || getLocalDateString();
}

function getAccountingMonthInputValue(value = null) {
  return getAccountingDateInputValue(value).slice(0, 7);
}

function getCurrentFacilityIdForAccounting() {
  const user = Storage.getCurrentUser?.();
  return currentReception?.facility_id
    || currentPatient?.facility_id
    || user?.facility_id
    || user?.facilityId
    || user?.facility?.id
    || null;
}

function getCurrentBillingFinalAmount() {
  return Math.round(Number(
    currentBilling?.final_amount
    ?? currentBilling?.finalAmount
    ?? currentBilling?.patientAmount
    ?? currentBilling?.unpaid_amount
    ?? 0
  ));
}

function getCurrentBillingPaidAmount() {
  return Math.round(Number(currentBilling?.paid_amount ?? currentBilling?.paidAmount ?? 0));
}

function getCurrentBillingAccountingId() {
  return currentBilling?.id
    || currentBilling?.billingId
    || getCompletedBillingDisplayData()?.billing?.id
    || getCompletedBillingDisplayData()?.billing?.billingId
    || null;
}

async function ensureBillingOperationBillingId() {
  const existingBillingId = getCurrentBillingAccountingId();
  if (existingBillingId) return existingBillingId;

  if (!currentBilling || !hasBillingDisplayItems({ billing: currentBilling })) {
    restoreCompletedBillingDisplayData(getCompletedBillingDisplayData());
  }
  if (!currentBilling || !hasBillingDisplayItems({ billing: currentBilling })) {
    throw new Error('会計明細がありません');
  }

  const shouldContinue = await confirmKarteWarningsBeforeBillingPayment();
  if (!shouldContinue) return null;
  const persisted = await persistCurrentKarteBillingForPayment();
  return persisted?.id || currentBilling?.id || currentBilling?.billingId || null;
}

function formatPaymentMethodLabel(method) {
  const labels = {
    cash: '現金',
    card: 'カード',
    qr: 'QR決済',
    ic: '電子マネー',
    transfer: '振込',
    other: 'その他'
  };
  return labels[method] || method || '-';
}

function renderBillingRefundHistory(payments = [], refunds = []) {
  const paymentTotal = payments.reduce((sum, payment) => sum + parseAccountingAmount(payment.payment_amount), 0);
  const refundTotal = refunds.reduce((sum, refund) => sum + parseAccountingAmount(refund.refund_amount), 0);
  const paymentRows = payments.length ? payments.map(payment => `
    <tr>
      <td>${escapeHtml(formatAccountingDateTime(payment.payment_datetime || payment.payment_date))}</td>
      <td>${escapeHtml(formatPaymentMethodLabel(payment.payment_method))}</td>
      <td class="amount">${escapeHtml(formatAccountingAmount(payment.payment_amount))}</td>
      <td>${escapeHtml(payment.receipt_no || '-')}</td>
    </tr>
  `).join('') : '<tr><td colspan="4" class="billing-operation-empty">入金履歴がありません</td></tr>';

  const refundRows = refunds.length ? refunds.map(refund => `
    <tr>
      <td>${escapeHtml(formatAccountingDateTime(refund.refund_datetime || refund.refund_date))}</td>
      <td>${escapeHtml(formatPaymentMethodLabel(refund.refund_method))}</td>
      <td class="amount">${escapeHtml(formatAccountingAmount(refund.refund_amount))}</td>
      <td>${escapeHtml(refund.reason || '-')}</td>
    </tr>
  `).join('') : '<tr><td colspan="4" class="billing-operation-empty">返金履歴がありません</td></tr>';

  return `
    <div class="billing-operation-note">
      入金合計 ${escapeHtml(formatAccountingAmount(paymentTotal))}
      / 返金累計 ${escapeHtml(formatAccountingAmount(refundTotal))}
      / 現在入金済 ${escapeHtml(formatAccountingAmount(getCurrentBillingPaidAmount()))}
      / 未収 ${escapeHtml(formatAccountingAmount(currentBilling?.unpaid_amount))}
    </div>
    <table class="billing-operation-table">
      <thead><tr><th>入金日時</th><th>方法</th><th>金額</th><th>領収番号</th></tr></thead>
      <tbody>${paymentRows}</tbody>
    </table>
    <table class="billing-operation-table">
      <thead><tr><th>返金日時</th><th>方法</th><th>金額</th><th>理由</th></tr></thead>
      <tbody>${refundRows}</tbody>
    </table>
  `;
}

async function renderBillingRefundPanel(billingId) {
  const elements = getBillingOperationElements();
  if (!elements.body) return;

  const [paymentsResult, refundsResult] = await Promise.all([
    BillingAPI.getPayments(billingId),
    BillingAPI.getRefunds(billingId)
  ]);
  const payments = Array.isArray(paymentsResult) ? paymentsResult : [];
  const refunds = Array.isArray(refundsResult) ? refundsResult : [];
  const paymentOptions = payments.map(payment => `
    <option value="${escapeHtml(payment.id)}">
      ${escapeHtml(formatAccountingDate(payment.payment_date))} ${escapeHtml(formatPaymentMethodLabel(payment.payment_method))} ${escapeHtml(formatAccountingAmount(payment.payment_amount))}
    </option>
  `).join('');

  elements.body.innerHTML = `
    <div class="billing-operation-form">
      <div class="billing-operation-grid">
        <label class="billing-operation-field">
          <span>返金額</span>
          <input type="text" id="billing-refund-amount" inputmode="numeric" value="${escapeHtml(String(getCurrentBillingPaidAmount()))}">
        </label>
        <label class="billing-operation-field">
          <span>返金方法</span>
          <select id="billing-refund-method">
            <option value="cash">現金</option>
            <option value="card">カード</option>
            <option value="qr">QR決済</option>
            <option value="ic">電子マネー</option>
            <option value="transfer">振込</option>
            <option value="other">その他</option>
          </select>
        </label>
        <label class="billing-operation-field full">
          <span>対象入金</span>
          <select id="billing-refund-payment-id">
            <option value="">指定なし</option>
            ${paymentOptions}
          </select>
        </label>
        <label class="billing-operation-field full">
          <span>理由</span>
          <textarea id="billing-refund-reason" placeholder="返金理由"></textarea>
        </label>
      </div>
      <div class="billing-operation-actions">
        <button type="button" class="btn btn-primary" id="billing-refund-save">返金を登録</button>
      </div>
    </div>
  `;
  setBillingOperationResult(renderBillingRefundHistory(payments, refunds));
  document.getElementById('billing-refund-save')?.addEventListener('click', () => submitBillingRefund(billingId));
}

async function openBillingRefundPanel() {
  const elements = openBillingOperationModal('返金');
  if (!elements) return;

  try {
    showLoading();
    const billingId = await ensureBillingOperationBillingId();
    hideLoading();
    if (!billingId) return;
    await renderBillingRefundPanel(billingId);
  } catch (error) {
    hideLoading();
    console.error('返金画面エラー:', error);
    elements.body.innerHTML = `<div class="billing-operation-error">${escapeHtml(error?.message || '返金画面を開けませんでした')}</div>`;
  }
}

async function submitBillingRefund(billingId) {
  const amount = parseAccountingAmount(document.getElementById('billing-refund-amount')?.value);
  const method = document.getElementById('billing-refund-method')?.value || 'cash';
  const paymentId = document.getElementById('billing-refund-payment-id')?.value || null;
  const reason = document.getElementById('billing-refund-reason')?.value.trim() || null;
  if (amount <= 0) {
    showToast('返金額を入力してください', 'error');
    return;
  }

  try {
    showLoading();
    const result = await BillingAPI.createRefund(billingId, {
      refund_amount: amount,
      refund_method: method,
      payment_id: paymentId,
      reason
    });
    applyServerBillingToCurrentBilling(result?.billing);
    hideLoading();
    showToast('返金を登録しました', 'success');
    await renderBillingRefundPanel(billingId);
  } catch (error) {
    hideLoading();
    console.error('返金登録エラー:', error);
    showToast(error?.message || '返金登録に失敗しました', 'error');
  }
}

function getReceiptSplitSuggestion(totalAmount) {
  const amount = Math.max(0, Math.round(Number(totalAmount || 0)));
  if (amount <= 1) return `${amount}`;
  const first = Math.floor(amount / 2);
  return `${first}\n${amount - first}`;
}

function parseReceiptSplitAmounts(value) {
  return String(value || '')
    .split(/\n+/)
    .map(row => parseAccountingAmount(row))
    .filter(amount => amount > 0);
}

function renderReceiptSplitRows(splits = []) {
  if (!splits.length) {
    return '<tr><td colspan="4" class="billing-operation-empty">分割設定がありません</td></tr>';
  }
  return splits.map(split => `
    <tr>
      <td>${escapeHtml(String(split.split_no || ''))}</td>
      <td>${escapeHtml(formatReceiptSplitTypeLabel(split.receipt_type))}</td>
      <td class="amount">${escapeHtml(formatAccountingAmount(split.amount))}</td>
      <td>${escapeHtml(split.memo || '-')}</td>
    </tr>
  `).join('');
}

function buildBillingSplitReceiptPrintHtml(splits = []) {
  const facility = getFacilityInfoForPrint();
  const patientLabel = getAccountingPatientLabel();
  const billingDate = formatJapaneseEraDate(currentBilling?.visitDate || currentBilling?.billingDate || getAccountingDateInputValue());
  const issueDate = formatJapaneseEraDate(getLocalDateString());
  const cards = splits.map(split => `
    <section class="split-card">
      <div class="split-title">診療費分割領収書</div>
      <div class="split-meta">
        <span>発行日 ${escapeHtml(issueDate)}</span>
        <span>No. ${escapeHtml(String(split.split_no || ''))}</span>
      </div>
      <table>
        <tbody>
          <tr><th>患者</th><td>${escapeHtml(patientLabel)}</td></tr>
          <tr><th>診療日</th><td>${escapeHtml(billingDate)}</td></tr>
          <tr><th>対象</th><td>${escapeHtml(formatReceiptSplitTypeLabel(split.receipt_type))}</td></tr>
          <tr class="amount-row"><th>領収金額</th><td>${escapeHtml(formatAccountingAmount(split.amount))}</td></tr>
          <tr><th>メモ</th><td>${escapeHtml(split.memo || '')}</td></tr>
        </tbody>
      </table>
      <div class="facility">
        <strong>${escapeHtml(facility.name || '')}</strong>
        <span>${escapeHtml(facility.address || '')}</span>
        <span>${facility.phone ? `電話 ${escapeHtml(facility.phone)}` : ''}</span>
      </div>
    </section>
  `).join('');

  return `
    <!DOCTYPE html>
    <html lang="ja">
    <head>
      <meta charset="UTF-8">
      <title>分割領収書</title>
      <style>
        @page { size: A5 portrait; margin: 10mm; }
        * { box-sizing: border-box; }
        body {
          margin: 0;
          background: #f3f4f6;
          color: #111827;
          font-family: "Yu Gothic", "Meiryo", sans-serif;
          font-size: 12px;
        }
        .split-card {
          width: 128mm;
          min-height: 188mm;
          margin: 0 auto 8mm;
          padding: 11mm;
          background: #fff;
          page-break-after: always;
        }
        .split-card:last-child { page-break-after: auto; }
        .split-title {
          text-align: center;
          font-size: 18px;
          font-weight: 700;
          margin-bottom: 7mm;
        }
        .split-meta {
          display: flex;
          justify-content: space-between;
          margin-bottom: 5mm;
        }
        table {
          width: 100%;
          border-collapse: collapse;
        }
        th,
        td {
          border: 1px solid #111827;
          padding: 2.5mm;
          text-align: left;
          vertical-align: top;
        }
        th { width: 31mm; font-weight: 400; background: #f8faf9; }
        .amount-row td {
          text-align: right;
          font-size: 20px;
          font-weight: 700;
        }
        .facility {
          margin-top: 10mm;
          display: grid;
          gap: 1.5mm;
          line-height: 1.5;
        }
        @media print {
          body { background: #fff; }
          .split-card { margin: 0; }
        }
      </style>
    </head>
    <body>${cards}</body>
    </html>
  `;
}

async function openBillingSplitReceiptPrint(splits = []) {
  if (!splits.length) {
    showToast('分割設定がありません', 'error');
    return;
  }
  if (!(await ensureFacilityInfoForPrintableDocument())) return;
  openPrintableHtml(buildBillingSplitReceiptPrintHtml(splits), '分割領収書', false);
}

function downloadBillingSplitCsv(splits = []) {
  if (!splits.length) {
    showToast('分割設定がありません', 'error');
    return;
  }
  downloadAccountingCsv(
    `領収書分割_${sanitizeDocumentFileName(getAccountingPatientLabel())}_${formatAccountingDateForFile(getAccountingDateInputValue())}.csv`,
    ['No', '対象', '金額', 'メモ'],
    splits.map(split => [
      split.split_no || '',
      formatReceiptSplitTypeLabel(split.receipt_type),
      split.amount || 0,
      split.memo || ''
    ])
  );
}

async function renderBillingSplitPanel(billingId) {
  const elements = getBillingOperationElements();
  if (!elements.body) return;
  const totalAmount = getCurrentBillingFinalAmount();
  const splitsResult = await BillingAPI.getReceiptSplits(billingId);
  const splits = Array.isArray(splitsResult) ? splitsResult : [];

  elements.body.innerHTML = `
    <div class="billing-operation-form">
      <div class="billing-operation-note">
        請求額 ${escapeHtml(formatAccountingAmount(totalAmount))} と分割金額の合計が一致する必要があります。
      </div>
      <div class="billing-operation-grid">
        <label class="billing-operation-field full">
          <span>分割金額（1行に1金額）</span>
          <textarea id="billing-split-amounts" inputmode="numeric">${escapeHtml(getReceiptSplitSuggestion(totalAmount))}</textarea>
        </label>
        <label class="billing-operation-field">
          <span>出力対象</span>
          <select id="billing-split-type">
            <option value="receipt">領収書</option>
            <option value="detail">明細書</option>
            <option value="both">領収書・明細書</option>
          </select>
        </label>
        <label class="billing-operation-field full">
          <span>メモ</span>
          <input type="text" id="billing-split-memo" placeholder="任意">
        </label>
      </div>
      <div class="billing-operation-actions">
        <button type="button" class="btn btn-primary" id="billing-split-save">分割を保存</button>
      </div>
    </div>
  `;
  setBillingOperationResult(`
    ${splits.length ? `
      <div class="billing-operation-result-actions">
        <button type="button" class="btn btn-outline btn-sm" id="billing-split-print">分割領収書を表示</button>
        <button type="button" class="btn btn-outline btn-sm" id="billing-split-csv">CSV出力</button>
      </div>
    ` : ''}
    <table class="billing-operation-table">
      <thead><tr><th>No.</th><th>対象</th><th>金額</th><th>メモ</th></tr></thead>
      <tbody>${renderReceiptSplitRows(splits)}</tbody>
    </table>
  `);
  document.getElementById('billing-split-save')?.addEventListener('click', () => submitBillingSplit(billingId));
  document.getElementById('billing-split-print')?.addEventListener('click', () => openBillingSplitReceiptPrint(splits));
  document.getElementById('billing-split-csv')?.addEventListener('click', () => downloadBillingSplitCsv(splits));
}

async function openBillingSplitPanel() {
  const elements = openBillingOperationModal('領収書分割');
  if (!elements) return;

  try {
    showLoading();
    const billingId = await ensureBillingOperationBillingId();
    hideLoading();
    if (!billingId) return;
    await renderBillingSplitPanel(billingId);
  } catch (error) {
    hideLoading();
    console.error('領収書分割画面エラー:', error);
    elements.body.innerHTML = `<div class="billing-operation-error">${escapeHtml(error?.message || '領収書分割画面を開けませんでした')}</div>`;
  }
}

async function submitBillingSplit(billingId) {
  const amounts = parseReceiptSplitAmounts(document.getElementById('billing-split-amounts')?.value);
  const totalAmount = getCurrentBillingFinalAmount();
  const sumAmount = amounts.reduce((sum, amount) => sum + amount, 0);
  if (amounts.length < 2) {
    showToast('分割金額は2行以上入力してください', 'error');
    return;
  }
  if (sumAmount !== totalAmount) {
    showToast(`分割合計が請求額と一致していません（${formatAccountingAmount(sumAmount)}）`, 'error');
    return;
  }

  try {
    showLoading();
    await BillingAPI.createReceiptSplits(billingId, {
      amounts,
      receipt_type: document.getElementById('billing-split-type')?.value || 'receipt',
      memo: document.getElementById('billing-split-memo')?.value.trim() || null
    });
    hideLoading();
    showToast('領収書分割を保存しました', 'success');
    await renderBillingSplitPanel(billingId);
  } catch (error) {
    hideLoading();
    console.error('領収書分割保存エラー:', error);
    showToast(error?.message || '領収書分割の保存に失敗しました', 'error');
  }
}

function renderMonthlyInvoiceRows(rows = []) {
  if (!rows.length) {
    return '<tr><td colspan="8" class="billing-operation-empty">月まとめ請求がありません</td></tr>';
  }
  return rows.map(invoice => `
    <tr>
      <td>${escapeHtml(formatAccountingDate(invoice.invoice_month))}</td>
      <td>${escapeHtml(invoice.invoice_no || '-')}</td>
      <td>${escapeHtml(invoice.patient_no || currentPatient?.patient_no || '-')}</td>
      <td>${escapeHtml(invoice.patient_name || currentPatient?.name || '-')}</td>
      <td>${escapeHtml(String(invoice.billing_count || 0))}</td>
      <td class="amount">${escapeHtml(formatAccountingAmount(invoice.total_amount))}</td>
      <td class="amount">${escapeHtml(formatAccountingAmount(invoice.unpaid_amount))}</td>
      <td>${escapeHtml(formatMonthlyInvoiceStatus(invoice.status))}</td>
    </tr>
  `).join('');
}

function downloadMonthlyInvoiceCsv() {
  if (!billingOperationMonthlyInvoices.length) {
    showToast('月まとめ請求がありません', 'error');
    return;
  }
  const month = document.getElementById('billing-monthly-invoice-month')?.value || getAccountingMonthInputValue();
  downloadAccountingCsv(
    `月まとめ請求_${formatAccountingMonthForFile(month)}.csv`,
    ['請求月', '請求番号', '患者番号', '氏名', '件数', '合計', '未収', '状態', 'メモ'],
    billingOperationMonthlyInvoices.map(invoice => [
      formatAccountingDate(invoice.invoice_month),
      invoice.invoice_no || '',
      invoice.patient_no || currentPatient?.patient_no || '',
      invoice.patient_name || currentPatient?.name || '',
      invoice.billing_count || 0,
      invoice.total_amount || 0,
      invoice.unpaid_amount || 0,
      formatMonthlyInvoiceStatus(invoice.status),
      invoice.memo || ''
    ])
  );
}

function buildMonthlyInvoicePrintHtml(rows = []) {
  const facility = getFacilityInfoForPrint();
  const month = document.getElementById('billing-monthly-invoice-month')?.value || getAccountingMonthInputValue();
  const rowHtml = rows.map(invoice => `
    <tr>
      <td>${escapeHtml(invoice.invoice_no || '')}</td>
      <td>${escapeHtml(invoice.patient_no || currentPatient?.patient_no || '')}</td>
      <td>${escapeHtml(invoice.patient_name || currentPatient?.name || '')}</td>
      <td class="right">${escapeHtml(String(invoice.billing_count || 0))}</td>
      <td class="right">${escapeHtml(formatAccountingAmount(invoice.total_amount))}</td>
      <td class="right">${escapeHtml(formatAccountingAmount(invoice.paid_amount))}</td>
      <td class="right">${escapeHtml(formatAccountingAmount(invoice.unpaid_amount))}</td>
      <td>${escapeHtml(formatMonthlyInvoiceStatus(invoice.status))}</td>
    </tr>
  `).join('') || '<tr><td colspan="8" class="empty">月まとめ請求がありません</td></tr>';

  const total = rows.reduce((sum, invoice) => sum + parseAccountingAmount(invoice.total_amount), 0);
  const unpaid = rows.reduce((sum, invoice) => sum + parseAccountingAmount(invoice.unpaid_amount), 0);

  return `
    <!DOCTYPE html>
    <html lang="ja">
    <head>
      <meta charset="UTF-8">
      <title>月まとめ請求控え</title>
      <style>
        @page { size: A4 portrait; margin: 12mm; }
        body { margin: 0; color: #111827; font-family: "Yu Gothic", "Meiryo", sans-serif; font-size: 11px; }
        h1 { margin: 0 0 6mm; text-align: center; font-size: 18px; }
        .meta { display: flex; justify-content: space-between; margin-bottom: 5mm; }
        table { width: 100%; border-collapse: collapse; }
        th, td { border: 1px solid #111827; padding: 2mm; text-align: left; vertical-align: top; }
        th { background: #f3f7f5; font-weight: 700; }
        .right { text-align: right; }
        .summary { margin-top: 5mm; display: flex; justify-content: flex-end; gap: 8mm; font-weight: 700; }
        .facility { margin-top: 8mm; line-height: 1.6; }
        .empty { text-align: center; color: #6b7280; }
      </style>
    </head>
    <body>
      <h1>月まとめ請求控え</h1>
      <div class="meta">
        <span>対象月 ${escapeHtml(month.replace('-', '/'))}</span>
        <span>発行日 ${escapeHtml(formatJapaneseEraDate(getLocalDateString()))}</span>
      </div>
      <table>
        <thead>
          <tr><th>請求番号</th><th>患者番号</th><th>氏名</th><th>件数</th><th>合計</th><th>入金</th><th>未収</th><th>状態</th></tr>
        </thead>
        <tbody>${rowHtml}</tbody>
      </table>
      <div class="summary">
        <span>合計 ${escapeHtml(formatAccountingAmount(total))}</span>
        <span>未収 ${escapeHtml(formatAccountingAmount(unpaid))}</span>
      </div>
      <div class="facility">
        <strong>${escapeHtml(facility.name || '')}</strong><br>
        ${escapeHtml(facility.address || '')}<br>
        ${facility.phone ? `電話 ${escapeHtml(facility.phone)}` : ''}
      </div>
    </body>
    </html>
  `;
}

async function openMonthlyInvoicePrint() {
  if (!billingOperationMonthlyInvoices.length) {
    showToast('月まとめ請求がありません', 'error');
    return;
  }
  if (!(await ensureFacilityInfoForPrintableDocument())) return;
  openPrintableHtml(buildMonthlyInvoicePrintHtml(billingOperationMonthlyInvoices), '月まとめ請求控え', false);
}

async function loadMonthlyInvoiceRows(facilityId) {
  const month = document.getElementById('billing-monthly-invoice-month')?.value || getAccountingMonthInputValue();
  const invoiceMonth = `${month}-01`;
  try {
    setBillingOperationResult('<div class="billing-operation-empty">月まとめ請求を読み込み中...</div>');
    const rows = await BillingAPI.listMonthlyInvoices({
      facilityId,
      invoiceMonth,
      patientId: currentPatient?.id || null
    });
    billingOperationMonthlyInvoices = Array.isArray(rows) ? rows : [];
    setBillingOperationResult(`
      ${billingOperationMonthlyInvoices.length ? `
        <div class="billing-operation-result-actions">
          <button type="button" class="btn btn-outline btn-sm" id="billing-monthly-invoice-print">請求控えを表示</button>
          <button type="button" class="btn btn-outline btn-sm" id="billing-monthly-invoice-csv">CSV出力</button>
        </div>
      ` : ''}
      <table class="billing-operation-table">
        <thead><tr><th>請求月</th><th>請求番号</th><th>患者番号</th><th>氏名</th><th>件数</th><th>合計</th><th>未収</th><th>状態</th></tr></thead>
        <tbody>${renderMonthlyInvoiceRows(billingOperationMonthlyInvoices)}</tbody>
      </table>
    `);
    document.getElementById('billing-monthly-invoice-print')?.addEventListener('click', openMonthlyInvoicePrint);
    document.getElementById('billing-monthly-invoice-csv')?.addEventListener('click', downloadMonthlyInvoiceCsv);
  } catch (error) {
    console.error('月まとめ請求一覧エラー:', error);
    setBillingOperationResult(`<div class="billing-operation-error">${escapeHtml(error?.message || '月まとめ請求を読み込めませんでした')}</div>`);
  }
}

