async function submitMonthlyInvoice(facilityId) {
  const month = document.getElementById('billing-monthly-invoice-month')?.value || getAccountingMonthInputValue();
  try {
    showLoading();
    await BillingAPI.createMonthlyInvoice({
      facility_id: facilityId,
      patient_id: currentPatient.id,
      invoice_month: `${month}-01`,
      include_paid: document.getElementById('billing-monthly-invoice-include-paid')?.value === 'true',
      memo: document.getElementById('billing-monthly-invoice-memo')?.value.trim() || null
    });
    hideLoading();
    showToast('月まとめ請求を作成しました', 'success');
    await loadMonthlyInvoiceRows(facilityId);
  } catch (error) {
    hideLoading();
    console.error('月まとめ請求作成エラー:', error);
  showToast(error?.message || '月まとめ請求の作成に失敗しました', 'error');
  }
}

function renderAccountingUnpaidRows(rows = []) {
  if (!rows.length) {
    return '<tr><td colspan="8" class="billing-operation-empty">対象期間の未収金はありません</td></tr>';
  }
  return rows.map(row => `
    <tr>
      <td>${escapeHtml(formatAccountingDate(row.billing_date))}</td>
      <td>${escapeHtml(row.billing_no || '-')}</td>
      <td>${escapeHtml(row.patient_no || '-')}</td>
      <td>${escapeHtml(row.patient_name || '-')}</td>
      <td class="amount">${escapeHtml(formatAccountingAmount(row.original_amount))}</td>
      <td class="amount">${escapeHtml(formatAccountingAmount(row.unpaid_amount))}</td>
      <td>${escapeHtml(formatUnpaidStatus(row.status))}</td>
      <td>${escapeHtml(row.last_reminder_date ? formatAccountingDate(row.last_reminder_date) : '-')}</td>
    </tr>
  `).join('');
}

function downloadAccountingStatsCsv() {
  if (!billingOperationStatsSnapshot?.stats) {
    showToast('会計集計がありません', 'error');
    return;
  }
  const { stats, dateFrom, dateTo } = billingOperationStatsSnapshot;
  const summary = stats.summary || {};
  const rows = [
    ['集計', `${formatAccountingDate(dateFrom)}-${formatAccountingDate(dateTo)}`, summary.billing_count || 0, summary.final_amount || 0, summary.paid_amount || 0, summary.unpaid_amount || 0]
  ];
  (stats.daily || []).forEach(row => {
    rows.push(['日別', formatAccountingDate(row.date), row.billing_count || 0, row.final_amount || 0, row.paid_amount || 0, row.unpaid_amount || 0]);
  });
  Object.entries(stats.payment_methods || {}).forEach(([method, value]) => {
    rows.push(['入金方法', formatPaymentMethodLabel(method), value.count || 0, value.amount || 0, '', '']);
  });
  Object.entries(stats.refund_methods || {}).forEach(([method, value]) => {
    rows.push(['返金方法', formatPaymentMethodLabel(method), value.count || 0, value.amount || 0, '', '']);
  });
  downloadAccountingCsv(
    `日計月計_${formatAccountingDateForFile(dateFrom)}_${formatAccountingDateForFile(dateTo)}.csv`,
    ['区分', '日付/方法', '件数', '請求/金額', '入金', '未収'],
    rows
  );
}

function downloadAccountingUnpaidCsv() {
  if (!billingOperationUnpaidRows.length) {
    showToast('未収金がありません', 'error');
    return;
  }
  const dateFrom = billingOperationStatsSnapshot?.dateFrom || document.getElementById('billing-stats-date-from')?.value || getLocalDateString();
  const dateTo = billingOperationStatsSnapshot?.dateTo || document.getElementById('billing-stats-date-to')?.value || getLocalDateString();
  downloadAccountingCsv(
    `未収一覧_${formatAccountingDateForFile(dateFrom)}_${formatAccountingDateForFile(dateTo)}.csv`,
    ['診療日', '会計番号', '患者番号', '氏名', '元請求額', '未収額', '状態', '督促回数', '最終督促日'],
    billingOperationUnpaidRows.map(row => [
      formatAccountingDate(row.billing_date),
      row.billing_no || '',
      row.patient_no || '',
      row.patient_name || '',
      row.original_amount || 0,
      row.unpaid_amount || 0,
      formatUnpaidStatus(row.status),
      row.reminder_count || 0,
      row.last_reminder_date ? formatAccountingDate(row.last_reminder_date) : ''
    ])
  );
}

async function downloadAccountingBusinessReportZip() {
  const facilityId = getCurrentFacilityIdForAccounting();
  if (!facilityId) {
    showToast('施設を特定できませんでした', 'error');
    return;
  }

  const dateFrom = billingOperationStatsSnapshot?.dateFrom || document.getElementById('billing-stats-date-from')?.value || getLocalDateString();
  const dateTo = billingOperationStatsSnapshot?.dateTo || document.getElementById('billing-stats-date-to')?.value || getLocalDateString();
  try {
    showLoading();
    const { blob, filename } = await BillingAPI.downloadBusinessReportZip(facilityId, dateFrom, dateTo);
    hideLoading();
    downloadBlobAsFile(blob, filename);
    showToast('経営データ集計ZIPをダウンロードしました', 'success');
  } catch (error) {
    hideLoading();
    console.error('経営データ集計ZIPエラー:', error);
    showToast(error?.message || '経営データ集計ZIPの作成に失敗しました', 'error');
  }
}

function renderAccountingStatsResult(stats, unpaidRows = []) {
  const summary = stats?.summary || {};
  const dailyRows = (stats?.daily || []).map(row => `
    <tr>
      <td>${escapeHtml(formatAccountingDate(row.date))}</td>
      <td>${escapeHtml(String(row.billing_count || 0))}</td>
      <td class="amount">${escapeHtml(formatAccountingAmount(row.final_amount))}</td>
      <td class="amount">${escapeHtml(formatAccountingAmount(row.paid_amount))}</td>
      <td class="amount">${escapeHtml(formatAccountingAmount(row.unpaid_amount))}</td>
    </tr>
  `).join('') || '<tr><td colspan="5" class="billing-operation-empty">対象期間の会計がありません</td></tr>';
  const paymentRows = Object.entries(stats?.payment_methods || {}).map(([method, value]) => `
    <tr>
      <td>${escapeHtml(formatPaymentMethodLabel(method))}</td>
      <td>${escapeHtml(String(value.count || 0))}</td>
      <td class="amount">${escapeHtml(formatAccountingAmount(value.amount))}</td>
    </tr>
  `).join('') || '<tr><td colspan="3" class="billing-operation-empty">入金集計がありません</td></tr>';
  const refundRows = Object.entries(stats?.refund_methods || {}).map(([method, value]) => `
    <tr>
      <td>${escapeHtml(formatPaymentMethodLabel(method))}</td>
      <td>${escapeHtml(String(value.count || 0))}</td>
      <td class="amount">${escapeHtml(formatAccountingAmount(value.amount))}</td>
    </tr>
  `).join('') || '<tr><td colspan="3" class="billing-operation-empty">返金集計がありません</td></tr>';

  return `
    <div class="billing-operation-result-actions">
      <button type="button" class="btn btn-outline btn-sm" id="billing-stats-csv">集計CSV</button>
      <button type="button" class="btn btn-outline btn-sm" id="billing-unpaid-csv">未収CSV</button>
      <button type="button" class="btn btn-outline btn-sm" id="billing-business-report-zip">経営データZIP</button>
    </div>
    <div class="billing-operation-note">
      件数 ${escapeHtml(String(summary.billing_count || 0))} / 請求 ${escapeHtml(formatAccountingAmount(summary.final_amount))}
      / 入金 ${escapeHtml(formatAccountingAmount(summary.paid_amount))} / 未収 ${escapeHtml(formatAccountingAmount(summary.unpaid_amount))}
      / 自費 ${escapeHtml(formatAccountingAmount(summary.self_pay_amount))} / 公費 ${escapeHtml(formatAccountingAmount(summary.public_expense_amount))}
    </div>
    <table class="billing-operation-table">
      <thead><tr><th>日付</th><th>件数</th><th>請求</th><th>入金</th><th>未収</th></tr></thead>
      <tbody>${dailyRows}</tbody>
    </table>
    <table class="billing-operation-table">
      <thead><tr><th>入金方法</th><th>件数</th><th>金額</th></tr></thead>
      <tbody>${paymentRows}</tbody>
    </table>
    <table class="billing-operation-table">
      <thead><tr><th>返金方法</th><th>件数</th><th>金額</th></tr></thead>
      <tbody>${refundRows}</tbody>
    </table>
    <div class="billing-operation-section-title">未収金</div>
    <table class="billing-operation-table">
      <thead><tr><th>診療日</th><th>会計番号</th><th>患者番号</th><th>氏名</th><th>元請求額</th><th>未収額</th><th>状態</th><th>最終督促</th></tr></thead>
      <tbody>${renderAccountingUnpaidRows(unpaidRows)}</tbody>
    </table>
  `;
}

async function loadAccountingStats(facilityId) {
  const dateFrom = document.getElementById('billing-stats-date-from')?.value || `${getAccountingMonthInputValue()}-01`;
  const dateTo = document.getElementById('billing-stats-date-to')?.value || getAccountingDateInputValue();
  try {
    setBillingOperationResult('<div class="billing-operation-empty">集計中...</div>');
    const [stats, unpaidRows] = await Promise.all([
      BillingAPI.getPeriodStats(facilityId, dateFrom, dateTo),
      BillingAPI.listUnpaidRecords({
        facilityId,
        dateFrom,
        dateTo,
        status: 'active'
      })
    ]);
    billingOperationStatsSnapshot = { stats, dateFrom, dateTo };
    billingOperationUnpaidRows = Array.isArray(unpaidRows) ? unpaidRows : [];
    setBillingOperationResult(renderAccountingStatsResult(stats, billingOperationUnpaidRows));
    document.getElementById('billing-stats-csv')?.addEventListener('click', downloadAccountingStatsCsv);
    document.getElementById('billing-unpaid-csv')?.addEventListener('click', downloadAccountingUnpaidCsv);
    document.getElementById('billing-business-report-zip')?.addEventListener('click', downloadAccountingBusinessReportZip);
  } catch (error) {
    console.error('会計集計エラー:', error);
    setBillingOperationResult(`<div class="billing-operation-error">${escapeHtml(error?.message || '会計集計に失敗しました')}</div>`);
  }
}

async function openAccountingStatsPanel(title = '日計・月計') {
  const elements = openBillingOperationModal(title);
  if (!elements) return;
  const facilityId = getCurrentFacilityIdForAccounting();
  if (!facilityId) {
    elements.body.innerHTML = '<div class="billing-operation-error">施設を特定できませんでした</div>';
    return;
  }
  const month = getAccountingMonthInputValue();
  elements.body.innerHTML = `
    <div class="billing-operation-form">
      <div class="billing-operation-grid">
        <label class="billing-operation-field">
          <span>開始日</span>
          <input type="date" id="billing-stats-date-from" value="${escapeHtml(`${month}-01`)}">
        </label>
        <label class="billing-operation-field">
          <span>終了日</span>
          <input type="date" id="billing-stats-date-to" value="${escapeHtml(getAccountingDateInputValue())}">
        </label>
      </div>
      <div class="billing-operation-actions">
        <button type="button" class="btn btn-primary" id="billing-stats-load">集計</button>
      </div>
    </div>
  `;
  document.getElementById('billing-stats-load')?.addEventListener('click', () => loadAccountingStats(facilityId));
  await loadAccountingStats(facilityId);
}

function renderBillingRecalculateResult(result) {
  const rows = (result?.items || []).slice(0, 40).map(item => `
    <tr>
      <td>${escapeHtml(formatAccountingDate(item.billing_date))}</td>
      <td>${escapeHtml(String(item.billing_id || ''))}</td>
      <td class="amount">${escapeHtml(formatAccountingAmount(item.before_final_amount))}</td>
      <td class="amount">${escapeHtml(formatAccountingAmount(item.after_final_amount))}</td>
      <td>${escapeHtml(item.payment_status || '-')}</td>
    </tr>
  `).join('') || '<tr><td colspan="5" class="billing-operation-empty">再計算対象がありません</td></tr>';

  return `
    <div class="billing-operation-result-actions">
      <button type="button" class="btn btn-outline btn-sm" id="billing-recalculate-csv">結果CSV</button>
    </div>
    <div class="billing-operation-note">
      対象 ${escapeHtml(String(result?.count || 0))}件 / 変更 ${escapeHtml(String(result?.changed_count || 0))}件
      ${result?.dry_run ? ' / 確認のみ' : ' / 更新済み'}
    </div>
    <table class="billing-operation-table">
      <thead><tr><th>診療日</th><th>会計ID</th><th>再計算前</th><th>再計算後</th><th>状態</th></tr></thead>
      <tbody>${rows}</tbody>
    </table>
  `;
}

function downloadBillingRecalculateCsv() {
  if (!billingOperationRecalculateResult) {
    showToast('再計算結果がありません', 'error');
    return;
  }
  const result = billingOperationRecalculateResult;
  downloadAccountingCsv(
    `一括再計算_${formatAccountingMonthForFile(result.target_month)}_${result.dry_run ? '確認' : '更新'}.csv`,
    ['診療日', '会計ID', '患者ID', '再計算前', '再計算後', '未収前', '未収後', '状態'],
    (result.items || []).map(item => [
      formatAccountingDate(item.billing_date),
      item.billing_id || '',
      item.patient_id || '',
      item.before_final_amount || 0,
      item.after_final_amount || 0,
      item.before_unpaid_amount || 0,
      item.after_unpaid_amount || 0,
      item.payment_status || ''
    ])
  );
}

async function openBillingRecalculatePanel() {
  const elements = openBillingOperationModal('一括再計算');
  if (!elements) return;
  const facilityId = getCurrentFacilityIdForAccounting();
  if (!facilityId) {
    elements.body.innerHTML = '<div class="billing-operation-error">施設を特定できませんでした</div>';
    return;
  }

  elements.body.innerHTML = `
    <div class="billing-operation-form">
      <div class="billing-operation-note">まず確認のみで差分を見て、問題なければ更新実行に切り替えてください。</div>
      <div class="billing-operation-grid">
        <label class="billing-operation-field">
          <span>対象月</span>
          <input type="month" id="billing-recalculate-month" value="${escapeHtml(getAccountingMonthInputValue())}">
        </label>
        <label class="billing-operation-field">
          <span>範囲</span>
          <select id="billing-recalculate-patient-scope">
            <option value="patient" ${currentPatient?.id ? '' : 'disabled'}>この患者のみ</option>
            <option value="facility">施設全体</option>
          </select>
        </label>
        <label class="billing-operation-field full">
          <span>実行方法</span>
          <select id="billing-recalculate-dry-run">
            <option value="true">確認のみ</option>
            <option value="false">更新実行</option>
          </select>
        </label>
      </div>
      <div class="billing-operation-actions">
        <button type="button" class="btn btn-primary" id="billing-recalculate-run">再計算</button>
      </div>
    </div>
  `;
  if (!currentPatient?.id) {
    const scope = document.getElementById('billing-recalculate-patient-scope');
    if (scope) scope.value = 'facility';
  }
  document.getElementById('billing-recalculate-run')?.addEventListener('click', () => runBillingRecalculate(facilityId));
}

async function runBillingRecalculate(facilityId) {
  const month = document.getElementById('billing-recalculate-month')?.value || getAccountingMonthInputValue();
  const scope = document.getElementById('billing-recalculate-patient-scope')?.value || 'patient';
  const dryRun = document.getElementById('billing-recalculate-dry-run')?.value !== 'false';
  if (!dryRun) {
    const confirmed = await showAppConfirm({
      title: '一括再計算',
      message: '対象月の会計金額を更新します。実行してよろしいですか？',
      confirmText: '更新する',
      cancelText: 'キャンセル'
    });
    if (!confirmed) return;
  }

  try {
    showLoading();
    const result = await BillingAPI.recalculateMonth({
      facility_id: facilityId,
      target_month: `${month}-01`,
      patient_id: scope === 'patient' && currentPatient?.id ? currentPatient.id : null,
      dry_run: dryRun
    });
    hideLoading();
    billingOperationRecalculateResult = result;
    setBillingOperationResult(renderBillingRecalculateResult(result));
    document.getElementById('billing-recalculate-csv')?.addEventListener('click', downloadBillingRecalculateCsv);
    showToast(dryRun ? '再計算結果を確認しました' : '一括再計算を実行しました', 'success');
  } catch (error) {
    hideLoading();
    console.error('一括再計算エラー:', error);
    showToast(error?.message || '一括再計算に失敗しました', 'error');
  }
}

