// 時間区分を判定: 'normal', 'overtime', 'holiday', 'night'
function getTimeCategory(dateTime = new Date()) {
  const hour = dateTime.getHours();
  const day = dateTime.getDay(); // 0=日曜, 6=土曜

  // 深夜: 22時～6時
  if (hour >= 22 || hour < 6) {
    return 'night';
  }

  // 休日: 日曜・祝日（簡易判定として日曜のみ）
  if (day === 0) {
    return 'holiday';
  }

  // 時間外: 土曜午後（13時以降）、平日早朝（6時～8時）、平日夜間（18時～22時）
  if (day === 6 && hour >= 13) {
    return 'overtime';
  }
  if (day >= 1 && day <= 5) {
    if (hour < 8 || hour >= 18) {
      return 'overtime';
    }
  }

  return 'normal';
}

// 年齢区分を判定: 'infant'(6歳未満), 'child'(6-15歳), 'adult'(15歳以上)
function getAgeCategory(birthDate) {
  const age = calculateAge(birthDate);
  if (typeof age !== 'number' || isNaN(age)) return 'adult';

  if (age < 6) return 'infant';   // 乳幼児
  if (age < 15) return 'child';   // 小児
  return 'adult';
}

// 初診/再診を判定（同期版 - 受付フラグのみ）
function isFirstVisit() {
  // 受付データに初診フラグがあれば使用
  const receptionFirstVisit = getFirstVisitOverrideFromReception();
  if (receptionFirstVisit !== null) {
    return receptionFirstVisit;
  }
  // 受付データがない場合はnull（要API確認）
  return null;
}

function getFirstVisitOverrideFromReception() {
  if (!currentReception || currentReception.first_visit === undefined || currentReception.first_visit === null) {
    return null;
  }
  return currentReception.first_visit === true || currentReception.first_visit === 1 || currentReception.first_visit === '1';
}

function normalizePrescriptionDispensingType(prescription) {
  const raw = prescription.dispensing_type || prescription.prescription_type || '院外';
  if (raw === '院内' || raw === 'internal') return '院内';
  return '院外';
}

function inferPrescriptionDrugType(prescription) {
  const raw = prescription.drug_type;
  if (['内服', '外用', '頓服', '注射'].includes(raw)) return raw;

  const frequency = String(prescription.frequency || '');
  const unit = String(prescription.unit || prescription.dosage_unit || '');
  const name = String(prescription.drug_name || prescription.name || '');

  if (frequency.startsWith('[注]') || /(注|点滴|静注|筋注|皮下注|注射)/.test(name)) return '注射';
  if (frequency.startsWith('[外]') || /^(枚|g|mL|個)$/.test(unit) || /(テープ|パップ|ゲル|軟膏|クリーム|ローション|点眼|点鼻|吸入|坐剤|坐薬|貼付)/.test(name)) return '外用';
  if (frequency.startsWith('[頓]') || frequency.includes('頓服')) return '頓服';
  return '内服';
}

// 初診/再診を判定（非同期版 - APIでカルテ履歴を確認）
async function checkFirstVisit() {
  // 受付データに初診フラグがあれば使用
  const receptionFirstVisit = getFirstVisitOverrideFromReception();
  if (receptionFirstVisit !== null) {
    return receptionFirstVisit;
  }

  // APIで過去のカルテを確認
  if (currentPatient && typeof RecordAPI !== 'undefined') {
    try {
      const records = await RecordAPI.list(currentPatient.id, 10);
      // 過去のカルテがなければ初診
      if (!records || records.length === 0) {
        return true;
      }
      // 過去のカルテがあれば再診
      return false;
    } catch (e) {
      console.warn('初診判定APIエラー:', e);
    }
  }

  // デフォルトは初診（新規患者を再診扱いしないため）
  return true;
}

