// 自動算定提案結果を一時保存
let autoCalcResult = null;
let autoCalcSuggestedItems = [];

function isAutoCalcItemAlreadyAdded(code, name) {
  const standard = findStandardBillingAction({ code, name });
  const candidateCodes = new Set([
    code,
    standard?.code,
    ...(standard?.codeAliases || [])
  ].filter(Boolean).map(value => String(value)));
  const aliases = {
    '処方箋料': ['処方箋料', '処方箋料（その他）'],
    '処方箋料（その他）': ['処方箋料', '処方箋料（その他）'],
    '処方料': ['処方料', '処方料（その他）'],
    '処方料（その他）': ['処方料', '処方料（その他）'],
    '調剤料': ['調剤料', '調剤料（内服薬）', '調剤料（外用薬）']
  };
  const candidateNames = new Set([name, ...(aliases[name] || [])].filter(Boolean));
  return selectedActions.some(action => {
    const actionCode = action.code || action.action_code || '';
    const actionName = action.name || action.action_name || '';
    const actionStandard = findStandardBillingAction(action);
    const actionCodes = new Set([
      actionCode,
      actionStandard?.code,
      ...(actionStandard?.codeAliases || [])
    ].filter(Boolean).map(value => String(value)));
    return (
      [...candidateCodes].some(candidateCode => actionCodes.has(candidateCode))
      || candidateNames.has(actionName)
      || (standard && normalizeStandardBillingLookupText(actionName) === normalizeStandardBillingLookupText(standard.name))
    );
  });
}

function getAutoCalcActionCategory(item) {
  if ((item.category || '').includes('処方')) return '投薬';
  if ((item.category || '').includes('施設') || (item.category || '').includes('その他')) return 'その他';
  return '診察';
}

function getAutoCalcItemIcon(item) {
  const category = getAutoCalcActionCategory(item);
  return getCategoryIcon(category);
}

function isAutoCalcSuggestionInsertable(action, isAlreadyAdded) {
  if (!action) return false;
  if (isAlreadyAdded) return false;
  if (action.auto_add === false) return false;
  return Boolean(action.code || action.name);
}

function isFacilityAutoCalcCatalogOnlyAction(action) {
  if (!action) return false;
  if (action.source === 'digikar_standard') return true;
  if (action.conditionKey) return true;
  if (action.requiresExactMasterCode) return true;
  return false;
}

function buildAutoCalcSuggestedItems(result) {
  const items = [];

  if (result.suggested_actions) {
    result.suggested_actions.forEach(action => {
      const isAlreadyAdded = isAutoCalcItemAlreadyAdded(action.code, action.name);
      if (!isAutoCalcSuggestionInsertable(action, isAlreadyAdded)) return;

      items.push(enrichStandardBillingAction({
        code: action.code,
        name: action.name,
        points: Number(action.score || 0),
        category: action.category || '診察',
        reason: action.reason || '',
        autoAdd: action.auto_add,
        checked: true,
        disabled: false
      }));
    });
  }

  const today = new Date();
  const firstVisit = result.visit_type === 'initial';
  facilityAutoCalcActions.forEach(fac => {
    if (isFacilityAutoCalcCatalogOnlyAction(fac)) return;
    if (fac.isAutoAdd === false) return;
    if (!fac.period) return;

    const [startStr, endStr] = fac.period.split('〜');
    const start = new Date(startStr);
    const end = new Date(endStr);
    if (Number.isNaN(start.getTime()) || Number.isNaN(end.getTime())) return;
    if (today < start || today > end) return;

    const actionLower = fac.action.toLowerCase();
    const isForFirst = actionLower.includes('初診');
    const isForRevisit = actionLower.includes('再診');
    if ((isForFirst && !firstVisit) || (isForRevisit && firstVisit)) return;

    const actionCode = fac.actionCode || fac.group;
    const isAlreadyAdded = isAutoCalcItemAlreadyAdded(actionCode, fac.action);
    if (isAlreadyAdded) return;

    items.push(enrichStandardBillingAction({
      code: actionCode,
      name: fac.action,
      points: Number(fac.score || 0),
      category: fac.category || '施設設定',
      reason: fac.condition || fac.period,
      autoAdd: true,
      checked: true,
      disabled: false
    }));
  });

  return items;
}

function normalizeDiagnosisForAutoCalculation(diagnosis) {
  return {
    diagnosis_code: diagnosis.diagnosis_code || diagnosis.disease_code || null,
    diagnosis_name: diagnosis.diagnosis_name || diagnosis.disease_name || diagnosis.full_name || diagnosis.name || '',
    is_main: diagnosis.is_main || diagnosis.diagnosis_category === 'main',
    is_suspected: diagnosis.is_suspected === true,
    start_date: diagnosis.start_date || null,
    end_date: diagnosis.end_date || null,
    outcome: diagnosis.outcome || null
  };
}

async function getDiagnosesForAutoCalculation() {
  const patientId = currentPatient?.id || null;
  const cached = currentPatientDiagnosesPatientId === patientId && Array.isArray(currentPatientDiagnoses)
    ? currentPatientDiagnoses
    : [];
  const localDiagnoses = currentPatient?.diagnoses || currentPatient?.diseases || cached;

  if (!patientId || typeof DiagnosisAPI === 'undefined') {
    return (localDiagnoses || []).map(normalizeDiagnosisForAutoCalculation);
  }

  try {
    const result = await DiagnosisAPI.listByPatient(patientId, {
      activeOnly: true,
      includeEnded: false
    });
    const diagnoses = result.items || result.data || result.diagnoses || [];
    currentPatientDiagnoses = diagnoses;
    currentPatientDiagnosesPatientId = patientId;
    return diagnoses.map(normalizeDiagnosisForAutoCalculation);
  } catch (error) {
    console.warn('傷病名取得エラー:', error);
    return (localDiagnoses || []).map(normalizeDiagnosisForAutoCalculation);
  }
}

function buildPrescriptionCalculationPayload(p) {
  syncPrescriptionDerivedFields(p);
  const comments = getPrescriptionComments(p);
  const enteredComments = getEnteredProcedureComments(comments);
  const hasCommentRows = comments.length > 0;
  const requirements = getPrescriptionRequirementState(p);
  const unitPrice = getPrescriptionUnitPrice(p);
  const totalPrice = calculatePrescriptionDrugTotalPrice(p);
  const refillAllowed = Boolean(p.refill_allowed || p.refillAllowed || p.is_refill || p.isRefill);
  const isTemporary = Boolean(p.is_temporary || p.isTemporary || p.temporary);
  const printGenericName = shouldPrintPrescriptionAsGeneralName(p);
  const genericNameRequested = Boolean(
    p.generic_name_prescription ||
    p.genericNamePrescription ||
    p.general_name_prescription ||
    p.generalNamePrescription ||
    p.print_generic_name ||
    p.printGenericName ||
    prescriptionHasGenericNameComment(p)
  );
  return {
    prescription_type: normalizePrescriptionDispensingType(p),
    dispensing_type: normalizePrescriptionDispensingType(p),
    drug_type: inferPrescriptionDrugType(p),
    code: p.code || p.drug_code || p.yj_code || p.hot_code || p.receipt_code || '',
    drug_code: p.drug_code || p.code || p.yj_code || p.hot_code || '',
    yj_code: p.yj_code || '',
    hot_code: p.hot_code || '',
    receipt_code: p.receipt_code || p.recept_code || '',
    drug_name: p.drug_name || p.name || '',
    name: p.name || p.drug_name || '',
    route: p.route || '',
    days: Number(p.days) || null,
    quantity: Number(p.dosage_quantity || p.quantity || parseFloat(p.dosage)) || null,
    dosage_quantity: Number(p.dosage_quantity || p.quantity || parseFloat(p.dosage)) || null,
    dose_quantity: Number(p.dosage_quantity || p.quantity || parseFloat(p.dosage)) || null,
    body_weight_kg: getCurrentPrescriptionAuditWeightKg(),
    frequency: p.frequency || '',
    unit: p.unit || p.dosage_unit || '',
    dose_unit: p.unit || p.dosage_unit || '',
    unit_price: unitPrice > 0 ? unitPrice : null,
    drug_price: unitPrice > 0 ? unitPrice : null,
    total_price: totalPrice > 0 ? totalPrice : null,
    generic_name: p.generic_name || p.genericName || '',
    generic_prescription_code: p.generic_prescription_code || p.genericPrescriptionCode || '',
    generic_prescription_name: p.generic_prescription_name || p.genericPrescriptionName || '',
    generic_prescription_addition_category: p.generic_prescription_addition_category || p.genericPrescriptionAdditionCategory || '',
    generic_prescription_master_note: p.generic_prescription_master_note || p.genericPrescriptionMasterNote || '',
    generic_prescription_master_version: p.generic_prescription_master_version || p.genericPrescriptionMasterVersion || '',
    generic_name_prescription: genericNameRequested,
    general_name_prescription: genericNameRequested,
    print_generic_name: printGenericName,
    is_generic: Boolean(p.is_generic || p.isGeneric),
    generic_class: p.generic_class || p.genericClass || p.generic_type || p.genericType || '',
    therapeutic_category: p.therapeutic_category || p.therapeuticCategory || p.therapeutic_category_code || '',
    therapeutic_category_code: p.therapeutic_category_code || p.therapeuticCategoryCode || '',
    therapeutic_name: p.therapeutic_name || p.therapeuticName || '',
    efficacy_effect: p.efficacy_effect || p.efficacyEffect || '',
    usage_dosage: p.usage_dosage || p.usageDosage || p.dosage_usage || p.dosageUsage || '',
    side_effects: p.side_effects || p.sideEffects || '',
    application_precautions: p.application_precautions || p.applicationPrecautions || '',
    detail_info: p.detail_info || p.detailInfo || '',
    is_narcotic: Boolean(p.is_narcotic || p.isNarcotic),
    is_psychotropic: Boolean(p.is_psychotropic || p.isPsychotropic),
    refill_allowed: refillAllowed,
    is_refill: refillAllowed,
    refill_count: Number(p.refill_count || p.refillCount || 0) || null,
    note: p.note || '',
    comment: p.comment || '',
    instructions: p.instructions || p.usage || p.note || '',
    comment_codes: hasCommentRows ? getClaimCommentCodes(enteredComments) : (p.comment_codes || []),
    comments: enteredComments,
    free_comment: hasCommentRows ? getClaimFreeCommentText(enteredComments) : (p.free_comment || p.freeComment || ''),
    karte_comment: hasCommentRows ? getKarteCommentText(enteredComments) : (p.karte_comment || p.karteComment || ''),
    requires_comment: requirements.requiresComment,
    comment_required: requirements.requiresComment,
    selectable_comment_required: requirements.requiresComment,
    long_term_listed: requirements.longTermListed,
    long_term_patient_choice: requirements.longTermPatientChoice,
    generic_change_allowed: requirements.genericChangeAllowed,
    generic_change_reason: requirements.genericChangeReason,
    is_temporary: isTemporary,
    temporary: isTemporary
  };
}

function buildPrescriptionAutoCalculationPayloads() {
  return (pendingPrescriptions || []).map(buildPrescriptionCalculationPayload);
}

function buildActionAutoCalculationPayload(action) {
  const comments = getActionComments(action);
  const enteredComments = getEnteredProcedureComments(comments);
  const hasCommentRows = comments.length > 0;
  const score = Number(action.points ?? action.score ?? action.unit_score ?? 0) || 0;
  return {
    code: action.code || action.action_code || action.billing_code || '',
    name: action.name || action.action_name || action.billing_name || '',
    score,
    points: score,
    unit_score: score,
    quantity: Number(action.quantity || 1),
    category: action.category || action.category_name || '',
    category_code: action.category_code || action.categoryCode || '',
    category_name: action.category_name || action.categoryName || action.category || '',
    item_type: action.item_type || action.type || '',
    billing_group_id: action.billing_group_id || action.billingGroupId || '',
    billing_group_parent_id: action.billing_group_parent_id || action.billingGroupParentId || '',
    billing_group_label: action.billing_group_label || action.billingGroupLabel || '',
    receipt_code: action.receipt_code || action.receiptCode || action.recept_code || '',
    billing_code: action.billing_code || action.billingCode || '',
    do_not_bill: isActionDoNotBill(action),
    is_self_pay: Boolean(action.isSelfPay || action.is_self_pay),
    comment_codes: hasCommentRows ? getClaimCommentCodes(enteredComments) : (action.comment_codes || []),
    comments: enteredComments,
    free_comment: hasCommentRows ? getClaimFreeCommentText(enteredComments) : (action.free_comment || ''),
    karte_comment: hasCommentRows ? getKarteCommentText(enteredComments) : (action.karte_comment || action.karteComment || ''),
    requires_comment: Boolean(
      action.requires_comment ||
      action.comment_required ||
      action.selectable_comment_required ||
      action.requiresComment ||
      action.commentRequired
    ),
    comment_required: Boolean(action.comment_required || action.commentRequired),
    selectable_comment_required: Boolean(action.selectable_comment_required || action.selectableCommentRequired)
  };
}

function buildActionAutoCalculationPayloads() {
  return (selectedActions || [])
    .filter(a => !isActionDoNotBill(a) && !a.isSelfPay && a.item_type !== 'self_pay')
    .map(buildActionAutoCalculationPayload);
}

async function buildCurrentAutoCalculationPayload() {
  const birthDate = currentPatient.birth_date || currentPatient.birth;
  const visitDate = getCurrentKarteDateValue();
  const visitDatetime = getVisitDatetimeForCalculation(visitDate);
  const user = Storage.getCurrentUser();
  const facilityId = currentPatient.facility_id || user?.facility_id || null;
  const firstVisitOverride = getFirstVisitOverrideFromReception();
  const diagnoses = await getDiagnosesForAutoCalculation();

  return {
    patient_id: currentPatient.id,
    record_id: currentRecordId,
    reception_id: getCurrentReceptionRecordId(),
    visit_datetime: visitDatetime,
    birth_date: birthDate,
    facility_id: facilityId,
    first_visit: firstVisitOverride,
    visit_fee_enabled: facilityAutoCalcSettings.initialFee,
    time_addition_enabled: facilityAutoCalcSettings.overtime,
    guidance_fee_enabled: facilityAutoCalcSettings.specificDisease
      || facilityAutoCalcSettings.dermatology
      || facilityAutoCalcSettings.epilepsy
      || facilityAutoCalcSettings.intractable,
    specific_disease_enabled: facilityAutoCalcSettings.specificDisease,
    dermatology_enabled: facilityAutoCalcSettings.dermatology,
    epilepsy_enabled: facilityAutoCalcSettings.epilepsy,
    intractable_enabled: facilityAutoCalcSettings.intractable,
    actions: buildActionAutoCalculationPayloads(),
    prescriptions: buildPrescriptionAutoCalculationPayloads(),
    diagnoses
  };
}

async function calculateCurrentAutoCalculationResult() {
  if (typeof AutoCalculationAPI === 'undefined' || !AutoCalculationAPI.calculate) {
    throw new Error('自動算定APIが利用できません');
  }
  return await AutoCalculationAPI.calculate(await buildCurrentAutoCalculationPayload());
}

async function ensureFacilityAutoCalcLoadedForCurrentContext() {
  const facilityId = getCurrentFacilityIdForAutoCalc();
  if (!facilityId || typeof AutoCalculationAPI === 'undefined') return false;
  if (facilityAutoCalcActionsFacilityId === String(facilityId)) return true;

  try {
    return await loadFacilityAutoCalcFromApi();
  } catch (error) {
    console.warn('会計前の自動算定設定読み込みエラー:', error);
    return false;
  }
}

async function ensureAutoCalculatedForBilling() {
  if (!currentPatient) return 0;

  const completedDisplayData = getCompletedBillingDisplayData();
  const hasCompletedBillingDisplay = completedDisplayData?.status === 'payment_done'
    || completedDisplayData?.billing?.paymentStatus === 'payment_done'
    || Boolean(completedDisplayData?.payment);
  const currentOrderItems = buildBillingItemsFromCurrentOrders();
  if (hasCompletedBillingDisplay && hasBillingDisplayItems(completedDisplayData) && currentOrderItems.length === 0) {
    return 0;
  }

  const autoCalcReady = await ensureFacilityAutoCalcLoadedForCurrentContext();
  if (!autoCalcReady) {
    throw new Error('自動算定設定を取得できません');
  }

  let result;
  try {
    result = await calculateCurrentAutoCalculationResult();
  } catch (error) {
    console.error('会計前自動算定APIエラー:', error);
    showToast(`会計前自動算定に失敗しました: ${error?.message || '不明なエラー'}`, 'error');
    throw error;
  }

  const items = buildAutoCalcSuggestedItems(result)
    .filter(item => item.autoAdd !== false && !item.disabled);
  let addedCount = 0;

  items.forEach(item => {
    const added = addActionToSelectedActions({
      code: item.code,
      name: item.name,
      points: item.points,
      category: getAutoCalcActionCategory(item),
      quantity: 1,
      reason: item.reason,
      source: 'auto_calculation'
    }, { showToast: false, showDuplicateToast: false, assignToSelectedGroup: false });

    if (added) addedCount += 1;
  });

  if (addedCount > 0) {
    renderSelectedActionsInProcedure();
    updateSelectedList();
    updateTotalPoints();
    saveCurrentPatientBilling();
    checkActionsRealtime();
  }

  return addedCount;
}

// 自動算定機能（モーダル対応版）
async function autoCalculate() {
  if (!currentPatient) {
    showToast('患者を選択してください', 'error');
    return;
  }

  // モーダルを開いてローディング表示
  showAutoCalcModal();
  showAutoCalcLoading();

  try {
    // 患者情報からパラメータを準備
    const birthDate = currentPatient.birth_date || currentPatient.birth;
    const visitDate = getCurrentKarteDateValue();
    const visitDatetime = getVisitDatetimeForCalculation(visitDate);
    const user = Storage.getCurrentUser();
    const facilityId = currentPatient.facility_id || user?.facility_id || null;
    const firstVisitOverride = getFirstVisitOverrideFromReception();

    // 現在の患者の有効傷病名を取得
    const diagnoses = await getDiagnosesForAutoCalculation();

    // 現在の処方を取得
    const prescriptions = buildPrescriptionAutoCalculationPayloads();

    // 現在入力済みの診療行為を取得
    const actions = (selectedActions || [])
      .filter(a => !a.isSelfPay && a.item_type !== 'self_pay')
      .map(buildActionAutoCalculationPayload);

    if (typeof AutoCalculationAPI === 'undefined' || !AutoCalculationAPI.calculate) {
      throw new Error('自動算定APIが利用できません');
    }

    const result = await AutoCalculationAPI.calculate({
      patient_id: currentPatient.id,
      record_id: currentRecordId,
      visit_datetime: visitDatetime,
      birth_date: birthDate,
      facility_id: facilityId,
      first_visit: firstVisitOverride,
      visit_fee_enabled: facilityAutoCalcSettings.initialFee,
      time_addition_enabled: facilityAutoCalcSettings.overtime,
      guidance_fee_enabled: facilityAutoCalcSettings.specificDisease
        || facilityAutoCalcSettings.dermatology
        || facilityAutoCalcSettings.epilepsy
        || facilityAutoCalcSettings.intractable,
      specific_disease_enabled: facilityAutoCalcSettings.specificDisease,
      dermatology_enabled: facilityAutoCalcSettings.dermatology,
      epilepsy_enabled: facilityAutoCalcSettings.epilepsy,
      intractable_enabled: facilityAutoCalcSettings.intractable,
      actions: actions,
      prescriptions: prescriptions,
      diagnoses: diagnoses
    });

    // 結果を保存
    autoCalcResult = result;
    autoCalcSuggestedItems = buildAutoCalcSuggestedItems(result);

    // モーダルに結果を表示
    renderAutoCalcModal(result, autoCalcSuggestedItems);

  } catch (error) {
    console.error('自動算定エラー:', error);
    autoCalcResult = null;
    autoCalcSuggestedItems = [];
    showAutoCalcError(error?.message || '自動算定に失敗しました');
    showToast(`自動算定に失敗しました: ${error?.message || '不明なエラー'}`, 'error');
  }
}

// 自動算定モーダルを表示
function showAutoCalcModal() {
  const modal = document.getElementById('auto-calc-modal');
  if (modal) {
    modal.classList.remove('hidden');
  }
}

// 自動算定モーダルを非表示
function hideAutoCalcModal() {
  const modal = document.getElementById('auto-calc-modal');
  if (modal) {
    modal.classList.add('hidden');
  }
  autoCalcResult = null;
  autoCalcSuggestedItems = [];
}

// ローディング表示
function showAutoCalcLoading() {
  const body = document.getElementById('auto-calc-body');
  if (body) {
    body.innerHTML = `
      <div class="auto-calc-loading">
        <div class="spinner"></div>
        <p>自動算定を実行中...</p>
      </div>
    `;
  }
  // バッジとサマリーをクリア
  const badges = document.getElementById('auto-calc-badges');
  if (badges) badges.innerHTML = '';
  const total = document.getElementById('auto-calc-total');
  if (total) total.innerHTML = '選択中: <strong>0</strong>件 / 合計 <strong>0</strong>点';
  const addButton = document.getElementById('btn-auto-calc-add');
  if (addButton) addButton.disabled = true;
}

function showAutoCalcError(message) {
  const body = document.getElementById('auto-calc-body');
  const badges = document.getElementById('auto-calc-badges');
  const total = document.getElementById('auto-calc-total');
  const addButton = document.getElementById('btn-auto-calc-add');

  if (badges) badges.innerHTML = '';
  if (total) total.innerHTML = '選択中: <strong>0</strong>件 / 合計 <strong>0</strong>点';
  if (addButton) addButton.disabled = true;
  if (body) {
    body.innerHTML = `
      <div class="auto-calc-empty auto-calc-error">
        <i class="fas fa-exclamation-triangle"></i>
        <p>${escapeHtml(message)}</p>
      </div>
    `;
  }
}

function buildAutoCalcMessages(result) {
  // 自動算定の判定メッセージは内部確認用。確認モーダルでは候補だけ表示する。
  return '';
}

// モーダルに結果を表示
function renderAutoCalcModal(result, items) {
  const badges = document.getElementById('auto-calc-badges');
  const body = document.getElementById('auto-calc-body');
  const addButton = document.getElementById('btn-auto-calc-add');
  const messagesHtml = buildAutoCalcMessages(result);

  // バッジを表示
  if (badges) {
    const visitBadge = result.visit_type === 'initial'
      ? '<span class="auto-calc-badge visit-initial">初診</span>'
      : '<span class="auto-calc-badge visit-revisit">再診</span>';

    const timeMap = {
      normal: { cls: 'time-normal', text: '通常' },
      overtime: { cls: 'time-overtime', text: '時間外' },
      holiday: { cls: 'time-holiday', text: '休日' },
      night: { cls: 'time-night', text: '深夜' }
    };
    const timeInfo = timeMap[result.time_category] || timeMap.normal;
    const timeBadge = `<span class="auto-calc-badge ${timeInfo.cls}">${timeInfo.text}</span>`;

    const infantBadge = result.is_infant
      ? '<span class="auto-calc-badge infant">乳幼児</span>'
      : '';

    badges.innerHTML = visitBadge + timeBadge + infantBadge;
  }

  // 項目を表示
  if (body) {
    if (items.length === 0) {
      body.innerHTML = `
        <p class="auto-calc-confirm-message">下記の項目を追加出来ます。追加する項目をチェックしてください。</p>
        ${messagesHtml}
        <div class="auto-calc-empty">
          <i class="fas fa-check-circle"></i>
          <p>追加できる算定項目はありません</p>
        </div>
      `;
      if (addButton) addButton.disabled = true;
      updateAutoCalcSummary();
      return;
    }

    const enabledItems = items.filter(item => !item.disabled);
    const allEnabledChecked = enabledItems.length > 0 && enabledItems.every(item => item.checked);

    const rows = items.map((item, index) => {
      const checkedAttr = item.checked ? 'checked' : '';
      const disabledAttr = item.disabled ? 'disabled' : '';
      const disabledClass = item.disabled ? 'disabled' : '';
      const checkedClass = item.checked ? 'checked' : '';
      const suggestedClass = !item.autoAdd ? 'suggested' : '';
      const iconText = getAutoCalcItemIcon(item);
      const pointsText = Number(item.points || 0) > 0 ? `${Number(item.points)}点` : '';
      const reasonParts = [item.reason || '', item.disabled ? '追加済み' : ''].filter(Boolean);
      const reasonText = reasonParts.join(' / ');

      return `
        <label class="auto-calc-item ${checkedClass} ${suggestedClass} ${disabledClass}" data-index="${index}">
          <input type="checkbox" ${checkedAttr} ${disabledAttr}
                 onchange="onAutoCalcItemChange(${index}, this.checked)">
          <span class="auto-calc-item-icon">${escapeHtml(iconText)}</span>
          <span class="auto-calc-item-content">
            <span class="auto-calc-item-name">${escapeHalfWidthNumericText(item.name)}</span>
            ${reasonText ? `<span class="auto-calc-item-reason">${escapeHalfWidthNumericText(reasonText)}</span>` : ''}
          </span>
          ${pointsText ? `<span class="auto-calc-item-score">${escapeHtml(pointsText)}</span>` : ''}
        </label>
      `;
    }).join('');

    body.innerHTML = `
      <p class="auto-calc-confirm-message">下記の項目を追加出来ます。追加する項目をチェックしてください。</p>
      ${messagesHtml}
      <div class="auto-calc-confirm-list">
        <label class="auto-calc-select-all-row">
          <input type="checkbox" id="auto-calc-select-all"
                 ${allEnabledChecked ? 'checked' : ''}
                 ${enabledItems.length === 0 ? 'disabled' : ''}
                 onchange="onAutoCalcSelectAllChange(this.checked)">
          <span>全てチェックする</span>
        </label>
        ${rows}
      </div>
    `;
  }

  updateAutoCalcSummary();
}

// 項目のチェック状態変更
function onAutoCalcItemChange(index, checked) {
  if (autoCalcSuggestedItems[index]) {
    autoCalcSuggestedItems[index].checked = checked;

    // UIを更新
    const label = document.querySelector(`.auto-calc-item[data-index="${index}"]`);
    if (label) {
      if (checked) {
        label.classList.add('checked');
      } else {
        label.classList.remove('checked');
      }
    }

    updateAutoCalcSummary();
  }
}

function onAutoCalcSelectAllChange(checked) {
  autoCalcSuggestedItems.forEach((item, index) => {
    if (item.disabled) return;
    item.checked = checked;

    const label = document.querySelector(`.auto-calc-item[data-index="${index}"]`);
    const checkbox = label?.querySelector('input[type="checkbox"]');
    if (checkbox) checkbox.checked = checked;
    if (label) label.classList.toggle('checked', checked);
  });

  updateAutoCalcSummary();
}

// サマリー更新
function updateAutoCalcSummary() {
  const total = document.getElementById('auto-calc-total');
  const checkedItems = autoCalcSuggestedItems.filter(i => i.checked && !i.disabled);
  const enabledItems = autoCalcSuggestedItems.filter(i => !i.disabled);

  if (total && autoCalcSuggestedItems) {
    const count = checkedItems.length;
    const points = checkedItems.reduce((sum, i) => sum + (Number(i.points) || 0), 0);
    total.innerHTML = `選択中: <strong>${count}</strong>件 / 合計 <strong>${points}</strong>点`;
  }

  const selectAll = document.getElementById('auto-calc-select-all');
  if (selectAll) {
    const checkedCount = checkedItems.length;
    selectAll.checked = enabledItems.length > 0 && checkedCount === enabledItems.length;
    selectAll.indeterminate = checkedCount > 0 && checkedCount < enabledItems.length;
    selectAll.disabled = enabledItems.length === 0;
  }

  const addButton = document.getElementById('btn-auto-calc-add');
  if (addButton) addButton.disabled = checkedItems.length === 0;
}

// 選択した項目を追加
function addAutoCalcItems() {
  const checkedItems = autoCalcSuggestedItems.filter(i => i.checked && !i.disabled);
  if (checkedItems.length === 0) {
    showToast('追加する算定項目を選択してください', 'info');
    return;
  }

  const result = autoCalcResult;
  const addButton = document.getElementById('btn-auto-calc-add');
  let addedCount = 0;

  if (addButton) addButton.disabled = true;

  try {
    checkedItems.forEach(item => {
      const added = addActionToSelectedActions({
        code: item.code,
        name: item.name,
        points: item.points,
        category: getAutoCalcActionCategory(item),
        quantity: 1,
        reason: item.reason,
        source: 'auto_calculation'
      }, { showToast: false, showDuplicateToast: false, assignToSelectedGroup: false });
      if (added) {
        addedCount++;
      }
    });

    // 表示を更新
    renderSelectedActionsInProcedure();
    updateTotalPoints();
    updateSelectedList();
    saveCurrentPatientBilling();

    void result;
    void addedCount;
  } catch (error) {
    console.error('自動算定項目追加エラー:', error);
    showToast('自動算定項目の追加に失敗しました', 'error');
  } finally {
    hideAutoCalcModal();
  }
}

// 自動算定モーダルのイベントリスナー設定
function initAutoCalcModal() {
  // 閉じるボタン
  document.getElementById('auto-calc-close')?.addEventListener('click', hideAutoCalcModal);
  document.getElementById('btn-auto-calc-cancel')?.addEventListener('click', hideAutoCalcModal);
  document.getElementById('auto-calc-help')?.addEventListener('click', () => {
    window.open('https://digikar.zendesk.com/hc/ja/articles/49950464239385', '_blank', 'noopener');
  });

  // 追加ボタン
  document.getElementById('btn-auto-calc-add')?.addEventListener('click', addAutoCalcItems);

  // モーダル外クリックで閉じる
  document.getElementById('auto-calc-modal')?.addEventListener('click', (e) => {
    if (e.target.id === 'auto-calc-modal') {
      hideAutoCalcModal();
    }
  });
}

// 互換性のため旧関数名は維持するが、APIを通さない自動算定は行わない。
async function autoCalculateLocalResult() {
  throw new Error('自動算定APIが利用できません');
}

async function autoCalculateLocalWithAdd() {
  return await autoCalculateLocalResult();
}

async function autoCalculateLocal() {
  return await autoCalculateLocalResult();
}

