function getPrintableBillingTotalPoints(items = getPrintableBillingItems()) {
  if (currentBilling && hasBillingDisplayItems({ billing: currentBilling })) {
    return Number(currentBilling.totalPoints || 0);
  }
  return items.filter(item => !item.isSelfPay).reduce((sum, item) => sum + Number(item.subtotal || 0), 0);
}

function getPrintableBillingPatientAmount() {
  return Number(currentBilling?.patientAmount || 0);
}

function formatPrintableNumber(value, blankZero = true) {
  const number = Number(value || 0);
  if (blankZero && number === 0) return '';
  return Number.isFinite(number) ? number.toLocaleString() : '';
}

function formatPrintableMultiline(value) {
  const text = String(value || '').trim();
  if (!text) return '';
  return escapeHtml(text).replace(/\r?\n/g, '<br>');
}

function buildPrintableBaseHtml({ title, pageSize = 'A4', bodyClass = '', body }) {
  const safeTitle = escapeHtml(title);
  return `
<!DOCTYPE html>
<html lang="ja">
<head>
  <meta charset="UTF-8">
  <title>${safeTitle}</title>
  <style>
    @page { size: ${pageSize}; margin: ${pageSize === 'A5' ? '8mm' : '10mm'}; }
    * { box-sizing: border-box; }
    body {
      margin: 0;
      color: #111827;
      background: #fff;
      font-family: "Yu Gothic", "Meiryo", sans-serif;
      font-size: ${pageSize === 'A5' ? '10px' : '10.5px'};
      line-height: 1.45;
    }
    .print-page { width: 100%; min-height: 100%; }
    .print-header { display: flex; justify-content: space-between; gap: 16px; margin-bottom: 7mm; }
    .print-header-line { font-size: 10px; color: #374151; }
    .print-title { margin: 0 0 5mm; text-align: center; font-size: ${pageSize === 'A5' ? '20px' : '22px'}; font-weight: 700; letter-spacing: 0; }
    .print-subtitle { margin: -3mm 0 4mm; text-align: center; font-size: 10px; color: #374151; }
    .print-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 4mm; }
    .print-section { margin-bottom: 4mm; }
    .print-section-title { margin: 0 0 2mm; font-weight: 700; font-size: 11px; }
    table { width: 100%; border-collapse: collapse; }
    th, td { border: 1px solid #bfc8c4; padding: 2.2mm 2.4mm; vertical-align: top; }
    th { background: #f4f7f5; font-weight: 700; text-align: left; white-space: nowrap; }
    .compact th, .compact td { padding: 1.5mm 1.8mm; }
    .right { text-align: right; }
    .center { text-align: center; }
    .muted { color: #6b7280; }
    .box { min-height: 28mm; border: 1px solid #bfc8c4; padding: 3mm; }
    .large-box { min-height: 80mm; border: 1px solid #bfc8c4; padding: 3mm; }
    .signature-box { height: 18mm; border: 1px solid #bfc8c4; }
    .no-border { border: 0; }
    .nowrap { white-space: nowrap; }
    .label-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 4mm; }
    .procedure-label { min-height: 28mm; border: 1px solid #111827; padding: 3mm; page-break-inside: avoid; }
    .procedure-label-title { font-size: 12px; font-weight: 700; margin-bottom: 2mm; }
    .claim-stamp { display: inline-block; padding: 1mm 3mm; border: 1px solid #111827; font-weight: 700; }
    @media print { body { -webkit-print-color-adjust: exact; print-color-adjust: exact; } }
  </style>
</head>
<body class="${escapeHtml(bodyClass)}">
${body}
</body>
</html>`;
}

