function getPaperReceiptEraParts(value = getPrintableVisitDate()) {
  const normalized = normalizeKarteDateValue(value) || getLocalDateString();
  const date = parseLocalDate(normalized);
  if (!(date instanceof Date) || Number.isNaN(date.getTime())) {
    return { eraName: '令和', eraAbbr: '令', eraCode: '5', eraYear: '', month: '', day: '' };
  }

  const eras = [
    { name: '令和', abbr: '令', code: '5', start: '2019-05-01', baseYear: 2018 },
    { name: '平成', abbr: '平', code: '4', start: '1989-01-08', baseYear: 1988 },
    { name: '昭和', abbr: '昭', code: '3', start: '1926-12-25', baseYear: 1925 },
    { name: '大正', abbr: '大', code: '2', start: '1912-07-30', baseYear: 1911 },
    { name: '明治', abbr: '明', code: '1', start: '1868-01-25', baseYear: 1867 }
  ];
  const era = eras.find(item => date >= parseLocalDate(item.start)) || eras[0];
  return {
    eraName: era.name,
    eraAbbr: era.abbr,
    eraCode: era.code,
    eraYear: date.getFullYear() - era.baseYear,
    month: date.getMonth() + 1,
    day: date.getDate()
  };
}

function formatPaperReceiptDate(value) {
  const parts = getPaperReceiptEraParts(value);
  if (!parts.eraYear) return '';
  return `${parts.eraAbbr}${String(parts.eraYear).padStart(2, '0')}.${parts.month}.${parts.day}`;
}

function formatPaperReceiptFullDate(value) {
  const parts = getPaperReceiptEraParts(value);
  if (!parts.eraYear) return '';
  return `${parts.eraAbbr} ${String(parts.eraYear).padStart(2, '0')}年${parts.month}月${parts.day}日`;
}

function formatPaperReceiptBirthDate(value) {
  const parts = getPaperReceiptEraParts(value);
  if (!parts.eraYear) return '';
  return `${parts.eraCode} ${parts.eraAbbr}　${String(parts.eraYear).padStart(2, '0')}.　${parts.month}.　${parts.day}　生`;
}

function formatPaperReceiptClaimMonth(value = getPrintableVisitDate()) {
  const parts = getPaperReceiptEraParts(value);
  if (!parts.eraYear) return '令和　年　月分';
  return `${parts.eraName} ${String(parts.eraYear).padStart(2, '0')} 年 ${parts.month} 月分`;
}

function buildPaperReceiptDigitBoxes(value, count, className = '') {
  const digits = normalizeDigits(String(value || '')).slice(0, count).split('');
  return `
    <div class="paper-receipt-digits ${className}" style="grid-template-columns: repeat(${count}, 1fr);">
      ${Array.from({ length: count }, (_, index) => `<span>${escapeHtml(digits[index] || '')}</span>`).join('')}
    </div>
  `;
}

function getPaperReceiptPublicExpense(index) {
  const ids = [
    currentReception?.public_expense_1_id,
    currentReception?.public_expense_2_id,
    currentReception?.public_expense_3_id
  ];
  const selected = ids[index]
    ? currentPatientPublicExpenses.find(item => String(item.id) === String(ids[index]))
    : null;
  return selected || currentPatientPublicExpenses[index] || {};
}

function getPaperReceiptPayerGroup(insurance = getPrintableInsurance()) {
  const type = firstNonEmptyString(insurance?.insurance_type, currentReception?.insurance_type, currentBilling?.payerGroup);
  if (type === 'elderly' || type === 'late_elderly') return '3 後期';
  if (type === 'national' || type === 'kokuho') return '2 国保';
  if (type === 'self_pay') return '自費';
  return '1 社';
}

function getPaperReceiptPatientGenderShort() {
  const gender = getPrintablePatientGender();
  if (gender.includes('女性')) return '女';
  if (gender.includes('男性')) return '男';
  return gender || '';
}

function getPaperReceiptPatientGenderNumbered() {
  const gender = getPrintablePatientGender();
  if (gender.includes('女性')) return '2 女';
  if (gender.includes('男性')) return '1 男';
  return gender || '';
}

function getPaperReceiptVisitKindLabel() {
  return getFirstVisitOverrideFromReception() === false ? '再診' : '初診';
}

function getPaperReceiptItemPoints(item) {
  if (!item || item.isSelfPay) return 0;
  const subtotal = Number(item.subtotal ?? item.total_points);
  if (Number.isFinite(subtotal) && subtotal > 0) return subtotal;
  const points = Number(item.points || item.score || 0);
  const quantity = Number(item.quantity || 1);
  return Number.isFinite(points) ? points * (Number.isFinite(quantity) ? quantity : 1) : 0;
}

function getPaperReceiptScoreKey(item) {
  const category = getReceiptPointCategory(item) || 'その他';
  const itemCategory = String(item?.category || '');
  const itemName = String(item?.name || '');
  if (itemCategory === 'その他') return 'other';
  if (category === '初・再診料') {
    return /再診|外来診療料/.test(itemName) ? 'revisit' : 'initial';
  }
  if (category === '医学管理料') return 'management';
  if (category === '在宅医療') return 'home';
  if (category === '投薬') return 'medication';
  if (category === '注射') return 'injection';
  if (category === '処置') return 'procedure';
  if (category === '手術' || category === '麻酔') return 'surgery';
  if (category === '検査' || category === '病理診断') return 'exam';
  if (category === '画像診断') return 'image';
  return 'other';
}

function getPaperReceiptScoreLineKey(item) {
  const key = getPaperReceiptScoreKey(item);
  const text = `${item?.code || ''} ${item?.category || ''} ${item?.name || ''}`;

  if (key === 'initial') {
    if (/時間外|休日|深夜/.test(text)) return 'initialSpecial';
    return 'initial';
  }
  if (key === 'revisit') {
    if (/外来管理加算/.test(text)) return 'outpatientManagement';
    if (/時間外/.test(text)) return 'revisitTime';
    if (/休日/.test(text)) return 'revisitHoliday';
    if (/深夜/.test(text)) return 'revisitNight';
    return 'revisit';
  }
  if (key === 'management') return 'management';
  if (key === 'home') {
    if (/往診/.test(text)) return 'homeVisit';
    if (/夜間/.test(text)) return 'homeNight';
    if (/深夜|緊急/.test(text)) return 'homeUrgent';
    if (/訪問診療/.test(text)) return 'homePatientVisit';
    if (/薬剤|薬/.test(text)) return 'homeDrug';
    return 'homeOther';
  }
  if (key === 'medication') {
    if (/調剤基本|調基/.test(text)) return 'dispensingBase';
    if (/麻薬|毒薬/.test(text)) return 'narcoticPoison';
    if (/処方せん/.test(text)) return 'otherPrescription';
    if (/処方/.test(text)) return 'prescriptionFee';
    if (/頓服/.test(text)) return 'temporaryDrug';
    if (/外用調剤/.test(text)) return 'externalDispense';
    if (/内服調剤|調剤料/.test(text)) return 'oralDispense';
    if (/外用|点眼|点鼻|軟膏|貼付|クリーム|ローション|ゲル|吸入|スプレー|坐剤/.test(text)) {
      return 'externalDrug';
    }
    return 'oralDrug';
  }
  if (key === 'injection') {
    if (/皮下|筋肉|筋注/.test(text)) return 'injectionSubcutaneous';
    if (/静脈|静注|点滴/.test(text)) return 'injectionIntravenous';
    return 'injectionOther';
  }
  if (key === 'procedure') return /薬剤|薬/.test(text) ? 'procedureDrug' : 'procedure';
  if (key === 'surgery') return /薬剤|薬/.test(text) ? 'surgeryDrug' : 'surgery';
  if (key === 'exam') return /薬剤|薬/.test(text) ? 'examDrug' : 'exam';
  if (key === 'image') return /薬剤|薬/.test(text) ? 'imageDrug' : 'image';
  if (/処方せん/.test(text)) return 'otherPrescription';
  return 'other';
}

function getPaperReceiptScoreCount(item, lineKey) {
  const name = String(item?.name || '');
  const quantity = Number(item?.quantity || 1) || 1;
  if (lineKey === 'initial') return /初診|初診料/.test(name) && !/加算/.test(name) ? quantity : 0;
  if (lineKey === 'revisit') return /再診|外来診療料/.test(name) && !/加算/.test(name) ? quantity : 0;
  return quantity;
}

function getPaperReceiptScoreSummary(items = getPrintableBillingItems()) {
  const summary = Object.fromEntries(
    Array.from(PAPER_RECEIPT_SCORE_LINE_LOOKUP.keys()).map(key => [key, { points: 0, count: 0 }])
  );
  items.forEach(item => {
    if (item?.isSelfPay) return;
    const key = getPaperReceiptScoreLineKey(item);
    if (!summary[key]) summary[key] = { points: 0, count: 0 };
    summary[key].points += getPaperReceiptItemPoints(item);
    summary[key].count += getPaperReceiptScoreCount(item, key);
  });
  return summary;
}

function buildPaperReceiptScoreRowsHtml(items = getPrintableBillingItems()) {
  const summary = getPaperReceiptScoreSummary(items);
  const body = PAPER_RECEIPT_SCORE_SECTIONS.map(section => {
    const rowCount = section.rows.length;
    const sectionHeight = Math.max(rowCount * 4.4, 5.6).toFixed(1);
    const rowTemplate = `repeat(${rowCount}, 1fr)`;
    const labels = section.rows.map(row => `<div class="paper-score-line-label">${escapeHtml(row.label)}</div>`).join('');
    const counts = section.rows.map(row => {
      const value = summary[row.key] || { points: 0, count: 0 };
      const countText = value.count && row.unit
        ? `${formatPrintableNumber(value.count, false)} ${row.unit}`
        : (row.unit === '回' ? `× ${row.unit}` : (row.unit || ''));
      return `<div class="paper-score-line-count">${escapeHtml(countText)}</div>`;
    }).join('');
    const points = section.rows.map(row => {
      const value = summary[row.key] || { points: 0, count: 0 };
      return `<div class="paper-score-line-points">${formatPrintableNumber(value.points)}</div>`;
    }).join('');
    const publicPoints = section.rows.map(() => '<div class="paper-score-line-public"></div>').join('');
    return `
      <div class="paper-score-section" style="min-height: ${sectionHeight}mm;">
        <div class="paper-score-section-code">${escapeHtml(section.code)}</div>
        <div class="paper-score-section-group">${section.groupLabel ? `<span>${escapeHtml(section.groupLabel)}</span>` : ''}</div>
        <div class="paper-score-lines" style="grid-template-rows: ${rowTemplate};">${labels}</div>
        <div class="paper-score-counts" style="grid-template-rows: ${rowTemplate};">${counts}</div>
        <div class="paper-score-points-column" style="grid-template-rows: ${rowTemplate};">${points}</div>
        <div class="paper-score-public-column" style="grid-template-rows: ${rowTemplate};">${publicPoints}</div>
      </div>
    `;
  }).join('');

  return `
    <div class="paper-score-body">${body}</div>
  `;
}

function getPaperReceiptCategoryCode(item) {
  const key = getPaperReceiptScoreLineKey(item);
  const row = PAPER_RECEIPT_SCORE_LINE_LOOKUP.get(key);
  return row?.detailCode || row?.sectionCode || '80';
}

function buildPaperReceiptDetailLinesHtml(items = getPrintableBillingItems()) {
  const rows = items.filter(item => item && !item.isSelfPay);
  if (!rows.length) return '<div class="paper-detail-empty">診療明細はありません。</div>';

  return rows.map(item => {
    const points = Number(item.points || item.score || 0);
    const quantity = Number(item.quantity || 1) || 1;
    const subtotal = getPaperReceiptItemPoints(item);
    const comments = [
      item.free_comment,
      ...(Array.isArray(item.comments)
        ? item.comments.map(comment => firstNonEmptyString(comment?.freeText, comment?.text, comment?.name, comment?.label))
        : []),
      ...(Array.isArray(item.comment_names)
        ? item.comment_names.map(comment => firstNonEmptyString(comment?.text, comment?.name, comment?.label))
        : [])
    ].filter(Boolean);
    const commentLines = Array.from(new Set(comments));

    return `
      <div class="paper-detail-line">
        <div class="paper-detail-code">${escapeHtml(getPaperReceiptCategoryCode(item))}</div>
        <div class="paper-detail-name">${escapeHtml(item.name || '')}</div>
        <div class="paper-detail-calc">${points ? `${formatPrintableNumber(points, false)} x ${formatPrintableNumber(quantity, false)}` : formatPrintableNumber(subtotal)}</div>
      </div>
      ${commentLines.map(line => `<div class="paper-detail-comment">${formatPrintableMultiline(line)}</div>`).join('')}
    `;
  }).join('<div class="paper-detail-separator"></div>');
}

function buildPaperReceiptDiagnosisRowsHtml(options = {}) {
  const includeDate = options.includeDate !== false;
  const diagnoses = getPrintableDiagnoses()
    .filter(diagnosis => !diagnosis.end_date && getPrintableDiagnosisName(diagnosis))
    .slice(0, 3);
  return Array.from({ length: 3 }, (_, index) => {
    const diagnosis = diagnoses[index] || {};
    return `
      <div class="paper-diagnosis-row">
        <div>(${index + 1})</div>
        <div>${escapeHtml(getPrintableDiagnosisName(diagnosis))}</div>
        <div>${includeDate ? escapeHtml(formatPaperReceiptDate(diagnosis.start_date || diagnosis.diagnosis_start_date || '')) : ''}</div>
      </div>
    `;
  }).join('');
}

function buildPaperReceiptFlag(label, active = false, className = 'paper-flag') {
  return `<span class="${escapeHtml(className)}${active ? ' active' : ''}">${escapeHtml(label)}</span>`;
}

