    kana: toKatakana(firstNonEmptyString(patient?.name_kana, patient?.kana, currentReception?.name_kana, currentReception?.patient_name_kana)),
    name: firstNonEmptyString(patient?.name, currentReception?.patient_name),
    birthDate: birthDate ? formatPrescriptionPrintDate(birthDate, { suffix: '生' }) : '',
