function collectPrescriptionPrintModelErrors(model) {
  const errors = [];
  const requiredValues = [
    ['患者番号', model.patient?.number],
    ['患者氏名', model.patient?.name],
    ['患者生年月日', model.patient?.birthDate],
    ['患者性別', model.patient?.gender],
    ['交付年月日', model.issueDate],
    ['医療機関所在地', model.facility?.address],
    ['医療機関名', model.facility?.name],
    ['医療機関電話番号', model.facility?.phone],
    ['保険医師名', model.facility?.doctorName],
    ['都道府県番号', model.facility?.prefectureNumber],
    ['医療機関コード', model.facility?.code]
  ];

  requiredValues.forEach(([label, value]) => {
    if (!String(value || '').trim()) errors.push(`${label}が取得できません`);
  });

  const publicPayerDigits = normalizeDigits(model.publicExpense?.payerNumber || model.publicPayerNumber || '');
  const publicRecipientDigits = normalizeDigits(model.publicExpense?.recipientNumber || model.publicRecipientNumber || '');
  if (!isValidPublicExpensePayerNumberLength(publicPayerDigits)) {
    errors.push('公費負担者番号は2桁または8桁で登録してください');
  }
  if (publicRecipientDigits && publicRecipientDigits.length !== 7) {
    errors.push('公費受給者番号は7桁で登録してください');
  }

  const groups = Array.isArray(model.prescriptionGroups) ? model.prescriptionGroups : [];
  const prescriptions = groups.flatMap(group => Array.isArray(group.prescriptions) ? group.prescriptions : []);
  prescriptions.forEach(({ prescription }, index) => {
    const lineNumber = index + 1;
    if (!String(prescription?.drug_name || prescription?.name || '').trim()) {
      errors.push(`処方${lineNumber}行目の薬剤名が取得できません`);
    }
    if (!formatPrescriptionDoseForList(prescription || {})) {
      errors.push(`処方${lineNumber}行目の用量が取得できません`);
    }
    if (!formatPrescriptionPrintUsage(prescription || {})) {
      errors.push(`処方${lineNumber}行目の用法が取得できません`);
    }
    if (!prescription?.days) {
      errors.push(`処方${lineNumber}行目の日数/回数が取得できません`);
    }
  });

  const remarkLines = normalizePrescriptionRemarksText(model.remarksComments)
    .split('\n')
    .filter(Boolean);
  if (remarkLines.length > PRESCRIPTION_PRINT_REMARK_MAX_LINES) {
    errors.push(`処方箋備考欄は${PRESCRIPTION_PRINT_REMARK_MAX_LINES}行までです`);
  }

  return errors;
}

