    patientNumber: patient.number,
    publicPayerNumber: publicExpense.payerNumber,
    publicRecipientNumber: publicExpense.recipientNumber,
    insurerNumber: insuranceData.insurerNumber,
    insuranceSymbolNumber: insuranceData.symbolNumber,
    insuranceBranchNumber: insuranceData.branchNumber,
    patientKana: patient.kana,
    patientName: patient.name,
    patientBirthDate: patient.birthDate,
    patientGender: patient.gender,
    patientClass: patient.class,
    facilityAddress: facility.address,
    facilityName: facility.name,
    facilityPhone: facility.phone,
    doctorName: facility.doctorName,
    prefectureNumber: facility.prefectureNumber,
    pointTableNumber: facility.pointTableNumber,
    facilityCode: facility.code,
    remarksAge: patient.remarksAgeMarker,
    remarksComments: getEffectivePrescriptionRemarksValue(),
