// ====================================
// フィルター機能
// ====================================
const receptionFilterStatusOptions = [
  'reserved',
  'waiting',
  'exam_waiting',
  'in_exam',
  'testing',
  'treatment',
  'payment_waiting',
  'payment_done',
  'recalc_waiting',
  'absent'
].map(key => ({
  key,
  label: statusMap[key].label,
  color: statusMap[key].color
}));

const receptionFilterDoctorDefaults = [
  '島原　立樹',
  '蟹江　晃司',
  '福井　康大',
  '石田　隆之',
  '朝岡　龍博',
  '吉川　達郎',
  '磯貝　徹也'
];

const receptionFilterDepartmentDefaults = [
  '内科',
  '在宅',
  '夜間休日外来',
  '発熱外来'
];

const receptionFilterColumnOptions = [
  { key: 'num', label: '番号', classes: ['col-num'], defaultVisible: true },
  { key: 'appointment', label: '予約時間', classes: ['col-appointment'], defaultVisible: true },
  { key: 'time', label: '受付時間', classes: ['col-time'], defaultVisible: true },
  { key: 'status', label: 'ステータス', classes: ['col-status'], defaultVisible: true },
  { key: 'patient_id', label: '患者番号', classes: ['col-patient-id'], defaultVisible: true },
  { key: 'patient_name', label: '患者氏名', classes: ['col-patient-name'], defaultVisible: true },
  { key: 'birth_date', label: '生年月日', classes: ['col-birth-date'], defaultVisible: false },
  { key: 'age', label: '年齢', classes: ['col-age'], defaultVisible: true },
  { key: 'insurance', label: '保険', classes: ['col-insurance'], defaultVisible: true },
  { key: 'department', label: '診療科', classes: ['col-department'], defaultVisible: true },
  { key: 'doctor', label: '医師', classes: ['col-doctor'], defaultVisible: true },
  { key: 'last_visit', label: '前回診療日', classes: ['col-last-visit'], defaultVisible: true },
  { key: 'patient_memo', label: '患者メモ', classes: ['col-patient-memo'], defaultVisible: true },
  { key: 'reception_memo', label: '受付メモ', classes: ['col-reception-memo'], defaultVisible: true },
  { key: 'first_visit', label: '初診', classes: ['col-first-visit'], defaultVisible: true },
  { key: 'terminal', label: '端末', classes: ['col-terminal'], defaultVisible: true },
  { key: 'payment', label: '支払', classes: ['col-payment'], defaultVisible: true }
];

function createDefaultReceptionFilterState() {
  return {
    statuses: new Set(receptionFilterStatusOptions.map(option => option.key)),
    doctors: new Set(receptionFilterDoctorDefaults),
    departments: new Set(receptionFilterDepartmentDefaults),
    visibleColumns: new Set(
      receptionFilterColumnOptions
        .filter(option => option.defaultVisible)
        .map(option => option.key)
    ),
    patientMemo: '',
    receptionMemo: ''
  };
}

let receptionFilterState = createDefaultReceptionFilterState();

function initFilterButtons() {
  const filterBtn = document.getElementById('btn-filter');
  const clearFilterBtn = document.getElementById('btn-clear-filter');

  if (filterBtn) {
    filterBtn.addEventListener('click', showFilterMenu);
  }

  if (clearFilterBtn) {
    clearFilterBtn.addEventListener('click', clearFilter);
  }
}

function uniqueReceptionValues(field, fallbackValues) {
  const values = new Set(fallbackValues);
  receptionsCache.forEach(reception => {
    const value = reception[field];
    if (value) values.add(value);
  });
  return Array.from(values);
}

function getFilterDoctors() {
  return uniqueReceptionValues('doctor_name', receptionFilterDoctorDefaults);
}

function getFilterDepartments() {
  return uniqueReceptionValues('department', receptionFilterDepartmentDefaults);
}

function isSetDefaultOnly(targetSet, defaultValues) {
  return targetSet.size === defaultValues.length
    && defaultValues.every(value => targetSet.has(value));
}

function syncReceptionFilterSelections() {
  if (!receptionFilterState) return;

  if (isSetDefaultOnly(receptionFilterState.doctors, receptionFilterDoctorDefaults)) {
    getFilterDoctors().forEach(name => receptionFilterState.doctors.add(name));
  }

  if (isSetDefaultOnly(receptionFilterState.departments, receptionFilterDepartmentDefaults)) {
    getFilterDepartments().forEach(name => receptionFilterState.departments.add(name));
  }
}

function getFilteredReceptions() {
  return receptionsCache.filter(reception => {
    if (!receptionFilterState.statuses.has(reception.status)) return false;

    const doctorName = reception.doctor_name || '';
    if (doctorName && !receptionFilterState.doctors.has(doctorName)) return false;

    const department = reception.department || '';
    if (department && !receptionFilterState.departments.has(department)) return false;

    const patientMemo = [
      reception.patient_memo,
      reception.memo,
      reception.patient_note
    ].filter(Boolean).join(' ');
    if (receptionFilterState.patientMemo && !patientMemo.includes(receptionFilterState.patientMemo)) {
      return false;
    }

    const receptionMemo = reception.reception_memo || '';
    if (receptionFilterState.receptionMemo && !receptionMemo.includes(receptionFilterState.receptionMemo)) {
      return false;
    }

    return true;
  });
}

function applyReceptionColumnVisibility() {
  const table = document.getElementById('patient-table');
  if (!table || !receptionFilterState) return;

  receptionFilterColumnOptions.forEach(option => {
    const isVisible = receptionFilterState.visibleColumns.has(option.key);
    option.classes.forEach(className => {
      table.querySelectorAll(`.${className}`).forEach(cell => {
        cell.classList.toggle('filter-column-hidden', !isVisible);
      });
    });
  });
}

function isReceptionFilterActive() {
  const sameSet = (a, b) => a.size === b.size && Array.from(a).every(value => b.has(value));
  const defaultStatuses = new Set(receptionFilterStatusOptions.map(option => option.key));
  const defaultDoctors = new Set(getFilterDoctors());
  const defaultDepartments = new Set(getFilterDepartments());
  const defaultColumns = new Set(
    receptionFilterColumnOptions
      .filter(option => option.defaultVisible)
      .map(option => option.key)
  );

  return !sameSet(receptionFilterState.statuses, defaultStatuses)
    || !sameSet(receptionFilterState.doctors, defaultDoctors)
    || !sameSet(receptionFilterState.departments, defaultDepartments)
    || !sameSet(receptionFilterState.visibleColumns, defaultColumns)
    || Boolean(receptionFilterState.patientMemo)
    || Boolean(receptionFilterState.receptionMemo);
}

function updateFilterButtonState() {
  const filterBtn = document.getElementById('btn-filter');
  if (filterBtn) filterBtn.classList.toggle('active', isReceptionFilterActive());
}

function renderFilterCheckbox(type, key, label, checked, color = null) {
  return `
    <label class="reception-filter-check">
      <input type="checkbox" data-filter-type="${type}" data-filter-key="${escapeHtml(key)}" ${checked ? 'checked' : ''}>
      <span class="filter-check-box"></span>
      ${color ? `<span class="filter-color-dot" style="background:${color};"></span>` : ''}
      <span class="filter-check-label">${escapeHtml(label)}</span>
    </label>
  `;
}

function renderFilterSection(title, type, options, selectedSet, scrollable = false) {
  return `
    <section class="reception-filter-section">
      <div class="reception-filter-title">${title}</div>
      <div class="reception-filter-links">
        <button type="button" data-filter-action="select-all" data-filter-target="${type}">すべて選択</button>
        <button type="button" data-filter-action="clear" data-filter-target="${type}">クリア</button>
      </div>
      <div class="reception-filter-options ${scrollable ? 'scrollable' : ''}">
        ${options.map(option => renderFilterCheckbox(
          type,
          option.key,
          option.label,
          selectedSet.has(option.key),
          option.color
        )).join('')}
      </div>
    </section>
  `;
}

function updateFilterSet(type, key, checked) {
  const map = {
    status: receptionFilterState.statuses,
    doctor: receptionFilterState.doctors,
    department: receptionFilterState.departments,
    column: receptionFilterState.visibleColumns
  };
  const targetSet = map[type];
  if (!targetSet) return;

  if (checked) {
    targetSet.add(key);
  } else {
    targetSet.delete(key);
  }
}

function setFilterSection(type, keys) {
  const map = {
    status: 'statuses',
    doctor: 'doctors',
    department: 'departments',
    column: 'visibleColumns'
  };
  const stateKey = map[type];
  if (!stateKey) return;
  receptionFilterState[stateKey] = new Set(keys);
}

function refreshOpenFilterMenu(menu) {
  if (!menu) return;
  menu.querySelectorAll('input[type="checkbox"][data-filter-type]').forEach(input => {
    const type = input.dataset.filterType;
    const key = input.dataset.filterKey;
    const map = {
      status: receptionFilterState.statuses,
      doctor: receptionFilterState.doctors,
      department: receptionFilterState.departments,
      column: receptionFilterState.visibleColumns
    };
    input.checked = Boolean(map[type]?.has(key));
  });
}

// フィルターメニューを表示
function showFilterMenu(event) {
  event.stopPropagation();

  // 既存メニューを削除
  const existingMenu = document.querySelector('.filter-menu');
  if (existingMenu) existingMenu.remove();

  const menu = document.createElement('div');
  menu.className = 'filter-menu';
  const doctorOptions = getFilterDoctors().map(name => ({ key: name, label: name }));
  const departmentOptions = getFilterDepartments().map(name => ({ key: name, label: name }));

  menu.innerHTML = `
    <div class="reception-filter-arrow"></div>
    <div class="reception-filter-grid">
      ${renderFilterSection('ステータス', 'status', receptionFilterStatusOptions, receptionFilterState.statuses)}
      ${renderFilterSection('医師', 'doctor', doctorOptions, receptionFilterState.doctors)}
      ${renderFilterSection('診療科', 'department', departmentOptions, receptionFilterState.departments)}
      ${renderFilterSection('表示する項目', 'column', receptionFilterColumnOptions, receptionFilterState.visibleColumns, true)}
    </div>
    <div class="reception-filter-memos">
      <label>
        <span>患者メモ</span>
        <input type="text" data-filter-memo="patient" value="${escapeHtml(receptionFilterState.patientMemo)}">
      </label>
      <label>
        <span>受付メモ</span>
        <input type="text" data-filter-memo="reception" value="${escapeHtml(receptionFilterState.receptionMemo)}">
      </label>
    </div>
  `;

  // ボタンの位置を基準に配置
  const btn = event.currentTarget;
  const rect = btn.getBoundingClientRect();
  const panelWidth = Math.min(886, window.innerWidth - 16);
  const panelLeft = Math.max(4, Math.min(rect.left - 304, window.innerWidth - panelWidth - 4));
  menu.style.position = 'fixed';
  menu.style.left = panelLeft + 'px';
  menu.style.top = (rect.bottom + 12) + 'px';
  menu.style.width = panelWidth + 'px';

  document.body.appendChild(menu);
  const arrow = menu.querySelector('.reception-filter-arrow');
  if (arrow) {
    arrow.style.left = `${Math.max(16, rect.left - panelLeft + (rect.width / 2) - 7)}px`;
  }

  menu.addEventListener('change', (e) => {
    const input = e.target.closest('input[type="checkbox"][data-filter-type]');
    if (!input) return;
    updateFilterSet(input.dataset.filterType, input.dataset.filterKey, input.checked);
    applyReceptionFilterState();
  });

  menu.addEventListener('click', (e) => {
    const actionBtn = e.target.closest('[data-filter-action]');
    if (!actionBtn) return;

    const type = actionBtn.dataset.filterTarget;
    const action = actionBtn.dataset.filterAction;
    const keysByType = {
      status: receptionFilterStatusOptions.map(option => option.key),
      doctor: doctorOptions.map(option => option.key),
      department: departmentOptions.map(option => option.key),
      column: receptionFilterColumnOptions.map(option => option.key)
    };

    setFilterSection(type, action === 'select-all' ? keysByType[type] : []);
    refreshOpenFilterMenu(menu);
    applyReceptionFilterState();
  });

  menu.querySelectorAll('[data-filter-memo]').forEach(input => {
    input.addEventListener('input', () => {
      if (input.dataset.filterMemo === 'patient') {
        receptionFilterState.patientMemo = input.value.trim();
      } else {
        receptionFilterState.receptionMemo = input.value.trim();
      }
      applyReceptionFilterState();
    });
  });

  // 外側クリックで閉じる
  setTimeout(() => {
    document.addEventListener('click', function closeMenu(e) {
      if (!menu.contains(e.target)) {
        menu.remove();
        document.removeEventListener('click', closeMenu);
      }
    });
  }, 0);
}

function applyReceptionFilterState() {
  renderReceptionTable();
  updateFilterButtonState();
}

// フィルターを適用
async function applyFilter(status) {
  receptionFilterState = createDefaultReceptionFilterState();
  syncReceptionFilterSelections();
  if (status) {
    receptionFilterState.statuses = new Set([status]);
  }
  applyReceptionFilterState();

  if (status) {
    const statusLabel = statusMap[status]?.label || status;
    showToast(`「${statusLabel}」でフィルター中`, 'info');
  }
}

// フィルターをクリア
function clearFilter() {
  receptionFilterState = createDefaultReceptionFilterState();
  syncReceptionFilterSelections();
  const existingMenu = document.querySelector('.filter-menu');
  if (existingMenu) existingMenu.remove();
  applyReceptionFilterState();
  showToast('フィルターを解除しました', 'info');
}

