// CSVダウンロード
function downloadCSV() {
  const patients = Storage.getPatients();

  if (patients.length === 0) {
    showToast('ダウンロードするデータがありません', 'error');
    return;
  }

  // CSVヘッダー
  const headers = ['患者番号', '氏名', 'フリガナ', '性別', '生年月日', '最終受付日', '電話番号', '住所'];

  // CSVデータ
  const rows = patients.map(p => [
    p.patient_no || p.id,
    p.name,
    p.name_kana || p.kana || '',
    formatPatientGenderLabel(p),
    p.birth_date || p.birth || '',
    formatPatientLastReceptionDate(p),
    p.phone1 || '',
    p.address || ''
  ]);

  // CSV文字列を生成
  const csvContent = [headers, ...rows]
    .map(row => row.map(cell => `"${(cell || '').replace(/"/g, '""')}"`).join(','))
    .join('\n');

  // BOMを付けてダウンロード（Excel対応）
  const bom = '\uFEFF';
  const blob = new Blob([bom + csvContent], { type: 'text/csv;charset=utf-8' });
  const url = URL.createObjectURL(blob);

  const a = document.createElement('a');
  a.href = url;
  a.download = `patients_${getLocalDateString()}.csv`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);

  showToast('CSVファイルをダウンロードしました', 'success');
}

// パスワード変更モーダル
function showPasswordChangeModal() {
  const modal = document.getElementById('password-modal');
  if (!modal) return;

  // フォームをクリア
  document.getElementById('current-password').value = '';
  document.getElementById('new-password').value = '';
  document.getElementById('confirm-password').value = '';

  modal.classList.remove('hidden');
}

function closePasswordModal() {
  document.getElementById('password-modal').classList.add('hidden');
}

async function changePassword() {
  const currentPw = document.getElementById('current-password').value;
  const newPw = document.getElementById('new-password').value;
  const confirmPw = document.getElementById('confirm-password').value;

  if (!currentPw || !newPw || !confirmPw) {
    showToast('すべての項目を入力してください', 'error');
    return;
  }

  if (newPw.length < 8) {
    showToast('パスワードは8文字以上で設定してください', 'error');
    return;
  }

  if (newPw !== confirmPw) {
    showToast('新しいパスワードが一致しません', 'error');
    return;
  }

  try {
    showLoading();
    // APIでパスワード変更（実装時に有効化）
    // await apiRequest('/auth/change-password', {
    //   method: 'POST',
    //   body: JSON.stringify({ current_password: currentPw, new_password: newPw })
    // });

    hideLoading();
    closePasswordModal();
    showToast('パスワードを変更しました', 'success');
  } catch (error) {
    hideLoading();
    showToast('パスワード変更に失敗しました: ' + error.message, 'error');
  }
}

// 施設管理モーダル
async function showFacilityModal() {
  const modal = document.getElementById('facility-modal');
  if (!modal) return;

  try {
    showLoading();
    const facility = await loadCurrentFacilityInfo({ force: true });
    populateFacilitySettingsForm(facility);
    switchFacilityTab('basic');
    modal.classList.remove('hidden');
  } catch (error) {
    console.error('施設情報編集モーダル表示エラー:', error);
    showToast(`医療機関情報を取得できませんでした: ${error?.message || '不明なエラー'}`, 'error');
  } finally {
    hideLoading();
  }
}

function closeFacilityModal() {
  document.getElementById('facility-modal')?.classList.add('hidden');
}

function switchFacilityTab(tabName) {
  // タブボタンの状態を更新
  document.querySelectorAll('.facility-tab').forEach(tab => {
    tab.classList.toggle('active', tab.dataset.tab === tabName);
  });

  // タブコンテンツの表示を切り替え
  document.querySelectorAll('.facility-tab-content').forEach(content => {
    content.classList.add('hidden');
  });
  document.getElementById(`facility-tab-${tabName}`)?.classList.remove('hidden');
}

async function saveFacilitySettings() {
  const facilityData = {
    name: document.getElementById('facility-name')?.value.trim() || '',
    founder_name: document.getElementById('facility-founder-name')?.value.trim() || null,
    medical_institution_code: document.getElementById('facility-code')?.value.trim() || null,
    postal_code: document.getElementById('facility-postal-code')?.value.trim() || null,
    address: document.getElementById('facility-address')?.value.trim() || null,
    phone: document.getElementById('facility-tel')?.value.trim() || null,
    fax: document.getElementById('facility-fax')?.value.trim() || null,
    email: document.getElementById('facility-email')?.value.trim() || null,
    outpatient_type: document.getElementById('facility-outpatient-type')?.value || null,
    invoice_registration_number: document.getElementById('facility-registration-number')?.value.trim() || null
  };

  if (!facilityData.name) {
    showToast('施設名を入力してください', 'error');
    return;
  }

  try {
    showLoading();
    if (typeof FacilityAPI === 'undefined' || !FacilityAPI?.updateCurrent) {
      throw new Error('施設情報APIが利用できません');
    }
    const savedFacility = normalizeFacilityInfo(await FacilityAPI.updateCurrent(facilityData));
    currentFacilityInfoCache = savedFacility;
    currentFacilityInfoLoadError = null;
    updateCurrentUserFacilitySnapshot(savedFacility);
    updateFacilityDisplayLabels(savedFacility);
    await renderFacilityMedicalInfo(savedFacility);

    hideLoading();
    closeFacilityModal();
    showToast('施設情報を保存しました', 'success');
  } catch (error) {
    hideLoading();
    showToast('保存に失敗しました: ' + error.message, 'error');
  }
}

// モーダル初期化
function initSettingsModals() {
  // パスワードモーダル
  const passwordModal = document.getElementById('password-modal');
  if (passwordModal) {
    document.getElementById('password-modal-close')?.addEventListener('click', closePasswordModal);
    document.getElementById('btn-password-cancel')?.addEventListener('click', closePasswordModal);
    document.getElementById('btn-password-save')?.addEventListener('click', changePassword);

    passwordModal.addEventListener('click', (e) => {
      if (e.target === passwordModal) closePasswordModal();
    });
  }

  // 施設モーダル
  const facilityModal = document.getElementById('facility-modal');
  if (facilityModal) {
    document.getElementById('facility-modal-close')?.addEventListener('click', closeFacilityModal);
    document.getElementById('btn-facility-cancel')?.addEventListener('click', closeFacilityModal);
    document.getElementById('btn-facility-save')?.addEventListener('click', saveFacilitySettings);

    facilityModal.addEventListener('click', (e) => {
      if (e.target === facilityModal) closeFacilityModal();
    });

    // タブ切り替え
    document.querySelectorAll('.facility-tab').forEach(tab => {
      tab.addEventListener('click', () => {
        switchFacilityTab(tab.dataset.tab);
      });
    });
  }

  // メニューからの呼び出し
  document.getElementById('menu-password')?.addEventListener('click', (e) => {
    e.preventDefault();
    showPasswordChangeModal();
  });

  document.getElementById('menu-facility')?.addEventListener('click', (e) => {
    e.preventDefault();
    document.getElementById('user-dropdown')?.classList.remove('open');
    showFacilityScreen('medical');
  });
}

