// 患者情報編集
function editPatient(patientId) {
  const patients = Storage.getPatients();
  const patient = patients.find(p => p.id === patientId);

  if (!patient) {
    showToast('患者情報が見つかりません', 'error');
    return;
  }

  // 患者登録モーダルを編集モードで開く
  const modal = document.getElementById('patient-modal');
  const title = document.getElementById('modal-title');
  title.textContent = '患者情報編集';
  document.getElementById('patient-form')?.reset();
  clearPatientFormErrors();
  setDefaultPatientGenderIfUnset();
  setDefaultPatientBirthYearIfUnset();

  // フォームに既存データをセット
  document.getElementById('patient-id').value = patient.patient_no || patient.id;
  document.getElementById('patient-id').disabled = true; // 患者番号は編集不可
  document.getElementById('patient-name').value = patient.name;
  document.getElementById('patient-kana').value = patient.name_kana || patient.kana || '';

  // 性別
  const genderCode = normalizePatientGenderCode(firstNonEmptyString(patient.gender, patient.sex, patient.patient_gender, patient.patientGender));
  const genderRadio = document.querySelector(`input[name="gender"][value="${genderCode}"]`);
  if (genderRadio) {
    genderRadio.checked = true;
  } else {
    setDefaultPatientGenderIfUnset();
  }

  // 生年月日
  const birthDate = patient.birth_date || patient.birth;
  if (birthDate) {
    const [year, month, day] = birthDate.split('-');
    document.getElementById('birth-year').value = year;
    document.getElementById('birth-month').value = parseInt(month);
    document.getElementById('birth-day').value = parseInt(day);
  }

  // 住所
  if (patient.postal_code) {
    document.getElementById('postal-code').value = patient.postal_code;
  }
  if (patient.address) {
    // 住所を分解（簡易的な実装）
    const addressParts = patient.address.split(' ');
    if (addressParts.length > 0) {
      document.getElementById('prefecture').value = addressParts[0] || '';
      document.getElementById('city').value = addressParts[1] || '';
      document.getElementById('address1').value = addressParts.slice(2).join(' ') || '';
    }
  }

  // 電話番号
  document.getElementById('phone1').value = patient.phone1 || '';
  document.getElementById('phone2').value = patient.phone2 || '';

  // 編集モードフラグをセット
  modal.dataset.editMode = 'true';
  modal.dataset.editPatientId = patientId;
  syncPatientModalActions();

  modal.classList.remove('hidden');
}

// 患者情報更新
async function updatePatient() {
  const modal = document.getElementById('patient-modal');
  const patientId = modal.dataset.editPatientId;

  if (!patientId) {
    showToast('編集対象の患者が不明です', 'error');
    return;
  }

  const validation = validatePatientForm({ includePatientNo: false });
  if (!validation.valid) {
    showToast(validation.summary, 'error');
    validation.firstElement?.focus();
    return;
  }

  const { name, kana, gender, birthDate } = validation.values;
  const duplicatePatient = findDuplicatePatientForRegistration({ name, kana, birthDate }, patientId);
  if (duplicatePatient) {
    const message = buildDuplicatePatientMessage(duplicatePatient);
    setPatientFieldError('name', message);
    showToast(message, 'error');
    document.getElementById('patient-name')?.focus();
    return;
  }

  const address = [
    document.getElementById('prefecture').value,
    document.getElementById('city').value,
    document.getElementById('address1').value,
    document.getElementById('address2').value
  ].filter(Boolean).join(' ');

  const patientData = {
    name: name,
    name_kana: kana,
    gender: gender,
    birth_date: birthDate,
    postal_code: document.getElementById('postal-code').value,
    address: address,
    phone1: document.getElementById('phone1').value,
    phone2: document.getElementById('phone2').value
  };

  try {
    showLoading();
    await PatientAPI.update(patientId, patientData);

    modal.classList.add('hidden');
    modal.dataset.editMode = '';
    modal.dataset.editPatientId = '';
    syncPatientModalActions();
    document.getElementById('patient-id').disabled = false;
    document.getElementById('modal-title').textContent = '患者情報登録';
    document.getElementById('patient-form').reset();
    setDefaultPatientGenderIfUnset();
    setDefaultPatientBirthYearIfUnset();

    await loadPatients();
    updatePatientSelector();

    hideLoading();
    showToast('患者情報を更新しました', 'success');

    // 現在の患者情報も更新
    if (currentPatient && currentPatient.id === patientId) {
      const updatedPatient = Storage.getPatients().find(p => p.id === patientId);
      if (updatedPatient) {
        selectPatient(updatedPatient);
      }
    }

  } catch (error) {
    hideLoading();
    const message = error.status === 409 ? error.message : '更新に失敗しました: ' + error.message;
    showToast(message, 'error');
  }
}

// グローバル関数として公開
window.editPatient = editPatient;
window.downloadCSV = downloadCSV;
window.showFilterMenu = showFilterMenu;
window.clearFilter = clearFilter;
